\title{Elimination of angular dependency in quantum three-body problem made easy}  


\author{Anjan Sadhukhan}
\affiliation{Department of Applied Chemistry, National Yang Ming Chiao Tung University, 
1001 University Road, Hsinchu, 300, Taiwan}
