\subsubsection{\textnormal{RSE} for \texorpdfstring{$\textnormal{S}^{\textnormal{e}}$}~ states}
In the simplest case of the $\text{S}^{\textnormal{e}}$ states, the wave function $\Psi^{00n} = \psi_{0}^{0n}\hspace{1pt}\bm{\Omega}_{0}^{00n}$ with $\bm{\Omega}_{0}^{00n}= \frac{1}{4\pi}$, can be constructed using only a single reduced component $\psi_{0}^{0n}=\psi_{0}^{0n}(r_1,r_2,r_{12})$ considered first by Hylleraas \cite{Hylleraas1929}. Consequently, the RSE for the $\text{S}^{\textnormal{e}}$ states 
\begin{eqnarray}\label{rrsese}
        \left(\hat{\mathcal{H}}^{0n}_{00}-E\right)\psi_{0}^{0n} =   0
\end{eqnarray}
with the explicit form of $\hat{\mathcal{H}}^{0n}_{00}$ obtained from Eq.~\eqref{hkkgnygp2} as
\begin{eqnarray}\label{h00} 
    \hat{\mathcal{H}}^{0n}_{00} &\!=\!& 
    -\tfrac{\partial_{r_{1\vphantom{y}}r_{1}}}{2\mu_{1}}
    \hspace{-3pt}-\hspace{-3pt}\tfrac{\partial_{r_{2\vphantom{y}}r_{2}}}{2\mu_{2}}
    \hspace{-3pt}-\hspace{-3pt}\tfrac{\partial_{r_{12\vphantom{y}}r_{12}}}{2\mu_{12}}\hspace{-3pt}+\hspace{-3pt} \tfrac{q_{1\vphantom{y}}q_{2}}{r_{12}}\hspace{-3pt}+\hspace{-3pt}\tfrac{q_{1\vphantom{y}}q_{3}}{r_{1}\vphantom{\mu_2}}\hspace{-3pt}+\hspace{-3pt}\tfrac{q_{2\vphantom{y}}q_{3}}{r_{2}} \nonumber\\[2pt]
    &&  -\tfrac{\partial_{r_{1\vphantom{y}}}}{\mu_{1}r_{1}}\hspace{-3pt}-\hspace{-3pt}\tfrac{\partial_{r_{12\vphantom{y}}}}{m_{1}r_{12}}
    \hspace{-3pt}-\hspace{-2pt}\tfrac{\partial_{r_{2\vphantom{y}}}}{\mu_{2}r_{2}}\hspace{-3pt}-\hspace{-3pt}\tfrac{\partial_{r_{12\vphantom{y}}}}{m_{2}r_{12}}\hspace{-3pt}-\hspace{-3pt} \tfrac{r_{1\vphantom{y}}^2+r_{2}^2-r_{12}^2}{2m_{3}r_{1}r_{2}}\partial_{r_{1}r_{2}}\nonumber\\[2pt]
    && \!-\tfrac{r_{1\vphantom{y}}^2+r_{12}^2-r_{2}^2}{2m_{1}r_{1}r_{12}}\partial_{r_{1}r_{12}}\hspace{-4pt}-\hspace{-3pt}  \tfrac{r_{2\vphantom{y}}^2+r_{12}^2-r_{1}^2}{2m_{2}r_{2}r_{12}}\partial_{r_{2}r_{12}} 
\end{eqnarray}
is the generalization of the original Hylleraas equation for a clamped-nucleus helium atom (see for example Eq.~(5) of \cite{Hylleraas1929}, or, for more recent account, Eq.~(5) of \cite{Nakashima2007})  to the situation when the nucleus has a finite mass. The form of the operator $\hat{\mathcal{H}}^{0n}_{00}$, given by Eq.~\eqref{h00}, is consistent with Eq.~(24) of \cite{Efros1986} by \'{E}fros. Various variants of Eq.~\eqref{rrsese} were derived in the literature; detailed discussion of relevant citations has been given above in the paragraph following Eq.~\eqref{hkk-1gnygp2}.

\subsubsection{\textnormal{RSE} for \texorpdfstring{$\textnormal{P}^{\textnormal{e}}$ and $\textnormal{P}^{\textnormal{o}}$}~ states}
The next possible value of $L\hspace{-1.5pt}=\hspace{-1.5pt}1$ allows states with both natural and unnatural parity. For the $\text{P}^{\textnormal{e}}$ states, the wave function $\Psi^{11n} = \psi_{1}^{1u}\hspace{2pt}\bm{\Omega}_{1}^{11u}$ with 
\begin{equation}
    \bm{\Omega}_{1}^{11u} = \tfrac{3}{8\pi}\left[z_{1}(x_{2}+\textit{\textbf{i}}\hspace{1pt}y_{2})-z_{2}(x_{1}+\textit{\textbf{i}}\hspace{1pt}y_{1})\right]\label{Omg111u}
\end{equation}
(for details, see Eqs.~\eqref{nlpik} and~(\ref{nsbshccnp}--\ref{usbshccup})) can be constructed using only a single reduced component $\psi_{1}^{1u}=\psi_{1}^{1u}(r_1,r_2,r_{12})$. The corresponding RSE for $\text{P}^{\textnormal{e}}$ is
\begin{equation}
   \mathscr{W}_{11}^{1u}\left(\hat{\mathcal{H}}^{1u}_{11}-E\right)\psi_{1}^{1u} = 0 
\end{equation}
where
\begin{eqnarray}\label{w111u}
     \mathscr{W}_{11}^{1u} &=& -\frac{3}{4}\hspace{2pt}r_{1}^2\hspace{2pt}r_{2}^2\hspace{2pt}\sin^2{\hspace{-1.5pt}\theta} \\ \nonumber
     &=& -\tfrac{3}{16}\left(r_{1}\!+r_{2}\!+r_{12}\right)\left(r_{2}\!-r_{1}\!+r_{12}\right) \\
     && \phantom{-\tfrac{3}{6}} \cdot\!\left(r_{1}\!-r_{2}\!+r_{12}\right)\left(r_{1}\!+r_{2}\!-r_{12}\right) \label{w111u0}
\end{eqnarray}
and where the explicit form of $\hat{\mathcal{H}}^{1u}_{11}$ can be readily found from Eq.~\eqref{hkkgnygp2} as
\begin{equation}\label{h1u11}
    \hat{\mathcal{H}}^{1u}_{11} = \hat{\mathcal{H}}^{0n}_{00}\hspace{-1pt}-\hspace{-1pt}\tfrac{\partial_{r_{1\vphantom{y}}}}{\mu_{1}r_{1}}\hspace{-1pt}-\hspace{-1pt}\tfrac{\partial_{r_{2\vphantom{y}}}}{\mu_{2}r_{2}}\hspace{-1pt}-\hspace{-1pt}\tfrac{\partial_{r_{12\vphantom{y}}}}{\mu_{12}r_{12}}\hspace{-3pt}
\end{equation}
with $\hat{\mathcal{H}}^{0n}_{00}$ defined by Eq.~\eqref{h00}. 

For the $\text{P}^{\textnormal{o}}$ states, the corresponding wave function
\begin{eqnarray}
    \Psi^{11n} = \psi_{0}^{1n}\hspace{2pt}\bm{\Omega}_{0}^{11n}\! + \psi_{1}^{1n}\hspace{2pt}\bm{\Omega}_{1}^{11n}
\end{eqnarray}
with
\begin{eqnarray}
    \bm{\Omega}_{0}^{11n} &=& -\tfrac{\sqrt{6}}{8\pi} \left(x_{2}+\textit{\textbf{i}}\, y_{2}\right)\nonumber\\
    \bm{\Omega}_{1}^{11n} &=& -\tfrac{\sqrt{6}}{8\pi} \left(x_{1}+\textit{\textbf{i}}\, y_{1}\right)
\end{eqnarray}
(for details, see Eqs.~\eqref{nlpik},~\eqref{nsbshccnp} and~\eqref{usbshccnp}) can be constructed using two reduced components $\psi_{0}^{1n}=\psi_{0}^{1n}(r_1,r_2,r_{12})$ and $\psi_{1}^{1n}=\psi_{1}^{1n}(r_1,r_2,r_{12})$. The corresponding RSE takes the following two-component form
\begin{equation}\label{rrsepo}
\left(\!\!\begin{array}{cc}
     \mathscr{W}_{00}^{1n} \hspace{-5pt}& \hspace{-5pt}\mathscr{W}_{10}^{1n}\\
      \\
     \mathscr{W}_{01}^{1n} \hspace{-5pt}& \hspace{-5pt} \mathscr{W}_{11}^{1n}
\end{array}\!\!\right)\hspace{-5pt}\left(\!\!\begin{array}{lr}
     \hat{\mathcal{H}}^{1n}_{00}\hspace{-2.5pt}-\hspace{-2pt}E \hspace{-9pt}&\hspace{-15pt} \hat{\mathcal{H}}^{1n}_{01}\\
        &\\
        \hat{\mathcal{H}}^{1n}_{10} \hspace{-9pt}& \hspace{-15pt}\hat{\mathcal{H}}^{1n}_{11}\hspace{-2.5pt}-\hspace{-2pt}E
\end{array}\!\!\right)\hspace{-5pt}\left(\!\!\begin{array}{c}
     \psi_{0}^{1n}\\
     \\
    \psi_{1}^{1n}
\end{array}\!\!\right)\! =\! \left(\!\begin{array}{c}
     0\\
     \\
    0
\end{array}\!\right)
\end{equation}
where
\begin{eqnarray}
    \left(\!\!\begin{array}{cc}
     \mathscr{W}_{00}^{1n} \hspace{-5pt}& \hspace{-5pt}\mathscr{W}_{10}^{1n}\\
      \\
     \mathscr{W}_{01}^{1n} \hspace{-5pt}& \hspace{-5pt} \mathscr{W}_{11}^{1n}
\end{array}\!\!\right) &=& \tfrac{r_{1}r_{2\vphantom{_{a}}}}{2}\!\left(\!\begin{array}{lr}
     \frac{r_{2\vphantom{_{a}}}}{r_{1}}\hspace{-5pt} & \hspace{-10pt}\cos{\theta}\\
     \\ 
     \cos{\theta} \hspace{-5pt}&\hspace{-10pt} \frac{r_{1\vphantom{_{a}}}}{r_{2}}
\end{array}\!\right)= \left(\!\!\begin{array}{lr}
     \frac{r^{2}_{2\vphantom{_{a}}}}{2} & \hspace*{-32pt}\frac{r_{1\vphantom{_{a}}}^{2}+r_{2}^{2}-r_{12}^{2}}{4}\\
     \\ 
     \frac{r_{1\vphantom{_{a}}}^{2}+r_{2}^{2}-r_{12}^{2}}{4} &\hspace*{-32pt} \frac{r^{2}_{1\vphantom{_{a}}}}{2}
\end{array}\!\!\right) \nonumber
\end{eqnarray}
The explicit form of the operators $\hat{\mathcal{H}}^{1n}_{00}$, $\hat{\mathcal{H}}^{1n}_{11}$, $\hat{\mathcal{H}}^{1n}_{10}$ and $\hat{\mathcal{H}}^{1n}_{01}$ can be easily found from Eqs.~(\ref{hkkgnygp2}--\ref{hkk-1gnygp2}) as
\begin{eqnarray}
    \hat{\mathcal{H}}^{1n}_{00} &=& \hat{\mathcal{H}}^{0n}_{00}\hspace{-1pt}-\hspace{-1pt}\tfrac{\partial_{r_{2\vphantom{y}}}}{\mu_{2}\,r_{2}}\hspace{-1pt}-\hspace{-1pt}\tfrac{\partial_{r_{12\vphantom{y}}}}{m_{2}\,r_{12}}\nonumber\\
    \hat{\mathcal{H}}^{1n}_{11} &=& \hat{\mathcal{H}}^{0n}_{00}\hspace{-1pt}-\hspace{-1pt}\tfrac{\partial_{r_{1\vphantom{y}}}}{\mu_{1}\,r_{1}}\hspace{-1pt}-\hspace{-1pt}\tfrac{\partial_{r_{12\vphantom{y}}}}{m_{1}\,r_{12}}\nonumber\\
    \hat{\mathcal{H}}^{1n}_{10} &=& \tfrac{\partial_{r_{12\vphantom{y}}}}{m_{2}\,r_{12}}\hspace{-1pt}-\hspace{-1pt}\tfrac{\partial_{r_{1\vphantom{y}}}}{m_{3}\,r_{1}}\nonumber\\
    \hat{\mathcal{H}}^{1n}_{01} &=& \tfrac{\partial_{r_{12\vphantom{y}}}}{m_{1}\,r_{12}}\hspace{-1pt}-\hspace{-1pt}\tfrac{\partial_{r_{2\vphantom{y}}}}{m_{3}\,r_{2}}
\end{eqnarray}
with $\hat{\mathcal{H}}^{0n}_{00}$ defined by Eq.~\eqref{h00}.
\subsubsection{\textnormal{RSE} for \texorpdfstring{$\textnormal{D}^{\textnormal{e}}$ and $\textnormal{D}^{\textnormal{o}}$}~ states}
The wave function for the $\text{D}^{\text{o}}$ states 
\begin{equation}
    \Psi^{22u} = \psi_{1}^{2u}\hspace{2pt}\bm{\Omega}_{1}^{22u}\! + \psi_{2}^{2u}\hspace{2pt}\bm{\Omega}_{2}^{22u} 
\end{equation}
with
\begin{eqnarray}
    \bm{\Omega}_{1}^{22u} &=& -\tfrac{\sqrt{15}}{3}\left(x_{2}+\textit{\textbf{i}}\hspace{1pt}y_{2}\right)\bm{\Omega}_{1}^{11u}\nonumber\\
    \bm{\Omega}_{2}^{22u} &=& -\tfrac{\sqrt{15}}{3}\left(x_{1}+\textit{\textbf{i}}\hspace{1pt}y_{1}\right)\bm{\Omega}_{1}^{11u}
\end{eqnarray}
and $\bm{\Omega}_{1}^{11u}$ defined by Eq.~\eqref{Omg111u}, consists of two components $\psi_{1}^{2u}=\psi_{1}^{2u}(r_1,r_2,r_{12})$ and $\psi_{2}^{2u}=\psi_{2}^{2u}(r_1,r_2,r_{12})$. The corresponding RSE is
\begin{equation}
\left(\!\begin{array}{cc}
     \mathscr{W}_{11}^{2u} \hspace{-5pt}& \hspace{-5pt}\mathscr{W}_{21}^{2u}\\
      \\
     \mathscr{W}_{12}^{2u} \hspace{-5pt}& \hspace{-5pt} \mathscr{W}_{22}^{2u}
\end{array}\!\right)\hspace{-7pt}\left(\!\begin{array}{lr}
     \hat{\mathcal{H}}^{2u}_{11}\hspace{-2.5pt}-\hspace{-2pt}E \hspace{-9pt}&\hspace{-15pt} \hat{\mathcal{H}}^{2u}_{12}\\
        &\\
        \hat{\mathcal{H}}^{2u}_{21} \hspace{-9pt}& \hspace{-15pt}\hat{\mathcal{H}}^{2u}_{22}\hspace{-2.5pt}-\hspace{-2pt}E
\end{array}\!\right)\hspace{-7pt}\left(\!\!\!\begin{array}{c}
     \psi_{1}^{2u}\\
     \\
    \psi_{2}^{2u}
\end{array}\!\!\!\right)\!\! =\!\! \left(\!\!\begin{array}{c}
     0\\
     \\
    0
\end{array}\!\!\right)
\end{equation}
where
\begin{equation}
    \left(\!\!\begin{array}{cc}
     \mathscr{W}_{11}^{2u} \hspace{-5pt}& \hspace{-5pt}\mathscr{W}_{21}^{2u}\\
      \\
     \mathscr{W}_{12}^{2u} \hspace{-5pt}& \hspace{-5pt} \mathscr{W}_{22}^{2u}
\end{array}\!\!\right)=\left(\!\begin{array}{cc}
        \frac{r_{2\vphantom{_{a}}}}{r_{1}} \hspace{-2pt}&\hspace{-2pt} 1\\
        &\\
        1 \hspace{-2pt}&\hspace{-2pt} \frac{r_{1\vphantom{_{a}}}}{r_{2}}\\
    \end{array}\!\right) \cdot r_{1}r_{2}\hspace{2pt} \mathscr{W}_{11}^{1u}
\end{equation}
with $\mathscr{W}_{11}^{1u}$ defined by Eqs.~\eqref{w111u} and~\eqref{w111u0}. The explicit form of the diagonal operators $\hat{\mathcal{H}}^{2u}_{11}$ and $\hat{\mathcal{H}}^{2u}_{22}$ can be easily found using Eq.~\eqref{hkkgnygp2}, while the off-diagonal operators $\hat{\mathcal{H}}^{2u}_{21}$ and $\hat{\mathcal{H}}^{2u}_{12}$ are given by Eqs.~\eqref{hkk+1gnygp2} and \eqref{hkk-1gnygp2}, respectively.

The wave function for $\text{D}^{\text{e}}$ states of the system consists of three terms
\begin{eqnarray}
    \Psi^{22n} = \psi_{0}^{2n}\hspace{2pt}\bm{\Omega}_{0}^{22n}\! + \psi_{1}^{2n}\hspace{2pt}\bm{\Omega}_{1}^{22n}\! + \psi_{2}^{2n}\hspace{2pt}\bm{\Omega}_{2}^{22n}
\end{eqnarray}
with
\begin{eqnarray}
    \bm{\Omega}_{0}^{22n} =& ~\tfrac{\sqrt{30}}{16\pi}~&\left(x_{2}+\textit{\textbf{i}}\,y_{2}\right)^{2}\nonumber\\
    \bm{\Omega}_{1}^{22n} =& ~\tfrac{3}{8\pi}~&\left(x_{1}+\textit{\textbf{i}}\,y_{1}\right)\left(x_{2}+\textit{\textbf{i}}\,y_{2}\right)\\
    \bm{\Omega}_{2}^{22n} =& ~\tfrac{\sqrt{30}}{16\pi}~&\left(x_{1}+\textit{\textbf{i}}\,y_{1}\right)^{2}\nonumber
\end{eqnarray}
and with the reduced components $\psi_{l}^{2n}=\psi_{l}^{2n}(r_1,r_2,r_{12})$, $l=0,1,2$. The corresponding RSE takes the following form
\begin{equation}
    \left(\!\!\begin{array}{ccc}
        \mathscr{W}_{00}^{2n} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{10}^{2n} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{20}^{2n}\vspace{-5pt}\\
        &\\
        \mathscr{W}_{01}^{2n} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{11}^{2n} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{21}^{2n}\vspace{-5pt}\\
        &\\
        \mathscr{W}_{02}^{2n} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{12}^{2n} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{22}^{2n}
    \end{array}\!\!\right)\hspace{-6.5pt}\left(\!\!\begin{array}{llr}
        \hat{\mathcal{H}}^{2n}_{00}\hspace{-2.5pt}-\hspace{-2pt}E & \hspace{5pt}\hat{\mathcal{H}}^{2n}_{01} &  0\hspace*{2pt}\vspace{-5pt}\\
        &\\
        \hat{\mathcal{H}}^{2n}_{10} & \hspace{-10pt}\hat{\mathcal{H}}^{2n}_{11}\hspace{-2.5pt}-\hspace{-2pt}E & \hspace{-10pt}\hat{\mathcal{H}}^{2n}_{12}\vspace{-5pt}\\
        &\\
        \hspace{2pt}0 & \hspace{-10pt}\hat{\mathcal{H}}^{2n}_{21} & \hspace{-10pt}\hat{\mathcal{H}}^{2n}_{22}\hspace{-2.5pt}-\hspace{-2pt}E
    \end{array}\!\!\right)\hspace{-6.5pt}\left(\!\!\!\begin{array}{c}
    \psi_{0}^{2n}\vspace{-5pt}\\
    \\
    \psi_{1}^{2n}\vspace{-5pt}\\
    \\
    \psi_{2}^{2n}
    \end{array}\!\!\!\right)\hspace{-4pt} =\hspace{-4pt} \left(\!\!\begin{array}{c}
    0\vspace{-5pt}\\
    \\
    0\vspace{-5pt}\\
    \\
    0
    \end{array}\!\!\right) \nonumber
\end{equation}
where
\begin{equation}
    \left(\!\!\begin{array}{ccc}
        \mathscr{W}_{00}^{2n} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{10}^{2n} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{20}^{2n}\vspace{-5pt}\\ 
        &\\
        \mathscr{W}_{01}^{2n} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{11}^{2n} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{21}^{2n}\vspace{-5pt}\\
        &\\
        \mathscr{W}_{02}^{2n} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{12}^{2n} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{22}^{2n}
    \end{array}\!\!\right)\!\!=\!
     \tfrac{r_{1}^2r_{2\vphantom{_a}}^2}{2}\!\!\left(\!\!\begin{array}{ccc}
        \frac{r_{2\vphantom{_a}}^2}{r_{1}^{2\vphantom{^a}}} \hspace{-5pt}&\hspace{-5pt} \frac{\sqrt{30}\,r_{2\vphantom{_a}}\hspace{-1pt}\cos{\theta}}{5r_{1}} \hspace{-5pt}&\hspace{-5pt} \frac{(3\cos^{2}\!{\theta}-1)}{2}\vspace{-5pt}\\
        &\\
        \frac{\sqrt{30}\,r_{2\vphantom{_a}}\hspace{-1pt}\cos{\theta}}{5r_{1}} \hspace{-5pt}&\hspace{-5pt} \frac{3(\cos^{2}\!{\theta}+3)}{10} \hspace{-5pt}&\hspace{-5pt} \frac{\sqrt{30}\,r_{1\vphantom{_a}}\hspace{-1pt}\cos{\theta}}{5r_{2}}\vspace{-5pt}\\
        &\\
        \frac{(3\cos^{2}\!{\theta}-1)}{2} \hspace{-5pt}&\hspace{-5pt} \frac{\sqrt{30}\,r_{1\vphantom{_a}}\hspace{-1pt}\cos{\theta}}{5r_{2}} \hspace{-5pt}&\hspace{-5pt} \frac{r_{1\vphantom{_a}}^2}{r_{2}^{2\vphantom{^a}}}
    \end{array}\!\!\right) \nonumber
\end{equation}
with $\cos{\theta} = \!\sfrac{\left( r_1^2+r_2^2-r_{12}^2\right)}{\left(2 r_1 r_2\right)} $ and where the differential operators in the Hamiltonian matrix can easily be generated from the Eqs.~(\ref{hkkgnygp2}--\ref{hkk-1gnygp2}). 
\subsubsection{\textnormal{RSE} for \texorpdfstring{$\textnormal{F}^{\textnormal{e}}$ and $\textnormal{F}^{\textnormal{o}}$}~ states}
For the $\text{F}^{\text{e}}$ states, the wave function is expanded as
\begin{eqnarray}
    \Psi^{33u} = \psi_{1}^{3u}\hspace{2pt}\bm{\Omega}_{1}^{33u}\! + \psi_{2}^{3u}\hspace{2pt}\bm{\Omega}_{2}^{33u}\! + \psi_{3}^{3u}\hspace{2pt}\bm{\Omega}_{3}^{33u}
\end{eqnarray}
with
\begin{eqnarray}
    \bm{\Omega}_{1}^{33u} &=& \tfrac{\sqrt{35}}{4}\hspace{1pt}\bm{\Omega}_{1}^{11u}\left(x_{2}+\textit{\textbf{i}}\hspace{1pt}y_{2}\right)^{2}\nonumber\\
    \bm{\Omega}_{2}^{33u} &=& \tfrac{5\sqrt{2}}{4}\hspace{1pt}\bm{\Omega}_{1}^{11u}\left(x_{1}+\textit{\textbf{i}}\hspace{1pt}y_{1}\right)\left(x_{2}+\textit{\textbf{i}}\hspace{1pt}y_{2}\right)\nonumber\\
    \bm{\Omega}_{3}^{33u} &=& \tfrac{\sqrt{35}}{4}\hspace{1pt}\bm{\Omega}_{1}^{11u}\left(x_{1}+\textit{\textbf{i}}\hspace{1pt}y_{1}\right)^{2}
\end{eqnarray}
and $\bm{\Omega}_{1}^{11u}$ defined by Eq.~\eqref{Omg111u}, and with the three reduced components $\psi_{l}^{3u}=\psi_{l}^{3u}(r_1,r_2,r_{12})$, $l=1,2,3$. The corresponding RSE has the following form
\begin{equation}
    \left(\!\!\begin{array}{ccc}
        \mathscr{W}_{11}^{3u} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{21}^{3u} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{31}^{3u}\vspace{-5pt}\\
        &\\
        \mathscr{W}_{12}^{3u} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{22}^{3u} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{32}^{3u}\vspace{-5pt}\\
        &\\
        \mathscr{W}_{13}^{3u} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{23}^{3u} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{33}^{3u}
    \end{array}\!\!\right)\hspace{-6.5pt}\left(\!\!\begin{array}{llr}
        \hat{\mathcal{H}}^{3u}_{11}\hspace{-2.5pt}-\hspace{-2pt}E & \hspace{5pt}\hat{\mathcal{H}}^{3u}_{12} &  0\hspace*{2pt}\vspace{-5pt}\\
        &\\
        \hat{\mathcal{H}}^{3u}_{21} & \hspace{-10pt}\hat{\mathcal{H}}^{3u}_{22}\hspace{-2.5pt}-\hspace{-2pt}E & \hspace{-10pt}\hat{\mathcal{H}}^{3u}_{23}\vspace{-5pt}\\
        &\\
        \hspace{2pt}0 & \hspace{-10pt}\hat{\mathcal{H}}^{3u}_{32} & \hspace{-10pt}\hat{\mathcal{H}}^{3u}_{33}\hspace{-2.5pt}-\hspace{-2pt}E
    \end{array}\!\!\right)\hspace{-6.5pt}\left(\!\!\begin{array}{c}
    \psi_{1}^{3u}\vspace{-5pt}\\
    \\
    \psi_{2}^{3u}\vspace{-5pt}\\
    \\
    \psi_{3}^{3u}
    \end{array}\!\!\right)\hspace{-4pt} =\hspace{-4pt} \left(\!\!\begin{array}{c}
            0\vspace{-5pt}\\
            \\
            0\vspace{-5pt}\\
            \\
            0
        \end{array}\!\!\right) \nonumber
\end{equation}
where
\begin{eqnarray}
    \left(\!\!\begin{array}{ccc}
        \mathscr{W}_{11}^{3u} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{21}^{3u} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{31}^{3u}\vspace{-5pt}\\
        &\\
        \mathscr{W}_{12}^{3u} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{22}^{3u} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{32}^{3u}\vspace{-5pt}\\
        &\\
        \mathscr{W}_{13}^{3u} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{23}^{3u} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{33}^{3u}
    \end{array}\!\!\right)\!\!&=&\!\!\left(\!\!\begin{array}{ccc}
        \frac{r_{2\vphantom{_{a}}}^2}{r_{1}^{2\vphantom{^{a}}}} \hspace{-5pt}&\hspace{-5pt} \frac{\sqrt{70}\,r_{2}\hspace{-1pt}\cos{\theta}}{7r_{1}} \hspace{-5pt}&\hspace{-5pt} \frac{(1\hspace{-1pt}-5\cos^{2}\!{\theta})}{4}\vspace{-5pt}\\
        &\\
        \frac{\sqrt{70}\,r_{2\vphantom{_{a}}}\hspace{-1pt}\cos{\theta}}{7r_{1}} \hspace{-5pt}&\hspace{-5pt} \frac{-5(3\cos^2\!{\theta}+5)}{28} \hspace{-5pt}&\hspace{-5pt} \frac{\sqrt{70}\,r_{1\vphantom{_{a}}}\hspace{-1pt}\cos{\theta}}{7r_{2}}\vspace{-5pt}\\
        &\\
        \frac{(1\hspace{-1pt}-5\cos^{2}\!{\theta})}{4} \hspace{-5pt}&\hspace{-5pt} \frac{\sqrt{70}\,r_{1\vphantom{_{a}}}\hspace{-1pt}\cos{\theta}}{7r_{2}} \hspace{-5pt}&\hspace{-5pt} \frac{r_{1\vphantom{_{a}}}^2}{r_{2}^{2\vphantom{^{a}}}}
    \end{array}\!\!\right)\nonumber\\
    & &\cdot \hspace{1pt} r_{1}^2\hspace{1pt}r_{2}^2\hspace{1pt}\mathscr{W}_{11}^{1u}
\end{eqnarray}
with $\cos{\theta} = \!\sfrac{\left( r_1^2+r_2^2-r_{12}^2\right)}{\left(2 r_1 r_2\right)} $ and with $\mathscr{W}_{11}^{1u}$ defined by Eqs.~\eqref{w111u} and~\eqref{w111u0}. 

For the $\text{F}^{\text{o}}$ states, the wave function
\begin{equation}
    \Psi^{33n} = \psi_{0}^{3n}\hspace{1pt}\bm{\Omega}_{0}^{33n}\! + \psi_{1}^{3n}\hspace{1pt}\bm{\Omega}_{1}^{33n}\! + \psi_{2}^{3n}\hspace{1pt}\bm{\Omega}_{2}^{33n}\! + \psi_{3}^{3n}\hspace{1pt}\bm{\Omega}_{3}^{33n}
\end{equation}
with

\begin{eqnarray}
    \bm{\Omega}_{0}^{33n} \!&=&\! -\tfrac{\sqrt{35}}{16\pi}\!\left(x_{2}\!+\!\textit{\textbf{i}}\hspace{1pt}y_{2}\hspace{-1pt}\right)\!^{3}\nonumber\\
    \bm{\Omega}_{1}^{33n} \!&=&\! -\tfrac{3\sqrt{5}}{16\pi}\!\left(x_{1}\!+\!\textit{\textbf{i}}\hspace{1pt}y_{1}\hspace{-1pt}\right)\!\left(x_{2}\!+\!\textit{\textbf{i}}\hspace{1pt}y_{2}\right)^{2}\nonumber\\
    \bm{\Omega}_{2}^{33n} \!&=&\! -\tfrac{3\sqrt{5}}{16\pi}\!\left(x_{2}\!+\!\textit{\textbf{i}}\hspace{1pt}y_{2}\hspace{-1pt}\right)\!\left(x_{1}\!+\!\textit{\textbf{i}}\hspace{1pt}y_{1}\hspace{-1pt}\right)\!^{2}\nonumber\\
    \bm{\Omega}_{3}^{33n} \!&=&\! -\tfrac{\sqrt{35}}{16\pi}\!\left(x_{1}\!+\!\textit{\textbf{i}}\hspace{1pt}y_{1}\hspace{-1pt}\right)\!^{3}
\end{eqnarray}
can be constructed using the four reduced components $\psi_{l}^{3n}=\psi_{l}^{3n}(r_1,r_2,r_{12})$, $l=0,1,2,3$. The corresponding RSE takes the following form
\begin{widetext}
\begin{equation}
    \left(\hspace{-5pt}\begin{array}{cccc}
            \mathscr{W}_{00}^{3n} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{10}^{3n} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{20}^{3n} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{30}^{3n}\vspace{-5pt}\\
            &&&\\
            \mathscr{W}_{01}^{3n} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{11}^{3n} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{21}^{3n} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{31}^{3n}\vspace{-5pt}\\
            &&&\\
            \mathscr{W}_{02}^{3n} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{12}^{3n} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{22}^{3n} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{32}^{3n}\vspace{-5pt}\\
            &&&\\
            \mathscr{W}_{03}^{3n} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{13}^{3n} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{23}^{3n} \hspace{-5pt}&\hspace{-5pt} \mathscr{W}_{33}^{3n}
        \end{array}\hspace{-5pt}\right)\hspace{-6.5pt}\left(\hspace{-5pt}\begin{array}{cccc}
        \hat{\mathcal{H}}^{3n}_{00}\!-\!E \hspace{-7pt}&\hspace{-7pt} \hat{\mathcal{H}}^{3n}_{01} \hspace{-7pt}&\hspace{-7pt} 0 \hspace{-7pt}&\hspace{-7pt} 0\vspace{-5pt}\\
        &\\
        \hat{\mathcal{H}}^{3n}_{10} \hspace{-7pt}&\hspace{-7pt} \hat{\mathcal{H}}^{3n}_{11}\!-\!E \hspace{-7pt}&\hspace{-7pt} \hat{\mathcal{H}}^{3n}_{12} \hspace{-7pt}&\hspace{-7pt} 0\vspace{-5pt}\\
        &\\
        0 \hspace{-7pt}&\hspace{-7pt} \hat{\mathcal{H}}^{3n}_{21} \hspace{-7pt}&\hspace{-7pt} \hat{\mathcal{H}}^{3n}_{22}\!-\!E \hspace{-7pt}&\hspace{-7pt} \hat{\mathcal{H}}^{3n}_{23}\vspace{-5pt}\\
        &\\
        0 \hspace{-7pt}&\hspace{-7pt} 0 \hspace{-7pt}&\hspace{-7pt} \hat{\mathcal{H}}^{3n}_{32} \hspace{-7pt}&\hspace{-7pt} \hat{\mathcal{H}}^{3n}_{33}\!-\!E
    \end{array}\hspace{-5pt}\right)\hspace{-6.5pt}\left(\hspace{-3pt}\begin{array}{c}
