	\label{fig:all_sky_imagesa}
\end{figure}

\begin{figure} 
	\centering
	\includegraphics[width=0.81\textwidth]{all_sky_images9b.jpg}
	\caption{
	Same as Figure~\ref{fig:all_sky_imagesa}, but for 2020-2024. 
        There was a +2 minute discrepancy in the computer clock when these images were saved in 2020. 
        In 2024, a new camera was used, resulting images had higher resolution and some portions of the western and southern horizons were blocked by the roof terrace's sidewall.}
