\[w^*_{\cE}=(X_\cE X_\cE^\intercal +\lambda_2 I_{|\cE|})^{-1}(X_{\cE}y+\lambda_1 s), w^*_{[d]\setminus\cE}=0,\]
for some $\cE\subseteq[d]$ and $s\in\{-1,1\}^{|\cE|}$.
\label{lem:enet}
\end{lemma}

