\subsection{Constructing Gramian matrices with lower bounded smallest eigenvalue}

Here we present a helper lemma for constructing an illustrative example distribution where our distribution-dependent bounds lead to improved generalization guarantees over prior work. We will need the following standard Theorem that gives a lower bound on the smallest singular value of a sub-Gaussian matrix.

\begin{theorem}[\citealt{vershynin2018high}] Let $A$ be a $d\times n$ random matrix with independent, mean zero, subgaussian with variance proxy $K^2$, and isotropic columns $A_i$. Then
for any $t \ge 0$ the smallest singular value of $A$ satisfies,

  $$\sigma_{\min}(A)\ge \sqrt{n} - CK^2(\sqrt{d} + t),$$

with probability at least $1 - 2 \exp(-t^2)$, where $C$ is an absolute constant. 
\end{theorem}


To construct our example for the Elastic Net, we need to extend this result to all sub-matrices and all tasks.
Roughly speaking, in the following lemma, we establish a uniform high-probability lower bound on the smallest singular value of sub-Gaussian submatrices for all tasks.

\begin{lemma}

Let $A^t\in\R^{d\times n}$ be i.i.d.\ random matrices for each $t\in [T]$, with independent, mean-zero, isotropic, sub-Gaussian columns with variance proxy $K^2$. 
Then there exist constants $C,C'$ depending only on $K$, such that the following holds: if $n \ge C \left(d+ \log \frac{T}{\delta} \right)$, then with probability at least $1-\delta$, 

$$\min_{\substack{E \subseteq [d] \\ t\in[T]}} \sigma_{\min}(A^t_E) \ge {\sqrt{C'n}}.$$

Equivalently,

$$\min_{\substack{E \subseteq [d] \\ t\in[T]}} \lambda_{\min}(A^t_E (A^t_E)^\intercal) \ge C'n.$$


    \label{lem:dd-gram}
\end{lemma}

\begin{proof}
For a fixed subset $E\subseteq[d]$ of size $|E|=s$ and fixed $t\in[T]$, note that the matrix $A^t_E$ has independent, isotropic, sub-Gaussian rows. By standard results (e.g., ~\citet{vershynin2018high}, Theorem 4.6.1 in the 2nd Edition), there exist constants $c_0,C_0$ such that

$$\Pr\left[ \sigma_{\min}(A^t_E) \le \sqrt{n} - C_0 \sqrt{s} - r \right] \le \exp(-4c_0 r^2), \quad \forall r \ge 0.$$

Set $r=\sqrt{n}/2$ to get

$$\Pr\left[ \sigma_{\min}(A^t_E) \le \frac{\sqrt{n}}{2} - C_0 \sqrt{s} \right] \le \exp(-c_0 n).$$


We now do a union bound over subsets $E$ and the tasks $t$.
There are $2^d$ subsets of $[d]$ and $T$ tasks. Applying a union bound, we get the probability of failure

\begin{align*}
    \Pr\left[ \exists E \subseteq [d], t\in[T] \mid \sigma_{\min}(A_E) \le \frac{\sqrt{n}}{2} - C_0 \sqrt{|E|} \right] 
&\le 2^d \cdot T \cdot \exp(-c_0 n)\\
&\le \exp\left( -c_0(n-c_1d-c_2\log T)\right),
\end{align*}


for constants $c_1,c_2$. Choose $n\ge c_1d+c_2\log T+\frac{1}{c_0}\log\frac{1}{\delta}$, to make this probability at most $\delta$. Thus, with probability at least $1-\delta$, we have for all $E,t$

$$\min_{\substack{E \subseteq [d] \\ t\in[T]}} \sigma_{\min}(A^t_E) \ge \frac{\sqrt{n}}{2}-C_0\sqrt{d}.$$

Choosing  $n\ge C(d+\log\frac{T}{\delta})$ with a sufficiently large constant $C$ completes the proof.
\end{proof}



\subsection{Proof of Proposition \ref{prop:en_isotropic_main}}

Finally, we show an example where our bounds improve over the distribution independent bounds from prior work~\citep{regression_pdim}.

\begin{proposition}\label{prop:en_isotropic}
    Consider the expected validation error of an ERM estimator for the Elastic Net hyperparameters over the  range $\lambda_1\in[\underline{\Lambda_1},\overline{\Lambda_1}],\lambda_2\in[\underline{\Lambda_2},\infty)$.
    Assume further that all tasks are well-specified such that all inputs $x$ are sampled from sub-Gaussian distributions with independent entries. Concretely, assume that each entry in the input $x$ is sampled independently from a sub-Gaussian distribution  such that $\E{}{xx^\intercal} = \Sigma = (\sigma_x^2/d) I_d$. We further restrict the covariance matrices of both $x,\ws{}$ to have constant trace as $d$ increases. So, $tr(\Sigma) = \sigma_x^2 = const$ and $tr(\E{}{\ws{}\ws{\intercal}}) = \sigma_w^2 = const$. For sufficiently large $n \geq \Omega\left(d+\log\frac{T}{\underline{\Lambda_2}}\right)$, the generalization error bound given in Theorem \ref{thm:en} is $\tilde{O}\left(1/\sqrt{nT}\right)$, where the soft-O notation suppresses dependence on quantities apart from $T,n$ and $d$.
\end{proposition}
\begin{proof}
The generalization error bound in Theorem \ref{thm:en} is

\begin{align*}
    l_v&(\lambda_{ERM}) - l_v(\lambda^*)=\\&\tilde{O}\left(\frac{L\overline{\Lambda}\tilde{\Lambda}_D^T\sqrt{d}}{\sqrt{T}}+\frac{L}{\sqrt{n_vT}}\E{X,y}{ \max_{\cE}\left( \frac{\|y\|\sqrt{V^*(X_\cE X_\cE^\intercal)}}{V^*(X_\cE X_\cE^\intercal)+\underline{\Lambda_2}}+\frac{\overline{\Lambda_1}\sqrt{d}}{V(X_\cE X_\cE^\intercal)+\underline{\Lambda_2}}\right)} \right).
\end{align*}

Define $G^{t,\cE}:=X^t_\cE X_\cE^{t\intercal}$. We have,
$$\|(X^t_\cE X_\cE^{t\intercal} +\underline{\Lambda_2} I)^{-1}\|= \frac{1}{\underline{\Lambda_2}+ \lambda_{\min}(G^{t,\cE})}.$$ 

Now by Lemma \ref{lem:dd-gram}, if $n=\Omega(d+\log (T/\delta))$ with probability at least $1-\delta$,

$$\max_{\cE,t}\|(X^t_\cE X_\cE^{t\intercal} +\underline{\Lambda_2} I)^{-1}\|\le\frac{1}{\underline{\Lambda_2}+C{n}}.$$

    Setting $\delta=\frac{\underline{\Lambda_2}}{n}$, we get that for $n=\Omega\left(d+\log\frac{T}{\underline{\Lambda_2}}\right)$,
\begin{align*}
\tilde{\Lambda}_D^T=\E{X}{\max_{t,\cE}  \|(X^t_\cE X_\cE^{t\intercal} +\underline{\Lambda_2} I)^{-1}\|}\le  \frac{1}{\underline{\Lambda_2}+C{n}} +\frac{\underline{\Lambda_2}}{n}\cdot \frac{1}{\underline{\Lambda_2}}=O\left(\frac{1}{n}\right).
\end{align*}
    A similar argument shows that
    \begin{align*}
    \E{X,y}{\max_{\cE}\left( \frac{\|y\|\sqrt{V^*(X_\cE X_\cE^\intercal)}}{V^*(X_\cE X_\cE^\intercal)+\underline{\Lambda_2}}+\frac{\overline{\Lambda_1}\sqrt{d}}{V(X_\cE X_\cE^\intercal)+\underline{\Lambda_2}}\right)}\\
    =O\left(\frac{1}{\sqrt{n}}+\frac{\overline{\Lambda}\sqrt{d}}{n}\right)
    \end{align*}
    Therefore,
    \begin{align*}
        l_v(\lambda_{ERM}) - l_v(\lambda^*)=O\left(\frac{L\overline{\Lambda}\sqrt{d}}{\sqrt{T}}\cdot \frac{1}{n}+\frac{L}{n_vT}\cdot\frac{\overline{\Lambda}}{\sqrt{n}}\right)=O\left(\frac{L\overline{\Lambda}}{\sqrt{nT}}\right).
        \end{align*}
\end{proof}



\section{Alternative Bounds Based on Prior Work}\label{sec:alt_bounds}
In this section, we present an alternative to Theorem \ref{thm:lips_tgt} that uses previous techniques like the ones used in \cite{mtl_maurer}. In particular, \cite{mtl_maurer} address learning optimal representations from multiple tasks. They give generalization error bounds using Rademacher complexities by dividing the error into an error induced from learning imperfect representations and from imperfect learning given a representation. This section proceeds similarly, by dividing the generalization error into an error induced from imperfect estimation of expected validation error (due to finiteness of validation data), and error from imperfect estimation of $\lambda$ due to finiteness of the number of tasks.

The main distinction of this section from the proof of Theorem \ref{thm:lips_tgt} is the difference in the decomposition of error in Lemmas  \ref{lem:sup_to_rad} and \ref{lem:sup_to_rad_2}. While the decomposition in Lemma \ref{lem:sup_to_rad} is more intuitive and similar to a decomposition done in \cite{mtl_maurer}, the decomposition in \ref{lem:sup_to_rad_2} led to an asymptotically tighter analysis.

Before we state the main theorem, we start with an overloaded definition of the empirical expected validation loss which takes $\etr{S}$ as input:
\begin{align}
    \lev(\lambda, \etr{S})  
    &= \frac{1}{T} \sum_t \E{x_v^t,\epsilon_v^t}{l(x_{v}^{t\intercal}\wh^t_{\lambda}, y_{v}^t)}\nonumber\\
    &= \E{\eval{S'}}{\lve(\lambda, \etr{S}\ewtimes \eval{S'})}\label{step:ev_exp}.
\end{align}
Where $y_v^t = f^t(x_v^t,\epsilon_v^t)$.
Thus for a given $\etr{S}$, $\lev$ computes the expectation of the empirical validation loss over all possible sampling of the validation data.
We state the main theorem of this section below.

\begin{theorem}\label{thm:lips}
    Given a loss function that satisfies Assumptions \ref{assum:bound} and \ref{assum:lips} above, the expected validation loss error using the ERM estimator defined in Equation \ref{def:lamb_erm} is bounded with probability $\geq 1-\delta$ as:
    \begin{align}
        l_v(\lambda_{ERM}) - l_v(\lambda^*) &\leq\frac{2ML\Lambda_D^T
        }{\sqrt{T}}\E{x_v}{\|x_v\|} + \frac{2L}{\sqrt{n_v}} \sqrt{\E{x_v}{\|x_v\|^2}}\sqrt{\E{X,y}{ \|y\|^2/V(XX^\intercal)}}\nonumber\\
        &
         + \frac{2L\tilde{M}}{\sqrt{n_v}\sqrt[4]{T}}\sqrt{\E{x_v}{\|x_v\|^2}}\sqrt[4]{\frac{\ln(4/\delta)}{2}}\nonumber + 5C\sqrt{\frac{\ln(16/\delta)}{2T}}.\nonumber
    \end{align}
    Here $M^2 = \max\|Xy\|^2$, $\tilde{M}^2 = \max \|y\|^2/V(XX^\intercal)$, $\Lambda_D^T = \E{}{\max_t 1/V(X^tX^{t\intercal})}$. 
\end{theorem}
\begin{proof}
The proof proceeds similar to the proof for Theorem \ref{thm:lips_tgt}.
We write $l_v(\lambda_{ERM}) - l_v(\lambda^*) = l_v(\lambda_{ERM}) - l_{v}(\lambda_{ERM},S) +  l_{v}(\lambda_{ERM},S) - l_{v}(\lambda^*,S) + l_{v}(\lambda^*,S) - l_v(\lambda^*)$. We note, as usual, that $l_{v}(\lambda_{ERM},S) - l_{v}(\lambda^*,S) \leq 0$ and $l_{v}(\lambda^*,S) - l_v(\lambda^*)$ is bounded by a Hoeffding bound (Theorem \ref{thm:Hoeffding}). Notably, with probability $\geq 1-\delta$,
\begin{align*}
    l_{v}(\lambda^*,S) - l_v(\lambda^*) \leq C\sqrt{\frac{\ln(1/\delta)}{2T}}.
\end{align*}

It remains to bound $l_v(\lambda_{ERM}) - l_{v}(\lambda_{ERM},S) \leq \sup_\lambda l_v(\lambda) - l_{v}(\lambda,S)$. We observe that this is error between the empirical loss, and expected loss over sampling of validation examples and tasks. We break this error into error induced from a finite sampling of validation examples, and error from a finite sampling of tasks in Lemma \ref{lem:sup_to_rad}. We get that with probability $\geq 1-\delta$:
\begin{align}
    \sup_\lambda l_v(\lambda) - &l_{v}(\lambda,S) \leq 2\E{\sigma, (X^t,f^t, \epsilon^t \forall t)}{\sup_\lambda \frac{1}{T} \sum_{t} \sigma^t \E{x_v,\epsilon_v}{l(x_v^\intercal\wh_\lambda^t,y_v)}}\nonumber\\
    &+ 2\E{\sigma, (X_v^t, \epsilon_v^t \forall t)}{\sup_\lambda \frac{1}{n_vT} \sum_{t,i} \sigma^{t(i)}l(X_v^{t(i)\intercal}\wh_\lambda^t,y_v^{t(i)})}+ 2C\sqrt{\frac{2\ln(4/\delta)}{T}}.\label{eq:from_sup_rad}
\end{align}
In Lemma \ref{lem:S_v}, we show that $\E{\epsilon_v}{l(x_v^\intercal\wh_\lambda^t,y_v)}$ is Lipschitz in $\frac{1}{V(X^tX^{t\intercal}) + \lambda}$ with Lipschitz constant $\|X^ty^t\|\|x_v\|$ for fixed $y_v$. We use this Lipschitzness to bound the first term as: 
\begin{align*}
    \Eml{\sigma, (X^t,f^t, \epsilon^t \forall t)}\biggl[\sup_\lambda \frac{1}{T} &\sum_{t} \sigma^t \E{x_v,\epsilon_v}{l(x_v^\intercal\wh_\lambda^t,y_v^t)}\biggr]\leq \frac{ML\Lambda_D^T}{\sqrt{T}}.
\end{align*}
We can use Lipschitzness of the loss function in the second term of Equation \ref{eq:from_sup_rad} to get 
\begin{align*}
    \E{\sigma, (X_v^t, \epsilon_v^t \forall t)}{\sup_\lambda \frac{1}{n_vT} \sum_{t,i} \sigma^{t(i)}l(X_v^{t(i)\intercal}\wh_\lambda^t,y_v^{t(i)})} \leq \frac{L}{n_vT}\E{\sigma, (X_v^t, \epsilon_v^t \forall t)}{\sup_\lambda \sum_{t,i} \sigma^{t(i)}X_v^{t(i)\intercal}\wh_\lambda^t}.
\end{align*}
This term can be viewed as a trace product between validation examples and a matrix of predictions $\wh_\lambda^t$. We use this in Lemma \ref{lem:S_tr} to show that with probability $\geq 1-\delta$:
\begin{align*}
    &\E{\sigma, (X_v^t, \epsilon_v^t \forall t)}{\sup_\lambda \frac{1}{n_vT} \sum_{t,i} \sigma^{t(i)} l(x_v^{t(i)\intercal}\wh_\lambda^t,y_v^{t(i)})} \leq\nonumber\\
       &\frac{L}{\sqrt{n_v}} \sqrt{\E{x_v}{\|x_v\|^2}}\sqrt{\E{X,y}{\|y\|^2/V(XX^\intercal)}} + \frac{L\tilde{M}}{\sqrt[4]{n_v^2T}}\sqrt{\E{x_v}{\|x_v\|^2}}\sqrt[4]{\frac{\ln(1/\delta)}{2}}.
\end{align*}
We can now replace $\delta$ by $\delta/4$ in the three probabilistic bounds above so that the following holds with probability at least $1-\delta$:
\begin{align*}
    l_v(\lambda_{ERM}) - l_v(\lambda^*) &\leq\frac{2ML\Lambda_D^T
        }{\sqrt{T}}\E{x_v}{\|x_v\|} + \frac{2L}{\sqrt{n_v}} \sqrt{\E{x_v}{\|x_v\|^2}}\sqrt{\E{X,y}{\|y\|^2/V(XX^\intercal)}}\nonumber\\
        &
         + \frac{2L\tilde{M}}{\sqrt[4]{n_v^2T}}\sqrt{\E{x_v}{\|x_v\|^2}}\sqrt[4]{\frac{\ln(4/\delta)}{2}}\nonumber\\
       & + 2C\sqrt{\frac{2\ln(16/\delta)}{T}} + C\sqrt{\frac{\ln(4/\delta)}{2T}}.
\end{align*}
To get the desired result, we note that $C\sqrt{\frac{\ln(4/\delta)}{2T}} \leq C/2\sqrt{\frac{2\ln(16/\delta)}{T}}$.
\end{proof}


Below we present and prove the main Lemmas used in the above theorem. We first start by upper-bounding the generalization error in terms of two different Rademacher complexities: Rademacher complexity of validation loss with fixed training data and Rademacher complexity of expected validation loss over choice of validation data. 

\begin{lemma}\label{lem:sup_to_rad}
    Given a bounded validation loss function, that is, given that $l(x_v^\intercal\wh_\lambda(X,y),y_v) \leq C,  \forall x_v,y_v,X,y,\lambda$. For any problem instance $S$ as defined in Equation \ref{def:prob}, with probability at least $1-\delta$, 
    \begin{align}
        \sup_\lambda (l_v(\lambda) - l_{v}(\lambda,S)) &\leq 2\E{\sigma, \etr{S}}{\sup_\lambda \frac{1}{T} \sum_{t} \sigma^t \E{x_v,\epsilon_v}{l(x_v^\intercal\wh_\lambda^t,y_v^t)}}\nonumber\\
        &+ 2\E{\sigma, \eval{S}}{\sup_\lambda \frac{1}{n_vT} \sum_{t,i} \sigma^{t(i)}l(X_v^{t(i)\intercal}\wh_\lambda^t,y_v^{t(i)})}\nonumber\\
        &+ 2C\sqrt{\frac{2\ln(4/\delta)}{T}}.\nonumber
    \end{align}
    Where $y_v^t = f^t(x_v^\intercal,\epsilon_v)$, $y_v^{t(i)} = f^t(X_v^{\intercal t(i)},\epsilon_v^{t(i)})$.
    % Here $M_{ev} = \max_t\E{x_v^t,\epsilon_v^t}{(x_{v}^{tT}\wh^t_{\lambda} - y_{v}^t)^2} \leq C$.
\end{lemma}
\begin{proof}
We begin by breaking the generalization error into error induced from a finite sampling of tasks, and error from a finite sampling of validation examples. This is similar to the approach of \cite{mtl_maurer}, where the authors break the generalization error into error induced from learning a representation, and error from learning given a representation.
    \begin{align}
    \sup_\lambda (l_v(\lambda) - l_{v}(\lambda,S)) = &\sup_\lambda (l_v(\lambda) - l_{ev}(\lambda, \etr{S}) + l_{ev}(\lambda, \etr{S}) - l_{v}(\lambda,S))\nonumber\\
    \leq &\sup_\lambda (l_v(\lambda) - l_{ev}(\lambda, \etr{S})) + \sup_\lambda (l_{ev}(\lambda, \etr{S}) - l_{v}(\lambda,S))\label{eq:sup_decompose}.
\end{align}
Note that $l_v(\lambda)$ is the expected value of $l_{ev}(\lambda, \etr{S})$ over sampling of $\etr{S}$, whereas $l_{ev}(\lambda, \etr{S})$ is the average over $T$ samples of training data. We can use Corollary \ref{cor:mcd} by replacing each $l^i$ by $l_{ev}(\lambda, \etr{S})$ to get that with probability $\geq 1-\delta/2$,
\begin{equation}\label{eq:mcd_tr}
    \sup_\lambda (l_v(\lambda) - \lev(\lambda, \etr{S})) \leq \E{\etr{S}, \etr{S'}}{\sup_\lambda (\lev(\lambda,\etr{S}) - \lev(\lambda, \etr{S'}))} +  C\sqrt{\frac{2\ln(4/\delta)}{T}}.%M_{ev}\sqrt{\frac{2\ln(2/\delta)}{T}},
\end{equation}

Again note that, for a fixed $\etr{S}$, we can view $l_{v}(\lambda,S)$ as an average over $n_vT$ i.i.d.\ samples of the form $x_v,\epsilon_v$, where the $(tn_v+i)^\text{th}$ sample for $t\in[T], i\in[n_v]$ becomes the $i^\text{th}$ validation example for the $t^\text{th}$ task. We can then view $l_{ev}(\lambda, \etr{S})$ as the expected value of $l_{v}(\lambda,S)$ over the sampling of $\eval{S}$. Thus, replacing each $l^i$ in Corollary \ref{cor:mcd} by $l_{v}(\lambda,S)$, we get that with probability $\geq 1-\delta/2$,
\begin{align}\label{eq:mcd_val}
    \sup_\lambda (l_{ev}(\lambda, \etr{S}) - &l_{v}(\lambda,S)) \leq\nonumber\\
    &\E{\eval{S}, \eval{S'}}{\sup_\lambda (\lve(\lambda, \etr{S}\ewtimes\eval{S'}) - \lve(\lambda, \etr{S}\ewtimes\eval{S}))}+ C\sqrt{\frac{2\ln(4/\delta)}{n_vT}}.
\end{align}

In order to upper bound the unknown term in Equation \ref{eq:mcd_tr}, we note that we can arbitrarily swap the $i^{\text{th}}$ training instances between $\etr{S}$ and $\etr{S'}$ without changing the expectation. In fact, we can do this for all $i\in R \subseteq [T]$ for any arbitrary set $R$. This allows us to reduce the term to a Rademacher complexity. We show this below where we denote $y_v^t = f^t(x_v^\intercal,\epsilon_v)$:
\begin{align}
    \Eml{\etr{S}, \etr{S'}}\biggl[\sup_\lambda \lev(\lambda,& \etr{S'}) - \lev(\lambda, \etr{S})\biggr]\nonumber\\
    &=\Eml{\etr{S}, \etr{S'}}\left[\sup_\lambda \frac{1}{T} \sum_t \E{x_v,\epsilon_v}{l(x_v^\intercal\wh_\lambda^{\prime t},y_v^{\prime t})} - \frac{1}{T} \sum_t \E{x_v,\epsilon_v}{l(x_v^\intercal\wh^{t}_\lambda,y_v^t)}\right]\nonumber\\
    &= \Eml{\etr{S}, \etr{S'}}\left[\sup_\lambda \frac{1}{T} \sum_{t\in R} \E{x_v,\epsilon_v}{l(x_v^\intercal\wh_\lambda^t,y_v^t)} + \frac{1}{T} \sum_{t\notin R} \E{x_v,\epsilon_v}{l(x_v^\intercal\whp^{t}_\lambda,y_v^{\prime t})}\right.\nonumber\\
    &\left.- \frac{1}{T} \sum_{t\notin R} \E{x_v,\epsilon_v}{l(x_v^\intercal\wh_\lambda^t,y_v^t)} - \frac{1}{T} \sum_{t\in R} \E{x_v,\epsilon_v}{l(x_v^\intercal\whp^{t}_\lambda,y_v^{\prime t})}\right]\nonumber\\
    &= 2\E{\sigma, \etr{S}}{\sup_\lambda \frac{1}{T} \sum_{t} \sigma^t \E{x_v,\epsilon_v}{l(x_v^\intercal\wh_\lambda^t,y_v^t)}}\label{eq:task_rad}.
\end{align}
In the last step we introduce rademachar variables for each task.

Similarly, in Equation \ref{eq:mcd_val}, we note that we can arbitrarily swap the $(tn_v + i)^{\text{th}}$ validation instances between $\eval{S}$ and $\eval{S'}$ without changing the expectation. In fact, we can do this for all $(t,i)\in R \subseteq [T]\times [n_v]$ for any arbitrary set $R$. This allows us to reduce the term to a Rademacher complexity. We show this below where we denote $y_v^{t(i)} = f^t(X_v^{\intercal t(i)},\epsilon_v^{t(i)})$ and $y_v^{\prime t(i)} = f^t(X_v^{\prime \intercal t(i)},\epsilon_v^{\prime t(i)})$:
\begin{align}
    \Eml{\eval{S}, \eval{S'}}&\biggl[\sup_\lambda(l_v(\lambda, \etr{S}\ewtimes\eval{S}) - l_{v}(\lambda,\etr{S}\ewtimes\eval{S'}))\biggr]\nonumber\\
    &=\Eml{\eval{S}, \eval{S'}}\left[\sup_\lambda \frac{1}{T} \sum_t \frac{1}{n_v} \sum_i l(X_v^{t(i)\intercal}\wh_\lambda^t,y_v^{t(i)}) - \frac{1}{T} \sum_t \frac{1}{n_v} \sum_i l(X_v^{\prime t(i)\intercal}\wh_\lambda^t,y_v^{\prime t(i)})\right]\nonumber\\
    &= \Eml{\eval{S}, \eval{S'}}\left[\sup_\lambda \frac{1}{n_vT} \sum_{(t,i) \notin R} l(X_v^{t(i)\intercal}\wh_\lambda^t,y_v^{t(i)}) + \frac{1}{n_vT} \sum_{(t,i) \in R} l(X_v^{\prime t(i)\intercal}\wh_\lambda^t,y_v^{\prime t(i)})\right.\nonumber\\
    &\left.- \frac{1}{n_vT} \sum_{(t,i) \notin R} l(X_v^{\prime t(i)\intercal}\wh_\lambda^t,y_v^{\prime t(i)}) - \frac{1}{n_vT} \sum_{(t,i) \in R} l(X_v^{t(i)\intercal}\wh_\lambda^t,y_v^{t(i)})\right]\nonumber\\
    &= 2\E{\sigma, \eval{S}}{\sup_\lambda \frac{1}{n_vT} \sum_{t,i} \sigma^{t(i)}l(X_v^{t(i)\intercal}\wh_\lambda^t,y_v^{t(i)})}\label{eq:tr_rad}.
\end{align}
In the last step, we introduce rademachar variables for each value of $(t,i)$.

Since Equations \ref{eq:mcd_tr} and \ref{eq:mcd_val} hold with probability $\geq 1-\delta/2$ each, both equations hold with probability $\geq 1-\delta$ by a union bound. We get the desired result by combining Equations \ref{eq:sup_decompose}, \ref{eq:mcd_tr}, \ref{eq:mcd_val}, \ref{eq:task_rad}, \ref{eq:tr_rad} and further noting that $C\sqrt{\frac{2\ln(4/\delta)}{T}} \geq C\sqrt{\frac{2\ln(4/\delta)}{n_vT}}$.
\end{proof}



In the following we give an upper bound on the expectation with respect to sampling of the training set, of the Rademacher complexity of the expected value of validation error over sampling of validation tasks in terms of the distribution of inputs $x$.

\begin{lemma}\label{lem:S_v}
   Given a validation loss function that satisfies Assumptions \ref{assum:bound} and \ref{assum:lips} given in Section \ref{sec:ridge} and $\etr{S}$ as defined in Equation \ref{def:etr}, the following holds with probability at least $1-\delta$ (where we denote $y_v^t = f^t(x_v,\epsilon_v)$):
   \begin{align}
       \Eml{\sigma, \etr{S}}\biggl[\sup_\lambda \frac{1}{T} \sum_{t}& \sigma^t \E{x_v,\epsilon_v}{l(x_v^\intercal\wh_\lambda^t,y_v^t)}\biggr]\leq \frac{ML\Lambda_D^T}{\sqrt{T}}
   \end{align}
   where $M^2 = \max\|Xy\|^2$ and $\Lambda_D^T = \E{X}{\max_t 1/V(X^tX^{t\intercal})}$. 
\end{lemma}
\begin{proof}
We proceed with the proof much similar to Lemma \ref{lem:S_v_2}. We first note that if $y_v = f(x_v,\epsilon_v)$ for a deterministic function $f$, Lipschitzness of the loss function implies Lipschitzness in expectation over $\epsilon_v$:
\begin{align}
    l(x_v^\intercal\wh_1, y_v) - l(x_v^\intercal\wh_2, y_v) &\leq L|x_v^\intercal\wh_1 - x_v^\intercal\wh_2|\nonumber\\
    \implies \E{\epsilon_v}{l(x_v^\intercal\wh_1, y_v) - l(x_v^\intercal\wh_2, y_v)} &\leq L|x_v^\intercal\wh_1 - x_v^\intercal\wh_2|.\nonumber
\end{align}
Using Lipschitzness (Corollary \ref{thm:rad_lipschitz}):
\begin{align}
    \E{\sigma, \etr{S}}{\sup_\lambda \frac{1}{T} \sum_{t} \sigma^t \E{x_v,\epsilon_v}{l(x_v^\intercal\wh_\lambda^t,y_v^t)}} &\leq \E{\sigma, \etr{S},x_v}{\sup_\lambda \frac{1}{T} \sum_{t} \sigma^t \E{\epsilon_v}{l(x_v^\intercal\wh_\lambda^t,y_v^t)}}\nonumber\\
    &\leq \frac{L}{T}\E{\sigma, \etr{S},x_v}{\sup_\lambda  \sum_{t} \sigma^t x_{v}^{\intercal}\wh^t_{\lambda}}.\label{step:task_rc_l1}
\end{align}
This expression is similar to a one-sample variant of the Rademacher complexity in Lemma \ref{lem:S_tr} as well as that in \cite{trace_reg}. However, we cannot use the techniques used there since that would result in a constant upper bound. We instead use Equation \ref{eq:lamb_lips} and Theorem \ref{thm:rad_lips_general} to conclude that,
\begin{align}
    \frac{L}{T}\E{\sigma, \etr{S},x_v}{\sup_\lambda  \sum_{t} \sigma^t x_{v}^{\intercal}\wh^t_{\lambda}} &\leq \frac{L}{T}\E{x_v}{\|x_v\|\E{\sigma, \etr{S}}{\sup_\lambda  \sum_{t} \sigma^t \frac{\|X^ty^t\|}{V^T+\lambda}}}\nonumber\\
    &= \frac{L}{T}\E{x_v}{\|x_v\|}\E{\sigma, \etr{S}}{\sup_\lambda \sum \sigma^t \frac{\|X^ty^t\|}{V^T+\lambda}}\nonumber\\
    &\leq \frac{L}{T}\E{x_v}{\|x_v\|}\E{\etr{S}}{(\sup_\lambda\frac{1}{V^T + \lambda}) \E{\sigma}{\sum \sigma^t \|X^ty^t\|}}\nonumber\\
    &\leq \frac{L}{T}\E{x_v}{\|x_v\|}\E{\etr{S}}{\frac{\sqrt{\sum \|X^ty^t\|^2}}{V^T}}.\nonumber
\end{align}
We use Khintchine's inequality (Theorem \ref{thm:khintchine}) and set $\lambda = 0$ in the last step. 
To get the desired result, we note from assumption that $M^2 = \max \|Xy\|^2 \implies \sqrt{\sum \|X^ty^t\|^2} \leq M\sqrt{T}$. Thus,
\begin{align}
    \frac{L}{T}\Eml{\sigma, \etr{S},x_v}\biggl[\sup_\lambda & \sum_{t} \sigma^t x_{v}^{\intercal}\wh^t_{\lambda}\biggr]\nonumber\\
    &\leq \frac{L}{T}\E{x_v}{\|x_v\|}\E{\etr{S}}{\frac{\sqrt{\sum \|X^ty^t\|^2}}{V^T}}\nonumber\\
    &\leq \frac{L}{T}\E{x_v}{\|x_v\|}\E{\etr{S}}{\frac{M\sqrt{T}}{V^T}}\nonumber\\
    &\leq \frac{ML\Lambda_D^T}{\sqrt{T}}\E{x_v}{\|x_v\|}\nonumber
\end{align}
\end{proof}



We now show an upper bound on the expected Rademacher complexity of validation loss given fixed training data in terms of the distribution of outputs $y$.

\begin{lemma}\label{lem:S_tr}
    Given a validation loss function that satisfies Assumptions \ref{assum:bound} and \ref{assum:lips} given in Section \ref{sec:ridge}, and $\eval{S}$ as defined in Equation \ref{def:eval}, the following holds with probability at least $1-\delta$ (where we denote $y_v^{t(i)} = f^t(x_v^{t(i)},\epsilon_v^{t(i)})$):
   \begin{align}
       &\E{\sigma, \eval{S}}{\sup_\lambda \frac{1}{n_vT} \sum_{t,i} \sigma^{t(i)} l(x_v^{t(i)\intercal}\wh_\lambda^t,y_v^{t(i)})} \leq\nonumber\\
       &\frac{L}{\sqrt{n_v}} \sqrt{\E{x_v}{\|x_v\|^2}}\sqrt{\E{X,y}{\|y\|^2/V(XX^\intercal)}} + \frac{L\tilde{M}}{\sqrt[4]{n_v^2T}}\sqrt{\E{x_v}{\|x_v\|^2}}\sqrt[4]{\frac{\ln(1/\delta)}{2}}.\nonumber
   \end{align}
Here $\tilde{M}^2 = \max \|y\|^2/V(XX^\intercal)$. 
\end{lemma}
\begin{proof}
We define $\mathcal{R}$ as below and use Lipschitzness to upper bound it as a simpler Rademacher complexity term:
\begin{align}
    \mathcal{R} &= \frac{1}{n_vT} \E{\sigma}{\sup_\lambda \sum_t\sum_i \sigma^{t(i)} l(x_v^{t(i)\intercal}\wh_\lambda^t,y_v^{t(i)})} \nonumber\\
    &\leq \frac{L}{n_vT} \E{\sigma}{\sup_\lambda \sum_t\sum_i \sigma^{t(i)} x^{t(i)\intercal}_{v} \wh^t_\lambda}.\nonumber
\end{align}

To compute the above quantity, we use a manipulation similar to one in \cite{trace_reg}. We define two matrices $X_\sigma \in \R^{T\times d}$ and $W_\lambda \in \R^{d \times T}$: the $t$-th row of $X_\sigma$ is defined as $X_{\sigma_{(t)}} = \sum_i \sigma^{t(i)} x^{t(i)\intercal}_{v}$ and the $t$-th column of $W_\lambda$ is defined as $W_\lambda^{(t)} = \wh^t_\lambda$
. By this definition we see that,
\begin{align}
    \frac{L}{n_vT} \E{\sigma}{\sup_\lambda \sum_t\sum_i \sigma^{t(i)} x^{t(i)\intercal}_{v} \wh^t_\lambda} &=  \frac{L}{n_vT} \E{\sigma}{\sup_\lambda tr(X_\sigma W_\lambda)}\nonumber\\
    \implies \mathcal{R} &\leq \frac{L}{n_vT} \E{\sigma}{\sup_\lambda \|X_\sigma\|_2 \|W_\lambda\|_2}\nonumber\\%\label{eq:rad_holder_tight}\\
     \implies \E{\eval{S}}{\mathcal{R}} &\leq \frac{L}{n_vT} \E{\sigma,x^{t(i)}_{v}}{\|X_\sigma\|_2}{\sup_\lambda\|W_\lambda\|_2}.\label{eq:rad_holder}
\end{align}
Note that $\E{\eval{S}}{\mathcal{R}}$ corresponds to the left hand side in the statement of the Lemma.

\begin{align}
    \|X_\sigma\|_2 &= \sqrt{tr(X_\sigma X_\sigma^T)}\nonumber\\
    &= \sqrt{\sum_t (\sum_i \sigma^{t(i)} x^{t(i)\intercal}_{v})(\sum_j \sigma^{t(j)} x^{t(j)\intercal}_{v})^\intercal} \quad \text{(from definition)}\nonumber\\
    \implies \E{\sigma,x^{t(i)}_{v}}{\|X_\sigma\|_2} &\leq \sqrt{\sum_t \E{}{(\sum_i \sigma^{t(i)} x^{t(i)\intercal}_{v})(\sum_j \sigma^{t(j)} x^{t(j)\intercal}_{v})^\intercal}}\nonumber\\
    &= \sqrt{\sum_t \E{}{\sum_ix^{t(i)\intercal}_{v}x^{t(i)}_{v}}}\nonumber\\
    &= \sqrt{\sum_t \E{}{\sum_i \|x^{t(i)\intercal}_{v}\|^2}}\nonumber\\
    &= \sqrt{n_vT\E{x_v}{\|x_v\|^2}}.\label{eq:X_2}
\end{align}

To compute $\|W_\lambda\|_2$:
\begin{align}
    \|W_\lambda\|_2 &= \sqrt{tr(W_\lambda^\intercal W_\lambda)}\nonumber\\
    &= \sqrt{\sum_t \wh_\lambda^{t\intercal}\wh_\lambda^t} = \sqrt{\sum_t \|\wh_\lambda^t\|^2}\nonumber.
\end{align}

It remains to compute bounds on $\E{}{\sup_\lambda \sqrt{\sum_t \|\wh^t_\lambda\|^2}}$.
Using Hoeffding inequality (Theorem \ref{thm:Hoeffding}), if $\|\wh_\lambda^t\|^2\leq \tilde{M}^2 \forall t,\lambda$, we can say the following with probability $\geq 1-\delta$:
\begin{align}
    \frac{1}{T} \sum_t \|\wh^t_\lambda\|^2 \leq \E{X,y}{\|\wh_\lambda\|^2} + \tilde{M}^2\sqrt{\frac{\ln(1/\delta)}{2T}}.\nonumber
\end{align}
This gives us that with probability $\geq 1-\delta$,
\begin{align}
    \sup_\lambda\|W_\lambda\|_2 &\leq \sup_\lambda \sqrt{T(\E{X,y}{\|\wh_\lambda\|^2}) + \tilde{M}^2\sqrt{\frac{T\ln(1/\delta)}{2}}}\nonumber\\
    &= \sqrt{T}\sqrt{\sup_\lambda (\E{X,y}{\|\wh_\lambda\|^2}) + \tilde{M}^2\sqrt{\frac{\ln(1/\delta)}{2T}}}\nonumber\\
    &\leq \sqrt{T\sup_\lambda (\E{X,y}{\|\wh_\lambda\|^2})} + \tilde{M}\sqrt[4]{\frac{T\ln(1/\delta)}{2}}.\label{eq:w_lamb_sum}
\end{align}

Finally, note that from Equation \ref{eq:w_norm_max},
\begin{align}
    \|\wh_\lambda\|^2 &\leq \|y\|^2/V(XX^\intercal),\nonumber
\end{align}
where we defined $V(.)$ as the smallest non-0 singular value of the matrix. Thus,
\begin{align}
    \sup_\lambda \E{X,y}{\|\wh_\lambda\|^2} &\leq \E{X,y}{ \|y\|^2/V(XX^\intercal)}\label{eq:sup_w_lamb}
\end{align}
and,
\begin{align}
    \max \|\wh_\lambda\|^2 &\leq \max \|y\|^2/V(XX^\intercal).\nonumber
\end{align}
{So that $\tilde{M}^2 = \max\|y\|^2/V(XX^\intercal)$ satisfies $\|\wh_\lambda^t\|^2\leq \tilde{M}^2\forall t,\lambda$}.

Combining Equations \ref{eq:rad_holder}, \ref{eq:X_2}, \ref{eq:w_lamb_sum} and \ref{eq:sup_w_lamb},
\begin{align}
    \E{\eval{S}}{\mathcal{R}} \leq \frac{L}{\sqrt{n_v}}\sqrt{\E{x_v}{\|x_v\|^2}}\sqrt{\E{X,y}{ \|y\|^2/V(XX^\intercal)}} + \frac{L\tilde{M}}{\sqrt[4]{n_v^2T}}\sqrt{\E{x_v}{\|x_v\|^2}}\sqrt[4]{\frac{\ln(1/\delta)}{2}}\nonumber.
\end{align}

\end{proof}


