\begin{algorithm}[h]
\caption{Generation Algorithm}\label{alg:alg2}
\begin{algorithmic}[1]
\State{\textbf{Input:}} prompt $\{x_1,...,x_N\}$; integer hash function \(H\) with hash space $\{1,2,...,d\}$; secret key $\xi$; watermark strength $\delta$; watermark window size \( h\); large language model $P_M$.
\For{$n = N+1, N+2, \dots$}
    \State Apply the language model to compute next logit vector $\ell_t \gets P_M(x_{1:n-1})$.  
    % \State Calculate the universal cipher $\theta_n^{0} \gets \xi \cdot x_n$ via self-seeding strategy.
    % \State Seed the random number generator with cipher $\theta_t \gets \xi \cdot H(x_t)$.
    \State Calculate the hash signature of the watermark window $I \gets \{H(x_{n-k})|1\leq k\leq h\}$.
    \State Partition the vocabulary $\mathcal{V}$ into uniform sub-vocabularies \( \{v_1, \dots, v_d\} \).
    \State Derive the cipher $\theta^{i}_n$ for each sub-vocabulary $v_i$ following Eq~\ref{eq:seed2}.
    \State Generate a sub-green list $G^{i}$ for each sub-vocabulary $v_i$ seeded by the corresponding $\theta^{i}_n$.
    % \For{$v_i = v_1, v_2, \dots v_d$}
    % \If{i in $\{\hat{H}(o_1),\dots,\hat{H}(o_k)\}$)}
    %     \State Use  $\theta_t\cdot i$ as the seed of PRF $P$ and generate $v_g^i$ from $v_i$ .
    % \Else
    %     \State Use $\theta_t$ the seed of PRF $P$ and generate $v_g^i$ from $v_i$ .
    % \EndIf
    % \EndFor
    \State  Union all sub-green lists $G^{i}$ as the green list $G$ of the full vocabulary. 
    \State Add $\delta$ to the logits of tokens in $G$ to modify the distribution by Eq~\ref{eq:equation1}.

    \State Sample the next token from the modified distribution.
\EndFor

\end{algorithmic}
\end{algorithm}
