% \begin{equation}
% P(X = x) = \sum_{i = x}^{h} \phi^{h - 1} \times \sum_{k = x}^{i} (1 - \phi)^{i - k} \phi^k \binom{k}{x} (1 - \gamma)^x \gamma^{k - x}
% \end{equation}

\begin{proposition}
For our watermark scheme with a window size of $h$ and hash space $d$, the probability of having exactly $X$ watermarks removed is given by:
\begin{equation}
P(X=x)=\sum_{i=x}^h\sum_{k=x}^i(\frac{1}{d})^{i-k}(1-\frac{1}{d})^{h+k-1}\binom{k}{x}(\frac{1-\gamma}{d})^x(1-\frac{1-\gamma}{d})^{k-x}
\end{equation}
\end{proposition}
\textbf{Proof:} We define the following events:
\begin{itemize}
    \item \textbf{Event A}: The watermark window does not include any texture key to protect the watermark text. 
    \item \textbf{Event B}: The watermark window contains only one texture key to protect the watermark text.
    \item \textbf{Event C}: More than two tokens from the watermark window are involved in the hash space that protects the watermark text. In this case, modifying a single token will not remove the watermark.
\end{itemize}


Events A and C only contribute to $P(X = 0)$. Therefore, when considering perturbations for $X > 0$, we only need to focus on Event B. We define \( I = i \) as the number of consecutive tokens, starting from \( y_{o-1} \), that satisfy the condition \( H(y) \neq H(u_o) \), where \( u_o \) represents the position of the watermark. The sequence \( \{ y_{o-i}, \dots, u_o, \dots, y_{o+h-i-1} \} \) represents the first watermark window, where \( i \) is the maximum sliding distance for this window. The basic probability of a watermark window where no token's hash value equals \( H(u_o) \) is given by $\left( 1 - \frac{1}{d} \right)^{h-1}$,
where \( m \) is the size of the hash space. For \( X = x \), there must exist a segment within the watermark window that can slide to the right by at least \( x \) positions. This implies that \( i \geq x \) for the watermark to affect subsequent tokens. Next, we consider the suffix \( \{ y_o, \dots, y_{o+h-i-1} \} \) and the probability distribution \( P(K=k|I=i) \), where \( K \) denotes the number of tokens in the suffix that do not match \( H(u_o) \). This probability follows:

\begin{equation}
P(K=k|I=i) = \left( 1 - \frac{1}{d} \right)^{h-1} \cdot \left( \frac{1}{d} \right)^{i-k} \cdot \left( 1 - \frac{1}{d} \right)^k
\end{equation}

Let \( Z \) represent the number of tokens that are affected by $u_o$. Given \( Z=z \), the probability \( P(Z=z|K=k) \) follows a binomial distribution:
\begin{equation}
P(Z=z|K=k) = \binom{k}{z} \left( \frac{1}{d} \right)^z \left( 1 - \frac{1}{d} \right)^{k-z}
\end{equation}
For each affected token, there is a probability of \( 1-\gamma \) of being in the red set (i.e., the watermark is erased) and \( \gamma \) for being in the green set (i.e., the watermark remains). Given \( Z=z \), the value \( X \) follows a binomial distribution \( \text{Binomial}(z, 1-\gamma) \), and the probability of erasing \( x \) watermarks is:
\begin{equation}
P(X=x|Z=z) = \binom{z}{x} (1-\gamma)^{x} \gamma^{z-x}
\end{equation}
We now compute the overall probability:
\begin{align}
P(X=x|K=k) &= \sum_{z=x}^k P(X=x|Z=z) P(Z=z|K=k) \\
&=\sum_{z=x}^k \binom{k}{z} \left( \frac{1}{d} \right)^z \left( 1 - \frac{1}{d} \right)^{k-z} \binom{z}{x} (1-\gamma)^{x} \gamma^{z-x}
\end{align}
Using the law of total probability, we can calculate \( P(X=x|I=i) \) by summing over \( k \):
\begin{align}
P(X=x|I=i) &= \sum_{k=x}^{i} P(X=x|K=k) P(K=k|I=i)
\end{align}
Finally, by iterating over all possible values of \( i \), we obtain the total probability for \( X=x \):
\begin{align}
P(X=x) &= \sum_{i=x}^{h} P(X=x|I=i)\\
&=\sum_{i=x}^h\sum_{k=x}^i(\frac{1}{d})^{i-k}(1-\frac{1}{d})^{h+k-1}\sum_{z=x}^k\binom{k}{z}(\frac{1}{d})^z(1-\frac{1}{d})^{k-z} \binom{z}{x} (1-\gamma)^{x} \gamma^{z-x} \\
&=\sum_{i=x}^h\sum_{k=x}^i(\frac{1}{d})^{i-k}(1-\frac{1}{d})^{h+k-1}\binom{k}{x}\sum_{z=x}^k\binom{k-x}{z-x}(\frac{1}{d})^z(1-\frac{1}{d})^{k-z} (1-\gamma)^{x} \gamma^{z-x}
\end{align}
by adjusting the summation variable, setting \( t = z - x \), which implies \( z = t + x \). Consequently, the range of \( t \) is \( 0 \leq t \leq k - x \). Substituting this into the sum, we obtain:
\begin{equation}
P(X=x) =\sum_{i=x}^n\sum_{k=x}^i(\frac{1}{d})^{i-k}(1-\frac{1}{d})^{h+k-1} \left( \frac{1}{d} \right)^x \sum_{t=0}^{k - x} \binom{k - x}{t} \left( \frac{1}{d} \right)^t \left( 1 - \frac{1}{d} \right)^{(k - x) - t} \gamma^t
\end{equation}
This equation can be simplified by applying the binomial expansion for \( \sum_{t=0}^{n} \binom{n}{t} a^t b^{n - t} = (a + b)^n \), leading to:
\begin{equation}
P(X=x) = \sum_{i=x}^{h} \sum_{k=x}^{i} \left( \frac{1}{d} \right)^{i-k} \left( 1 - \frac{1}{d} \right)^{h+k-1} \binom{k}{x} \left( \frac{1-\gamma}{d} \right)^x \left( 1 - \frac{1-\gamma}{d} \right)^{k-x}
\end{equation}
Alternatively, a more efficient derivation can be achieved by directly applying Proposition~\ref{prop:kgw_min}. In this approach, let \( \phi = 1 - \frac{1}{d} \), and define \( \gamma = \frac{1}{d} (1 - r) \) as the probability of successfully eliminating the watermark. The failure probability is then \( 1 - \frac{1 - r}{d} \), from which this can be directly derived.

\begin{proposition}
Let $\hat{E}(X)$ denote the expected perturbation under the KGW-Min strategy in the presence of adversarial tampering, and let $E(X)$ denote the expected perturbation under our proposed method. There exists a threshold pair $(\gamma_c, d_c)$ such that for $d > d_c$ and $\gamma \geq \gamma_c = \frac{1}{d+1}$, then the inequality $\hat{E}(X) > E(X)$ holds.
\end{proposition}
\textbf{Proof:} 
We use $\hat{P}$ and $P$ to denote the probability that the subsequent watermark tokens are perturbed under the KGW-MIN method and our proposed method, respectively, given that an adversarial manipulation occurs. We next aim to establish the existence of threshold values $r_c$ and $m_c$, such that for all $x > 0$, when $\gamma \geq \gamma_c = \frac{1}{d + 1}$ and $d > d_c$, the inequality $\hat{P}(X = x) \geq P(X = x)$ holds. Formally,
\begin{equation}
\begin{aligned}
\hat{P}(X = x) &= \sum_{v=1}^{|\mathcal{V}|} \sum_{i = x}^{h} \sum_{k = x}^{i} (1 - p)^{i - k} p^{k + h - 1} \binom{k}{x} (1 - \gamma)^x \gamma^{k - x} \\
&> \sum_{i = x}^{n} \sum_{k = x}^{i} \left(\frac{1}{d}\right)^{i - k} \left(1 - \frac{1}{d}\right)^{h + k - 1} \binom{k}{x} \left(\frac{1 - \gamma}{d}\right)^x \left(1 - \frac{1 - \gamma}{d}\right)^{k - x}\\
&=P(X = x)
\end{aligned}
\end{equation}

To prove the above inequality holds universally, we first show that when $\gamma \geq \frac{1}{d + 1}$, the inequality:
\begin{equation}
\left(\frac{1 - \gamma}{d}\right)^x \left(1 - \frac{1 - \gamma}{d}\right)^{k - x} < (1 - \gamma)^x \gamma^{k - x}
\end{equation}
holds for all $0 \leq x \leq k \leq h$. This inequality is equivalent to showing that $\left(\frac{1}{d}\right)^x \left(1 - \frac{1 - \gamma}{d}\right)^{k - x} < \gamma^{k - x}$. Taking the logarithm of both sides and subtracting yields the difference function, formally:
\begin{equation}
f(k) = -x \ln d + (k - x) \left[ \ln\left(1 - \frac{1 - \gamma}{d}\right) - \ln \gamma \right]
\end{equation}
Since $d > 1$ and $0 < \gamma < 1$, the term $\ln\left(1 - \frac{1 - \gamma}{d}\right) - \ln \gamma$ is always non-negative. Therefore, $f(k)$ increases with $k$, and we have $f(k) < f(h) < -x \ln d + h \left[ \ln\left(1 - \frac{1 - \gamma}{d}\right) - \ln \gamma \right]$. To ensure that $f(k) < 0$ holds for all $k$, it suffices to impose:
\begin{equation}
-x \ln d + h \left[ \ln\left(1 - \frac{1 - \gamma}{d}\right) - \ln \gamma \right] \leq 0,
\end{equation}
which yields $\gamma \geq \frac{d - 1}{d^{x/h + 1} - 1}$. To guarantee this inequality holds for any $x$, a sufficient condition is $\gamma \geq \frac{1}{1 + m} \geq \frac{d - 1}{1 + d^{x/h + 1}}$. Hence, if $\gamma \geq \frac{1}{d + 1}$, we have $f(k) < -x \ln d+ h \left[ \ln\left(1 - \frac{1 - \gamma}{d}\right) - \ln \gamma \right] < 0$ always holds, completing the proof of the inequality. As a direct consequence, the following inequality between the probabilities holds:
\begin{equation}
\begin{aligned}
P(X = x) &= \sum_{i=x}^n\sum_{k=x}^i(\frac{1}{d})^{i-k}(1-\frac{1}{d})^{h+k-1}\binom{k}{x}(\frac{1-\gamma}{d})^x(1-\frac{1-\gamma}{d})^{k-x} \\
&< \sum_{i=x}^n\sum_{k=x}^i(\frac{1}{d})^{i-k}(1-\frac{1}{d})^{h+k-1}\binom{k}{x}(1-\gamma)^{x} \gamma^{k-x}
\end{aligned}
\end{equation}

Next, we aim to show that there exists a real-valued threshold $m_c$ such that for all $m > m_c$, the following inequality holds:
\begin{equation}
\sum_{i = x}^h \sum_{k = x}^i \left(\frac{1}{d}\right)^{i - k} \left(1 - \frac{1}{d}\right)^{h + k - 1}
< \sum_{v = 1}^{|\mathcal{V}|} \sum_{i = x}^h \sum_{k = x}^i (1 - p)^{i - k} p^{k + h - 1}
\end{equation}
Let us denote the left-hand side as $S_{\text{left}} = \sum_{i = x}^h \sum_{k = x}^{i} \left( \frac{1}{d} \right)^{i-k} \left( 1 - \frac{1}{d} \right)^{h+k-1}$. Given that the vocabulary size $|\mathcal{V}|$ is typically a large integer, the right-hand side can be approximated by an integral, i.e.,
\begin{equation}
S_{\text{right}} = \sum_{v=1}^{|\mathcal{V}|} \sum_{i = x}^h \sum_{k = x}^i (1 - p)^{i - k} p^{k + h - 1} \approx \int_0\textsuperscript{1} \sum_{i = x}^h \sum_{k = x}^i (1 - p)^{i - k} p^{k + h - 1} \, dp.
\end{equation}

By applying the identity of the Beta function with substitutions $a = i - k$ and $b = k + h - 1$, we obtain:
\begin{equation}
\int_0\textsuperscript{1} (1 - p)^a p^b \, dp = B(a + 1, b + 1) = \frac{a! \, b!}{(a + b + 1)!}
= \frac{(i - k)! \, (k + h - 1)!}{(i + h)!}
\end{equation}
If each term on the left-hand side satisfies the inequality$\left( \frac{1}{d} \right)^{i - k} \left( 1 - \frac{1}{d} \right)^{h + k - 1} < \frac{(i - k)! (k + h - 1)!}{(i + h)!}$, then it directly follows that $S_{\text{left}} < S_{\text{right}}$. Taking the natural logarithm of both sides, we obtain:
\begin{equation}
\left( \frac{1}{d} \right)^{i - k} \left( 1 - \frac{1}{d} \right)^{h + k - 1} < \frac{(i - k)! \, (k + h - 1)!}{(i + h)!}
\end{equation}
Taking the natural logarithm of both sides, the inequality becomes:
\begin{equation}
(i - k) \ln \left( \frac{1}{d} \right) + (h + k - 1) \ln \left( 1 - \frac{1}{d} \right)
< \ln \left( \frac{(i - k)! \, (k + h - 1)!}{(i + h)!} \right)
\end{equation}
Define the function:
\begin{equation}
f(m) = (i - k) \ln \left( \frac{1}{d} \right) + (h + k - 1) \ln \left( 1 - \frac{1}{d} \right)
= - (i - k) \ln m + (h + k - 1) \ln \left(1 - \frac{1}{d} \right)
\end{equation}

To further bound the function $f(m)$, we utilize the inequality $\ln(1 - x) < -x - \frac{x^2}{2}$ for $0 < x < 1$, and note that since $m > 1$, it follows that:
\begin{equation}
\ln\left(1 - \frac{1}{d} \right) \leq -\frac{1}{d} - \frac{1}{2d^2} \quad \Rightarrow \quad
f(m) < - (i - k)\ln d - \frac{h + k - 1}{d}
\end{equation}
To lower-bound the right-hand side of the inequality involving factorial terms, we apply a simplified version of Stirling’s approximation, namely $\ln(n!) \geq n \ln n - n$, and obtain:
\begin{equation}
\begin{aligned}
\ln \left( \frac{(i - k)! (k + h - 1)!}{(i + h)!} \right)
&= \ln (i-k)! + \ln (k + h - 1)! - \ln (i + h)! \\
&\geq (i - k)\ln(i - k) + (k + h - 1)\ln(k + h - 1) \\
&\quad - (i + h)\ln(i + h)
\end{aligned}
\end{equation}

We now consider a constructive lower bound for $m$ as follows:
\begin{equation}
d \geq \left\lceil \frac{(i + h)^{2h}}{(i - k)(h + k - 1)} \right\rceil 
\quad \Rightarrow \quad 
\ln d \geq \ln \left( \frac{(i + h)^{2h}}{(i - k)(h + k - 1)} \right)
\end{equation}
This yields the upper bound:
\begin{equation}
\begin{aligned}
- (i - k) \ln m 
&\leq - (i - k) \ln \left( \frac{(i + h)^{2h}}{(i - k)(h + k - 1)} \right) \\
&= (i - k)\left[ \ln(i - k) + \ln(h + k - 1) - 2h \ln(i + h) \right]
\end{aligned}
\end{equation}
Therefore,
\begin{equation}
f(m) < - (i - k)\ln m - \frac{h + k - 1}{m}
\leq (i - k)\left[ \ln(i - k) + \ln(h + k - 1) - 2h \ln(i + h) \right] - \frac{h + k - 1}{m}
\end{equation}
Since $(i - k) \ln(h + k - 1) < (k + h - 1)\ln(k + h - 1)$ and $-2h \ln(i + h) < - (i + h) \ln(i + h)$, it follows that:
\begin{equation}
\begin{aligned}
&(i - k)\left[ \ln(i - k) + \ln(h + k - 1) - 2h \ln(i + h) \right] - \frac{h + k - 1}{m} \\
&\quad < (i - k)\ln(i - k) + (k + h - 1)\ln(k + h - 1) - (i + h)\ln(i + h)
\end{aligned}
\end{equation}
which guarantees that the desired inequality holds. As a result, there exists a constant threshold $m_c$ such that for all $m > m_c$, we have:
\begin{equation}
\sum_{i = x}^h \sum_{k = x}^i \left(\frac{1}{d}\right)^{i - k} \left(1 - \frac{1}{d}\right)^{h + k - 1}
< \sum_{v = 1}^{|\mathcal{V}|} \sum_{i = x}^h \sum_{k = x}^i (1 - p)^{i - k} p^{k + h - 1}
\end{equation}
Combining the previously established inequality $(\frac{1 - \gamma}{m})^x \left(1 - \frac{1 - \gamma}{m}\right)^{k - x} < (1 - \gamma)^x \gamma^{k - x}$, we obtain the following relationship:
\begin{equation}
\begin{aligned}
\hat{P}(X = x) &= \sum_{v = 1}^{|\mathcal{V}|} \sum_{i = x}^{h} \sum_{k = x}^{i} (1 - \phi)^{i - k} \phi^{k + h - 1} \binom{k}{x} (1 - \gamma)^x \gamma^{k - x} \\
&> \sum_{i = x}^{n} \sum_{k = x}^{i} \left(\frac{1}{d}\right)^{i - k} \left(1 - \frac{1}{d} \right)^{h + k - 1} \binom{k}{x} \left(\frac{1 - \gamma}{d} \right)^x \left(1 - \frac{1 - \gamma}{d} \right)^{k - x}\\& >\sum_{i=x}^n\sum_{k=x}^i(\frac{1}{d})^{i-k}(1-\frac{1}{d})^{h+k-1}\binom{k}{x}(1-\gamma)^{x} \gamma^{k-x}\\& = P(X = x).
\end{aligned}
\end{equation}
Since the inequality $\hat{P}(X = x) > P(X = x)$ holds for all $x > 0$, it must follow that $\hat{P}(X = 0) < P(X = 0)$ to preserve the total probability mass. Let $\hat{E}$ and $E$ denote the expected values under $\hat{P}$ and $P$, respectively. Then,
\begin{equation}
\hat{E}(X) = \sum_{x = 0}^{h} \hat{P}(X = x) \cdot x = \sum_{x = 1}^{h} \hat{P}(X = x) \cdot x, \quad
E(X) = \sum_{x = 0}^{h} P(X = x) \cdot x = \sum_{x = 1}^{h} P(X = x) \cdot x
\end{equation}
Hence, we conclude:
\begin{equation}
\hat{P}(X = x) > P(X = x) \quad \Rightarrow \quad \hat{E}(X) > E(X)
\end{equation}

\textbf{In conclusion}, we have shown that under the conditions $\gamma \geq \frac{1}{d + 1}$ and $d > d_c$, the KGW-MIN mechanism yields a strictly greater expected number of perturbed tokens than the baseline, i.e., $\hat{E}(X) > E(X)$.


\section{Visualization}

To better illustrate the effectiveness of our watermarking method, we provide qualitative visualizations based on representative examples from the C4-RealNewsLike dataset. As shown in Table~\ref{tab:demo-examples2} and Table~\ref{tab:demo-examples}, we present side-by-side comparisons of real completions, unwatermarked generations (NW), and watermarked generations (W) under the same prompt. In the visualization presented in Table~\ref{tab:examples3}, we comparatively analyze the output of unwatermarked text versus two forms of adversarial attacks on the MMW-FakeNews dataset. 
For scrubbing, a higher residual $z$-score post-attack indicates stronger watermark retention. For spoofing, a lower $z$-score indicates higher robustness to imitation. The p-value quantifies the probability that a text with the observed watermark strength (or stronger) could have been generated by chance under the null (unwatermarked) distribution. Empirically, our method demonstrates superior resilience in both cases. Under scrubbing attacks, our watermark yields a substantially higher residual $z$-score (7.38) compared to KGW’s (4.82), despite both being attacked under the same conditions. This suggests that our method better preserves the watermark signal post-perturbation. Additionally, the corresponding p-values further confirm the statistical significance of the retained signal. In the spoofing setting, the attacker on KGW achieves a high $z$-score of 11.09, indicating a successful watermark fabrication. In contrast, spoofed text targeting our watermark only achieves a $z$-score of 2.29, substantially closer to the null distribution. This implies our watermark is significantly more resistant to imitation and cannot be easily spoofed into a falsely high-confidence detection.

