\subsection{Proofs for Section \ref{sec:determ Lagrange}}
We now provide the intermediate results that we need to prove Theorem \ref{th:bound $\sens$-sensitive discount factor - deterministic}.
In what follows, we denote by $H(P)$ the height of the polynomial $P=\sum^{d}_{k=0} c_k x^k$ defined as $H(P) \coloneqq  \max_{k \in \{ 0, \ldots , d\}} | c_k |$. 
\begin{lemma}\label{lemmaTechnical2} 
Let $P =\sum^{d}_{k=0} c_k x^k$ be a polynomial with integer coefficients and $Q(y)=\sum^{d}_{k=0} c'_k y^k$ be the polynomial which is obtained making the change of variable $x = 1 - y$ in $P(x)$. Suppose that, %$c'_0 = \ldots = c'_{j-1} = 0$ and $c'_j \neq 0$ for some $j \geq 1$. 
for some $j\in \{0, \ldots , d\}$, we have $c'_j \neq 0$ and $c'_i = 0$ for all $i < j$. 
Then, the polynomial $Q(y)$ has no zeros in the interval $]0 , \frac{1}{2 H(P){d+1\choose j+2}}[$.
\end{lemma}

\begin{proof}
We first bound the magnitude of the coefficients of $Q$ in terms of $H(P)$. Since $Q(y) = P(1-y)$, we have $c'_i = (-1)^i \sum_{k=i}^d c_k {k\choose i}$ for $i \in \{0, \ldots , d\}$. Now we use $\sum_{k=i}^d {k \choose i} = {d+1 \choose i+1} $ to obtain that $|c'_i| \leq H(P) {d+1 \choose i+1}$ for all $i \in \{0, \ldots , d\}$.

Note that $|c'_j|\geq 1$ since $c'_j \neq 0$ and $c'_j \in \Z$. %Then, for any $i \in \{ j+1, \ldots , d\}$, we have 
%\begin{equation}\label{eq:intermed eq 0}
%\left(\frac{|c'_{j}|}{|c'_i|}\right)^{\frac{1}{i-j}} \geq \frac{|c'_{j}|^{\frac{1}{i-j}}}{H(P)^\frac{1}{i-j}     {d+1 \choose i+1}^\frac{1}{i-j}}.
   % \geq \frac{1}{H(P) {d +1 \choose j+2}} 
%\end{equation}
Besides, note that for $m \geq 3$ and $j\leq m-1$, we have 
\begin{equation}\label{eq:aux} 
{m \choose i} \leq {m \choose j+1}^{i-j}
\end{equation}
for all $i \in \{j+1, \ldots , m\}$. Indeed, the cases $i = j+1$ and $i = m$ are trivial, so we may assume $j < m -1$ (because $j = m -1$ implies $i = m $). Suppose that ${m \choose i} \leq {m \choose j+1}^{i-j}$ for some $i\leq m-1$. Then,  \begin{align*}
{m \choose i+1} = \frac{m-i}{i+1}{m \choose i}  \leq \frac{m}{2} {m \choose j+1}^{i-j} \leq {m \choose j+1}^{i + 1 -j}\enspace ,
\end{align*}
because $\frac{m}{2} \leq 
\frac{m}{2}\frac{m-1}{j+1}\cdots \frac{m-j+1}{3}\frac{m-j}{1}= \frac{m}{j+1}\frac{m-1}{j}\cdots \frac{m-j+1}{2}\frac{m-j}{1}= {m \choose j+1}$. 

We are now ready to apply the Lagrange bound (\Cref{th:Lagrange}). 
Using \eqref{eq:aux} we get
\[ 
\left(\frac{|c'_{j}|}{|c'_i|}\right)^{\frac{1}{i-j}} \geq  \frac{|c'_{j}|^{\frac{1}{i-j}}}{H(P)^\frac{1}{i-j}     {d+1 \choose i+1}^\frac{1}{i-j}}
   \geq \frac{1}{H(P) {d +1 \choose j+2}} 
 \]
for any $i \in \{ j+1, \ldots , d\}$. %We conclude that $\gamma \geq \frac{1}{2 H(P) {d +1 \choose j+2}}$, which completes the proof. 
The lemma now follows from \Cref{th:Lagrange}.
\end{proof}

Note that the polynomial $\epsilon \mapsto \Delta(1-\epsilon)$ can be rewritten as
\begin{align}\label{DeltaEpsilon}
  \Delta(1-\epsilon)  
  % =   \sum_{k=0}^K a_k (1-\epsilon)^k
   % = \sum_{k=0}^K a_k (\sum_{i=0}^k {k\choose i}(-1)^i\epsilon^i)
   = \sum_{i=0}^K (-1)^i\epsilon^i b_i \enspace 
   % \text{ where } b_i &= \sum_{k=i}^K  a_k {k\choose i}\enspace .
\end{align}
where $b_i = \sum_{k=i}^K  a_k {k\choose i}$. 
Then, the next proposition is a direct consequence of Lemmas~\ref{lemmaTechnical2} and~\ref{lem:degree coeff Delta - deterministic}.

\begin{proposition}\label{prop_threshold_det}
Suppose that $b_0 = \ldots = b_{j-1} = 0$ and $b_j \neq 0$ for some $j \geq 1$ in~\eqref{DeltaEpsilon}. Then, the polynomial $\epsilon \mapsto \Delta(1-\epsilon)$ has no zeros in the interval $]0 , \frac{1}{24 W{K+1\choose j+2}}[$.
\end{proposition} 

\begin{proof}[Proof of \Cref{th:bound $\sens$-sensitive discount factor - deterministic}]
% \todoi{RK: this proof uses the definition of $\sens$-sensitive optimality of the note, which uses $\liminf$ and $\limsup$ for players $\Max $ and $\Min$ respectively. Since that definition differs from the one used here (no distinction between the players is made), one of the two should be chosen.}
% Jgc: I changed the proof here (and in the appendix for the unichain case) to the case of symmetric definition for d-sensitivity
Let $\alpha'$ be such that $1-\frac{1}{24 W{2n\choose {\min \{ \sens+4, n\} }}} < \alpha' < 1$, and let $(\sigma^*,\tau^*)$ be a pair of discount optimal strategies for the discount factor $\alpha'$. To prove the theorem, it is enough to show that $(\sigma^*,\tau^*)$ is a pair of $\sens$-sensitive optimal strategies.

On the contrary, suppose that $(\sigma^*,\tau^*)$ is not a pair of $\sens$-sensitive optimal strategies. Then, either there exist a strategy $\tau$ of player $\Max$ and a state $i$ such that
\begin{equation}\label{Eq1Th1}
\lim_{\alpha\to 1^-} \; (1-\alpha)^{-\sens}(v_i^{\sigma^*, \tau^*} (\alpha) - v_i^{\sigma^*,\tau} (\alpha)) < 0 \; ,
\end{equation}
or there exist a strategy $\sigma$ of player $\Min$ and a state $i$ such that 
\begin{equation}\label{Eq2Th1}
\lim_{\alpha\to 1^-} \; (1-\alpha)^{-\sens}(v_i^{\sigma^*, \tau^*} (\alpha) - v_i^{\sigma,\tau^*} (\alpha)) > 0 \;.
\end{equation}

In the first place, assume that~\eqref{Eq1Th1} holds. Let $d'$ be the smallest value satisfying 
\begin{equation}\label{Eq1Th1-general}
\lim_{\alpha\to 1^-} \; (1-\alpha)^{-\sens'}(v_i^{\sigma^*, \tau^*} (\alpha) - v_i^{\sigma^*,\tau} (\alpha)) < 0 \; .
\end{equation}
By~\eqref{Eq1Th1}, it follows that $d' \leq d$ and that $
\lim_{\alpha\to 1^-} \; (1-\alpha)^{-\sens''}(v_i^{\sigma^*, \tau^*} (\alpha) - v_i^{\sigma^*,\tau} (\alpha)) = 0$ for all $d'' < d'$. 

If for $q \in \N$ we set $\q[q]:=1+\alpha+ \dots + \alpha^{q-1}$,  then the polynomial $\Delta$ defined in~\eqref{eq:def_Delta} satisfies
\begin{equation}\label{eq:property_Delta}
\Delta(\alpha) = (1-\alpha^q)(1-\alpha^{q'}) (v_i^{\sigma, \tau} (\alpha) - v_i^{\sigma',\tau'} (\alpha) ) = (1 -\alpha)^2 \q[q] \q[q'] (v_i^{\sigma, \tau} (\alpha) - v_i^{\sigma',\tau'} (\alpha) )  \; .
\end{equation}
Therefore, for all $\sens''$ we have
    \[
        \lim_{\alpha\to 1^-} \; (1-\alpha)^{-\sens''}(v_i^{\sigma^*, \tau^*} (\alpha) - v_i^{\sigma^*,\tau} (\alpha)) = 0 \iff 
\lim_{\alpha\to 1^-} \; (1-\alpha)^{-(\sens'' +2)} \Delta(\alpha) = 0 \; .
    \]
     We conclude that $b_0=\ldots = b_{\sens'+1}=0$ and $b_{\sens'+2}\neq 0$ if we represent the polynomial $\Delta(1-\epsilon)$ as in~\eqref{DeltaEpsilon}. Thus, by~\eqref{Eq1Th1} and \Cref{prop_threshold_det},  it follows that $v_i^{\sigma^*, \tau^*} (\alpha) - v_i^{\sigma^*,\tau} (\alpha) < 0$ for $1-\frac{1}{24 W{K+1\choose {\sens' + 4}} } < \alpha < 1$, and therefore this remains true for $1-\frac{1}{24 W{2n\choose {\min \{ \sens + 4 , n\}}}} < \alpha < 1$ because $K+1 \leq 2n$ and $\sens' \leq \sens$. Since $1-\frac{1}{24 W{2n\choose {\min \{\sens+4, n\}}}} < \alpha' < 1$, in particular we have $v_i^{\sigma^*, \tau^*} (\alpha') - v_i^{\sigma^*,\tau} (\alpha') < 0$, contradicting the fact that $(\sigma^*,\tau^*)$ is a pair of discount optimal strategies for $\alpha'$.

On the other hand, if~\eqref{Eq2Th1} is satisfied, using symmetric arguments we also arrive to a contradiction. This completes the proof.
\end{proof}

