%The maximum in \Cref{th-dubickas-1} is necessary because for a fixed $\epsilon>0$, the bound in \Cref{th:mahler-1} only applies for algebraic numbers with degree larger than $D_{\epsilon}$. Thus, if a root of $\Delta$ has degree larger than $D_{\epsilon}$, we can apply Theorem \ref{th:mahler-1}, else we apply the Lagrange bound.
\begin{proof}[Proof of \Cref{th-dubickas}]
Given $\epsilon > 0$, let $D_\epsilon$ be the constant provided by \Cref{th:mahler}.
Let $z$ be any real root of the polynomial $\Delta$ different from  $1$, $d$ be its degree and $P =\sum^{d}_{k=0} c_k x^k$ be its minimal polynomial. Since $z$ is a root of $\Delta$, it follows that $P$ divides $\Delta$, and so we have $d \leq 2n -1$ and $M(P) \leq M(\Delta)$ (see Section~1.3 of \cite{cerlienco1987computing}). Besides, note that $M(\Delta)\leq 12W \sqrt{2n}$ by Landau's bound~\cite{Landau1905}.
% \todo{RK: this sentence is critical and needs to be checked.}
If $d > D_\epsilon$, then~\eqref{dubickas} holds, and so we have
\begin{align*}
|z - 1 | & > e^{-(\pi/4 + \epsilon) \sqrt{d \log d  \log M(P)}} \geq e^{-(\pi/4 + \epsilon) \sqrt{(2n-1) \log (2n-1) \log M(\Delta)}} \\
& \geq e^{-(\pi/4 + \epsilon) \sqrt{(2n-1) \log (2n-1)  \log (12 W \sqrt{2n}) }} \; . 
\end{align*}
Assume now that $d \leq D_\epsilon$. By Lemma~\ref{lemmaTechnical2}, it follows that
$|z -1 | \geq \frac{1}{2 H(P) {d+1\choose \lceil \frac{d}{2}\rceil}}$. Then, since $H(P) \leq 2^d M(P)$, we have
\[
|z -1 | \geq \frac{1}{2^{d+1} M(P) {d+1\choose \lceil \frac{d}{2}\rceil }}
\geq \frac{1}{2^{D_\epsilon +1} M(\Delta) {D_\epsilon +1\choose \lceil \frac{D_\epsilon}{2}\rceil }} \geq \frac{1}{2^{D_\epsilon +1} {D_\epsilon +1\choose \lceil \frac{D_\epsilon}{2}\rceil } 12 W \sqrt{2n}} \enspace .
\]
Setting $a_\epsilon = \log\left(2^{D_\epsilon +1} {D_\epsilon +1\choose \lceil \frac{D_\epsilon}{2}\rceil }\right)$,
we conclude that $\Delta$ has no zeros in the interval  $]\alphama^{\sf det}, 1[$. %and so the difference $v_i^{\sigma, \tau} (\alpha) - v_i^{\sigma',\tau'} (\alpha)$ has constant sign in this interval for any pairs of strategies $(\sigma, \tau)$ and $(\sigma', \tau')$. This concludes the proof of Theorem \ref{th-dubickas-1}.
\end{proof}
\section{Proof for \Cref{SectionStochastic}}\label{app:proof stochastic}
\subsection{Proof of \Cref{prop:bound on Delta - stochastic}}
We now detail the proof of \Cref{prop:bound on Delta - stochastic}. 

We first provide the exact formula for the polynomial $\Delta(\alpha)$ considered in \Cref{SectionStochastic}.  Given a pair of stationary strategies $(\sigma,\tau)$, let $P^{\sigma,\tau} $ be the transition matrix and $r^{\sigma,\tau}$ be the vector of instantaneous rewards induced by $(\sigma,\tau)$, and let us define $Q^{\sigma,\tau} \coloneq M P^{\sigma,\tau}$ and $D^{\sigma,\tau}(\alpha) \coloneq \det \left(M I - \alpha Q^{\sigma,\tau}\right)$. Since it is known that $\left(v^{\sigma,\tau}_{i}(\alpha)\right)_{i \in [n]} = \left(I - \alpha P^{\sigma,\tau}\right)^{-1}r^{\sigma,\tau}$, using Cramer's formula for the inverse of a matrix and Laplace's cofactor extension, it follows that $v^{\sigma,\tau}_{i}(\alpha) - v^{\sigma',\tau'}_{i}(\alpha) = \frac{M \Delta(\alpha)}{D^{\sigma,\tau}(\alpha)D^{\sigma',\tau'}(\alpha)}$ for any state $i$, where
\begin{equation}\label{eq:def_Delta_stoch}
\Delta(\alpha) \coloneq  D^{\sigma',\tau'} (\alpha)(\sum_{j=1}^{n} \cof_{ji} (M I - \alpha Q^{\sigma,\tau}) r_j^{\sigma,\tau} ) 
 -  D^{\sigma,\tau}(\alpha) (\sum_{j=1}^{n} \cof_{ji} (M I - \alpha Q^{\sigma',\tau'}) r_j^{\sigma',\tau'}) . %\label{DeltaP} 
\end{equation}

We now proceed to bound the degree and the coefficients of $\Delta$. In the next two propositions, we assume that $\frac{Q}{M}$ is a row-stochastic matrix, with $Q \in \N^{n \times n}$. 
\begin{proposition}\label{Prop_det_stoch_bound}
The polynomial $\det (M I - \alpha Q)$ is of the form $\sum_{k=0}^n a_k \alpha^k$, where $|a_k| \leq {n \choose k} M^n$. 
\end{proposition}

\begin{proof}
We have 
\begin{equation}\label{det_stoch_bound}
\det (M I - \alpha Q) = \sum_{k=0}^n (-\alpha)^k M^{n - k} \tr (\comp_k (Q)) \enspace ,
\end{equation}
where $\comp_k (Q)$ is the $k$-th compound matrix of $Q$. Since the entries of $\comp_k (Q)$ are minors of $Q$ of size $k \times k$, and $\sum_{j=1}^n Q_{ij} = M$ for each $i= 1,\ldots ,n$, we conclude that the absolute value of all the entries of $\comp_k (Q)$ are less than or equal to $M^k$. The result now follows from~\eqref{det_stoch_bound} and the fact that $\comp_k (Q)$ is of size ${n \choose k} \times {n \choose k}$.
\end{proof}
It is worth noting that the result in the previous proposition is tight when $Q = M I$.
\begin{proposition}\label{Prop_cofactor_bound}
For each $i,j \in \{1, \ldots , n\}$, the $(i,j)$ cofactor of the matrix $M I - \alpha Q$ is of the form $\sum_{k=0}^{n-1} a_k \alpha^k$, where $|a_k| \leq {n-1 \choose k} M^{n-1}$. 
\end{proposition}

\begin{proof}
The $(i,j)$ cofactor of the matrix $M I - \alpha Q$ is given by
\begin{equation}\label{cofactor_stoch_bound}
(-1)^{i+j} \det (M J - \alpha R) = (-1)^{i+j} \sum_{k=0}^{n-1} (-\alpha)^k  M^{n - 1 - k}  \tr ((\adj_k (J)) (\comp_k (R))) \enspace ,
\end{equation}
where $J$ and $R$ are the $(i,j)$ sub-matrices of $I$ and $Q$ respectively, $\adj_k (J)$ is the $k$-th higher adjugate matrix of $J$, and $\comp_k (R)$ is the $k$-th compound matrix of $R$. Since $\adj_k (J)$ has just one non-zero entry per row, of absolute value one, as in the proof of Proposition~\ref{Prop_det_stoch_bound} we conclude that the absolute value of all the entries of $(\adj_k (J))(\comp_k (R))$ are less than or equal to $M^k$. The result now follows from~\eqref{cofactor_stoch_bound} and the fact that $(\adj_k (J)) (\comp_k (R))$ is of size ${n-1 \choose k} \times {n-1 \choose k}$.
\end{proof}

By Propositions~\ref{Prop_det_stoch_bound} and~\ref{Prop_cofactor_bound}, both terms appearing in the polynomial $\Delta$ defined in \eqref{eq:def_Delta_stoch} are of the form $\sum_{k=0}^{2n-1} b_k \alpha^k$, where
% \todo{RK : In comparison to the notes, the bound that I obtain here has a factor $n$ instead of $n-1$.} 
\begin{align*}
|b_k| & \leq n W M^{2n-1} \left(\sum_{s+l=k,s\leq n-1,l\leq n} {n-1 \choose s} {n \choose l}\right)\\ 
& = n W M^{2n-1} \left(\sum_{0 \leq k-l\leq n-1,l\leq n} {n -1 \choose k-l} {n \choose l}\right)\\ 
& \leq n W M^{2n-1} \left(\sum_{l=0}^{k} {n -1 \choose k-l} {n \choose l}\right) = n W M^{2n-1} {2n - 1 \choose k} \enspace ,
\end{align*}
by Vandermonde's Identity. Therefore, we can rewrite $\Delta$ as $\sum_{k=0}^{2n - 1} c_k \alpha^k$, where $|c_k| \leq 2 n W M^{2n-1} {2n - 1 \choose k}$. This concludes the proof of \Cref{prop:bound on Delta - stochastic}.
