\subsection{Other proofs for Section \ref{SectionStochastic}}

To use the Lagrange bound, we consider the polynomial $\epsilon \mapsto \Delta(1-\epsilon)$, which can be rewritten as
\begin{equation}\label{eq:bound_gi}
\Delta(1-\epsilon) = \sum_{i=0}^{2n-1} (-1)^i\epsilon^i g_i 
\end{equation}
where $g_i = \sum_{k=i}^{2n-1} c_k {k\choose i}$. Then,  using \Cref{prop:bound on Delta - stochastic} and the identity $\sum_{k=q}^{m} {m\choose k} {k\choose q}= 2^{m-q}{m\choose q}$, we have 
\begin{equation}\label{boundg}
|g_i| \leq \sum_{k=i}^{2n-1} 2 n W M^{2n-1} {2n - 1 \choose k} {k\choose i} 
%\leq 2n W M^{2n-1} \sum_{k=i}^{2n} {2n \choose k} {k\choose i} 
=  n W (2M)^{2n-1} 2^{1-i}{2n-1\choose i}
\end{equation}
for all $i \in \{0,\ldots ,2n-1\}$.

\begin{proposition}\label{prop_threshold_sto}
% \todo{RK: please check}
Let $j$ be the smallest index such that $g_j \neq 0$ in~\eqref{eq:bound_gi}. Then, the polynomial $\epsilon \mapsto \Delta(1-\epsilon)$ has no zeros in the interval $]0 ,\frac{2^{j-1}}{nW (2M)^{2n-1} {2n-1 \choose j+1}}[$.
\end{proposition}

\begin{proof}%[Proof of Proposition \ref{prop_threshold_sto}]
As in the proof of \Cref{lemmaTechnical2}, we apply the Lagrange bound (\Cref{th:Lagrange}). 
Note that $|g_j|\geq 1$ since $g_j \neq 0$ and $g_j \in \Z$. 
Then, for any $i\in \{ j+1, \ldots , 2n-1\}$, we have 
  \begin{align*}
   \left(\frac{|g_{j}|}{|g_i|}\right)^{\frac{1}{i-j}} &\geq \frac{|g_{j}|^{\frac{1}{i-j}}}{(nW (2M)^{2n-1}2^{1-i})^\frac{1}{i-j}
     {2n-1 \choose i}^\frac{1}{i-j}}
   \geq \frac{2^{i-1}}{nW (2M)^{2n-1} {2n-1 \choose j+1}} % \\ &\geq \frac{2^{j}}{nW (2M)^{2n-1} {2n-1 \choose j+1}} 
 \end{align*}
by~\eqref{boundg} and~\eqref{eq:aux}. 
The proposition now follows from \Cref{th:Lagrange}.
\end{proof}

\begin{proof}[Proof of \Cref{coro:bound blackwell factor - stochastic}]
Note that the function $j \mapsto \frac{2^{j-1}}{nW (2M)^{2n-1} {2n-1 \choose j+1}}$ is convex and attains its minimum at $j = \lfloor \frac{2}{3} n - 1 \rfloor$. Then, by \Cref{prop_threshold_sto}, we conclude that 
no function $\alpha \mapsto v^{\sigma,\tau}_{i}(\alpha) - v^{\sigma',\tau'}_{i}(\alpha)$ has zeros in the interval $]1-\frac{2^{\lfloor \frac{2}{3} n \rfloor-2}}{nW (2M)^{2n-1} {2n-1 \choose \lfloor \frac{2}{3} n \rfloor}}, 1[$. The corollary now follows from the discussion in \Cref{sec:stochastic games}.
\end{proof}

\begin{proof}[Proof of \Cref{th:bound $\sens$-sensitive discount factor - stochastic}]
Let $(\sigma^*,\tau^*)$ be a pair of discount optimal strategies for the discount factor
$\alpha'$, where $\alpha'$ satisfies $1-\frac{2^{\min \{ \sens+2 , \lfloor \frac{2}{3} n - 1 \rfloor \} - 1}}{nW (2M)^{2n-1} {2n-1 \choose \min \{ \sens+2 , \lfloor \frac{2}{3} n - 1 \rfloor \} + 1}} < \alpha' < 1$. 

As in the proof for the deterministic case, in the first place assume that there exist a strategy $\tau$ and a state $i$ such that~\eqref{Eq1Th1} is satisfied, and let $d'$ be the smallest value satisfying~\eqref{Eq1Th1-general}. %$\lim_{\alpha\to 1^-} \; (1-\alpha)^{-\sens'}(v_i^{\sigma^*, \tau^*} (\alpha) - v_i^{\sigma^*,\tau} (\alpha)) < 0$. 
By~\eqref{Eq1Th1}, it follows that $d' \leq d$ and that $
\lim_{\alpha\to 1^-} \; (1-\alpha)^{-\sens''}(v_i^{\sigma^*, \tau^*} (\alpha) - v_i^{\sigma^*,\tau} (\alpha)) = 0$ for all $d'' < d'$. 

If the game is unichain, there exist two polynomials $p(\alpha)$ and $q(\alpha)$ such that $p(1)\neq 0$, $q(1)\neq 0$ and $\Delta(\alpha) = (1-\alpha)^2 
 p(\alpha) q(\alpha) (v_i^{\sigma^*, \tau^*} (\alpha) - v_i^{\sigma^*,\tau} (\alpha)) $,
 % \todo{RK: should we justify this?}
 where $\Delta$ is the polynomial defined in \eqref{eq:def_Delta_stoch} considering the pairs of strategies $(\sigma^*, \tau^*)$ and $(\sigma^*, \tau)$. Then, we have
    \[
        \lim_{\alpha\to 1^-} \; (1-\alpha)^{-\sens''}(v_i^{\sigma^*, \tau^*} (\alpha) - v_i^{\sigma^*,\tau} (\alpha)) = 0 \iff 
\lim_{\alpha\to 1^-} \; (1-\alpha)^{-(\sens'' +2)} \Delta (\alpha)= 0 
    \]
for all $\sens''$. 
We conclude that $g_0=\ldots = g_{\sens'+1}=0$ and $g_{\sens'+2}\neq 0$ in~\eqref{eq:bound_gi}. Thus, by~\eqref{Eq1Th1} and \Cref{prop_threshold_sto}, it follows that $v_i^{\sigma^*, \tau^*} (\alpha) - v_i^{\sigma^*,\tau} (\alpha) < 0$ for $1-\frac{2^{\sens'+1}}{nW (2M)^{2n-1} {2n-1 \choose \sens'+3}} < \alpha < 1$. Since the function $j \mapsto \frac{2^{j-1}}{nW (2M)^{2n-1} {2n-1 \choose j+1}}$ is convex and attains its minimum at $j = \lfloor \frac{2}{3} n - 1 \rfloor$, and $\sens' \leq \sens$, we conclude that $v_i^{\sigma^*, \tau^*} (\alpha) - v_i^{\sigma^*,\tau} (\alpha) < 0$ for $1-\frac{2^{\min \{ \sens+2 , \lfloor \frac{2}{3} n - 1 \rfloor \} - 1}}{nW (2M)^{2n-1} {2n-1 \choose \min \{ \sens+2 , \lfloor \frac{2}{3} n - 1 \rfloor \} + 1}} < \alpha < 1$. Thus, in particular we have $v_i^{\sigma^*, \tau^*} (\alpha') - v_i^{\sigma^*,\tau} (\alpha') < 0$, contradicting the fact that $(\sigma^*,\tau^*)$ is a pair of discount optimal strategies for $\alpha'$.

Now, if we assume that there exist a strategy $\sigma$ and a state $i$ such that~\eqref{Eq2Th1} is satisfied, using similar arguments as above we arrive at a contradiction. 

This shows that $(\sigma^*,\tau^*)$ is a pair of $\sens $-sensitive discount optimal strategies.
    \end{proof}

\begin{remark}
Setting $M=1$ in our bounds for the stochastic case do not recover our results for the deterministic case (\Cref{SectionDeterm}). This is because, in the case of deterministic transitions, we can exploit the ``path then circuit structure" of the discounted value functions, as highlighted in \Cref{SectionDeterm}.
\end{remark}    
