\subsection{Transformation to optimal control}\label{Sec:transform_to_control}

Before we further analyze \eqref{hjbp2}, let us first consider the following general stochastic control problem \begin{equation}\label{pp1}
	v(s,x)=\max_{u\in\setu} J(s,x; u),
\end{equation}
where the controlled $n$-dimensional process $X_t$ follows
\begin{equation}\label{xpp1a}
	\dd X_t=\tilde b(t, X_t, u_{t})\dt+\tilde \sigma(t,X_t, u_{t})\dw_t,
\end{equation}
and the objective functional (also called the reward function in the RL literature) is defined as
\begin{equation*}
	J(s,x;u)=\BE{\int_s^{T} e^{-\int_{s}^{t}f(r, X_{r}, u_{r})\dr}G(t, X_t, u_{t})\dt
		+e^{-\int_{s}^{T}f(r, X_{r}, u_{r})\dr}H(X_T)\;\bigg|\; X_s=x}.
\end{equation*}
Here $\setu$ denotes the set of admissible controls $u:[0,T]\times \Omega\to U$ which are progressively measurable such that \eqref{xpp1a} admits a unique strong solution and $J(s,x;u)$ is finite, while $U\subseteq\R^{m}$ is a given closed control constraint set.

%For simplicity, we assume the drift $b$ and volatility $\sigma$ satisfy the standard assumption in \cite{YZ99}.
%Then we have the following Theorem \ref{vf} regarding the value function $v(s,x)$.

Note that this is not a conventional stochastic control problem (e.g., \citealp{YZ99}) as it involves control-dependent discount factors. However, we still have the following HJB equation and verification theorem.

\begin{thm}[Verification theorem]\label{vf}
	Suppose $v$ is a classical solution of
	\begin{equation}\label{hjbpp1}
		\begin{cases}
			v_{t}+\max_{u\in U}\left\{\opla_{u} v-vf+G\right\}=0, ~~ (t,x)\in[0,T)\times\R^{n},\\
			v(T,x)=H(x),
		\end{cases}
	\end{equation}
	where $$\opla_{u} v=\frac{1}{2}\sum_{i,j,k}\tilde\sigma_{i,k}(t,x,u)\tilde\sigma_{j,k}(t,x,u)\frac{\partial^2v }{\partial x_{i}\partial x_{j}}
	+\sum_{i} \tilde b_{i}(t,x,u)\frac{\partial v}{\partial x_{i}}.$$
	%	\begin{align*}
		%		\opla_{u} v=\frac{1}{2}\sum_{i,j,k}\sigma_{i,k}(t,x,u)\sigma_{j,k}(t,x,u)\frac{\partial^2v }{\partial x_{i}\partial x_{j}}
		%		+\sum_{i} b_{i}(t,x,u)\frac{\partial v}{\partial x_{i}}.
		%	\end{align*}
	Then it is the value function of problem \eqref{pp1}.
\end{thm}


\begin{remark}
	If $f$ is a constant, then the above result reduces to the classical verification theorem.
	One can indeed establish a similar result when a term like $e^{-\int_{s}^{t}f(r, X_{r}, u_{r})\dr-\int_{s}^{t}g(r, X_{r}, u_{r})\dd W_r}$
	is in place of
	$e^{-\int_{s}^{t}f(r, X_{r}, u_{r})\dr}$
	in the reward functional $J$.
	%	One can establish a similar result when \[e^{-\int_{s}^{t}f(r, X_{r}, u_{r})\dr-\int_{s}^{t}g(r, X_{r}, u_{r})\dd W_r}\]
	%	is in place of
	%	\[e^{-\int_{s}^{t}f(r, X_{r}, u_{r})\dr}\]
	%	in the cost/reward functional $J$.
\end{remark}


By \citethm{vf}, the PDE \eqref{hjbp2} is indeed the HJB equation of the following stochastic control problem:
\begin{equation}\label{p2}
	v(s,x)=\max_{u_{t}\in\{0,1\}} J(s,x;u),
\end{equation}
where the (uncontrolled) process $X_t$ is driven by \eqref{process1} and
\begin{equation}\label{value_func_control}
	J(s,x;u)=\BE{\int_s^{T} Ke^{-K\int_{s}^{t}u_{r}\dr}g(t,X_t)u_{t}\dt
		+e^{-K\int_{s}^{T}u_{r}\dr}g(T,X_T)\;\bigg|\; X_s=x}.
\end{equation}

%Taking $f(t,x,u)=Ku$, $G(t,x,u)=Kg(t,x)u$ and $H(x)=g(T,x)$ into \citethm{vf} yields the following lemma.
Applying \citethm{vf} yields
\begin{lemma} \label{lemma_control}
	Suppose $v$ is a classical solution of \eqref{hjbp2} with terminal condition $v(T,x)=g(T,x)$. Then it is the value function of problem \eqref{p2}.
\end{lemma}



