	%		%&\approx \frac{1}{2}\mathbb{E}\left[\sum_{l=0}^{L-1}\left(R_{T}g(T,X_T) - R_{t_l} V_{\theta_l}(X_{t_l})+\int_{t_l}^{T} R_{s}\big[Kg(s,X_s)\pi_{s}- \lam \BH(\pi_{s})\big]\ds\right)^2\Delta t\right]\\
	%		&\approx \frac{1}{2}\mathbb{E}\left[\sum_{l=0}^{L-1}\left(R_{T}g(T,X_T) - R_{t_l} V_{\theta_l}(X_{t_l})+\sum_{j=l}^{L-1} R_{t_j}\big[Kg(t_j,X_{t_j})\pi_{t_j}- \lam \BH(\pi_{t_j})\big]\Delta t\right)^2\Delta t\right]\\
	%		&=:\frac{1}{2}\mathbb{E}\bigg[ \sum_{l=0}^{L-1}G_l^2 \Delta t\bigg],
	%	\end{aligned}
%\end{equation}
\begin{equation}
	\begin{aligned}\label{martingale_loss}
		\text{ML}\left(\left\{\theta_l\right\}_{l=0}^{L-1}\right)
		&=\frac{1}{2}\mathbb{E}\left[\int_0^T|\mathcal{M}_T-\mathcal{M}_t|^2dt\right]
		\approx:\frac{1}{2}\mathbb{E}\bigg[ \sum_{l=0}^{L-1}G_l^2 \Delta t\bigg],
	\end{aligned}
\end{equation}
where
\begin{equation}
	G_l=R_{T}g(T,X_T) - R_{t_l} V_{\theta_l}(X_{t_l})+\sum_{j=l}^{L-1} R_{t_j}\big[Kg(t_j,X_{t_j})\pi_{t_j}- \lam \BH(\pi_{t_j})\big]\Delta t. \label{ML_component}
\end{equation}
For states at discretized time points, we adopt the forward Euler scheme as follows,
\begin{equation}
	X_{t_{l+1}}=X_{t_l}+b(t_l,X_{t_l})\Delta t+\sigma(t_l,X_{t_l})\Delta W\quad \text{with } \Delta W\sim\mathcal{N}(0,\Delta t),\label{discrete X}
\end{equation}
and
\begin{equation}
	R_{t_{l+1}}=R_{t_l}\left(1-K\pi_{t_l}\Delta t\right)\quad \text{for }l=0,\ldots,L-1.\label{discrete R}
\end{equation}
%\begin{align*}
%	R_{t_l}=R_0e^{-K\sum_{i=0}^{l-1}\pi_{t_i}\Delta t}\quad \text{for }l=0,\ldots,L-1,
%\end{align*}

It is obvious that to minimize the martingale loss, the state trajectories in the whole time horizon are required, which leads to the
offline RL Algorithm \ref{algorithm_ML}.
During training, as long as we can collect the realized outcomes of the payoff function $g$, referred to  as the {\it reward signals}  from the environment, the algorithm is applicable even if we do not know the functional form of $g$.\footnote{In some situations, we may also be able to learn  $g$ through parameterizations. For instance, in the next section we will show that when $g$ is the payoff function corresponding to the early exercise premium of an American put option, whose exact value is dependent on the unknown market volatility, an accurate approximation of $g$ is available upon training by the martingale approach.}
