For online learning, we apply the martingale orthogonality condition $\mathbb{E}\left[\int_0^T\xi_t \text{d} \mathcal{M}_t\right]=0$
for any test function $\xi\in L_{\mathcal{F}}^2\left([0,T],\mathcal{M}\right)$, again proposed by \cite{jia2022policy}, where
%$\left(\Omega, \mathcal{F}, \{\mathcal{F}_t\}_{t\geq 0}, \mathbb{P}\right)$ is the filtered probability space and
%$L_{\mathcal{F}}^2\left([0,T],M\right):=\left\{\kappa: \kappa \text{ is $\mathcal{F}_t$-progressively measurable and } \mathbb{E}\int_0^T |\kappa_t|^2 \text{d} \langle M\rangle_t < \infty \right\}$,
\begin{eqnarray*}
&& L_{\mathcal{F}}^2\left([0,T],\mathcal{M}\right)\\
&:=&\left\{\kappa=\left\{\kappa_t, 0\leq t\leq T\right\}: \kappa \text{ is $\mathcal{F}_t$-progressively measurable and } \mathbb{E}\int_0^T |\kappa_t|^2 \text{d} \langle \mathcal{M}\rangle_t < \infty \right\}.
\end{eqnarray*}
%\begin{center}
%	$L_{\mathcal{F}}^2\left([0,T],M\right):=\left\{\kappa: \kappa \text{ is $\mathcal{F}_t$-progressively measurable and } \mathbb{E}\int_0^T |\kappa_t|^2 \text{d} \langle M\rangle_t < \infty \right\}$,
%\end{center}
In particular, a TD(0)-type algorithm results  from choosing $\xi_t=\frac{\partial \barJ^{\pi}(t, X_t, R_t)}{\partial \theta}$. The corresponding online updating rule is
$$\theta \leftarrow \theta+\alpha \frac{\partial \barJ^{\pi}(t, X_t, R_t)}{\partial \theta} \text{d}\mathcal{M}_t,$$
where $\alpha$ is the learning rate.
%\begin{align*}
%	\theta \leftarrow \theta+\alpha \frac{\partial \barJ^{\pi}(t, X_t, R_t)}{\partial \theta} \dM_t.
%\end{align*}
For actual implementation where time is discretized, we have at time $t_l$:
\begin{equation*}
	\begin{aligned}
		&\quad \frac{\partial \barJ^{\pi}(t_l, X_{t_l}, R_{t_l})}{\partial \theta_l} \text{d} \mathcal{M}_{t_l} \\
		&\approx\frac{\partial \left(R_{t_l}V_{\theta_l}(X_{t_l})\right)}{\partial \theta_l} \left\{R_{t_{l+1}}V_{\theta_{l+1}}(X_{t_{l+1}}) - R_{t_l}V_{\theta_l}(X_{t_l})+R_{t_l}\left[Kg\left(t_l,X_{t_l}\right)\pi_{t_l}-\lambda\BH(\pi_{t_l})\right]\Delta t\right\}\\
		& \propto \frac{\partial V_{\theta_l}(X_{t_l})}{\partial \theta_l}\left\{\frac{R_{t_{l+1}}}{R_{t_l}}V_{\theta_{l+1}}(X_{t_{l+1}}) - V_{\theta_l}(X_{t_l})+
		\left[Kg(t_l,X_{t_l})\pi_{t_l} - \lambda \BH(\pi_{t_l})\right]\Delta t \right\}.
	\end{aligned}
\end{equation*}
Consequently, the updating rule in our online algorithm is
\begin{equation}\label{update_TD0}
	\theta_l \leftarrow \theta_l+\alpha \frac{\partial V_{\theta_l}(X_{t_l})}{\partial \theta_l}\left\{\frac{R_{t_{l+1}}}{R_{t_l}}V_{\theta_{l+1}}(X_{t_{l+1}}) - V_{\theta_l}(X_{t_l})+
	\left[Kg(t_l,X_{t_l})\pi_{t_l} - \lambda \BH(\pi_{t_l})\right]\Delta t\right\}
\end{equation}
for $l=0,\ldots,L-1$.
Algorithm \ref{algorithm_TD0} presents the online learning procedure.
%\red{Letter $M$ is used to present the martingle alreay. we may need to use another letter in the below algorithms.}

\begin{algorithm}\label{algorithm_ML}
	\caption{Offline ML}
	\textbf{Inputs:} initial states $x_0$ and $r_0=1$, penalty factor $K$, time horizon $T$, time step $\Delta t$, number of time intervals $L$, training batch size $M$, number of training steps $N$, learning rate $\alpha$, temperature parameter $\lambda$ and a good representation of the payoff function $g(\cdot,\cdot)$.\\
	\textbf{Learning procedure:}\\
	Initialize the neural networks $V_{\theta_l}(\cdot)$ for $l=0,\ldots,L-1$.\\
	\For{$n=1,\dots,N$}{
		Generate $M$ state trajectories of $\left\{X_{t_l}\right\}_{l=0}^L$ with $X_0=x_0$ by \eqref{discrete X}.\\
		Calculate the strategy $\left\{\pi\left(t_l,X_{t_l}\right)\right\}_{l=0}^L$ according to $\pi\left(t_l,X_{t_l}\right)=\frac{1}{1+\exp\left(\frac{K}{\lambda}\left(V_{\theta_l}(X_{t_l})-g(t_l,X_{t_l})\right)\right)}$.\\
		%		\begin{align*}
			%			\pi\left(t_l,X_{t_l}\right)=\frac{1}{1+\exp\left(\frac{K}{\lambda}\left(V_{\theta_l}(X_{t_l})-g(t_l,X_{t_l})\right)\right)}.
			%		\end{align*}\\
		Generate $M$ state trajectories of $\left\{R_{t_l}\right\}_{l=0}^L$ with $R_0=r_0$ by \eqref{discrete R}.\\

		Calculate the martingale loss \eqref{martingale_loss}.\\
		Update $\left\{\theta_l\right\}_{l=0}^{L-1}$ by taking one step stochastic gradient descent with respect to the martingale loss with learning rate $\alpha$.\\		
		%		Update $\theta$ and $\psi$ by
		%		\begin{align*}
			%			\theta & \leftarrow \theta+l(j)\alpha_{\theta}\sum_{n=0}^{N-1} \frac{\partial J^{\theta}}{\partial \theta}(t_n, x_{t_n}, r_{t_n}) G_{t_n:T} \Delta t, \\
			%			\psi & \leftarrow \psi+l(j)\alpha_{\psi}\sum_{n=0}^{N-1}
			%			\left[\sum_{i=n}^{N-1}e^{-\rho\Delta t}\frac{\partial q^{\psi}}{\partial \psi}(t_i, x_{t_i}, r_{t_i}, u_{t_i}) \Delta t\right] G_{t_n:T} \Delta t.
			%		\end{align*}
	}
\end{algorithm}
%\vspace{-120pt}
\begin{algorithm}\label{algorithm_TD0}
	\caption{Online TD(0)}
	\textbf{Inputs:} initial states $x_0$ and $r_0=1$, penalty factor $K$, time horizon $T$, time step $\Delta t$, number of time intervals $L$, training batch size $M$, number of training steps $N$, learning rate $\alpha$, temperature parameter $\lambda$ and a good representation of the payoff function $g(\cdot,\cdot)$.\\
	\textbf{Learning procedure:}\\
	Initialize the neural networks $V_{\theta_l}(\cdot)$ for $l=0,\ldots,L-1$.\\
	\For{$n=1,\dots,N$}{
		Generate $M$ state trajectories with the identical initial states $X_0=x_0$ and $R_0=r_0$.\\
		\For{$l=0,\dots,L-1$}{
			Generate $X_{t_{l+1}}$ by \eqref{discrete X} for all $M$ state trajectories.\\
			Calculate the strategy $\pi\left(t_l,X_{t_l}\right)$ according to $\pi\left(t_l,X_{t_l}\right)=\frac{1}{1+\exp\left(\frac{K}{\lambda}\left(V_{\theta_l}(X_{t_l})-g(t_l,X_{t_l})\right)\right)}$.\\
			%			\begin{align*}
				%				\pi\left(t_l,X_{t_l}\right)=\frac{1}{1+\exp\left(\frac{K}{\lambda}\left(V_{\theta_l}(X_{t_l})-g(t_l,X_{t_l})\right)\right)}.
				%			\end{align*}\\
			Generate $R_{t_{l+1}}$ by \eqref{discrete R} for all $M$ state trajectories.\\	
			Update $\theta_l$ by stochastic approximation \eqref{update_TD0} with learning rate $\alpha$.\\
			%			\begin{align}
				%				\theta_l \leftarrow \theta_l+\alpha \frac{\partial V_{\theta_l}(X_{t_l})}{\partial \theta_l}\Bigg\{\frac{R_{t_{l+1}}}{R_{t_l}}V_{\theta_{l+1}}(X_{t_{l+1}}) - V_{\theta_l}(X_{t_l})+\nn\\
