		}		
	}
\end{algorithm}





\section{Simulation studies: American put options}\label{Sec:Simulation}


In this section, we present simulation experiments in which an RL agent learns how to exercise finite-horizon American put options. % and simultaneously calculate the option price through simulations.
%At the end of this section, we will also learn a more complicated example, that is, Merton's problem with transaction costs.
A put option can be formulated as the following optimal stopping problem under the risk-neutral measure
\begin{equation}\label{put}
	\max_{\tau\in[0,T]} \BE{ e^{-\rho\tau} \left(\Gamma-X_{\tau}\right)^+},
\end{equation}
where the stock price follows a one-dimensional geometric Brownian motion:
$	\dd X_t=\rho X_t\dt+\sigma X_t \dw_t$
with $\rho$ being the risk-free rate and $\sigma$ being the volatility of the stock price, and the (time-invariant) payoff function is
%\begin{align}
%	g(x)=\left(\Gamma-x\right)^+
%\end{align}
$	g(x)=\left(\Gamma-x\right)^+$
with $\Gamma$ being the strike price.
In the RL setting, only the volatility $\sigma$ is unknown to the agent.

Due to the presence of the exponential time discounting in the objective function, \eqref{ML_component} and \eqref{update_TD0} in Algorithm \ref{algorithm_ML} and \ref{algorithm_TD0} need to be respectively modified to (refer to Section 5.1 in \citealp{jia2022policy})
%\begin{center}
%	$G_l=e^{-\rho T}R_{T}g(X_T) - e^{-\rho t_l}R_{t_l} V_{\theta_l}(X_{t_l})+\sum_{j=l}^{L-1} e^{-\rho t_j} R_{t_j}\big[Kg(X_{t_j})\pi_{t_j}- \lam \BH(\pi_{t_j})\big]\Delta t,$
%\end{center}
\begin{equation*}
	G_l=e^{-\rho T}R_{T}g(X_T) - e^{-\rho t_l}R_{t_l} V_{\theta_l}(X_{t_l})+\sum_{j=l}^{L-1} e^{-\rho t_j} R_{t_j}\big[Kg(X_{t_j})\pi_{t_j}- \lam \BH(\pi_{t_j})\big]\Delta t,
\end{equation*}
and
%\begin{center}
%	$\theta_l \leftarrow \theta_l+\alpha \frac{\partial V_{\theta_l}(X_{t_l})}{\partial \theta_l}\Big\{\frac{R_{t_{l+1}}}{R_{t_l}}V_{\theta_{l+1}}(X_{t_{l+1}}) - V_{\theta_l}(X_{t_l})+
%	\left[Kg(X_{t_l})\pi_{t_l} - \lambda \BH(\pi_{t_l})\right]\Delta t-\rho V_{\theta_l}(X_{t_l})\Big\}.$
%\end{center}
\begin{equation*}
	\theta_l \leftarrow \theta_l+\alpha \frac{\partial V_{\theta_l}(X_{t_l})}{\partial \theta_l}\left\{\frac{R_{t_{l+1}}}{R_{t_l}}V_{\theta_{l+1}}(X_{t_{l+1}}) - V_{\theta_l}(X_{t_l})+
	\left[Kg(X_{t_l})\pi_{t_l} - \lambda \BH(\pi_{t_l})\right]\Delta t-\rho V_{\theta_l}(X_{t_l})\right\}.
\end{equation*}

In our experiments, we use the same parameters as in \cite{becker2021solving} and \cite{dong2023randomized} for the simulator, i.e., the initial stock price $x_0=40$, strike price $\Gamma=40$, risk-free rate $\rho=0.06$, volatility $\sigma=0.4$ (but unknown to the agent), and maturity time $T=1$.
