%\[\overline{R}_{t}=e^{-\int_{s}^{t}f(r, X_{r}, u_{r})\dr}, \quad t\geq s,\]
%then
%\begin{align*}%\label{processR}
%	\dd \overline{R}_{t}=-\overline{R}_{t}f(t, X_{t}, u_{t})\dt, \quad \overline{R}_{s}=1.
%\end{align*}
It\^{o}'s lemma gives
\begin{equation*}
	\begin{aligned}
		&\quad\;\dd\; (\overline{R}_{t}v(t,X_{t})) \\
		&=\overline{R}_{t}\dd v(t,X_{t})+v(t,X_{t}) \dd \overline{R}_{t}\\
		&=\overline{R}_{t}\big[\left(v_{t}(t,X_t)+\opla_{u} v(t,X_t)\right)\dt+v_x(t,X_t)\sigma(t,X_t, u_{t})\dd W_{t}\big]-v(t,X_{t}) \overline{R}_{t} f(t, X_{t}, u_{t})\dt\\
		&=\overline{R}_{t}\big[\left(v_{t}(t,X_t)+\opla_{u} v(t,X_t)-v(t,X_t)f(t, X_{t}, u_{t})\right)\dt+v_x(t,X_t)\sigma(t,X_t, u_{t})\dd W_{t}\big]\\
		&\leq -\overline{R}_{t} G(t, X_{t}, u_{t}) \dt+\overline{R}_{t} v_x(t,X_t)\sigma(t,X_t, u_{t})\dd W_{t},
	\end{aligned}
\end{equation*}
%\begin{align*}
%	&\quad\;\dd\; (\overline{R}_{t}v(t,X_{t}))\\
%	&=\overline{R}_{t}\dd v(t,X_{t})+v(t,X_{t}) \dd \overline{R}_{t}\\
%	&=\overline{R}_{t}\big[\left(v_{t}(t,X_t)+\opla_{u} v(t,X_t)\right)\dt+v_x(t,X_t)\sigma(t,X_t, u_{t})\dd W_{t}\big]-v(t,X_{t}) \overline{R}_{t} f(t, X_{t}, u_{t})\dt\\
%	&=\overline{R}_{t}\big[\left(v_{t}(t,X_t)+\opla_{u} v(t,X_t)-v(t,X_t)f(t, X_{t}, u_{t})\right)\dt+v_x(t,X_t)\sigma(t,X_t, u_{t})\dd W_{t}\big]\\
%	&\leq -\overline{R}_{t} G(t, X_{t}, u_{t}) \dt+\overline{R}_{t} v_x(t,X_t)\sigma(t,X_t, u_{t})\dd W_{t},
%\end{align*}
where the last inequality is due to \eqref{hjbpp1} and $\overline{R}_{t}>0$.
Integrating both sides from $s$ to $T$ and then taking conditional expectation yield
\begin{equation*}
	\BE{\overline{R}_{T}v(T,X_{T})-\overline{R}_{s}v(s,X_{s})\;\big|\; X_s=x}
	\leq -\BE{\int_s^{T}\overline{R}_{t} G(t, X_{t}, u_{t})\dt\;\bigg|\; X_s=x }.
\end{equation*}
As $\overline{R}_{s}=1$, the above leads to
\begin{equation*}
	\begin{aligned}
		v(s, x)
		&\geq \BE{\int_s^{T}\overline{R}_{t} G(t, X_{t}, u_{t})\dt+\overline{R}_{T}v(T,X_{T})\;\bigg|\; X_s=x}\\
		&=\BE{\int_s^{T} e^{-\int_{s}^{t}f(r, X_{r}, u_{r})\dr}G(t, X_t, u_{t})\dt
			+e^{-\int_{s}^{T}f(r, X_{r}, u_{r})\dr}H(X_T)\;\bigg|\; X_s=x}.
	\end{aligned}
\end{equation*}
This means that $v$ is an upper bound of the value function of problem \eqref{pp1}.
All the inequalities above become equalities if we take $u\in U$ that solves the optimization problem in \eqref{hjbpp1}.
Therefore, we conclude $v$ is the value function of \eqref{pp1}.

\subsection{Proof of Theorem \ref{policy improvement}}
By the Feynman--Kac formula, for any $(t,x)$,
\begin{equation*}
	\partial_t J^{\pi}(t,x)+\opla J^{\pi}(t,x)+H\left(t,x,\pi,J^{\pi}\right)=0,
\end{equation*}
where
\begin{equation*}
	H\left(t,x,\pi,J^{\pi}\right) :=K \pi(t,x)\left(g(t,x)-J^{\pi}(t,x)\right) - \lambda \BH(\pi(t,x)).
\end{equation*}
Similarly, for any $(t,x)$,
\begin{equation*}
	\partial_t J^{\tilde{\pi}}(t,x)+\opla J^{\tilde{\pi}}(t,x)+H\left(t,x,\tilde{\pi},J^{\tilde{\pi}}\right)=0,
\end{equation*}
where $\tilde{\pi}$ is defined in \eqref{tilde_pi}. It turns out that
\begin{equation*}
	\tilde{\pi}(t,x)=\argmax_{\pi\in[0, 1]} H\left(t,x,\pi,J^{\pi}\right).
\end{equation*}

Denote $\Delta(t,x):=J^{\tilde{\pi}}(t,x)-J^{\pi}(t,x)$. Then
\begin{equation*}
	\partial_t \Delta(t,x)+\opla \Delta(t,x)+H\left(t,x,\tilde{\pi},J^{\tilde{\pi}}\right) - H\left(t,x,\pi,J^{\pi}\right)=0.
\end{equation*}
Because
\begin{equation*}
	\begin{aligned}
		& H\left(t,x,\tilde{\pi},J^{\tilde{\pi}}\right) - H\left(t,x,\pi,J^{\pi}\right) \\
		=&\ H\left(t,x,\tilde{\pi},J^{\tilde{\pi}}\right) - H\left(t,x,\tilde{\pi},J^{\pi}\right)+
		H\left(t,x,\tilde{\pi},J^{\pi}\right) - H\left(t,x,\pi,J^{\pi}\right) \\
		=& - K \tilde{\pi}(t,x)\Delta(t,x)+H\left(t,x,\tilde{\pi},J^{\pi}\right) - H\left(t,x,\pi,J^{\pi}\right),
	\end{aligned}
\end{equation*}
we have
\begin{equation*}%\label{PDE_delta_pi}
	\partial_t \Delta(t,x)+\opla \Delta(t,x) - K \tilde{\pi}(t,x)\Delta (t,x)=H\left(t,x,\pi,J^{\pi}\right) - H\left(t,x,\tilde{\pi},J^{\pi}\right)\leq 0,
\end{equation*}
where the last inequality is from the definition of $\tilde{\pi}$.
Besides, $\Delta(T,x)=0$ at the terminal time $T$.
Therefore, 0 is a sub-solution of $-\partial_t u(t,x) - \opla u(t,x)+K \tilde{\pi}(t,x) u(t,x)+H\left(t,x,\pi,J^{\pi}\right) - H\left(t,x,\tilde{\pi},J^{\pi}\right)=0$.
%\begin{align*}
%	-\partial_t u(t,x) - \opla u(t,x)+K \tilde{\pi}(t,x) u(t,x)+H\left(t,x,\pi,J^{\pi}\right) - H\left(t,x,\tilde{\pi},J^{\pi}\right)=0.
%\end{align*}
By the maximum principle, we have $\Delta(t,x)\geq 0$, resulting in $J^{\tilde{\pi}}(t,x)\geq J^{\pi}(t,x)$.



\section{Learning early exercise premium}\label{learn early exercise premium}
%Instead of learning the value of American put option, we learn the value of early exercise premium. The reasons are twofold. First, we could remove the singularity of the terminal condition, which helps the learning performance of the values around the maturity time. Second, we could take this opportunity to show how to deal with the circumstances when the payoff function is not fully known.
In this section, we discuss how to learn the early exercise premium of an American put option.

Recall we have an explicit pricing formula for a European put option:
\begin{equation}
	\begin{cases}\label{European_put_value}
		V_E(t, x)=\Gamma e^{-\rho(T-t)}N\left(-d_{-}(t,x)\right) - xN\left(-d_{+}(t,x)\right), \ t\in[0,T),\\
		V_E(T,x)=g(x),
	\end{cases}	
\end{equation}
where $d_{\pm}(t,x)=\frac{1}{\sigma\sqrt{T-t}}\left[\log\left(\frac{x}{\Gamma}\right)+\left(\rho\pm\frac{1}{2}\sigma^2\right)\left(T-t\right)\right]$,
%\begin{align*}
%	d_{\pm}(t,x)=\frac{1}{\sigma\sqrt{T-t}}\left[\log\left(\frac{x}{\Gamma}\right)+\left(\rho\pm\frac{1}{2}\sigma^2\right)\left(T-t\right)\right],
%\end{align*}
and $N(\cdot)$ is the cumulative standard normal distribution function $N(y)=\frac{1}{\sqrt{2\pi}}\int_{-\infty}^y e^{-\frac{z^2}{2}} \dz=\frac{1}{\sqrt{2\pi}}\int_{-y}^{\infty} e^{-\frac{z^2}{2}} \dz$.
%\begin{align*}
%	N(y)=\frac{1}{\sqrt{2\pi}}\int_{-\infty}^y e^{-\frac{z^2}{2}} dz=\frac{1}{\sqrt{2\pi}}\int_{-y}^{\infty} e^{-\frac{z^2}{2}} dz.
%\end{align*}

The early exercise premium of the American put option is
\begin{equation}%\label{v_tilde}
	\tilde{v}(t,x):=v(t,x)-V_E(t,x),
\end{equation}
where $v(t,x)$ is the option value at the time--state pair $(t,x)$.
The associated payoff function is
\begin{equation}%\label{g_tilde}
	\tilde{g}(t,x):=g(x)-V_E(t,x).
\end{equation}
By \eqref{hjbp1} and the fact that $V_E$ satisfies $\frac{\partial}{\partial t}V_E+\opla V_E=0$ with terminal condition $V_E(T,x)=g(x)$,
%\begin{align*}
%	\frac{\partial}{\partial t}V_E+\opla V_E=0,\quad V_E(T,x)=g(x),
%\end{align*}
we have
\begin{equation}%\label{hjbp1}
	\begin{cases}
		\max\{\tilde{v}_{t}+\opla \tilde{v}, \ \tilde{g}-\tilde{v}\}=0,\ (t,x)\in[0,T)\times\R, \\
		\tilde{v}(T,x)=0.
	\end{cases}
\end{equation}
Thus, the terminal condition is smooth now, and the related PDE by penalty approximation is
\begin{equation*}
	\begin{cases}
		\tilde{v}_{t}+\max_{u\in\{0,1\}} \left\{\opla \tilde{v}- Ku\tilde{v}+K\tilde{g}(t,x)u\right\}=0,
		\ (t,x)\in[0,T)\times\R,\\
		\tilde{v}(T,x)=0.
	\end{cases}
\end{equation*}
%\begin{align*}
%	\begin{cases}
	%		\tilde{v}_{t}+\max_{u\in\{0,1\}} \Big[\frac{1}{2}\sigma^2(t,x)\frac{\partial^2 \tilde{v}}{\partial x^2}
	%		+b(t,x)\frac{\partial \tilde{v}}{\partial x}- Ku\tilde{v}+K\tilde{g}(t,x)u\Big]=0,\qquad\\
	%		\hfill\quad (t,x)\in[0,T)\times\R,\\
	%		\tilde{v}(T,x)=0.
	%	\end{cases}
%\end{align*}
Consequently, by Theorem \ref{vf} the corresponding control problem is
\begin{equation}
	%	\max_{u\in \{0,1\} }\; \be\Big[\int_s^{T} Ke^{-K\int_{s}^{t}u_{r}\dr}\tilde{g}(t,X_t)u_{t}\dt \;\bigg|\; X_s=x\Big],
	\max_{u\in \{0,1\} }\; \BE{\int_s^{T} Ke^{-K\int_{s}^{t}u_{r}\dr}\tilde{g}(t,X_t)u_{t}\dt \;\bigg|\; X_s=x},
\end{equation}
and the entropy-regularized exploratory problem is
\begin{equation}\label{v_tilde randomized}
	%	\max_{\pi\in [0,1]} \; \be\Big\{\int_s^{T} & e^{-K\int_{s}^{t}\pi_{v}\dv}\big[K \tilde{g}(t,X_t) \pi_{t}-\lam \BH(\pi_{t})\big]\dt \;\bigg|\; X_s=x \Big\}.
	\max_{\pi\in [0,1]} \; \BE{\int_s^{T} e^{-K\int_{s}^{t}\pi_{v}\dv}\big[K \tilde{g}(t,X_t) \pi_{t}-\lam \BH(\pi_{t})\big]\dt \;\bigg|\; X_s=x }.
\end{equation}
While we could use the algorithms in Section \ref{Section: RL algorithms} to learn $\tilde{v}$, $\tilde{g}$ is not fully known to us since $\sigma$ (which appears in $V_E$) is an unknown model parameter.

To deal with the unknown payoff function $\tilde{g}$,
recall
\begin{equation}\label{payoff_g_tilde}
	\tilde{g}(t,x)=g(x) - V_E(t,x)=\left(\Gamma - x\right)^+- V_E(t,x).
\end{equation}
Hence, in the formula of $V_E$, namely \eqref{European_put_value}, we replace $\sigma$ by $\phi$, which is a parameter to learn with a properly chosen initial value. Denote by $V_E^{\phi}$ and $\tilde{g}^{\phi}$ the parameterized European option value function and payoff function, respectively. % towards its true value $\sigma$?
%Thanks to the martingale approach developed in \cite{jia2022policy}, we can do policy evaluation because
Note that
\begin{equation}\label{V_E expectation}
	V_E(t,x)=\mathbb{E}\left[e^{-\rho(T-t)}g(X_T) \;\bigg|\; X_t=x\right]=\mathbb{E}\left[e^{-\rho(T-t)}\left(\Gamma-X_T\right)^+\;\bigg|\; X_t=x\right].
\end{equation}
This is a policy evaluation problem. Thanks to the martingale approach developed in \cite{jia2022policy}, we can learn/update $\phi$ by minimizing the martingale loss w.r.t. $\phi$:
\begin{equation}
	\begin{aligned}\label{martingale_loss_payoff}
		\quad\quad\text{ML}\left(\phi\right)
		&\approx \frac{1}{2}\mathbb{E}\left[\sum_{l=0}^{L-1}\left( e^{-\rho T}V_E\left(T,X_T\right)- e^{-\rho t} V_E^{\phi}\left(t_l,X_l\right) \right)^2\Delta t\right]\\
		&=\frac{1}{2}\mathbb{E}\left[\sum_{l=0}^{L-1}\left (e^{-\rho T}\left(\Gamma-X_T\right)^+- e^{-\rho t} V_E^{\phi}\left(t_l,X_l\right)\right)^2\Delta t\right].
	\end{aligned}
\end{equation}
In each episode, we simulate a batch of stock price trajectories and then use the stochastic gradient descent method to minimize the above loss function to update $\phi$.
Figure \ref{fig:learn payoff} shows the efficacy of this policy evaluation algorithm, with an initial guess of the unknown $\sigma$ to be 0.8, twice the true value.

