\section{RL for Dynkin games} \label{RL_Dynkin_penalty}
Theorem 1 in \cite{dai2024learningcost} reveals that Merton's problem with proportional transaction costs is equivalent to a Dynkin game that is essentially an optimal stopping problem. Here, we focus on the Black--Scholes market where the stock price follows
\begin{equation*}
	\dS_t=\alpha S_t\dt+\sigma S_t\dw_t,
\end{equation*}
where $\alpha$ and $\sigma$ are constants but unknown to the agent.
The value function of the Dynkin game satisfies the following variational inequality problem
\begin{equation}\label{HJB_Dynkin_game}
	\max\left\{\min\left\{-w_t-\mathcal{L}w, w-L(x)\right\}, w-U(x)\right\}=0
\end{equation}
with terminal condition
\begin{equation}
	w(T,x)=\frac{x}{x+1-\theta},
\end{equation}
where $\theta\in (0,1)$ is the proportional transaction cost rate, $x$ is the bond--stock position ratio, $\mathcal{L}$ is the generator of this ratio process, and $L(x)$ and $U(x)$ are respectively the lower and upper obstacles of $w(t,x)$.

It is proved in \cite{zhang2022solution} that \eqref{HJB_Dynkin_game} can be approximated by the following penalized PDE:
\begin{equation}
	-w_t - \mathcal{L}w - K \left(w-L(x)\right)^{-}+K \left(w-U(x)\right)^{+}=0,
\end{equation}
where $K>0$ is a large penalty factor. This PDE can be equivalently written as
\begin{equation}\label{penalty_PDE_Dynkin}
	w_t+\max_{a\in\left\{0, 1\right\}}\min_{b\in\left\{0, 1\right\}}\left\{\mathcal{L}w-wf(t,x,a,b)+G(t,x,a,b)\right\}=0,
\end{equation}
where
\begin{equation*}
	f(t,x,a,b)=K (a+b),\quad G(t,x,a,b)=K \left(L(x)a+U(x)b\right).
\end{equation*}


Similar to the setup in Section \ref{Sec:transform_to_control}, we consider a constrained differential game:
\begin{equation}\label{prob_max_min}
	w(s,x)=\max_{a\in\setu}\min_{b\in\setu} J(s,x; a,b),
\end{equation}
where
\begin{equation*}
	\begin{aligned}
		J(s,x;a,b)=\mathbb{E}\Bigg[\int_s^{T} &e^{-\int_{s}^{t}f(r, X_{r}, a_{r}, b_r)\dr}G(t, X_t, a_t, b_t)\dt\nn\\ &+e^{-\int_{s}^{T}f(r, X_{r}, a_{r}, b_r)\dr}H(X_T)\;\bigg|\; X_s=x\Bigg],
	\end{aligned}
\end{equation*}
%\begin{align*}
%	J(s,x;a,b)&=\BE{\int_s^{T} e^{-\int_{s}^{t}f(r, X_{r}, a_{r}, b_r)\dr}G(t, X_t, a_t, b_t)\dt
	%		+e^{-\int_{s}^{T}f(r, X_{r}, a_{r}, b_r)\dr}H(X_T)\;\bigg|\; X_s=x},
%\end{align*}
and the controlled $n$-dimensional process $X$ follows
\begin{equation}
	\dd X_t=b(t, X_t, a_t, b_t)\dt+\sigma(t,X_t, a_t, b_t)\dw_t.
\end{equation}
We have the following result.

\begin{thm}[Verification theorem]
	Suppose $w$ is a classical solution of
	\begin{equation}
		\begin{cases}\label{HJB_max_min}
			w_{t}+\max_{a\in U}\min_{b\in U}\left\{\opla_{a,b} w-wf+G\right\}=0, ~~ (t,x)\in[0,T)\times\R^{n},\\
			w(T,x)=H(x),
		\end{cases}
	\end{equation}
	where
	\begin{equation*}
		\opla_{a,b} w=\frac{1}{2}\sum_{i,j,k}\sigma_{i,k}(t,x,a,b)\sigma_{j,k}(t,x,a,b)\frac{\partial^2w }{\partial x_{i}\partial x_{j}}
		+\sum_{i} b_{i}(t,x,a,b)\frac{\partial w}{\partial x_{i}}.
	\end{equation*}
	Then it is the value function of problem \eqref{prob_max_min}.
\end{thm}

\begin{proof}%{Proof}
	Let $\overline{R}_{t}=e^{-\int_{s}^{t}f(r, X_{r}, a_{r}, b_{r})\dr}, \ t\geq s$.	Then $\dd \overline{R}_{t}=-\overline{R}_{t}f(t, X_{t}, a_{t}, b_{t})\dt$ and $\overline{R}_{s}=1.$	

	For each fixed ${a\in U}$, let $b^*_{t}=b_t^*(x,a)$ denote the minimizer of $\opla_{a,b} w-wf+G$.
	By \eqref{HJB_max_min}, $$w_{t}+\max_{a\in U}\left\{\opla_{a,b^*} w-wf(t,x,a,b^*)+G(t,x,a,b^*)\right\}=0.$$
	%Let $$z(s,x;a):=J(s,x;a,b^*(a))=\min_{b\in\setu} J(s,x;a,b).$$
	Then, similar to the proof in Appendix \ref{proof_HJB}, we get for any admissible process $a\in\setu$,
	\begin{equation*}
		\begin{aligned}
			w(s, x)
			&\geq \BE{\int_s^{T}\overline{R}_{t}^{a,b^*} G(t, X_{t}, a_t,b_t^*)\dt+\overline{R}_{T}^{a,b^*}w(T,X_{T})\;\bigg|\; X_s=x}\\
			&=\BE{\int_s^{T} e^{-\int_{s}^{t}f(r, X_{r}, a_r,b_r^*)\dr}G(t, X_t, a_t,b_t^*)\dt
				+e^{-\int_{s}^{T}f(r, X_{r}, a_r,b_r^*)\dr}H(X_T)\;\bigg|\; X_s=x}\\
			&=J(s,x;a,b^{*})\\
			& \geq \min_{b\in\setu} J(s,x;a,b).
		\end{aligned}
	\end{equation*}
	Since $a\in\setu$ is arbitrarily chosen, the above implies
	\begin{equation*}
		w(s, x)
		\geq \max_{a\in \setu}\min_{b\in \setu} J(s,x;a,b).
	\end{equation*}
	Hence, $w$ is an upper bound of the value function of problem \eqref{prob_max_min}.

	On the other hand, 	 if we choose a pair $(a^{*}, b^{*}_{t}(x,a^{*}))$ to solve
	$$\max_{a\in U}\min_{b\in U}\left\{\opla_{a,b} w-wf+G\right\},$$ all the inequalities in the above become equalities, yielding that $w$ is the value function of \eqref{prob_max_min}.	%\Halmos
\end{proof}


Following the same procedure as in Section \ref{Sec:transform_to_control}, we find that the solution to \eqref{penalty_PDE_Dynkin} satisfying the terminal condition is the value function of the following stochastic differential game \citep{fleming2006controlled}:
\begin{equation}
	w(s,x)=\max_{a_{t}\in\{0,1\}}\min_{b_{t}\in\{0,1\}} J(s,x;a, b),
\end{equation}
where
\begin{equation}\label{value_func_control_Dynkin}
	\begin{aligned}
		J(s,x;a,b)=\mathbb{E}\Big[\int_s^{T} &Ke^{-K\int_{s}^{t}(a_r+b_r)\dr}\left(L(X_t)a_t+U(X_t)b_t\right)\dt\\\nonumber
		&+e^{-K\int_{s}^{T}(a_r+b_r)\dr}\frac{X_T}{X_T+1-\theta}\;\bigg|\; X_s=x\Big].
	\end{aligned}
\end{equation}

Next, we randomize $\{a_t\}_{t\in[0,T]}$ and $\{b_t\}_{t\in[0,T]}$ respectively by $\{\nu_t\}_{t\in[0,T]}$ and $\{\mu_t\}_{t\in[0,T]}$, where
\begin{equation*}
	\nu_t=\mathbb{P}\left(a_t=1\right)=1 - \mathbb{P}\left(a_t=0\right), \quad \mu_t=\mathbb{P}\left(b_t=1\right)=1 - \mathbb{P}\left(b_t=0\right).
\end{equation*}
It turns out that the exploratory value function of the Dynkin game is
\begin{equation}\label{value_Dynkin_randomized}
	w^{\lambda}(s,x)=\max_{\nu_{t}\in[0,1]}\min_{\mu_{t}\in[0,1]} J^{\lambda}(s,x;\nu, \mu),
\end{equation}
where
\begin{equation}\label{value_func_control_Dynkin_randomize}
	\begin{aligned}
		J^{\lambda}(s,x;\nu,\mu)=\mathbb{E}\Big[\int_s^{T} &Ke^{-K\int_{s}^{t}(\nu_r+\mu_r)\dr}\left[L(X_t)\nu_t+U(X_t)\mu_t-\lam \left(\BH(\nu_{t}) - \BH(\mu_t)\right)\right]\dt\\\nonumber
		&+e^{-K\int_{s}^{T}(\nu_r+\mu_r)\dr}\frac{X_T}{X_T+1-\theta}\;\bigg|\; X_s=x\Big].
	\end{aligned}
\end{equation}
The HJB equation of problem \eqref{value_Dynkin_randomized} is thus
\begin{equation}
	w^{\lambda}_t+\mathcal{L}w^{\lambda}+\max_{\nu\in[0,1]}\min_{\mu\in[0,1]}\left\{-w^{\lambda}K(\nu+\mu)+K\left(L(x)\nu+U(x)\mu\right)-\lambda\left(\BH(\nu)-\BH(\mu)\right)\right\}=0,
\end{equation}
and the optimal solutions are
\begin{equation}
	\begin{aligned}\label{optimal_prob_nu_mu_Dynkin}
		\nu^* &=\frac{\exp\left(\frac{K}{\lambda}(L(x)-w^{\lambda})\right)}{\exp\left(\frac{K}{\lambda}(L(x)-w^{\lambda})\right)+1}=\frac{1}{1+\exp\left(-\frac{K}{\lambda}(L(x)-w^{\lambda})\right)},\\%\label{optimal_prob_nu_Dynkin}\\
		\mu^* &=\frac{\exp\left(\frac{K}{\lambda}(w^{\lambda}-U(x))\right)}{\exp\left(\frac{K}{\lambda}(w^{\lambda}-U(x))\right)+1}=\frac{1}{1+\exp\left(-\frac{K}{\lambda}(w^{\lambda}-U(x))\right)}.%\label{optimal_prob_mu_Dynkin}
	\end{aligned}
\end{equation}

Consequently, if we choose the TD error criterion for policy evaluation, the RL algorithm is essentially the same as Algorithm 1 in \cite{dai2024learningcost}, except that $\nu, \mu, \nu^*, \mu^*$ in their algorithm should be replaced by $K\nu, K\mu$, $\nu^*, \mu^*$ in \eqref{optimal_prob_nu_mu_Dynkin} in this section, and their entropy term should be replaced by the differential entropy in this paper.





\section{Finite difference method}\label{finite_difference}

In this section, we present (classical, model-based) algorithms for pricing a finite-horizon American put option and obtaining its stopping boundary. We use the penalty method in \cite{forsyth2002quadratic}. The payoff function is $g(x)=\left(\Gamma-x\right)^{+}$ with $x$ being the stock price and $\Gamma$ the strike price.
We consider the PDE \eqref{hjb2} and let $u(t,y) := v(t,x)$ with $x=e^{y}$.
In the finite difference scheme below, the time horizon $\left[0,T\right]$ is divided to $N_t$ equally spaced intervals with $t_i=i\Delta t,\ \text{for } i=0,\ldots, N_t$, and the range for $y$ is chosen to be $\left[-N, N\right]$ with $N$ being a large positive number, which is further divided into $N_y$ equally spaced intervals with $y_j = -N + j\Delta y\ \text{for } j = 0,\ldots,N_y$.
Thus, $u_{i,j}$ denotes the numerical value at the mesh point $\left(t_i, y_j\right)$, namely, $u_{i,j}:=u\left(t_i,y_j\right)$ for $i=0,\ldots,N_t, j=0,\ldots,N_y$.

In the following, let $u_{i,j}^k$ denotes the $k$-th iteration value of $u_{i,j}$. The terminal condition is
\begin{equation}\label{u_terminal}
	u_{N_t,j} = g(e^{y_j})
\end{equation}
for $j=0,\ldots,N_y$.
Similarly, the boundary conditions at $y_0$ and $y_{N_y}$ are set to be
\begin{equation}\label{u_boundary}
	u_{i,0} = g(e^{y_0}),\ \text{and }	u_{i,N_y} = g(e^{y_{N_y}})
\end{equation}
for $i=0,\ldots,N_t$.
The Black--Scholes operator $v_t(t,x)+\frac{1}{2}\sigma^2x^2v_{xx}(t,x)+\rho xv_x(t,x)-\rho v(t,x)$ changes to
\begin{equation*}
	\mathcal{L}_{BS}u(t,y):=u_{t}(t,y)+\frac{1}{2}\sigma^2u_{yy}(t,y)+\left(\rho-\frac{1}{2}\sigma^2\right)u_y(t,y)-\rho u(t,y).
\end{equation*}

By the fully implicit finite difference scheme,
\begin{equation*}
	\begin{aligned}
		\frac{\partial}{\partial t} u(t_i, y_j) &= \frac{u_{i+1,j} - u_{i,j}}{\Delta t},\\
		\frac{\partial}{\partial y} u(t_i, y_j) &= \frac{u_{i, j+1}-u_{i, j-1}}{2\Delta y},\\
		\frac{\partial^2}{\partial y^2} u(t_i, y_j) &= \frac{u_{i, j+1} - 2u_{i,j} + u_{i, j-1}}{\left(\Delta y\right)^2},
	\end{aligned}
\end{equation*}
for $j=1,\ldots,N_y-1$ and $i=0,\ldots,N_t-1$. The discretized Black--Scholes operator is therefore
\begin{equation}\label{L_BS_finite}
	\mathcal{L}_{BS} u_{i,j} = \frac{u_{i+1,j}-u_{i,j}}{\Delta t} + \beta u_{i, j+1} - \left(\alpha+\beta+\rho\right) u_{i,j} + \alpha u_{i, j-1},
\end{equation}
where
\begin{equation*}
	\alpha = \frac{\sigma^2}{2\left(\Delta y\right)^2} - \frac{\rho - \frac{1}{2}\sigma^2}{2\Delta y},\ \text{and } \beta = \frac{\sigma^2}{2\left(\Delta y\right)^2} + \frac{\rho - \frac{1}{2}\sigma^2}{2\Delta y}.
\end{equation*}


%\subsection{Numerical solution for \eqref{hjb2}}
The PDE in \eqref{hjb2} becomes
\begin{equation}\label{ti_yj_PDE}
	-\mathcal{L}_{BS} u(t,y) = K \left(g(e^y)-u(t,y)\right)^{+}.
\end{equation}
For each mesh point $\left(t_i, y_j\right)$, we use the following approximation by Newton iteration:
\begin{equation}\label{NewtonIter_VI}
	\begin{aligned}
		\left(g(e^{y_j})-u_{i,j}^{k+1}\right)^{+} & = \left(g(e^{y_j})-u_{i,j}^{k}+u_{i,j}^{k}-u_{i,j}^{k+1}\right)^{+}\nonumber\\
		& \approx \left(g(e^{y_j})-u_{i,j}^{k}\right)^{+} + 1_{g(e^{y_j})-u_{i,j}^{k} > 0} \left(u_{i,j}^{k}-u_{i,j}^{k+1}\right)\nonumber\\
		& = \left(g(e^{y_j})-u_{i,j}^{k+1}\right)1_{g(e^{y_j})-u_{i,j}^{k} > 0},
	\end{aligned}
\end{equation}
where $1_{A}$ is the indicator function of a set $A$.
By \eqref{L_BS_finite} and \eqref{NewtonIter_VI}, it turns out that \eqref{ti_yj_PDE} reads
\begin{equation*}
	- \frac{u_{i+1,j}-u_{i,j}^{k+1}}{\Delta t} - \beta u_{i, j+1}^{k+1} + \left(\alpha+\beta+\rho\right) u_{i,j}^{k+1} - \alpha u_{i, j-1}^{k+1} =
	K \left(g(e^{y_j})-u_{i,j}^{k+1}\right)1_{g(e^{y_j})-u_{i,j}^{k} > 0},
\end{equation*}
which simplifies to
\begin{equation}\label{NewtonIter_equ}
	- \beta u_{i, j+1}^{k+1} + \left(\frac{1}{\Delta t} + \alpha+\beta+ \rho + K 1_{g(e^{y_j})-u_{i,j}^{k} > 0}\right) u_{i,j}^{k+1} - \alpha u_{i, j-1}^{k+1} = \frac{u_{i+1,j}}{\Delta t} +
	K g(e^{y_j}) 1_{g(e^{y_j})-u_{i,j}^{k} > 0}.
\end{equation}
In each iterative step, the quantities in the RHS of \eqref{NewtonIter_equ} regarding future values $u_{i+1,j}$ for all $j$ and previous estimates $u_{i,j}^k$ for all $i$ and $j$ are known, and the current estimates $u_{i,j}^{k+1}$ are obtained by solving the equation \eqref{NewtonIter_equ}. See Algorithm \ref{algorithm_am_put} for details.
\begin{algorithm}\label{algorithm_am_put}
	\caption{Finite difference scheme for \eqref{hjb2}}
	\textbf{Inputs:} $\Delta t, \Delta y, N, N_t, N_y, K$ and the tolerance level $\ep>0$.\\
	\textbf{Learning procedure:}\\
	Initialize $u_{N_t,j}$ for all $j$ by \eqref{u_terminal} as well as $u_{i,0}$ and $u_{i,N_y}$ for all $i$ by \eqref{u_boundary}.\\
	\For {$i = N_t-1,\ldots,0$}{
		Set $u_{i, j}^0 = u_{i+1, j}$ for $j=1,\ldots,N_y-1$.\\
		\For{$k=0,1,\dots$}{
			Solve the equation \eqref{NewtonIter_equ} to get $u_{i,j}^{k+1}$ for $j=1,\ldots,N_y-1$.\\
			\If{$ {||u_i^{k+1}-u_i^k||_{\infty}}< \ep* {\max\left\{1,\ ||u_i^k||_{\infty}\right\}} $}
			%		\If{$||u_i^{k+1}-u_i^k||_{\infty} / \max\left\{1,\ ||u_i^k||_{\infty}\right\}< tol$}
			{Quit the loop for $k$.}			
		}
		Set $u_{i,j}=u_{i,j}^{k+1}$ for $j=1,\ldots,N_y-1$.\\
	}
\end{algorithm}

