\section{Resolving Instability: Additional Material} \label{app:resolving}

\subsection{Generating Unstable Matchings}
Here we describe the procedures we use to generate the two types of unstable matchings we consider.

\paragraph{One-BP.} We generate a matching that contains a single blocking pair, by swapping the partners of two randomly selected proposer agents in the Optimal matching. Since such a swap may lead to more than one blocking-pair (or no blocking pairs), we perform this process (for every instance) until we obtain a matching with exactly one blocking-pair. This procedure is formally described in \Cref{alg:generate-unstable}.

\begin{algorithm}[ht]
  \caption{\textsc{GenerateOneBPMatching}}
  \label{alg:generate-unstable}
  \begin{algorithmic}[1]
    \Require
      \Statex $\,\Pi = (\succ_m, \succ_w)$ \Comment{Preference profile for all men $m\in M$ and women $w\in W$}
      \Statex $\mu^\ast$ \Comment{Men-optimal stable matching returned by Deferred Acceptance}
    \Ensure
      \Statex A matching $\mu$ containing \emph{exactly one} blocking pair
    \Function{GenerateOneBPMatching}{$\Pi, \mu^\ast$}
      \Repeat                                           \Comment{Keep trying until the condition is met}
        \State $\mu \gets \text{copy}(\mu^\ast)$        \Comment{Start from the stable matching}
        \State $(m_a, m_b) \gets \text{arbitrary pair } m_a, m_b \in M \text{ s.t. } m_a \neq m_b$
        \State $w_a \gets \mu(m_a)$
        \State $w_b \gets \mu(m_b)$
        \Comment{Swap partners of the two men}
        % \HH{can you make this 4 lines two at most; it is just a swap!}
        \State $\mu(m_a) \gets w_b,\;\; \mu(w_b) \gets m_a$
        \State $\mu(m_b) \gets w_a,\;\; \mu(w_a) \gets m_b$
      \Until{$\lvert $\textsc{BlockingPairs}$(\mu,\Pi)\rvert = 1$}          \Comment{Stop when exactly one blocking pair exists}
      \State \Return $\mu$
    \EndFunction
    \bigskip
    \Function{BlockingPairs}{$\mu,\Pi$}
      \State $B \gets \emptyset$
      \ForAll{$m \in M$}
        \ForAll{$w \in W$}
          \If{$w \succ_m \mu(m)$ \textbf{and} $m \succ_w \mu(w)$}
            \State $B \gets B \cup \{(m,w)\}$
          \EndIf
        \EndFor
      \EndFor
      \State \Return $B$
    \EndFunction
  \end{algorithmic}
\end{algorithm}


\paragraph{Random.} A Random matching is simply generated by generating a random permutation of agents on one side and assigning agents such a list to the agents on the other side, one-by-one.

