\begin{proof}[Proof of Theorem \ref{thm:nonid_att}]
Construct two data-generating processes, $\mathcal{P}_1$ and $\mathcal{P}_2$, which induce the same observed distribution $P_{\text{obs}} := P^*(X, D, Y \mid S = 1)$, yet imply different values of $\tau_{\text{ATT}}$.

\paragraph{DGP 1 (Ignorable Sampling):}
Suppose that the sampling mechanism satisfies
\[
S \perp (Y(1), Y(0)) \mid X, D.
\]
Then for treated units ($D = 1$),
\[
\mathbb{E}[Y \mid D = 1, X, S = 1] = \mathbb{E}[Y(1) \mid X, D = 1] = \mathbb{E}[Y(1) \mid X].
\]
For untreated units ($D = 0$),
\[
\mathbb{E}[Y \mid D = 0, X, S = 1] = \mathbb{E}[Y(0) \mid X, D = 0] = \mathbb{E}[Y(0) \mid X].
\]
If we further assume unconfoundedness, i.e.,
\[
(Y(1), Y(0)) \perp D \mid X,
\]
then
\[
\mathbb{E}[Y(0) \mid D = 1] = \mathbb{E}_X \left[ \mathbb{E}[Y(0) \mid X] \mid D = 1 \right].
\]
Therefore,
\[
\tau_{\text{ATT}} = \mathbb{E}[Y(1) \mid D = 1] - \mathbb{E}[Y(0) \mid D = 1]
\]
can be identified using observed treated outcomes and imputed counterfactuals from controls.

\paragraph{DGP 2 (Non-Ignorable Sampling):}
Now suppose sampling depends on $Y(0)$:
\[
\mathbb{P}(S = 1 \mid Y(0)) = \mathbbm{1}\{Y(0) > c\}
\]
for some threshold $c \in \mathbb{R}$. Then, among untreated units ($D = 0$), we only observe outcomes $Y(0)$ for units with $Y(0) > c$. Thus,
\[
\mathbb{E}[Y \mid D = 0, X, S = 1] = \mathbb{E}[Y(0) \mid X, Y(0) > c],
\]
and hence the counterfactual distribution for treated units, $\mathbb{E}[Y(0) \mid D = 1]$, cannot be recovered from the observed controls.

\paragraph{Conclusion:}
Both $\mathcal{P}_1$ and $\mathcal{P}_2$ induce the same observed distribution $P_{\text{obs}}$, but they imply different values of
\[
\tau_{\text{ATT}} = \mathbb{E}[Y(1) \mid D = 1] - \mathbb{E}[Y(0) \mid D = 1].
\]
Therefore, $\tau_{\text{ATT}}$ is not identified from $P_{\text{obs}}$ unless assumptions are placed on the sampling mechanism $S$ or the counterfactual distribution.
\end{proof}


\begin{proof}[Proof of Theorem~\ref{thm:monotonicity}]
Let $\delta_1 < \delta_2$, and define the corresponding families of selection mechanisms:
\[
\mathcal{S}_{\delta_1} \subset \mathcal{S}_{\delta_2}.
\]
Let $\mathcal{G}_\delta(P_{\mathrm{obs}})$ denote the set of full-data distributions and selection rules such that:
\[
\mathcal{G}_\delta(P_{\mathrm{obs}}) := \left\{ (P, S) : S \in \mathcal{S}_\delta,\ P(Y, D, X \mid S = 1) = P_{\mathrm{obs}} \right\}.
\]
The identified set for the estimand $\theta(P)$ under selection curvature $\delta$ is:
\[
\mathcal{I}_\theta(\delta) := \left\{ \theta(P) : (P, S) \in \mathcal{G}_\delta(P_{\mathrm{obs}}) \right\}.
\]

Now take any $\theta_1 \in \mathcal{I}_\theta(\delta_1)$. By definition, there exists $(P_1, S_1) \in \mathcal{G}_{\delta_1}(P_{\mathrm{obs}})$ such that $\theta_1 = \theta(P_1)$ and $S_1 \in \mathcal{S}_{\delta_1}$. Since $\mathcal{S}_{\delta_1} \subset \mathcal{S}_{\delta_2}$, it follows that $S_1 \in \mathcal{S}_{\delta_2}$ and thus $(P_1, S_1) \in \mathcal{G}_{\delta_2}(P_{\mathrm{obs}})$. Therefore,
\[
\theta_1 \in \mathcal{I}_\theta(\delta_2).
\]

As this argument holds for arbitrary $\theta_1 \in \mathcal{I}_\theta(\delta_1)$, we conclude that:
\[
\mathcal{I}_\theta(\delta_1) \subseteq \mathcal{I}_\theta(\delta_2).
\]
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:duality}]
Let $\theta(P) = \mathbb{E}[Y(1) - Y(0)]$, and let the identified set under selection class $\mathcal{S}_\delta$ be defined as:
\[
\mathcal{I}_\tau(\delta) := \left\{ \mathbb{E}_P[Y(1) - Y(0)] : (P, S) \in \mathcal{G}_\delta(P_{\mathrm{obs}}) \right\},
\]
where
\[
\mathcal{G}_\delta(P_{\mathrm{obs}}) := \left\{ (P, S) : P(Y, D, X \mid S = 1) = P_{\mathrm{obs}},\ S \in \mathcal{S}_\delta \right\}.
\]
The three parts are proven in order.

\paragraph{(i) Monotonicity and Right-Continuity.}
Assume $\delta_1 < \delta_2$. By definition of the constraint:
\[
\mathcal{S}_{\delta_1} \subseteq \mathcal{S}_{\delta_2} \quad \Rightarrow \quad \mathcal{G}_{\delta_1}(P_{\mathrm{obs}}) \subseteq \mathcal{G}_{\delta_2}(P_{\mathrm{obs}}).
\]
Therefore,
\[
\mathcal{I}_\tau(\delta_1) \subseteq \mathcal{I}_\tau(\delta_2),
\]
which implies that the map $\delta \mapsto \mathcal{I}_\tau(\delta)$ is set-increasing. Consequently, the width function:
\[
\delta \mapsto \text{width}(\mathcal{I}_\tau(\delta)) := \sup \mathcal{I}_\tau(\delta) - \inf \mathcal{I}_\tau(\delta)
\]
is non-decreasing.

To prove right-continuity, let $\delta_n \downarrow \delta$. The corresponding selection classes satisfy $\mathcal{S}_{\delta_n} \downarrow \mathcal{S}_\delta$ in the sense of set intersection. Since $\mathcal{I}_\tau(\delta_n)$ is defined by taking the image of a continuous functional (the ATE) over a decreasing family of closed sets (the feasible DGPs), and $\theta(P)$ is continuous in $P$, we have:
\[
\bigcap_{n} \mathcal{I}_\tau(\delta_n) = \mathcal{I}_\tau(\delta),
\]
and the endpoints of $\mathcal{I}_\tau(\delta_n)$ converge to those of $\mathcal{I}_\tau(\delta)$. Hence, the width function is right-continuous.

\paragraph{(ii) Limit as $\delta \to 0$: Recovery of $\tau_{\mathrm{MAR}}$.}
When $\delta = 0$, the selection mechanism satisfies:
\[
P(S = 1 \mid Y, D, X) = P(S = 1 \mid D, X),
\]
i.e., MAR holds. Then,
\[
\mathcal{I}_\tau(0) = \left\{ \mathbb{E}[Y(1) - Y(0)] \text{ computed under MAR} \right\} = \{ \tau_{\mathrm{MAR}} \}.
\]
As $\delta \downarrow 0$, the constraint set $\mathcal{S}_\delta$ shrinks to MAR, and $\mathcal{I}_\tau(\delta)$ shrinks to a singleton at $\tau_{\mathrm{MAR}}$ by continuity of expectations. Thus,
\[
\lim_{\delta \to 0} \mathcal{I}_\tau(\delta) = \{ \tau_{\mathrm{MAR}} \}.
\]

\paragraph{(iii) Limit as $\delta \to \infty$: Recovery of Manski Bounds.}
As $\delta \to \infty$, the curvature constraint on the selection mechanism disappears:
\[
\lim_{\delta \to \infty} \mathcal{S}_\delta = \mathcal{S}_{\infty},
\]
where $\mathcal{S}_\infty$ denotes the unrestricted class of selection mechanisms consistent with $P_{\mathrm{obs}}$. The resulting identified set becomes:
\[
\mathcal{I}_\tau(\infty) := \left\{ \mathbb{E}_P[Y(1) - Y(0)] : (P, S) \in \mathcal{G}_{\infty}(P_{\mathrm{obs}}) \right\},
\]
which corresponds to the standard partial identification region given only by the observed data and the support of $Y(1), Y(0)$ (e.g., $[0,1]$ outcomes). This is equivalent to the Manski bounds:
\[
\lim_{\delta \to \infty} \mathcal{I}_\tau(\delta) = [\tau_{\min}, \tau_{\max}].
\]

\paragraph{Conclusion.}
Each component follows from the nested structure of $\mathcal{S}_\delta$, the continuity of the ATE functional, and the extreme cases of MAR and worst-case selection. This establishes the duality between structural curvature $\delta$ and epistemic uncertainty in causal inference.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:frontier}]
Let $P_{\mathrm{obs}}(Y, D, X)$ denote the observed distribution over outcomes, treatment, and covariates, conditional on $S = 1$. Recall the definition of the selection frontier:
\[
\mathcal{S}(P_{\mathrm{obs}}) := \left\{ S : \exists P \text{ such that } P(Y, D, X \mid S = 1) = P_{\mathrm{obs}} \right\}.
\]
Let $\mathcal{S}'$ be a proposed class of sampling mechanisms.

Suppose, for contradiction, that $\mathcal{S}' \not\subseteq \mathcal{S}(P_{\mathrm{obs}})$, but there exists some $S' \in \mathcal{S}'$ and a joint distribution $P$ such that
\[
P(Y, D, X \mid S' = 1) = P_{\mathrm{obs}}.
\]
Then by definition of $\mathcal{S}(P_{\mathrm{obs}})$, it must be that $S' \in \mathcal{S}(P_{\mathrm{obs}})$, which contradicts the assumption that $\mathcal{S}' \not\subseteq \mathcal{S}(P_{\mathrm{obs}})$.

Therefore, for all $S' \in \mathcal{S}' \setminus \mathcal{S}(P_{\mathrm{obs}})$, no joint distribution $P$ exists such that the observed conditional distribution $P(Y, D, X \mid S = 1)$ is consistent with $P_{\mathrm{obs}}$ under $S = S'$.

\paragraph{Conclusion.} If $\mathcal{S}' \not\subseteq \mathcal{S}(P_{\mathrm{obs}})$, then any inference made under sampling mechanism class $\mathcal{S}'$ is logically inconsistent with the observed data. The model is misspecified, and inference under $\mathcal{S}'$ necessarily violates the empirical support of the data.
\end{proof}

