\subsection{Topological groupoids with involution.} Recall that a \emph{topological groupoid} $\mr X = [R\rightrightarrows U]$ consists of two topological spaces, $U$ (the space of objects) and $R$ (the space of arrows), and a collection of continuous maps $(s,t,c,e,i)$ satisfying a number of natural conditions (see Section \ref{sec:topstacks:top} for more details). For instance, $s \colon R \to U$ is the source map, $t \colon R \to U$ the target map, and $c \colon R \times_{s,U,t} R \to R$ the composition map. If $f\in R$ is such that $s(f)=x$ and $t(f)=y$, we write $x\xrightarrow{f}y$ and we say that $f$ is an isomorphism between $x$ and $y$. If $f,g\in R$ are such that $t(f)=s(g)$ we write $g\circ f$ for $c(g,f)$.  

Write $x\cong y$ if there exists a $f\in R$ with $x\xrightarrow{f}y$. The axioms of topological groupoids ensure that $\cong$ is an equivalence relation, so that we can consider 
$\vert \mr X\vert = U/_{\cong}$, the set of isomorphism classes of objects of $\mr X$.
We equip $\va{\mr X}$ with the quotient topology. 
\begin{example}\label{ex:stackvcomplexsgroupoidintro}
 Let $\mathcal X$ be a Deligne--Mumford stack of finite type over $\CC$. Let $U \to \ca X$ be a surjective \'etale presentation by a scheme $U$, and let $R$ be a scheme with $R \cong U \times_{\ca X} U$. The two projections $\pi_1,\pi_2 \colon (U \times_{\ca X} U)(\CC) \to U(\CC)$ define maps $s,t \colon R(\CC) \to U(\CC)$ that extend to the structure of a topological groupoid $\mr X = [R(\CC) \rightrightarrows U(\CC)]$. There is a natural bijection between
 $\va{\mr X}$ and the set $\va{\ca X(\CC)}$ of isomorphism classes of objects in $\ca X(\CC)$; see Construction \ref{cons:groupoid-DM} for more details. 
\end{example}

An \emph{involution} $\sigma \colon \mr X \to \mr X$ consists of involutions $\sigma \colon R \to R$ and $\sigma \colon U \to U$ that are compatible all the structure maps of the topological groupoid. 
\begin{example}\label{ex:stackvsgroupoidintro}
 Let $\mathcal X$ be a Deligne--Mumford stack of finite type over $\RR$, let $U \to \ca X$ be a surjective \'etale presentation by a scheme $U$ over $\RR$. % and let $R = U \times_{\ca X} U$.  
If $\mr X = [R(\CC)\rightrightarrows U(\CC)]$ is the topological groupoid associated to $\mathcal X_{\mathbb C}$ as in Example \ref{ex:stackvcomplexsgroupoidintro}, the natural anti-holomorphic involutions on $R(\CC)$ and $U(\CC)$ define an involution $\sigma \colon \mr X \to \mr X$. 
\end{example}

Let $\mr X = [R\rightrightarrows U]$ be a topological groupoid, equipped with an involution $\sigma \colon \mr X\rightarrow \mr X$. Inspired by the case of topological spaces with involution, we call the pair $(\mr X, \sigma)$ a \emph{topological $G$-groupoid}, where
\[
G \coloneqq \Gal(\CC/\RR) \cong \ZZ/2.
\]
We define the \emph{fixed locus} of the topological $G$-groupoid $(\mr X, \sigma)$ as follows:
\begin{equation}\label{def:real-locusintro}
\va{\mr{X}^{G}} \coloneqq \set{(x, \varphi) \in U \times R \text{ such that  $x \xrightarrow{\varphi} \sigma(x)$ with $\sigma(\varphi) \circ \varphi = \id$}}/_{\cong}
\end{equation}
where $(x, \varphi)\cong (y, \psi)$  if there exists an arrow $f \colon x \to y$ in $R$ such that $\psi \circ f = \sigma(f) \circ \varphi$. This definition is motivated by the following example.
 \begin{example}\label{ex:realvsgroupoidintro}
 Let $\mathcal X$ be a Deligne--Mumford stack of finite type over $\RR$, and let $\mr X = [R(\CC)\rightrightarrows U(\CC)]$ be the topological groupoid with involution associated to $\mathcal X$ as in Example \ref{ex:stackvsgroupoidintro}. By the axioms of a stack over $\RR$, which imply that the objects and morphisms of $\ca X$ satisfy descent for étale coverings (see \cite[Définition (3.1), page 15]{laumon-moretbailly}), one has a canonical bijection $\va{\mr X^G} \cong \va{\ca X(\RR)}$. For details, see Lemma \ref{lemma:realDMstackasgrupoid2}.
 \end{example}
 %Let $\ca X$ be a separated Deligne--Mumford stack of finite type over $\RR$, and consider the functor $\sigma \colon \ca X(\CC) \to \ca X(\CC)$ that sends an object $x \in \ca X(\CC)$ to its pull-back along complex conjugation $ \Spec(\CC) \to \Spec(\CC)$. Let $\kappa \colon \sigma^2 \Rightarrow \id$ be the canonical isomorphism between $\sigma^2 \colon \ca X(\CC) \to \ca X(\CC)$ and the identity functor. By Galois descent, see \cite{grothendieck-descente-I}, the set of isomorphism classes $\vert \mathcal X(\mathbb R)\vert $ of objects in $\ca X(\RR)$ is naturally in bijection the set of isomorphism classes of pairs $(x,\varphi)$, where $x\in \mathcal X(\mathbb C)\vert$ and $\varphi \colon  x \xrightarrow{\sim} \sigma(x)$ is an isomorphism such that $\kappa \circ \sigma(\varphi) \circ \varphi = \id$ as isomorphisms $x \xrightarrow{\sim} x$. 
