\section{Notation and conventions} \label{sec:notation}
We let $G$ denote the finite group
$
G \coloneqq \Gal(\CC/\RR) \cong \ZZ/2,
$
and $\sigma \in G$ a generator. A topological groupoid $(U,R, s,t,c,e,i)$, consisting of topological spaces $U$ and $R$ and continuous maps $s,t \colon R \to U$, $c \colon R \times_{s,U,t} R \to R$, $e \colon U \to R$ and $i \colon R \to R$ that satisfy the usual compatibility conditions (see \cite[\href{https://stacks.math.columbia.edu/tag/0230}{Tag 0230}]{stacks-project}), will be denoted by $[R \rightrightarrows U]$. 

A \emph{variety} over $\RR$ (resp. $\CC$) will be a reduced and separated scheme of finite type over $\RR$ (resp.\ $\CC$). For a scheme $S$, and $(\Sch/S)_{fppf}$ a big fppf site of $S$ (cf.\ \cite[\href{https://stacks.math.columbia.edu/tag/021S}{Tag 021S}]{stacks-project}), an \emph{algebraic stack} over $S$ is a stack in groupoids $p \colon \ca X \to (\Sch/S)_{fppf}$ (see \cite[\href{https://stacks.math.columbia.edu/tag/0304}{Tag 0304}]{stacks-project}) which satisfies the conditions in \cite[\href{https://stacks.math.columbia.edu/tag/026O}{Tag 026O}]{stacks-project}. 
We will indicate an algebraic stack by a calligraphic letter, such as $\ca X, \ca Y, \ca Z$. Schemes are usually indicated by roman capitals, such as $X,Y,Z$. For an algebraic stack $\ca X$, we let $\ca I_{\ca X}\to \ca X$ denote the inertia stack over $\ca X$. When $\ca X$ is an algebraic stack over a scheme $S$, we let $\va{\ca X(S)}$ denote the set of isomorphism classes of the groupoid $\ca X(S)$.

An algebraic stack $\ca X$ over $S$ is a \emph{Deligne--Mumford stack} if there exists a scheme $U$ and a surjective \'etale morphism $U \to \ca X$. We will repeatedly use the following theorem by Keel and Mori \cite{keelmori}: if $\ca X$ is a separated Deligne--Mumford stack locally of finite type over a scheme $S$, there exists a coarse moduli space $\ca X \to M$. In particular, if $S = \Spec(\RR)$, then $M$ is an algebraic space locally of finite type over $\RR$, and hence its complex locus $M(\CC)$ has naturally the structure of a complex-analytic space (see \cite[Chapter I, Proposition 5.18]{knutson}) endowed with an anti-holomorphic involution with fixed locus $M(\RR)$. This provides the real locus $M(\RR)$ of $M$ with the structure of a closed real analytic subspace $M(\RR) \subset M(\CC)$ and in particular with a topology.

 %For an object $x \in \ca X(S)$, we let $[x] \in \va{\ca X(S)}$ denote its isomorphism class. 




\section{Topological groupoids with involution} \label{sec:preliminaries-top-groupoids}
In this section, we associate a groupoid of fixed points $\mr X^G$ to a topological groupoid $\mr X$ endowed with an involution $\sigma \colon \mr X \to \mr X$, and establish preliminary results concerning such groupoids. %Section \ref{sec:preliminaries-top-groupoids} is organized as follows. 
In Section \ref{sec:topstacks:top}, we recall the definition of topological groupoids and examine basic properties of their associated coarse spaces. In Section \ref{sec:topstacks:top:inv}, we introduce groupoids of fixed points, and provide examples. Finally, in Section \ref{sec:propfixpoint}, we prove structural properties of the groupoid of fixed points that will be used in later sections.


\subsection{Topological groupoids.} \label{sec:topstacks:top}
Recall that a topological groupoid is a groupoid object in the category of topological spaces (see e.g.\ \cite[Section 1]{crainic-moerdijk}). As such, a topological groupoid $\mr X = [R\rightrightarrows U]$ consist of two topological spaces, $U$ (the space of objects) and $R$ (the space of arrows), and a collection of continuous maps $s \colon R \to U$ (source), $t \colon R \to U$ (target), $c \colon R \times_{U} R \to R$ (composition), $e \colon U \to R$ (identity) and $i \colon R \to R$ (inversion), satisfying various natural compatibilities (see e.g.~\cite[\href{https://stacks.math.columbia.edu/tag/0230}{Tag 0230}]{stacks-project}).
%(see e.g. \cite[Section 2]{gursoy})
\begin{definition}
    One defines $\vert \mr X\vert = U/R = U/_{\cong}$, the set of isomorphism classes of objects $x \in U$, and one equips $\va{\mr X}$ with the quotient topology induced by $U \to \va{\mr X}$. The topological space $\va{\mr X}$ is called the \emph{coarse space} of the topological groupoid $\mr X$. 
\end{definition}
 For later use, we make the following observation. 
\begin{lemma} \label{lem:quotient-open}
   Assume that the target map $t \colon R \to U$ is open. Then the quotient map $\pi \colon U \to \va{\mr X} = U/R$ is open.
\end{lemma}
\begin{proof}
    For $B \subset U$ open, we have that $\pi^{-1}(\pi(B)) = t(s^{-1}(B))$ is open in $U$. Hence $\pi(B)$ is open in $U/R$. 
\end{proof}
In the classical Smith--Thom inequality \eqref{align:inequality-ST}, one assumes that the topological spaces are locally compact Hausdorff, see \cite{borel-seminar}. We give a criterion to guarantee that the coarse space of a topological groupoid is locally compact Hausdorff.
\begin{lemma}
    Let $\mr X = [R \rightrightarrows U]$ be a topological groupoid. Assume that $U$ and $R$ are locally compact Hausdorff. Suppose the quotient map $\pi \colon U \to \va{\mr X} = U/R$ is open and the map $(s,t) \colon R \to U \times U$ is closed. Then $\va{\mr X} = U/R$ is locally compact Hausdorff. 
\end{lemma}
\begin{proof}
    Let $Z \subset U \times U$ be the image of $(s,t) \colon R \to U \times U$. Let $\sim$ be the equivalence relation on $U$ such that $x \sim y$ if and only if $x=y$ or $(x,y) \in Z$. 
    Since $U$ is Hausdorff, $\pi \colon U \to U/_\sim = U/R$ is open and $Z \subset U \times U$ is closed, we have that $\va{\mr X} = U/_\sim$ is Hausdorff. Since $\pi$ is open and $U$ is locally compact, $\va{\mr X}$ is locally compact. 
    %For $[x] \in U/R$, let $x \in \pi^{-1}([x])$ and let $x \in U \subset K$ with $U$ open and $K$ compact. Then $[x] \in \pi(U) \subset \pi(K)$ with $\pi(U)$ open and $\pi(K)$ compact. 
\end{proof}

\subsection{Topological groupoids with involution.} \label{sec:topstacks:top:inv}
Recall that if  \( \mr{X}_1 = [R_1 \rightrightarrows U_1] \) and  \( \mr{X}_2 = [R_2 \rightrightarrows U_2] \) are two topological groupoids, then a morphism of topological groupoids $F\colon \mr{X}_1  \rightarrow \mr{X}_2 $ is a pair $(f,g)$ of continuous maps $f\colon R_1\rightarrow R_2$ and $g\colon U_1\rightarrow U_2$ compatible with all the structure maps of the groupoids. A \emph{topological $G$-groupoid} (or a \emph{topological groupoid with involution}) is a pair ($\mr X$, $\sigma$), where $\mr X$ is a topological groupoid and $\sigma\colon \mr X\rightarrow \mr X$ is an involution (i.e., a morphism that satisfies $\sigma^2=\id$). For topological $G$-groupoids $\mr X_1$ and $\mr X_2$, a morphism $F = (f,g) \colon \mr X_1 \to \mr X_2$ is called \emph{$G$-equivariant} if $f \colon R_1 \to R_2$ and $g \colon U_1 \to U_2$ commute with the involutions on both sides. 

Let \( \mr{X} = [R \rightrightarrows U] \) be a topological $G$-groupoid. We now define the appropriate analogue of the fixed locus of the involution. 

\begin{definition} \label{def:fix groupoid} 
The \emph{groupoid of fixed points} is the topological groupoid $\mr X^G \coloneqq  [\rm A^1(G,R) \rightrightarrows \rm Z^1(G,R)]$, where:
\begin{itemize}
    \item $\rm Z^1(G,R)$ is the subspace $\rm Z^1(G, R)\subset U \times R$ of pairs $(x, \varphi)$ such that $\varphi$ is an isomorphism $x \xrightarrow{\sim} \sigma(x)$ such that $\sigma(\varphi) \circ \varphi = \id$; in particular we have two natural maps $\rm Z^1(G,R) \to U, (x, \varphi)\mapsto x$ and $\rm Z^1(G,R) \to R, (x, \varphi) \mapsto \varphi$.
    \item $\rm A^1(G,R)$ is the fibre product $\rm A^1(G,R) = R \times_{s,U} \rm Z^1(G,R)$; more explicitly, an arrow $f \colon (x, \varphi) \to (x', \varphi')$ between two objects $(x,\varphi), (x', \varphi') \in \rm Z^1(G,R)$ is given by an arrow $f \in R$ with $s(f) = x$ and $t(f) = x'$, such that $\sigma(f) \circ \varphi = \varphi' \circ f$ as maps $x \to \sigma(x')$.
    \item The maps $s, t \colon \rm A^1(G,R) \to \rm Z^1(G,R)$ are defined as $s(f, (x, \varphi)) = (x, \varphi) = (s(f), \varphi)$ and $t(f, (x, \varphi)) = (t(x), \sigma(f) \circ \varphi \circ f^{-1})$.
    \item  The inversion map $i \colon \rm A^1(G,R) \to \rm A^1(G,R)$ is defined by sending an arrow $f \colon (x, \varphi) \to (x', \varphi')$ with $f \in R$ to the arrow $f^{-1} \in R$. The composition of two arrows is induced by the composition in $R$, and finally, the identity $e \colon \rm Z^1(G,R) \to \rm A^1(G,R)$ is defined by sending $(x, \varphi)$ to the identity $\id_x \colon (x, \varphi) \to (x, \varphi)$, where $\id_x \in R$ is the identity arrow of $x \in U$.
\end{itemize}
 With these arrows $(s, t, c, e, i)$, one can check that $\mr X^G =  [\rm A^1(G,R) \rightrightarrows \rm Z^1(G,R)]$ is indeed a topological groupoid. 
\end{definition}



