\begin{example} \label{ex:DM-top-stack}
Let $\mr T$ be a stack on the site of all topological spaces. Define an \emph{involution} on $\mr T$ to be a $1$-morphism $\sigma \colon \mr T \to \mr T$ such that $\sigma^2$ is $2$-isomorphic to the identity functor (where $2$-isomorphic should be taken in the sense of \cite[\href{https://stacks.math.columbia.edu/tag/02ZK}{Tag 02ZK}]{stacks-project}). Say that a  \emph{topological $G$-stack} consists of a topological stack $\mr T$ in the sense of \cite[Section 2]{noohi-2012} and an involution $\sigma$ on $\mr T$, such that there exists a representable surjective morphism $p \colon U \to \mr T$ where $U$ is a topological space equipped with an involution $\sigma_U \colon U \to U$ that $2$-commutes with $\sigma$ and $p$. %Let $(\mr T, \sigma)$ be a topological $G$-stack. 
For such a stack $\mr T$ with presentation $p \colon U \to \mr T$, let $R$ be a topological space with $R \cong U \times_{\mr T}U$. Then $R$ carries a natural involution $\sigma_R \colon R \to R$ induced by $\sigma$ and $\sigma_U$, %defined by the involution $(x,y, \phi) \mapsto (\sigma_U(x), \sigma_U(y), \sigma(\phi))$ on $U \times_{\mr T}U$, %where $\sigma(\phi)$ is the map $p(\sigma_U x) \to p(\sigma_U y)$ induced by the map $\sigma(px) \to \sigma(py)$. 
and the involutions $\sigma_U$ and $\sigma_R$ induce on $\mr X = [R \rightrightarrows U]$ the structure of a topological $G$-groupoid.
\end{example}

\begin{example} \label{ex:fixed-BGamma}
If $\Gamma$ is a finite group equipped with an involution $\sigma \colon \Gamma \to \Gamma$, and if $\mr X = B\Gamma = [\Gamma \rightrightarrows \rm{pt}]$ is the classifying groupoid of $\Gamma$, then there is a natural isomorphism of topological groupoids
    $$
    \mr X^G = \coprod_{[\gamma] \in \rm H^1(G, \Gamma)} B(\Gamma^{\sigma_\gamma})
    $$
    where, for an element $\gamma \in \Gamma$ with $\gamma \sigma(\gamma) = e$, the subgroup $\Gamma^{\sigma_\gamma}\subset \Gamma$ consists of those elements $g\in \Gamma$ such that $\gamma\sigma(g)=g\gamma$. 
\end{example}
\subsection{Properties of the groupoid of fixed points.}\label{sec:propfixpoint}
In order to prove Theorem \ref{theorem:indepencence-topology-intro}, we need Proposition \ref{proposition:topological-indepence-Ggroupoids} below, which is the main result of this section. %We are almost ready to prove the main result of Section \ref{sec:preliminaries-top-groupoids}, which is Proposition \ref{proposition:topological-indepence-Ggroupoids} below. 
This proposition roughly says that the formation of $\va{\mr X^G}$ is invariant under a base change $U' \to U$ with suitable properties. To prove it, we need a definition and two lemmas.

\begin{definition}\label{def:open-equivalence}(Compare \cite[Section 1.5]{crainic-moerdijk}.) Let $\mr X_1 = [R_1 \rightrightarrows U_1]$ and $\mr X_2 = [R_2 \rightrightarrows U_2]$ be topological groupoids, 
and let $F\colon \mr X_2 \to \mr X_1$ be a morphism of topological groupoids, defined by a pair of compatible maps $(f \colon U_2 \to U_1, g \colon R_2 \to R_1)$.
%Assume that the maps $s,t \colon R_i \to U_i$ are surjective and open for $i = 1,2$. 
We say that $F$ is an \emph{open equivalence} if the following conditions hold: the map $f \colon U_2 \to U_1$ is open, the composition
\begin{align} \label{align:comp-surj-homeo-def}
R_1 \times_{s,U_1}U_2 \to R_1 \xrightarrow{t}U_1
\end{align}
is open and surjective, and the diagram 
\begin{align}\label{align:diagram:zero:H1A1R1-def}
\begin{split}
\xymatrix{
R_2 \ar[d]^{(s,t)}\ar[r]^{g} & R_1 \ar[d]^{(s,t)} \\
U_2 \times U_2 \ar[r]^{f \times f} & U_1 \times U_1
}
\end{split}
\end{align}
is cartesian.
\end{definition}

%Thus, we see in view of Lemma \ref{lem:quotient-open} that the quotient map $\rm Z^1(G,R) \to \vert \mr X^G \vert$ is open. 



 %In turn, this proposition will provide the key to prove Theorem \ref{theorem:indepencence-topology-intro} in the next Section \ref{sec:topgrp-DM}. 
%We first need a definition and a lemma.


\begin{lemma} \label{lemma:open-equivalence-homeomoprhism}
    Let $F \colon \mr X_2 \to \mr X_1$ be a morphism of topological groupoids $\mr X_i = [R_i \rightrightarrows U_i]$ for which $s,t \colon R_i \to U_i$ are surjective and open ($i = 1,2$), and assume that $F$ is an open equivalence. Then the induced map $\va{F} \colon \va{\mr X_2} \to \va{\mr X_1}$ is a homeomorphism. 
\end{lemma}
\begin{proof}
Note first that $\va{F}$ is bijective. Indeed, the surjectivity of \eqref{align:comp-surj-homeo-def} implies that each $x \in U_1$ is isomorphic to an object in the image of $f \colon U_2 \to U_1$, hence $\va{F}$ is surjective; the injectivity of $\va{F}$ follows from from the fact that diagram \eqref{align:diagram:zero:H1A1R1-def} is cartesian.
%which implies that for each $a,b \in U_2$ and each isomorphism $\varphi \colon f(a) \cong f(b)$ with $\varphi \in R_1$, there exists a unique isomorphism $\psi \colon a \cong b$ with $\psi \in R_2$ such that $g(\psi)= \varphi$.

The map $\va{F}$ is continuous (since $\va{F}$ lifts to a continuous map $U_2 \to U_1$) hence it remains to prove that $\va{F}$ is open. This holds in view of the commutative diagram 
\[
\xymatrix{
U_1 \ar[r]^f \ar@{->>}[d]\ar[r] & U_2 \ar@{->>}[d] \\
U_1/R_1 \ar[r]^{\va{F}} & U_2/R_2,
}
\]
since the vertical arrows are open by Lemma \ref{lem:quotient-open} and the upper horizontal arrow is open by assumption. 
\end{proof}

\begin{lemma} \label{lemma:st-open}
    Let $\mr X = [R \rightrightarrows U]$ be a topological $G$-groupoid. Assume that the maps $s, t\colon R \to U$ are surjective and open. Then the maps $s,t\colon \rm A^1(G,R) \to \rm Z^1(G,R)$ are surjective and open. Similarly, if $s,t \colon R \to U$ are local homeomorphisms, the same holds for $s,t \colon \rm A^1(G,R) \to \rm Z^1(G,R)$.
\end{lemma}
\begin{proof}
%By definition of $\rm A^1(G,R)$, we have 
%\[
%\rm A^1(G,R) = R \times_{s,U} \rm Z^1(G,R);
%\]
Since the inversion $i \colon \rm A^1(G,R)  \xrightarrow{\sim} \rm A^1(G,R)$ is a homeomorphism, and since $s \circ i = t$ as maps $\rm A^1(G,R) \to \rm Z^1(G,R)$,  the assertions for $t$ follow from the assertions for $s$. The assertions for $s$ follow from the fact that the following diagram is cartesian:
\[
\xymatrix{
\rm A^1(G,R) \ar[d] \ar[r]^-s & \rm Z^1(G,R) \ar[d] \\
R \ar[r]^-s & U.
}
\]
This ends the proof. 
\end{proof}

\begin{proposition} \label{proposition:topological-indepence-Ggroupoids}
Let $\mr X_1 = [R_1 \rightrightarrows U_1]$ and $\mr X_2 = [R_2 \rightrightarrows U_2]$ be topological $G$-groupoids, such that the maps $s,t \colon R_i \to U_i$ are surjective and open for $i = 1,2$. Let $F\colon \mr X_2 \to \mr X_1$ be a $G$-equivariant open equivalence. 
Then the map $$F^G \colon \mr X_2^G \to \mr X_1^G$$ is an open equivalence. In particular, the map
$\va{F^G} \colon \va{\mr X_2^G}\to \va{\mr X_1^G}
$
is a homeomorphism. 
\end{proposition}
\begin{proof}
Let $f\colon U_2\rightarrow U_1$ and $g\colon R_2\rightarrow R_1$ be the maps corresponding to $F$. 
By Lemma \ref{lemma:open-equivalence-homeomoprhism}, it suffices to prove that the map $F^G \colon \mr X_2^G \to \mr X_1^G$ is an open equivalence. Note that $s,t \colon \rm A^1(G,R_i) \to \rm Z^1(G,R_i)$ are surjective and open by Lemma \ref{lemma:st-open}. By construction, the map $\rm Z^1(G,R_i) \to R_i$ defined as $(x, \varphi) \mapsto \varphi$ is an embedding. For $i = 1,2$, consider the restriction $(s,t) \colon \rm Z^1(G,R_i) \to U_i \times U_i$ of the map $(s,t) \colon R_i \to U_i \times U_i$ to $\rm Z^1(G,R_i)$. Observe that the diagram
\[
\xymatrix{
\rm Z^1(G,R_2) \ar[d]^f \ar[r]^{(s,t)} & U_2 \times U_2 \ar[d]^{f \times f} \\
\rm Z^1(G, R_1) \ar[r]^{(s,t)} & U_1 \times U_1
}
\]
is cartesian. As $U_2 \times U_2 \to U_1 \times U_1$ is open, it follows that the map $\rm Z^1(G,R_2) \to \rm Z^1(G,R_1)$ is open.

Next, %we claim that the composition
%\begin{align} %\label{align:comp-surj-homeo-fixed-proof}
%\rm A^1(G,R_1) \times_{s,\rm Z^1(G,R_1)}\rm Z^1(G,R_2) \to \rm A^1(G,R_1) \xrightarrow{t}\rm Z^1(G,R_1)
%\end{align}
%is surjective. To prove this, 
observe that the squares in the following diagram are cartesian:
\[
\xymatrix{
\rm A^1(G,R_1) \times_{s,\rm Z^1(G,R_1)} \rm Z^1(G,R_2)\ar[d] \ar[r] & \rm A^1(G,R_1) \ar[r]^-t \ar[d]& \rm Z^1(G,R_1)\ar[d] \\
R_1 \times_{s,U_1} U_2 \ar[r] & R_1 \ar[r]^-t & U_1.
}
\]
Consequently, since the bottom row is surjective, the top row is surjective as well. 

It remains to show that the diagram
\begin{align*}%\label{align:diagram:carteisna:H1A1R1-proof}
\begin{split}
\xymatrix{
\rm A^1(G,R_2) \ar[d]^{(s,t)}\ar[r]^{g} & \rm A^1(G,R_1) \ar[d]^{(s,t)} \\
\rm Z^1(G,R_2) \times \rm Z^1(G,R_2) \ar[r]^{f \times f} & \rm Z^1(G,R_1) \times \rm Z^1(G,R_1)
}
\end{split}
\end{align*}
is cartesian. This follows from the fact that \eqref{align:diagram:zero:H1A1R1-def} is cartesian and we are done.
\end{proof}

\section{Topological groupoids and Deligne--Mumford stacks} \label{sec:topgrp-DM}
The goal of this section is to prove Theorem \ref{theorem:indepencence-topology-intro}. To that end, in Section \ref{sec:topstacks}, we recall the relationship between topological groupoids and complex Deligne–Mumford stacks. In Section \ref{sec:topstacksrel}, we explain how to associate a topological groupoid with involution to a real Deligne–Mumford stack. Section \ref{sec:realanalytictopology} is devoted to recalling the definition of the real analytic topology on a real Deligne–Mumford stack, to stating Theorem \ref{theorem:indepencence-topology} -- which is a reformulation of Theorem \ref{theorem:indepencence-topology-intro} in the introduction -- and to proving this theorem by using the preliminary results from Section \ref{sec:preliminaries-top-groupoids}. 


\subsection{Topological groupoids arising from complex Deligne-Mumford stacks.} \label{sec:topstacks}
For a Deligne--Mumford stack $\ca X$ locally of finite type over $\CC$, we view the set of isomorphism classes $\va{\ca X(\CC)}$ of the groupoid $\ca X(\CC)$ as a topological space, by equipping it with the quotient topology induced by the surjective morphism $U(\CC) \to \va{\ca X(\CC)}$, where $U$ is a scheme and $U \to \ca X$ a surjective \'etale morphism. This topology on $\va{\ca X(\CC)}$ does not depend on the choice of \'etale presentation $U \to \ca X$.  Every complex Deligne--Mumford stack gives rise to a topological groupoid in the following way. 

\begin{construction} \label{cons:groupoid-DM}
Let $\mathcal X$ be a complex Deligne--Mumford stack, so that there exists an \'etale surjective presentation $\pi \colon U\rightarrow \mathcal X$ by a scheme. Let $R$ be a scheme with $R \cong U \times_{\ca X} U$, so that the two projection maps $U \times_{\ca X} U \to U$ yield two maps $R \to U$ that turn $[R \rightrightarrows U]$ into a groupoid scheme. Then $\mr X = [R(\CC) \rightrightarrows U(\CC)]$ is a topological groupoid. %with objects $U(\CC)$ and arrows $R(\CC)$

Via the bijection $R(\CC) \cong \left( U \times_{\ca X} U \right)(\CC)$, any $r \in R(\CC)$ corresponds to an element $(x,y,\alpha) \in (U \times_{\ca X}U)(\CC)$ consisting of two elements $x, y \in U(\CC)$ and an isomorphism $\alpha \colon \pi(x) \xrightarrow{\sim} \pi(y)$. This yields a functor $F \colon \mr X \to \ca X(\CC)$ that sends an object $x \in U(\CC)$ to the object $\pi(x) \in \ca X(\CC)$ and an arrow $r = (x,y,\alpha)  \in R(\CC)$ to the isomorphism $\alpha \colon \pi(x) \xrightarrow{\sim} \pi(y)$. The functor $F \colon \mr X \to \ca X(\CC)$ is an equivalence of categories. 
\end{construction}
Let $\ca X$ be a Deligne--Mumford stack of finite type over $\CC$. If $\ca X$ is separated, then it has a coarse moduli space $\ca X \to M$ by \cite{keelmori}. By Construction \ref{cons:groupoid-DM} and Lemma \ref{lem:quotient-open}, it follows that the map $\va{\ca X(\CC)} \to M(\CC)$ is a homeomorphism (this can also been seen by using that $\ca X$ is \'etale locally over $M$ a finite quotient stack, see \cite[Lemma 2.2.3]{abramvistoli-2002}). 

\subsection{Topological groupoids arising from real Deligne--Mumford stacks.} \label{sec:topstacksrel}

We will often make use of the following definition.

\begin{definition}
A \emph{real DM stack} is a separated Deligne--Mumford stack of finite type over $\RR$. 
\end{definition}
Every real DM stack $\ca X$ give rise to a topological $G$-groupoid $(\mr X, \sigma)$ in the following way. \begin{construction}\label{ex:realDMstackasgrupoid}
Let $\mathcal X$ be a real DM stack, and choose a scheme $U$ over $\RR$ and an \'etale surjective morphism $U \to \ca X$. Let $R$ be a scheme with $R \cong U \times_{\ca X} U$, so that we get a groupoid scheme $[R \rightrightarrows U]$, see Construction \ref{cons:groupoid-DM}.  
Since $U$ and $R$ are schemes locally of finite type over $\RR$, $U(\mathbb C)$ and $R(\mathbb C)$ admit natural anti-holomorphic involutions $\sigma \colon U(\CC) \to U(\CC)$ and $\sigma \colon R(\CC) \to R(\CC)$,  compatible with the structure maps of the groupoid. 
Hence  $[R(\mathbb C)\rightrightarrows U(\mathbb C)]$ is a topological groupoid with involution. 
\end{construction}

 Let $\mr X = [R(\CC) \rightrightarrows U(\CC)]$ be the topological groupoid with involution associated to a real Deligne-Mumford stack $\ca X = [U/R]$ as in Construction \ref{ex:realDMstackasgrupoid}. We aim to construct a natural equivalence of categories $F \colon \mr X^G \to \ca X(\RR)$. 

 To do this, recall that any $r \in R(\CC) =  \left(U \times_{\ca X}U\right)(\CC)$ corresponds to a triple $r = (x, y, \alpha)$ with $x ,y \in U(\CC)$ and $\alpha \colon \pi(x) \xrightarrow{\sim} \pi(y)$ an isomorphism, where $\pi$ is the map $U \to \ca X$. Thus, we have $$\rm Z^1(G, R(\CC)) = \set{\omega = (x, (x, \sigma(x), \varphi)) \in U(\CC) \times R(\CC) \mid \sigma(\varphi) \circ \varphi = \id}.$$ For $\omega = (x, (x, \sigma(x), \varphi)) \in \rm Z^1(G, R(\CC))$, we get an element $\pi(x) \in \ca X(\CC)$ and an isomorphism $\varphi \colon  \pi(x) \xrightarrow{\sim} \pi(\sigma(x))$ such that $\sigma(\varphi) \circ \varphi = \id$. Since, by definition, the objects of $\ca X$ satisfy descent for étale coverings (see \cite[Définition (3.1), page 15]{laumon-moretbailly}), %one has a canonical bijection $\va{\mr X^G} \cong \va{\ca X(\RR)}$.
 %By Galois descent (cf.\ \cite{grothendieck-descente-I}), 
 this yields an object $F(\omega) \in \ca X(\RR)$. Similarly, any arrow  $f \colon \omega \to \omega'$, $f \in \rm A^1(G,R(\CC))$, is given by an arrow $f = (x,x',\alpha) \in R(\CC)$ such that $\varphi' \circ \alpha = \sigma(\alpha) \circ \varphi$ as maps $\pi(x) \to \pi(\sigma(x'))$, and this yields an arrow $F(f) \colon F(\omega) \to F(\omega')$ in $\ca X(\RR)$, again by the stack axioms (see \cite[Définition (3.1), page 15]{laumon-moretbailly}). 
 This gives a natural functor 
 $$F \colon \mr X^G \to \ca X(\RR).$$
 \begin{lemma}\label{lemma:realDMstackasgrupoid2} The functor $F \colon \mr X^G \to \ca X(\RR)$ is an equivalence of categories. In particular, we get a bijection $\va{F} \colon \va{\mr X^G} \xrightarrow{\sim} \va{\ca X(\RR)}$. \end{lemma}
\begin{proof}
Since $\ca X$ is a stack over $\RR$, the objects and morphisms of $\ca X$ satisfy descent for étale coverings (see \cite[Définition (3.1), page 15]{laumon-moretbailly}); the lemma follows. 
\end{proof}

\begin{proposition}\label{prop:independence}
    Let $\ca X$ be a real DM stack. Let $U$ be a scheme with a surjective \'etale morphism $U \to \ca X$, consider the resulting topological $G$-groupoid $\mr X = [R(\CC) \rightrightarrows U(\CC)]$ (cf.\ Construction \ref{ex:realDMstackasgrupoid}). Then the topology on $\va{\ca X(\RR)}$ induced by the topology of $\va{\mr X^G}$ and the bijection $\va{F} \colon \va{\mr X^G} \xrightarrow{\sim} \va{\ca X(\RR)}$ of Lemma \ref{lemma:realDMstackasgrupoid2} does not depend on the choice of the surjective \'etale presentation $U \to \ca X$. 
    % 
\end{proposition}
\begin{proof}
    Let $U_i \to \ca X$ ($i = 1,2$) be two surjective \'etale morphisms with $U_i$ schemes, and let $R_i$ be schemes with $R_i \cong U_i \times_{\ca X} U_i$. Let $U_3$ be a scheme with an isomorphism $U_3 \cong U_1 \times_{\ca X}U_2$. Let $R_3$ be a scheme with an isomorphism $R_3 \cong U_3 \times_{\ca X} U_3$. By Construction \ref{ex:realDMstackasgrupoid}, this defines three topological $G$-groupoids 
$
\mr X_i \coloneqq [R_i(\CC) \rightrightarrows U_i(\CC)]$ $(i = 1,2,3)$. Then, for $i = 1,2$, we obtain a $G$-equivariant morphism of topological $G$-groupoids 
$
\Phi_i \colon \mr X_3 \to \mr X_i.
$
We claim that for $i = 1,2$, the morphism $\Phi_i$ is an open equivalence (in the sense of Definition \ref{def:open-equivalence}). To prove this, note that %\begin{align*}
%\left(U_3 \times_\RR U_3\right) \times_{(U_1 \times_\RR U_1)} R_1
%\cong
%\left(U_3 \times_\RR U_3\right) \times_{(U_1 \times_\RR U_1)} \left(U_1 \times_{\ca X} U_1 \right) 
%\cong
%U_3 \times_{\ca X}U_3 \cong R_3.
%\end{align*}
$R_3 \cong \left(U_3 \times_\RR U_3\right) \times_{(U_1 \times_\RR U_1)} R_1$
and $R_3 \cong \left(U_3 \times_\RR U_3\right) \times_{(U_2 \times_\RR U_2)} R_2$. 
Moreover, since $U_3 \to U_i$ is \'etale for $i =1,2$, the resulting maps $U_3(\CC) \to U_1(\CC)$ and $U_3(\CC) \to U_2(\CC)$ are local homeomorphisms (see \cite[Exposé XII, Proposition 3.1 \& Remarque 3.3]{SGA1}). In particular, the maps $U_3(\CC) \to U_i(\CC)$ are open for $i = 1,2$. As the map $U_3(\CC) \to U_i(\CC)$ is surjective for $i =1,2$, the composition $R_i(\CC) \times_{s,U_i(\CC)}U_3(\CC) \to R_i(\CC) \xrightarrow{t}U_i(\CC)
$ is surjective for $i = 1,2$, proving the claim.

Consequently, by Proposition \ref{proposition:topological-indepence-Ggroupoids}, the induced maps 
$
\va{\mr X_1^G} \leftarrow \va{\mr X_3^G} \rightarrow \va{\mr X_2^G}
$
are homeomorphisms. This proves the proposition.
\end{proof}

\subsection{The real analytic topology of a real DM stack.}\label{sec:realanalytictopology} For a real DM stack $\ca X$, the set of isomorphism classes $\va{\ca X(\RR)}$ of its real locus $\ca X(\RR)$ has a natural topology, generalizing the euclidean topology on $X(\RR)$ when $X$ is a scheme. Indeed, we have the following theorem. 
\begin{theorem} \label{theorem:DGF-reallocusstack}
Let $\ca X$ be a real DM stack. There exists a scheme $U$ over $\RR$ and a surjective \'etale morphism $U \to \ca X$ such that $U(\RR) \to \va{\ca X(\RR)}$ is surjective. 
\end{theorem}
\begin{proof}
See \cite[Theorem 2.9]{thesis-degaayfortman} or \cite[Theorem 7.4]{degaay-realmoduli}.  
\end{proof}
\begin{definition}(cf.\ \cite[Definition 7.5]{degaay-realmoduli}) \label{def:real-an-top}
    Let $\ca X$ be a real DM stack. The \emph{real analytic topology} on $\va{\ca X(\RR)}$ is defined as follows. Choose a scheme $U$ over $\RR$ and a surjective \'etale morphism $U \to \ca X$ such that $U(\RR) \to \va{\ca X(\RR)}$ is surjective. Then consider the real analytic topology on $U(\RR)$, and give $\va{\ca X(\RR)}$ the quotient topology induced by the surjection $U(\RR) \to \va{\ca X(\RR)}$. 
\end{definition}

One shows that the real analytic topology is independent of the choice of an étale presentation that is essentially surjective on real points, see \cite[Proposition 7.6]{degaay-realmoduli}.
Let now $\mathcal X$ be a real DM stack and fix a surjective \'etale morphism $U \to \ca X$. % such that $U(\RR) \to \va{\ca X(\RR)}$ is surjective (cf.\ Theorem \ref{theorem:DGF-reallocusstack}). 
Let $\mr X = [R(\CC) \rightrightarrows U(\CC)]$ be the topological groupoid with involution associated to a real Deligne-Mumford stack $\ca X = [U/R]$ as in Construction \ref{ex:realDMstackasgrupoid}. %The equivalence of categories of Lemma \ref{lemma:realDMstackasgrupoid2} induces a natural bijection of topological spaces
%$$\va{F} \colon \va{\mr X^G} \xrightarrow{\sim} \va{\ca X(\RR)}.$$
\begin{theorem}\label{theorem:indepencence-topology}
Consider the groupoid of fixed points $\mr X^G$, see Definition \ref{def:fix groupoid}, with attached topological space $\va{\mr X^G}$. Consider $\va{\ca X(\RR)}$ as a topological space via the real analytic topology. 
 The bijection $\va{F} \colon \va{\mr X^G} \cong \va{\ca X(\RR)}$ of Lemma \ref{lemma:realDMstackasgrupoid2} is a homeomorphism. 
\end{theorem}
\begin{proof}
By Proposition \ref{prop:independence}, to prove the theorem, we may replace our surjective \'etale morphism $U \to \ca X$ by any other surjective \'etale morphism $U' \to \ca X$ with $U'$ a scheme. In particular, by Theorem \ref{theorem:DGF-reallocusstack}, we may assume that $U(\RR) \to \va{\ca X(\RR)}$ is surjective. By definition of the real analytic topology on $\va{\ca X(\RR)}$, it therefore suffices to show that the topology of $\va{\mr X^G}$ agrees with the quotient topology induced by the surjection $U(\RR) \to \va{\mr X^G}$ and the real analytic topology of $U(\RR)$. This holds, because the map $U(\RR) \to \va{\mr X^G}$ is open by Lemmas \ref{lem:quotient-open} and \ref{lemma:st-open}. We are done. 
\end{proof}
