\begin{proposition}\label{lem:dm-flatness}
Let $\ca X$ be a separated Deligne--Mumford stack locally of finite type over $\CC$. Consider the following assertions.
\begin{enumerate}
    \item \label{item:ii}
The inertia $\pi\colon \ca I_{\ca X} \to \ca X$ is \'etale over $\ca X$. 
\item \label{item:iii}The inertia $\pi\colon \ca I_{\ca X} \to \ca X$ is flat over $\ca X$. 
\item \label{item:iv}The coarse moduli space map $\ca X \to M$ is a gerbe. 
\item \label{item:i}We have that $\# \Aut(x)$ is locally constant for $x \in \ca X(\CC)$. 
\end{enumerate}
Then $\ref{item:ii}\Leftrightarrow \ref{item:iii}\Leftrightarrow \ref{item:iv}\Rightarrow \ref{item:i}$. If $\ca X$ is reduced, then all four assertions are equivalent. 
\end{proposition}
\begin{proof}
We start by proving the equivalence of \ref{item:iii} and \ref{item:iv}.
Note that $\pi \colon \ca I_{\ca X} \to \ca X$ is finite by Lemma \ref{cor:coarse-proper}. Therefore, 
by \cite[\href{https://stacks.math.columbia.edu/tag/06QJ}{Tag 06QJ}]{stacks-project}, the morphism $\pi \colon \ca I_{\ca X} \to \ca X$ is flat if and only if $\ca X$ is a gerbe. Hence, we need to prove that $\ca X$ is a gerbe if and only if $\ca X$ is a gerbe over $M$. By definition, if $\ca X$ is a gerbe over $M$ then $\ca X$ is a gerbe. Conversely, assume that $\ca X$ is a gerbe. Let $\pi_0(\ca X)^{sh}$ be the sheafification of the presheaf $U \mapsto \rm{Ob}(\ca X(U))/_{\cong}$ on the site $(\Sch/\CC)_{fppf}$. By \cite[\href{https://stacks.math.columbia.edu/tag/06QD}{Tag 06QD}]{stacks-project}, we have that $\pi_0(\ca X)^{sh}$ is an algebraic space. On the one hand, by \cite[Lemme 3.18, page 23]{laumon-moretbailly}, the morphism $\ca X \to M$ factors uniquely as $\ca X \to \pi_0(\ca X)^{sh} \to M$. 
    On the other hand, since $\ca X \to M$ is the coarse moduli space of $\ca X$ and since $\pi_0(\ca X)^{sh}$ is an algebraic space, the morphism $\ca X \to \pi_0(\ca X)^{sh}$ factors uniquely as $\ca X \to M \to \pi_0(\ca X)^{sh}$. This proves that $M \cong \pi_0(\ca X)^{sh}$. Finally, by \cite[\href{https://stacks.math.columbia.edu/tag/06QD}{Tag 06QD}]{stacks-project}, the natural morphism $\ca X \to \pi_0(\ca X)^{sh}$ turns $\ca X$ into a gerbe over $\pi_0(\ca X)^{sh} \cong M$. This proves the equivalence of assertions \ref{item:iii} and \ref{item:iv}. 

Trivially, assertion \ref{item:ii} implies assertion \ref{item:iii}. Moreover, as a finite flat group scheme of order invertible in the base is finite étale, flatness of $\pi$ implies \'etaleness of $\pi$. Thus, assertions \ref{item:ii} and \ref{item:iii} are equivalent, and assertion \ref{item:ii} readily implies assertion \ref{item:i}.

To conclude the proof, it is enough to show that assertion \ref{item:i} implies assertion \ref{item:iii} if $\ca X$ is reduced. So, assume that $\ca X$ is reduced and that $\# \Aut(x)$ is locally constant for $x \in \ca X(\CC)$.  Since $\ca X$ is reduced, there exists a reduced scheme $U$ and a surjective \'etale morphism $U \to \ca X$. Let $x \in \ca X(U)$ be the object corresponding to $U \to \ca X$. We have ${\ca I_{\ca X}} \times_{\ca X} U = \underline{\Aut}_U(x) \to U$, the automorphism group scheme of $x$ over $U$, and by \cite[\href{https://stacks.math.columbia.edu/tag/04XD}{Tag 04XD}]{stacks-project}, it suffices to show that $\underline{\Aut}_U(x) \to U$ is flat. By Lemma \ref{cor:coarse-proper}, the morphism $\underline{\rm{Aut}}_U(x) \to U$ is finite, and by Cartier's theorem it has reduced fibres. As $\#\Aut(x)$ is locally constant for $x \in \ca X(\CC)$, it follows that the function $\rho \colon U \to \ZZ$ defined as $\rho(u) = \dim_{k(u)}(f_U^{-1}(y))$ is locally constant; since $U$ is reduced, $\underline{\rm{Aut}}_U(x) \to U$ is therefore flat by \cite[\href{https://stacks.math.columbia.edu/tag/00NX}{Tag 00NX}]{stacks-project} and \cite[\href{https://stacks.math.columbia.edu/tag/0FWG}{Tag 0FWG}]{stacks-project}. 
\end{proof}
\subsection{The fibers of the maps $\va{\mathcal I_{\mathcal X}(\CC)}\rightarrow \va{\mathcal X(\CC)}$ and $\va{\mathcal X(\mathbb R)}\rightarrow M(\mathbb R)$.}\label{fibers}

For later use, and to provide further motivation for Conjecture \ref{conj:ST-top}, we show that, in the case of a stacky quotient $\ca X = [X/\Gamma]$ of a real scheme $X$ by a finite group $\Gamma$, the fibers of the maps $\pi \colon \va{\ca I_{\mathcal X}(\mathbb 
 C)} \rightarrow \vert\ca X(\CC)\vert = (X/\Gamma)(\CC)$ and $f \colon \vert \mathcal X(\mathbb R)\vert \rightarrow (X/\Gamma)(\mathbb R)$ are closely related. For example, by combining Propositions \ref{prop:fibres-of-inertia} and \ref{prop:fibre-H1}, one sees that for a point \( x \in X(\mathbb{R}) \) with image \( y \in (X/\Gamma)(\mathbb{R}) \), we have  
$
\pi^{-1}(y) = \Gamma_x / \Gamma_x$ and $f^{-1}(y) = \mathrm{H}^1(G, \Gamma_x).
$
\subsubsection{Fibres of the coarse inertia map.} Let $S$ be a scheme of finite type over $\mathbb C$. Let $X$ be a scheme and $f\colon X \to S$ a scheme of finite type over $S$. Let $H \to S$ be a finite group scheme over $S$, equipped with an action on $X$ over $S$. 

Define $\ca X$ as the quotient stack $[X/H]$, which we view as a stack over $\CC$ equipped with a natural morphism $\ca X \to S$.  Let $q \colon X(\CC) \to \va{\ca X(\CC)}$ be the natural map of spaces over $S(\CC)$, giving the quotient map $q_s\colon X_s(\CC) \to \va{\ca X(\CC)}_s = X_s(\CC)/H_s(\CC)$ for $s \in S(\CC)$. 
Consider the canonical map $\va{\pi} \colon \va{\ca I_{\ca X}(\CC)} \to \va{\ca X(\CC)}$ of topological spaces over $S(\CC)$. 

\begin{proposition}  \label{prop:fibres-of-inertia}
In the above notation, the following holds. 
\begin{enumerate}
\item There is a canonical bijection \begin{align} \label{align:inertia-description}
\va{\ca I_{\ca X}(\CC)}= \set{\left(x \in X(\CC), \gamma \in \Stab_{H_{f(x)}(\CC)}(x) \right)} /_{\sim}
\end{align}
where $(x,\gamma) \sim (gx, g\gamma g^{-1})$ for $g \in H_{f(x)}(\CC)$. 
\item Fix $s \in S(\CC)$, and consider the induced map $\va{\pi}_s \colon \va{\ca I_{\ca X}(\CC)}_s \to \va{\ca X(\CC)}_s$. Fix $x \in \va{\ca X(\CC)}_s$. 
There is a canonical bijection
\begin{align}\label{align:item222}
\va{\pi}^{-1}_s(x) = \left( \coprod_{y \in q_s^{-1}(x)} \Gamma_{y} \right)/\Gamma \quad \quad \left(\Gamma = H_s(\CC), \quad \Gamma_y = \Stab_\Gamma(y)\right).
\end{align}
Here, $g \in \Gamma$ acts on $\bigsqcup_{y \in q_s^{-1}(x)} \Gamma_{y}$ as follows: for $y \in q^{-1}(x)$, $\gamma \in \Gamma_y$, we define 
$
g \cdot (y, \gamma) = (gy, g \gamma g^{-1})$. In particular, for fixed $y'\in q^{-1}_s(x)$, there are bijections
\begin{align} \label{align:bij-stab-non-can}
\va{\pi}^{-1}_s(x) = \left( \coprod_{y \in q_s^{-1}(x)} \Gamma_{y} \right)/\Gamma 
\cong \Gamma_{y'} /\Gamma_{y'},
\end{align}
of which the second one is in general non-canonical. 
\end{enumerate}

\end{proposition}
\begin{proof}
Let $\rm{Stab}_S \to X$ be the stabilizer group scheme attached to the action of $H$ on $X$ over $S$. Then
$
\rm{Stab}_S(\CC) = \set{(x, \gamma) \in X(\CC) \times_{S(\CC)} H(\CC) \mid \gamma x = x}$. The group scheme $H$ acts on the scheme $\rm{Stab}_S$ over $S$ by 
$
g \cdot (x, \gamma) = (gx, g\gamma g^{-1})$ for $(g, (x, \gamma)) \in H \times_S \rm{Stab}_S$. 
We have a canonical isomorphism of stacks 
$
\ca I_{\ca X} = [\rm{Stab}_S/H]$ (see e.g.\ \cite[Exercise 3.2.12]{notesstack}). In particular, \eqref{align:inertia-description} follows. This proves item 1. Then \eqref{align:item222} follows from item 1. It remains to provide the second bijection in \eqref{align:bij-stab-non-can}. This holds, since for each $y_1, y_2 \in q^{-1}(x)$, there exists $g \in \Gamma$ such that $g y_1 = y_2$ and $g\Gamma_{y_1} g^{-1} = \Gamma_{y_2}$. 
\end{proof}

