\subsubsection{Fibres of the map to the real locus of the coarse moduli space.} The next proposition allows one to understand the fibres of the map on real loci $\va{\ca X(\RR)} \to M(\RR)$ induced by the coarse moduli space map $\ca X \to M$ of a real DM stack $\ca X$.
\begin{proposition} \label{prop:fibre-H1}
    Let $\ca X$ be a real DM stack, with coarse moduli space $p \colon \ca X \to M$. Let $f \colon \vXR \to M(\RR)$ denote the map induced by $p$, and let $x \in \ca X(\RR)$ with isomorphism class $[x] \in \va{\ca X(\RR)}$ (cf.\ Section \ref{sec:notation}).
    \begin{enumerate}
        \item There is a canonical bijection $f^{-1}(f([x])) = \rm  H^1(G, \Aut(x_\CC))$.  
        \item We have $\# \rm  H^1(G, \Aut(x_\CC)) = \# \rm  H^1(G, \Aut(x'_\CC))$ for each pair of objects $x, x' \in \ca X(\RR)$ whose induced objects $x_\CC, x'_\CC \in \ca X(\CC)$ are isomorphic in $\ca X(\CC)$. 
        %with $f([x]) = f([x'])$. Then
    \end{enumerate}
\end{proposition}
\begin{proof}
Since two objects in $\ca X(\CC)$ are isomorphic if and only if their images in $M(\CC)$ are the same, the second item is a consequence of the first item. The first item follows from \cite[Section 4]{grothendieck-descente-I}. 
\end{proof}

\subsection{Topological groupoids and families of finite $G$-groups.}\label{sec:families} Let $\pi \colon H \to U$ be a locally trivial family of finite topological $G$-groups. This means that $\pi$ is a finite topological covering, that there are involutions $\sigma \colon H \to H, \sigma \colon U \to U$ commuting with $\pi$,
    and that there is a continuous group law $m \colon H \times_U H \to H$, an inversion $i \colon H \to H$ and identity $e \colon U \to H$ all compatible with the involutions $\sigma$; moreover, we require that for each $x \in U$ there exists an open neighbourhood $x \in V \subset U$ such that $H|_V \cong V \times \Gamma$ as families of topological groups, for a finite group $\Gamma$. 
\begin{definition} \label{def:H1GH}
Let $\pi \colon H \to U$ be a locally trivial family of finite topological $G$-groups. We define 
\begin{align*}
\rm Z^1(G,H) &\coloneqq \set{(u, g) \in U \times H \mid u \in U^G, g \in H_u \text{ and } g \sigma(g) = e}, \\
\rm  H^1(G,H) &\coloneqq \rm Z^1(G,H) /\sim
\end{align*}
where $(u, g) \sim (u',g')$ if $u = u'$ and there exists $h \in H_u$ such that $g' = h g \sigma(h)^{-1}$. %There is a natural surjective map $\rm  H^1(G,H) \to U^G$, and for $V \subset U^G$ open such that $H|_V \cong V \times \Gamma$ as families of topological $G$-groups, for a finite $G$-group $\Gamma$, we have $\rm  H^1(G,H)|_V = \rm  H^1(G,H|_V) \cong \rm  H^1(G,\Gamma) \times V$. This proves a topology on the subsets $\rm  H^1(G,H)|_V$ for $V \subset U^G$ open, which glue to define a topology on $\rm  H^1(G,H)$. 
We equip $ \rm Z^1(G,H)$ with the subspace topology coming from $U \times H$ and we equip $\rm  H^1(G,H)$ with the quotient topology coming from $\rm Z^1(G,H)$. 
\end{definition}

\begin{remark} \label{rem:HUgroupoid}
    Note that $\pi \colon H \to U$ defines a topological groupoid $\mr X = [H \rightrightarrows U]$ enhanced with a natural involution $\sigma \colon \mr X \to \mr X$. The maps $s,t \colon H \to U$ are the same and both equal $\pi$, and the composition map $c\colon H \times_U H \to H$ equals the group law morphism $m$.   
Moreover, by construction, the space $\rm H^1(G,H)$ is nothing but the coarse space $\va{\mr X^G}$ of the groupoid of fixed points $\mr X^G$ constructed in Definition \ref{def:fix groupoid}. 
\end{remark}

\begin{lemma} \label{lem:topcovH1}
Let $\pi \colon H \to U$ be a locally trivial family of finite topological $G$-groups. 
    There is a natural surjective map $\rm  H^1(G,H) \to U^G$, and for $V \subset U^G$ open such that $H|_V \cong V \times \Gamma$ as families of topological $G$-groups over $V$ for some finite $G$-group $\Gamma$, we have $\rm  H^1(G,H)|_V = \rm  H^1(G,H|_V) \cong \rm  H^1(G,\Gamma) \times V$. In particular, the natural map 
    \[
    \rm  H^1(G,H) \longrightarrow U^G
    \]
    is a topological covering, with fibre $\rm  H^1(G,H_u)$ for $u \in U^G$. 
\end{lemma}
\begin{proof}
This follows from the fact that the construction of $\rm H^1(G,H)$ commutes with base change along a map $V \to U$ of topological $G$-spaces. 
\end{proof}

\begin{proposition} \label{proposition:comparison-alg-top}
Let $H \to U$ be a finite \'etale group scheme over a scheme $U$ of finite type over $\RR$. Consider the associated quotient stack $[U/H]$, and also the associated locally trivial family of finite $G$-groups $H(\CC)\to U(\CC)$. 
There is a canonical homeomorphism
\[
\va{[U/H](\RR)} \xrightarrow{\sim} \rm  H^1(G, H(\CC))
\]
of spaces over $U(\RR)$, where the space on the right is defined in Definition \ref{def:H1GH}. 
\end{proposition}
\begin{proof}
As the group scheme $H \to U$ is finite \'etale, the morphism $H(\mathbb C)\rightarrow U(\mathbb C)$ is a locally trivial family of finite topological $G$-groups. Hence, in view of Remark \ref{rem:HUgroupoid}, the proposition is a special case of Theorem \ref{theorem:indepencence-topology}. 
