    \begin{enumerate}
        \item \label{item:poincare:1} $P_{\ZZ/2 \times \ZZ/2}=\frac{1}{(1-t)^2}$;
       \item \label{item:poincare:2} $P_{D_8}=\frac{1}{(1-t)^2}$;
       \item \label{item:poincare:3} $P_{\mathfrak S_4}=\frac{1+t^2}{(1-t)^2(1+t+t^2)}$.
