\begin{proof}[Proof of Lemma \ref{lem:computationpoincareseries}]
Let us recall that if $A=\sum_{i\in \mathbb N} A_i$ is a graded $\mathbb F_2$-algebra, we can consider its Poincaré series 
$$P_{A}(t) \coloneqq \sum_{i\geq 0}\dim (A_i),$$
so that $P_{N}(t)=P_{H^*(N,\mathbb F_2)}(t)$ for every group $N$. 
If $f\in A$ is an homogeneous element of degree $d$, then 
\begin{equation}\label{eq:poincarequotient}
    P_{A}(t)=\frac{P_{A/(f)}(t)}{(1-t^d)},
\end{equation}
In particular if $A$ is freely degenerated by $R\dots x_n$ with $x_i$ of degree $j_i$, one has
\begin{equation}\label{eq:poincarepolinomial}
    P_A(t)=\prod_{1\leq i\leq n}\frac{1}{(1-t^{j_i})}
\end{equation}
To prove item \ref{item:poincare:1}, note that, by the Kunneth-Formula 
    $$H^*(\mathbb Z/2\times \mathbb Z/2,\mathbb Z/2)\simeq H^*(\mathbb Z/2,\mathbb Z/2)\otimes H^*(\mathbb Z/2,\mathbb Z/2) \simeq \mathbb F_2[x,y]$$
    with $x,y$ of degree $1$. Hence item \ref{item:poincare:1} of Lemma \ref{lem:computationpoincareseries} follows from (\ref{eq:poincarepolinomial}).

By \cite[Theorem 5.5]{MR1200878},
  $$  H^*(D_8,\mathbb Z/2)\simeq\frac{\mathbb F_2[x,y,z]}{(x(x+y))}\quad \text{with } \deg(x)=1, \deg(y)=1, \deg(z)=2.$$
  Since $x(x+y)$ is an homogenous element of degree 2, we get
  $$P_{H^*(D_8,\mathbb Z/2)}(t)= P_{\mathbb F_2[x,y,z]}(t)(1-t^2)=\frac{1}{(1-t)^2(1-t^2)}(1-t^2)=\frac{1}{(1-t)^2},$$
  where the first equality follows from (\ref{eq:poincarequotient}) and the second from (\ref{eq:poincarepolinomial}). This proves item \ref{item:poincare:3} of Lemma \ref{lem:computationpoincareseries}. 

By \cite[Theorem 4.1]{MR154905},
  $$  H^*(\mathfrak S_4 ,\mathbb Z/2)\simeq\frac{\mathbb F_2[x,y,z]}{(xz)}\quad \text{with } \deg(x)=1, \deg(y)=2, \deg(z)=3.$$
  Since $xz$ is an homogeonous element of degree $4$, we get
  $$H^*(\mathfrak S_4 ,\mathbb Z/2)=P_{\mathbb F_2[x,y,z]}(t)(1-t^4)=\frac{1}{(1-t)(1-t^2)(1-t^3)}(1-t^4)=\frac{1+t^2}{(1-t)^2(1+t+t^2)}$$
    where the first equality follows from (\ref{eq:poincarequotient}) and the second from (\ref{eq:poincarepolinomial}). This finishes the proof of Lemma \ref{lem:computationpoincareseries}. 
\end{proof}
