\chapter*{Appendix}\label{Remove Duration}
\addcontentsline{toc}{chapter}{Appendix:  Removing Duration from Portfolio \& Hedge Instrument Returns}
\counterwithin{equation}{section}
\setcounter{equation}{0}
\renewcommand\theequation{A\arabic{equation}}


As mentioned in the body of the manuscript, IG and HY bonds prices (and therefore returns) depend on their spreads to US Treasury bonds with similar durations. The first step in removing duration effects from the corporate bond ETF and portfolio returns is to identify the Treasuries with durations that closely match that of the instrument. Specifically, given a target asset with duration $D_{target}$, and a treasury universe with durations $D_1, ..., D_n$, select two treasuries whose durations ($D_{i^\ast}$ and $D_{j^\ast}$) bound $D_{target}$, i.e.

\begin{equation}\label{A1}
    \begin{aligned}
        D_{i^\ast} &=\min_{{0\le i\le n}} {{(D}_i-D_{target}|}D_i>D_{target}) \\
        D_{j^\ast} &=\min_{{0\le j\le n}} {{(D}_{target}-D_j|}D_j<D_{target})
    \end{aligned}
\end{equation}

A simple linear combination of these two Treasuries then matches the target duration $D_{target}$, with the constraint that their weights sum to one.

\begin{equation}\label{A2}
    \begin{aligned}
        w_{i^\ast} &= \frac{D_{target} - D_{j^\ast}}{D_{i^\ast} - D_{j^\ast}} \\
        w_{j^\ast} &= 1 - w_{i^\ast}         
    \end{aligned}
\end{equation}

\noindent The duration-driven (simple) return (i.e. the weighted average of $R_{i^\ast}$ and $R_{j^\ast}$) is then

\begin{equation}\label{A3}
    R_{duration}=w_{i^\ast}R_{i^\ast}+w_{j^\ast}R_{j^\ast}    
\end{equation}

\noindent Finally, the duration-neutral return is

\begin{equation}
  \Tilde{R}_{target}=R_{target}-R_{duration}  
\end{equation}

