\insertappendix{System Design: Optimization Strategies of Time-Step Level Prediction Algorithm}{figures/algo1_graphical.pdf}{fig: data_flow}
% \input{02-algorithm-code}
\subsection{System Design: Optimized Algorithm of Time-Step Level Prediction}
\label{sec: alorthm}
\begin{algorithm}

\caption{Optimization of Prediction Algorithm}
\begin{algorithmic}[1]
\footnotesize
\label{al:optimizing_prediction}
\State \textbf{Input:} $y\_prediction, strategy1, strategy2, strategy3$
\State $non\_zero\_cnt \gets 0$
\For{$i \gets 0$ \textbf{to} $len(y\_prediction) - 1$}
    \If{$i > 2$}

        \If{$strategy1$} \Comment{Execute strategy1: Low-Pass Strategy}
            \If{$y\_prediction[i-2] = 0$ \textbf{and} $y\_prediction[i-1] \neq 0$ \textbf{and} $y\_prediction[i] = 0$}
                \State $y\_prediction[i-1] \gets 0$
            \EndIf
        \EndIf
        \If{$y\_prediction[i-2] \neq 0$ \textbf{and} $y\_prediction[i-1] = 0$ \textbf{and} $y\_prediction[i] \neq 0$}
            \State $y\_prediction[i-1] \gets y\_prediction[i]$
        \EndIf

        \If{$strategy2$} \Comment{Execute strategy2: Front follows back strategy} 
            \If{$y\_prediction[i-1] = 2$ \textbf{and} $y\_prediction[i] = 3$}
                \State $y\_prediction[i-non\_zero\_cnt:i] =3$
            \EndIf

            \If{$y\_prediction[i-1] = 3$ \textbf{and} $y\_prediction[i] = 4$}
                \State $y\_prediction[i-non\_zero\_cnt:i] =4$
            \EndIf

            \If{$y\_prediction[i-1] = 2$ \textbf{and} $y\_prediction[i] = 1$}
                \State $y\_prediction[i-non\_zero\_cnt:i] =1$
            \EndIf
        \EndIf

        % \If{$strategy2$} \Comment{Execute strategy2: Front follows back strategy} 
        %     \If{$(y\_prediction[i-1] = 2$ \textbf{and} $y\_prediction[i] = 3)$ \\
        %         \textbf{or} $(y\_prediction[i-1] = 3$ \textbf{and} $y\_prediction[i] = 4$ \\
        %         \textbf{or} $(y\_prediction[i-1] = 2$ \textbf{and} $y\_prediction[i] = 1$)}
        %         \State $y\_prediction[i-non\_zero\_cnt:i] =y\_prediction[i]$
        %     \EndIf

        % \EndIf


        \If{$strategy3$} \Comment{Execute strategy3: Majority rule strategy}
            \If{$y\_prediction[i-1] \neq 0$ \textbf{and} $y\_prediction[i] = 0$}
                \State $VotingResult = MajorityRule(y\_prediction[i-non\_zero\_cnt:i])$ 
                \State $y\_prediction[i-non\_zero\_cnt:i-1] = VotingResult$ 
            \EndIf
        \EndIf

        \If{$y\_prediction[i-1] \neq 0$ \textbf{and} $y\_prediction[i] = 0$}

            \State $non\_zero\_cnt \gets 0$
        \Else
            \State $non\_zero\_cnt \gets non\_zero\_cnt + 1$
        \EndIf


    \EndIf
\EndFor

\end{algorithmic}
\end{algorithm}



