\subsection{Sampling in spaces of continuous functions}\label{sec:Tn_sampling}
Given some compact metric space $\Omega$ and $a\in \N$, we we consider the space $\X=\CC(\Omega, \K^a)$ equipped with the supremum norm throughout this section.
If $\Omega$ is uncountable, it is due to Milutin's theorem that $\CC(\Omega, \K^a)$ is isomorphic to $\CC([0,1], \K^a)$, see for example \cite[Chapter 4.i]{Lindenstrauß_classical_banach_spaces}. Since the latter has a Schauder basis, according to \cite[Chapter 1]{Semadeni_SchauderBases}, also $\CC(\Omega, \K^a)$ must possess a Schauder basis, meaning that it has the $\lambda$-BAP according to Section \ref{sec:Tn_schauder}.
However, the corresponding choice of $T_n(f) = \sum_{i\leq n} c_i(f) b_i$ is not the only possible choice for $T_n$ in Definition \ref{def:BAP} of the BAP, which we want to outline in what follows. %\Pascal{This sentence is slightly unclear, I think. Do we mean here that $T_n(f) = \sum_{k\leq n} c_k(f) b_k$ is not the only possible choice in order to fulfill the BAP?}
The constructions within this section are inspired from \cite[Lemma 7]{Chen1995_approx_thm}, in which the case $\CC(\Omega, \R)$ and $\Omega$ being a compact subset of a Banach space was considered.

\begin{definition}[\textbf{$\varepsilon$-covering}]
    Let $\Omega$ be a metric space and $\varepsilon>0$. An $\varepsilon$-covering of $\Omega$ is a set $M \subseteq \Omega$ such that 
    \begin{align*}
        \Omega \subseteq \bigcup_{x\in M}B_\varepsilon(x)
    \end{align*}
    Note that if $\Omega$ is compact, there exists a finite $\varepsilon$-covering for every $\varepsilon>0$.
\end{definition}

\begin{lemma}\label{lem:partition_unity}
    Let $(\Omega, d)$ be a compact metric space. Further, let $\varepsilon>0$ and $\{y_1,\dots, y_k\}$ be an $\varepsilon$-covering for $\Omega$. Then there exist finitely many continuous mappings $P_{\varepsilon, i}:\Omega \to [0,1]$ for $i\in \{1,\dots,k\}$ such that 
    \begin{enumerate}[(i)]
        \item For every $y\in \Omega$ it is $\sum_{i=1}^{k} P_{\varepsilon, i}(y) = 1$.\label{lem:partition_unity:i}
        \item For every $y\in \Omega$ it holds that $P_{\varepsilon, i}(y) = 0$ whenever $d( y\, ,\, y_i) \geq \varepsilon.$\label{lem:partition_unity:ii}
    \end{enumerate}
    If $\Omega\subseteq \R^p$, the mappings $P_{\varepsilon, i}$ can be chosen to be a smooth function belonging to $\CC^\infty(\Omega, \R)$.
\end{lemma}
\begin{proof}
    For the construction, we start by defining the continuous functions
    \begin{align*}
        \Tilde{P}_{\varepsilon, i}:\Omega &\longrightarrow [0,\infty) \\
        y&\longmapsto \begin{cases}
            \exp{\left(-\frac{1}{\varepsilon^2 - d(y,y_i)^2}\right)} &\text{if}\quad d(y,y_i)<\varepsilon, \\
            0& \text{else}.
        \end{cases}
    \end{align*}
    Note that property \ref{lem:partition_unity:ii} is already satisfied for $\Tilde{P}_{\varepsilon, i}$. In order to ensure property \ref{lem:partition_unity:i}, we normalize the functions by defining
    \begin{equation}\label{eq:P_eps_i}
         P_{\varepsilon, i}(y) \coloneqq \frac{ \Tilde{P}_{\varepsilon, i}(y)}{\sum_{\ell=1}^{k} \Tilde{P}_{\varepsilon, \ell}(y)}.
    \end{equation}
    By definition of $\{y_1,\dots, y_k\}$ being an $\varepsilon$-covering for $\Omega,$ note that for each $y\in \Omega$ there exists $i\in \{1,\dots,k\}$ such that $y\in B_\varepsilon(y_i)$. Hence, $\sum_{\ell=1}^{k} \Tilde{P}_{\varepsilon, \ell}(y)> 0$ for all $y\in \Omega$ so that the $P_{\varepsilon, i}$ are well-defined. Additionally, the $P_{\varepsilon, i}$ fulfill both properties \ref{lem:partition_unity:i} and \ref{lem:partition_unity:ii} leading to the desired partition of unity.\newline
    In the case of $\Omega\subseteq \R^p$, it is well-known that the so-called bump functions $\Tilde{P}_{\varepsilon, i}$ belong to $\CC^\infty(\Omega, \R)$ (see e.g.\ \cite[page 36]{Adams_SobolevSpaces}). Together with the fact that $\sum_{\ell=1}^{k} \Tilde{P}_{\varepsilon, \ell}(y)> 0$ for all $y\in \Omega$, this leads to $P_{\varepsilon, i}\in \CC^\infty(\Omega, \R)$.
\end{proof}
\begin{remark}
    In \cite[Lemma 7]{Chen1995_approx_thm}, a different partition of unity was used by defining
    \begin{align*}
        \Tilde{P}_{\varepsilon, i}:\Omega &\longrightarrow [0,1] \\
        y&\longmapsto \begin{cases}
            1- \varepsilon^{-1}d(y, y_i)\textup{ \, if \, } d(y, y_i) < \varepsilon, \\
            0 \textup{ \, else.}
        \end{cases}
    \end{align*}
    The advantage of using the $\Tilde{P}_{\varepsilon, i}$ as in the proof of Lemma \ref{lem:partition_unity} is their smoothness if $\Omega\subseteq \K^p$, see Corollary \ref{coro:sampling_BAP}.
\end{remark}


\begin{theorem}\label{thm:sampling_BAP}
    Let $\Omega$ be a compact metric space and consider $\CC(\Omega, \K^a)$ equipped with the supremum-norm. For $n\in \N$ let $\left\{y_1^{(n)},\dots,y_{k(n)}^{(n)} \right\}$ be an $1/n$-covering for $\Omega$ and $P_{\frac{1}{n}, i}$ the partition of unity on $\Omega$ from Lemma \ref{lem:partition_unity}.
    Then the operators  
    \begin{align*}
        \T_n: \CC(\Omega, \K^a) &\longrightarrow \CC(\Omega, \K^a)\\
        f &\longmapsto \left(y \mapsto \sum_{i=1}^{k(n)} f(y_i^{(n)}) P_{\frac{1}{n}, i}(y) \right)
    \end{align*}
    are linear, bounded, have finite rank and converge uniformly to the identity operator on every compact set $K\subset \CC(\Omega, \K^a)$. In other words, $T_n$ are suitable mappings in Definition \ref{def:BAP} of the $\lambda$-BAP.
\end{theorem}
\begin{proof}
    First, we mention that all $P_{\frac{1}{n}, i}$ are continuous which means that $\T_n$ indeed maps into $\CC(\Omega, \K^a)$.
    Let $f\in \CC(\Omega, \K^a)$ and $\varepsilon>0$. As $\Omega$ is compact, $f$ is uniformly continuous due to the Heine-Cantor theorem. Hence, there exists some $N \in \N$ such that for all $n\geq N$ it holds that
    \begin{align}\label{eq:thm_sampling_UAP_1}
        \vert f(x) - f(y) \vert \leq \varepsilon \textup{ \, whenever \, } x,y\in \Omega \textup{ \, with \, } d(x,y) < \frac{1}{n}.
    \end{align}
    Given $y\in \Omega$ let $I(y,n)$ denote the set of all indices $i$ such that $d(y\, , y_i^{(n)}) < 1/n$.
    Due to the properties of $P_{\frac{1}{n}, i}$, see Lemma \ref{lem:partition_unity}, we conclude for $n\geq N$ that
    \begin{align*}
        \Big\vert f(y) - (\T_n f)(y) \Big\vert = \left\vert  \sum_{i=1}^{k(n)} \left( f(y)- f(y_i^{(n)})\right) P_{\frac{1}{n}, i}(y)\right\vert &= \left\vert  \sum_{i\in I(y,n)} \left( f(y)- f(y_i^{(n)})\right) P_{\frac{1}{n}, i}(y)\right\vert \\
        &\leq \sum_{i\in I(y,n)} \left \vert  f(y)- f(y_i^{(n)})\right\vert  P_{\frac{1}{n}, i}(y) \\
        &\overset{(\ref{eq:thm_sampling_UAP_1})}{\leq} \varepsilon \sum_{i\in I(y,n)} P_{\frac{1}{n}, i}(y)\\
        &\leq \varepsilon \sum_{i=1}^{k(n)} P_{\frac{1}{n}, i}(y) = \varepsilon.
    \end{align*}
    Taking the supremum over all $y\in \Omega$ shows that $\T_n f$ converges to $f$. By Lemma \ref{lem:BAP_pointwise_convergence_suffices}, this implies that $\T_n$ uniformly converges to the identity operator on every compact $K\subset \CC(\Omega, \K^a)$. The range space of $T_n$ is spanned by the vectors $b_{i,j} = e_j P_i$, where $\{e_j: j = 1,\dots,a\}$ is the standard basis of $\K^a.$ Hence, $T_n$ has finite rank, namely at most $k(n) a$.
\end{proof}

Due to the smoothness of the partition of unities, we immediately obtain the following result.
\begin{corollary}\label{coro:sampling_BAP}
    For compact $\Omega\subseteq \R^p$, the mappings $T_n$ in Theorem \ref{thm:sampling_BAP} are also well-defined as mappings $\X\to \X$ for $\X$ being $\CC^k(\Omega, \R^a)$ or a Sobolev space $W^{k,2}(\Omega,\R)$ that continuously embeds into $\CC(\Omega, \R)$. In either case, $T_n$ uniformly converges to the identity on $\X$ on every compact $K\subset \X$, where $\X$ is equipped with the supremum norm. 
\end{corollary}

As in the previous sections, the mappings $T_n$ admit a canonical representation of the form $T_n = D_n\circ E_n$ where $D_n$ and $E_n$ are decoders and encoders, respectively. In the following, we refer to $E_n$ as a sampling encoder and to $D_n$ as a sampling decoder, which are shown in Table \ref{tab:sampling_encoder} and satisfy the required conditions in Definition \ref{def:EDAP_normed_space} of the EDAP for  $\CC(\Omega, \K^a).$


