    \subsection{Proof of Lemma \ref{lem:adherent_point_compact_open_topology}}\label{subsec:proof_adherent_point_compact_open_topology}
        \begin{replemma}{lem:adherent_point_compact_open_topology}\label{lem:adherent_point_compact_open_topology_appendix}
            Let $\X$ and $(\Y, d_\Y)$ be metric spaces and consider a subset $S\subseteq \CC(\X, \Y)$. A mapping $G\in \CC(\X, \Y)$ is an adherent point of $S$ with respect to the compact-open topology if and only if for every compact $K\subseteq \X$ there exists a sequence $(G_n)_{n\in \N}$ in $S$ such that 
            \begin{align*}
                \sup_{x\in K} d_\Y\big(G(x) \, , \, G_n(x) \big) \xrightarrow{n\to\infty} 0.
            \end{align*}
        \end{replemma}
        \begin{proof}
            For the proof, we follow the arguments used by Dugundji \cite[Chapter XII, Theorem 7.2]{Dugundji_Topologie}, where the convergence of sequences in the compact-open topology is characterized (see also Lemma \ref{lem:convergence_compact_open_topology}). \newline
            Assume that $G\in \CC(\X, \Y)$ is an adherent point of $S$. Let $K\subseteq \X$ be compact and $\varepsilon>0$. By continuity of $G$, for every $x\in K$ there is some $\delta_x>0$ such that 
            \begin{align*}
                G(B_{\delta_x}(x) ) \subseteq B_\varepsilon(G(x)).
            \end{align*}
            Since $K$ is compact, there are finitely many $x_1,\dots,x_n\in K$ such that 
            \begin{align*}
                K \subseteq \bigcup_{i=1}^n B_{\frac{1}{2}\delta_{x_i}}(x_i).
            \end{align*}
            For each $i=1,\dots,n,$ we define the compact set $K_i \coloneqq K \cap \overline{B}_{\frac{1}{2}\delta_{x_i}}(x_i)$, which is contained in $B_{\delta_{x_i}}(x_i)$ and satisfies $K = \cup_{i=1}^n K_i.$ Consider the set
            \begin{align*}
                U \coloneqq \bigcap_{i=1}^n \Big\{ f\in \CC(\X, \Y): f(K_i) \subseteq B_\varepsilon(G(x_i)) \Big\},
            \end{align*}
            which is open in the compact-open topology by Definition \ref{def:compact_open_topology} and contains $G$. Since $G$ is an adherent point of $S$, there exists $f\in S\cap U$. Furthermore, each $x\in K$ must belong to some $K_i$. Therefore, it follows from the triangular inequality that 
            \begin{align*}
                d_\Y(f(x)\, ,\, G(x)) \leq d_\Y(f(x)\, ,\, G(x_i)) + d_\Y(G(x_i)\, ,\, G(x)) < 2\varepsilon
            \end{align*}
            for all $x\in K.$ As a consequence,
            \begin{align*}
                \sup_{x\in K} d_\Y(f(x)\, ,\, G(x)) \leq 2 \varepsilon.
            \end{align*}
            Hence, since $\varepsilon$ has been chosen arbitrarily, we can find a sequence $(f_n)_{n\in\N}$ in $S$ converging uniformly to $G$ on $K$.

            For the other direction, consider any finitely many compact sets $K_1,\dots,K_n\subseteq \X$ and open sets $V_1,\dots,V_n\subseteq \Y$ such that $G(K_i)\subseteq V_i$. In other words, 
            \begin{align*}
                G\in U\coloneqq \bigcap_{i=1}^n U_{K_i, V_i},
            \end{align*}
            where $U_{K_i, V_i}\coloneqq \{f\in \CC(\X, \Y): f(K_i) \subseteq V_i\}$ belongs to the subbase of the compact-open topology from Definition \ref{def:compact_open_topology}. Note that any open neighborhood of $G$ can be written as a union of sets like $U$. Therefore, in order to show that $G$ is an adherent point of $S$, it suffices to show that there is always a $\Tilde{G}\in S\cap U$.\newline
            As $G\in \CC(\X, \Y)$ is continuous, the sets $G(K_i)$ are compact. Hence, according to Corollary \ref{coro:compact_set_uniform_extension}, there is some $\varepsilon_i>0$ such that for all $i\in \{1,\dots,n\}$
            \begin{align*}
                \bigcup_{x\in K_i} B_{\varepsilon_i}(G(x)) \subseteq V_i.
            \end{align*}
            Let $K$ denote the union of all $K_i$, which is also compact as it is the finite union of compact sets. By assumption, there exists a sequence $(G_n)_{n\in \N}$ in $S$ such that
            \begin{align*}
                \sup_{x\in K} d_\Y\big(G(x)\, ,\, G_n(x) \big) \xrightarrow{n\to\infty} 0.
            \end{align*}
            Therefore, there exists $\Tilde{G}\in S$ such that
            \begin{align*}
                \sup_{x\in K} d_\Y\big(G(x)\, ,\, \Tilde{G}(x) \big) < \varepsilon\coloneqq \min \big \{\varepsilon_1,\dots,\varepsilon_n\big\}.
            \end{align*}
            As a consequence, for every $x\in K_i$ it holds that $\Tilde{G}(x)\in B_\varepsilon(G(x))\subseteq V_i,$ which implies $\Tilde{G}\in U$. Thus, $G$ is an adherent point of $S$ with respect to the compact-open topology.
        \end{proof}

        In the following, we state the auxiliary results from basic topology, which are needed for the proof of Lemma \ref{lem:adherent_point_compact_open_topology}. The first lemma can, for example, be found in \cite[Chapter XI.4]{Dugundji_Topologie}.


        \begin{lemma}\label{lem:distance_compact_closed_sets}
            Let $(\X, d)$ be a metric space, $K\subseteq \X$ compact and $A\subseteq \X$ be closed such that $K\cap A = \emptyset$. Then the distance $\dist(K, A)$ between $K$ and $A$ is positive, i.e.,
            \begin{align*}
                0 < \dist(K, A) = \inf \{d(x,y): x\in K, y\in A\}.
            \end{align*}
        \end{lemma}

        \begin{corollary}\label{coro:compact_set_uniform_extension}
            Let $\X$ be a metric space, $K\subseteq \X$ compact and $U\subseteq \X$ open such that $K\subseteq U$. Then there exists some $\varepsilon>0$ such that 
            \begin{align*}
                \bigcup_{x\in K} B_\varepsilon(x) \subseteq U, 
            \end{align*}
            where $B_\varepsilon(x)$ denotes the open ball around $x$ with radius $\varepsilon$.
        \end{corollary}
        \begin{proof}
            If $U=\X$, the result is trivial, so assume $\X \setminus U\neq \emptyset$. As $\X \setminus U$ is closed and has empty intersection with $K$, Lemma \ref{lem:distance_compact_closed_sets} implies that $\dist(K, \X \setminus U)>0.$ Therefore, by choosing $0<\varepsilon<\dist(K, \X \setminus U)$ we obtain
            $\bigcup_{x\in K} B_\varepsilon(x) \subseteq U$.
        \end{proof}

    \subsection{Further Results}

        \begin{lemma}\label{lem:metric_separability}
            A metric space $\X$ is separable if and only if for every $\varepsilon>0$ there exists a sequence $(x_n)_{n\in\N}$ in $\X$ such that 
            \begin{align*}
                \X = \bigcup_{n=1}^\infty B_\varepsilon(x_n).
            \end{align*}
        \end{lemma}
        \begin{proof}
            Assume that for every $\varepsilon>0$ there is a sequence $(x_n(\varepsilon))_{n\in \N}$ in $\X$ such that 
            \begin{align*}
                \X = \bigcup_{n=1}^\infty B_\varepsilon(x_n(\varepsilon)).
            \end{align*}
            In particular, for $\varepsilon_m=\frac{1}{m}$, such a sequence exists. It is easy to verify that the countable set 
            \begin{align*}
                \left\{ x_n\left(\varepsilon_m\right): n,m\in \N \right\}
            \end{align*}
            is dense in $\X$, implying separability of $\X$. The converse is evident.
        \end{proof}

        \begin{theorem}\label{thm:X_nonseparableMetricSpace_equivalence}
            Let $\X$ be a non-seperable metric space and $\Y$ be a normed space which has at least one dimension. Then there exists a set $S\subset \CC(\X, \Y)$ that is dense with respect to the compact-open topology, but $S$ is not sequentially dense.
        \end{theorem}
        \begin{proof}
            Since $\X$ is not separable, it is due to Lemma \ref{lem:metric_separability} that there exists some $\varepsilon>0$ such that for every sequence $(x_n)_{n\in \N}$ in $\X$ it holds that 
            \begin{align}\label{eq:choice_eps_nonseparable}
                \X \neq \bigcup_{n=1}^\infty B_\varepsilon(x_n).
            \end{align}
            Define the set
            \begin{align*}
                S \coloneqq \left \{ f\in \CC(\X, \Y): f=0 \textup{ \, on \, } \X \setminus\left( \bigcup_{n=1}^\infty B_\varepsilon(x_n)\right)  \textup{ \, for \, } x_n\in \X\right \}.
            \end{align*}
            Consider $f\in \CC(\X, \Y)$ and some compact $K\subset \X$. The compactness of $K$ guarantees the existence of finitely many $x_1,\dots, x_n\in K$ such that 
            \begin{align*}
                K \subseteq V\coloneqq \bigcup_{i=1}^n B_\varepsilon(x_i).
            \end{align*}
            By Urysohn's lemma, see for example \cite[Chapter 4]{Dugundji_Topologie}, there exists a continuous mapping $\varphi:\X \to [0,1]$ such that $\varphi(x) = 1$ for all $x\in K$, and $\varphi(x) = 0$ for all $x\in \X \setminus V$.
            Consequently, the function $\varphi f$ is continuous and belongs to $S$. Further, $f(x) - \varphi(x)f(x) = 0$ for all $x\in K$, which shows that $S$ is dense in $\CC(\X, \Y)$ in the compact-open topology according to Theorem \ref{thm:density_compact_open_topology}.
            On the other hand, consider a constant function $f=a$ for some $a\in \Y\setminus \{ 0\}$, and let $(f_n)_{n\in \N}$ be an arbitrary sequence in $S$. 
            By definition of $S$, for each $n\in \N$, there must exist a sequence $(x_\ell^{(n)})_{\ell\in \N}$ in $\X$ such that 
            \begin{align*}
                f_n(x) = 0 \textup{\, for all \,} x\in \X \setminus \left( \bigcup_{\ell=1}^\infty B_\varepsilon(x_\ell^{(n)})\right).
            \end{align*}
            By the choice of $\varepsilon$ in Eq. (\ref{eq:choice_eps_nonseparable}), there exists some $x'\in \X$ that does not belong to any of the balls $B_\varepsilon(x_\ell^{(n)})$ for $n,\ell\in \N$. Hence, for every $n\in \N$ it is $f_n(x') = 0 \neq a = f(x')$ which implies that $f_n$ does not converge uniformly to $f$ on the compact set $\{x'\}$. Thus, $S$ cannot be sequentially dense in $\CC(\X, \Y)$ in the compact-open topology, according to Theorem \ref{thm:sequential_density_compact_open_topology} (not even in the topology of point-wise convergence).
        \end{proof}

        It is well-known that compact metric spaces are separable, see for example \cite[Chapter XI, Theorem 4.1.]{Dugundji_Topologie}.
        Below we give a simple proof based on Lemma \ref{lem:metric_separability}.\begin{lemma}\label{lem:compact_metric_separable}
            Every compact metric space $\X$ is separable.
        \end{lemma}
        \begin{proof}
            Let $\varepsilon>0$. Then $\X = \cup_{x\in \X}B_\varepsilon(x).$ By compactness of $\X$ there are finitely many $x_n\in \X$ for $n\leq N\in \N$ such that $\X = \cup_{n\leq N} B_\varepsilon(x_n)$. Hence, $\X$ is separable according to Lemma \ref{lem:metric_separability}.
        \end{proof}

        \begin{lemma}\label{lem:example_dense_FU_not_FU}
            Let $(\Z, \mathfrak{T})$ be a topological space, which is not a Fréchet-Urysohn space. For any object $x\notin \Z$ define $\Z' = \Z \cup \{ x\}$ and the topology
            \begin{align*}
                \mathfrak{T}' = \{ \emptyset\} \cup \big\{U\cup \{x\}: U\in \mathfrak{T} \big\}.
            \end{align*}
            on $\Z'$. Then $(\Z', \mathfrak{T}')$ is not a Fréchet-Urysohn space, but every dense set $D\subseteq \Z$ is sequentially dense.
        \end{lemma}
        \begin{proof}
            It is straightforward to verify that $\mathfrak{T}'$ defines a topology on $\Z'$. Let $D\subseteq \Z'$ be dense. Since $\{x\} = (\emptyset\cup\{x\})\in \mathfrak{T}'$, it follows that $x\in D$. Due to the fact that $x$ belongs to every non-empty open set $U'\in \mathfrak{T}'$, it follows that the constant sequence $x_n= x\in D$ converges to every $z\in \Z'$ in the topology $\mathfrak{T}'$. Therefore, $D$ must also be sequentially dense in $\Z'$.
            Since $(\Z, \mathfrak{T})$ is not a Fréchet-Urysohn space, there is some $S\subseteq \Z$ which has an adherent point $s\in \overline{S}$, but no sequence in $S$ converges to $s$ in the topology $\mathfrak{T}$. Therefore, and due to $x\notin \Z$, no sequence in $S$ converges to $s$ in the topology $\mathfrak{T}'$. Hence, $(\Z', \mathfrak{T}')$ is not a Fréchet-Urysohn space.
        \end{proof}
    \begin{lemma}\label{lem:compact_set_convergent_sequence}
        Let $(\X, d)$ be a metric space with metric $d$ and $(x_n)_{n\in\N}\subset \X$ be a convergent sequence in $\X$ with limit $x\in \X$. Then the set $C\coloneqq\{x\}\cup \{x_n: n\in \N\}$ is compact.
    \end{lemma}
    \begin{proof}
        Let $\{U_i : i\in I\}$ be an open cover of $C$ with index set $I$. The aim is to find a finite subcover. As $x\in C\subset \bigcup_{i\in I }U_i,$ there exists an index $i_x\in I,$ such that $x\in U_{i_x}.$ As $U_{i_x}$ is an open neighbourhood of $x$ and $x_n \xrightarrow[]{n\to \infty}x,$ there exists an index $N\in\N$ such that $x_n\in U_{i_x}$ for all $n\geq N.$ The remaining elements $\{x_1,\dots,x_{N-1}\}$ can be covered by a finite number of open sets leading to the desired finite subcover of $C.$
    \end{proof}

\section{Schauder basis coefficients and sampling}\label{sec:appendix_coeff_sampling}
\begin{lemma}\label{lem:density_single_point}
    Let $\Omega$ be a topological space satisfying the following properties:
    \begin{itemize}
        \item[(i)] For every $x\in \Omega$ the set $\{x\}$ is closed. (Note that in metric spaces points are always closed sets.)
        \item[(ii)] $\Omega$ has no isolated points, i.e. for any $x\in \Omega$ and any open neighborhood $U$ of $x$, the set $U\setminus\{x\}$ is non-empty. 
    \end{itemize}
    Further, assume that $Y\subseteq \Omega$ is dense in $\Omega$. Then $Y \setminus \{ y'\}$ is still dense in $\Omega$ for any $y'\in Y$.
\end{lemma}
\begin{proof}
    Assume $Y\setminus \{y'\}$ was not dense in $\Omega$. Hence, there must be some $z\in \Omega$ and an open neighborhood $U\subset \Omega$ of $z$ such that 
    \begin{align}\label{lem:eq1:density_single_point}
        U \cap \Big( Y\setminus \{y'\} \Big) = \emptyset.
    \end{align}
    Since $Y$ is dense in $\Omega$ it must hold that $U\cap Y\neq \emptyset$, which implies $y'\in U$. This means that $U$ is an open neighborhood of $y'$. Due to (ii) we conclude that $U\setminus\{y'\}$ cannot be empty, so there must be some $x'\in U\setminus\{y'\}$. From (i) it follows that $U\setminus \{y'\}$ is open and thereby it is an open neighborhood of $x'$. 
    We observe
    \begin{align*}
         \Big(U\setminus \{ y'\} \Big)\cap Y =  U \cap \Big( Y\setminus \{y'\} \Big) \overset{(\ref{lem:eq1:density_single_point})}{=} \emptyset,
    \end{align*}
    which is a contradiction to the density of $Y$ in $\Omega$.
\end{proof}


\begin{theorem}\label{thm:sampling_schauder_differ}
    Let $\Omega$ be a metric space without isolated points. Assume that there is a Schauder basis $(b_n)_{n\in \N}$ of the space of bounded continuous functions $\CC_b(\Omega, \K)$, equipped with the supremum-norm.
    Then for any sequence of points $(y_n)_{n\in \N}$ in $\Omega$ there exists some $f\in \CC_b(\Omega, \K)$ such that
    \begin{align*}
        f \neq \sum_{n=1}^\infty f(y_n) b_n.
    \end{align*}
    %holds for all $f\in \CC(\Omega, \K)$.
\end{theorem}
\begin{proof}
    Assume there was such a Schauder basis and a sequence of sampling points such that $f = \sum_{n=1}^\infty f(y_n) b_n$ holds for all $f\in \CC_b(\Omega, \K)$. Define the set of sampling points $Y\coloneqq\{ y_n: n\in \N\}$, which are either dense or not dense in $\Omega$. In both cases this will lead to a contradiction: 

    If $Y$ is not dense in $\Omega$, there must exist some $z\in \Omega$ and $\varepsilon>0$ such that the open ball $B_\varepsilon(z)$ and $Y$ are disjoint. In this case one can construct an $f\in \CC_b(\Omega, \K)\setminus\{0\}$ with support in $B_\varepsilon(z)$. This implies $f(y_n)=0$ for all $n\in \N$, which yields
    \begin{align*}
        0\neq f = \sum_{n=1}^\infty f(y_n) b_n = 0,
    \end{align*}
    a contradiction.

    Assume that $Y$ is dense in $\Omega$. Consider, for example,  the representation of the first Schauder basis function 
    \begin{align*}
        b_1 = \sum_{n=1}^\infty b_1(y_n) b_n.
    \end{align*}
    Due to the uniqueness of Schauder basis representations it follows that $b_1(y_n) = 0$ for all $n\in \N\setminus\{1\}$.
    Since $\Omega$ has no isolated points, $Y\setminus\{y_1\}$ is still dense in $\Omega$ (see previous Lemma \ref{lem:density_single_point}). Therefore, continuity of $b_1\in \CC_b(\Omega, \K)$ implies $b_1 = 0$, which is again a contradiction. Hence, there cannot exist such a Schauder basis representation.
\end{proof}


