\section{Further useful results}
\begin{lemma}\label{lem:Lipschitz_K_independence}
    Let $(\X, d_\X)$ and $(\Y, d_\Y)$ be metric spaces, where $\X$ is separable. Consider some Lipschitz continuous $F\in \CC(\X, \Y)$. Assume that for every compact $K\subset \X$ there is some sequence $(F_{K, n})_{n\in \N}$ in $\CC(\X, \Y)$ which satisfies
    \begin{itemize}
        \item[(i)] All $F_{K, n}$ are Lipschitz continuous with Lipschitz constant $L>0$, which is independent on $n$ and $K$.
        \item[(ii)] It holds that 
        \begin{align*}
            \sup_{x\in K} d_\Y\big(F(x) \, , \, F_{K, n}(x)\big) \xrightarrow{n\to\infty} 0.
        \end{align*}
    \end{itemize}
    Then there exists a strictly increasing sequence $(a_n)_{n\in\N}\subset \N$ as well as a sequence of compact sets $K_n$ such that $F_n \coloneqq F_{K_n, a_n}$ converges uniformly to $F$ on every compact $K$.
\end{lemma}
\begin{proof}
    By separability of $\X$, there exists a sequence $(x_n)_{n\in \N}$ which is dense in $\X$. Define the compact sets $K_n \coloneqq \{x_k: k\leq n\}$. By property (ii) there is some strictly increasing sequence of natural numbers $(a_n)_{n\in\N}$ such that for all $n\in \N$ it holds that
    \begin{align*}
        \sup_{x\in K_n} d_\Y\big( F_{K_n, a_n} (x) \, , \, F(x)\big) \leq \frac{1}{n}.
    \end{align*}
    Define the operators $F_n \coloneqq F_{K_n, a_n}.$ We first show pointwise convergence, so let $x\in \X$ and $\varepsilon>0$.
    Due to density of $\{x_n: n\in \N\}$ and continuity of $F$ in $x$, there exists $i\in \N$ such that
    \begin{equation*}
        d_\X( x\, , \, x_i) \leq \frac{\varepsilon}{3L} \quad \text{and} \quad d_\Y\big( F(x_i) \, , \, F(x)\big) \leq \frac{\varepsilon}{3}.
    \end{equation*}
    Choose $N\in \N$ large enough such that for all $n\in \N$ we have
    \begin{align*}
        x_i\in K_n\quad \text{and} \quad \sup_{x\in K_n} d_\Y\big( F_{n} (x) \, , \, F(x)\big) \leq \frac{\varepsilon}{3}.
    \end{align*}
    It follows then from (i) that
    \begin{align*}
        d_\Y\big( F(x) \, , \, F_n(x) \big) &\leq d_\Y\big( F(x) \, , \, F(x_{i}) \big) + d_\Y\big( F(x_{i}) \, , \, F_n(x_{i}) \big) + d_\Y\big( F_n(x_{i}) \, , \, F_n(x) \big) \\
        &\leq \frac{\varepsilon}{3} + \frac{\varepsilon}{3} + Ld_\X( x_{i} \, , \, x ) \leq \varepsilon,
    \end{align*}
    which shows pointwise convergence of $F_n$ to $F$.

    Let $K\subset \X$ be compact and $\varepsilon>0$. Let $L_0>0$ be a Lipschitz constant of $F$. By compactness of $K$, there exists $y_1,\dots,y_p\in K$ such that 
    \begin{align*}
        K \subset \bigcup_{i=1}^p B_r(y_i) \textup{\, with radius }r\coloneqq \frac{\varepsilon}{3(L_0+L)}
    \end{align*}
    Since $F_n$ converges pointwise to $F$, choose $N\in \N$ large enough such that for all $n\geq N$ and every $i=1, \dots,p$ it is
    \begin{align*}
        d_\Y\big( F_n(y_i) \, , \, F(y_i) \big) \leq \frac{\varepsilon}{3}.
    \end{align*}
     Given any $x\in K$ there exists $y_{i^*}$ with $i^*\in \{1,\dots,p\}$ such that $d_\X( x\, , \,y_{i^*}) \leq r$. Therefore,
    \begin{align*}
        d_\Y\big( F(x) \, , \, F_n(x) )&\leq d_\Y\big( F(x) \, , \, F(y_{i^*}\big) + d_\Y\big( F(y_{i^*}) \, , \, F_n(y_{i^*}) \big)  + d_\Y\big( F_n(y_{i^*}) \, , \, F_n(x) \big) \\
        &\leq L_0 d_\X( x \, , \, y_{i^*} ) + \frac{\varepsilon}{3} + L d_\X( y_{i^*} \, , \, x) \leq \varepsilon.
    \end{align*}
    Taking the supremum over all $x\in K$ shows that $F_n$ converges uniformly to $F$ on $K$.
    \end{proof}

