\par The received signal of the $n$-th RIS element follows
\begin{align}\label{passiveyin}
 y^p_{in}=\sqrt{P_tL_g} g(n)s.  
\end{align}

\par The representation of the reflected signal of the $n$-th RIS element is as follows
\begin{align}\label{passiveyout}
   y^p_{out}=\sqrt{P_tL_g} g(n)p(n)s.  
\end{align}

\par The received signal at user can be represented as
\begin{align}\label{passiveyu}
    &y^p_u=\sqrt{P_t}\big(\sqrt{L_fL_g}\sum_{n=1}^{N} f^\ast(n)p(n)g(n)+\sqrt{L_h}h^\ast\big)s+w_u\nonumber\\
    &~~~=\sqrt{P_t}e^{-j\phi_{h}}\big(\sqrt{L_fL_g}\sum_{n=1}^{N}|f(n)||p(n)||g(n)|\cdot e^{j\big(2\pi\phi_g(n)+\theta(n)-2\pi\phi_f(n)+\phi_{h}\big)}+\sqrt{L_h}|h|\big)s+w_u,
\end{align}
\noindent assuming the phase of the direct channel is $\phi_{h}=0$, similar to the phase alignment method of active RIS, the received signal at user can be derived as
\begin{align}\label{passiveyu1}
    &\widetilde{y}_u^p=\sqrt{P_t}\big(\sqrt{L_fL_g}\sum_{n=1}^{N}|f(n)||p(n)||g(n)|+\sqrt{L_h}|h|\big)s+w_u.
\end{align}

\par The total power received by passive RIS is as follows
\begin{align}\label{passivePin}
&P^p_{in}=\sum_{n=1}^{N}{y_{in}^p}^\ast(n)y^p_{in}(n)=P_tL_g\sum_{n=1}^{N}|g(n)|^2.
\end{align}

\par Assuming that passive RIS uses the same reflection coefficient for each channel, according to \cite{ref5}, since passive RIS does not have signal amplification capability, $|p(n)|$ can be set to 1, the reflected power of passive RIS can be denoted as
\begin{align}\label{passivePout}
&P^p_{out}=\sum_{n=1}^{N}{y_{out}^p}^\ast(n)y^p_{out}(n)=P_tL_g\sum_{n=1}^{N}|g(n)|^2|p(n)|^2=P_tL_g\sum_{n=1}^{N}|g(n)|^2.
\end{align}

\par Therefore, the power consumption in the  system is given by
\begin{align}\label{passiveP_{tot}}
    &P^p_{tot}=\mu P_t+P_0+NP^p_{c,n}+P^p_{0,RIS},
\end{align}
\noindent where $P_{c,n}^p$ represents the static power required for reconfiguring each passive RIS element, while $P^p_{0,RIS}$ accounts for the remaining static power components in passive RIS system.


\par Similar to the derivation of active RIS, by using the law of large numbers, the SNR obtained by user can be converted into
\begin{align}
    &\gamma^p_u=\frac{ P_t\big(\sqrt{L_fL_g}\sum_{n=1}^{N}|f(n)||g(n)|+\sqrt{L_h}|h|\big)^2}{\sigma^2_u}\\
    &~~~=\frac{ P_t\big(\sqrt{L_fL_g}N\cdot\frac{1}{N}\sum_{n=1}^{N}|f(n)||g(n)|+\sqrt{L_h}|h|\big)^2}{\sigma^2_u}\nonumber\\
    &~~~\approx\frac{ P_t\big(\sqrt{L_fL_g}N\mathbb{E}\big\{|f(n)||g(n)|\big\}+\sqrt{L_h}|h|\big)^2}{\sigma^2_u}=\frac{ P_t\big(\frac{\pi}{2}\sqrt{L_fL_g}N\alpha_f\alpha_g+(\frac{\pi}{2})^\frac{1}{2}\sqrt{L_h}\alpha_h\big)^2}{\sigma^2_u}.\nonumber
\end{align}

\par Ultimately, for passive RIS-aided system, the EE is expressed as
\begin{align}
    \mathrm{EE}^p=B\cdot\frac{\mathrm{log}_2(1+\gamma^p_u)}{P^p_{tot}},
\end{align}
\noindent the EE can be further expressed as
\begin{align}
    \mathrm{EE}^p(N, P_t, \sigma^2_u)=B\cdot\frac{\mathrm{log}_2(1+\frac{P_t(A_8N^2+A_9N+A_{10}}{\sigma^2_u})}{P_t+NP^p_{c,n}+A_{11}},
\end{align}
\noindent where
\begin{align}
    &A_8=\frac{\pi^2}{4}L_fL_g\alpha^2_f\alpha^2_g,~~~~~A_9=\pi(\frac{\pi}{2})^{\frac{1}{2}}\sqrt{L_fL_gL_h}\alpha_f\alpha_g\alpha_h,\nonumber\\
    &A_{10}=\frac{\pi}{2}L_h\alpha^2_h,~~~~~~~~~~~A_{11}=P_0+P^p_{0,RIS}.
\end{align}

