\begin{proof}[Proof of \Cref{p:HATH1}]\phlabel{p:p:HATH1}
  Recall
  that $\sinc(z)$ is an analytic function and for $|z|<\pi$,
  \begin{align} \label{e:sinc-zeta}
    \ln[\sinc(z)]
    = -\sumoi n \frac{\zeta(2n)}{n} (z/\pi)^{2n};
    % \\\nonumber
    % &=
    % -\sumoi n \frac{2^{2n-1} |B_{2n}|}{n(2n)!} z^{2n} =
    % -\frac{z^2}6  - \frac{z^4}{180} - \frac{z^6}{2835} - \frac{z^8}{48600}
    % - \ldots
  \end{align}
  see \cite{NIST:10}, 25.8.8.  
  % and $B_{2n}$ are the Bernoulli numbers (\cite{NIST:10}, 25.5.6,
  % 24.2).
  Then for $c\in (0,1)$ and $|x|<1$, 
  \[
    \frac{\dd}{\dd x}\Sbr{\ln\frac{\sinc(c\pi x)}{\sinc(\pi x)}}
    =
    \frac{\dd}{\dd x} \Sbr{\sumoi n \frac{\zeta(2n)}{n} (1-
      c^{2n}) x^{2n}}
    =
    2\sumoi n \zeta(2n) (1-c^{2n}) x^{2n-1}.
  \]
  Then from \eqref{e:HAT}, it follows that 
  \begin{align*}
    \frac{\dd}{\dd x}[\ln \HAT[\pi x]]
    &=
    2\sumoi n \zeta(2n) (1-\delta^{2n}) x^{2n-1}
    +
    \frac{2\alpha}\delta\sumoi n \zeta(2n) (1-\alpha^{2n}) x^{2n-1}
    \\
    &=
    2\alpha \sumoi n \zeta(2n)\sum^{2n-1}_{k=0} (\alpha^k + \delta^k)
    x^{2n-1}.
  \end{align*}
  From $\ln \HAT[0]=0$, the equality in \eqref{e:lHAT} follows.  Treat
  $\alpha^k + \delta^k$ as a function of $\alpha$.  If
  $k=0$, then $\alpha^k + \delta^k\equiv 2$ on $[\nth2,1]$.  On the
  other hand, if $k\ge1$, then $\alpha^k + \delta^k$ is increasing on
  $[\nth2, 1]$.  As a result, given $\theta$, $\alpha^{-1} \ln\HAT$ is
  less than the limit as $\alpha\to1$, which is $\ln\HAT[\theta][1]$.
  This also yields $\ln \HAT[\theta][1]= \sumoi n \zeta(2n)(2+1/n)
  (\theta/\pi)^{2n} = \theta^2/2 + V_1(\theta)$, as claimed.
  Similarly, given $0<\theta_1 <  \theta_2<\pi$, $\alpha^{-1} [\ln
  \HAT[\theta_2] - \ln \HAT[\theta_1]]$ as a function of $\alpha$ is
  increasing on $[1/2,1]$.  Then it is easy to see that
  $\HAT[\theta_2]/\HAT[\theta_1]$ is increasing on $[1/2,1]$. 
\end{proof} %p:HATH1

\begin{proof}[Proof of \Cref{p:H-sand}]\phlabel{p:p:H-sand}
  Denote $u=\pi-\theta$.  By $\pi - \alpha\theta=\delta\pi + \alpha u$, 
  \begin{align*}
    \hAT
    =
    \frac{\sin(\delta\theta)[\sin(\alpha\theta)]^{\alpha/\delta}}
    {[\sin(\theta)]^{1/\delta}}
    &=
    \frac{\sin(\delta\theta)}{\sin(u)}
    \Sbr{\frac{\sin(\delta\pi + \alpha u)}{\sin(u)}}^{\alpha/\delta}
    \\
    &\hspace{-2cm}=
    \XiAT
    \frac{\delta\theta}{u}
    \Grp{\frac{\delta\pi+\alpha u}u}^{\alpha/\delta}
    =    
    \delta \alpha^{\alpha/\delta} \XiAT 
    \frac\theta u
    \Grp{1+ \frac{\delta\pi}{\alpha u}}^{\alpha/\delta}.
  \end{align*}
  Since $\hAT[0]=\delta \alpha^{\alpha/\delta}$ and $\HAT =
  \hAT/\hAT[0]$, then \eqref{e:HAT-factor} follows.

  From \eqref{e:sinc-zeta} and $u=\pi-\theta$,
  \begin{align*}
    [\delta\ln\XiAT]'
    &=
    \sumoi n \frac{\zeta(2n)}{n} \pi^{-2n}
    \frac{\dd}{\dd\theta}[(\pi-\theta)^{2n} -
    \delta (\delta\theta)^{2n} - \alpha(\pi-\alpha\theta)^{2n}]
    \\
    &=
    2\sumoi n \zeta(2n) \pi^{-2n}[-(\pi-\theta)^{2n-1}-
    \delta^2(\delta\theta)^{2n-1} + \alpha^2(\pi-\alpha\theta)^{2n-1}].
  \end{align*}
  Let $\alpha\in (1/2,1)$.  Then $I:=[(\nth3 + \nth{3\alpha})\pi,
  \pi)\ne\emptyset$.  To show that $\XiAT$ is increasing on $I$, it 
  suffices to show that for each $n\ge1$, $\alpha^2(\pi -
  \alpha\theta)^n \ge (\pi-\theta)^n + \delta^2(\delta\theta)^n$ on
  $I$, or equivalently $\alpha^2 \ge [(\pi-\theta)/(\pi -
  \alpha\theta)]^n + \delta^2[\delta\theta/(\pi - \alpha\theta)]^n$.
  By $\delta=1-\alpha$, it is easy to check that the inequality holds
  for $n=1$.  Then by $\pi-\alpha\theta \ge \max(\pi-\theta, \delta
  \theta) \ge0$, the inequality holds for all $n\ge1$.  The claim on
  $\XIAT$ then easily follows.  Finally, from the above display
  \begin{align*}
    [\ln\XiAT]'
    &\le
    \frac2\delta \sumoi n \zeta(2n) \pi^{-2n}
    [(\pi-\alpha\theta)^{2n-1}-(\pi-\theta)^{2n-1}]
    \\
    &\le
    2\theta\sumoi n \zeta(2n) \pi^{-2n}
    (2 n-1)(\pi-\alpha\theta)^{2n-2}.
  \end{align*}
  By \eqref{e:sinc-zeta}, the \rhs is $\theta[\ln
  \nth{\sinc(t)}]''|_{t=\pi - \alpha\theta}$.  Since
  $[\nth{\sinc(t)}]'' = \nth{(\sin t)^2} - \nth{t^2}$, the inequality
  for $[\ln\XiAT]'$ follows.  The last equality follows by using
  \eqref{e:HAT-factor} and direct calculation.
\end{proof} %p:H-sand


\begin{proof}[Proof of \Cref{p:fpus-squeeze}]\phlabel{p:p:fpus-squeeze}
  Let $k_\alpha(y)=(y^{-\alpha}+1)[1- (y+1)^{-\delta/\alpha}]^\alpha$,
  $y>0$.  Then \eqref{e:fpus-squeeze} holds $\Iff c_{1,\alpha}\le \nth
  {\sup k_\alpha}$ and $c_{2,\alpha}\ge \nth{\inf k_\alpha}$.  Since
  on $(0,\infty)$, $f(y):= (y+1)^{-\delta/\alpha}$ is decreasing and
  convex and takes values in $(0,1)$,
  \begin{align*}
    \sup k_\alpha
    &\le \sup_{y>0} y^{-\alpha}[1- f(y)]^\alpha +
    \sup_{y>0} [1- f(y)]^\alpha
    \\
    &\le \sup_{y>0} \Abs{\frac{f(y)-1}y}^\alpha + 1
    \le |f'(0)|^\alpha + 1 = (\delta/\alpha)^\alpha + 1 =
    \nth{c_\alpha}+1.
  \end{align*}
  Then the first inequality in \eqref{e:fpus-squeeze} holds.  Since
  $c_\alpha$ is a continuous and nonnegative function of $\alpha\in
  (0,1]$ and tends to 1 as $\alpha\to0$, then $\inf_{\alpha\in (0,1)}
  c_{1,\alpha}>0$.  To show the second inequality in
  \eqref{e:fpus-squeeze}, if $\alpha\le1/2$, then $\delta/\alpha\ge1$,
  giving
  \[
    k_\alpha(y)
    \ge
    (y^{-\alpha}+1)[1- (y+1)^{-1}]^\alpha = t^\alpha + (1-t)^\alpha,
    \quad
    \text{with~} t = 1/(y+1).
  \]
  The infimum of the \rhs is attained at $t=0,1$, so $\inf k_\alpha\ge
  1$ and the second inequality in \eqref{e:fpus-squeeze} holds
  if $c_{2,\alpha} = 1$.  On the other hand, if
  $\alpha>1/2$, then by $|f'(y)|\le |f'(0)| =\delta/\alpha < 1$,
  $0<[1-f(y)]/y<1$.  Then 
  \[
    k_\alpha(y)
    =[1-f(y)]^\alpha + \Sbr{\frac{1-f(y)}y}^\alpha
    \ge 1-f(y) + \frac{1-f(y)}y
    =
    \frac{(y+1) [1-f(y)]}{y}.
  \]
  Since $(y+1)[1-f(y)] = (y+1) - (y+1)^{1-\delta/\alpha}$ is convex in
  $y\ge0$ and equal to 0 at $y=0$, the infimum of the \rhs is attained
  at $y=0$ with value $\delta/\alpha$.  Then $\inf k_\alpha\ge
  \delta/\alpha$ and the second inequality \eqref{e:fpus-squeeze}
  holds.
  % From $k_\alpha(1)
  % = O(1-\alpha)$ as $\alpha\uto1$, $\inf k_\alpha\asymp (1-\alpha)$,
  % giving $\liminf_{\alpha\uto1} (1-\alpha) c_{2,\alpha}>0$ for any
  % $c_{2,\alpha}$ satisfying \eqref{e:fpus-squeeze}.
\end{proof}%p:fpus-squeeze


\begin{proof}[Proof of \Cref{l:icgamma}] \phlabel{p:l:icgamma}
  If $b<a+1$, then
  \[
    e^{-b} \int^b_a x^{c-1}\,\dd x \le \int g_{a,b,c} =
    \int^b_a x^{c-1} e^{-x}\,\dd x \le e^{-a} \int^b_a x^{c-1}\,\dd x.
  \]
  Since $e^{-a} \int^b_a x^{c-1}\,\dd x = G(a,b,c)$ and $e^{-b} >
  e^{-a-1}$, then \eqref{e:icgamma} holds.  If $a+1\le b<a+2$, then
  from $g_{a,b,c} = g_{a,a+1,c} + g_{a+1,b,c}$ and the above proof,
  \eqref{e:icgamma} holds.

  Let $b>a+2$.  Put $d=a+2$.  First, suppose $c\in [1,2)$.  Then 
  \begin{align*}
    e^{-1} [G(a,a+1,c) &+ G(a+1,a+2,c)] + \int g_{d,b,c}
    \\
    &\le
    \int g_{a,b,c} \le G(a,a+1,c) + G(a+1,a+2,c) +\int g_{d,b,c}.
  \end{align*}
  From $\int g_{d,b,c} = \int^b_d [x^{c-1} - (c-1) x^{c-2}]
  e^{-x}\, \dd x + \int^b_d (c-1) x^{c-2} e^{-x}\,\dd x =
  d^{c-1} e^{-d} - b^{c-1} e^{-b} + \int^b_d (c-1) x^{c-2}
  e^{-x}\,\dd x$ and 
  \[
    \frac{\int^b_d [x^{c-1} - (c-1) x^{c-2}) e^{-x}\, \dd x}{
      \int^b_d (c-1) x^{c-2} e^{-x}\,\dd x}
    \ge
    \inf_{x\ge d} \frac{[x^{c-1} - (c-1) x^{c-2}] e^{-x}}{
      (c-1) x^{c-2} e^{-x}} \ge1,
  \]
  it follows that $d^{c-1} e^{-d} - b^{c-1} e^{-b} \le \int g_{d,b,c}
  \le 2[d^{c-1} e^{-d} - b^{c-1} e^{-b}]$.  Then \eqref{e:icgamma}
  holds.

  Now let $c\in (0,1)$.  As in the previous case, it suffices to show
  $e^{-1} d^{c-1} (e^{-d} - e^{-b})\le \int g_{d,b,c} \le d^{c-1}
  (e^{-d} - e^{-b})$.  Since $c<1$, $\int g_{d,b,c} \le \int^b_d
  d^{c-1}e^{-x}\,\dd x$, yielding the second inequality.  If $b\le
  d+1$, then by $1-c<1$, $\int g_{d,b,c} = d^{c-1}\int^b_d
  (\frac dx)^{1-c} e^{-x}\,\dd x \ge d^{c-1} \int^b_d(\frac{d}{d+1})
  e^{-x}\,\dd x \ge \frac23 d^{c-1} \int^b_d e^{-x}\,\dd x$.  Since
  $\frac23>1/e$, the first inequality follows.  If $b>d+1$, then by
  $g_{d,b,c} > g_{d,d+1, c}$, $\int g_{d,b,c}\ge (2/3) d^{c-1}
  \int^{d+1}_d e^{-x}\,\dd x \ge e^{-1}d^{c-1} e^{-d}\ge
  e^{-1}d^{c-1}(e^{-d}  - e^{-b})$.
\end{proof} %l:icgamma

\begin{proof}[Proof of \Cref{p:chi-G}]\phlabel{p:p:chi-G}
  Since $f(s)=1-e^{-s}$ is concave, for $s>0$, $f'(s) s \le f(s) \le
  f'(0) s$, implying $e^{-1}(s\wedge1) \le 1-e^{-s}\le s\wedge1$.
  Letting $s = (\delta/\alpha) \ell(y)$,
  \begin{gather*}
    e^{-1} \le \frac{1-(y+1)^{-\delta/\alpha}}{[(\delta/\alpha)
      \ell(y)]\wedge1}\le1\implies\\
    \nth{[(\delta/\alpha)\ell(y)]^\alpha \wedge1}
    \le \nth{[1-(y+1)^{-\delta/\alpha}]^\alpha}
    \le
    \frac{e^\alpha}{[(\delta/\alpha)\ell(y)]^\alpha \wedge1}.
  \end{gather*}
  Since $\nth2(1/a + 1/b) \le(a\wedge b)^{-1}\le 1/a + 1/b$ for
  $a,b>0$,
  \begin{align} \label{e:fpus-sandwich}
    \nth2\Cbr{\frac{c_\alpha}{[\ell(y)]^\alpha}+1}
    \le \nth{[1-(y+1)^{-\delta/\alpha}]^\alpha}
    \le
    e^\alpha\Cbr{\frac{c_\alpha}{[\ell(y)]^\alpha}+1}.
  \end{align}
  Put
  \[
    F^*_\alpha(y,t) = \frac{\cf{0<y<1/t} + \cf{y\ge1/t}
      e^{-ty}}{[\ell(y)]^\alpha} +  \frac{\cf{y>0} e^{-ty}}{c_\alpha}.
  \]
  It is easy to see that for any $t>0$ and $y>0$,
  \[
    \frac{c_\alpha}{[\ell(y)]^\alpha} +  1
    \le
    c_\alpha F^*_\alpha(y,t) e^{ty} \le e
    \Cbr{\frac{c_\alpha}{[\ell(y)]^\alpha} +  1}.
  \]
  Let $G^*\alz(y,\theta) =e^\alpha c_\alpha \HAT e^{-z\HAT}
  F^*_\alpha(y,z\HAT)$.  Then from and \eqref{e:fpus-sandwich} and 
  \eqref{e:fpus-joint},
  \begin{align} \label{e:chi-G*}
    \frac{\chi\alz(y,\theta)}{G^*\alz(y,\theta)}
    =
    \frac{[1-(y+1)^{-\delta/\alpha}]^{-\alpha}}{
       e^\alpha c_\alpha F^*_\alpha(y, z\HAT) e^{z\HAT y}
    } \in [e^{-\alpha-1}/2, 1].
  \end{align}

  Let $r^*_{t,1}(y) = \cf{y\ge1/t}[\ell(y)]^{-\alpha} e^{-ty}$.  By
  \eqref{e:m-r},
  \begin{align} \label{e:F*-F}
    F^*_\alpha(y,t) = m_t(y) + r^*_{t,1}(y) +
    r_{t,2}(y) \le m_t(y) + r_{t,1}(y) + r_{t,2}(y) = F_\alpha(y,t).
  \end{align}
  Then from \eqref {e:F-G} and \eqref{e:chi-G*}, the first
  inequality in \eqref {e:chi-G} follows.  Next, from
  \eqref{e:chi-G*},
  \begin{align*}
    \frac{\iint \chi\alz(y,\theta)\,\dd y\,\dd
      \theta}{\iint G\alz(y,\theta)\,\dd y\,\dd\theta}
    &=
    \frac{\iint \chi\alz(y,\theta)\,\dd y\,\dd
      \theta}{\iint G^*\alz(y,\theta)\,\dd y\,\dd\theta}
    \frac{\iint G^*\alz(y,\theta)\,\dd y\,\dd
      \theta}{\iint G\alz(y,\theta)\,\dd y\,\dd\theta}
    \\
    &
    \ge
    \nth{2e^{\alpha+1}}
    \frac{\int \HAT e^{-z\HAT} [\int F^*_\alpha(y,z\HAT)\,\dd y]
      \dd \theta}
    {\int \HAT e^{-z\HAT} [\int F_\alpha(y,z\HAT)\,\dd y]\dd\theta}
    \\
    &\ge
    \nth{2e^{\alpha+1}}
    \inf_{t>0}
    \frac{\int F^*_\alpha(y,t)\,\dd y}{\int F_\alpha(y,t)\,\dd y}.
  \end{align*}
  For each $t>0$, by \eqref{e:F*-F},
  \[
    \frac{\int F^*_\alpha(y,t)\,\dd y}{\int F_\alpha(y,t)\,\dd y}
    \ge
    \frac{\int r^*_{t,1}(y)\,\dd y}{\int r_{t,1}(y)\,\dd y}
    =
    \frac{\int^\infty_{1/t} e^{-ty}[\ell(y)]^{-\alpha}\,\dd y}
    {\int^\infty_{1/t} e^{-ty}[\ell(1/t)]^{-\alpha}\,\dd y}
    =
    \int^\infty_1 \Sbr{\frac{\ell(1/t)}{\ell(y/t)}}^\alpha
    e^{-y+1}\,\dd y.
  \]
  Since $\ell$ is concave with $\ell(0)=0$ and $y\ge1$, $y\ell(1/t)\ge
  \ell(y/t)$.  Therefore, the \rhs is at least $\int^\infty_1
  y^{-\alpha} e^{-y+1}\,\dd y$.  This combined with the previous
  display then finishes the proof.
\end{proof}%p:chi-G

\begin{proof}[Proof of \Cref{p:nodes}]\phlabel{p:p:nodes}
  Since $\alpha\ge\alpha_0$, by \eqref{e:pars}, $\theta_0 > \pi/3 +
  \pi/(3\alpha)$.  From \Cref{p:H-sand}, $\XIAT$ is increasing on
  $[\theta_0, \pi)$, so every ratio in \eqref{e:K-nodes} is at least
  1.  Next, from \eqref{e:KAT}, 
  \[
    \frac{\XIAT[\theta']}{\XIAT}=
    \frac{\theta'/(\pi-\alpha\theta')}{\theta/(\pi-\alpha\theta)}
    \frac{\XiAT[\theta']}{\XiAT}, \quad
    \theta_0 \le\theta\le\theta'\le\pi.
  \]
  By \Cref{p:H-sand}, $0<\ln\frac{\XiAT[\theta']}{\XiAT} \le \theta^*
  [\ln\nth{\sinc(x)}]''|_{x = \pi - \alpha\theta^*} (\theta' - 
  \theta)$ for some $\theta^*\in (\theta, \theta')$.  From \eqref
  {e:sinc-zeta}, $[\ln\nth{\sinc(x)}]''$ is increasing on $(0,\pi)$.
  Let $C$ be as in \Cref{p:nodes}.  Then $\ln\frac{\XiAT[\theta']}
  {\XiAT}\le C(\theta' - \theta)$.  Then
  $\XIAT[f_\alpha(\theta)]/\XIAT \le (1+\Delta/2) \exp[C 
  (f(\theta) - \theta)] \le 1+\Delta$.  Furthermore, $\theta\le
  f_\alpha(\theta) \le \pi$ with either equality holding
  $\Iff\theta=\pi$.  Next show that the number of $\theta_i$ in $(0,
  \pi)$ is $O(\ln(1/\delta))$.  Put
  \[
    \rx = \nth C\ln\frac{1+\Delta}{1+\Delta/2}.
  \]
  Then
  \begin{align} \label{e:falpha}
    f_\alpha(\theta) = \min(\pi, g_\alpha(\theta), \theta+\rx),
    \text{~where~}
    g_\alpha(\theta) = \frac{(1+\Delta/2)\theta}
    {1+\alpha(\Delta/2)\theta/\pi}.
  \end{align}
  From
  \[
    g'_\alpha(\theta) = \frac{1+\Delta/2}
    {[1+\alpha(\Delta/2)\theta/\pi]^2},
  \]
  $g_\alpha(\theta)$ is strictly increasing and concave.  From the
  choice of $\alpha_0$ and $\theta_0$ in \eqref{e:pars},
  $\alpha\theta/\pi \ge \alpha_0\theta_0/\pi>1/2$.  Then
  \[
    g'_\alpha(\theta)\le g'_\alpha(\theta_0)
    <\frac{1+\Delta/2}{1+\alpha\Delta\theta_0/\pi} <1.
  \]
  Then $g_\alpha(\theta) = \theta+\rx$ has at most one solution in
  $(\theta_0, \infty)$.  Suppose there is a solution $\theta_*$.  Then
  $g_\alpha(\theta)\ge \theta+\rx$ on $[\theta_0,\theta_*]$ and
  $g_\alpha(\theta) \le \theta+\rx$ on $[\theta_*,\infty)$.  For every
  $\theta_i \le \theta_*$, $\theta_{i+1} =  \theta_i + \rx$.  As a
  result, the number of $\theta_i$'s in $[\theta_0, \theta_*]$ is
  $O(1/\rx) = O(1)$.  On the other hand, if $\theta_i$ and
  $\theta_{i+1}$ are in $[\theta_*, \pi)$, then $\theta_{i+1} =
  g_\alpha(\theta_i)$, giving $\frac{\theta_{i+1}}{\pi -
    \alpha\theta_{i+1}} = (1+\frac\Delta 2) \frac{\theta_i}{\pi -
    \alpha\theta_i}$.  By induction, if $\theta_{i+k}\in
  [\theta_*,\pi)$, then $\frac{\theta_{i+k}}{\pi - \alpha\theta_{i+k}}
  = (1+\frac\Delta 2)^k \frac{\theta_i}{\pi - \alpha\theta_i}\ge
  (1+\frac\Delta 2)^k \frac{\theta_0}{\pi - \alpha\theta_0}$.
  However, when $\frac\theta{\pi - \alpha\theta}$ is increasing on
  $[\theta_0, \pi]$, and when $\theta=\pi$, $\frac\theta{\pi -
    \alpha\theta} = \nth\delta$.  As a result, $\nth\delta
  \ge(1+\frac\Delta 2)^k \frac{\theta_0}{\pi -\alpha\theta_0}$.  Then
  the number of $\theta_i$ in $[\theta_*, \pi)$ is $O(\ln(1/\delta))$.
  Therefore the number of $\theta_i$'s in $[\theta_0, \pi)$ is
  $O(\ln(1/\delta))$.  The case where $g_\alpha(\theta) = \theta+\rx$
  has no solution on $(\theta_0,\infty)$ can be similarly dealt with.

  Finally, since $\theta_\nal$ is the last $\theta_i$ in $[\theta_0,
  \pi)$, then $g_\alpha(\theta_\nal)\ge\pi$ and $\theta_\nal+\rx
  \ge\pi$.  Then it is easy to get $\XIAT[\pi]/\XIAT\le1+\Delta$.  The
  proof is complete.
\end{proof} % \label{p:nodes}

To prove \Cref{p:N-J-sup}, we need the following two lemmas.
\begin{lemma} \label{l:convex}
  Let $c\ge0$ be a constant and $F(x)>0$ be a continuous function on
  an interval $I$.  Let $I_c = \{x\in I: F(x)\ge c\}$.
  \begin{subenum}
  \item If $F$ is increasing on $I$, then $F^c e^{-F}$ is decreasing
    on $I_c$.
  \item If $F$ is convex, then $F^c e^{-F}$ is log-concave on any
    interval in $I_c$. 
  \end{subenum}
\end{lemma}

\begin{proof}
  Let $f(v) = c\ln v - v$.  Then $f$ is concave and decreasing on
  $[c,\infty)$.  Since $\ln (F^c e^{-F}) = f\circ F$, 1) is plain.
  For 2), fix any
  $[x,y]\subset I_c$ and $a\in (0,1)$.  Let $z=(1-a)x + a y$.  Then
  $c\le F(z) \le (1-a) F(x) + a F(y)$, giving $f(F(z)) \ge
  f((1-a) F(x) + a F(y)) \ge (1-a) f(F(x)) + a f(F(y))$.  As a result,
  $f\circ F$ is concave.  Then $F^c e^{-F}$ is log-concave.
\end{proof} %l:convex

\begin{lemma} \label{l:integral}
  Let $f>0$ be a function on an interval $I$ with $0<\int_I
  f<\infty$, and $g$ a strictly increasing and differentiable
  convex function on an interval $J$ with $g(J)=I$.  Then
  \[
    \frac{\int_{J\cap (-\infty,x]} f\circ g}{\int_{I\cap (-\infty,
        g(x)]} f}
    \ge
    \nth{g'(x)} \ge
    \frac{\int_{J\cap [x,\infty)} f\circ g}{\int_{I\cap [g(x),
        \infty)} f} 
  \]
  for any non-boundary point $x\in J$.
\end{lemma}

\begin{proof}
  Since $x$ is in the inner part of $J$, then $g(x)$ is in the inner
  part of $I$, so $\int_{I\cap (-\infty, g(x)]} f>0$ and $\int_{I\cap
    [g(x), \infty)} f>0$.  Then $\int_{I\cap (-\infty, g(x)]} f =
  \int_{J\cap (-\infty, x]} (f\circ g) g' \le g'(x) \int_{J\cap
    (-\infty, x]} f\circ g$ and $\int_{I\cap [g(x), \infty} f =
  \int_{J\cap [x, \infty)} (f\circ g) g'\ge g'(x) \int_{J\cap
    [x,\infty)} f\circ g$, yielding the inequalities.
\end{proof} %l:integral


\begin{proof}[Proof of \Cref{p:N-J-sup}] \phlabel{p:p:N-J-sup}
  Let $\theta\in [\vartheta_z,\pi)$.  As in \eqref{e:calpha}, let
  $\tau = z\HAT$.  Since $z\JAT\ge1$, by \eqref{e:JH}, $\tau\ge1$.
  Then $(1/\tau)\ln2\le \ln(1+1/\tau) \le1/\tau$, so from the
  expression of $\psi_\alpha$ in \eqref{e:kappa-psi-alpha},
  $\kappa_{\alpha,4}\le \lfrac{\psi_\alpha(\tau)}{\tau^\alpha}
  \le\kappa_{\alpha,3}$.  Define $D\alz(\theta) =
  \kappa_{\alpha,3}\tau^\alpha e^{-\tau}$.  Then from \eqref{e:Dpsi2},
  \begin{align} \label{e:K-D-ratio}
    \frac{\kappa_{\alpha,4}}
    {\kappa_{\alpha,3}}
    \le \frac{Q\alz(\theta)}{D\alz(\theta)}
    = \frac{\psi_\alpha(\tau)}{\kappa_{\alpha,3} \tau^\alpha}
    \le1,
    \quad
    \theta\in [\vartheta_z, \pi),
  \end{align}
  in particular, $Q\alz(\theta) \le D\alz(\theta)$.  From \cite
  {gonzalez:23:arxiva}, $z\HAT$ is strictly increasing and 
  convex.  Then by \Cref{l:convex}, $D\alz(\theta)$ is decreasing and
  log-concave on $[\vartheta_z, \pi)$.  Therefore, by
  \eqref{e:log-concave}, for any $A\ge \int^\pi_{\vartheta_z} D\alz$,
  \begin{align} \label{e:K-D-log-concave}
    D\alz(\theta) \le 2 A \Vrx_s(\theta - \vartheta_z)
    \quad\text{with~} s = D\alz(\vartheta_z)/A.
  \end{align}
  From \Cref{l:integral},
  \begin{align*}
    \int^\pi_{\vartheta_z} D\alz
    \le
    \frac{\kappa_{\alpha,3}}{z\dHAT[\vartheta_z]}
    \int^\infty_{z\HAT[\vartheta_z]} s^\alpha e^{-s}\,\dd s
    &\le
    \frac{\kappa_{\alpha,3}}{z\dHAT[\vartheta_z]}
    \intzi s^\alpha e^{-s}\,\dd s
    \\
    &=
    \frac{\kappa_{\alpha,3}\Gamma(1+\alpha)}{z\dHAT[\vartheta_z]}
    \le \frac{\kappa_{\alpha,3}}{z\dHAT[\vartheta_z]}.
  \end{align*}
  Since $z\dHAT[\vartheta_z] = z\HAT[\vartheta_z] (\ln
  H_\alpha)'(\vartheta_z) = \tau_z \varrho_z$, then 
  letting $A=\kappa_{\alpha,3}/[z\dHAT[\vartheta_z]]$ in \eqref
  {e:K-D-log-concave} gives \eqref{e:z-star}.  Since $z\HAT[\vartheta_z]
  \ge z\JAT[\vartheta_z]\ge1$, then from \Cref{l:integral} and 
  \eqref{e:K-D-ratio}
  \[
    \nth{z\dHAT[\vartheta_z]}
    \le
    \frac{\int^{\vartheta_z}_0 D\alz}
    {\kappa_{\alpha,3} \int^{z\HAT[\vartheta_z]}_{z
        \HAT[0]} s^\alpha e^{-s}\,\dd s}
    \le \frac{\int^{\vartheta_z}_0 Q\alz}{\kappa_{\alpha,4}\int^1_z
      s^\alpha e^{-s}\,\dd s}. 
  \]
  Since $s^\alpha>s$ for $s\in (z,1)$, then \eqref{e:K-sup} follows.

  Finally, for $\alpha\ge\alpha_0$, since $\alpha_0>1/2$, then
  $2\alpha-1\ge0$, so
  \begin{align*}
    \frac{\kappa_{\alpha,3}}{\kappa_{\alpha,4}}
    &=
    \frac
    {(2\alpha-1)/(1-\alpha) + (\ln2)^{-\alpha}(2+e^{-1}) +
      [(1-\alpha)/\alpha]^\alpha}
    {(\ln2)^{1-\alpha}(2\alpha-1)/(1-\alpha) + 2+e^{-1}}
    \\
    &\le
    \frac
    {(2\alpha-1)/(1-\alpha) + (\ln2)^{-\alpha}(2+e^{-1}) +
      [(1-\alpha)/\alpha]^\alpha}
    {(\ln2)^{1-\alpha}(2\alpha-1)/(1-\alpha)}
    \\
    &=
    (\ln 2)^{\alpha-1} + \frac{2+e^{-1}}{\ln
      2}\frac{1-\alpha}{2\alpha-1} +
    \Grp{\frac{1-\alpha}\alpha}^\alpha
    \frac{1-\alpha}{2\alpha-1}.  \tag*{\qedhere}
  \end{align*}
\end{proof}%p:N-J-sup

For the proof of \Cref{p:N-J-sandwich}, we need the following.
\begin{lemma} \label{l:psi-alpha}
  The function  $\psi_\alpha(s)=\kappa_{\alpha,1}[\ell(1/s)]^\delta s +
  \kappa_{\alpha,2}[\ell(1/s)]^{-\alpha} + 1$ in
  \eqref{e:kappa-psi-alpha} is increasing on $(0,\infty)$ and for
  $a\ge1$, $0<\psi_\alpha(as)\le a\psi_\alpha(s)$.
\end{lemma}
\begin{proof}
  Since $\ell(t) = \ln(1+t)$ is concave in $t>0$, $\ell(t)/t =
  [\ell(t)-\ln(0)]/t$ is decreasing.  Letting $t=1/s$, $s\ell(1/s)$ is
  increasing, so $[\ell(1/s)]^\delta s = [s\ell(1/s)]^\delta s^\alpha$
  is increasing.  Then it is easy to see that $\psi_\alpha(s)$ is
  increasing.  Let $a\ge1$.  Clearly, $[\ell(1/(as))]^\delta(as)\le
  [\ell(1/s)]^\delta (as)$.  By concavity, $\ell(1/(as))\ge
  (1/a)\ell(1/s)$, so $[\ell(1/(as))]^{-\alpha}
  \le[(1/a)\ell(1/s)]^{-\alpha} < a [\ell(1/s)]^{-\alpha}$.  Then it
  follows that $\psi_\alpha(as)\le a\psi_\alpha(s)$.
\end{proof} 

\begin{proof}[Proof of \Cref{p:N-J-sandwich}]
  \phlabel{p:p:N-J-sandwich}
  From \eqref{e:Dpsi2}, \eqref{e:JH}, and \Cref{l:psi-alpha}, 
  \[
    Q\alz(\theta) = \psi_\alpha(z\HAT) e^{-z\HAT} \le
    \psi_\alpha(z\HAT) \le (1+\Delta)\psi_\alpha(z\JAT).
  \]
  On the other hand,  since $z\JAT<1$, $z\HAT<1+\Delta$, yielding
  \[
    Q\alz(\theta) \ge 
    e^{-1-\Delta} \psi_\alpha(z\HAT) \ge e^{-1-\Delta} 
    \psi_\alpha(z\JAT).  \eqno{\qedhere}
  \]
\end{proof}

\begin{proof}[Proof of \Cref{l:N-J-mid}]\phlabel{p:l:N-J-mid}
  Put $\phi(\theta) =\psi_\alpha(z\JAT)$, where again $\psi_\alpha$ is
  given in \eqref{e:Dpsi2}.  We will show that for each $n$, provided
  $I_n = [\theta_n\wedge\vartheta_z, \theta_{n+1}\wedge \vartheta_z)\ne
  \emptyset$,
  \begin{align} \label{e:cP}
    v_n P_n(t) \le \laz\#\phi(t)\le P_n(t),  \quad t\in \laz(I_n) =
    (c_n, d_n],
  \end{align}
  where $c_n$ and $d_n$ are as in \eqref{e:lambda-I}.  Once
  \eqref{e:cP} is established, it yields
  \[
    v_n \laz^{-1}\# P_n(\theta) \le \phi(\theta) \le \laz^{-1}\#
    P_n(\theta),
    \quad \theta\in I_n,
  \]
  which combined with \eqref{e:psi-phi} gives \eqref{e:Q-P}.

  To start, on the interval $[\theta_0, \vartheta_z)$, by $\laz(\theta)=
  \ell\Grp{\nth{z\JAT}}$,  
  \[
    \phi(\theta)
    = \kappa_{\alpha,1}[\laz(\theta)]^\delta
    (e^{\laz(\theta)}-1)^{-1} +
    \kappa_{\alpha,2}[\laz(\theta)]^{-\alpha} + 1.
  \]
  Since $\laz(\theta)$ is strictly decreasing and piecewise
  differentiable, for $t\in\laz([\theta_0, 
  \vartheta_z))$,
  \begin{align} \label{e:lambda-pw-phi}
    \laz\#\phi(t)
    = \phi(\laz^{-1}(t)) |(\laz^{-1})'(t)|
    = [\kappa_{\alpha,1} t^\delta(e^t-1)^{-1} + \kappa_{\alpha,2}
    t^{-\alpha} + 1]\times |(\laz^{-1})'(t)|.
  \end{align}
  We have  $\laz^{-1}(t) = \IJAT[z^{-1}(e^t-1)^{-1}]$.  Put
  \begin{align} \label{e:t-theta-s}
    \theta = \laz^{-1}(t), \quad s=[z(e^t-1)]^{-1}.
  \end{align}
  Then $s = \JAT$, $t=\ell(1/(zs))$, and by the chain rule, 
  \begin{align} \label{e:lambda}
    |(\laz^{-1})'(t)| = \dIJAT[s]\times \frac{e^t}{z(e^t-1)^2}.
  \end{align}
  Let $t\in \laz(I_n) = (c_n,
  d_n]$.  Then $\theta\in [\theta_n \wedge \vartheta_z,
  \theta_{n+1}\wedge\vartheta_z) = [\theta_n, \theta_{n+1})\cap [0,
  \vartheta_z)\ne\emptyset$.  By \eqref{e:JAT-upper},
  \begin{align} \label{e:JAT-inv}
    s = \XIAT[\theta_n]\Sbr{1+\frac{\delta\pi}{\alpha (\pi -
        \theta)}}^{1/\delta}, \quad
    \theta= \IJAT[s] = \pi-\frac{\delta\pi/\alpha}
    {[\frac s{\XIAT[\theta_n]}]^\delta-1}.
  \end{align}
  As a result,
  \begin{align} \label{e:JAT-inv-diff}
    \dIJAT[s]
    &= \nth{[\XIAT[\theta_n]]^\delta}
    \frac{(\delta\pi/\alpha) \delta s^{\delta-1}}
    {([\frac s{\XIAT[\theta_n]}]^\delta-1)^2}
    \\ \label{e:JAT-inv-diff2}
    &= \frac{(\alpha/\pi) s^{-\alpha}}{[\XIAT[\theta_n]]^\delta}(\pi
    - \theta)^2.
  \end{align}
  On the other hand, from \eqref{e:mid-range-consts}, $z s =
  z \JAT < z\JAT[(\theta_{n+1}\wedge \vartheta_z)-] = a_n$.   Then
  \begin{align} \label{e:expt}
    e^t - 1 = e^t(1 - e^{-t})  = e^t(1+zs)^{-1} \ge e^t/(1 + a_n).
  \end{align}
  Then from \eqref{e:t-theta-s} and \eqref{e:lambda},
  \begin{align} \label{e:inverse-diff}
    \begin{split}
      z^{-1}[\dIJAT[s]] e^{-t}<
      &
      |(\laz^{-1})'(t)|< z^{-1}(1+a_n)^2[\dIJAT[s]] e^{-t}, \\
      z^{-1} e^{-t} <
      &s < (1+a_n) z^{-1} e^{-t}.
    \end{split}
  \end{align}

  First, suppose $\theta_n\le (1-\delta/\alpha)\pi$.  Clearly,
  $\pi-\theta \le \pi-\theta_n$.  On the other hand, by
  \Cref{p:nodes}, $\theta_{n+1} = f_\alpha(\theta_n)$, so from
  \eqref{e:falpha},
  \[
    \pi-\theta \ge \pi - (\theta_{n+1}\wedge \vartheta_z)
    \ge\pi - g_\alpha(\theta_n)
    =\pi - \frac{(1+\Delta/2)\theta_n}{1 + \alpha
      (\Delta/2)\theta_n/\pi}
    = \frac{\pi - \theta_n - \delta(\Delta/2)\theta_n}{1+ \alpha
      (\Delta/2) \theta_n/\pi}.
  \]
  From $\delta(\Delta/2) \theta_n \le (\alpha-\delta)(\Delta/2)(\pi -
  \theta_n)$ and $\alpha(\Delta/2) \theta_n/\pi\le (\Delta/2)(\alpha -
  \delta)$, the \rhs is at least
  \[
    \frac{(\pi - \theta_n)[1- (\alpha - \delta)\Delta/2]}{
      1+ (\alpha - \delta)\Delta/2}
    \ge
    \frac{(\pi - \theta_n)(1- \Delta/2)}{1+ \Delta/2}.
  \]
  Then by \eqref{e:JAT-inv-diff2} and $[(1-\Delta/2)/(1+\Delta/2)]^2
  >(1-\Delta)/(1+\Delta)$,
  \[
    \Grp{\frac{1-\Delta}{1+\Delta}}
    \frac{(\alpha/\pi) s^{-\alpha}}{[\XIAT[\theta_n]]^\delta}
    (\pi - \theta_n)^2
    \le
    \dIJAT[s]\le \frac{(\alpha/\pi) s^{-\alpha}}
    {[\XIAT[\theta_n]]^\delta} (\pi - \theta_n)^2.
  \]
  This combined with \eqref{e:lambda-pw-phi}, \eqref{e:t-theta-s},
  \eqref{e:expt}, and \eqref{e:inverse-diff} yields two inequalities.
  First,
  \begin{align*}
    \laz\#\phi(t)
    &\le
    [\kappa_{\alpha,1} t^\delta(e^t-1)^{-1} +\kappa_{\alpha,2}
    t^{-\alpha} + 1] 
    \times \frac{(1+a_n)^2(\alpha/\pi) s^{-\alpha}}{z
      [\XIAT[\theta_n]]^\delta} (\pi - \theta_n)^2 e^{-t}
    \\
    &\le
    [(1+a_n)\kappa_{\alpha,1} t^\delta e^{-t}+ \kappa_{\alpha,2}
    t^{-\alpha} + 1] \times
    \frac{(1+a_n)^2(\alpha/\pi) z^\alpha e^{\alpha t}} 
    {z [\XIAT[\theta_n]]^\delta}(\pi - \theta_n)^2 e^{-t}
    \\
    &=
    \frac{(1+a_n)^2(\alpha/\pi)} {[z\XIAT[\theta_n]]^\delta}
    (\pi - \theta_n)^2 
    \times [(1+a_n)\kappa_{\alpha,1} t^\delta e^{-t}  +
    \kappa_{\alpha,2} t^{-\alpha} + 1] e^{-\delta t}.
  \end{align*}
  By \eqref{e:mid-range-P1}, the \rhs is $P_n(t)$.  On the other hand,
  \begin{align*}
    \laz\#\phi(t)
    &\ge
    [\kappa_{\alpha,1} t^\delta(e^t-1)^{-1} +\kappa_{\alpha,2}
    t^{-\alpha} + 1] 
    \times \Grp{\frac{1-\Delta}{1+\Delta}}
    \frac{(\alpha/\pi) s^{-\alpha}}{z[\XIAT[\theta_n]]^\delta}
    (\pi - \theta_n)^2 e^{-t}
    \\
    &\ge
    (\kappa_{\alpha,1} t^\delta e^{-t}+\kappa_{\alpha,2} t^{-\alpha}+
    1) \times\Grp{\frac{1-\Delta}{1+\Delta}}
    \frac{(\alpha/\pi) z^\alpha e^{\alpha t}} 
    {(1+a_n)^\alpha z[\XIAT[\theta_n]]^\delta}(\pi - \theta_n)^2
    e^{-t}
    \\
    &=\Grp{\frac{1-\Delta}{1+\Delta}}
    \frac{(\alpha/\pi)} {(1+a_n)^\alpha [z\XIAT[\theta_n]]^\delta}
    (\pi - \theta_n)^2 \times (\kappa_{\alpha,1} t^\delta e^{-t}  +
    \kappa_{\alpha,2} t^{-\alpha} + 1) e^{-\delta t}.
  \end{align*}
  The \rhs is at least $\Grp{\frac{1 - \Delta}{1 +\Delta}} (1+
  a_n)^{-\alpha-3} P_n(t) = v_n P_n(t)$, where $v_n$ is defined as in
  \Cref{l:N-J-mid}.  Then \eqref{e:cP} holds in the case where
  $\theta_n \le (1-\delta/\alpha)\pi$.

  Next, suppose $\theta_n>(1-\delta/\alpha)\pi$.  By
  \eqref{e:JAT-inv},
  \[
    \Sbr{\frac s{\XIAT[\theta_n]}}^\delta
    =1 + \frac{\delta\pi}{\alpha(\pi-\theta)}
    \ge1 + \frac{\delta\pi}{\alpha(\pi-\theta_n)}
    = \frac{\pi - \alpha\theta_n}{\alpha(\pi-\theta_n)},
  \]
  and so
  \[
    \Sbr{\frac s{\XIAT[\theta_n]}}^\delta -1
    \ge\Sbr{\frac s{\XIAT[\theta_n]}}^\delta
    \Cbr{1-\frac{\alpha(\pi-\theta_n)}{\pi - \alpha\theta_n}}
    = b_n \Sbr{\frac s{\XIAT[\theta_n]}}^\delta,
  \]
  where $b_n$ is given in \eqref{e:mid-range-consts}; note that
  $b_n>1/2$.  Then by \eqref{e:JAT-inv-diff},
  \[
    \nth{[\XIAT[\theta_n]]^\delta}
    \frac{(\delta\pi/\alpha) \delta s^{\delta-1}}
    {[\frac s{\XIAT[\theta_n]}]^{2\delta}}
    \le
    \dIJAT[s]
    \le
    \nth{[\XIAT[\theta_n]]^\delta}
    \frac{(\delta\pi/\alpha) \delta s^{\delta-1}}
    {b^2_n [\frac s{\XIAT[\theta_n]}]^{2\delta}},
  \]
  which combined with \eqref{e:t-theta-s} gives
  \[
    (\delta^2\pi/\alpha)[\XIAT[\theta_n]]^\delta
    [z(e^t-1)]^{\delta+1}
    \le
    \dIJAT[s]
    \le
    \nth{b^2_n}
    (\delta^2\pi/\alpha)[\XIAT[\theta_n]]^\delta
    [z(e^t-1)]^{\delta+1}.
  \]
  This combined with \eqref{e:lambda-pw-phi} and
  \eqref{e:inverse-diff} yields two inequalities.  First,
  \begin{align*}
    \laz\#\phi(t)
    &\le
    [\kappa_{\alpha,1} t^\delta(e^t-1)^{-1} +\kappa_{\alpha,2}
    t^{-\alpha} + 1] 
    \times
    \frac{(1+a_n)^2}{z b^2_n}(\delta^2\pi/\alpha)
    [\XIAT[\theta_n]]^\delta
    [z(e^t-1)]^{\delta+1} e^{-t}
    \\
    &=
    \frac{(1+a_n)^2}{b^2_n}(\delta^2\pi/\alpha)
    [z\XIAT[\theta_n]]^\delta
    [\kappa_{\alpha,1} t^\delta(e^t-1)^\delta +(\kappa_{\alpha,2}
    t^{-\alpha} + 1) (e^t-1)^{\delta+1}] e^{-t}
    \\
    &\le
    \frac{(1+a_n)^2}{b^2_n}(\delta^2\pi/\alpha)
    [z\XIAT[\theta_n]]^\delta
    [\kappa_{\alpha,1} t^\delta e^{-\alpha t} +(\kappa_{\alpha,2}
    t^{-\alpha} + 1) e^{\delta t}].
  \end{align*}
  From \eqref{e:mid-range-P2}, the \rhs is $P_n(t)$.  On the other
  hand,
  \begin{align*}
    \laz\#\phi(t)
    &\ge
    [\kappa_{\alpha,1} t^\delta(e^t-1)^{-1} +\kappa_{\alpha,2}
    t^{-\alpha} + 1] 
    \times
    z^{-1}(\delta^2\pi/\alpha)[\XIAT[\theta_n]]^\delta
    [z(e^t-1)]^{\delta+1} e^{-t}
    \\
    &=
    (\delta^2\pi/\alpha)[z\XIAT[\theta_n]]^\delta
    [\kappa_{\alpha,1} t^\delta(e^t-1)^\delta +(\kappa_{\alpha,2}
    t^{-\alpha} + 1) (e^t-1)^{\delta+1}] e^{-t}.
  \end{align*}
  Since $\theta<\vartheta_z$, $z\JAT<1$.  Then by \eqref{e:t-theta-s},
  $e^t = 1+\nth{z\JAT}\ge2$, giving $e^t-1\ge e^t/2$.  Then
  \begin{align*}
    \laz\#\phi(t)
    &\ge
    (\delta^2\pi/\alpha)[z\XIAT[\theta_n]]^\delta
    [\kappa_{\alpha,1} (t/2)^\delta e^{\delta t} +(\kappa_{\alpha,2}
    t^{-\alpha} + 1) (e^t/2)^{\delta+1}] e^{-t}
    \\
    &=
    2^{-\delta}
    (\delta^2\pi/\alpha)[z\XIAT[\theta_n]]^\delta
    [\kappa_{\alpha,1} t^\delta e^{-\alpha t} +(\kappa_{\alpha,2}
    t^{-\alpha} + 1) e^{\delta t}/2].
  \end{align*}
  The \rhs is at least $\frac{b^2_n}{2^{1+\delta} (1+a_n)^2} P_n(t) =
  v_n P_n(t)$.  Then \eqref{e:cP} again holds. 
\end{proof}%l:N-J-mid


\begin{proof}[Proof of \Cref{p:N-J-mid2}] \phlabel{p:p:N-J-mid2}
  If
  $\theta_n\le (1-\delta/\alpha)\pi$, then by \eqref{e:mid-range-P1},
  for $t\in (c_n, d_n]$,
  \[
    P_n(t)
    =
    \pi_n
    [(1+a_n)\kappa_{\alpha,1} t^\delta e^{-(1+\delta) t}
    + \kappa_{\alpha,2} t^{-\alpha} e^{-\delta t} +  e^{-\delta t}]
    \cf{c_n<t\le d_n}
  \]
  From the definition of $g_{a,b,c}$ in \eqref{e:gabc},
  \begin{align*}
    &
    t^\delta e^{-(1+\delta) t}\cf{c_n < t\le d_n}
    \\
    &=(1+\delta)^{-\delta} [(1+\delta) t]^\delta
    e^{-(1+\delta)t}\cf{(1+\delta)c_n < (1+\delta) t\le (1+\delta)
      d_n} \\
    &=(1+\delta)^{-\delta} g_{(1+\delta)c_n,
      (1+\delta) d_n, 1+\delta}((1+\delta) t)
  \end{align*}
  and
  \[
    t^{-\alpha} e^{-\delta t}\cf{c_n < t\le d_n}
    = \delta^\alpha (\delta t)^{-\alpha} e^{-\delta t} \cf{\delta
      c_n < \delta t \le \delta d_n}
    = \delta^\alpha g_{\delta c_n, \delta
      d_n,\delta}(\delta t).
  \]
  Then by \eqref{e:icgamma-env}, $P_n(t)\cf{c_n < t\le d_n} \le
  P^*_n(t)$ and
  \[
    \nth{2e} \int 
    \laz^{-1}\#P^*_n
    =
    \nth{2e} \int 
    P^*_n
    \le
    \int P_n(t)\cf{c_n < t\le d_n}
    = \int_{I_n}\laz^{-1}\#P.
  \]
  This combined with \eqref{e:Q-P} yields the proof of
  \eqref{e:mid-range-P-env} when $\theta_n\le (1-\delta/\alpha)\pi$.

  On the other hand, if $\theta_n> (1-\delta/\alpha)\pi$, then by
  \eqref{e:mid-range-P2}, for $t\in (c_n, d_n]$,
  \[
    P_n(t)=\pi_n (\kappa_{\alpha,1} t^\delta e^{-\alpha t} +
    \kappa_{\alpha,2} t^{-\alpha}e^{\delta t} + e^{\delta t})
    \cf{c_n<t\le d_n}.
  \]
  Similar to the above argument, for $c_n<t\le d_n$, $t^\delta
  e^{-\alpha t} =\alpha^{-\delta} g_{\alpha c_n, \alpha d_n,
    1+\delta}(\alpha t)$ and $t^{-\alpha} e^{\delta t} =\delta^\alpha
  \varphi_{\delta c_n, \delta d_n,\delta}(\delta t)$, where
  $\varphi_{a,b,c}$ is defined in \eqref{e:varphi-def}.   Then the
  proof of \eqref{e:mid-range-P-env} in this case follows from 
  \eqref{e:varphi*}, \eqref{e:icgamma-env}, and
  \eqref{e:mid-range-P2}.
\end{proof}%p:N-J-mid2

\begin{proof}[Proof of \Cref{l:lambda-inv}] \phlabel{p:l:lambda-inv}
  The first expression in \eqref{e:lambda-inv} is a repeat of
