Thus, we find:
\begin{subequations}
\begin{align}
&\Phi_{\epsilon}^{(o)}(z+1,a,m; \mathfrak{q})=\sum_{\epsilon''=\pm}M_{A,\,\epsilon \epsilon''}^{(o)}\Phi_{\epsilon''}^{(o)}(z,a,m; \mathfrak{q}),\\
&\Phi_{\epsilon}^{(o)}(z+\tau,a,m; \mathfrak{q})=\sum_{\epsilon'''=\pm}M_{B,\,\epsilon \epsilon'''}^{(o)}\Phi_{\epsilon'''}^{(o)}(z,a,m; \mathfrak{q}),
\end{align}
\end{subequations}
where 
\begin{subequations}
\label{eq: Ma, Mb ope}
\begin{align}
&M_{A,\,\epsilon \epsilon''}^{(o)}=\sum_{\epsilon'=\pm}\mathbb{F}^{-1}_{\epsilon\epsilon'}\begin{bmatrix}
m & -b/2\\
a & a
