m & -b/2\\
a & a
\end{bmatrix}M_{B,\,\epsilon' \epsilon''}^{(n)}\mathbb{F}_{\epsilon''\epsilon'''}\begin{bmatrix}
m & -b/2\\
a & a
\end{bmatrix},
\end{align}
\end{subequations}
and the shift operator $e^{k\partial_{a}}$ in $M_{B}^{(n)}$ acts on everything on its right. By going to the OPE channel basis (\ref{eq: 0mono}), we can also compute the monodromy matrix for the analytic continuation of necklace channel blocks around the point $z=0$, which is given by:
\begin{equation}
\label{eq: M0 necklace}
M^{(n)}_{0,\,\epsilon\epsilon''}=\sum_{\epsilon'=\pm}\mathbb{F}_{\epsilon\epsilon'}\begin{bmatrix}
m & -b/2\\
a & a
\end{bmatrix}e^{2\pi i(\Delta_{m_{\epsilon'}}-\Delta_{m}-\Delta_{(2,1)})}\mathbb{F}^{-1}_{\epsilon'\epsilon''}\begin{bmatrix}
m & -b/2\\
a & a
\end{bmatrix}.
\end{equation}
Similarly, by decomposing the computation in terms of the elementary fusion and braiding matrices, one can obtain the monodromy matrix for the analytic continuation of any n-point block, with the insertion of at least one degenerate $\phi_{(2,1)}$, around any point of insertion of other primaries and around the two non-trivial cycles of the torus.
\subsection{The Lamé and the Mathieu equations}
The torus conformal blocks (\ref{eq: torusblock}) satisfy the BPZ equation:
\begin{equation}
\label{eqn:BPZt1}
    \Big(-b^{-2}\partial_{z}^{2}+\zeta_{*}(z)\partial_{z}-\Delta_{m}\wp_{*}(z)-2\Delta_{(2,1)}\eta_{1}-2\pi i\partial_{\tau}\log Z(\tau)-2\pi i\partial_{\tau}\Big)\Phi(z,a,m; \mathfrak{q})=0,
\end{equation}
where $\zeta_{*}(z)=\zeta(z; 1,\tau)-2\eta_{1}z$ and $\wp_{*}(z)=\wp(z;1, \tau)+2\eta_{1}$ \cite{Piatek:2013ifa}, $\wp$ and $\zeta$ being the Weierstrass elliptic functions, see Appendix \ref{app: special functions} for the conventions adopted. In the $semi$-$classical$ limit $b\rightarrow 0$ \cite{Zamolodchikov:1995aa, Desiraju:2024fmo}, considering $a=\alpha/b$ and $m=\mu/b$, the conformal blocks have the asymptotic behavior:
\begin{equation}
    \Phi\left(z,a,m; \mathfrak{q}\right) \simeq e^{\frac{1}{b^{2}}f(\alpha,\mu;\mathfrak{q})}\psi(z,\alpha, \mu;\mathfrak{q}),
\end{equation}
where $f(\alpha,\mu; \mathfrak{q})$ is the semi-classical 1-point torus conformal block:
\begin{equation}
f(\alpha,\mu; \mathfrak{q})=\lim_{b\to 0}b^{2}\log \mathcal{F}\left(\frac{\alpha}{b},\frac{\mu}{b}; \mathfrak{q}\right),
\end{equation}
with $\mathcal{F}(a,m; \mathfrak{q})$ being the 1-point torus conformal block, while the $semi$-$classical$ 2-point block\footnote{Due to the AGT correspondence \cite{Alday:2009aq}, the 2-point block on the torus, and thus its semi-classical limit, can be computed via simple combinatorial formulas, see equations \eqref{eq: block = inst} and (\ref{eq: classical defect}).} is given by:
\begin{equation}
\label{eq: 2pt classical}
\psi(z,\alpha,\mu; \mathfrak{q})=\lim_{b\to 0}\frac{\Phi(z,\alpha/b,\mu/b; \mathfrak{q})}{\mathcal{F}(\alpha/b,\mu/b; \mathfrak{q})}.
\end{equation}
In this limit, equation (\ref{eqn:BPZt1}) reduces to the Lamé equation in Weierstrass form: 
\begin{equation}
\label{eq: lame1}
    \left(\partial_{z}^{2}+E-\mu(\mu-1) \wp(z)\right)\psi(z,\alpha,\mu; \mathfrak{q})=0,
\end{equation}
and the eigenvalue $E$ is given in terms of the semi-classical 1-point block as:
\begin{equation}
\label{eq: Ens}
E=-2\mu(\mu-1)\eta_{1}-4\pi^{2}\mathfrak{q}\partial_{\mathfrak{q}}f(\alpha,\mu; \mathfrak{q}).
\end{equation}
To obtain connection formulas for the analytic continuation of solutions to the Lamé equation, we can simply take the semi-classical limit of the monodromy matrices \eqref{eq: Mb necklace}, \eqref{eq: Ma, Mb ope} and \eqref{eq: M0 necklace} derived in the previous section. More precisely, the necklace channel blocks (\ref{eq: necklace blocks}) descend to a basis of Floquet solutions to the Hill equation\footnote{Indeed, this equation defines a $real$ periodic spectral problem for $\tau \in i\mathbb{R}$.}
\begin{equation}
\label{eq: hill}
    \left(\partial_{x}^2+E-\mu(\mu-1)\wp(x+\tau/2)\right)\psi(x+\tau/2,\alpha,\mu; \mathfrak{q})=0,
\end{equation}
with Floquet exponent $\nu =2\alpha-1$, as can be seen by their quasi-periodicity along the A-cycle:
\begin{equation}
\label{eqn:A-n}
    \psi_{\epsilon}^{(n)}(z+1,\alpha,\mu;\mathfrak{q})=e^{2\pi i \epsilon(\alpha-1/2)}\psi_{\epsilon}^{(n)}(z,\alpha,\mu;\mathfrak{q}).
\end{equation}
In terms of $\nu$, the $\mathfrak{q}$-expansion of the eigenvalue (\ref{eq: Ens}) takes a particularly simple form:
\begin{equation}
\label{eq: expansion ns lame}
E/\pi^{2} = \nu^2 -\frac{1}{3}\mu(\mu-1) + \frac{8\mu(\mu-1)(\nu^2-1+\mu(\mu-1))}{\nu^2-1}\mathfrak{q}+\mathcal{O}(\mathfrak{q}^{2}),
\end{equation}
which can easily be verified by standard methods, see appendix \ref{app: checks 1}. Concerning the B-cycle monodromy \eqref{eq: Mb necklace}, in the semi-classical limit we have:
\begin{equation*}
\Phi_{\epsilon'}(z,a-\epsilon b/2,m; \mathfrak{q})\simeq e^{\frac{1}{b^{2}}f( \alpha-\epsilon b^{2}/2,\mu; \mathfrak{q})}\psi_{\epsilon'}(z, \alpha-\epsilon b^{2}/2,\mu; \mathfrak{q}),
\end{equation*}
so that, by expanding the semi-classical 1-point block at leading order in $b^{2}$, we find:
\begin{equation}
\label{eqn:B-n}
    \psi_{\epsilon}^{(n)}(z+\tau,\alpha,\mu;\mathfrak{q})=\sum_{\epsilon'=\pm}M^{(n)}_{B,\,\epsilon \epsilon'}\psi_{\epsilon'}^{(n)}(z,\alpha,\mu;\mathfrak{q}),
\end{equation}
with the B-cycle monodromy matrix $M_{B}^{(n)}$ given by:
\begin{equation}
\label{eq: B-cycle mm}
M_{B}^{(n)}=
\begin{pmatrix}
-e^{-\frac{1}{2}\frac{\partial f}{\partial \alpha}}(i+\cot2\pi\alpha)\sin\pi\mu & e^{-\frac{1}{2}\frac{\partial f}{\partial \alpha}}\frac{\cos4\pi\alpha-\cos2\pi\mu}{\cos4\pi\alpha-1}\frac{\Gamma(2-2\alpha-\mu)\Gamma(1-2\alpha+\mu)}{\Gamma(2-2\alpha)\Gamma(1-2\alpha)}\\
e^{\frac{1}{2}\frac{\partial f}{\partial \alpha}}\frac{\cos4\pi\alpha-\cos2\pi\mu}{\cos4\pi\alpha-1}\frac{\Gamma(2-2\alpha-\mu)\Gamma(2\alpha+\mu-1)}{\Gamma(2\alpha)\Gamma(2\alpha-1)}\,\, &\,\, e^{\frac{1}{2}\frac{\partial f}{\partial \alpha}}(-i+\cot2\pi\alpha)\sin\pi\mu 
\end{pmatrix}.
\end{equation}
Meanwhile, the OPE channel blocks (\ref{eq: ope blocks}) descend to a basis of Frobenius solutions near the point $z=0$. This too can be seen by their monodromy around these points:
\begin{equation}
    \psi_{\epsilon}^{(o)}(e^{2\pi i}z,\alpha,\mu;\mathfrak{q})=e^{2\pi i \epsilon\mu}\,\psi_{\epsilon}^{(o)}(z,\alpha,\mu;\mathfrak{q}).
\end{equation}
All other connection matrices can be obtained in a similar way\footnote{The connection formulas for the Lamé equation can be obtained also via the probabilistic construction of conformal blocks \cite{connections}.}. As a quick check of the consistency of our results one can compute the combination $M_{A}M_{B}M_{A}^{-1}M_{B}^{-1}$, which results in the same conjugacy class of $M_{0}$, as expected. Moreover, the commutator $[M_{A},M_{B}]$ is zero if and only if $\mu \in \mathbb{Z}$, meaning that this is the only case in which the A-cycle and B-cycle monodromy matrices can be simultaneously diagonalized\footnote{Monodromy matrices are defined up to conjugation, while the commutator is invariant.}. In other words, we rediscover that the Lamé equation admits elliptic solutions only for $\mu \in \mathbb{Z}$, which go under the name of Lamé polynomials \cite{Wang:1989}. By a further limit, it is known that the Lamé equation degenerates into the Mathieu one. Specifically, using the representation (\ref{eq: wp q-exp}) of the Weierstrass $\wp$ function in equation (\ref{eq: hill}) and considering the limit $\mathfrak{q}\to 0$, $\mu\to \infty$ with $t= \mathfrak{q}\mu^{4}$ fixed, one finds:
\begin{equation}
\label{eq: mathieu}
    \left(\partial_x^2+\lambda+8\pi^{2}\sqrt{t} \cos2\pi x\right)\psi(x,\alpha;t)=0,
\end{equation}
so that the eigenvalue is obtained from equation (\ref{eq: Ens}) as the limit:
\begin{equation}
    \lambda =  \Big[ E + 2\mu(\mu - 1)\eta_1 \Big]_{q \to 0,\, \mu \to \infty} = -4\pi^2 t \, \partial_t f(\alpha; t),
\end{equation}
and similarly for the eigenfunctions. The function $f(\alpha ;t)$ obtained as the limit of the semi-classical torus 1-point block corresponds to the semi-classical irregular block on the sphere \cite{Gaiotto:2009ma}. In terms of the Floquet exponent $\nu=2\alpha-1$, the first few terms of the small $t$ expansion of the eigenvalue read\footnote{In order to compare with the expansion presented in \cite{NIST:DLMF}, Section \href{https://dlmf.nist.gov/28.15.i}{28.15}, one must identify $t=\frac{1}{16}q^2$.}:
\begin{equation}
    \lambda/\pi^{2}=\nu^{2}+\frac{8t}{(\nu^{2}-1)}+\frac{8(7+5\nu^{2})t^{2}}{(\nu^{2}-1)^{3}(\nu^{2}-4)}+\mathcal{O}(t^{3}),
\end{equation}
which again can be verified via standard methods.
\section{\texorpdfstring{Resummation via $\mathbb{C}^{2}$ blow-up equations}{C2 blow-up equations and resummation}}
\label{sec: blow-up C2}
In this section we investigate the analytic structure of semi-classical conformal blocks as functions of the semi-classical intermediate momentum $\alpha$ or better, the Floquet exponent $\nu=2\alpha-1$. Since in the following we will discuss the $\mathbb{C}^{2}$ and the $\mathbb{C}^{2}/\mathbb{Z}_{2}$ blow-up equations, following the conventions of \cite{Bershtein:2021uts,Bonelli:2025owb}, we briefly review the dictionary of the AGT correspondence \cite{Alday:2009aq}, leaving definitions to Appendix \ref{app: special functions}. The Nekrasov partition function \cite{Nekrasov:2002qd, Nekrasov:2003rj} of the $SU(2)$ gauge theory with $N_f$ fundamentals of masses $\{\mu_{i}\}_{i=1}^{N_f}$ is the product of a semi-classical, a 1-loop and an instanton part:
\begin{equation}
\label{eq: Z fundamentals}
    \mathcal{Z}^{[N_{f}]}(a,\{\mu_{i}\};\epsilon_{1},\epsilon_{2}; t)=\mathcal{Z}^{[N_{f}]}_{cl}(a;\epsilon_{1},\epsilon_{2}; t)\mathcal{Z}^{[N_{f}]}_{1\text{-}loop}(a,\{\mu_{i}\};\epsilon_{1},\epsilon_{2})\mathcal{Z}^{[N_{f}]}_{inst}(a,\{\mu_{i}\};\epsilon_{1},\epsilon_{2}; t),
\end{equation}
which depend on the vev of the adjoint scalar $a$, the two equivariant parameters $\epsilon_{1}$, $\epsilon_{2}$ and the coupling constant $t$. The AGT correspondence relates the $N_f =4$ Nekrasov partition function to the 4-point conformal block on the sphere by:
\begin{equation}
\begin{aligned}
\mathcal{F}(\tilde{a};\alpha_{0},m_0,m_1,\alpha_{1};t)=&\,(1-t)^{-2\frac{m_0(Q-m_1)}{\epsilon_1 \epsilon_2}}t^{-\frac{m_1(Q-m_1)+\alpha_1(Q-\alpha_1)}{\epsilon_1 \epsilon_2}}\\
&\cdot\mathcal{Z}^{[4]}_{cl}(a;\epsilon_{1},\epsilon_{2}; t)\mathcal{Z}^{[4]}_{inst}(a,\{\mu_{i}\};\epsilon_{1},\epsilon_{2}; t),
\end{aligned}
\end{equation}
where $\tilde{a}$, $Q$ are related to the gauge theory parameters by:
\begin{equation}
\label{eq: atilde and Q}
\Tilde{a}=a+Q/2,\quad Q=b+b^{-1}=\epsilon_1 + \epsilon_2,
\end{equation}
while for the remaining ones the dictionary reads:
\begin{equation}
\begin{aligned}
\alpha_{0}&=(Q+\mu_1-\mu_2)/2 ,\quad m_0 =(Q+\mu_1+\mu_2 )/2,\\
\alpha_{1}&=(Q-\mu_3 +\mu_4)/2 ,\quad m_1 =(Q-\mu_3 -\mu_4)/2.
\end{aligned}
\end{equation}
The partition function can be equivalently written as:
\begin{equation}
\label{eq: Z with F}
    \mathcal{Z}^{[N_{f}]}(a,\{\mu_{i}\};\epsilon_{1},\epsilon_{2}; t)=\exp\bigg( F^{[N_{f}]}(a,\{\mu_{i}\};\epsilon_{1},\epsilon_{2}; t)\bigg),
\end{equation}
where the prepotential:
\begin{equation}
    F^{[N_{f}]}(a,\{\mu_{i}\};\epsilon_{1},\epsilon_{2}; t)=F^{[N_{f}]}_{cl}(a;\epsilon_{1},\epsilon_{2}; t)+F^{[N_{f}]}_{1\text{-}loop}(a,\{\mu_{i}\};\epsilon_{1},\epsilon_{2})+F^{[N_{f}]}_{inst}(a,\{\mu_{i}\};\epsilon_{1},\epsilon_{2}; t),
\end{equation}
admits an expansion in powers of $\epsilon_{1}$ and $\epsilon_{2}$. In particular, writing:
\begin{equation}
    F^{[N_{f}]}(a,\{\mu_{i}\};\epsilon_{1},\epsilon_{2}; t)\simeq\sum_{n=0}^{\infty}\mathcal{W}^{[N_{f}]}_{n}(a,\{\mu_{i}\},\epsilon_{1}; t)\epsilon_{2}^{n-1},
\end{equation}
and denoting the semi-classical 4-point block on the sphere by $f^{[4]}( \nu, \{\mu_{i}\};t)$, the latter can be expressed in terms of the NS prepotential \cite{Nekrasov:2009rc} $\mathcal{W}^{[4]}_{0}(a,\{\mu_{i}\};\epsilon_{1}; t)$ as:
\begin{equation}
    \epsilon_1 f^{[4]}\left(\frac{\nu}{\epsilon_1}, \left\{\frac{\mu_{i}}{\epsilon_1}\right\}; t\right)=-\frac{\beta_1}{2\epsilon_1}\log (1-t)-\frac{\beta_2}{2\epsilon_1}\log t+\mathcal{W}^{[4]}_{0,\,cl}\left(\frac{\nu}{2},\epsilon_{1}; t\right)+\mathcal{W}^{[4]}_{0,\,inst}\left(\frac{\nu}{2},\{\mu_{i}\},\epsilon_{1}; t\right),
\end{equation}
where $\beta_1=(\epsilon_1+\mu_1+\mu_2)(\epsilon_1+\mu_3+\mu_4)$, $\beta_2=\epsilon_1^{2}-\mu_3^{2}-\mu_4^{2}$, and $\nu=2a$. The remaining equivariant parameter $\epsilon_{1}$ is then identified with the reduced Planck constant $\epsilon_{1}=\hbar$ of the relevant quantum mechanical problem. Then, from the $N_f=4$ partition function we can obtain the $N_f<4$ ones by decoupling the appropriate number of hypermultiplets. This is achieved by sending their masses to infinity and the coupling constant $t$ to zero, while keeping their product fixed:
\begin{equation}
    \mathcal{Z}^{[N_f < 4]}(a,\{\mu_{i}\};\epsilon_{1},\epsilon_{2}; t)=\lim_{\mu_{N_f+1}\to \infty}\cdots\lim_{\mu_{4}\to \infty}\mathcal{Z}^{[4]}\left(a,\{\mu_{i}\};\epsilon_{1},\epsilon_{2}; \frac{t}{\prod_{i=N_f+1}^{4}\mu_{i}}\right).
\end{equation}
At the level of the semi-classical 4-point conformal block $f^{[4]}( \nu, \{\mu_{i}\};t)$, these decoupling limits result in the irregular semi-classical blocks $f^{[N_f<4]}( \nu, \{\mu_{i}\};t)$ \cite{Gaiotto:2009ma}. Moving to the torus, the Nekrasov partition function $\mathcal{Z}(a,m;\epsilon_{1},\epsilon_{2};\mathfrak{q})$ of the $\mathcal{N}=2^{*}$ $SU(2)$ gauge theory depends instead on the mass of the adjoint hypermultiplet $m$ and the coupling constant $\mathfrak{q}=e^{2\pi i \tau}$. Via the AGT correspondence, the 1-point torus conformal block is identified with the Nekrasov instanton partition function as:
\begin{equation}
\label{eq: block = inst}
    \mathcal{F}(m, \Tilde{a}; \mathfrak{q})=\mathcal{Z}_{cl}(a;\epsilon_{1},\epsilon_{2};\mathfrak{q})\mathcal{Z}_{inst}(a,m;\epsilon_1,\epsilon_2;\mathfrak{q}),
\end{equation}
where $\tilde{a}$ and $Q$ are as in (\ref{eq: atilde and Q}). Thus, the NS prepotential $\mathcal{W}_{0}(a,m;\epsilon_1;\mathfrak{q})$ is related to the semi-classical conformal block $f(\nu,\mu;\mathfrak{q})$ by:
\begin{equation}
\label{eq: F0 = f}
    \epsilon
    _{1}f\left(\frac{\nu}{\epsilon_{1}},\frac{\mu}{\epsilon_{1}};\mathfrak{q}\right)=\mathcal{W}_{0,\,cl}\left(\frac{\nu}{2},\epsilon_{1};\mathfrak{q}\right)+\mathcal{W}_{0,\, inst}\left(\frac{\nu}{2},\mu,\epsilon_{1};\mathfrak{q}\right).
\end{equation}
In the limit $m \to \infty$, $\mathfrak{q}\to 0$ with $t=m^{4}\mathfrak{q}$ fixed, the $\mathcal{N}=2^{*}$ partition function $\mathcal{Z}(a,m;\epsilon_{1},\epsilon_{2};\mathfrak{q})$ reduces to the pure gauge theory one, $\mathcal{Z}^{[0]}(a;\epsilon_{1},\epsilon_{2};t)$, and similarly for the prepotential and the semi-classical block. Leveraging the identifications due to the AGT correspondence, in the following we will denote by $f_{inst}^{[N_f]}$ and $f_{inst}$ the $instanton$ part of the semi-classical conformal blocks.

\subsection{\texorpdfstring{NS limit: $N_f\leq4$ and $\mathcal{N}=2^{*}$ theories}{C2 blow-up equations}}
The blow-up equations are a set of extremely rigid constraints satisfied by Nekrasov partition functions \cite{nakajima2005instanton, Jeong:2020uxz}, and thus conformal blocks \cite{bershtein2013coupling}. We consider the vanishing $\mathbb{C}^{2}$ blow-up equations, which, for the partition functions of $SU(2)$ gauge theories with $N_f \leq 4$ fundamental hypermultiplets, take the form:
\begin{equation}
\label{eq: C2 blow-up 1 Nf}
\sum_{n\in \mathbb{Z}+\frac{1}{2}}\mathcal{Z}^{[N_{f}]}(a+n\epsilon_{1},\{\tilde{\mu}_{i}\};\epsilon_{1},\epsilon_{2}-\epsilon_{1}; t)\mathcal{Z}^{[N_{f}]}(a+n\epsilon_{2},\{\tilde{\mu}_{i}\};\epsilon_{2},\epsilon_{1}-\epsilon_{2}; t)=0,
\end{equation}
where $\tilde{\mu}_{1,2}=\mu_{1,2}-(\epsilon_1+\epsilon_2)/2$ and $\tilde{\mu}_{3,4}=-\mu_{3,4}+(\epsilon_1+\epsilon_2)/2$, while for the $\mathcal{N}=2^{*}$ $SU(2)$ gauge theory, we consider \cite{Bershtein:2021uts}:
\begin{equation}
\label{eq: C2 blow-up 1 *}
\begin{aligned}
& \theta_{2}(0|2\tau)\sum_{n\in \mathbb{Z}}\mathcal{Z}(a+n\epsilon_{1},m;\epsilon_1,\epsilon_2-\epsilon_1;\mathfrak{q})\mathcal{Z}(a+2n\epsilon_{2},m;\epsilon_2,\epsilon_1-\epsilon_2;\mathfrak{q})\\
&-\theta_{3}(0|2\tau)\sum_{n\in\mathbb{Z}+\frac{1}{2}}\mathcal{Z}(a+n\epsilon_{1},m;\epsilon_1,\epsilon_2-\epsilon_1;\mathfrak{q})\mathcal{Z}(a+n\epsilon_{2},m;\epsilon_2,\epsilon_1-\epsilon_2;\mathfrak{q})=0.
\end{aligned}
\end{equation}
In particular, in the pure gauge theory limit $\mathfrak{q} \to 0$, $m \to \infty$, with $t = \mathfrak{q} m^4$ held fixed, equation~(\ref{eq: C2 blow-up 1 *}) reduces to equation~\eqref{eq: C2 blow-up 1 Nf} for $N_f = 0$. To obtain relations involving the semi-classical conformal blocks, we consider the $\epsilon_1 - \epsilon_2 \to 0$ limit of the previous blow-up equations, starting with \eqref{eq: C2 blow-up 1 Nf}. Expressing the partition function in terms of the prepotential, as in equation~\eqref{eq: Z with F}, we obtain:
\begin{equation}
    \sum_{n\in \mathbb{Z}+\frac{1}{2}}\exp\left(F^{[N_{f}]}(a+n\epsilon_{1},\{\tilde{\mu}_{i}\};\epsilon_{1},\epsilon_{2}-\epsilon_{1}; t)+F^{[N_{f}]}(a+n\epsilon_{2},\{\tilde{\mu}_{i}\};\epsilon_{2},\epsilon_{1}-\epsilon_{2}; t)\right)=0.
\end{equation}
Then, expanding the prepotential as:
\begin{equation}
F^{[N_{f}]}(a,\{\mu_i\};\epsilon_{1},\epsilon_{2}; t)=\frac{1}{\epsilon_{2}}\mathcal{W}^{[N_{f}]}_{0}(a,\{\mu_i\},\epsilon_{1}; t)+\mathcal{W}^{[N_{f}]}_{1}(a,\{\mu_i\},\epsilon_{1}; t)+ \mathcal{O}(\epsilon_{2}),
\end{equation}
in the limit $\epsilon_1 - \epsilon_2 \to 0$, we obtain:
\begin{equation*}
\begin{aligned}
& F^{[N_{f}]}(a+n\epsilon_{1},\{\tilde{\mu}_{i}\};\epsilon_{1},\epsilon_{2}-\epsilon_{1}; t)+F^{[N_{f}]}(a+n\epsilon_{2},\{\tilde{\mu}_{i}\};\epsilon_{2},\epsilon_{1}-\epsilon_{2}; t)\\[4pt]
\simeq& \frac{1}{\epsilon_{2}-\epsilon_{1}}\mathcal{W}^{[N_{f}]}_{0}(a+n\epsilon_{1},\{\tilde{\mu}_i\},\epsilon_{1}; t)+\mathcal{W}^{[N_{f}]}_{1}(a+n\epsilon_{1},\{\tilde{\mu}_i\},\epsilon_{1}; t)+\epsilon_{1}\leftrightarrow\epsilon_{2}\\[4pt]
=&2\mathcal{W}^{[N_{f}]}_{1}(a+n\hbar,\{\tilde{\mu}_i\},\hbar; t)-n\partial_{a}\mathcal{W}^{[N_{f}]}_{0}(a+n\hbar,\{\tilde{\mu}_i\},\hbar; t)-\partial_{\hbar}\mathcal{W}^{[N_{f}]}_{0}(a+n\hbar,\{\tilde{\mu}_i\},\hbar; t),
\end{aligned}
\end{equation*}
where we set $\epsilon_{1}=\epsilon_{2}=\hbar$. Thus, in this limit, equation \eqref{eq: C2 blow-up 1 Nf} becomes:
\begin{equation}
\label{eq: C2 blow-up 1 pure ns}
    \sum_{n \in \mathbb{Z}+\frac{1}{2}}e^{ 2\mathcal{W}_{1}^{[N_{f}]}(a+n\hbar,\{\tilde{\mu}_i\},\hbar; t)-n\partial_{a}\mathcal{W}_{0}^{[N_{f}]}(a+n\hbar,\{\tilde{\mu}_i\},\hbar; t)-\partial_{\hbar}\mathcal{W}_{0}^{[N_{f}]}(a+n\hbar,\{\tilde{\mu}_i\},\hbar; t)}=0,
\end{equation}
where the Coulomb branch parameter $a$ and the masses $\mu_i$ are shifted after taking the $\hbar$-derivative. In particular, after taking the limit, the shifted masses read $\tilde{\mu}_{1,2} = \mu_{1,2} - \hbar$ and $\tilde{\mu}_{3,4} = -\mu_{3,4} + \hbar$. Similarly, for the $\mathcal{N}=2^*$ gauge theory, the NS limit of the blow-up equation~(\ref{eq: C2 blow-up 1 *}) takes the form:
\begin{equation}
\label{eq: C2 blow-up 1 NS lame 1}
\begin{aligned}
& \theta_{2}(0|2\tau)\sum_{n \in \mathbb{Z}}e^{ 2\mathcal{W}_{1}(a+n\hbar,m,\hbar; \mathfrak{q})-n\partial_{a}\mathcal{W}_{0}(a+n\hbar,m,\hbar; \mathfrak{q})-\partial_{\hbar}\mathcal{W}_{0}(a+n\hbar,m,\hbar; \mathfrak{q})}\\
&-\theta_{3}(0|2\tau)\sum_{n \in \mathbb{Z}+\frac{1}{2}}e^{ 2\mathcal{W}_{1}(a+n\hbar,m,\hbar; \mathfrak{q})-n\partial_{a}\mathcal{W}_{0}(a+n\hbar,m,\hbar; \mathfrak{q})-\partial_{\hbar}\mathcal{W}_{0}(a+n\hbar,m,\hbar; \mathfrak{q})}=0.
\end{aligned}
\end{equation}


\subsection{\texorpdfstring{Solving the blow-up equations: $N_f\leq 4$ theories}{Solving the blow-up equations 1}}
Let us begin by considering equation (\ref{eq: C2 blow-up 1 pure ns}). To make it more explicit, we split the two prepotentials into classical, 1-loop and instanton parts, using the definitions \eqref{eq: classical part Nf} and \eqref{eq: 1-loop part Nf} . Then, dividing by a common factor of $t^{\frac{a^2}{\hbar ^2}-\frac{3}{4}}$, we find:
\begin{equation}
\label{eq: C2 blow-up 1 explicit}
\sum_{n\in \mathbb{Z}+\frac{1}{2}}t^{n^{2}} e^{ 2\mathcal{W}^{[N_f]}_{1,\,1\text{-}loop} -\left( \partial_{\hbar}+n \partial_{a}\right) \mathcal{W}^{[N_f]}_{0,\,1\text{-}loop} +2\mathcal{W}_{1,\, inst} - \left(\partial_{\hbar}+n \partial_{a}\right) \mathcal{W}^{[N_f]}_{0,\, inst}}=0,
\end{equation}
where $\mathcal{W}^{[N_f]}_{j,\,1\text{-}loop}=\mathcal{W}^{[N_f]}_{j,\,1\text{-}loop}\left(a + n\hbar,\{\tilde{\mu}_{i}\}, \hbar\right)$ and $\mathcal{W}^{[N_f]}_{j,\, inst}=\mathcal{W}^{[N_f]}_{j,\, inst}\left(a + n\hbar,\{\tilde{\mu}_{i}\}, \hbar ; t\right)$. Normalizing by the 1-loop term for $n=0$, what remains are just simple rational functions of $a$, $\{\mu_{i}\}_{i=1}^{N_f}$ and $\hbar$, with poles for $a \in \frac{\hbar}{2} \mathbb{Z}$. Indeed, with this normalization and setting $\hbar=1$, equation (\ref{eq: C2 blow-up 1 explicit}) reads:
\begin{equation}
\label{eq: C2 blow-up 1 explicit 2}
    \sum_{n\in \mathbb{Z}+\frac{1}{2}}t^{n^{2}}\mathcal{G}^{[N_f]}_{1\text{-}loop}\big(a,\{\mu_{i}\},n\big)\,e^{ 2\mathcal{W}^{[N_f]}_{1,\,inst}- \left( \partial_{\hbar}+n \partial_{a}\right) \mathcal{W}^{[N_f]}_{0,\, inst}  }=0,
\end{equation}
where $\mathcal{G}_{1\text{-}loop}^{[N_f]}(a,\{\mu_{i}\},n)$ can be computed as the $\epsilon_{1}=\epsilon_{2}=1$ limit of the $l$-factors $L^{(n,-n),1}$ in Appendix B of \cite{Jeong:2020uxz}. Namely, defining the functions:
\begin{subequations}
\begin{align}
g_{1\text{-}loop}^{hyp}(a, \mu, n) &= \prod _{j=0}^{n-\frac{1}{2}} (-a-j+\mu +1)^j (a+j+\mu +1)^j, \quad n\geq \frac{1}{2},\\
g_{1\text{-}loop}^{vec}(a, n) &=
\begin{cases}
\prod _{j=1}^{2 n} (-2 a-j+1)^j (2 a+j)^{j-1}, & \text{if } n \geq \frac{1}{2},\\[4pt]
 1, & \text{if } n =0,
\end{cases}\label{eq: gvec}
\end{align}
\end{subequations}
the 1-loop factor can be written as:
\begin{equation}
\label{eq: C2 G1L general}
\mathcal{G}^{[N_f]}_{1\text{-}loop}(a,\{\mu_{i}\},n)=
\begin{cases}
\frac{\prod_{i=1}^{N_{f}}g_{1\text{-}loop}^{hyp}(a, \mu_{i}, n)}{g_{1\text{-}loop}^{vec}(a, n)}, & \text{if } n \geq \frac{1}{2},\\[4pt]
 \frac{\prod_{i=1}^{N_{f}}g_{1\text{-}loop}^{hyp}(-a, \mu_{i}, -n)}{g_{1\text{-}loop}^{vec}(-a, -n)}, & \text{if } n \leq -\frac{1}{2}.
\end{cases}
\end{equation}
Generalizing the considerations of \cite{Beccaria:2016wop,Gorsky:2017ndg}, to solve equation (\ref{eq: C2 blow-up 1 explicit 2}) we make the following ansatz:
\begin{subequations}
\begin{align}
\mathcal{W}_{0,\,inst}^{[N_{f}]}(a,\{\mu_{i}\},\hbar;t) 
&= R_{0}^{[N_{f}]}(a,\{\mu_{i}\},\hbar;t) \nonumber\\
&\quad + \hbar\sum_{k,j=1}^{\infty}\left[\sum_{\pm}
    g^{[N_f]}_{k,j}\left(\frac{\left(t\hbar^{N_f -4}\right)^{j/2}}{j\pm2a/\hbar},\left\{\frac{\mu_{i}}{\hbar}\right\}\right)\right]\left(t\hbar^{N_f -4}\right)^{k+j/2-1}, \label{eq: resumm ansatz F0} \\
\mathcal{W}_{1,\,inst}^{\,[N_{f}]}(a,\{\mu_{i}\},\hbar;t) 
&= R_{1}^{[N_{f}]}(\{\mu_{i}\},\hbar;t) \nonumber\\
&\quad + \sum_{k,j=1}^{\infty}\left[\sum_{\pm}
\tilde{g}^{[N_f]}_{k,j}\left(\frac{\left(t\hbar^{N_f -4}\right)^{j/2}}{j\pm2a/\hbar},\left\{\frac{\mu_{i}}{\hbar}\right\}\right)\right]\left(t\hbar^{N_f -4}\right)^{k+j/2-1} \nonumber\\
&\quad + \sum_{k,j=1}^{\infty}\left[\sum_{\pm}
\tilde{f}^{[N_f]}_{k,j}\left(\frac{\left(t\hbar^{N_f -4}\right)^{j/2}}{j\pm2a/\hbar},\left\{\frac{\mu_{i}}{\hbar}\right\}\right)\right]\left(t\hbar^{N_f -4}\right)^{k-1}, \label{eq: resumm ansatz F1}
\end{align}
\end{subequations}
where the $resummation$ $functions$ $g^{[N_f]}_{k,j}(x,\{\mu_i\})$, $\tilde{g}^{[N_f]}_{k,j}(x,\{\mu_i\})$ and $\tilde{f}^{[N_f]}_{k,j}(x,\{\mu_i\})$ must be analytic in a neighborhood of $x=0$, where they vanish. Moreover, in order for the ansatz to admit a power series expansion in integer powers of $t$, the functions must have definite parity in their first argument, namely, the $g^{[N_f]}_{k,j}$ and $\tilde{g}^{[N_f]}_{k,j}$ are assumed to be odd, while the functions $\tilde{f}_{k,j}$ are assumed to be even. The functions $R_i^{[N_f]}$ are also vanishing at $t=0$ and take into account the regular part of the instanton expansion. They can be computed explicitly from $R_{0}^{[4]}$ and $R_{1}^{[4]}$ in equations (\ref{eq: reg0}) and (\ref{eq: reg1}) by taking appropriate decoupling limits. To obtain equations for the resummation functions we proceed in the following way. The blow-up equation (\ref{eq: C2 blow-up 1 explicit 2}) holds for any value of the parameter $a$, allowing us to set:
\begin{equation}
\label{eq: a pole}
    a = \frac{\hbar}{2}\left(m_{1}+\frac{1}{x}t^{\frac{m_{2}}{2}} \right),\quad m_{1}\in \mathbb{Z},\quad m_{2}\in \mathbb{N},
\end{equation}
with $x$ a complex variable, and expand the resulting expression in $t$. Due to the symmetry of the equation for $a \to -a$ (accompanied by $n \to -n$), we may restrict to $m_{1}\geq 0$. This choice allows us to focus on the functions with $j=m_{2}$, as can be seen by noting that, when $j=m_{2}$ and $2n=\mp j-m_{1}$, these functions and their derivatives enter the equations as: 
\begin{equation*}
    g_{k,j}^{[N_f]}\left(\frac{\left(t\hbar^{N_f -4}\right)^{j/2}}{j\pm (2n+m_{1})\pm t^{m_{2}/2}/x},\left\{\frac{\mu_{i}}{\hbar}\right\}\right)=g^{[N_f]}_{k,m_{2}}\left(\pm x\hbar^{m_{2}(N_f-4)/2},\left\{\frac{\mu_{i}}{\hbar}\right\}\right).
\end{equation*}
Meanwhile, when $2n=\mp j-m_{1}$ and $j\neq m_{2}$ we have two possibilities: if $m_{2}<j$ the functions will enter through their expansion around zero, while if $m_{2}>j$ they will enter through their expansion around infinity. Finally, if $j\pm (2n+m_{1})\neq 0$, the functions will enter simply through their expansion around zero. We now begin by deriving the equations satisfied by the resummation functions and show that they can be easily solved. Finally, we discuss the structure of the blow-up equation's expansion, taking into account the behavior of the resummation functions expanded around infinity. 
\subsubsection{Algebraic equations for the resummation functions}
First of all, we consider the simple rational functions $\mathcal{G}^{[N_f]}_{1\text{-}loop}(a,\{\mu_i\},n)$ in equation \eqref{eq: C2 G1L general}. When both $a>0$ and $n>0$, its expansion in $a$ around some fixed positive value will start from a constant term. Then, for any value of $n\in \mathbb{Z}+\frac{1}{2}$, $\mathcal{G}_{1\text{-}loop}(a,n)$ has always a simple pole for $a=0$ and finally, for $n<0$, the function has poles at $a=j/2$, $j\in \{1,...,2|n|-1\}$, of order $2j$ except for $j=2|n|$, for which the order is $2|n|-1$. Setting $2a = m_{1}+t^{m_{2}/2}/x$, expanding in $t$ and combining with the overall power of $t^{n^{2}}$, results in a predictable leading order behavior. In particular, for $2n=\mp m_{2}-m_{1}$ we find:
\begin{equation*}
\begin{aligned}
&t^{(m_{1}+m_{2})^{2}/4}\mathcal{G}^{[N_f]}_{1\text{-}loop}\left(\frac{m_{1}x+t^{m_{2}/2}}{2x},\{\mu_{i}\},-\frac{m_{2}+m_{1}}{2}\right)\sim \mathcal{O}\big(t^{(m_{1}-m_{2})^{2}/4}\big),\\
& t^{(m_{1}-m_{2})^{2}/4}\mathcal{G}^{[N_f]}_{1\text{-}loop}\left(\frac{m_{1}x+t^{m_{2}/2}}{2x},\{\mu_{i}\},\frac{m_{2}-m_{1}}{2}\right)\sim \mathcal{O}\big(t^{(m_{1}-m_{2})^{2}/4}\big),
\end{aligned}
\end{equation*}
while for values of $n$ between $-(m_{2}+m_{1})/2$ and $(m_{2}-m_{1})/2$, the power of $t$ at leading order can be negative. Let us now consider the instanton contributions. To understand the structure of the expansion and the form of the resulting equations, we can examine the $n$-th term of the blow-up equation (\ref{eq: C2 blow-up 1 explicit 2}), where $n$ is such that $j\pm (2n+m_{1})=0$, for some $j \leq m_{2}$. These terms give the most interesting contributions, since for $j<m_{2}$ we will find the non-trivial expansion of the resummation functions around infinity and for $j=m_{2}$ we will find the functions valued at $\pm x$, while for $j>m_{2}$ the functions are expanded around zero. For example, we have:
\begin{equation*}
\begin{aligned}
\mathcal{W}_{1,\, inst}^{\mp,\,[N_f]}&=\mathcal{W}^{[N_f]}_{1,\, inst}\left(\frac{\mp jx+t^{m_{2}/2}}{2x},\{\tilde{\mu}_{i}\}, 1; t\right)\\
&= \sum_{k=1}^{\infty}t^{k-1}\left[\Tilde{f}^{[N_f]}_{k,j}\left(y,\{\tilde{\mu}_{i}\}\right)\pm t^{j/2}
\Tilde{g}^{[N_f]}_{k,j}\left(y,\{\tilde{\mu}_{i}\}\right)\right]+h^{\mp,\,[N_f]}(x,\{\mu_{i}\},t),
\end{aligned}
\end{equation*}
and similarly for $\mathcal{W}^{[N_f]}_{0,\, inst}$, where $y=x t^{(j-m_{2})/2}$, while the functions $h^{\mp,\,[N_f]}$ take into account the remaining part of the expression, which will have an expansion starting from some positive power of $t$. The parity of the resummation functions has been used to simplify the previous formula. Thus, isolating only the relevant terms at the exponent in equation \eqref{eq: C2 blow-up 1 explicit 2}, we find the following expression:
\begin{equation}
\label{eq: C2 Gexp gen}
\begin{aligned}
&2\mathcal{W}^{\mp,\,[N_f]}_{1,\,inst}- \left( \partial_{\hbar}+n \partial_{a}\right) \mathcal{W}^{\mp,\, [N_f]}_{0,\, inst}=\sum_{k\geq 1}t^{k-1}\bigg[2\tilde{f}^{[N_f]}_{k,j}(y,\{\tilde{\mu}_{i}\})\mp m_{1}y^{2} \partial_{y}g^{[N_f]}_{k,j}(y,\{\tilde{\mu}_{i}\})\\
&\pm t^{j/2}\bigg(2\tilde{g}^{[N_f]}_{k,j}(y,\{\tilde{\mu}_{i}\})+\gamma_{k,j}^{[N_f]}g^{[N_f]}_{k,j}(y,\{\tilde{\mu}_{i}\})+  \delta_j^{[N_f]}y\, \partial_{y}g^{[N_f]}_{k,j}(y,\{\tilde{\mu}_{i}\})\\
&+\sum_{i=1}^{N_f}\tilde{\mu}_{i}\partial_{\tilde{\mu}_i}g^{[N_f]}_{k,j}(y,\{\tilde{\mu}_{i}\})\bigg)\bigg] + s^{\mp,\, [N_f]}(x,\{\mu_{i}\},t),
\end{aligned}
\end{equation}
where:
\begin{subequations}
\begin{align}
\gamma_{k,j}^{[N_f]}&=(4-N_f)(k+j/2)+N_f-5,\\
\delta_j^{[N_f]}&=(4-N_f)j/2-1,
\end{align}
\end{subequations}
and the functions $s^{\mp,\,[N_f]}(x,\{\mu_{i}\}, t)$ vanish at $t=0$. By collecting terms of the same order in $t$ from the expansion of the blow-up equation, these expressions, together with the 1-loop term, allow us to derive the form of the equations satisfied by the resummation functions and show that the $t$-expansion around the poles (\ref{eq: a pole}) is well-behaved. Namely, by setting $j = m_2$, assuming $m_1 > 0$ for simplicity\footnote{The equations for $m_{1}=0$ are automatically satisfied once a solution for the $m_1>0$ case is found.}, omitting the $[N_f]$ label from the resummation functions, and performing the change of variables:
\begin{equation}
\label{eq: C2 log branch}
\tilde{f}_{1,m_2}=\frac{1}{2}\log u_{m_2}, \quad\quad\quad
\partial_x g_{1,m_2}=\frac{1}{x^{2}}\log(x\, v_{m_2}) ,
\end{equation}
we obtain at leading order:
\begin{equation}
\label{eq: 1st linear eq}
u_{m_2}\big(v_{m_2}^{m_1}+c_{m_1,m_2} v_{m_2}^{-m_1}\big)+r_{m_1,m_2,1}=0
\end{equation}
where the constant $c_{m_1,m_2}$ can be computed from the 1-loop factor \eqref{eq: C2 G1L general} and reads:
\begin{equation}
    c_{m_1,m_2}(\{\mu_i\})=(-1)^{m_1+1}\frac{\prod_{i=1}^{N_f}\tilde{c}_{m_1,m_2}(\mu_i+1)}{m_2^{2m1}[(m_2-1)!]^{4m_1}},
\end{equation}
with $\tilde{c}_{m_1,m_2}(\mu)$ defined in equation \eqref{eq: c tilde}. We observe here, via the change of variables \eqref{eq: C2 log branch}, the appearance of logarithmic branching, necessary to obtain a linear equation \eqref{eq: 1st linear eq} in the function $u_{m_2}$. Meanwhile, at orders $t^{k-1}$ and $t^{k+j/2-1}$, respectively, compared to the leading order equations, we find:
\begin{equation}
\label{eq: linear equations fk}
2(v_{m_2}^{m_1}+c_{m_1,m_2}v_{m_2}^{-m_1})\tilde{f}_{k,m_2}+m_1x^2(v_{m_2}^{m_1}-c_{m_1,m_2}v_{m_2}^{-m_1})\partial_x g_{k,m_2}+r_{m_1,m_2,k}=0
\end{equation}
\begin{equation}
\label{eq: linear equations gtk}
2\tilde{g}_{k,j}+\gamma_{k,j}^{[N_f]} g_{k,j}+ \delta_{j}^{[N_f]} x\partial_x g_{k,j} +\sum_{i=1}^{N_f}\tilde{\mu}_{i}\partial_{\tilde{\mu}_{i}}g_{k,j}+\tilde{r}_{m_1,m_2,k}=0
\end{equation}
The functions $r_{m_{1},m_{2},k}(x,\{\mu_i\})$ and $\tilde{r}_{m_{1},m_{2},k}(x,\{\mu_i\})$ account for the remaining contributions of the $t$-expansion at each fixed order and can be explicitly computed for any choice of $m_1$ and $m_2$. In particular, they also include contributions from resummation functions that are assumed to have been determined from equations at lower orders in the expansion. For example, in equation \eqref{eq: linear equations gtk}, the terms involving the function $g_{k,j}$ could, in principle, be absorbed into $\tilde{r}_{m_{1},m_{2},k}$. However, we write them explicitly to highlight the simple relations that connect the functions at each step. The three families of equations \eqref{eq: 1st linear eq}, \eqref{eq: linear equations fk} and \eqref{eq: linear equations gtk}, determine the resummation functions up to a branching ambiguity, which can be fixed by imposing the appropriate behavior at zero and at infinity, see Appendix \ref{app: blow-up example 1} for an explicit example. Indeed, equation \eqref{eq: 1st linear eq} determines $u_{m_2}$ as a function of $v_{m_2}$, and by equating two such expressions for different values of $m_1$, one finds:
\begin{equation}
\label{eq: C2 root branch}
    v_{m_2}^{\tilde{m}_1}\,r_{\tilde{m}_1,m_2,1}-v_{m_2}^{m_1}\,r_{m_1,m_2,1}=0\implies \begin{cases}
v_{m2}^{2}=\frac{r_{2,m_2,1}}{r_{4,m_2,1}}, & \text{for } m_2 \text{ odd},\\[4pt]
 v_{m2}^{2}=\frac{r_{1,m_2,1}}{r_{3,m_2,1}}, & \text{for } m_2 \text{ even},
\end{cases}
\end{equation}
where in the last step we set $m_1=2$, $\tilde{m}_1=4$ for odd $m_2$, and $m_1=1$, $\tilde{m}_1=3$ for even $m_2$, respectively. Thus, $v_{m_2}$ is determined by a simple quadratic equation, which gives rise to a square root branching structure in the resummation functions. Then, two copies of equation \eqref{eq: linear equations fk}, evaluated at different values of $m_1$, determine the functions $\tilde{f}_{k,m_2}$ and $g_{k,m_2}$, with the integration constant of the latter fixed by requiring it to vanish at zero. Finally, equation \eqref{eq: linear equations gtk} determines $\tilde{g}_{k,m_2}$ in terms of the previously determined resummation functions. Thus, we have shown that expanding the blow-up equation \eqref{eq: C2 blow-up 1 explicit 2} for two distinct values of $m_1$ is sufficient to determine all the resummation functions. For example, the first few functions in the $N_f =0$ case are given by:
\begin{center}
\begin{tabular}{c c}
\vspace{1mm}
$g_{1,1}^{[0]}(x) = -\dfrac{1 - \sqrt{1 + 4x^2} + \log\left( \sqrt{\tfrac{1}{4} + x^2} + \tfrac{1}{2} \right)}{x},$
\vspace{1mm}
&
\vspace{1mm}
$g^{[0]}_{2,1}(x) = \dfrac{(2 - x^2)\sqrt{1 + 4x^2} - 3x^2 - 2}{12x^3},$
\vspace{1mm}
\\
\vspace{1mm}
$g^{[0]}_{1,2}(x) = \dfrac{\sqrt{1 + x^2} - 1 - \log\left( \tfrac{1}{2} \sqrt{1 + x^2} + \tfrac{1}{2} \right)}{x},$
