\section{Special Functions}
\label{app: special functions}
\subsection{Classical special functions}
In this sub-appendix, we summarize the conventions used for the various special functions appearing throughout the main text. The Weierstrass $\wp$-function, defined by:
\begin{equation}
\wp(z;2\omega_1,2\omega_2)=\frac{1}{z^{2}}+\sum_{(m,n)\neq (0,0)}\left(\frac{1}{(z-2m\omega_1-2n \omega_2)^{2}}-\frac{1}{(2m\omega_1+2n \omega_2)^{2}}\right),
\end{equation}
admits the following alternative representations:
\begin{subequations}
\begin{align}
&\wp(z)=\frac{\pi^{2}}{\sin^{2}\pi z}-\frac{\pi^{2}}{3}+\pi^{2}\sum_{n\neq 0}\left(\frac{1}{\sin^{2}\pi(z-n\tau)}-\frac{1}{\sin^{2}\pi n\tau} \right),\\
&\wp(z)=\frac{\pi^{2}/\tau^{2}}{\sin^{2}\frac{\pi z}{\tau}}-\frac{\pi^{2}}{3\tau^{2}}+\frac{\pi^{2}}{\tau^{2}}\sum_{m\neq 0}\left(\frac{1}{\sin^{2}\frac{\pi(z-m)}{\tau}}-\frac{1}{\sin^{2}\frac{\pi m}{\tau}} \right),
\end{align}
\end{subequations}
where $\wp(z)$ always denotes $\wp(z;1,\tau)$, $\tau=\omega_2/\omega_1$. In particular, in the limit $\tau\to +i \infty$, we find:
\begin{equation}
\label{eq: wp q-exp}
    \wp(z)=\frac{\pi^{2}}{\sin^{2}\pi z}-\frac{\pi^{2}}{3}+16\pi^{2}\mathfrak{q}\sin^{2}\pi z+\mathcal{O}\left(\mathfrak{q}^{2}\right),
\end{equation}
where $\mathfrak{q}=e^{2\pi i \tau}$. Moreover, the values of the $\wp$-function at the half-periods are denoted respectively by: $e_1=\wp(\omega_1;2\omega_1,2\omega_2)$, $e_2=\wp(\omega_2;2\omega_1,2\omega_2)$  and $e_3=\wp(\omega_1+\omega_2;2\omega_1,2\omega_2)$. The Weierstrass $\zeta$-function, defined as:
\begin{equation}
    \zeta(z; 2\omega_1, 2\omega_2)=\frac{1}{z}+\sum_{(m,n)\neq (0,0)}\left(\frac{1}{z-2m\omega_1-2n\omega_2}+\frac{1}{2m\omega_1+2n\omega_2}+\frac{z}{(2m\omega_1+2n\omega_2)^2} \right),
\end{equation}
is related to the Weierstrass $\wp$-function by:
\begin{equation}
    \wp(z;2\omega_1,2\omega_2)=-\zeta'(z;2\omega_1,2\omega_2),
\end{equation}
and, once again, $\zeta(z)$ always denotes $\zeta(z;1,\tau)$. For the Jacobi theta functions, we use the following conventions:
\begin{subequations}
\begin{align}
&\theta_{1}(z|\tau)=-i\sum_{n\in \mathbb{Z}}(-1)^{n}e^{i\pi\tau\left(n+\frac{1}{2}\right)^{2}}e^{2\pi i z\left(n+\frac{1}{2}\right)},\\
&\theta_{2}(z|\tau)=\sum_{n\in \mathbb{Z}}e^{i\pi\tau\left(n+\frac{1}{2}\right)^{2}}e^{2\pi i z\left(n+\frac{1}{2}\right)},\\
&\theta_{3}(z|\tau)=\sum_{n\in \mathbb{Z}}e^{i\pi\tau n^{2}}e^{2\pi i zn},\\
&\theta_{4}(z|\tau)=\sum_{n\in \mathbb{Z}}(-1)^{n}e^{i\pi\tau n^{2}}e^{2\pi i zn}.
\end{align}
\end{subequations}
The Euler $\varphi$-function is defined by:
\begin{equation}
\varphi(\mathfrak{q})=\prod_{n\geq 1}(1-\mathfrak{q}^n),
\end{equation}
while the Dedekind $\eta$-function as:
\begin{equation}
\eta(\tau)=\mathfrak{q}^{1/24}\varphi(\mathfrak{q}).
\end{equation}
In terms of Jacobi theta functions, the Weierstrass elliptic functions can be represented as follows:
\begin{subequations}
\begin{align}
&\wp(z)=-\partial_{z}^{2}\log\theta_1(z|\tau)-2\eta_1(\tau),\\[1ex]
&\zeta(z)=\partial_{z}\log\theta_1(z|\tau)+2z\eta_1(\tau),
\end{align}
\end{subequations}
where
\begin{equation}
    \eta_{1}(\tau)=-2\pi i \partial_{\tau}\log\eta(\tau)=4\pi^2 \left(\frac{1}{24}-\sum_{n=1}^{\infty}\frac{n\mathfrak{q}^{n}}{1-\mathfrak{q}^{n}}\right).
\end{equation}
Moreover, we have the relation:
\begin{equation}
    E_{2}(\tau)=\frac{6}{\pi^2}\eta_{1}(\tau).
\end{equation}
Finally, the Jacobi elliptic sine function is given by:
\begin{equation}
    \sn(z;\kappa^{2})=\frac{\theta_{3}(0|\tau)\theta_{1}(u(z)|\tau)}{\theta_{2}(0|\tau)\theta_{4}(u(z)|\tau)},\quad u(z)=\frac{\ z}{2K(\kappa^{2})},
\end{equation}
where
\begin{equation}
K(\kappa^{2})=\int_{0}^{1}\frac{dt}{\sqrt{(1-t^{2})(1-\kappa^{2}t^{2})}},
\end{equation}
is the complete elliptic integral of the first kind. The function $\sn(z;\kappa^2)$ is an odd, doubly periodic function of periods $4K(\kappa^2)$ and $2iK(1-\kappa^2)$, related to the Weierstrass $\wp$-function by:
\begin{equation}
    \wp(z)=e_{3}+\frac{e_{1}-e_{3}}{\sn^{2}(z\sqrt{e_{1}-e_{3}};\kappa^2)},
\end{equation}
with the following formulas relating modular parameters:
\begin{subequations}
\begin{align}
&\kappa^2=\frac{e_{2}-e_{3}}{e_{1}-e_{3}}=\frac{\theta_{2}(0|\tau)^{4}}{\theta_{3}(0|\tau)^{4}},\\[1ex]
&\tau = i\,\frac{K(1-\kappa^{2})}{K(\kappa^{2})}.
\end{align}
\end{subequations}
\subsection{Nekrasov partition functions, conformal blocks \& AGT dictionary}
Starting from the Nekrasov partition function of the $SU(2)$ gauge theory with $N_f$ fundamental hypermultiplets, we adopt the conventions of \cite{Bonelli:2025owb} and write:
\begin{equation}
    \mathcal{Z}^{[N_{f}]}(a,\{\mu_{i}\};\epsilon_{1},\epsilon_{2}; t)=\mathcal{Z}^{[N_{f}]}_{cl}(a;\epsilon_{1},\epsilon_{2}; t)\mathcal{Z}^{[N_{f}]}_{1\text{-}loop}(a,\{\mu_{i}\};\epsilon_{1},\epsilon_{2})\mathcal{Z}^{[N_{f}]}_{inst}(a,\{\mu_{i}\};\epsilon_{1},\epsilon_{2}; t),
\end{equation}
where:
\begin{subequations}
\begin{align}
&\mathcal{Z}^{[N_{f}]}_{cl}(a;\epsilon_{1},\epsilon_{2}; t)=t^{\frac{(\epsilon_1+\epsilon_2)^2/4-a^2}{\epsilon_1 \epsilon_2}},\label{eq: classical part Nf}\\[1ex]
&\mathcal{Z}^{[N_{f}]}_{1\text{-}loop}(a,\{\mu_{i}\};\epsilon_{1},\epsilon_{2})=\prod_{\pm}\frac{\prod_{i=1}^{N_f}\exp\left(\gamma_{\epsilon_1,\epsilon_2}(\mu_i\pm a-(\epsilon_1+\epsilon_2)/2) \right)}{\exp(\gamma_{\epsilon_1,\epsilon_2}(\pm2 a)) },\label{eq: 1-loop part Nf}\\[1ex]
&\mathcal{Z}^{[N_{f}]}_{inst}(a,\{\mu_{i}\};\epsilon_{1},\epsilon_{2}; t)=\sum_{\boldsymbol{Y}=(Y_+,Y_-)}\frac{\prod_{i=1}^{N_f}z_{fund}(a,\mu_i,\boldsymbol{Y})}{z_{vec}(a,\boldsymbol{Y})}t^{|\boldsymbol{Y}|},
\end{align}
\end{subequations}
and $\boldsymbol{Y}=(Y_+,Y_-)$ denotes a couple of Young tableaux, $|\boldsymbol{Y}|$ being the total number of boxes of the pair. The double gamma function $\gamma_{\epsilon_1,\epsilon_2}$ is defined as:
\begin{equation}
    \gamma_{\epsilon_1,\epsilon_2}(x)=\frac{d}{ds}\frac{1}{\Gamma(s)}\int_{0}^{\infty}\frac{dz}{z}z^{s} \frac{e^{-xz}}{(e^{\epsilon_1 z}-1)(e^{\epsilon_2 z}-1)}\bigg{|}_{s=0}, \quad \Re(x)>0, \quad \Re(\epsilon_{1/2})\neq 0,
\end{equation}
and satisfies the difference equation:
\begin{equation}
   \gamma_{\epsilon_1,\epsilon_2}(x-\epsilon_1)+\gamma_{\epsilon_1,\epsilon_2}(x-\epsilon_2)-\gamma_{\epsilon_1,\epsilon_2}(x-\epsilon_1-\epsilon_2)-\gamma_{\epsilon_1,\epsilon_2}(x)=\log x.
\end{equation}
Many useful properties of this function, including its shift relations, can be found e.g. in the appendices of \cite{Bonelli:2025owb} and \cite{Bershtein:2018zcz}. Coming back to the instanton part of the partition function, we have \cite{Bruzzo:2002xf,Flume:2002az}:
\begin{equation}
    z_{fund}(a,\mu,\boldsymbol{Y})=\prod_{\pm}\prod_{(i,j)\in Y_{\pm}}(\mu\pm a+(i-1/2)\epsilon_1 +(j-1/2)\epsilon_2),
\end{equation}
while, in order to define $z_{vec}$, we first define:
\begin{equation}
\begin{aligned}
z_{bif}(\vec{a},\vec{b},m,\boldsymbol{Y},\boldsymbol{W})=&\prod_{\alpha,\beta=\pm}\prod_{s_1\in Y_{\alpha}}\left[a_{\alpha}-b_{\beta}+\epsilon_{2}\left(A_{Y_{\alpha}}(s_1)+1\right)-\epsilon_{1}L_{W_{\beta}}(s_1)-m\right]\\
&\prod_{s_2\in W_{\beta}}\left[a_{\alpha}-b_{\beta}+\epsilon_{1}\left(L_{Y_{\alpha}}(s_2)+1\right)-\epsilon_{2}A_{W_{\beta}}(s_2)-m\right],
\end{aligned}
\end{equation}
where, following \cite{Alday:2009aq}, $\vec{a}=(a_+,a_-)$ and $\vec{b}=(b_+,b_-)$, $s_{1}$ and $s_{2}$ label a box in the corresponding Young tableau, $A_Y $ and $L_Y$ are defined as: 
\begin{equation}
    A_{Y}(s)= \lambda_{i}-j\,, \quad L_{Y}(s)=\lambda^{'}_{j}-i, \quad s=(i,j)\in Y,
\end{equation}
and the Young tableau $Y$ is identified with the corresponding partition $Y=\{\lambda_{1}\geq...\geq\lambda_{n}>0\}$, $Y^{T}=\{\lambda^{'}_{1}\geq...\geq\lambda^{'}_{m}>0\}$ being its transpose. Then, we have:
\begin{equation}
    z_{adj}(a,m,\boldsymbol{Y})=z_{bif}(\vec{a},\vec{a},m,\boldsymbol{Y},\boldsymbol{Y}),
\end{equation}
where $\vec{a}=(a,-a)$, and finally:
\begin{equation}
    z_{vec}(a,\boldsymbol{Y})=z_{adj}(a,0,\boldsymbol{Y}).
\end{equation}
Moving on to the partition function of the $\mathcal{N}=2^{*}$ $SU(2)$ gauge theory, we have:
\begin{equation}
\label{eq: SU(2) Z *}
    \mathcal{Z}(a,m;\epsilon_1,\epsilon_2;\mathfrak{q})=\mathcal{Z}_{cl}(a;\epsilon_{1},\epsilon_{2};\mathfrak{q})\mathcal{Z}_{1\text{-}loop}(a,m;\epsilon_1,\epsilon_2)\mathcal{Z}_{inst}(a,m;\epsilon_1,\epsilon_2;\mathfrak{q}),
\end{equation}
where:
\begin{subequations}
\begin{align}
&\mathcal{Z}_{cl}(a;\epsilon_{1},\epsilon_{2};\mathfrak{q})=\mathfrak{q}^{-\frac{a^2}{\epsilon_1 \epsilon_2}},\\[1ex]
&\mathcal{Z}_{1\text{-}loop}(a,m;\epsilon_1,\epsilon_2)=\prod_{\pm}\frac{\exp(\gamma_{\epsilon_1,\epsilon_2}(\pm2 a-m))}{\exp(\gamma_{\epsilon_1,\epsilon_2}(\pm2 a))}\label{eq: SU(2) 1-loop star},\\[1ex]
&\mathcal{Z}_{inst}(a,m;\epsilon_1,\epsilon_2;\mathfrak{q})=\varphi(\mathfrak{q})^{1-\frac{2m(Q-m)}{\epsilon_1 \epsilon_2}}\mathcal{Z}_{inst}^{U(2)}(a,m;\epsilon_1,\epsilon_2;\mathfrak{q})\label{eq: zinst 2*},
\end{align}
\end{subequations}
and finally:
\begin{equation}
\label{eq: U(2) inst star}
   \mathcal{Z}_{inst}^{U(2)}(a,m;\epsilon_1,\epsilon_2;\mathfrak{q})= \sum_{\boldsymbol{Y}}\mathfrak{q}^{|\boldsymbol{Y}|}\frac{z_{adj}(a,m,\boldsymbol{Y})}{z_{vec}(\vec{a},\boldsymbol{Y})}.
\end{equation}
In conclusion, we describe how the semi-classical limit $\psi_{s}$ of the degenerate torus blocks in the $necklace$ basis $\Phi^{(n)}_{s}$, as in equation \eqref{eq: 2pt classical}, can be expressed in terms of surface defect partition functions of the $\mathcal{N}=2^{*}$ $SU(2)$ gauge theory. We consider the quiver gauge theory \cite{Katz:1997eq,Gaiotto:2009we, Nekrasov:2012xe} associated to the circular quiver with two $SU(2)$ gauge nodes, one of which is degenerate \cite{Nekrasov:2017rqy}, and compute its instanton partition function as:
\begin{equation}
\begin{aligned}
\mathcal{Z}_{s,\, inst}^{defect}(z,\sigma,m;\epsilon_1,\epsilon_2;\mathfrak{q})=&\sum_{\boldsymbol{Y},\boldsymbol{W}}z^{|\boldsymbol{Y}|-|\boldsymbol{W}|}\mathfrak{q}^{\frac{|\boldsymbol{Y}|+|\boldsymbol{W}|}{2}}\frac{z_{bif}(\vec{\sigma}_1,\vec{\sigma}_2,m,\boldsymbol{Y},\boldsymbol{W})}{z_{vec}(\sigma,\boldsymbol{Y})}\\
&\cdot\frac{z_{bif}(\vec{\sigma}_2,\vec{\sigma}_1,-\epsilon_2/2,\boldsymbol{W},\boldsymbol{Y})}{z_{vec}(\sigma-s\epsilon_2/2,\boldsymbol{W})},
\end{aligned}
\end{equation}
where $\vec{\sigma}_1=(\sigma,-\sigma)$ and $\vec{\sigma}_2=(\sigma-s\epsilon_2/2,-\sigma+s\epsilon_2/2)$, $s=\pm$. Up to a simple overall prefactor, the AGT correspondence implies the relation:
\begin{equation}
    \Phi^{(n)}_{s}(x+i\tau/2,a,m;\mathfrak{q})\propto \mathcal{Z}^{U(1)}(z,m;\mathfrak{q})\mathcal{Z}_{s,\, inst}^{defect}(e^{2i\pi x},a-Q/2,m;b,b^{-1};\mathfrak{q}),
\end{equation}
where $Q=\epsilon_1+\epsilon_2=b+b^{-1}$, while:
\begin{equation}
\begin{aligned}
\mathcal{Z}^{U(1)}(z,m;\mathfrak{q})=&\prod_{l\geq 0}\left(1-\mathfrak{q}^{l+1}\right)^{2m(Q-m)-3b^{2}/2-2}\left(1-z\mathfrak{q}^{l+1/2}\right)^{-b(Q-m)}\\
&\cdot\left(1-z^{-1}\mathfrak{q}^{l+1/2}\right)^{2m(Q+b/2)}.
\end{aligned}
\end{equation}
Thus, taking the semi-classical limit, we obtain the following representation for a pair of linearly independent Floquet solutions of the Lamé equation (\ref{eq: hill}):
\begin{equation}
\label{eq: classical defect}
\psi_s(x,\nu,\mu;\mathfrak{q})=e^{-2\pi isx}\lim_{b\to 0}\frac{\mathcal{Z}_{s,\, inst}^{defect}(e^{2i\pi x},\frac{\nu}{2b},\frac{\mu}{b};b,b^{-1};\mathfrak{q})}{\mathcal{Z}_{ inst}(\frac{\nu}{2b},\frac{\mu}{b};b,b^{-1};\mathfrak{q})}.
\end{equation}





\section{Checks}
\label{app: checks}

\subsection{Comparison with Hill determinant method}
\label{app: checks 1}
In this sub-appendix, we describe how the expansions of the eigenvalues and eigenfunctions of the Lamé equation can be computed using standard techniques. The first method we present concerns the computation of eigenvalues and is known as the Hill determinant method \cite{Wang:1989}. Consider the following complex Hill equation:
\begin{equation}
\label{eq: hill appendix}
    -\partial_{x}^{2}\psi(x)+V(x)\psi(x)=0,
\end{equation}
with $V(x)$ an even, periodic potential of period $\pi$. Its Fourier expansion reads:
\begin{equation}
    V(x)=a_{0}+\sum_{k\neq 0}a_{k}e^{2ikx},
\end{equation}
where $a_{-k}=a_{k}$, due to the parity of the potential, and $a_{k}\in \mathbb{C}$ for any $ k\in\mathbb{Z}$. We search for a Floquet solution $\psi(x)$, meaning a quasi-periodic function such that $\psi(x+\pi)=e^{i \nu \pi}\psi(x)$, where $\nu \in \mathbb{C}$ is the Floquet exponent. We can then write $\psi(x)$ in the form $\psi(x)=e^{i \nu x}\phi(x)$, where $\phi(x)$ is a periodic function of period $\pi$, and expand $\phi(x)$ in Fourier series, obtaining:
\begin{equation}
    \psi(x)=e^{i\nu x}\sum_{n=-\infty}^{\infty}b_{n}e^{2inx},
\end{equation}
where $b_{n}\in \mathbb{C}$ for any $n \in \mathbb{Z}$. Inserting this expansion into equation (\ref{eq: hill appendix}), we find:
\begin{equation}
    \sum_{n=-\infty}^{\infty}b_{n}(\nu+2n)^{2}e^{i(\nu+2n)x}+\sum_{k=-\infty}^{\infty}a_{k}e^{2ikx}\sum_{n=-\infty}^{\infty}b_{n}e^{i(\nu+2n)x}=0,
\end{equation}
and thus an infinite number of linear equations of the form:
\begin{equation}
    (\nu+2n)^{2}b_{n}+\sum_{k=-\infty}^{\infty}a_{k}b_{n-k}=0, \quad\forall n \in \mathbb{Z}.
\end{equation}
This system can be reformulated as the following matrix equation:
\begin{equation}
    \sum_{m\in \mathbb{Z}}B_{nm}b_{m}=0\,, \quad B_{nn}=a_{0}+(\nu+2n)^{2}\,,\quad B_{nm}=a_{n-m},
\end{equation}
which admits non-trivial solutions if and only if the determinant of the matrix $B$ vanishes. We can then use this last condition as an equation for determining the eigenvalues. In the case of equation (\ref{eq: lame std}), the relevant Fourier expansion of the potential is given by:
\begin{equation}
\label{eq: p fourier}
\wp(x+\pi\tau/2;\pi,\pi\tau)=-\frac{2}{\pi^2}\eta_{1}(\tau)-4\sum_{k\geq 1}2k\,\cos2k x\, \frac{\mathfrak{q}^{k/2}}{1-\mathfrak{q}^{k}},
\end{equation}
which leads to the identification:
\begin{equation*}
a_{0}=\text{\Large $\mathfrak{e}$}\,,\quad a_{k}=4\mu(\mu-1)k\frac{\mathfrak{q}^{k/2}}{1-\mathfrak{q}^{k}}.
\end{equation*}
We can then solve the condition $\det B=0$ as an equation for $\text{\Large $\mathfrak{e}$}=\nu^{2}+\cdots$, obtaining a power series expansion in $\mathfrak{q}^{1/2}$. In particular, solving the equation for generic values of $\nu$ we recover the expansion (\ref{eq: expansion ns lame}). Meanwhile, fixing $\nu$ to a specific integer value from the outset yields the expansion for the corresponding periodic or anti-periodic eigenvalue. The two possible eigenvalues corresponding to the same value of $|\nu|$ arise from the two distinct solutions of a quadratic equation satisfied by the first non-trivial coefficient in the expansion. An equivalent approach for computing the eigenvalues is provided by a continued fraction expansion, which is also available in the literature: \cite{doi:10.1142/S0219530504000023}. Alternatively, one can directly solve equation (\ref{eq: lame std}) as a power series in $\mathfrak{q}^{1/2}$ by expanding both the eigenfunction and the eigenvalue accordingly. Indeed, considering the Fourier expansion (\ref{eq: p fourier}), the equation takes the form:
\begin{equation}
\label{eq: lamé fourier}
    \Big(\partial_{x}^{2}+4\mu(\mu-1)\sum_{k\geq 1}2k\,\cos2kx\,\frac{\mathfrak{q}^{k/2}}{1-\mathfrak{q}^{k}}+\text{\Large $\mathfrak{e}$}\Big)\psi=0,
\end{equation}
where the eigenvalue is expanded as:
\begin{equation}
\text{\Large $\mathfrak{e}$}(\nu,\mu;\mathfrak{q}) = \sum_{n\geq 0}e_{n}(\nu,\mu)\mathfrak{q}^{n/2}.
\end{equation}
To proceed, we must specify the form of the eigenfunction $\psi(x)$, distinguishing between the case of non-integer and integer $\nu$, which correspond respectively to quasi-periodic and (anti-)periodic solutions. In the first case, we can write:
\begin{equation}
    \psi_{\pm}(x,\nu,\mu;\mathfrak{q})=e^{\pm i \nu x}\sum_{n\geq 0}\psi_{n}(x,\nu,\mu)\mathfrak{q}^{n/2},
\end{equation}
where the coefficients $\psi_{n}(x,\nu,\mu)$ are periodic functions of period $\pi$, more specifically Laurent polynomials in $e^{ 2 i x}$. Equivalently, we can consider the even and odd combinations:
\begin{subequations}
\begin{align}
&\psi_{even}(x,\nu,\mu;\mathfrak{q})=\psi_{+}(x,\nu,\mu;\mathfrak{q})+\psi_{-}(x,\nu,\mu;\mathfrak{q}),\\[1ex]
&\psi_{odd}(x,\nu,\mu;\mathfrak{q})=\psi_{+}(x,\nu,\mu;\mathfrak{q})-\psi_{-}(x,\nu,\mu;\mathfrak{q}).
\end{align}
\end{subequations}
Meanwhile, for a fixed integer value of $\nu$, we can write:
\begin{subequations}
\begin{align}
&\psi_{even}^{(\nu)}(x,\mu;\mathfrak{q})\propto \cos(|\nu|x)+\sum_{n\geq 1}\psi_{even,\,n}^{(\nu)}(x,\mu)\mathfrak{q}^{n/2},\\[1ex]
&\psi_{odd}^{(\nu)}(x,\mu;\mathfrak{q})\propto \sin(|\nu|x)+\sum_{n\geq 1}\psi_{odd,\,n}^{(\nu)}(x,\mu)\mathfrak{q}^{n/2},
\end{align}
\end{subequations}
where each coefficient $\psi_{even,\,n}^{(\nu)}$ and $\psi_{odd,\,n}^{(\nu)}$ is a linear combination of elementary trigonometric functions. For example, the solution associated with a vanishing Floquet exponent $\nu=0$ takes the form:
\begin{equation}
    \psi^{(0)}(x)\propto 1 + 2 \mu(\mu-1)\cos\,2x \,\sqrt{\mathfrak{q}} + 
 \frac{1}{2} \mu (-2 + 3 \mu - 2 \mu^2 + \mu^3) \cos\,4x\,\mathfrak{q} +O(\mathfrak{q}^{3/2}),
\end{equation}
up to a choice of initial condition.
\subsection{\texorpdfstring{Consistency check at $\tau\to +i\infty$}{Check at tau to infinity}}
\label{app: checks 2}
In this sub-appendix we perform a consistency check of the quantization condition (\ref{eq: trmb=nudual}) in the $\tau\to +i \infty$ limit, where the problem reduces to the analysis of the hyperbolic Pöschl–Teller potential \cite{practicalQM}. Indeed, consider the Lamé equation:
\begin{equation}
    -\partial_{x}^{2}\psi+\mu(\mu-1)\wp(x;1,\tau)\psi=E\psi,
\end{equation}
Using the transformation properties of the Weierstrass $\wp$-function, we can write:
\begin{equation}
    \wp(x;1,\tau)=t^{-2}\wp(x/t;1/t,i),
\end{equation}
where $t=\Im(\tau)$, so that, performing the change of variable $z=x/t$, the equations becomes: 
\begin{equation}
     -\partial_{z}^{2}\psi+\mu(\mu-1)\wp(z;1/t,i)\psi=t^{2}E\psi.
\end{equation}
The Weierstrass $\wp$-function can be represented as:
\begin{equation}
    \wp(z;1/t,i)=t^{2}\left(\frac{\pi^{2}}{\sin^{2}\pi z t}-\frac{\pi^{2}}{3}+\sum_{k\neq 0}\frac{\pi^{2}}{\sin^{2}\pi t(z-k i)}-\frac{\pi^{2}}{\sin^{2}\pi tk i}\right),
\end{equation}
and in the $t \to +\infty$ limit we can approximate it by:
\begin{equation}
    \wp(z;1/t,i)\simeq t^{2}\left(\frac{\pi^{2}}{\sin^{2}\pi z t}-\frac{\pi^{2}}{3}\right).
\end{equation}
Setting now $z=i v +1/2t$, so as to lie along the vertical line at the center of the torus, we find:
\begin{equation}
    \left[-\partial_{v}^{2}-\mu(\mu-1)\frac{t^{2}\pi^{2}}{\cosh^{2}\pi t v}+t^{2}\left(E+\frac{\pi^{2}}{3}\mu(\mu-1)\right)\right]\psi=0.
\end{equation}
Up to exponentially small corrections, we can approximate the potential on the B-cycle as an infinite sum of such localized contributions centered at $v \in \mathbb{Z}$, with the previous equation serving as the effective description in the vicinity of $v=0$. To solve it, we make the substitutions:
\begin{equation}
    y = \cosh^{2}\pi t v\,, \quad E=-\kappa^{2}\pi^{2}-\frac{\pi^{2}}{3}\mu(\mu-1),
\end{equation}
obtaining the hypergeometric equation:
\begin{equation*}
y\left(1-y\right)\psi''+\left(\frac{1}{2}-y\right)\psi'-\frac{1}{4}\left(\frac{\mu(\mu-1)}{y}+\kappa^{2}\right)\psi=0 .
\end{equation*}
Setting then $\psi=y^{\mu/2}\phi$, we find:
\begin{equation*}
    y(1-y)\phi''+\left(\frac{1}{2}+\mu-y(1+\mu)\right)\phi'-\frac{1}{4}\left(\kappa^{2}+\mu^{2}\right)\phi=0,
\end{equation*}
which we can easily solve near $y=1$, or $v=0$, in terms of hypergeometric functions. Expressing the solutions in terms of the variable $v$, we find:
\begin{subequations}
\begin{align}
&\psi_{even}(v)=\cosh^{\mu}\pi t v 
\ _2F_1\left(\frac{\mu+i\kappa}{2},\frac{\mu-i\kappa}{2},\frac{1}{2};-\sinh^{2}\pi tv\right),\\
&\psi_{odd}(v)=\sinh\pi t v\,\cosh^{\mu}\pi t v \ _2F_1\left(\frac{1+\mu+i\kappa}{2},\frac{1+\mu-i\kappa}{2},\frac{3}{2};-\sinh^{2}\pi tv\right),
\end{align}
\end{subequations}
distinguishing the two linearly independent solutions by parity. Then, in the vicinity of the other integer $v$ points, we will have similar local solutions. For example, near $v=1$, we would find: $\Tilde{\psi}_{even/odd}(v)=\psi_{even/odd}(1-v)$. To obtain the desired quantization condition, we must impose the periodicity of the solutions, which can be achieved by matching their asymptotic behaviors. Indeed, assuming $t>>1$, for $0<v<1$, we have:
\begin{equation}
\begin{aligned}
\psi_{even}(v) &\simeq\ 
\frac{\Gamma\left(\frac{i\kappa}{2}\right) \Gamma\left(\frac{1}{2} + \frac{i\kappa}{2}\right)}{\Gamma\left(\frac{i\kappa}{2} + \frac{\mu}{2}\right) \Gamma\left(\frac{1}{2} - \frac{\mu}{2} + \frac{i\kappa}{2}\right)} e^{i \kappa \pi t v} +\frac{\Gamma\left(-\frac{i\kappa}{2}\right) \Gamma\left(\frac{1}{2} - \frac{i\kappa}{2}\right)}{\Gamma\left(-\frac{i\kappa}{2} + \frac{\mu}{2}\right) \Gamma\left(\frac{1}{2} - \frac{\mu}{2} - \frac{i\kappa}{2}\right)} e^{-i \kappa \pi t v}\\[4pt]
&=\Omega_{even}e^{i\kappa \pi t v}+\Bar{\Omega}_{even}e^{-i\kappa \pi t v},
\end{aligned}
\end{equation}
and imposing (anti-)periodicity, namely $\psi_{even}(v)=\pm\psi_{even}(v+1)$, we obtain:
\begin{equation}
\label{eq: qc limit even}
    e^{i\kappa \pi t}\frac{\Omega_{even}}{\Bar{\Omega}_{even}}=\pm 1.
\end{equation}
Similarly, for the odd solution we have:
\begin{equation}
\begin{aligned}
\psi_{\text{odd}}(v) &\simeq \frac{1}{4}  \frac{\Gamma\left(\frac{i\kappa}{2}\right) \Gamma\left(\frac{1}{2} + \frac{i\kappa}{2}\right)}{\Gamma\left(\frac{1}{2} + \frac{i\kappa}{2} + \frac{\mu}{2}\right) \Gamma\left(1 - \frac{\mu}{2} + \frac{i\kappa}{2}\right)} e^{i \kappa \pi t v}
+\frac{1}{4}  \frac{\Gamma\left(-\frac{i\kappa}{2}\right) \Gamma\left(\frac{1}{2} - \frac{i\kappa}{2}\right)}{\Gamma\left(\frac{1}{2} - \frac{i\kappa}{2} + \frac{\mu}{2}\right) \Gamma\left(1 - \frac{\mu}{2} - \frac{i\kappa}{2}\right)} e^{-i \kappa \pi t v} \\[4pt]
&= \Omega_{\text{odd}} e^{i \kappa \pi t v} + \Bar{\Omega}_{\text{odd}} e^{-i \kappa \pi t v},
\end{aligned}
\end{equation}
and imposing $\psi_{odd}(x)=\pm\psi_{odd}(x+1)$, we find the quantization condition:
\begin{equation}
\label{eq: qc limit odd}
    e^{i\kappa \pi t}\frac{\Omega_{odd}}{\Bar{\Omega}_{odd}}=\mp 1 .
\end{equation}
By solving equation (\ref{eq: trmb=nudual}) for $e^{\eta/2}$ in the case of periodic or anti-periodic solutions, corresponding to $\cos\nu_D=\pm1$, we obtain:
\begin{subequations}
\begin{align}
& e^{\eta/2}= \pm \frac{\sin2\pi a - \sin\pi \mu}{\sin\pi(2a-\mu)},\label{eq: qc limit 1}\\
& e^{\eta/2}= \pm \frac{\sin2\pi a + \sin\pi \mu}{\sin\pi(2a-\mu)},\label{eq: qc limit 2}
\end{align}
\end{subequations}
where 
\begin{equation}
    \eta = 4\pi a t+2\log\frac{\Gamma(\mu-2a)\Gamma(1+2a)}{\Gamma(\mu+2a)\Gamma(1-2a)},
\end{equation}
neglecting corrections that are exponentially suppressed in the limit $t \to +\infty$. Upon identifying $\kappa = 2a/i$, we find that the quantization condition (\ref{eq: qc limit even}) matches with (\ref{eq: qc limit 1}), while the quantization condition (\ref{eq: qc limit odd}) corresponds to (\ref{eq: qc limit 2}).



\section{Blow-up equations}
\label{app: blow-up}
\subsection{\texorpdfstring{Useful formulae for $N_f>0$}{Formulas for Nf>0.}}
\label{app: blow-up formulas}
In this subsection, we collect some lengthy formulas relevant to the $\mathbb{C}^2$ and $\mathbb{C}^2/\mathbb{Z}_2$ blow-up equations for generic $N_f\leq 4$. First, the regular parts of the resummation ansatz for $N_f = 4$ are given by \cite{Poghossian:2009mk}:
\begin{equation}
\label{eq: reg0}
\begin{aligned}
&R_{0}^{[4]}(a,\{\mu_i \},\hbar;t)=\frac{a^2}{\hbar}\left(\frac{\pi  K(1-t)}{K(t)}+\log \left(\frac{t}{16}\right)\right)+\frac{1}{4\hbar}\left(\sum_{i=1}^{4}\mu_i\right)^{2}\log (1-t)\\
&+\frac{1}{\hbar}\left(\sum_{i=1}^{4}\mu_{i}^{2}\right)\log\left(\frac{2}{\pi}K(t) \right)+\frac{1}{2}\left(\sum_{i=1}^{4}\mu_i\right)\log(1-t)+\frac{\hbar}{4}\left(\log (1-t)-2 \log \left(\frac{2 K(t)}{\pi }\right)\right)\\
\end{aligned}
\end{equation}
\begin{equation}
\label{eq: reg1}
R_{1}^{[4]}(\{\mu_i \},\hbar;t)=\frac{1}{2} \left(\log (1-t)-2 \log \left(\frac{2 K(t)}{\pi }\right)\right)+\frac{1}{2\hbar}\left(\sum_{i=1}^{4}\mu_i\right)\log(1-t).
\end{equation}
From these expressions, it is possible to derive all other regular parts for $N_f \leq 3$ by decoupling the appropriate number of hypermultiplets. The function $R_{1}^{[4]}(\{\mu_i \},\hbar;t)$ is determined in terms of $R_{0}^{[4]}(\{\mu_i \},\hbar;t)$, for example by taking the large $a$ limit of the blow-up equation (\ref{eq: blow-up 1 pure ns}). Indeed, in this limit, the equation reduces to:
\begin{equation}
    t\partial_{t}\left(\mathcal{W}_{1,\, inst}(a,\{\mu_i\},\hbar;t)-\left(\partial_{\hbar}+\frac{1}{\hbar}\right)\mathcal{W}_{0,\, inst}(a,\{\mu_i\},\hbar;t)\right)\simeq 0
\end{equation}
thus fixing $R_{1}^{[4]}$ up to a $t$-independent term, which can then be seen to vanish. Then, writing: 
\begin{equation*}
\widetilde{\mathcal{G}}_{exp/inst}^{\,\mp,\,[N_f]} = \widetilde{\mathcal{G}}_{exp/inst}^{[N_f]}\left(\frac{m_{1}x+t^{m_{2}/2}}{2x},\{\mu_{i}\},\mp j -m_{1},t\right)
\end{equation*}
the expressions necessary to determine the differential equations satisfied by the resummation functions read:
\begin{equation}
\label{eq: Gexp Nf}
\begin{aligned}
&\log \widetilde{\mathcal{G}}_{exp}^{\,\mp,\,[N_f]}=2t^{k-1} \bigg\{
\tilde{f}_{k,j} 
\mp m_1 y^2\, \partial_{y}g_{k,j}
\mp t^{j/2} \bigg(\big[1-(4-N_f)(k+j/2-1)\big]g_{k,j} \\
&+\big[1-(4-N_f)j/2\big]y\,  \partial_{y}g_{k,j}-\tilde{g}_{k,j}- \sum_{i=1}^{N_{f}}\mu_i\, \partial_{\mu_i} g_{k,j}
\bigg)\bigg\}    + \sigma_{exp}^{\,\mp,\,[N_f]}(x,\{\mu_{i}\},t),
\end{aligned}
\end{equation}
\begin{equation}
\label{eq: Ginst Nf}
\begin{aligned}
&\widetilde{\mathcal{G}}_{inst}^{\,\mp,\,[N_f]}=\frac{j}{2} (j \pm m_1) 
+ t^{k-1} \bigg\{ (k - 1)\, \tilde{f}_{k,j}
+j \frac{y}{2} \,  \partial_{y}\tilde{f}_{k,j} \\
&\mp m_1 y \left[
(j + k - 1)\,  \partial_{y}g_{k,j}
+ j \frac{y}{2}\,  \partial_{y}^2g_{k,j}
\right]
\pm t^{j/2} \Big[
(k+j/2 - 1)\, \tilde{g}_{k,j}\\
&+ j\frac{y}{2}\,  \partial_{y}\tilde{g}_{k,j}-\big[2-(4-N_f)(k+j/2-1)\big](k+j/2 - 1)\, g_{k,j}\\
&- \big[k+2j-1-j(4-N_f)(k+3j/4-1)\big]y\,  \partial_{y}g_{k,j}
- j\big(1-\frac{j}{2}(4-N_f)\big)\frac{y^2}{2}\,  \partial_{y}^2g_{k,j}\\
& + \sum_{i=1}^{N_{f}} \mu_i \left(
(k+j/2 - 1)\, \partial_{\mu_i} g_{k,j}+
+ j\frac{y}{2}\,  \partial_{\mu_i} \partial_{y}g_{k,j}
\right)
\Big]\bigg\}+ \sigma_{inst}^{\,\mp,\,[N_f]}(x,\{\mu_{i}\},t),
\end{aligned}
\end{equation}
where $y=x t^{(j-m_{2})/2}$.  Assuming the asymptotic behavior of the resummation functions as in Section \ref{sec: results}, we find again that the expansions of the blow-up equations under consideration are proper series expansions. Finally, if $\varsigma_{m_{2}}=\frac{1-(-1)^{m_2}}{2}$ and we define:
\begin{equation}
\label{eq: c tilde}
    \tilde{c}_{m_{1},m_{2}}(\mu)=\mu^{m_{1}\varsigma_{m_{2}}}\prod_{j=\frac{1}{2}+\frac{\varsigma_{m_{2}}}{2}}^{\frac{m_2 -1}{2}}(\mu-j)^{m_1}(\mu+j)^{m_1},
\end{equation}
we have:
\begin{equation}
\label{eq: constant c Nf}
    d_{m_1,m_2}(\{\mu_{i}\})=-\frac{\prod_{i=1}^{N_f}\tilde{c}^{\,2}_{m_1, m_2}(\mu_i)}{m_{2}^{4m_1}[(m_{2}-1)!]^{8m_1}}.
\end{equation}
\subsection{\texorpdfstring{Example: $\mathbb{C}^2$ blow-up equations, $\mathcal{N}=2^{*}$ theory}{C2, N2star theory}}
\label{app: blow-up example 1}
In this section, we present and solve the first few equations derived from the expansion of the $\mathbb{C}^2$ blow-up equation \eqref{eq: C2 blow-up lame expl}. We focus on this case because the presence of both integer and half-integer shifts allows us to work with lower values of \( m_1 \), thereby reducing the complexity introduced by the Taylor coefficients of the resummation functions appearing in the equations. Specifically, we analyze the equations for $m_2=1$ and \( m_1 = 1, 2 \). The first two of these read, respectively:
\begin{subequations}
\begin{align}
& e^{2 \tilde{f}_{1,1}(x, \mu) + x^2 \partial_{x}g_{1,1}(x, \mu)} + \mu^2(\mu - 1)^2 x^2 \, e^{2 \tilde{f}_{1,1}(x, \mu) - x^2 \partial_{x}g_{1,1}(x, \mu)} - 1 = 0, \\
& e^{2 \tilde{f}_{1,1}(x, \mu) + 2x^2 \partial_x g_{1,1}(x, \mu) } 
- \mu^4(\mu - 1)^4 x^4 \, e^{2 \tilde{f}_{1,1}(x, \mu) - 2 x^2 \partial_x g_{1,1}(x, \mu)} 
- 1 = 0.
\end{align}
\end{subequations}
Performing the substitutions \(\tilde{f}_{1,1} = \frac{1}{2} \log u_1\) and \(g_{1,1}' = \frac{1}{x^2} \log(x v_1)\), and solving for \(u_1\), we obtain:
\begin{subequations}
\begin{align}
&u_1(x,\mu)=\frac{1}{ x\left(v_1(x, \mu) +\mu^2(-1 + \mu)^2 \,  v_1(x, \mu)^{-1}\right)},\\
&u_1(x,\mu) =\frac{1}{x^2 \left(v_1(x, \mu)^2- \mu^4(-1 + \mu)^4  \, v_1(x, \mu)^{-2}  \right)}
\end{align}
\end{subequations}
so that, by equating the two expressions for $ u_1 $, we find:
\begin{equation}
    v_1(x,\mu)=\frac{1\pm\sqrt{1+4 \mu ^2(\mu -1)^2 x^2}}{2 x},
\end{equation}
where only the choice of the $+$ sign in front of the square root is compatible with the boundary condition $g_{1,1}(0, \mu) = 0$. Thus, we find the following expressions for the first two resummation functions:
\begin{subequations}
\begin{align}
&\tilde{f}_{1,1}(x,\mu)=-\frac{1}{4} \log \left(1+4\mu ^2 (\mu -1)^2 x^2\right)\\
&g_{1,1}(x,\mu) = \frac{
\sqrt{1 + 4 \mu^2 (\mu - 1)^2 x^2} 
- \log\left( \tfrac{1}{2} + \tfrac{1}{2}\sqrt{1 + 4 \mu^2 (\mu - 1)^2 x^2} \right) - 1
}{x}.
\end{align}
\end{subequations}
Using the explicit forms of $\tilde{f}_{1,1}$ and $g_{1,1}$, and after some simplification, the second equation for $m_1 = 1$ takes the form:
\begin{equation}
    \left(1+ \sqrt{1+4\mu^2 (\mu - 1)^2 x^2} \right) \tilde{g}_{1,1}(x, \mu)
+ 2 \mu \left( \mu^3 - 2\mu + 1 \right) =0
\end{equation}
which can easily be solved to obtain:
\begin{equation}
\tilde{g}_{1,1}(x,\mu) = \frac{(-1 + \mu + \mu^2)\left(1- \sqrt{1 + 4 \mu^2 (\mu - 1)^2 x^2}  \right)}{2 \mu (\mu - 1) x}.
\end{equation}
Then, the second equation for $m_1=2$ is identically satisfied. Moving on to the third equation for $m_1 = 1$, and expanding it to the first few orders around $x = 0$, one obtains the following relation:
\begin{equation}
\begin{aligned}
\partial_x^2 \tilde{f}_{1,2}(\mu, 0)&=\frac{1}{4(\mu + 1)} \left[
- \mu^2 (\mu - 1)^2 ( -20 + 56\mu - 27\mu^2 - 45\mu^3 + 19\mu^4 + \mu^5 )\right.\\
&\left.
+\, 8 \, \partial_x^2 \tilde{f}_{2,1}(\mu, 0)
- 4 (\mu + 1) \, \partial_x g_{1,2}(\mu, 0)
+ 8 \, \partial_x g_{2,1}(\mu, 0)
\right]
\end{aligned}
\end{equation}
which simplifies the equation and allows it to be easily solved for $\tilde{f}_{2,1}$, yielding:
\begin{equation}
\tilde{f}_{2,1}(x, \mu)=-\frac{x^2 \, }{2 \sqrt{1+4 \mu^2 (\mu - 1)^2 x^2 }}\partial_x g_{2,1}(x, \mu)+ \dots
\end{equation}
where the remaining terms form a lengthy expression in $x$ and $\mu$, involving only $\partial_x^2 \tilde{f}_{2,1}(\mu, 0)$ and $\partial_x g_{2,1}(\mu, 0)$. Similarly, expanding the third equation for $m_1=2$ around $x=0$, we find the following relation:
\begin{equation}
\begin{aligned}
\partial_x g_{1,2}(\mu,0)=&\frac{1}{4(\mu + 1)} \left[
(\mu - 1)^2 \left(2 \mu^6 - 5 \mu^5 + 17 \mu^4 - 31 \mu^3 - 29 \mu^2 + 50 \mu - 16\right) \mu^2
\right.\\
&\left.
+ \left(-\mu^2 + \mu - 6\right) \partial_x^2 \tilde{f}_{2,1}(\mu, 0)
- 2 \left(\mu^2 - \mu + 2\right) \partial_x g_{2,1}(\mu, 0)
\right]
\end{aligned}
\end{equation}
which can be used to simplify it. Substituting the expression of $\tilde{f}_{2,1}$ as a function of $g_{2,1}$, one can easily solve the equation to find:
\begin{equation}
\begin{aligned}
&\partial_x g_{2,1}(\mu,x)=\frac{1}{2}\bigg[
\mu^4(\mu - 1)^4 \left(5 \mu^4 - 10 \mu^3 - 7 \mu^2 + 12 \mu - 6\right)+ 2\, \partial_x g_{2,1}(\mu,0)
\\
&
+ x^2 \left(6 \mu^2(\mu - 1)^2 \, \partial_x g_{2,1}(\mu,0) \right)
+ \bigg(2\, \partial_x g_{2,1}(\mu,0)+ 2 (\mu - 1)^2 \mu^2 \, \partial_x g_{2,1}(\mu,0) x^2\\
& +(\mu - 1)^4 \mu^4 \left(\mu^4 - 2 \mu^3 - 3 \mu^2 + 4 \mu - 2\right) x^2\bigg) \sqrt{1 + 4 \mu^2 (\mu - 1)^2 x^2} \bigg]\cdot \\
&
\left[
1 + 5 \mu^2 (\mu - 1)^2 x^2
+ 4 \mu^4 (\mu - 1)^4 x^4
+ \left(1 + 3 \mu^2 (\mu - 1)^2 x^2\right) \sqrt{1 + 4 \mu^2 (\mu - 1)^2 x^2}
\right]^{-1}.
\end{aligned}
\end{equation}
Expanding the previous function for $x \to +\infty$, we find at leading order:
\begin{equation}
\partial_x g_{2,1}(\mu, x) \simeq \frac{1}{4 \mu (\mu - 1)} \bigg(
2\, \partial_x g_{2,1}(\mu, 0)- \mu^2 (\mu - 1)^2 \left(2 - 4\mu + 3\mu^2 + 2\mu^3 + \mu^4 \right)
\bigg)x^{-1}
\end{equation}
which is clearly incompatible with the expansion \eqref{eq: C2 Gexp gen}, thereby forcing $\partial_x g_{2,1}(\mu, 0)$ to take the form:
\begin{equation}
\partial_x g_{2,1}(\mu, 0)
= -\frac{1}{2} (\mu - 1)^2 \mu^2 \left( \mu^4 - 2\mu^3 - 3\mu^2 + 4\mu - 2 \right).
\end{equation}
Thus, we obtain:
\begin{equation}
\begin{aligned}
g_{2,1}(\mu,x)&=-\frac{2 (\mu -2) (\mu -1) (\mu +1) \mu-2 +3 (\mu -1)^4 \mu ^4 x^2}{12 (\mu -1)^2 \mu ^2 x^3}\\
&-\frac{\sqrt{1+4 (\mu -1)^2 \mu ^2 x^2}}{12 (\mu -1)^2 \mu ^2 x^3}\Big[2-2 \mu ^4+4 \mu ^3+2 \mu ^2-4 \mu\\
&+\left(\mu ^8-4 \mu ^7-2 \mu ^6+20 \mu ^5-27 \mu ^4+16 \mu ^3-4 \mu ^2\right) x^2\Big],
\end{aligned}
\end{equation}
\begin{equation}
    \tilde{f}_{2,1}(\mu,x)= \frac{\left(3 \mu ^8-12 \mu ^7+10 \mu ^6+12 \mu ^5-25 \mu ^4+16 \mu ^3-4 \mu ^2\right) x^2}{2\big(1+4 (\mu -1)^2 \mu ^2 x^2\big)}.
\end{equation}
Moving on to the next equation for $m_1 = 1$, and expanding around $x = 0$ to the first few orders, we find the relations:
\begin{subequations}
\begin{align}
\partial_x^2 \tilde{f}_{1,2}(\mu, 0) &= -\frac{1}{2} \mu^2 (\mu + 1)^2 \left(\mu^2 - 3\mu + 2\right)^2, \\
\partial_x g_{1,2}(\mu, 0) &= \frac{1}{4} \mu^2 (\mu + 1)^2 \left(\mu^2 - 3\mu + 2\right)^2,
\end{align}
\end{subequations}
and
\begin{equation}
\begin{aligned}
\partial_\mu \partial_x g_{1,2}(\mu, 0)
&= \frac{-8 (\mu + 1) \partial_x \tilde{g}_{1,2}(\mu, 0)
+ 16 \partial_x \tilde{g}_{2,1}(\mu, 0)}{4 \mu (\mu + 1)} \\
&+ \frac{(\mu - 1) \left(7 \mu^7 - 42 \mu^6 + 28 \mu^5 + 118 \mu^4 - 67 \mu^3 - 68 \mu^2 + 48 \mu - 8\right)}{4 (\mu + 1)},
\end{aligned}
\end{equation}
which allow us to simplify the equation. Then, the equation, now involving only the remaining Taylor coefficient $\partial_x \tilde{g}_{2,1}(\mu, 0)$, can be readily solved for $\tilde{g}_{2,1}$, which at leading order as $x \to +\infty$ reads:
\begin{equation}
\begin{aligned}
    \tilde{g}_{2,1}(\mu, x) \simeq\; & 
- \mu(\mu - 1) \Big( \mu(\mu -1)  \left(2 - 6\mu + 4\mu^2 + 9\mu^3 - 9\mu^4 - 5\mu^5 + 3\mu^6\right)  \\
& - 2\, \partial_x \tilde{g}_{2,1}(\mu, 0)
\Big)x^2 + \mathcal{O}(1).
\end{aligned}
\end{equation}
Again, this is clearly incompatible with the expansion \eqref{eq: C2 Gexp gen}, and thus we find:
\begin{equation}
   \partial_x \tilde{g}_{2,1}(\mu, 0) =\frac{1}{2} \mu(\mu -1)  \left(2 - 6\mu + 4\mu^2 + 9\mu^3 - 9\mu^4 - 5\mu^5 + 3\mu^6\right).
\end{equation}
which, when substituted into $\tilde{g}_{2,1}(\mu, x)$, yields:
\begin{equation}
\begin{aligned}
&\tilde{g}_{2,1}(\mu,x)= \big(12 (\mu - 1)^3 \mu^3 x^3\big)^{-1}\Big[
  2 \mu^6 - 6 \mu^5 + 6 \mu^4 + 2 \mu^3 - 6 \mu^2 + 6 \mu
  - 2\\
&+ \left(6 \mu^{10} - 24 \mu^9 + 33 \mu^8 - 12 \mu^7 - 12 \mu^6 + 12 \mu^5 - 3 \mu^4\right) x^2\Big]\\
&+\left(12 (\mu - 1)^3 \mu^3 x^3 \sqrt{1+4 (\mu - 1)^2 \mu^2 x^2} \right)^{-1}\Big[ -2 \mu^6 + 6 \mu^5 - 6 \mu^4 - 2 \mu^3\\
&+ 6 \mu^2 - 6 \mu + 2+ \big(
    10 \mu^{14} - 58 \mu^{13} + 84 \mu^{12} + 90 \mu^{11}
    - 372 \mu^{10} + 354 \mu^9\\
&- 20 \mu^8 - 202 \mu^7 + 162 \mu^6 - 56 \mu^5 + 8 \mu^4
  \big) x^4\\
&+ \left(
    -10 \mu^{10} + 44 \mu^9 - 73 \mu^8 + 44 \mu^7 + 20 \mu^6
    - 52 \mu^5 + 43 \mu^4 - 20 \mu^3 + 4 \mu^2
  \right) x^2\Big],
\end{aligned}
\end{equation}
while the corresponding equation for $m_1 = 2$ vanishes identically. This procedure can be straightforwardly extended to higher orders in the expansion, and to different values of $m_1$ and $m_2$, with no essential change in the steps involved.


\subsection{\texorpdfstring{Example: $\mathbb{C}^2/\mathbb{Z}_2$ blow-up equations, $N_f=0$ theory}{C2Z2, pure gauge theory}}
\label{app: blow-up example 2}
In this section we show and solve the first few differential equations obtained from the expansion of the blow-up equation (\ref{eq: blow-up 1 explicit 2}). This is instructive in order to discuss a couple of subtleties which are not manifest from the general form of the equations presented in the main part of this work. In particular, we consider the expansions for $m_2=1$ and $m_{1}=1,2$, up to the first six equations. The very first equation for $m_{1}=1$ reads:
\begin{equation}
\begin{aligned}
& e^{- 2 x^2  g_{1,1}'(x)}
   x^3 \left(-2 - x \tilde{f}_{1,1}'(x) + 
    2 x^2 g_{1,1}'(x) + x^3 g_{1,1}''(x) \right)\\
&+ e^{2 x^2 g_{1,1}'(x)}
    \left( \tilde{f}_{1,1}'(x) + 
    2x   g_{1,1}'(x) + x^{2}  g_{1,1}''(x)  \right)=0,
\end{aligned}
\end{equation}
and can be solved algebraically for $ \tilde{f}_{1,1}'$. Integrating the solution and imposing the vanishing of the function at $x=0$, we find: 
\begin{equation}
\label{eq: f11}
    \tilde{f}_{1,1}(x)=-\frac{1}{2}\log (e^{2x^{2} g_{1,1}'(x)}-x^{4}e^{-2x^{2} g_{1,1}'(x)}),
\end{equation}
or equivalently, expressing the solution in terms of $u_1(x)$ and $\tilde{v}_1(x)$, where $\tilde{f}_{1,1}=\frac{1}{2}\log u_1$ and $g_{1,1}'=\frac{1}{2x^{2}}\log(x^{2} \tilde{v}_1)$, we can write:
\begin{equation}
\label{eq: u1 1}
    u_1(x)=\frac{1}{x^{2}}\frac{1}{\tilde{v}_1-\tilde{v}_1^{-1}}\,.
\end{equation}
Considering now the first equation for $m_{1}=2$, we find:
\begin{equation}
\begin{aligned}
&1 + e^{2 \tilde{f}_{1,1}(x) - 4x^2 g_{1,1}'(x)} \cdot x^8 \left( 
    -3 - x \tilde{f}_{1,1}'(x) + 4x^2 g_{1,1}'(x) + 2x^3 g_{1,1}''(x) 
\right) \\
&+e^{2 \tilde{f}_{1,1}(x) + 4x^2 g_{1,1}'(x)} \cdot \left( 
    -1 + x \tilde{f}_{1,1}'(x) + 4x^2 g_{1,1}'(x) + 2x^3 g_{1,1}''(x) 
\right)=0.
\end{aligned}
\end{equation}
Writing again everything in terms of $u_1$, $\tilde{v}_1$ and solving for the former, we find:
\begin{equation}
\label{eq: u1 2}
    u_1(x)=\frac{1-c_{1}x^{2}}{x^{4}}\frac{1}{\tilde{v}_1^{2}-\tilde{v}_1^{-2}}\,,
\end{equation}
where now the integration constant $c_{1}$ cannot be fixed by requiring $u_1(0)=1$ and $\tilde{v}_1(x)\simeq 1/x^{2}$, i.e. $\tilde{f}_{1,1}(0)=g_{1,1}(0)=0$. Solving the quadratic equation obtained from (\ref{eq: u1 1}) and (\ref{eq: u1 2}), we find:
\begin{equation}
\label{eq: v(x) 1}
    \tilde{v}_1(x)=\frac{1}{2x^{2}} \left( 1 - x^2 c_1 \pm \sqrt{\left(x^2 c_1-1\right)^2-4x^4 } \right).
\end{equation}
In order to satisfy $\tilde{v}_1(x)\simeq 1/x^{2}$, we must chose the plus sign in front of the square root. Then, $c_{1}$ is related to the value of $g_{1,1}'$ at zero by $c_{1}=-2g_{1,1}'(0)$, and by consequence of $\tilde{f}_{1,1}''(0)=-2g_{1}'(0)$, also to the value of $\tilde{f}_{1,1}''$ at zero. To determine $c_{1}$, we can consider the second equation for $m_{1}=1$. Writing $\tilde{f}_{1,1}(x)$ as in equation (\ref{eq: f11}) and $g_{1,1}'(x)$ in terms of $\tilde{v}_1(x)$, using (\ref{eq: v(x) 1}), the resulting equation reads:
\begin{equation}
\label{eq: g1tilde}
\begin{aligned}
&\left(1 - 2 x^2 c_1 + x^4 (c_{1}^{2}-4)\right)^{-2} \bigg\{ x c_1 
+ x^3(4 - 3c_1^2) 
+ 3x^5 c_1 (c_1^2-4) 
- x^7 (c_1^2-4)^2 \\
& + \sqrt{1 - 2x^2 c_1 + x^4 (c_1^2-4)} \cdot \Bigg[
  -4x^3 \left(1 + \log \frac{1}{2} \left( 1 - x^2 c_1 + \sqrt{ (x^2 c_1-1)^2-4x^4 } \right) \right)  \\
& - 8x^4 g_{1,1}(x)+ \left( -1 + 3x^2 c_1 + x^6 c_1 (c_1^2-4) - x^4 (4 + 3c_1^2) \right) \tilde{g}_{1,1}(x) \\
& + x(-1 + x^2(c_1-2))(x^2 c_1-1)(x^2(2 + c_1)-1)  \tilde{g}_{1,1}'(x)
\Bigg]\bigg\}=0.
\end{aligned}
\end{equation}
For simplicity, we do not substitute $g_{1,1}(x)$ yet. We now look at the equation near $x=+\infty$, setting $\tilde{g}_{1,1}(x)=\tilde{k}+O(x^{-1})$, $g_{1,1}(x)=k+O(x^{-1})$. The asymptotic behavior of $g_{1,1}(x)$ is dictated by that of its first derivative, which we just determined up to $c_{1}$, while that of $\tilde{g}_{1,1}(x)$ is dictated by the equation itself. We obtain:
\begin{equation}
\label{eq: integration constant c1}
    \frac{c_{1}\tilde{k}}{\sqrt{c_{1}^{2}-4}}-x^{-1} +\mathcal{O}(x^{-2})=0.
\end{equation}
Clearly, any choice of $c_{1}\neq \pm 2$ will not allow us to solve the equation. Assuming instead $c_{1}^{2}=4$, we see that the proper choice is $c_{1}=-2$, since $c_{1}=2$ would imply that $\tilde{v}_1(x)$ as in (\ref{eq: v(x) 1}) becomes imaginary when $x^{2}>1/4$. In view of the next section, we note here that the correct choice is the one for which the coefficient of $x^{4}$ inside the square root in (\ref{eq: v(x) 1}) vanishes, while also maintaining the function real on the real axis. With this choice, we find:
\begin{equation}
    \tilde{f}_{1,1}(x)=-\frac{1}{4}\log(1+4x^{2}) ,\quad g_{1,1}(x)=- \frac{\log\left( 1/2 + \sqrt{1/4 + x^2} \right) + 1 - \sqrt{1 + 4x^2}}{x},
\end{equation}
and equation (\ref{eq: g1tilde}) for $\tilde{g}_{1,1}(x)$ simplifies to:
\begin{equation}
4x^3 
- 2\sqrt{1 + 4x^2}(x + 4x^3) 
- (1 + 6x^2 + 16x^4)\, \tilde{g}_{1,1}(x) 
- (x + 6x^3 + 8x^5)\, \tilde{g}_{1,1}'(x)=0,
\end{equation}
which we can solve, to obtain:
\begin{equation}
    \tilde{g}_{1,1}(x)=\frac{1-\sqrt{1+4x^{2}}}{2x},
\end{equation}
where the integration constant has been fixed by enforcing $\tilde{g}_{1,1}(0)=0$. Then, having already found $\tilde{g}_{1,1}$, the second equation for $m_{1}=2$ becomes a simple algebraic relation between the Taylor coefficients of the functions for $m_{2}=2$, namely:
\begin{equation}
8 g_{1,2}'(0)+2\tilde{f}_{1,2}''(0)-1=0 \implies\tilde{f}_{1,2}''(0)=\frac{1}{2}-4g_{1,2}'(0),
\end{equation}
which we can use to simplify the next equations. The third equation for $m_{1}=1$ reads:
\begin{equation}
    \begin{aligned}
& 0=\sqrt{1 + 4x^2}-1 
- 2x^2 \left(7 + 6x^2 - 2\sqrt{1 + 4x^2} \right) + 4(1 + 4x^2)^{3/2}  \tilde{f}_{2,1}(x) \\
& + 2x(1 + 4x^2)^{3/2} \tilde{f}_{2,1}'(x) + 8x^2 (1 + 6x^2 + 10x^4)  g_{2,1}'(x) + 2x^2 (1 + 6x^2 + 8x^4)  g_{2,1}''(x),
\end{aligned}
\end{equation}
which we can solve to find:
\begin{equation}
\tilde{f}_{2,1}(x)=- \frac{
  (2 + x^2)\left(-1 - 2x^2 + \sqrt{1 + 4x^2} \right)
  + 4x^4(1 + 2x^2)  g_{2,1}'(x)
}{
  4x^2 \sqrt{1 + 4x^2}
},
\end{equation}
where the integration constant has been fixed by requiring $\tilde{f}_{2,1}(0)=0$. This solution can then be substituted into the third equation for $m_{1}=2$, which simplifies to:
\begin{equation}
    \begin{aligned}
& -1 - 2x^2 + x^4 
- 2(x^4 + 6x^6) g_{2,1}'(x) 
- (x^5 + 4x^7) g_{2,1}''(x) \\
