&+ 240x^7 \left(1523 + 2880\, g_{2,2}'(0) + 1296\, g_{1,2}^{(3)}(0)\right) + 25920x^9 \left(3 + 16\, g_{1,2}^{(3)}(0)\right)\Big]=0.
