\end{equation}
from which we find:
\begin{equation}
\begin{aligned}
&g_{1,3}'(0) = \frac{1}{144},\quad
\tilde{g}_{1,3}'(0) = -\frac{1}{432},\quad 
\tilde{f}_{3,2}''(0) = \frac{14161}{5184} - 4\, g_{3,2}'(0), \\
&\tilde{f}_{2,2}^{(4)}(0) = \frac{16}{3} - 24\, g_{2,2}^{(3)}(0), \quad
\tilde{f}_{1,2}^{(6)}(0) = 15 - 60\, g_{1,2}^{(5)}(0).
\end{aligned}
\end{equation}
As a final summary, the relations we found up until this order read:
\begin{equation}
    \begin{aligned}
& g_{1,2}'(0) = \frac{1}{4},\quad \tilde{g}_{1,2}'(0) = -\frac{1}{8}, \quad \tilde{f}_{1,2}''(0) = -\frac{1}{2},\\
& g_{1,2}^{(3)}(0) = -\frac{3}{16}, \quad \tilde{g}_{1,2}^{(3)}(0) = \frac{3}{16},\quad \tilde{f}_{1,2}^{(4)}(0) = 3,\\
& g_{1,3}'(0) = \frac{1}{144}, \quad \tilde{g}_{1,3}'(0) = -\frac{1}{432},\quad \tilde{f}_{1,3}''(0) = -\frac{1}{72}, \\
