\subsection{Localized filter representation of optimal JFRFT sampling operators}
If we define $h(\mathbf{\Delta}_J)$ as an ideal low-pass filter, i.e., $\boldsymbol{\Sigma}_{\mathcal{F}_J} = h(\mathbf{\Delta}_J)$, then the following holds, $\mathbf{T}^{\alpha,\beta} = \mathbf{J}^{-\alpha,-\beta} h(\mathbf{\Delta}_J) \mathbf{J}^{\alpha,\beta} = \mathbf{J}^{-\alpha,-\beta} \boldsymbol{\Sigma}_{\mathcal{F}_J} \mathbf{J}^{\alpha,\beta} = \mathbf{B}_J^{\alpha,\beta}$. This key operator relationship enables the localization of optimal sampling operators through the joint fractional filtering operator.

\textit{MaxSigMin}: Based on Eq. \eqref{SJ1}, the optimal sampling set can be reformulated using the localization operator
\[
\begin{aligned}
\mathcal{S}_J^{\text{opt}} = &\argmax_{\mathcal{S}_J \subseteq \mathcal{J}}~ \sigma_{\min} \left( \mathbf{J}^{-\alpha,-\beta}_{\mathcal{S}_J \mathcal{F}_J} \right)
= \argmax_{\mathcal{S}_J \subseteq \mathcal{J}}~ \sigma_{\min} \left( \mathbf{J}^{\alpha,\beta}_{\mathcal{F}_J \mathcal{S}_J} \right) \\
= &\argmax_{\mathcal{S}_J \subseteq \mathcal{J}}~ \sigma_{\min} \left( \mathbf{J}^{-\alpha,-\beta} \boldsymbol{\Sigma}_{\mathcal{F}_J} \mathbf{J}^{\alpha,\beta} \mathbf{D}_{\mathcal{S}_J} \right)
= \argmin_{\mathcal{S}_J \subseteq \mathcal{J}}~ \left\| \left( \mathbf{T}^{\alpha,\beta}_{\mathcal{J} \mathcal{S}_J} \right)^{\dagger} \right\|_2,
\end{aligned}
\]
where, $\mathbf{T}^{\alpha,\beta}$ serves as the spectral-domain localization operator. At iteration $m$, the optimal vertex can be selected by
\begin{equation}
y^{\text{opt}} = \argmin_{y \in \mathcal{J} \setminus \mathcal{S}_{J_m}}~ \left\| \left( \mathbf{T}^{\alpha,\beta}_{\mathcal{J}, \mathcal{S}_{J_m} \cup y} \right)^{\dagger} \right\|_2.
\label{y1}
\end{equation}

\textit{MinTrac}: The trace minimization of the covariance matrix (Eq. \eqref{SJ2}) can be equivalently expressed as
\[
\mathcal{S}_J^{\text{opt}} = \argmin_{\mathcal{S}_J \subseteq \mathcal{J}}~ \mathrm{tr} \left[ \left( \mathbf{J}^{\alpha,\beta}_{\mathcal{S}_J \mathcal{F}_J} \mathbf{J}^{-\alpha,-\beta}_{\mathcal{S}_J \mathcal{F}_J} \right)^{-1} \right]
= \argmin_{\mathcal{S}_J \subseteq \mathcal{J}}~ \mathrm{tr} \left[ \left( \mathbf{T}^{\alpha,\beta}_{\mathcal{S}_J} \right)^{-1} \right].
\]
Correspondingly,
\begin{equation}
y^{\text{opt}} = \argmin_{y \in \mathcal{J} \setminus \mathcal{S}_{J_m}}~ \mathrm{tr} \left[ \left( \mathbf{T}^{\alpha,\beta}_{\mathcal{S}_{J_m} \cup y} \right)^{-1} \right].
\label{y2}
\end{equation}

\textit{MinPinv}: Based on Eq. \eqref{SJ3}, the pseudo-inverse criterion can also be localized as
\[
\begin{aligned}
\mathcal{S}_J^{\text{opt}} =
&\argmin_{\mathcal{S}_J \subseteq \mathcal{J}}~ \sum_{i=1}^{K_J} \frac{1}{\sigma_i \left( \boldsymbol{\Sigma}_{\mathcal{F}_J} \mathbf{J}^{\alpha,\beta} \mathbf{D}_{\mathcal{S}_J} \right)} \\
= &\argmin_{\mathcal{S}_J \subseteq \mathcal{J}}~ \left\| \left( \mathbf{T}^{\alpha,\beta}_{\mathcal{J} \mathcal{S}_J} \right)^{\dagger} \right\|_F
=\argmin_{\mathcal{S}_J \subseteq \mathcal{J}}~ \mathrm{tr} \left[ \left( \mathbf{T}^{\alpha,\beta}_{\mathcal{S}_J} \right)^{-1} \right],
\end{aligned}
\label{S3}
\]
with the vertex selection criterion,
\begin{equation}
y^{\text{opt}} = \argmin_{y \in \mathcal{J} \setminus \mathcal{S}_{J_m}}~ \mathrm{tr} \left[ \left( \mathbf{T}^{\alpha,\beta}_{\mathcal{S}_{J_m} \cup y} \right)^{-1} \right].
\label{y3}
\end{equation}

\textit{MaxSig}: From Eq. \eqref{SJ4}, we obtain
\[
\mathcal{S}_J^{\text{opt}} = \argmax_{\mathcal{S}_J \subseteq \mathcal{J}}~ \left\| \mathbf{T}^{\alpha,\beta}_{\mathcal{J} \mathcal{S}_J} \right\|_F = \argmax_{\mathcal{S}_J \subseteq \mathcal{J}}~ \mathrm{tr} \left[ \mathbf{T}^{\alpha,\beta}_{\mathcal{S}_J} \right].
\label{S4}
\]
Accordingly,
\begin{equation}
y^{\text{opt}} = \argmax_{y \in \mathcal{J} \setminus \mathcal{S}_{J_m}}~ \mathrm{tr} \left[ \mathbf{T}^{\alpha,\beta}_{\mathcal{S}_{J_m} \cup y} \right].
\label{y4}
\end{equation}

\textit{MaxVol}: The volume maximization in Eq. \eqref{SJ5} can be rewritten as
\[
\mathcal{S}_J^{\text{opt}} = \argmax_{\mathcal{S}_J \subseteq \mathcal{J}}~ \det \left[ \mathbf{T}^{\alpha,\beta}_{\mathcal{S}_J} \right],
\label{S5}
\]
and its vertex selection counterpart becomes
\begin{equation}
y^{\text{opt}} = \argmax_{y \in \mathcal{J} \setminus \mathcal{S}_{J_m}}~ \det \left[ \mathbf{T}^{\alpha,\beta}_{\mathcal{S}_{J_m} \cup y} \right].
\label{y5}
\end{equation}

