\section{Proof of Theorem 1}
\label{AA}
Suppose $\bm{x} \in \mathbb{C}^{NT}$ satisfies $\mathbf{B}_J^{\alpha,\beta} \bm{x} = \bm{x}$ and $\mathbf{D}_J \bm{x} = \bm{x}$. Then,
\[
\mathbf{B}_J^{\alpha,\beta} \mathbf{D}_J \mathbf{B}_J^{\alpha,\beta} \bm{x}
= \mathbf{B}_J^{\alpha,\beta} \mathbf{D}_J \bm{x}
= \mathbf{B}_J^{\alpha,\beta} \bm{x}
= \bm{x},
\]
showing that $\bm{x}$ is an eigenvector of $\mathbf{B}_J^{\alpha,\beta} \mathbf{D}_J \mathbf{B}_J^{\alpha,\beta}$ associated with eigenvalue 1, and hence $\lambda_{\max} = 1$.

Conversely, assume
\[
\mathbf{B}_J^{\alpha,\beta} \mathbf{D}_J \mathbf{B}_J^{\alpha,\beta} \bm{x} = \bm{x}.
\]
Using the idempotent and Hermitian properties of the projectors, we write
\[
\mathbf{B}_J^{\alpha,\beta} \mathbf{D}_J \mathbf{B}_J^{\alpha,\beta} \bm{x} 
= \mathbf{B}_J^{\alpha,\beta} \mathbf{D}_J  (\mathbf{B}_J^{\alpha,\beta})^{2} \bm{x},
\]
which implies $\mathbf{B}_J^{\alpha,\beta} \bm{x} = \bm{x}$. Then, by the Rayleigh–Ritz theorem, the spectral norm condition
\[
\max_{\bm{x} \neq 0}
\frac{ \bm{x}^* (\mathbf{D}_J \mathbf{B}_J^{\alpha,\beta}) \bm{x} }
{ \| \bm{x} \|^2 } = 1
\]
implies $\mathbf{D}_J \bm{x} = \bm{x}$. Therefore, $\bm{x}$ lies in the intersection of the joint support and frequency subspaces.

Finally, converting back to matrix form yields
\[
\mathbf{B}_G^\beta \mathbf{X} \mathbf{B}_T^\alpha = \mathbf{X}, \quad
\mathbf{D}_G \mathbf{X} \mathbf{D}_T = \mathbf{X}.
\]


\section{Proof of Theorem 2}
\label{AB}
Let $\bm{x} \in \text{BL}_{K_J}(\mathbf{J}^{\alpha,\beta})$, and consider the sampling operator $\mathbf{D}_J$ and the reconstruction operator $\mathbf{R}_J$. Suppose  
\[
\text{rank}(\mathbf{D}_J|_{\text{BL}_{K_J}}) = \text{rank}(\mathbf{R}_J \mathbf{D}_J|_{\text{BL}_{K_J}}) = K_J,
\]  
which ensures that $\mathbf{R}_J$ spans the entire $\alpha,\beta$-bandlimited space $\text{BL}_{K_J}(\mathbf{J}^{\alpha,\beta})$.

Define $\mathbf{O} := \mathbf{R}_J \mathbf{D}_J$. Since both $\mathbf{R}_J$ and $\mathbf{D}_J$ are supported on $\text{BL}_{K_J}(\mathbf{J}^{\alpha,\beta})$, and $\mathbf{D}_J \mathbf{R}_J = \mathbf{I}$ on the image of $\mathbf{D}_J$, we have
\[
\mathbf{O}^2 = \mathbf{R}_J \mathbf{D}_J \mathbf{R}_J \mathbf{D}_J = \mathbf{R}_J (\mathbf{D}_J \mathbf{R}_J) \mathbf{D}_J = \mathbf{R}_J \mathbf{D}_J = \mathbf{O},
\]  
which shows that $\mathbf{O}$ is a projection operator onto $\text{BL}_{K_J}(\mathbf{J}^{\alpha,\beta})$.

Therefore, for any $\bm{x} \in \text{BL}_{K_J}(\mathbf{J}^{\alpha,\beta})$, we have
\[
\bm{x} = \mathbf{O} \bm{x} = \mathbf{R}_J \mathbf{D}_J \bm{x} = \mathbf{R}_J \bm{x}_{\mathcal{S}_J}.
\]



\section{Proof of Theorem 3}
\label{AC}

The reconstruction $\bm{x}' $ can be expressed as
\begin{equation*}
	\begin{aligned}
		\bm{x}' 
		=&\mathbf{T}^{\alpha,\beta}_{\mathcal{J}\mathcal{S}_J} \left( \mathbf{T}^{\alpha,\beta}_{\mathcal{S}_J} \right)^{\dag} \bm{x}_{\mathcal{S}_J} \\
		=& \left[ \mathbf{J}^{-\alpha,-\beta} h\left( \mathbf{\Delta}_J \right) \mathbf{J}^{\alpha,\beta} \right]_{\mathcal{J}\mathcal{S}_J} \left( \left[ \mathbf{J}^{-\alpha,-\beta} h\left( \mathbf{\Delta}_J \right) \mathbf{J}^{\alpha,\beta} \right]_{\mathcal{S}_J} \right)^{\dag} \bm{x}_{\mathcal{S}_J} \\
		=& \mathbf{J}^{-\alpha,-\beta} h\left( \mathbf{\Delta}_J \right) \mathbf{J}^{\alpha,\beta}_{\mathcal{S}_J \mathcal{J}} \left( \mathbf{J}^{-\alpha,-\beta}_{\mathcal{S}_J \mathcal{J}} h\left( \mathbf{\Delta}_J \right) \mathbf{J}^{\alpha,\beta}_{\mathcal{S}_J \mathcal{J}} \right)^{\dag} \bm{x}_{\mathcal{S}_J} \\
		=& \mathbf{J}^{-\alpha,-\beta} h^{\frac{1}{2}} \left( \mathbf{\Delta}_J \right) \left( \mathbf{J}^{-\alpha,-\beta}_{\mathcal{S}_J \mathcal{J}} h^{\frac{1}{2}} \left( \mathbf{\Delta}_J \right) \right)^{\dag} \bm{x}_{\mathcal{S}_J}.
	\end{aligned}
\end{equation*}

This expression can be equivalently reformulated as
\begin{equation}
	\bm{x}' = \mathbf{J}^{-\alpha,-\beta} \left( \frac{h\left( \mathbf{\Delta}_J \right)}{\rho} \right)^{\frac{1}{2}} \left( \mathbf{J}^{-\alpha,-\beta}_{\mathcal{S}_J \mathcal{J}} \left( \frac{h\left( \mathbf{\Delta}_J \right)}{\rho} \right)^{\frac{1}{2}} \right)^{\dag} \bm{x}_{\mathcal{S}_J}, \label{xR}
\end{equation}
where $\rho = \min_{0 \leq i \leq K_J - 1} [h(\mathbf{\Delta}_J)]_{ii}$. When \( i \geq K_J \), the corresponding components of \( \left( h\left( \mathbf{\Delta}_J \right)/\rho \right)^{1/2} \) asymptotically vanish. Under this assumption, the following approximation holds
\begin{equation}
	\left( \mathbf{J}^{-\alpha,-\beta}_{\mathcal{S}_J \mathcal{J}} \left( \frac{h\left( \mathbf{\Delta}_J \right)}{\rho} \right)^{\frac{1}{2}} \right)^{\dag} \approx \left( \frac{h\left( \left[\mathbf{\Delta}_J\right]_{\mathcal{F}_J} \right)}{\rho} \right)^{-\frac{1}{2}} \cdot \left( \mathbf{J}^{-\alpha,-\beta}_{\mathcal{S}_J \mathcal{F}_J} \right)^{\dag}. \label{approximation}
\end{equation}

Substituting \eqref{xR} and \eqref{approximation} yields
\[
\begin{aligned}
	\bm{x}' 
	=& \mathbf{J}^{-\alpha,-\beta}_{\mathcal{J} \mathcal{F}_J} \left( \mathbf{J}^{-\alpha,-\beta}_{\mathcal{S}_J \mathcal{F}_J} \right)^{\dag} \bm{x}_{\mathcal{S}_J} = \mathbf{J}^{-\alpha,-\beta}_{\mathcal{J}} \mathbf{\Sigma}_{\mathcal{F}_J} \mathbf{J}^{\alpha,\beta}_{\mathcal{S}_J \mathcal{J}} \bm{x}_{\mathcal{S}_J} \\
	=&\mathbf{D}_{\mathcal{S}_J} \mathbf{J}^{-\alpha,-\beta}_{\mathcal{J}} \mathbf{\Sigma}_{\mathcal{F}_J} \mathbf{J}^{\alpha,\beta}_{\mathcal{J}} \bm{x}_{\mathcal{S}_J} = \mathbf{D}_J \mathbf{B}^{\alpha,\beta}_J \bm{x}_{\mathcal{S}_J} = \mathbf{R}_J \bm{x}_{\mathcal{S}_J},
\end{aligned}
\]
which completes the proof.


