\section{Conclusion\label{sec:7}}
This paper introduces the first multivariate rough fractional volatility model, proposing a time-reversible multivariate fBm to jointly model a panel of realized volatilities. We develop the moment-based estimation method and investigate its asymptotic properties. We establish theoretical results on optimal forecasts, demonstrating that the multivariate model outperforms its univariate counterpart when correlations are non-zero and Hurst exponents differ across components. Empirically, the model delivers significant efficiency gains in volatility forecasting compared to both univariate and benchmark approaches.

During the preparation of this paper, we became aware of an independent study by \cite{dugo}, which constructs a multivariate fractional Ornstein-Uhlenbeck (mfOU) process. While their work primarily explores probabilistic properties rather than feasible estimation and forecasting, they also motivate their model using the concept of rough volatility. 

Our study opens several promising avenues for future research: (1) Asymmetric forecasting theory—developing a general theoretical framework for forecasting with asymmetry, which could broaden the model’s applicability across different financial contexts. (2) mfOU modelling and forecasting—investigating the modelling and forecasting performance of mfOU processes and assessing their potential practical advantages over existing approaches. (3) Efficient estimation methods—exploring improved estimation techniques, such as maximum likelihood estimation for mfBm, and quantifying the expected efficiency gains relative to current methods. (4) Structural break analysis—extending the model to incorporate change-point detection, as suggested by the regime-switching behavior observed in AAPL’s Hurst exponent, to better identify and interpret structural shifts in volatility dynamics.

\section{Proofs\label{sec:proofs}}
\subsection{Proofs on asymptotic statistics}
\subsubsection{Proof of Theorem \ref{propstat}}
For components $(p,q)\in\{1,\ldots,d\}^2$, the covariance of the $k$th and $j$th increments, $(j,k)\in\{1,\ldots,n\}^2$, of the time-reversible mfBm yields
\begin{align}\label{covincr}\cov\big(\Delta_k B^{(p)},\Delta_j B^{(q)}\big)=\rho_{p,q}\sigma_p\sigma_q\Delta^{H_p+H_q}\gamma_{p,q}(k-j)\,,\end{align}
where the dependence on time, or the lag $l\in\mathds{Z}$, is via the function
\begin{align}\label{gamma}\gamma_{p,q}(l)=\frac12\Big(|l+1|^{H_p+H_q}+|l-1|^{H_p+H_q}-2|l|^{H_p+H_q}\Big)\,.\end{align}
The function is symmetric in the sense that $\gamma_{p,q}(l)=\gamma_{p,q}(-l)$. For the correlation parameters, we use the notation $\rho_{p,p}=1$, for $p=q$. For $p=q$, we further write shortly $\gamma_{p}$ instead of $\gamma_{p,p}$. It holds $\gamma_{p,q}(0)=1$, for any $p,q$. Having Gaussian processes, a crucial ingredient to compute variances and covariances of our statistics, is obtained from the Isserlis' theorem (\cite{isserlis}):
\begin{align}\label{isserlis}\cov\big(\Delta_k B^{(p)}\Delta_j B^{(q)},\Delta_i B^{(r)}\Delta_l B^{(s)}\big)&=\cov\big(\Delta_k B^{(p)},\Delta_i B^{(r)}\big)\cov\big(\Delta_j B^{(q)},\Delta_l B^{(s)}\big)\\
&\notag\quad +\cov\big(\Delta_k B^{(p)},\Delta_l B^{(s)}\big)\cov\big(\Delta_j B^{(q)},\Delta_i B^{(r)}\big),\end{align}
for all $(p,q,r,s)\in\{1,\ldots,d\}^4$ and $(j,k,l,i)\in\{1,\ldots,n\}^4$.
We obtain the following variances of suitably normalized realized volatilities: 
\begin{align*}
\var\Big(\frac{\Delta^{-2H_p}}{\sqrt{n}}\sum_{k=1}^n\big(\Delta_kB^{(p)}\big)^2\Big)&=\frac{\Delta^{-4H_p}}{n}\sum_{1\le k,l\le n}\cov\big(\big(\Delta_kB^{(p)}\big)^2,\big(\Delta_lB^{(p)}\big)^2\big)\\
&\stackrel{\eqref{isserlis}}{=}\frac{\Delta^{-4H_p}}{n}\sum_{1\le k,l\le n}2\cov^2\big(\Delta_kB^{(p)},\Delta_lB^{(p)}\big)\\
&\stackrel{\eqref{covincr}}{=}\frac{2\sigma_p^4}{n}\sum_{1\le k,l\le n}\gamma_p^2(k-l)\\
&=\frac{2\sigma_p^4}{n}\Big(n\gamma_p^2(0)+2\sum_{r=1}^n(n-r)\gamma_p^2(r)\Big)\\
&=2\sigma_p^4\Big(1+2\sum_{r=1}^n\frac{n-r}{n}\gamma_p^2(r)\Big)\,.
\end{align*}
With dominated convergence, we obtain that
\begin{align*}\lim_{n\to\infty} \var\Big(\frac{\Delta^{-2H_p}}{\sqrt{n}}\sum_{k=1}^n\big(\Delta_kB^{(p)}\big)^2\Big)&=2\sigma_p^4\Big(1+2\sum_{r=1}^{\infty}\gamma_p^2(r)\Big)\\
&\stackrel{\eqref{gamma}}{=}\sigma_p^4\Big(2+\sum_{r=1}^{\infty}\Big(|r+1|^{2H_p}+|r-1|^{2H_p}-2|r|^{2H_p}\Big)^2\Big)\,.
\end{align*}
Applying twice the mean value theorem for differentiation with the functions $x\mapsto x^{2H_p}$, and $x\mapsto x^{2H_p-1}$, we find that
\begin{align*}(r+1)^{2H_p}+(r-1)^{2H_p}-2(r)^{2H_p}&=2H_p\big(\xi_r^{2H_p-1}-\xi_{r-1}^{2H_p-1}\big)\\
&=2H_p(2H_p-1)\zeta_r^{2H_p-2}\,,\end{align*}
with some $\xi_r\in(r,r+1),r\in\N$, and $\zeta_r\in(\xi_{r-1},\xi_r)\subset(r-1,r+1)$. This suffices to see (based on a majorant and minorant) that the series $\sum_{r=1}^{\infty}\gamma_p^2(r)$ converges if and only if $H_p\in(0,3/4)$. Similar arguments apply to upcoming series expressions in the proofs. Univariate central limit theorems 
\begin{align*}%\label{cltqv}
\sqrt{n}\Big(\frac{\Delta^{-2H_p}}{n}\sum_{k=1}^n\big(\Delta_kB^{(p)}\big)^2-\sigma_p^2\Big)\stackrel{d}{\rightarrow}\mathcal{N}\Big(0,\sigma_p^4\Big(2+\sum_{r=1}^{\infty}\big(|r+1|^{2H_p}+|r-1|^{2H_p}-2|r|^{2H_p}\big)^2\Big)\Big)\end{align*}
are known to hold in this case by an application of the celebrated limit theorem by \cite{breuermajor} with the Hermite polynomial $x\mapsto x^2-1$ of Hermite rank 2. For its rank, it suffices to see that $\E[(X^2-1)X]= 0$ and $\E[(X^2-1)^2]=2\ne 0$, for a normalized centred normal random variable $X$.

Next, consider lag-2-increments, which equal (telescoping) sums of increments:
\[\Delta_{k,2} B^{(p)}=B_{(k+1)\Delta}^{(p)}-B_{(k-1)\Delta}^{(p)}=\Delta_k B^{(p)}+\Delta_{k+1}B^{(p)},~k\in\{1,\ldots,n-1\}\,.\]
It holds that
\begin{align*}
\cov(\Delta_{k,2} B^{(p)},\Delta_{l,2} B^{(p)})&=\cov(\Delta_k B^{(p)}+\Delta_{k+1}B^{(p)},\Delta_l B^{(p)}+\Delta_{l+1}B^{(p)})\\
&=\Delta^{2H_p}\sigma_p^2\big(2\gamma_p(k-l)+\gamma_p(k+1-l)+\gamma_p(k-l-1)\big)\,
\end{align*}
by linearity. Note the relation $2^{2H_p}=(2\gamma_p(1)+2)$ for the variances. This relation and applying the Isserlis formula directly to lag-2-increments, what is possible, yields a simple computation of the variance
\begin{align*}
&\var\Big(\frac{\Delta^{-2H_p}}{\sqrt{n}}\sum_{k=1}^{n-1}\big(\Delta_{k,2}B^{(p)}\big)^2\Big)=\frac{\Delta^{-4H_p}}{n}\sum_{1\le k,l\le n-1}2\cov^2(\Delta_{k,2} B^{(p)},\Delta_{l,2} B^{(p)})\\
&\quad=\frac{2\sigma_p^4}{n}\Big((n-1)(2+2\gamma_p(1))^2+2\sum_{r=1}^{n-2}(n-1-r)\big(2\gamma_p(r)+\gamma_p(r+1)+\gamma_p(r-1)\big)^2\Big)\\
&\quad=\sigma_p^4\Big(2\cdot 2^{4H_p}\frac{n-1}{n}+4\sum_{r=1}^{n-2}\frac{n-1-r}{n}\big(2\gamma_p(r)+\gamma_p(r+1)+\gamma_p(r-1)\big)^2\Big)\,.
\end{align*}
With dominated convergence and elementary transformations, we obtain that
\begin{align*}\lim_{n\to\infty} \var\Big(\frac{\Delta^{-2H_p}}{\sqrt{n}}\sum_{k=1}^{n-1}\big(\Delta_{k,2}B^{(p)}\big)^2\Big)&=\sigma_p^4\Big(2\cdot 2^{4H_p}+4\sum_{r=1}^{\infty}\big(2\gamma_p(r)+\gamma_p(r+1)+\gamma_p(r-1)\big)^2\Big)\\
&\stackrel{\eqref{gamma}}{=}\sigma_p^4\Big(2\cdot 2^{4H_p}+\sum_{r=1}^{\infty}\Big(|r+2|^{2H_p}+|r-2|^{2H_p}-2|r|^{2H_p}\Big)^2\Big)\,.
\end{align*}
Since we sum over all $k$, and do not only use half of the observations, this is not obvious from the above asymptotics of the realized volatility. A central limit theorem follows analogously as for the realized volatility. For the covariance of both statistics, we use that
\begin{align*}
\cov\big(\Delta_k B^{(p)},\Delta_{l,2} B^{(p)}\big)&=\cov\big(\Delta_k B^{(p)},\Delta_{l} B^{(p)}+\Delta_{l+1} B^{(p)}\big)\\
&=\Delta^{2H_p}\sigma_p^2\big(\gamma_p(k-l)+\gamma_p(k-l-1)\big),~1\le k\le n,1\le l\le n-1\,.
\end{align*}
We derive that
\begin{align*}
&\cov\Big(\frac{\Delta^{-2H_p}}{\sqrt{n}}\sum_{k=1}^n\big(\Delta_k B^{(p)}\big)^2,\frac{\Delta^{-2H_p}}{\sqrt{n}}\sum_{l=1}^{n-1}\big(\Delta_{l,2}B^{(p)}\big)^2\Big)=\frac{\Delta^{-4H_p}}{n}\sum_{\substack{1\le k\le n\\1\le l\le n-1}}2\cov^2\big(\Delta_k B^{(p)},\Delta_{l,2} B^{(p)}\big)\\
&\quad=\frac{2\sigma_p^4}{n}\sum_{\substack{1\le k\le n\\1\le l\le n-1}}\big(\gamma_p(k-l)+\gamma_p(k-l-1)\big)^2\\
&\quad= \frac{2\sigma_p^4}{n}\Big(2(n-1)\big(\gamma_p(0)+\gamma_p(1)\big)^2+\sum_{r=1}^{n-2}(n-r-1)\big(\gamma_p(r)+\gamma_p(r+1)\big)^2+\sum_{r=2}^{n-1}(n-r)\big(\gamma_p(r)+\gamma_p(r-1)\big)^2\Big)\\
&\quad= 4\sigma_p^4\sum_{r=1}^{n-1}\frac{n-r}{n}\big(\gamma_p(r)+\gamma_p(r-1)\big)^2\,,
\end{align*}
such that with dominated convergence 
\begin{align*}&\lim_{n\to\infty} \cov\Big(\frac{\Delta^{-2H_p}}{\sqrt{n}}\sum_{k=1}^n\big(\Delta_k B^{(p)}\big)^2,\frac{\Delta^{-2H_p}}{\sqrt{n}}\sum_{l=1}^{n-1}\big(\Delta_{l,2}B^{(p)}\big)^2\Big)=4\sigma_p^4\sum_{r=1}^{\infty}\big(\gamma_p(r)+\gamma_p(r-1)\big)^2\\
&\quad \stackrel{\eqref{gamma}}{=}\sigma_p^4\sum_{r=1}^{\infty}\Big(|r+1|^{2H_p}+|r-2|^{2H_p}-|r|^{2H_p}-|r-1|^{2H_p}\Big)^2\,.
\end{align*}
If we show for scalar products $\langle \,\cdot,\,\cdot\,\rangle$, with any $\alpha\in\R^2$, that
\begin{align}\label{bicltsc}
\sqrt{n}\Big\langle\alpha,\Big(\frac{\Delta^{-2H_p}}{n}\sum_{k=1}^n(\Delta_k B^{(p)})^2-\sigma_p^2,\frac{\Delta^{-2H_p}}{n}\sum_{k=1}^{n-1}(\Delta_{k,2} B^{(p)})^2-2^{2H_p}\sigma_p^2\Big)^{\top}\Big\rangle\stackrel{d}{\rightarrow}\langle \alpha, Z\rangle\,,
\end{align}
with the bivariate normal
\begin{align*}
Z\sim\mathcal{N}\bigg(\bigg(\begin{array}{c}0 \\[-.25cm] 0\end{array}\bigg),\bigg(\begin{array}{cc}\text{AVAR}_{11}& \text{AVAR}_{12}\\[-.25cm] \text{AVAR}_{12}&\text{AVAR}_{22}\end{array}\bigg)\bigg)\,,
\end{align*}
where
\begin{subequations}
\begin{align}\label{bicltavar1}
\text{AVAR}_{11}&=\sigma_p^4\Big(2+\sum_{r=1}^{\infty}\Big(|r+1|^{2H_p}+|r-1|^{2H_p}-2|r|^{2H_p}\Big)^2\Big) \,,\\
\label{bicltavar2}\text{AVAR}_{12}&=\sigma_p^4 \sum_{r=1}^{\infty}\Big(|r+1|^{2H_p}+|r-2|^{2H_p}-|r|^{2H_p}-|r-1|^{2H_p}\Big)^2\,,\\
\label{bicltavar3}\text{AVAR}_{22}&=\sigma_p^4\Big(2\cdot 2^{4H_p}+\sum_{r=1}^{\infty}\Big(|r+2|^{2H_p}+|r-2|^{2H_p}-2|r|^{2H_p}\Big)^2\Big)\,,
\end{align}
\end{subequations}
the Cram\'{e}r-Wold device implies the bivariate central limit theorem
\begin{align}\label{bicltqv}\sqrt{n}\left(
\begin{array}{c}\frac{\Delta^{-2H_p}}{n}\sum_{k=1}^n(\Delta_k B^{(p)})^2-\sigma_p^2\\ \frac{\Delta^{-2H_p}}{n}\sum_{k=1}^{n-1}(\Delta_{k,2} B^{(p)})^2-2^{2H_p}\sigma_p^2\end{array}\right)\stackrel{d}{\rightarrow} Z\,.
\end{align}
By self-similarity $B_{k\Delta}^{(p)}\stackrel{d}{=}\Delta^{H_p}B_k^{(p)}$, such that (instead of a triangular array) we consider the $\R^2$-valued stationary, mean-zero Gaussian sequence 
\[(X_1,\ldots,X_{n-1}),~\mbox{with}~X_j=\big(X_j^{(1)},X_j^{(2)}\big)^{\top}=\big(\sigma_p(B_{j+1}^{(p)}-B_j^{(p)}),\sigma_p(B_{j+1}^{(p)}-B_{j-1}^{(p)})\big)^{\top}\,,\]
and for $\alpha=(\alpha_1,\alpha_2)^{\top}$ the function $f:\R^2\to\R,f(x,y)=\alpha_1x^2+\alpha_2y^2$. Since Hermite polynomials $H_r,r\in\N$, satisfy $\E[H_{r_1}(X_j^{(1)})H_{r_2}(X_j^{(2)})]=\delta_{r_1,r_2}r_1!c_{12}$, with (covariance) constant $c_{12}$, i.e., zero for $r_1\ne r_2$, and non-zero for $r_1=r_2$, $f$ has Hermite rank 2 in the sense of Eq.\ (2.2) in \cite{arcones}; see \eqref{rank} also. Neglecting the first increment in the first component, which is asymptotically negligible, the limit theorem from \cite{arcones} thus readily yields \eqref{bicltsc} and we conclude \eqref{bicltqv}. A (more direct) proof based on moment generating functions can be worked out similar to Theorem 4 of \cite{kubilius}. We have that
\begin{align*}\hat H_p=\frac{1}{2\log(2)}\log\Big(\frac{T}{S}\Big),~\mbox{with}~S=\frac{\Delta^{-2H_p}}{n}\sum_{k=1}^n(\Delta_k B^{(p)})^2\,,~\mbox{and}~T=\frac{\Delta^{-2H_p}}{n}\sum_{k=1}^{n-1}(\Delta_{k,2} B^{(p)})^2\,.
\end{align*}
From \eqref{bicltqv}, we can therefore derive a central limit theorem for $\hat H_p$ based on the multivariate $\Delta$-method applied to the function $g:\R^2\to\R$, $g(x,y)=\log(y/x)/(2\log(2))$. Since $g\big(\sigma_p^2,2^{2H_p}\sigma_p^2\big)=H_p$, the $\Delta$-method yields
\begin{align*}
\sqrt{n}\big(\hat H_p-H_p\big)
\stackrel{d}{\rightarrow}\mathcal{N}\bigg(0,\big(\nabla g\big(\sigma_p^2,2^{2H_p}\sigma_p^2\big)\big)^{\top}\bigg(\begin{array}{cc}\text{AVAR}_{11}& \text{AVAR}_{12}\\[-.2cm] \text{AVAR}_{12}&\text{AVAR}_{22}\end{array}\bigg)\nabla g\big(\sigma_p^2,2^{2H_p}\sigma_p^2\big)\bigg)\,,
\end{align*}
with $\big(\nabla g(x,y)\big)^{\top}=(-x^{-1},y^{-1})^{\top}/(2\log(2))$, such that
\begin{align*}
&\nabla g\big(\sigma_p^2,2^{2H_p}\sigma_p^2\big)\big)^{\top}\bigg(\begin{array}{cc}\text{AVAR}_{11}& \text{AVAR}_{12}\\[-.2cm] \text{AVAR}_{12}&\text{AVAR}_{22}\end{array}\bigg)\nabla g\big(\sigma_p^2,2^{2H_p}\sigma_p^2\big)\\
&\quad=\frac{1}{4\log^2(2)\sigma_p^4}\Big(\text{AVAR}_{11}-2\cdot2^{-2H_p}\text{AVAR}_{12}+2^{-4H_p}\cdot \text{AVAR}_{22}\Big)\,.
\end{align*}
We conclude with \eqref{bicltavar1}-\eqref{bicltavar3} for $H_p\in(0,3/4)$ that
\begin{align}\label{cltHhat2}
\sqrt{n}\big(\hat H_p-H_p\big)
\stackrel{d}{\rightarrow}\mathcal{N}\big(0,\text{AVAR}_{\hat H_p}\big)\,,
\end{align}
with asymptotic variance as in \eqref{cltHhat}
\begin{align*}
\text{AVAR}_{\hat H_p}&=\frac{1}{4\log^2(2)}\Big(4+\sum_{r=1}^{\infty}\Big(|r+1|^{2H_p}+|r-1|^{2H_p}-2|r|^{2H_p}\Big)^2\\
&\hspace*{2.5cm} +2^{-4H_p}\sum_{r=1}^{\infty}\Big(|r+2|^{2H_p}+|r-2|^{2H_p}-2|r|^{2H_p}\Big)^2\\
&\hspace*{2.5cm}-2\cdot 2^{-2H_p}\sum_{r=1}^{\infty}\Big(|r+1|^{2H_p}+|r-2|^{2H_p}-|r|^{2H_p}-|r-1|^{2H_p}\Big)^2\Big)\,.
\end{align*}
This asymptotic variance depends on $H_p$, but not on $\sigma_p^2$. Based on the expansion
\[\Delta^{2(H_p-\hat H_p)}=\exp\big(2(\hat H_p-H_p)\log(\Delta^{-1})\big)=1+2(\hat H_p-H_p)\log(n)+\mathcal{O}_{\P}\big(n^{-1}\log^2(n)\big)\,,\]
we obtain that
\begin{align*}
&\frac{\sqrt{n}}{\log(n)}\big(\hat\sigma_p^2-\sigma_p^2\big)=\frac{\sqrt{n}}{\log(n)}\Big(\frac{\Delta^{-2H_p}}{n}\sum_{k=1}^n\big(\Delta_k B^{(p)}\big)^2\Delta^{2(H_p-\hat H_p)}-\sigma_p^2\Big)\\
&\quad=\frac{\sqrt{n}}{\log(n)}\Big(\frac{\Delta^{-2H_p}}{n}\sum_{k=1}^n\big(\Delta_k B^{(p)}\big)^2-\sigma_p^2\Big)+2\sqrt{n}\big(\hat H_p-H_p\big)\frac{\Delta^{-2H_p}}{n}\sum_{k=1}^n\big(\Delta_k B^{(p)}\big)^2+\mathcal{O}_{\P}\big(n^{-1/2}\log^2(n)\big)\\
&\quad=2\sqrt{n}\big(\hat H_p-H_p\big)\sigma_p^2+\KLEINO_{\P}(1)\stackrel{d}{\rightarrow}\mathcal{N}\big(0,4\sigma_p^4\text{AVAR}_{\hat H_p}\big)\,,
\end{align*}
by Slutsky's lemma and \eqref{cltHhat2}. This proves \eqref{cltsigmaest} and completes the proof of Theorem \ref{propstat}.


\subsubsection{Proof of Theorem \ref{theostat2}}
For the general, bivariate fBm with asymmetry parameter $\eta_{1,2}=-\eta_{2,1}$, the cross-covariances of increments generalize from \eqref{covincr} to 
\begin{align}\label{covincr2}\cov\big(\Delta_k B^{(1)},\Delta_j B^{(2)}\big)=\big(\rho_{1,2}+\eta_{1,2}\operatorname{sign}{(k-j)}\big)\sigma_1\sigma_2\Delta^{H_1+H_2}\gamma_{1,2}(k-j)\,,\end{align}
for $(j,k)\in\{1,\ldots,n\}^2$, and with $\gamma_{1,2}$ from \eqref{gamma}. Covariances of increments of one component are not affected by the asymmetry. This implies 
\begin{align*}\E\big[\Delta_{k+1} B^{(1)}\Delta_k B^{(2)}-\Delta_{k} B^{(1)}\Delta_{k+1} B^{(2)}\big]&=\E\big[\Delta_{k+1} B^{(1)}\Delta_k B^{(2)}\big]-\E\big[\Delta_{k} B^{(1)}\Delta_{k+1} B^{(2)}\big]\\
&\stackrel{\eqref{covincr2}}{=}\sigma_1\sigma_2\Delta^{H_1+H_2}\gamma_{1,2}(1)\big((\rho_{1,2}+\eta_{1,2})-(\rho_{1,2}+\eta_{2,1})\big)\\
&=2\eta_{1,2}\sigma_1\sigma_2\Delta^{H_1+H_2}\gamma_{1,2}(1)\,,
\end{align*}
with $2\gamma_{1,2}(1)=2^{H_1+H_2}-2$. With a simple bound as $\big(\rho_{1,2}+\eta_{1,2}\operatorname{sign}{(k-j)}\big)^2\le 2(\rho_{1,2}^2+\eta_{1,2}^2)$, the above analysis for the covariation readily yields that
\[\frac{\Delta^{-H_1-H_2}}{n}\sum_{k=1}^{n-1}\Big(\Delta_{k+1} B^{(2)}\cdot \Delta_k B^{(1)}-\Delta_{k+1} B^{(1)}\cdot \Delta_k B^{(2)}\Big)-\eta_{1,2}\sigma_1\sigma_2(2^{H_1+H_2}-2)=\mathcal{O}_{\P}(n^{-1/2})\,.\]
The asymptotics of rescaled realized variances, with increments and lag-2-increments, i.e., the above central limit theorems, imply that
\begin{align*}
\frac{\Delta^{-2H_j}}{n}\sum_{k=1}^{n-1}\big(\Delta_{k,2} B^{(j)}\big)^2-2^{2H_j}\sigma_j^2=\mathcal{O}_{\P}(n^{-1/2}),~j=1,2,\\
\frac{\Delta^{-2H_j}}{n}\sum_{k=1}^{n}\big(\Delta_{k} B^{(j)}\big)^2-\sigma_j^2=\mathcal{O}_{\P}(n^{-1/2}),~j=1,2,
\end{align*}
such that elementary computations yield that 
\[\hat\eta_{1,2}-\eta_{1,2}=\mathcal{O}_{\P}(n^{-1/2})\,.\]
Since we aim to construct an asymptotic test for $\eta_{1,2}=0$ vs.\ $\eta_{1,2}\ne 0$, we work out the central limit theorem for $\hat\eta_{1,2}$ under the null hypothesis that $\eta_{1,2}=0$. Therefore, the following derivation of the asymptotic variance may restrict to covariances \eqref{covincr} instead of \eqref{covincr2}, what simplifies some terms. We deduce that
\begin{align*}
&\var\bigg(\frac{\Delta^{-H_1-H_2}}{\sqrt{n}}\sum_{k=1}^{n-1}\Big(\Delta_{k+1} B^{(2)}\cdot \Delta_k B^{(1)}-\Delta_{k+1} B^{(1)}\cdot \Delta_k B^{(2)}\Big)\bigg)\\
&\quad =\frac{\Delta^{-2(H_1+H_2)}}{n}\sum_{1\le i,j\le n-1}\cov\Big(\Delta_{i+1} B^{(2)} \Delta_i B^{(1)}-\Delta_{i+1} B^{(1)} \Delta_i B^{(2)},\Delta_{j+1} B^{(2)} \Delta_j B^{(1)}-\Delta_{j+1} B^{(1)} \Delta_j B^{(2)}\Big)\\
&\quad =\frac{\sigma_1^2\sigma_2^2}{n}\sum_{1\le i,j\le n-1}\Big(2\big(\gamma_1(i-j)\gamma_2(i-j)+\rho^2\gamma_{1,2}(i+1-j)\gamma_{1,2}(i-j-1)\big)\\
&\hspace*{1.5cm}-\gamma_1(i+1-j)\gamma_2(i-j-1)-\gamma_1(i-j-1)\gamma_2(i+1-j)-2\rho^2\gamma_{1,2}^2(i-j)\Big)\\
&\quad =\sigma_1^2\sigma_2^2\Big(\frac{n-1}{n}\big(2-2\gamma_1(1)\gamma_2(1)-2\rho^2\big(1-\gamma_{1,2}^2(1)\big)\big)\\
&\hspace*{1.5cm}+2\sum_{r=1}^{n-1}\frac{n-1-r}{n}\big(2\gamma_1(r)\gamma_2(r)-\gamma_1(r+1)\gamma_2(r-1)-\gamma_1(r-1)\gamma_2(r+1)\big)\\
&\hspace*{1.5cm}-4\rho^2\sum_{r=1}^{n-1}\frac{n-1-r}{n}\big(\gamma_{1,2}^2(r)-\gamma_{1,2}(r+1)\gamma_{1,2}(r-1)\big)\Big)\,.
\end{align*}
With dominated convergence, we conclude under the null, $\eta_{1,2}=0$, the asymptotic variance
\begin{align}
&\notag\lim_{n\to\infty}n\cdot\var\big(\hat\eta_{1,2}\big)=(2^{H_1+H_2}-2)^{-2}\Big(2\big(1-\gamma_1(1)\gamma_2(1)\big)+2\rho^2\big(\gamma_{1,2}^2(1)-1\big)\\
&\notag\quad-\rho^2\sum_{r=1}^{\infty}\Big(\big(|r+1|^{H_1+H_2}+|r-1|^{H_1+H_2}-2|r|^{H_1+H_2}\big)^2\\
&\notag\hspace*{1cm}-\big(|r+2|^{H_1+H_2}+|r|^{H_1+H_2}-2|r+1|^{H_1+H_2}\big)\big(|r|^{H_1+H_2}+|r-2|^{H_1+H_2}-2|r-1|^{H_1+H_2}\big)\Big)\\
&\notag\quad+\frac{1}{2}\sum_{r=1}^{\infty}\Big(2\big(|r+1|^{2H_1}+|r-1|^{2H_1}-2|r|^{2H_1}\big)\big(|r+1|^{2H_2}+|r-1|^{2H_2}-2|r|^{2H_2}\big)\\
&\notag\hspace*{2cm}-\big(|r+2|^{2H_1}+|r|^{2H_1}-2|r+1|^{2H_1}\big)\big(|r|^{2H_2}+|r-2|^{2H_2}-2|r-1|^{2H_2}\big)\\
&\notag\hspace*{2cm}-\big(|r+2|^{2H_2}+|r|^{2H_2}-2|r+1|^{2H_2}\big)\big(|r|^{2H_1}+|r-2|^{2H_1}-2|r-1|^{2H_1}\big)\Big)\Big)\\
&\hspace*{2cm}=\text{AVAR}_{\hat \eta_{1,2}}\label{avareta}\,.
\end{align}
For the proof of Theorem \ref{theostat2}, we use the asymptotic variance of $\hat\eta_{1,2}$ from \eqref{avareta} and show a central limit theorem. By self-similarity \eqref{selfsim}, it holds that $\big(B_{k\Delta}^{(1)},B_{k\Delta}^{(2)}\big)^{\top}\stackrel{d}{=}\big(\Delta^{H_1}B_k^{(1)},\Delta^{H_2}B_k^{(2)}\big)^{\top}$. To prove asymptotic normality of the numerator in \eqref{etahat}, multiplied with $\Delta^{-H_1-H_2}/\sigma_1\sigma_2$, we apply Theorem 4 from \cite{arcones} to prove asymptotic normality of $\sum_{k=1}^{n-1}f(X_k)$, with the $\R^4$-valued, stationary, mean-zero Gaussian sequence $(X_1,\ldots,X_{n-1})$, with
\[X_j=\big(X_j^{(1)},X_j^{(2)},X_j^{(3)},X_j^{(4)}\big)^{\top}=\big((B_{j}^{(1)}-B_{j-1}^{(1)}),(B_{j}^{(2)}-B_{j-1}^{(2)}),(B_{j+1}^{(1)}-B_{j}^{(1)}),(B_{j+1}^{(2)}-B_{j}^{(2)})\big)^{\top},\]
where the entries are already standardized with variances equal to one, and the function 
\[f:\R^4\to\R,f(x^{(1)},x^{(2)},x^{(3)},x^{(4)})=x^{(1)}\cdot x^{(4)}-x^{(2)}\cdot x^{(3)}\,.\]
It suffices to show that the Hermite rank of $f$ with respect to $X_1$ is 2 to conclude with Theorem 4 from \cite{arcones}. The Hermite rank is defined by
\begin{align}\label{rank}\operatorname{rank}(f):=\inf\Big\{\tau\ge 1|\sum_{j=1}^4l_j=\tau~\text{and}~\E\big[\big(f(X_1)-\E[f(X_1)]\big)\prod_{k=1}^4 H_{l_k}(X_1^{(k)})\big]\ne 0\Big\}\,,\end{align}
with $H_l,l\ge 0$, the Hermite polynomials. We have $\operatorname{rank}(f)>1$, since with $H_1(x)=x$ and $H_0=1$, it suffices to show
\[\E\big[\big(f(X_1)-\E[f(X_1)]\big)X_1^{(k)}\big]=0,~k=1,2,3,4.\]
For all $k=1,2,3,4$, the proof is similar, we consider without loss of generality $k=1$:
\begin{align*}\E\big[\big(f(X_1)-\E[f(X_1)]\big)X_1^{(1)}\big]&=\E\big[\big(X_1^{(1)}\cdot X_1^{(4)}-X_1^{(2)}\cdot X_1^{(3)}-\E[f(X_1)]\big)X_1^{(1)}\big]\\
&=\E\big[(X_1^{(1)})^2\cdot X_1^{(4)}\big]-\E\big[X_1^{(1)}\cdot X_1^{(2)}\cdot X_1^{(3)}\big]=0\,,
\end{align*}
where the last identity follows since $-X_1\stackrel{d}{=}X_1$, tantamount with the (trivial) odd case in Isserlis' theorem. To show $\operatorname{rank}(f)=2$, consider
\begin{align*}&\E\big[\big(f(X_1)-\E[f(X_1)]\big)\,X_1^{(1)}X_1^{(4)}\big]\\
&=\E\big[(X_1^{(1)}\cdot X_1^{(4)})^2\big]-\E\big[X_1^{(1)}\cdot X_1^{(2)}\cdot X_1^{(3)}\cdot X_1^{(4)}\big]-\Big(\E\big[X_1^{(1)}\cdot X_1^{(4)}\big]\Big)^2+\E\big[X_1^{(1)}\cdot X_1^{(4)}\big]\E\big[X_1^{(2)}\cdot X_1^{(3)}\big]\\
&\stackrel{\eqref{isserlis}}{=}1+\Big(\E\big[X_1^{(1)}\cdot X_1^{(4)}\big]\Big)^2-\E\big[X_1^{(1)}\cdot X_1^{(3)}\big]\E\big[X_1^{(2)}\cdot X_1^{(4)}\big]-\E\big[X_1^{(1)}\cdot X_1^{(2)}\big]\E\big[X_1^{(3)}\cdot X_1^{(4)}\big]\\
&=1+\rho^2\gamma_{1,2}^2(1)-\rho^2-\gamma_1(1)\gamma_2(1)\,.
\end{align*}
We make a case differentiation. If $\rho=0$, the above yields $1-\gamma_1(1)\gamma_2(1)>0$. If $H_1=H_2$, we have that $\gamma_1(1)=\gamma_2(1)=\gamma_{1,2}(1)=\gamma(1)$, what yields $(1-\rho^2)(1-\gamma^2(1))>0$. For the other case, it suffices to consider with $H_2(x)=x^2-1$ the expectation
\begin{align*}&\E\big[\big(f(X_1)-\E[f(X_1)]\big)\big(\big(X_1^{(1)}\big)^2-1\big)\big]\\
&\quad\quad=\E\big[(X_1^{(1)})^3\cdot X_1^{(4)}-X_1^{(1)}\cdot X_1^{(4)}+X_1^{(2)}\cdot X_1^{(3)}-(X_1^{(1)})^2\cdot X_1^{(2)}\cdot X_1^{(3)}\big]\\
&\quad\quad=3\E\big[(X_1^{(1)})^2\big]\E\big[X_1^{(1)} X_1^{(4)}\big]-\E\big[  X_1^{(1)} X_1^{(4)}\big]\\ &\quad\quad\quad+\E\big[X_1^{(2)} X_1^{(3)}\big]-2\E\big[X_1^{(1)} X_1^{(2)}\big]\E\big[X_1^{(1)} X_1^{(3)}\big]-\E\big[(X_1^{(1)})^2\big]\E\big[X_1^{(2)} X_1^{(3)}\big]\\
&\quad\quad=2\E\big[X_1^{(1)} X_1^{(4)}\big]-2\E\big[X_1^{(1)} X_1^{(2)}\big]\E\big[X_1^{(1)} X_1^{(3)}\big]\\
&\quad\quad=2\rho\big(\gamma_{1,2}(1)-\gamma_1(1)\big)\,,
\end{align*}
what is non-zero if $\rho\ne 0$, and $H_1\ne H_2$. The central limit theorem for $\hat\eta_{1,2}$, under the null hypothesis $\eta_{1,2}=0$, is hence implied by Slutsky's lemma. Since the map $(\rho,H_1,H_2)\mapsto \text{AVAR}_{\hat \eta_{1,2}}$ is continuous, what can be seen by dominated convergence, Corollary \ref{etatest} is hence implied by the convergence of the normalized realized volatilities in the denominator, continuous mapping for convergence in probability and Slutsky's lemma.

\subsubsection{Proof of Theorem \ref{theostat}}
Consider the variances of suitably normalized realized covariances
\begin{align*}
&\var\Big(\frac{\Delta^{-H_p-H_q}}{\sqrt{n}}\sum_{k=1}^n\Delta_kB^{(p)}\Delta_kB^{(q)}\Big)=\frac{\Delta^{-2(H_p+H_q)}}{n}\sum_{1\le k,l\le n}\cov\big(\Delta_kB^{(p)}\Delta_kB^{(q)},\Delta_lB^{(p)}\Delta_lB^{(q)}\big)\\
&\quad\stackrel{\eqref{isserlis}}{=}\frac{\Delta^{-2(H_p+H_q)}}{n}\sum_{1\le k,l\le n}\Big(\cov\big(\Delta_kB^{(p)},\Delta_lB^{(p)}\big)\cov\big(\Delta_kB^{(q)},\Delta_lB^{(q)}\big)\\
&\hspace*{4.2cm}+\cov\big(\Delta_kB^{(p)},\Delta_lB^{(q)}\big)\cov\big(\Delta_kB^{(q)},\Delta_lB^{(p)}\big)\Big)\\
&\quad\stackrel{\eqref{covincr}}{=}\frac{1}{n}\sum_{1\le k,l\le n}\Big(\sigma_p^2\sigma_q^2\gamma_p(k-l)\gamma_q(k-l)+\rho_{p,q}^2\sigma_p^2\sigma_q^2\gamma_{p,q}^2(k-l) \Big)\\
&\quad=\sigma_p^2\sigma_q^2\Big(\gamma_p(0)\gamma_q(0)+2\sum_{r=1}^n\frac{n-r}{n}\gamma_p(r)\gamma_q(r)+\rho_{p,q}^2\big(\gamma_{p,q}^2(0)+2\sum_{r=1}^n\frac{n-r}{n}\gamma^2_{p,q}(r)\big)\Big)\,,
\end{align*}
such that with dominated convergence, we obtain that
\begin{align*}\lim_{n\to\infty} \var\Big(\frac{\Delta^{-H_p-H_q}}{\sqrt{n}}\sum_{k=1}^n\Delta_kB^{(p)}\Delta_kB^{(q)}\Big)&=
\sigma_p^2\sigma_q^2(1+\rho_{p,q}^2)+2\sigma_p^2\sigma_q^2\sum_{r=1}^{\infty}\gamma_p(r)\gamma_q(r)\\
&\hspace*{2.75cm}+2\rho_{p,q}^2\sigma_p^2\sigma_q^2\sum_{r=1}^{\infty}\gamma_{p,q}^2(r)\,.
\end{align*}
The Hermite rank of $G:\R^2\to\R,G(x,y)=x\cdot y$, defined in general in Eq.\ (2.2) of \cite{arcones} as in \eqref{rank}, is 2. This is checked using that for $(X,Y)^{\top}$ jointly centred normal we have $\E[X^2Y^2]\ne 0$, while $\E[X^2Y]=0$. Therefore, the central limit theorem 
\begin{align*}%\label{cltqv}
\sqrt{n}\Big(\frac{\Delta^{-(H_p+H_q)}}{n}\sum_{k=1}^n\Delta_kB^{(p)}\Delta_kB^{(q)}-\rho_{p,q}\sigma_p\sigma_q\Big)\stackrel{d}{\rightarrow}\mathcal{N}\Big(0,\upsilon\Big)\end{align*}
is implied by \cite{arcones}, where
\begin{align*}\upsilon&=\sigma_p^2\sigma_q^2(1+\rho_{p,q}^2)+\frac{\sigma_p^2\sigma_q^2}{2}\Big(\rho^2_{p,q}\sum_{r=1}^{\infty}\big(|r+1|^{H_p+H_q}+|r-1|^{H_p+H_q}-2|r|^{H_p+H_q}\big)^2\\
&\hspace*{.5cm}+\sum_{r=1}^{\infty}\big(|r+1|^{2H_p}+|r-1|^{2H_p}-2|r|^{2H_p}\big)\big(|r+1|^{2H_q}+|r-1|^{2H_q}-2|r|^{2H_q}\big)\Big)\,.\end{align*}
Based on similar computations, we deduce the asymptotic covariances
\begin{align*}\lim_{n\to\infty} \cov\Big(\frac{\Delta^{-H_p-H_q}}{\sqrt{n}}\sum_{k=1}^n\Delta_kB^{(p)}\Delta_kB^{(q)},\frac{\Delta^{-2H_p}}{\sqrt{n}}\sum_{k=1}^n\big(\Delta_kB^{(p)}\big)^2\Big)&=2\sigma_p^3\sigma_q\rho\Big(1+2\sum_{r=1}^{\infty}\gamma_p(r)\gamma_{p,q}(r)\Big)
\end{align*}
between normalized realized variance and covariance, and between realized variances:
\begin{align*}\lim_{n\to\infty} \cov\Big(\frac{\Delta^{-2H_p}}{\sqrt{n}}\sum_{k=1}^n\big(\Delta_kB^{(p)}\big)^2,\frac{\Delta^{-2H_q}}{\sqrt{n}}\sum_{k=1}^n\big(\Delta_kB^{(q)}\big)^2\Big)&=2\rho^2\sigma_p^2\sigma_q^2\Big(1+2\sum_{r=1}^{\infty}\gamma_{p,q}^2(r)\Big)\,.
\end{align*}
Based on \cite{arcones} and Cram\'{e}r-Wold, analogously as above, we obtain a multivariate central limit theorem
\begin{align}\label{cltmatrix}\sqrt{n}\left(\begin{array}{c}\frac{\Delta^{-2H_1}}{n}\sum_{k=1}^n\big(\Delta_kB^{(1)}\big)^2-\sigma_1^2\\[.1cm] \frac{\Delta^{-2H_2}}{n}\sum_{k=1}^n\big(\Delta_kB^{(2)}\big)^2-\sigma_2^2\\[.1cm] \frac{\Delta^{-(H_1+H_2)}}{n}\sum_{k=1}^n\Delta_kB^{(1)}\Delta_kB^{(2)}-\rho\sigma_1\sigma_2\end{array}\right)\stackrel{d}{\rightarrow}\mathcal{N}\big(0,\operatorname{AV}\big)\,,
\end{align}
with the $(3\times 3)$ asymptotic variance-covariance matrix $\operatorname{AV}$, which contains the above given limiting variances and covariances. Since
\[\hat\rho=\frac{\frac{\Delta^{-(H_1+H_2)}}{n}\sum_{k=1}^n\Delta_kB^{(1)}\Delta_kB^{(2)}}{\sqrt{\frac{\Delta^{-2H_1}}{n}\sum_{k=1}^n\big(\Delta_kB^{(1)}\big)^2\frac{\Delta^{-2H_2}}{n}\sum_{k=1}^n\big(\Delta_kB^{(2)}\big)^2}}\,,\]
we derive \eqref{cltrho} from \eqref{cltmatrix} with the multivariate $\Delta$-method. With the function $h:(x,y,z)^{\top}\mapsto z/\sqrt{xy}$, $\nabla h(x,y,z)=\big(-yz/(2(xy)^{3/2}),-xz/(2(xy)^{3/2}),(xy)^{-1/2}\big)^{\top}$, we obtain
\begin{align*}\text{AVAR}_{\hat \rho}&=\big(\nabla h(\sigma_1^2,\sigma_2^2,\rho\sigma_1\sigma_2)\big)^{\top}\cdot\operatorname{AV}\cdot \nabla h(\sigma_1^2,\sigma_2^2,\rho\sigma_1\sigma_2)\\
&=\frac{\rho^2}{4\sigma_1^4}\operatorname{AV}_{\negthinspace 11}+\frac{\rho^2}{4\sigma_2^4}\operatorname{AV}_{\negthinspace 22}+\frac{\operatorname{AV}_{\negthinspace 33}}{\sigma_1^2\sigma_2^2}+\frac{\rho^2\operatorname{AV}_{\negthinspace 12}}{2\sigma_1^2\sigma_2^2}-\frac{\rho\operatorname{AV}_{\negthinspace 13}}{\sigma_1^3\sigma_2}-\frac{\rho\operatorname{AV}_{\negthinspace 23}}{\sigma_1\sigma_2^3}.
\end{align*}
Inserting the above limiting variances and covariances and simplifying the terms yields \eqref{cltrho}. This finishes the proof of Theorem \ref{theostat}.
