\subsection{Proofs of theoretical results on forecasting}
\subsubsection{Proof of Proposition \ref{forecastprop}}
Consider a multivariate normally distributed random vector
 \[ X = \left(\begin{array}{c}Y\\ Z\end{array}\right)\sim \mathcal{N}\bigg(
      \bigg(\begin{array}{c}\mu_Y\\[-.2cm] \mu_Z\end{array}\bigg), \bigg(\begin{array}{cc}\Sigma_Y & \Sigma_{Y,Z} \\[-.2cm] \Sigma_{Y,Z}^{\top} & \Sigma_Z \end{array}\bigg)\bigg) = \mathcal{N}(\mu, \Sigma),\]
which is $ \R^{d}$-valued with sub-vectors $Y$ taking values in  $ \R^{p}$ and $Z$ taking values in  $ \R^{d-p}$, $p,(d-p)\in\N$,
with marginals $Y \sim\mathcal{N}(\mu_Y, \Sigma_Y)$, $Z\sim \mathcal{N}(\mu_Z, \Sigma_Z)$, where \(\mu_Y \in \R^p\), \(\mu_Z \in \R^{d-p}\), \(\Sigma_Y \in \R^{p \times p}\), \(\Sigma_Z \in \R^{(d-p) \times (d-p)}\) and \(\Sigma_{Y,Z} \in \R^{p \times (d-p)}\). 
In this case, it is well known\footnote{See, for instance, \cite[Proposition 3.13]{eaton}.} that the conditional distribution of $Y$ given $Z=z$ is multivariate normal:
  \begin{align}\label{condexp}
    (Y \mid Z =  z) \sim \mathcal{N}\big(\mu_Y + \Sigma_{Y,Z} \Sigma_Z^{-1} (z -  \mu_Z),\Sigma_Y - \Sigma_{Y,Z} \Sigma_Z^{-1} {\Sigma^{\top}_{Y,Z}}\big).\end{align}
Having a Gaussian process, we apply this general result with $d=3$, $p=1$, to $Y=B_{t+h}^{(1)}$, with $\mu_Y=0$, $\Sigma_Y=\sigma_1^2(t+h)^{2H_1}$, and $Z=(B_t^{(1)},B_t^{(2)})^{\top}$, with $\mu_Z=(0,0)^{\top}$, and 
\[\Sigma_Z=\left(\begin{array}{cc}\sigma_1^2t^{2H_1} & \rho\sigma_{1}\sigma_2t^{2H} \\ \rho\sigma_{1}\sigma_2t^{2H} & \sigma_2^2t^{2H_2} \end{array}\right)\,,\]
with $H$ the cross Hurst exponent from \eqref{mcov}. The determinant 
\[\det(\Sigma_Z)=\sigma_1^2\sigma_2^2(1-\rho^2)t^{4H}\]
depends on $(H_1,H_2)$ only via $H$. We obtain that
\[\Sigma_Z^{-1}=\left(\begin{array}{cc}\big(\sigma_1^2(1-\rho^2)t^{2H_1}\big)^{-1} & -\rho\big(\sigma_1\sigma_2(1-\rho^2)t^{2H}\big)^{-1}  \\ -\rho\big(\sigma_1\sigma_2(1-\rho^2)t^{2H}\big)^{-1} & \big(\sigma_2^2(1-\rho^2)t^{2H_2}\big)^{-1}\end{array}\right)\,,\]
such that with $\Sigma_{Y,Z}=(\sigma_1^2 w(t,h,H_1),\rho\sigma_1\sigma_2 w(t,h,H))$, we obtain
\begin{align*}
\hat B_{t+h|t}^{(1)}&=\Sigma_{Y,Z} \Sigma_Z^{-1} z\\
&=(\sigma_1^2 w(t,h,H_1),\rho\sigma_1\sigma_2 w(t,h,H))\cdot \left(\begin{array}{c}\frac{B_t^{(1)}}{\sigma_1^2(1-\rho^2)t^{2H_1}}-\frac{\rho B_t^{(2)}}{\sigma_1\sigma_2(1-\rho^2)t^{2H}}\\ \frac{B_t^{(2)}}{\sigma_2^2(1-\rho^2)t^{2H_2}}-\frac{\rho B_t^{(1)}}{\sigma_1\sigma_2(1-\rho^2)t^{2H}}\end{array}\right)\,.
\end{align*} 
Computing this product proves \eqref{forecast}. The MSFE equals the conditional variance:
\begin{align*}&\E\Big[\big(\hat B_{t+h|t}^{(1)}-B_{t+h}^{(1)}\big)^2\Big]=\Sigma_Y-\Sigma_{Y,Z} \Sigma_Z^{-1} \Sigma_{Y,Z}^{\top}\\
&=\sigma_1^2\bigg((t+h)^{2H_1}-\frac{1}{1-\rho^2}\cdot\bigg( \frac{(w(t,h,H_1))^2}{t^{2H_1}}+\rho^2\bigg(\frac{2 w(t,h,H_1) w(t,h,H)}{t^{2H}}-\frac{(w(t,h,H))^2}{t^{2H_2}}\bigg)\bigg)\,.\hfill\qed
\end{align*}

\subsubsection{Proof of Proposition \ref{forecastprop2}}
With similar notation as in the proof of Proposition \ref{forecastprop}, we apply \eqref{condexp} with $Y=B_{t+h}^{(1)}$, and $Z=(B_t^{(1)},\ldots, B_t^{(d)})^{\top}$. The main step is to see that the $(d\times d)$ inverse of the covariance matrix $\Sigma_Z$ has entries
\[(\Sigma_Z^{-1})_{ij}=(\Sigma^{-1})_{ij}\,t^{-(H_i+H_j)}~,\,1\le i,j\le d\,.\]
First, $\det(\Sigma_Z)=\det(\Sigma)\cdot t^{2\textstyle\sum_{k=1}^dH_k}$ is verified by induction. For $d=3$, this follows readily with the rule of Sarrus. Then, a Laplace expansion, e.g., with respect to the first row, yields the induction step. Hence, the determinant depends in general only on the sum of all Hurst exponents. This yields for the inverse for $1\le i,j\le d$ that
\begin{align*}\big(\Sigma^{-1}_Z\big)_{ij}&=\frac{1}{\det(\Sigma_Z)}\operatorname{adj}(\Sigma_Z)=\frac{(-1)^{i+j}}{\det(\Sigma_Z)}\det\big((\Sigma_Z)_{-j,-i}\big)\\
&=\frac{(-1)^{i+j}}{\det(\Sigma)}t^{-2\textstyle\sum_{k=1}^dH_k}\det\big((\Sigma)_{-j,-i}\big)\,t^{\textstyle\sum_{k=1}^dH_k(1+\1(k\notin\{H_i,H_j\})}\\
&=(\Sigma^{-1})_{ij}\,t^{-(H_i+H_j)}\,,
\end{align*}
where we write $(\Sigma_Z)_{-j,-i}$ for the $((d-1)\times (d-1))$ matrix obtained from $\Sigma_Z$ by deleting the $j$th row and $i$th column, and $(\Sigma)_{-i,-j}$ analogously. We obtain the result from
\begin{align*}
\hat B_{t+h|t}^{(1)}&=\Sigma_{Y,Z} \Sigma_Z^{-1} \cdot (B_t^{(1)},\ldots, B_t^{(d)})^{\top}\,,\end{align*}
with $\Sigma_{Y,Z}=(\Sigma_{11}w(t,h,H_1),\ldots, \Sigma_{1d}w(t,h,(H_1+H_d)/2))$.\hfill\qed\\

\subsubsection{Proof of Proposition \ref{msedim}}
We use analogous notation as in the previous proofs. Based on similar linear algebra as above, we can prove inductively that $\Sigma^{-1}$ equals
\[\frac{1}{1+(d-2)\rho-(d-1)\rho^2}\left(\begin{array}{ccccc}1+(d-2)\rho&-\rho &-\rho&\ldots&-\rho\\ -\rho&1+(d-2)\rho&-\rho&\ldots&-\rho\\-\rho&\ldots&\ddots&\ldots&-\rho\\-\rho&\ldots&\ldots&1+(d-2)\rho&-\rho\\-\rho&-\rho&\ldots&-\rho&1+(d-2)\rho\end{array}\right).\]
Computing 
\begin{align*}
\big(w(t,h,H_1),\rho w(t,h,(H_1+H)/2),\ldots,\rho w(t,h,(H_1+H)/2)\big)\Sigma_Z^{-1}\left(\begin{array}{c}w(t,h,H_1)\\\rho w(t,h,(H_1+H)/2)\\ \vdots\\ \rho w(t,h,(H_1+H)/2)\end{array}\right)
\end{align*}
and re-using that $\big(\Sigma^{-1}_Z\big)_{ij}=(\Sigma^{-1})_{ij}\,t^{-(H_i+H_j)}$ yields the result.
\hfill\qed\\


\subsubsection{Proof of Proposition \ref{unifracprop}}
Since for $H=H_1=H_2$, it holds that 
\[\E\big[B_sB_t^{\top}\big]=w(t,s-t,H)\cdot \left(\begin{array}{cc}\sigma_1^2 & \rho\sigma_{1}\sigma_2 \\ \rho\sigma_{1}\sigma_2& \sigma_2^2\end{array}\right)\,,\]
the bivariate time-reversible fBm satisfies in this case the equality in distribution $B_t\stackrel{d}{=}A\cdot (W_t^{(1)},W_t^{(2)})^{\top}$, where $W_t^{(1)}$ and $W_t^{(2)}$ are two independent univariate fBms with Hurst exponents $H$, and
\[A= \left(\begin{array}{cc}\sigma_1 & 0 \\ \rho\sigma_2& \sqrt{1-\rho^2}\sigma_2\end{array}\right)~\mbox{with}~AA^{\top}=\left(\begin{array}{cc}\sigma_1^2 & \rho\sigma_{1}\sigma_2 \\ \rho\sigma_{1}\sigma_2& \sigma_2^2\end{array}\right)\,.\]
Since the covariance function uniquely determines the distribution of a centered Gaussian process, the equality is implied by that of the covariance functions. Let us point out that for $H_1\ne H_2$, it is impossible to illustrate $(B_t)$ as a linear transformation of independent fBms, unless all correlations between components of $(B_t)$ directly vanish.

The main step of the proof is now to show that for any $c,d,x,y\in\R$, we have that
\begin{align}\label{h1}(\sigma_1^2\,c,\rho\sigma_1\sigma_2\,c)A^{-\top}\left(\begin{array}{cc}d & 0 \\ 0& d\end{array}\right)A^{-1}\left(\begin{array}{c}x \\ y\end{array}\right)=c\cdot d\cdot x\,.\end{align}
We use the standard notation $A^{-\top}$ for $(A^{-1})^{\top}=(A^{\top})^{-1}$. Since the inverse
\begin{align*}A^{-1}=\left(\begin{array}{cc}\frac{1}{\sigma_1} & 0 \\ -\frac{\rho}{\sigma_1\sqrt{1-\rho^2}}& \frac{1}{\sigma_2\sqrt{1-\rho^2}}\end{array}\right)\,,\end{align*}
of the triangular matrix is easily determined, we obtain that
\begin{align*}&(\sigma_1^2\,c,\rho\sigma_1\sigma_2\,c)A^{-\top}\left(\begin{array}{cc}d & 0 \\ 0& d\end{array}\right)A^{-1}\left(\begin{array}{c}x \\ y\end{array}\right)=\\
&\quad=(\sigma_1^2\,c,\rho\sigma_1\sigma_2\,c)\left(\begin{array}{cc}\frac{1}{\sigma_1} & -\frac{\rho}{\sigma_1\sqrt{1-\rho^2}} \\[.25cm] 0& \frac{1}{\sigma_2\sqrt{1-\rho^2}}\end{array}\right)\left(\begin{array}{cc}\frac{d}{\sigma_1} & 0\\[.25cm] -\frac{d\rho}{\sigma_1\sqrt{1-\rho^2}}& \frac{d}{\sigma_2\sqrt{1-\rho^2}}\end{array}\right)\left(\begin{array}{c}x \\ y\end{array}\right)\\
&\quad=(\sigma_1^2\,c,\rho\sigma_1\sigma_2\,c)\left(\begin{array}{c}\Big(\frac{d}{\sigma_1^2}+\frac{d\rho^2}{\sigma_1^2(1-\rho^2)}\Big)x -\frac{d\rho}{\sigma_1\sigma_2(1-\rho^2)}y\\[.25cm]  -\frac{d\rho}{\sigma_1\sigma_2(1-\rho^2)}x+\frac{d}{\sigma_2^2(1-\rho^2)}y\end{array}\right)\\
&\quad=cd\Big(1+\frac{\rho^2}{1-\rho^2}\Big)x-\frac{cd\rho\sigma_1}{\sigma_2(1-\rho^2)}y-\frac{cd\rho^2}{1-\rho^2}x+\frac{cd\rho\sigma_1}{\sigma_2(1-\rho^2)}y\\
&\quad=cdx\,.
\end{align*}
Consider a forecast based on observations at two time points $t_1$ and $t_2$, being more general than equidistant ones. The covariance matrix $\mathfrak{W}$ of $(W_{t_1}^{(1)},W_{t_1}^{(2)},W_{t_2}^{(1)},W_{t_2}^{(2)})^{\top}$ contains due to the independence of the components four $(2\times 2)$-diagonal blocks:
\[\mathfrak{W}=\left(\begin{array}{cccc}(t_1)^{2H} & 0&w(t_1,t_2,H)&0 \\ 0&(t_1)^{2H} & 0&w(t_1,t_2,H)\\ w(t_1,t_2,H)&0&(t_2)^{2H}&0\\0&w(t_1,t_2,H)&0&(t_2)^{2H}\end{array}\right)\,,\]
and its inverse  $\mathfrak{W}^{-1}$ is of similar block-diagonal form. This and its explicit entries are determined in Lemma \ref{lemmatrix}, but the explicit entries are not required to conclude. Based on the linear transformation
\[(B_{t_1}^{(1)},B_{t_1}^{(2)},B_{t_2}^{(1)},B_{t_2}^{(2)})^{\top}\stackrel{d}{=}\left(\begin{array}{cc}A&0\\0&A\end{array}\right)(W_{t_1}^{(1)},W_{t_1}^{(2)},W_{t_2}^{(1)},W_{t_2}^{(2)})^{\top}\] 
the covariance matrix of $(B_{t_1}^{(1)},B_{t_1}^{(2)},B_{t_2}^{(1)},B_{t_2}^{(2)})^{\top}$ is given by 
\[\left(\begin{array}{cc}A&0\\0&A\end{array}\right)\mathfrak{W}\left(\begin{array}{cc}A^{\top}&0\\0&A^{\top}\end{array}\right)\,.\]
Writing  $\mathfrak{W}^{-1}$ with three $(2\times 2)$-diagonal blocks $D_1$, $D_2$ and $D_{12}$, the inverse covariance matrix of $(B_{t_1}^{(1)},B_{t_1}^{(2)},B_{t_2}^{(1)},B_{t_2}^{(2)})^{\top}$ yields
\[\left(\begin{array}{cc}A^{-\top}&0\\ 0&A^{-\top}\end{array}\right)\left(\begin{array}{cc}D_1&D_{12}\\ D_{12}&D_2\end{array}\right)\left(\begin{array}{cc}A^{-1}&0\\ 0&A^{-1}\end{array}\right)=\left(\begin{array}{cc}A^{-\top}D_1A^{-1}&A^{-\top}D_{12}A^{-1}\\ A^{-\top}D_{12}A^{-1}&A^{-\top}D_2A^{-1}\end{array}\right)\,.\]
Computing the optimal forecast based on the conditional expectation \eqref{condexp}, \eqref{h1} applies to all four blocks in the same way, such that the forecast does not contain the other component. The same $(2\times 2)$-diagonal block structure readily generalizes to arbitrarily many observation times, such that an algebraic induction step only requires an iterated application of \eqref{h1}. The induction hence yields the general result.\hfill\qed\\

To prove Proposition \ref{unifracgen}, we require the following algebraic lemma on inverses of block matrices of a specific form.
\begin{lem}\label{lemmatrix}
A positive definite, symmetric matrix $\mathfrak{W}\in\R^{nd\times nd}$ of the form
\begin{align*}\mathfrak{W}=\left(\begin{array}{cccc}w_{1,1}I_d&w_{1,2}I_d&\ldots&w_{1,n}I_d\\ \vdots& w_{2,2}I_d&\ldots&\vdots\\ \vdots&&\ddots&\\w_{1,n}I_d&w_{2,n}I_d&\ldots&w_{n,n}I_d \end{array}\right),~w_{i,j}\in\R,1\le i,j\le n,\end{align*}
where $I_d$ denotes the $(d\times d)$ identity matrix, has an inverse of the same form, i.e.\ there exist $\tilde w_{i,j}\in\R,1\le i,j\le n$, such that
\begin{align*}\mathfrak{W}^{-1}=\left(\begin{array}{cccc}\tilde w_{1,1}I_d&\tilde w_{1,2}I_d&\ldots&\tilde w_{1,n}I_d\\ \vdots& \tilde w_{2,2}I_d&\ldots&\vdots\\ \vdots&&\ddots&\\ \tilde w_{1,n}I_d&\tilde w_{2,n}I_d&\ldots&\tilde w_{n,n}I_d \end{array}\right).\end{align*}
\end{lem}

We prove the lemma by algebraic induction. For $n=2$, it is simple to verify by matrix multiplication that
\begin{align*}\left(\begin{array}{cc}w_{1,1}I_d&w_{1,2}I_d\\ w_{1,2}I_d&w_{2,2}I_d\end{array}\right)=\frac{1}{w_{1,1}w_{2,2}-w_{1,2}^2}\left(\begin{array}{cc}w_{2,2}I_d&-w_{1,2}I_d\\ -w_{1,2}I_d&w_{1,1}I_d\end{array}\right)\,,\end{align*}
what serves as the induction basis and yields an explicit formula for the one-period setting. If a positive definite, symmetric $\mathfrak{W}\in\R^{nd\times nd}$ is of the above form, write $\mathfrak{W}\in\operatorname{BD}(nd)$. Assume as induction hypothesis that for $\mathfrak{W}_{n-1}\in\operatorname{BD}((n-1)d)$, $n\ge 3$ arbitrary, it holds that  $\mathfrak{W}_{n-1}^{-1}\in\operatorname{BD}((n-1)d)$. To prepare the induction step, write for $\mathfrak{W}_n\in\operatorname{BD}(nd)$:
\begin{align*}\mathfrak{W}_n=\left(\begin{array}{cc}\mathfrak{W}_{n-1}&C\\ C^{\top}&w_{n,n}I_d\end{array}\right)\,,\end{align*}
with $w_{n,n}\in\R$, $C^{\top}=\big(w_{1,n}I_d,\ldots, w_{n-1,n}I_d\big)\in\R^{d\times (n-1)d}$. A general block inversion formula, see Sec.\ 9.3.1 in \cite{matrix}, yields
\begin{align*}\mathfrak{W}_n^{-1}=\left(\begin{array}{cc}\big(\mathfrak{W}_{n-1}-Cw_{n,n}^{-1}I_dC^{\top}\big)^{-1}&-\mathfrak{W}_{n-1}^{-1}C\big(w_{n,n}I_d-C^{\top}\mathfrak{W}_{n-1}^{-1}C\big)^{-1}\\ -\big(w_{n,n}I_d-C^{\top}\mathfrak{W}_{n-1}^{-1}C\big)^{-1}C^{\top}\mathfrak{W}_{n-1}^{-1}&\big(w_{n,n}I_d-C^{\top}\mathfrak{W}_{n-1}^{-1}C\big)^{-1}\end{array}\right)\,.\end{align*}
Since $C$ and $C^{\top}$ consist of $(d\times d)$-diagonal blocks in that $I_d$ is multiplied with real scalars, it follows that $C^{\top}\mathfrak{W}_{n-1}^{-1}C$ is a $(d\times d)$-diagonal matrix of the same form, such that $w_{n,n}I_d-C^{\top}\mathfrak{W}_{n-1}^{-1}C$ and its inverse are as well of this form. Since
\begin{align*}CC^{\top}=\left(\begin{array}{ccc}w_{1,n}^2I_d&\ldots&w_{1,n}w_{n-1,n}I_d\\ &\ddots&\\w_{1,n}w_{n-1,n}I_d&\ldots&w_{n-1,n}^2I_d\end{array}\right)\in\operatorname{BD}((n-1)d)\,,\end{align*}
$\mathfrak{W}_{n-1}-w_{n,n}^{-1}CC^{\top}$, and its inverse, are as well in $\operatorname{BD}((n-1)d)$. $C$ containing $(d\times d)$-diagonal blocks in that $I_d$ is multiplied with real scalars, and since $\mathfrak{W}_{n-1}^{-1}\in\operatorname{BD}((n-1)d)$, $\mathfrak{W}_{n-1}^{-1}C\big(w_{n,n}I_d-C^{\top}\mathfrak{W}_{n-1}^{-1}C\big)^{-1}$ preserves this structure, such that we conclude the induction step $\mathfrak{W}_{n}^{-1}\in\operatorname{BD}((n-1)d)$.


\subsubsection{Proof of Proposition \ref{unifracgen}}
In the general, $d$-dimensional setting with a mfBm $B_t=(B_t^{(1)},\ldots,B_t^{(d)})^{\top}$, with all Hurst exponents being $H\in(0,1)$, it holds that
\[\E\big[B_sB_t^{\top}\big]=w(t,s-t,H)\cdot \Sigma\,,\]
with the static, positive definite variance-covariance matrix $\Sigma\in\R^{d\times d}$ of $(B_1^{(1)},\ldots,B_1^{(d)})^{\top}$. By the spectral theorem, there is a diagonal matrix $\Lambda\in\R^{d\times d}$, with strictly positive entries on the diagonal, and an orthogonal matrix $O\in\R^{d\times d}$, such that
$\Sigma=O\Lambda O^{\top}$ and we set $\Sigma^{1/2}=O\Lambda^{1/2}O^{\top}$, where $\Lambda^{1/2}$ is obtained from $\Lambda$ taking square roots entry-wise. Similar as in the proof of Proposition \ref{unifracprop}, \eqref{mcov} yields an illustration
\begin{align*}B_t\stackrel{d}{=}\Sigma^{1/2}\cdot W_t\,,\end{align*}
with $W_t=(W_t^{(1)},\ldots,W_t^{(d)})^{\top}$ being a vector of $d$ independent fBms with equal Hurst exponents $H$. Considering $t$ observations in a vector $(B_{\Delta}^{(1)},\ldots,B_{\Delta}^{(d)},\ldots,B_{t\Delta}^{(1)},\ldots,B_{t\Delta}^{(d)})^{\top} \in\R^{td}$, this vector has the variance-covariance matrix $\mathfrak{C}\in\R^{td\times td}$ of the form
\begin{align*}\mathfrak{C}=BD_{\Sigma^{1/2}}\cdot \left(\begin{array}{cccc}\Delta^{2H}I_d&w(\Delta,2\Delta,H)&\ldots&w(\Delta,t\Delta,H)\\ w(\Delta,2\Delta,H)&(2\Delta)^{2H}I_d&\ldots&\vdots\\\vdots& &\ddots&\vdots\\w(\Delta,t\Delta,H)&\ldots&\ldots&(t\Delta)^{2H}I_d\end{array}\right)\cdot BD_{\Sigma^{1/2}}\,,\end{align*}
where $I_d$ denotes the $(d\times d)$ identity matrix and $BD_{\Sigma^{1/2}}$ the block-diagonal matrix
\begin{align*}BD_{\Sigma^{1/2}}=\left(\begin{array}{cccc}\Sigma^{1/2}&0&\ldots&0\\ 0&\Sigma^{1/2}&0\ldots&\vdots\\\vdots& &\ddots&0\\0&\ldots&0&\Sigma^{1/2}\end{array}\right)\,.\end{align*}
The inverse $\mathfrak{C}^{-1}\in\R^{td\times td}$, entering the conditional expectation of $B_{t\Delta+h}^{(1)}$, $h>0$, given the $t$ observations at times $j\Delta,1\le j\le t$, is with Lemma \ref{lemmatrix} hence of the form
\begin{align*}\mathfrak{C}^{-1}=\left(\begin{array}{cccc}\Sigma^{-1}c_{1,1}&\Sigma^{-1}c_{1,2}&\ldots&\Sigma^{-1}c_{1,t}\\ \Sigma^{-1}c_{1,2}&\Sigma^{-1}c_{2,2}&\ldots&\vdots\\\vdots& &\ddots&\\\Sigma^{-1}c_{1,t}&\ldots&\ldots&\Sigma^{-1}c_{t,t}\end{array}\right)\,,\end{align*}
with real scalars $c_{i,j}$, $1\le i,j\le t$, which depend on $\Delta$, $H$ and the observation times, but whose explicit values are not important.
With algebraic induction as in the proof of Proposition \ref{unifracprop}, it suffices to conclude block-wise that
\begin{align}\label{h2}c\cdot\Sigma_{1\bullet}\cdot\Sigma^{-1}\cdot d \cdot\left(\begin{array}{c}x_1\\ x_2\\\vdots\\ x_d\end{array}\right)=c\cdot d\cdot x_1\,,\end{align}
for arbitrary $c,d\in\R$, with $\Sigma_{1\bullet}\in\R^{1\times d}$ being the first row of $\Sigma$, entering the conditional expectation of $B_{t\Delta+h}^{(1)}$ given $(B_{\Delta}^{(1)},\ldots,B_{\Delta}^{(d)},\ldots,B_{t\Delta}^{(1)},\ldots,B_{t\Delta}^{(d)})^{\top}$. \eqref{h2} is readily obtained, since
\[\Sigma\cdot \Sigma^{-1}=I_d=\left(\begin{array}{c}\Sigma_{1\bullet}\cdot \Sigma^{-1}\\ \vdots\\ \vdots\end{array}\right)\,.\]
Similar as in the proof of Proposition \ref{unifracprop}, the main ingredient is that $\mathfrak{C}^{-1}$ only contains block matrices of the form $\Sigma^{-1}\cdot d$, $d\in\R$. The equidistant observation scheme, $t_j=j\Delta,1\le j\le t$, is not important for this proof which generalizes to arbitrary observation times.
\hfill\qed
