\begin{tcolorbox}[colback=white,colframe=black,rounded corners]
\textbf{Box 1: Optimal Transport}
\newline

 In the classical discrete optimal transport setting, two discrete mass distributions are given:
\[
 \sum_{i=1}^{n_1} \mu^{(i)}_1\delta_{x^{(i)}_1}, \quad  \sum_{j=1}^{n_2} \mu^{(j)}_2\delta_{x^{(j)}_2}, 
\]
 where the ordered sets $\mathcal{X}_1=(x_1^{(i)})_{i=1}^{n_1}$ and $\mathcal{X}_2=(x_2^{(j)})_{j=1}^{n_2}$ correspond to the points of support of the respective distributions, and where $\mu_1^{(i)}$ and $\mu_2^{(j)}$ represent the mass in the points $x_1^{(i)}$ and  $x_2^{(j)}\!,$ respectively.

\centering
\includegraphics[scale=0.33]{bi-marginal-ot-discrete-new.pdf} 
\captionsetup{width=\linewidth}
\captionof{figure}{Optimal transport finds an optimal assignment between points in two point cloud distributions $\mu_1 \in \mathbb{R}_+^2$ (blue dots) and $\mu_2 \in \mathbb{R}_+^4$ (orange dots). The two distributions $\mu_1$ and $\mu_2$ could for example represent two cell populations. The solution is a matrix, $M\in \mathbb{R}_+^{2\times 4}$, encoding the optimal way to redistribute the mass in $\mu_1$ to form $\mu_2$. The thickness of the black lines in the left plot represents the amount of mass sent between the points in the optimal solution under the squared Euclidean cost (\ref{eq:box_sqeuclidean_cost}). The corresponding transport plan's matrix elements in the right plot can be interpreted as the strength of the association between any pair of points $x_1^{(i)} \in \mathcal{X}_1, x_2^{(j)} \in \mathcal{X}_2$. }

\hfill 
\justify{
A transport plan is a matrix, $M=[m_{ij}]_{i=1, j=1}^{n_1, n_2} \in \mathbb{R}_+^{n_1\times n_2}$, whose component $m_{ij}$ denotes the amount of mass transported from  $x^{(i)}_1 \in \mathcal{X}_1$ to $x^{(j)}_2 \in \mathcal{X}_2$. We say that the transport plan is feasible if the total amounts transported are consistent with the initial and final distributions, i.e., if $M\ones{n_2}=\mu_1$ and $M^T\ones{n_1}=\mu_2$, where $\mu_1 = [\mu_1^{(i)}]_{i=1}^{n_1}$ and $\mu_2 = [\mu_2^{(j)}]_{j=1}^{n_2}$ are the vectors representing the mass distributions.
Let  
\begin{equation} 
\label{eq:box_sqeuclidean_cost}
c_{ij} :=  \lVert x_1^{(i)} - x_2^{(j)} \rVert_2^2
\end{equation}
denote the cost of moving a unit of mass from $x^{(i)}_1$ to $ x^{(j)}_2$\!, and let $C=[c_{ij}]_{i=1, j=1}^{n_1, n_2}$ be the corresponding cost matrix.  }
The optimal transport problem is to find a feasible transport plan that solves
\justify{\begin{subequations}
\begin{align}
  \mathcal{T}(\mu_1,\mu_2) := \underset{M \in \mathbb{R}_+^{n_1\times n_2}}{\text{minimize}}  \quad &\langle C, M  \rangle 
  \\
   \text{subject to} \,\, \quad  &M\ones{n_2} \;\;=\mu_1 \\
   &M^T \ones{n_1} = \mu_2,
   \end{align}
\end{subequations}
where $\langle \cdot, \cdot \rangle$ is the Frobenius inner product. An example of such a problem, together with a corresponding optimal solution, is given in Fig. 1. Note that when $\mu_1$ and $\mu_2$ are probability measures, then $\mathcal{T}(\mu_1,\mu_2)$ defines the Wasserstein-2 metric between $\mu_1$ and $\mu_2$. In practice, it is common to solve an entropy-regularized version of the problem using Sinkhorn algorithms \cite{cuturi2013sinkhorn}, corresponding to coordinate ascent on the dual function \cite{karlsson2017generalized}.}
\end{tcolorbox}
