\begin{ex}\label{paths}
    As already remarked, from a partial order $\le$, we can define a betweenness relation, with $b(p,q,r)$ if $p\neq q \neq r$ and $p\le q \le r$. This implies in particular to set systems, that is $\mathcal{S}\subset \mathcal{P}(V)$, where the latter is the power set of a set $V$. The subset relation in $\mathcal{S}$ then yields the partial order. In particular, if whenever $\rho \subset \sigma \subset V$ and $\sigma \in \mathcal{S}$, then also $\rho \in \mathcal{S}$. the set system defines a simplicial complex. Without that condition, we can consider $\mathcal{S}$ as a hypergraph. There is another way to view a simplicial complex $\mathcal{S}$ as a partially ordered set system, as pointed out in \cite{GLMY}. For a vertex set $V$, we consider a system of  finite paths $(v_{i_0},v_{i_1},\dots, v_{i_n})$. (There may be repetitions, that is, $v_{i_{j+1}}=v_{i_j}$ for some $j$, but for the theory developed in \cite{GLMY}, they turn out to be irrelevant.) When the system contains for any path also all its subpaths, we have a simplicial complex, and a  path is the ordered set of vertices of a simplex. Again, the subpath relation provides us with a partial order, hence a betweenness relation.
    \end{ex}
\bigskip

Here, we want to explore betweenness relations arising from cost functions $c$
satisfying \rf{1}, \rf{2}.
\begin{defi}\label{betdef3}
  Let $(S,c)$ be a set with a finite cost function. 
  $q\neq p,r$ then is between $p$ and $r$ if
  \bel{b1}
  c(p,r)=c(p,q)+c(q,r).
  \qe
\end{defi}


For the example $(I,c)$ of \rf{2a}, then $q$ is between $s$ and $t\in I$ if
\begin{equation*}
   s<q <t.
\end{equation*}
For the example of the circle $(S,c)$, see Example \ref{ex2}, $q$ is between $s$ and $t$ if the
three points are in cyclic order, 
\begin{equation*}
  s<q<t,\quad q<t<s\quad \text{ or } \quad t<s<q.
\end{equation*}
In fact, this looks more natural than the case where we take the usual distance function $d(.,.)$ on the unit circle and say that $q$ is between $p$ and $r$ if $d(p,q)>0, d(q,r)>0$ and $d(p,q)+d(q,r)=d(p,r)$. When $p$ and $r$ are antipodal, then any other point is between them, but if they are not, only the points on some segment of the circle are between them. This becomes even more drastic on spheres of dimension $\ge 2$, again equipped with the standard metric. When $p$ and $q$ are antipodal, again any other point is between them, but if they are not, only the interior points on the unique shortest geodesic arc are between them. \\



\section{Swiftest curves}\label{swift}
We shall now extend the notion of a (shortest) geodesic developed in \cite{JW}
to non-symmetric relations. We shall give the concepts new names, again
derived from classical Greek.\\

We consider cost functions as described in Definition \ref{costfunc}.
\begin{defi}\label{tach}
 For distinct $p,q \in S$, a  \emph{tachistic} (from Greek
 \emph{tachistos} = swiftest) from $p$ to $q$ is a map
$g: J \rightarrow S$ defined on a subset $J$ of an interval $[a,b]$ in ${\R}$
with $a,b \in J$ that satisfies  $g(a) = p$ and $g(b) = q$ and for all $s<t,
s,t \in J$
\bel{33}
c(g(s),g(t))=t-s
\qe
and that cannot be  extended 
to some larger subset of $[a,b]$ as a map with values in $S$ satisfying this
property. 
\end{defi}
It follows from Zorn's Lemma that such   tachistics always exist.
\begin{defi}\label{general}
 For $p,q \in S$, a \emph{chronodesic} (from Greek \emph{chronos} =
  time) from $p$ to $q$ is a
map $g: J \rightarrow S$ defined on a subset $J$ of a compact  interval
$[a,b] \subseteq \R$ with $a,b \in J$ and satisfying the following conditions:
 \begin{itemize}
\item[(C1)] $g(a) = p, \, g(b) = q$, and either
  \begin{itemize}
  \item[(C1a)]  $J=\{a,b\}$ and $c(g(a),g(b))=b-a$\\
    or
  \item[(C1b)]  we can find $t_0=a<t_1<\dots < t_n=b
    \in J$ for some $n\ge 2$ with $c(g(t_{i-1}),g(t_{i}))+c(g(t_{i}),g(t_{i+1}))
    =c(g(t_{i-1}),g(t_{i+1}))\\ =|t_{i+1}-t_{i-1}|$
  for $i=1,\dots , n-1$\\
(that means, $g$ is an tachistic map on any interval $[t_{i-1},t_{i+1}]$, and
$g(t_i)$ is between $g(t_{i-1})$ and $g(t_{i+1})$).
 \end{itemize}
\medskip
\item[(C2)] There does not exist a continuation
$\tilde{g}: \tilde{J} \rightarrow S$ of $g$ to some set $\tilde{J}$ with
$J \subsetneq \tilde{J} \subseteq [a,b]$ with the property (C1b)  into the
same space $S$.
 \end{itemize}
%\medskip
  % \item[ii)] When $x=y$ in the preceding, then $g$ is called a {\it 
  %     closed geodesic}.

  \end{defi}




In the same way that geodesic curves in Riemannian or metric geometric need not be shortest connections between their endpoints, also in non-commutative situations, chronodesics need not be tachistic. For instance, in diagram \eqref{dig}, the path from $p_1$ to $p_4$ via $p_2$ and $p_3$ is not tachistic, because one can get from $p_1$ to $p_4$ with lower cost directly. 






\section{Dress groups}

From a betweenness relation, one can define the \emph{Dress group} \cite{JW}.
\begin{defi}
   For a betweenness relation $b$ on the nonempty set $S$,
the group $\tilde{\F} = \tilde{\F}_S$ is the free group generated by all
symbols $X_{p,q}$ for $p,q \in S$ with $p \neq q$.
Let $\tilde{\K} = \tilde{\K}_S$ denote the smallest {\it normal} subgroup
of $\tilde{\F}_S$ that contains all elements

\medskip

%\centerline{$X_{p,q} \cdot X_{q,p}^{-1}$ for all $p.q \in S$ with $p \neq q$,}

%\medskip

\centerline{$X_{p,r} \cdot X_{q,r}^{-1} \cdot X_{p,q}^{-1}$ whenever $b(p,q,r)$.}

\medskip

Then the -- in general -- {\it noncommutative Dress group}
$\tilde{\T} = \tilde{\T}_S$ is defined as the factor group

\medskip

\centerline{$\tilde{\T}_S = \tilde{\F}_S / \tilde{\K}_S$.}
\end{defi}
We also denote the image of $X_{p,q}$ in this quotient by
$\tilde{T}_{p,q}$. 

A direct consequence is 
\begin{coro}
  If $c: S \times S \rightarrow {\R^+} \cup \{0\}$
is a cost function, then we have a well defined homomorphism
$f: \tilde{\T}_S \rightarrow \R$ given by

\medskip

\centerline{$f(\tilde{T}_{p,q}) := c(p,q)$, where $b(p,q,r)$ holds if
and only if $c(p,r) = c(p,q) + c(q,r)$.}

\end{coro}\qed
\begin{rem}
    When we also want to consider cost functions that can become infinite, we should restrict homomorphisms to the subgroup generated by the images $\tilde{T}_{p,q}$ of those $X_{p,q}$ for which the cost $c(p,q)$ is finite. 
\end{rem}

Next we look at some generalization of {\it metric embeddings}.

\medskip

\begin{defi}Suppose that $S_1$ and $S_2$ are sets with
betweenness relations $b_1$ and $b_2$, respectively.
Then a {\it morphism} $\varphi: (S_1,b_1) \rightarrow (S_2,b_2)$
is a map $\varphi: S_1 \rightarrow S_2$ satisfying

\medskip

\centerline{whenever $b_1(p,q,r),$ then
$b_2(\varphi(p),\varphi(q),\varphi(r))$.}
\end{defi}

From the definitions, we conclude at once
\begin{satz}\label{W.2}
  Whenever $\varphi: (S_1,b_1) \rightarrow (S_2,b_2)$
is a morphism between sets with bet\-weenness relations, then $\varphi$
induces a canonical homomorphism
$\psi: \tilde{\T}_{S_1} \rightarrow \tilde{\T}_{S_2}$.
\end{satz}
\qed\\


For any nonempty set $S$ with a betweenness relation $b$, we have of
course a canonical epimorphism $\pi$ from the group $\tilde{\T}_S$
onto the commutative group ${\T}_S$ as studied in
\cite{JW}.
\newline
If, in particular, $S$ is a metric space with a metric $d$, then by
Proposition 3.6 in \cite{JW} (which is strongly related to Proposition \ref{W.2}
above) we have also a well defined homomorphism $f$
from ${\T}_S$ into the field of real numbers given by
$f(T_{a,b}) := d(a,b)$.
\newline
By combining these last two mentioned facts, we obtain at once

\medskip

\begin{satz} For any metric space $(S,d)$ we get a composed
homomorphism $f \circ \pi$:

\medskip

\centerline{$\tilde{\T}_S \rightarrow {\T}_S \rightarrow {\R}.$}

\end{satz}

\begin{rem} Note that ${\T}_S$ is -- in general -- {\it not}
the abelianization one gets by starting from $\tilde{\T}_S$.\newline
If, for instance, $S = \{s,t\}$ contains only two -- different --
elements, then there does not exist any betweenness relation
between these elements, whence $\tilde{\T}_S$ is -- by definition --
the free group generated by $2$ elements. --Its abelianization
is isomorphic to ${\Z}^2$. However, since $T_{s,t} = T_{t,s}$ holds
in the commutative Dress group ${\T}_S$, this group is the infinite
cyclic group -- and, hence, isomorphic to ${\Z}$.
\end{rem}
\medskip

\noindent
{\bf Conventions:} Suppose that $S$ is a -- finite or infinite --
set with at least $2$ elements and a betweenness relation $b$.\newline
Then ${\Z}^S$ is -- as usual -- the set of {\it all} maps from $S$
into ${\Z}$, while we denote by ${\Z}^S_{fin}$ the set all of these maps $f$
of {\it finite support}; that means, there are only finitely many elements
$s \in S$ with $f(s) \neq 0$.\newline
Moreover, for $s \in S$, the map ${\delta}_s$ signifies the map
with ${\delta}_s(s) = 1$ and ${\delta}_s(t) = 0$ for all $t \neq s$.
Then, all of these maps ${\delta}_s$ build a base of the free
${\Z}-$ module ${\Z}^S_{fin}$.\newline
Moreover, put
\begin{equation}
    {\G}_0 := \{\sum_{s \in S} \, n_s \cdot {\delta}_s
\in {\Z}^S_{fin} \, | \, \sum_{s \in S} \, n_s = 0\}.
\end{equation}

We can now prove the following

\medskip
\begin{satz}\label{W.8}
    Assume that the set $S$ has at least $2$
elements and that $S$ is equipped with a betweenness relation $b$.
Then we have a well defined homomorphism
$\psi: \tilde{\T}_S \rightarrow {\G}_0$ given by
\begin{equation}
    \psi(\tilde{T}_{s,t}) := {\delta}_t - {\delta}_s.
\end{equation}

Moreover, $\psi$ is surjective -- and, hence, an epimorphism.
If we thus denote by ${\K}_0$ the kernel of $\psi$, we get
\begin{equation}
    \tilde{\T}_S / {\K}_0 \, \simeq \, {\G}_0.
\end{equation}
\end{satz}
\begin{proof}
Clearly, the images of the homomorphism $\psi$ lie in ${\G}_0$,
whence $\psi$ is well defined -- by the definition of $\tilde{\T}_S$.
The only remaining nontrivial fact is that $\psi$ is surjective.
\newline
Suppose that $g := \sum_{s \in S} \, n_s \cdot {\delta}_s$ lies in ${\G}_0$.
We must prove that $g \in \psi(\tilde{\T}_S)$.\newline
We proceed by induction on $N := \sum_{s \in S} \, |n_s|$ (or, if one formally
prefers, by the half of this sum $N$).\newline
If $N = 0$, then $g$ is the neutral element in ${\G}_0$, whence
$g = \psi(1)$.\newline
Now assume that $N > 0$. Then, in view of $g \in {\G}_0$, there exist
elements $s,t \in S$ with $n_s < 0$ and $n_t > 0$.\newline
Put $g' := g + {\delta}_s - {\delta}_t$. By the induction hypothesis,
there exists an element $\tilde{T}' \in \tilde{\T}_S$ with
$\psi(\tilde{T}') = g'$. If we now put
$\tilde{T} := \tilde{T}' \cdot \tilde{T}_{s,t}$, we get
$\psi(\tilde{T}) = g$ as claimed.
\end{proof}
\bigskip
\begin{rem}
     Clearly, the ${\Z}-$module ${\G}_0$ does not
depend on the betweenness relation $b$, while the kernel ${\K}_0$
heavily depends on $b$. For any three pairwise distinct elements
$p,q,r \in S$ one has
\begin{equation}
    \tilde{T} :=
\tilde{T}_{p,r} \cdot \tilde{T}_{q,r}^{-1} \cdot \tilde{T}_{p,q}^{-1} \in {\K}_0\ ,
\end{equation}
but this product is -- in general -- only the neutral element if $b(p,q,r)$
holds.\newline
Proposition \ref{W.8} suggests to study ${\K}_0$ exhaustively.

\medskip

In \cite{DW}, we have studied a conspicuous subgroup of the Tutte group of a matroid -- called
the {\it inner Tutte group} -- which has properties
very similar to those of ${\K}_0$.
\end{rem}

\bigskip

\begin{lemma}\label{embedding}
Suppose that $X_1,...,X_n$ are certain -- pairwise distinct --
indeterminates and that $(X_i)_{i \in I}$ are further pairwise
distinct indeterminates, different from $X_1,...,X_n$.\newline
Consider the free group $G$ generated by all $X_1,...,X_n$
as well as the group $H$ generated by all $X_k, 1 \leq k \leq n$
and all $X_i, i \in I,$ and certain relations $X_i = f_i(X_1,...,X_n)$,
where each $f_i(X_1,...,X_n)$ is a product of certain powers
of the elements $X_1,...,X_n$ -- with positive or negative
exponents. Then the groups $G$ and $H$ are isomorphic.
More precisely, two inverse isomorphisms $g: G \rightarrow H$
and $h: H \rightarrow G$ are given by

\medskip

\centerline{$g(X_k) := X_k$ for $1 \leq k \leq n$,}

\medskip

\centerline{$h(X_k) := X_k$ for $1 \leq k \leq n, \,
h(X_i) := f_i(X_1,...,X_n)$ for $i \in I$.}

\end{lemma}
\begin{proof} Clearly, by the definitions, we have
$h(g(X_k)) = X_k$ and $g(h(X_k)) = X_k$ for all $k$ with $1 \leq k \leq n$.
\newline
Moreover, for $i \in I$ we have 

\medskip

\centerline{$g(h(X_i)) = (g \circ f_i)(X_1,...,X_n) = f_i(X_1,...,X_n) = X_i$}

\medskip

as claimed, where the second equation holds by the assumptions about the
functions $f_i$ -- and the definition of $g$.
\end{proof}

