\medskip

\centerline{$\tilde{T}_{w_k,w_{k+d}} =
{\Pi}_{1 \leq j \leq d} \,\, 
\tilde{T}_{w_{k+j-1},w_{k+j}}$}

\medskip

for $2 \leq d \leq n-1$ and $k+d$ mod $n$.\newline
