Next, we overview our $(2k,2\alpha)$-hybrid algorithm that either finds a $C_{\leq 2k}$ or determines that $g> 2\alpha$ in $\Ot((\frac{k+1}{\alpha-1}+\alpha) \cdot m^{1+\frac{\alpha-1}{k+1}} )$ time. 
To determine that  $g\geq 2\alpha$, we can check for every $v\in V$ if $v$ is on a $C_{\leq 2\alpha}$.
If $v$ is on a $C_{\leq 2\alpha}$, then all the vertices and edges of this $C_{\leq 2\alpha}$ are at distance at most $\alpha$ from $v$.
If, for every $v\in V$, 
the number of edges at distance at most $\alpha$ is  $O(deg(v)\cdot m^{\frac{\alpha-1}{k+1}})$ 
then 
using standard techniques we can check for every $v\in V$ if $v$ is on a $C_{\leq 2\alpha}$ in $O(m^{1+\frac{\alpha-1}{k+1}})$ time.
However, this is not necessarily the case, and the region at  distance at most $\alpha$ from some vertices might be dense. 
To deal with dense regions within the promised running time  we develop  an iterative sampling procedure (see $\BFSSampleM$ in Section~\ref{sec:one-alg}), whose goal is to sparsify the graph, or to return a $C_{\leq 2k}$.
One component of the iterative sampling procedure is a generalization of our new cycle searching technique mentioned above.
In the generalization instead of checking whether a vertex $s$ and its neighbors are on a $C_{\leq 2k}$, we check whether all the vertices up to a  possibly further distance from $s$ are on a $C_{\leq 2\alpha}$, for $\alpha\leq k$, and if not we mark them so that they can be removed later.  

If the  iterative sampling procedure ends without finding a   $C_{\leq 2k}$ then there are two possibilities. 
Let $r=(k+1) \bmod (\alpha -1)$.
If $r=0$ then it holds that 
the number of edges at distance at most $\alpha$ from every $v\in V$ is  $O(deg(v)\cdot m^{\frac{\alpha-1}{k+1}})$, whp, as required.
If $r>0$ then 
it holds that 
the number of edges at distance at most $r$ from every $v\in V$ is  $O(m^{\frac{r}{k+1}})$, whp.
This does not necessarily imply that the graph is sparse enough for checking whether $g>2\alpha$.
In this case, we run another algorithm (see $\HandleReminderM$ in Section~\ref{sec:one-alg}) that continues to sparsify the graph until 
the number of edges at distance at most $\alpha$ from every $v\in V$ is  $O(deg(v)\cdot m^{\frac{\alpha-1}{k+1}})$
and 
checking whether $g>2\alpha$ is possible within the required running time of $O(m^{1+\frac{\alpha-1}{k+1}})$.








\section{Preliminaries}
\label{sec:prelim}

Let $G=(V,E)$ be an unweighted undirected graph  with $n$ vertices and $m$ edges. 
Let $U\subseteq V$ be a set of vertices and let $G\setminus U$  be the graph obtained from $G$ by deleting all the vertices of $U$ together with their incident edges. 
For two graphs $G=(V,E)$ and $G'=(V',E')$, let $G \setminus G'$ be $G\setminus V'$. We say that $G \subseteq G'$ if $V\subseteq V'$ and $E \subseteq E'$. For convenience, we use both $u \in V$ and $u\in G$ to say that $u \in V$.
For every $u,v \in V$, let $d_G(u,v)$
be the length of a shortest path between $u$ and $v$ in $G$. 
The \emph{girth} $g$ of $G$ is the length of a shortest cycle in  $G$. 
Let $\wt(C)$ be the length of a cycle $C$. 
For an integer $\ell$, we denote a cycle of length (at most) $\ell$ by ($C_{\leq \ell}$) $C_\ell$.\footnote{Both $C_{\ell}$ and $C_{\leq \ell}$ might  not be simple cycles. However, the cycles that our algorithms return are simple.}
Let $E(v)$ be the edges incident to $v$ and $E(v,i)$ the $i$th edge in $E(v)$. 
Let $deg_{G}(v)$ be the degree of $v$ in $G$.
Let $N(v)$ be the set of neighbors of $v$, namely $N(v) = \{w \mid (v,w)\in E\}$.
For an edge set  $S$, let 
$V(S)$ be the endpoints of $S$'s edges, that is, 
$V(S)=\{u\in V \mid \exists (u,v)\in S\}$.
Let $e=(u,v)\in E$ and $w\in V$. The distance $d_G(w,e)$ between $w$ and $e$  is $\min\{ d_G(w, u), d_G(w,v) \} + 1$.
For every $u\in V$ and a real number $k$ 
let $B(G,u,k) =(V_u^k(G),E_u^k(G))$ be the 
\emph{ball graph} of $u$, where $V_u^k(G)=\{ v\in V\mid d_G(u,v)\leq k\}$ and $E_u^k(G)=\{e\in E \mid d_G(u,e)\leq k\}$~\cite{kadria2022algorithmic}.\footnote{When the graph is clear from the context, we sometimes omit $G$ from the notations.} 



We now turn to  present several  essential tools  that are required in order to obtain our new algorithms.
We first restate an important property of the ball graph $B(v, R)$. 


\begin{lemma}[\cite{kadria2022algorithmic}] \label{L-not-part-of}
Let  $0\leq t \leq R$ be two integers and let $v\in V$. If $B(v, R)$ is a tree then  no vertex in $V_v^{R-t}$  is part of a cycle of length at most $2t$ in $G$.

\end{lemma}



We  use procedure  $\BallOrCycle(G,v,R)$ \cite{kadria2022algorithmic,lingas2009efficient} (see Algorithm~\ref{A-BallOrCycle-modified}) that  searches for a $C_{\leq 2R}$  in the ball graph $B(v,R)$.
We summarize the properties of $\BallOrCycle$ in the next lemma.

\begin{algorithm2e}[t]
    \caption{$\BallOrCycle(G,v,R)$ \cite{kadria2022algorithmic,lingas2009efficient}}
    \label{A-BallOrCycle-modified}
    $Q \gets$ a queue that contains $v$ with $d(v)=0$\;
      \While{$Q \neq \emptyset$}{
      $u \gets  dequeue(Q)$\; 

      $V_v^R  \gets V_v^R \cup \{u\}$\; 

      $i \gets 1$\;
      \While{$(i\leq |E(u)|) \codeAnd d(u)+1\leq R$}{
            $(u,w)\gets E(u,i)$\;
            \If{$w\in Q$}{
                \Return $\codeNull$, $P(LCA(u,w),u)\cup \{ (u,w) \} \cup P(LCA(u,w),w)$\footnotemark\;
            }
            $Q \gets Q \cup \{ w \}$ with $d(w) = d(u)+1$\;


            $i \gets i +1$\;
          }

      }
      \Return 
      $V_v^R$, $\codeNull$\;
\end{algorithm2e}

\footnotetext{$LCA(u,w)$ is the least common ancestor of $u$ and $w$ in the tree rooted at $v$ before the edge $(u,w)$ was discovered. $P(x,y)$ is the path in this tree between $x$ and $y$.}


\begin{lemma}[\cite{kadria2022algorithmic}] \label{L-BallOrCycle}
Let $v\in V$. If the ball graph $B(v,R)$ is not a tree then 
% procedure 
\mbox{\rm $\BallOrCycle(G,v,R)$} returns a  $C_{\leq 2R}$ from $B(v,R)$. 
If $B(v,R)$ is a tree then \mbox{\rm $\BallOrCycle(G,v,R)$} returns $V_v^R$.\footnote{If $V_v^R$ is returned then we assume that $V_v^R$ is ordered by the distance from $v$, and for every $u \in V_v^R$ we  store $d(u,v)$ with $u$. Thus, given the set $V_v^R$, we can find $V_v^{R'}$ for every $R'<R$ in $O(|V_v^{R'}|)$ time.}
The running time of  $\BallOrCycle(G,v,R)$ is $O(|V_v^R|)$.
\end{lemma}


Next, we obtain a simple $t$-hybrid algorithm, called $\dHybrid$, using 
$\BallOrCycle$. $\dHybrid$ (see Algorithm~\ref{A-dHybrid}) gets a graph $G$ and an integer $t\geq 2$, and runs $\BallOrCycle(v,t)$ from every  $v\in G$ as long as no cycle is found by $\BallOrCycle$. If $\BallOrCycle$ finds a cycle then $\dHybrid$ stops and returns that cycle. If no cycle is found then $\dHybrid$ returns $\codeNull$. We prove the next Lemma.
% The pseudo-code appears in Algorithm~\ref{A-dHybrid}.

 \begin{algorithm2e}[t]
    \caption{$\dHybrid(G,t)$} \label{A-dHybrid}
	\ForEach{$v\in V$}{
	    $(V_v^{t},C) \gets \BallOrCycle(v, t)$\;
	        \lIf {$C\neq \codeNull$}{\Return $C$}
	}
	\Return $\codeNull$\;
\end{algorithm2e}



\begin{lemma}
\label{L-dHybrid-properties} 
    $\dHybrid(G,t)$ either finds a $C_{\leq 2t}$ or determines that $g>2t$, in $O(\sum_{v\in V}|V_v^t|)$ time.
\end{lemma}

\begin{proof}
By Lemma~\ref{L-BallOrCycle}, if $\BallOrCycle(u,t)$ returns a cycle $C$ then  $\wt(C)\leq 2t$. 
Also by Lemma~\ref{L-BallOrCycle}, if $\BallOrCycle(u,t)$ does not return a cycle then the ball graph $B(u,t)$ is a tree, and specifically $u$ is not part of a $C_{\leq 2t}$ in $G$.
Therefore, if no cycle was found during any of the calls then all the vertices in $G$ are not part of a $C_{\leq 2t}$ in $G$. Hence, $G$ does not contain a $C_{\leq 2t}$, and we get that $g > 2t$.
By Lemma~\ref{L-BallOrCycle}, the running time of $\BallOrCycle(v,t)$ is $O(|V_v^t|)$, which is $O(\sum_{v\in V}|V_v^t|)$ in total.
\end{proof}

We now show that if the input graph satisfies a certain sparsity property then the running time of $\dHybrid(G,t)$ can be bounded as follows.

\begin{corollary}
\label{C-dHybrid-sparse-time}
If $|E_u^{t-1}| < D^{t-1}
% \red{m^{\frac{t-1}{k+1}}}
$ for every $u\in V$ then $\dHybrid(G,t)$ runs in $O(mD^{t-1})$ time. 
\end{corollary}

\begin{proof}
For every $u\in V$, we have $O(|V_v^{t}|) \leq 
    O(|E_v^{t}|) \leq 
    O(\sum_{u \in N(v)} |E_{u}^{t-1}|) 
    $, which is at most 
    $ 
    O(\sum_{u \in N(v)} D^{t-1}) =
    O(deg(v)\cdot  D^{t-1})$.
   Thus, by Lemma~\ref{L-dHybrid-properties}, the running time of $\dHybrid(G,t)$ is 
   $O(\sum_{v\in V}|V_v^t|)
   \leq 
   O(\sum_{v\in V}deg(v)\cdot  D^{t-1}) = O(m  D^{t-1})$.    
\end{proof}




Next, we present procedure $\IsDense(G,w,T,r)$ from \cite{kadria2022algorithmic}. 
$\IsDense$ (see Algorithm~\ref{A-Dense}) gets 
% as an input
a graph $G$, a vertex $w$, a budget $T \geq 1$ (real) and a distance $r\geq 0$ (integer). 
 In the procedure a BFS is executed from $w$. The BFS   counts the edges that are scanned as long as their total number is less than $T$ and the
farthest vertex from $w$ is at distance at most $r$.
% The pseudo-code of $\IsDense$  is presented in Algorithm~\ref{A-Dense}.


\begin{algorithm2e}[t]
    \caption{$\IsDense(G,w,T,r)$ \cite{kadria2022algorithmic}} 
    \label{A-Dense}
    $T'\gets 0$, $\ell_c \gets 1$, $\ell_n \gets 0$, $j\gets 0$\;
    $Q \gets \{w \}$\; 
    \While{$\big(Q\text{ is not empty }\big) \codeAnd \big( j < r\big) \codeAnd \big( T'< T\big)$}{
	    $u \gets dequeue(Q)$\;
	    $\ell_c \gets \ell_c - 1$, $i \gets 1$\;
     	\While{\big($i\leq |E(u)|\big)  \codeAnd \big( T'< T$\big)}{
     	    $(u,v)\gets E(u,i)$\;
     	    remove $(u,v)$ from $E(v)$\;
     	    $T'\gets T'+1$\;
      		\If{$v$ is not marked}{
      		    $Q \gets Q \cup \{ v \}$, mark $v$, $\ell_n \gets \ell_n +1$\;
		    }
		$i \gets i +1$\;
      	}
	\If{$\ell_c  = 0$}{
	    $\ell_c \gets \ell_n$, $\ell_n\gets 0$\;
	    $j \gets j+1$\;
	}
}

\lIf{$\big(T' \geq T \big)
% \red{\codeOr \big( T=1 \codeAnd r=0 \big)}
$
}{\Return $\codeYes$}
\lElse{\Return $\codeNo$}
\end{algorithm2e}

