Given a vertex $v$ and a distance $R$ we sometimes want to bound 
$|E_{v}^{R}|$. Therefore, we adapt a lemma and a corollary of \cite{kadria2022algorithmic} from vertices to  edges.

\begin{lemma}\label{L-SumOfDenseM}
Let $x,y$ be positive integers, let $D\geq 1$ be a real number, and let $w\in V$.
If $|E_w^{x}| < D^{x}$, and $|E_u^{y}| < D^{y}$ for every $u\in V$, then $|E_w^{x+y}| < D^{x+y}$. 
\end{lemma}

\begin{proof}
Let $w\in V$ and assume that  $|E_w^{x}| < D^{x}$. 
We also know that $|E_u^{y}| < D^{y}$, for every $u\in V$. 
We denote $L = V_w^{x}\setminus \{w\}$. 
If $L = \emptyset$ then $|E_w^{x}| = |E_w^{x+y}| = 0 \leq D^{x+y}$ as required. Now assume that $L \neq \emptyset$. Since $y\geq 1$, $E_w^{x+y} = \bigcup_{u\in L} E_u^{y}$. Therefore,  $|E_w^{x+y}| = |\bigcup_{u\in L } E_u^{y}|$.
As the ball graph $B(w,x) = (V_w^{x}, E_w^{x})$ is connected, we know that $|V_w^{x}| \leq |E_w^{x}| +1 < D^x +1$ and since $x>0$, $|L| = |V_w^{x}| - 1 < (D^x + 1) - 1 =  D^x$.
Thus, we get that 
$   |E_w^{x+y}| = 
    |\bigcup_{u\in L} E_u^{y}| \leq
    \sum_{u\in L}|E_u^{y}| < 
    \sum_{u\in L}D^{y} = 
    |L| \cdot D^{y}  <
    D^{x}\cdot D^{y} =
    D^{x+y}
$  so  $|E_w^{x+y}| < D^{x+y}$.
\end{proof}

Using Lemma~\ref{L-SumOfDenseM}, we prove following corollary.

\begin{corollary}\label{C-SumOfDenseM}
Let $x$ be a positive integer and let $D\geq 1$ be a real number. 
If $|E_w^{x}| < D^{x}$ for every $w\in V$, then $|E_w^{ix}| < D^{ix}$, for every $w\in V$ and $i\geq 1$.
\end{corollary}

\begin{proof}
The proof is by induction on $i$. For $i=1$ it follows from our assumption that $|E_w^{x}| < D^{x}$. Assume now that the claim holds for  $j = i-1$. This implies that $|E_w^{(i-1)x}| < D^{(i-1)x}$, for every $w\in V$. Combining this with the fact that $|E_w^{x}| < D^{x}$, for every $w\in V$, by Lemma~\ref{L-SumOfDenseM} we get that $|E_w^{ix}| < D^{ix}$, for every $w\in V$ and $i\geq1$.
\end{proof}

We also
adapt
procedure $\SparseOrCycleM(G,D,x,y)$ 
of \cite{kadria2022algorithmic} to our needs.
$\SparseOrCycleM$ (see Algorithm~\ref{A-SparseOrCycleM}) gets a graph $G$, a parameter $D \geq 1$,  and two integers $x, y >0$,
and
iterates over vertices using a for-each loop.
Let $w$ be the vertex currently considered
% by $\SparseOrCycleM$ 
and $G(w)$ the current graph. 
If $\IsDense(G(w),w,D^{x},x)=\codeYes$ then 
% \blue{we call $\BallOrCycle(G(w),w,x-1+y)$.}
$\BallOrCycle(G(w),w,x-1+y)$ is called.
If $\BallOrCycle$ returns a cycle $C$ then $C$ is returned by $\SparseOrCycleM$. Otherwise, the vertex set $V_w^{x-1}$ is removed from $G(w)$ along with the edge set $E_w^x$. 
After the loop ends, if no cycle was found, we return $\codeNull$.
Let $W\subseteq  V$ be the set of vertices for which $\BallOrCycle$ was called and no cycle was found, and $\hat{G}=(\hat{V},\hat{E})$
the graph
% $G=(V,E)$ 
after $\SparseOrCycleM$ ends.

\begin{algorithm2e}[t]
    \caption{$\SparseOrCycleM(G,D,x,y)$} \label{A-SparseOrCycleM}
	\ForEach{$w\in V$}{
	    \If{$\IsDense(G,w,D^{x}, x)=\codeYes$}{
	        $(V_w^{x-1+y},C) \gets \BallOrCycle(w, x-1+y)$\;
	        \lIf {$C\neq \codeNull$}{\Return $C$}
	       $G\gets G \setminus V_w^{x-1}$\;
        }
	}
	\Return $null$\;
\end{algorithm2e}

The following lemma is similar to the corresponding lemmas from~\cite{kadria2022algorithmic}, and the proof is omitted. \looseness=-1
% and the details of the proof are omitted. 



\begin{lemma}\label{L-SparseOrCycleM} 
$\SparseOrCycleM(G, D ,x,y)$ satisfies the following: 
\begin{enumerate} [label=(\roman*)]

\item
If a cycle $C$ is returned then $\wt(C)\leq 2(x-1+y)$
\item
If a cycle is not returned then $|E_u^{x}| 
<
D^x$, for every $u\in \hat{G}$
\item
If $u \in G \setminus \hat{G}$ then $u$ is not part of a $C_{\leq 2y}$ in $G$
\item 
$\SparseOrCycleM(G, D ,x,y)$ runs in $O(nD^x + \sum_{w\in W}(|V_w^{x-1+y}|))$ time.
\end{enumerate}

\end{lemma}


Similarly to $\dHybrid$, we show for $\SparseOrCycleM$ that if $G$ satisfies a certain sparsity property, the running time can be bounded as follows. 

\begin{corollary}
\label{C-SparseOrCycle-sparse-time}
If $|E_u^{x-1+y}| < D^{x-1+y}$ for every vertex $u\in V$ then $\SparseOrCycleM(G, D ,x,y)$ runs in $O(nD^x+mD^{y-1})$ time. 
\end{corollary}


\begin{proof}
By Lemma \ref{L-SparseOrCycleM}, $\SparseOrCycleM(G, D ,x,y)$ runs in $O(|V|D^x + \sum_{w\in W}(|V_w^{x-1+y}|))$ time.
For every $w\in W$, the call to $\IsDense(G,w,D^x,x)$ returned $\codeYes$, so it follows from Lemma~\ref{L-Dense} that $|E_w^x|\geq D^x$.
The edge set $E_w^x$ is removed while removing $V_w^{x-1}$. Therefore, for every $w\in W$ we remove at least $D^x$ edges. Since at most $m$ edges can be removed, the size of $W$ is at most $\frac{m}{D^x}$. By our assumption, we have $O(|V_w^{x-1+y}|)\leq O(|E_w^{x-1+y}|)\leq O(D^{x-1+y})$. Therefore, we get that $O(\sum_{w\in W}(|V_w^{x-1+y}|))\leq O(|W|\cdot D^{x-1+y}) \leq O(\frac{m}{D^x} \cdot D^{x-1+y}) = O(mD^{y-1})$. Thus, the running time of $\SparseOrCycleM$ is $O(nD^x+mD^{y-1})$.
\end{proof}


Finally, we include a standard lemma about sampling a hitting set (see, e.g., \cite{aingworth1999fast},  \cite{lingas2009efficient}, \cite{roditty2013fast}). 


\begin{lemma} \label{L-whpM}
    It is possible to obtain in $O(m)$ time, using sampling, a set of edges $S$ of size $\tilde{\Theta} (\frac{m}{s})$, that hits, whp, the $s$ closest edges of every $v\in V$.
\end{lemma}



We remark that some of our algorithms get a graph $G$ that is being updated during their run. 
Within their scope,
$G$ denotes the current graph that includes all updates done so far.



\section{A new cycle searching technique}
\label{sec:neighborhood_technique}


Consider a vertex $s\in V$. It is straightforward to check whether $s$ is on a $C_{\leq 2k}$, for every integer 
% value of 
$k$,
using  $\BallOrCycle(G,s,k)$ in $O(n)$ time. If $\BallOrCycle(G,s,k)$ does not return a $C_{\leq 2k}$ then 
% \blue{the ball graph $B(s,k)$ is a tree}
for every $x,y\in N(s)$ it holds that  $V_x^{k-1}(G')\cap V_y^{k-1}(G')= \emptyset$, where $G'= G\setminus \{s\}$, as otherwise {there was a $C_{\leq 2k}$ passing through $s$ and $\BallOrCycle(G,s,k)$ would have returned a $C_{\leq 2k}$. We show that it is possible to exploit this property to check  for every  $v\in N(s)$  whether $v$ is on a $C_{\leq 2k}$, using $\BallOrCycle(G', v,k)$,   in  $O(n+m)$ time instead of $O(deg(s) \cdot n)$. 
More specifically, we present algorithm 
$\DoubleBfsCycle(G, s, k)$ (see Algorithm~\ref{A-DoubleBfsCycle1}) that gets 
% as an input
a graph $G$, a vertex $s$, and an  integer $k\geq 2$.  We first initialize $\hat{U}$ to $\emptyset$. Then, we run $\BallOrCycle(G,s,k)$. If a cycle $C$ is found by $\BallOrCycle(G, s,k)$ then $C$ is returned by $\DoubleBfsCycle$.
Otherwise, we add the vertex $s$ to $\hat{U}$, keep the neighbors of $s$ in $N_s$, and then remove $s$ from $G$. Recall that  $G'$ equals $G\setminus \{s\}$. Next, for every $v\in N_s$ we run $\BallOrCycle(G',v,k)$,  as long as a cycle is not found. If a cycle $C$ is returned by $\BallOrCycle(G',v,k)$ then $C$ is returned by $\DoubleBfsCycle$.\footnote{For our needs it suffices to stop and return a cycle passing through an $s$ neighbor once we find one, though $\BallOrCycle$ can be run from all the neighbors of $s$ in the same running time bound of $O(n+m)$.}
% If $\BallOrCycle(G',v,k)$ does not return a cycle then 
Otherwise,
$v$ is added to $\hat{U}$. After the loop ends, the vertex $s$ and its adjacent edges are added back to the graph, and the set $\hat{U}$ is returned by $\DoubleBfsCycle$.
% The pseudo-code of $\DoubleBfsCycle$ appears in Algorithm~\ref{A-DoubleBfsCycle1}.
We prove the following lemma.


\begin{algorithm2e}[t]
\caption{$\DoubleBfsCycle(G, s, k)$}
% \DontPrintSemicolon
\label{A-DoubleBfsCycle1}

    $\hat{U} \gets \emptyset$\;

    $(V_s^k,C) \gets \BallOrCycle(s, k)$\;

    \lIf {$C\neq \codeNull$}{\Return $(\emptyset, C)$}
    % \BlankLine
    % \Else{

        $\hat{U}\gets \hat{U} \cup \{s\}$\;

        $N_s \gets N(s)$\;

        $G \gets G \setminus \{s\}$\;

         \ForEach{$v \in N_s$}{
             $(V_v^k,C) \gets \BallOrCycle(v, k)$\;

             \lIf {$C\neq \codeNull$}{\Return $(\emptyset, C)$}

             $\hat{U}\gets \hat{U} \cup \{v\}$ \;           

         }        
    % }

    add $s$ and the edge set $\{(s,v) \mid v\in N_s\}$ back to $G$;

    \Return $(\hat{U}, \codeNull);$

\end{algorithm2e}




\begin{lemma}  \label{L-DoubleBfsCycle1} 
    If algorithm $\DoubleBfsCycle(G,s,k)$ finds a cycle $C$ then $\wt(C)\leq 2k$. Otherwise, no vertex in $V_s^{1}$ is part of a $C_{\leq 2k}$ in $G$, and the set $\hat{U}= V_s^{1}$ is returned. 
\end{lemma}
\begin{proof}
    If a cycle was found, it happened during the call to $\BallOrCycle(G,s,k)$ or one of the calls to $\BallOrCycle(G',v,k)$. Therefore, by Lemma~\ref{L-BallOrCycle}, the cycle length is at most $2k$.

    If no cycle was found during the run of $\BallOrCycle(G,s,k)$ then $s$ is not on a $C_{\leq 2k}$ in $G$. 
    % Specifically, $s$ is not part of a $C_{\leq 2\alpha}$ since $\alpha \leq k$. 
    In addition, for every $v\in N_s$ $\BallOrCycle(G',v,k)$ did not find a cycle. Hence, $v$ is not on a $C_{\leq 2k}$ in $G'$ and therefore also in $G$, since $G'=G \setminus \{s\}$ and  $s$ is not on a $C_{\leq 2k}$.
    Since no cycle was found, $s$ and the vertices
    % \blue{in $N_s$} 
    $v$ for every $v\in N_s$
    are added to $\hat{U}$, so 
    by the definition of $V_s^{1}$ 
    we have $\hat{U} = V_s^{1}$.
\end{proof}



To bound the running time of $\DoubleBfsCycle$, 
we show how to use the fact that no $C_{\leq 2k}$ was found by
$\BallOrCycle(G,s,k)$,
to efficiently run $\BallOrCycle(G',v,k)$ for every $v\in N_s$. \looseness=-1


\begin{lemma}\label{L-Batch-RT}
Let $s\in V$. If the ball graph $B(G,s,k)$ is a tree then the total cost of running $\BallOrCycle(G',v,k)$ for every $v\in N_s$ is $O(|V_s^k(G)|+\sum_{w\in L_s^k(G)} deg(w) )$. 
\end{lemma}

\begin{proof}
By the definitions of $V_s^k$, $L_s^k$ and $G'$,
we know that $V_s^k (G) = \cup_{v\in N_s}V_v^{k-1}(G') \cup\{s\}$ and $L_s^k(G
) = \cup_{v\in N_s} L_v^{k-1}(G')$.
Since $B(G,s,k)$ 
% does not contain any cycle
contains no cycles
it follows that 
$V_x^{k-1}(G') \cap V_{y}^{k-1}(G') =\emptyset$ and 
$L_x^{k-1}(G') \cap L_{y}^{k-1}(G')=\emptyset$,
for any two distinct vertices 
% $x,y$ such that
$x,y\in N_s$.
Therefore, \textbf{(i)} $|V_s^k(G)| = \sum_{v\in N_s} |V_v^{k-1} (G')|+1$, and \textbf{(ii)} $L_s^k(G
) = \mathbin{\mathaccent\cdot\cup}_{v\in N_s} L_v^{k-1}(G')$.
From Lemma~\ref{L-BallOrCycle} it follows that the total cost 
of the calls to $\BallOrCycle(G',v,k)$ for every $v\in N_s$ is $O(\sum_{v\in N_s}|V_v^k(G')|)$.
It holds that $|V_v^k (G')| \leq |V_v^{k-1}(G')| + \sum_{w\in L_v^{k-1}(G')} deg(w)$, for every $v\in N_s$. 
Thus,
% we get that the the total cost of running $\BallOrCycle(G',v,k)$ for every $v\in N_s$ is 
we get that the total cost is 
$O(\sum_{v\in N_s}|V_v^k(G')|) = O(\sum_{v\in N_s}(|V_v^{k-1}(G')|+\sum_{w\in L_v^{k-1}(G')} deg(w)))$. This equals to 
$ O(\sum_{v\in N_s}|V_v^{k-1}(G')|+\sum_{v\in N_s} \sum_{w\in L_v^{k-1}(G')} deg(w)))$, and it follows from \textbf{(i)} and \textbf{(ii)} that this is at most $
O(|V_s^k(G)|+\sum_{w\in L_s^k(G)} deg(w) )$. 
\end{proof}

We use Lemma~\ref{L-Batch-RT} to bound the running time of $\DoubleBfsCycle$.

\begin{lemma} \label{L-DoubleBfsCycle-time}
    Algorithm $\DoubleBfsCycle$ runs in $O(n+m)$ time. 
\end{lemma}
\begin{proof}
    Running $\BallOrCycle(G,s,k)$ costs $O(n)$. If a cycle is found, it is returned and the running time is $O(n) = O(n+m)$. If no cycle is found, then removing (and later adding back) $s$ and its  edges costs $O(deg(s))$.   
    By Lemma~\ref{L-Batch-RT}, the cost of running     $\BallOrCycle(G',v,k)$ for every $v\in N_s$ is $O(|V_s^k(G)|+\sum_{w\in L_s^{k}(G)}deg(w)) = O(n+m)$.
    Adding $s$ and  $N_s$ to $\hat{U}$ takes $O(V_s^{1})=O(n)$ time. Thus,  the total running time of $\DoubleBfsCycle$ is $O(n+m)$.
    % \blue{The sets $V_{v}^{k}$ are computed during the execution of $\BallOrCycle(G',v,k)$ for every $(s,v)\in E_s$ for which no cycle was found. Their total size is also $O(n+m)$, and we can obtain the sets $V_{v}^{k-\alpha}$ and add them to $\hat{U}$ in $O(n+m)$ time.
    % }
\end{proof}



