    We compute this value for at most $n$ distinct vertices so the running time of this part is at most  $O(\sum_{v \in V} deg(v)) = O(m)$ in total.
    By Lemma~\ref{L-DoubleBfsCycle1}, running $\DoubleBfsCycle$ takes $O(n+m) = O(m)$ time.
    Each edge in $E_s^2$ contributes at most $2$ to the sum $ \sum_{v \in N(s)} deg(v)$, so 
    $ \sum_{v \in N(s)} deg(v) \leq 2|E_s^2|$ and 
    $\frac{1}{2} \sum_{v \in N(s)} deg(v) \leq |E_s^2|$.
    If a call to $\DoubleBfsCycle(G,s,k)$  did not return a cycle, then by Lemma~\ref{L-DoubleBfsCycle1}, the set $\hat{U}=V_s^{1}$ is returned. $\twoSparseOrCycle$ removes the set $\hat{U}=V_s^{1}$ and by doing so, the edge set $E_s^2$ is also removed. We charge each edge of $E_s^2$ with $O(m^{\frac{k-1}{k+1}})$. Thus the total cost that we charge for $s$ is $ O(|E_s^2|\cdot m^{\frac{k-1}{k+1}})
    \geq 
    O( \sum_{v \in N(s)} deg(v)
    \cdot m^{\frac{k-1}{k+1}})
    \geq
    O(m^{\frac{2}{k+1}}\cdot m^{\frac{k-1}{k+1}} )= O(m)
    $,
    which covers the $O(m)$ cost of $\DoubleBfsCycle(G,s,k)$.

    Since each edge can be charged and removed from $G$ at most once during the execution of $\twoSparseOrCycle$, the running time of $\twoSparseOrCycle$ is at most $O(m \cdot m^{\frac{k-1}{k+1}} )  = O(m^{1+\frac{k-1}{k+1}})$. \qedhere
\end{enumerate}
\end{proof}




Next, we use  $\twoSparseOrCycle$ to design a $2k$-hybrid algorithm called $\kHybrid$.
Notice first that if  $|E_u^{k-1}|< m^{\frac{k-1}{k+1}}$ for every $u\in V$, then 
it is straightforward to obtain an $O(m^{1+\frac{k-1}{k+1}})$-time  $2k$-hybrid algorithm, by  running $\dHybrid(G,k)$. 
Thus, in  $\kHybrid$ we  ensure that if we call  $\dHybrid$ then it holds for  every $u\in V$ that $|E_u^{k-1}|< m^{\frac{k-1}{k+1}}$. 
To do so, we  run $\twoSparseOrCycle$ and possibly $\SparseOrCycleM$. 
If no cycle was returned
then it holds that 
$|E_u^{k-1}|< m^{\frac{k-1}{k+1}}$ for every $u\in V$, and we can safely run  $\dHybrid$. 

$\kHybrid$ (see Algorithm~\ref{A-kHybrid}) gets a graph $G$ and an integer $k\geq 2$. 
$\kHybrid$ is composed of  three stages. 
In the first stage we call
$\twoSparseOrCycle(G,k)$. 
If $\twoSparseOrCycle$ returns a cycle $C$ then $\kHybrid$ stops and returns $C$, otherwise we proceed to the second stage. 
In the second stage, if $(k-1) \bmod 2 \neq 0$, we call 
$\SparseOrCycleM(G, m^{\frac{1}{k+1}}, 1, k)$.
If $\SparseOrCycleM$ returns a cycle $C$ then $\kHybrid$ stops and returns $C$, otherwise we proceed to the last stage. 
In the last  stage, we call $\dHybrid(G,k)$.
If $\dHybrid$ returns a cycle $C$ then $\kHybrid$ stops and returns $C$, otherwise $\kHybrid$ returns $\codeNull$.
In the next lemma we prove the correctness and analyze the running time of $\kHybrid(G,k)$. 



 \begin{algorithm2e}[t]
    \caption{$\kHybrid(G,k)$}
    % \DontPrintSemicolon
    \label{A-kHybrid}
        $C \gets \twoSparseOrCycle(G,k)$\;

        \lIf{$C\neq \codeNull$}{\Return $C$}

        \BlankLine

       \If{$ (k-1) \bmod 2 \neq 0$}{

          $C\gets \SparseOrCycleM(G, m^{\frac{1}{k+1}} , 1, k)$


          \lIf {$C\neq \codeNull$}{\Return $C$}

        }
         \BlankLine

         $C\gets \dHybrid(G,k)$\;

          \lIf {$C\neq \codeNull$}{\Return $C$}


        \BlankLine
        \Return $\codeNull$\;

\end{algorithm2e}


\begin{lemma} \label{L-kHybrid} 
    $\kHybrid(G,k)$ either returns a $C_{\leq 2k}$ or determines that $g>2k$, in $O(m^{1+\frac{k-1}{k+1}})$ time.
\end{lemma}


\begin{proof} 


First, $\kHybrid(G,k)$ returns a cycle $C$ only if $\twoSparseOrCycle(G,k)$, $\SparseOrCycleM(G, m^{\frac{1}{k+1}} , 1, k)$ or $\dHybrid(G,k)$ returns a cycle $C$. Therefore, if a cycle is returned then it follows from Lemmas~\ref{L-twoSparseOrCycle}, \ref{L-SparseOrCycleM}, or \ref{L-dHybrid-properties}, respectively,  that $\wt(C)\leq 2k$.

Second, we show that if no cycle was found then $g>2k$.
If no cycle was found then it might be that some vertices were removed from the graph.
A vertex $u$ can be removed either by  $\SparseOrCycleM$ or by $\twoSparseOrCycle$.  It follows from Lemma~\ref{L-SparseOrCycleM} and Lemma~\ref{L-twoSparseOrCycle}, that $u$ is not part of a $C_{\leq 2k}$ when $u$ is removed. Since only vertices that are not on a $C_{\leq 2k}$ are removed, every $C_{\leq 2k}$ that was in the input graph also belongs to the updated graph. 
We then call $\dHybrid(G,k)$ with the updated graph. Since we are in the case that no cycle was found, $\dHybrid$ did not return a cycle. It follows from Lemma~\ref{L-dHybrid-properties} that $g>2k$ in the updated graph, and therefore $g>2k$ also in the input graph.

Now we turn to analyze the running time of $\kHybrid$.
At the beginning, $\kHybrid$ calls $\twoSparseOrCycle$.
By Lemma~\ref{L-twoSparseOrCycle}, $\twoSparseOrCycle$ runs in $O(m^{1+\frac{k-1}{k+1}})$ time.
Let $G_1$ be the graph after the call to $\twoSparseOrCycle$. By Lemma~\ref{L-twoSparseOrCycle},
for every $u\in G_1$ we have $|E_u^{2}| < m^{\frac{2}{k+1}}$. 

Next, $\kHybrid$ checks if $(k-1) \bmod 2 \neq 0$. 
We divide the rest of the proof  to the case that $(k-1) \bmod 2 = 0$ and to the case that $(k-1) \bmod 2 \neq  0$. 
If $(k-1) \bmod 2 = 0$ then $\kHybrid$ calls $\dHybrid$. 
Since $(k-1) \bmod 2 = 0$ and since for every $u\in G_1$ we have $|E_u^{2}| < m^{\frac{2}{k+1}}$, it follows from Corollary~\ref{C-SumOfDenseM} that $|E_u^{k-1}| <  m^{\frac{k-1}{k+1}}$ for every $u\in G_1$. 
% Using Corollary~\ref{C-dHybrid-sparse-time} 
% with $D=m^{\frac{1}{k+1}}$
By Corollary~\ref{C-dHybrid-sparse-time}, the running time of $\dHybrid$ is $O(m\cdot m^{\frac{k-1}{k+1}}) = O(m^{1+\frac{k-1}{k+1}})$.

We now turn to the case that $(k-1) \bmod 2 \neq  0$. 
In this case it might be that $|E_u^{k-1}| \geq  m^{\frac{k-1}{k+1}}$ for some vertices $u\in G_1$. 
Therefore, we first call $\SparseOrCycleM(G_1, m^{\frac{1}{k+1}}, 1, k)$.
Notice that since we are in the case that $(k-1) \bmod 2 \neq 0$ it holds that $k \bmod 2 = 0$. 
Moreover, $|E_u^{2}| < m^{\frac{2}{k+1}}$ for every $u\in G_1$. Thus, it follows from Corollary~\ref{C-SumOfDenseM} that $|E_u^{k}| <  m^{\frac{k}{k+1}}$ for every $u\in G_1$. 
By Corollary~\ref{C-SparseOrCycle-sparse-time} if $|E_u^{k}| <  m^{\frac{k}{k+1}}$ for every $u\in G_1$ then the running time of $\SparseOrCycleM(G_1, m^{\frac{1}{k+1}}, 1, k)$ is $O(nm^{\frac{1}{k+1}}+mm^{\frac{k-1}{k+1}})=O(m^{1+\frac{k-1}{k+1}})$.

Let $G_2$ be the graph after $\SparseOrCycleM$ ends.  By Lemma~\ref{L-SparseOrCycleM}, for every $u\in G_2$ we have $|E_u^{1}| <  m^{\frac{1}{k+1}}$.
It follows from Corollary~\ref{C-SumOfDenseM} that $|E_u^{k-1}| <  m^{\frac{k-1}{k+1}}$.
Now $\kHybrid$ calls $\dHybrid$, and using  Corollary~\ref{C-dHybrid-sparse-time}
% with $D=m^{\frac{1}{k+1}}$
again, we get that the running time of $\dHybrid$ is $O(m\cdot m^{\frac{k-1}{k+1}}) = O(m^{1+\frac{k-1}{k+1}})$.


It follows from the above discussion that $\SrtCycSpr$ either returns a $C_{\leq 2k}$ or determines that $g>2k$, and
the running time is $O( m^{1+\frac{k-1}{k+1}})$.
\end{proof}


\subsection{\texorpdfstring{A $(+1)$-approximation of the girth}{A (+1)-approximation of the girth}}
% \subsection{A $(+1)$-approximation of the girth} \hfill

Next, we describe algorithm $\AdditiveGirthApprox$, which uses $\kHybrid$ and the framework described in Section~\ref{sec:introduction}, to obtain a $(+1)$-approximation of $g$, when $g\leq \log n$.
$\AdditiveGirthApprox$ (see Algorithm~\ref{A-AdditiveGirthApprox}) gets a graph $G$.
In $\AdditiveGirthApprox$, we set $k$ to $2$ and start a while loop.
In each iteration, we create a copy $G'$ of $G$ and call $\kHybrid(G',k)$. If  $\kHybrid$ finds a cycle $C$ then $\AdditiveGirthApprox$ stops and returns $C$, otherwise we increment $k$ by $1$ and continue to the next iteration. We prove the following theorem.
% The pseudo-code appears in Algorithm~\ref{A-AdditiveGirthApprox}.
\looseness=-1

 \begin{algorithm2e}[t]
        \caption{$\AdditiveGirthApprox(G)$}
        \label{A-AdditiveGirthApprox}
        % \DontPrintSemicolon
        \CommentSty{\color{blue}}
        $k \gets 2$\;

        \While{$\textsf{true}$}
        {
            $G' \gets$ a copy of $G$\;
            $C\gets \kHybrid(G',k)$\;
            \lIf{$C \neq \codeNull$}{return $C$}

            $k \gets k +1$\;    
        }


\end{algorithm2e}

\begin{theorem}
\label{T-Main-Approx} 
Algorithm $\AdditiveGirthApprox(G)$ returns either a $C_{g}$ or a $C_{g+1}$,  
and runs in $\Ot(m^{1+\frac{\ell -1}{\ell+1}})$ time, where $g=2\ell$ or $g=2\ell -1$ and $2\leq  \ell < \log n$.\footnote{
We note that when $\ell \geq \log n$,  the $O(n^2)$-time, $(+1)$-approximation of Itai and Rodeh~\cite{itai1977finding} can be used.}
\end{theorem}

\begin{proof}
We first prove the bound on the approximation. 
$\AdditiveGirthApprox$ always returns a cycle in $G$ so it cannot be that a $C_{<g}$ will be returned. 
$\AdditiveGirthApprox$ starts with $k = 2$. 
It follows from Lemma~\ref{L-kHybrid} that as long as $k<\ell$ the calls to $\kHybrid$ will not return a cycle since the graph does not contain a $C_{\leq 2k}$. 
Consider now the iteration in which $k=\ell$. 
$\AdditiveGirthApprox$ calls to  $\kHybrid(G',\ell)$ where $G'=G$. It follows from Lemma~\ref{L-kHybrid} that $\kHybrid$ will either return a $C_{\leq 2\ell}$, or determine that $g>2\ell$. Since  we assume that $g\leq 2\ell$, $\kHybrid$ will return a $C_{\leq 2\ell}$
which is either a $C_g$ or a $C_{g+1}$ since $g=2\ell$ or $g=2\ell -1$.

We now turn to analyze the running time. 
Creating a copy of $G$ takes $O(m)$ time, and by Lemma~\ref{L-kHybrid} the running time of $\kHybrid(G',k)$ is $O(m^{1+\frac{k -1}{k+1}})$. Therefore, for every $k \leq \ell$, the running time of the iteration of the while loop with this value of $k$ is $O(m^{1+\frac{k -1}{k+1}})$.
From the previous part of this proof
it follows that the last iteration of the while loop  is when $k = \ell$, thus, the running time of $\AdditiveGirthApprox$ is 
$O(m^{1+\frac{1}{3}}+m^{1+\frac{2}{4}}+\cdots+m^{1+\frac{\ell-2}{\ell}}+m^{1+\frac{\ell-1}{\ell+1}})\leq O(\ell\cdot m^{1+\frac{\ell-1}{\ell+1}})
$.
Therefore, when $\ell < \log n$, the running time is $\Ot(m^{2-\frac{2}{\ell+1}})$.
\end{proof}













\section{A general hybrid algorithm}
\label{sec:one-alg}


Algorithm $\kHybrid(G,k)$, presented in the previous section, either returns a $C_{\leq 2k}$ or determines that $g>2k$, in $O(m^{1+\frac{k-1}{k+1}})$ time.
In this section we introduce an additional parameter $2\leq \alpha\leq k$ and present a $(2k,2\alpha)$-hybrid algorithm  that  either returns a $C_{\leq 2k}$ or determines that $g>2\alpha$, in $O((\frac{k+1}{\alpha-1}+\alpha) \cdot m^{1+\frac{\alpha-1}{k+1}})$ time. 
In Section~\ref{sec:girth-approx} we use the $(2k,2\alpha)$-hybrid algorithm to present two tradeoffs for girth approximation.

To obtain the $(2k,2\alpha)$-hybrid algorithm we first  extend algorithm $\DoubleBfsCycle$.
%We obtain our new tradeoff for girth approximation using  the $(2k,2\alpha)$-hybrid algorithm. 
Then, we use the extended $\DoubleBfsCycle$ together with  additional tools that we develop to either return a $C_{\leq 2k}$ or sparsify dense regions of the graph, so that we  can check whether $g>2\alpha$ (or return a $C_{\leq 2k}$) in $O(m^{1+\frac{\alpha-1}{k+1}})$ time, by running $\dHybrid(G,\alpha)$.


\subsection{\texorpdfstring{Extending $\DoubleBfsCycle$}{Extending NeighborhoodBallOrCycle}}
% \subsection{Extending $\DoubleBfsCycle$} \hfill

In algorithm $\DoubleBfsCycle$ we mark
vertices that can be removed from the graph, by using 
the property that if $\BallOrCycle(v,k)$ did not return a $C_{\leq 2k}$ then $v$ is not on a $C_{\leq 2k}$.
In \cite{kadria2022algorithmic}, they introduce an additional parameter $\alpha$ and used the following extended version of this property:
If $\BallOrCycle(v,k)$ did not return a $C_{\leq 2k}$ then  no vertex of $V_v^{k-\alpha}$ is  on a $C_{\leq 2\alpha}$. 
We use the same approach and modify $\DoubleBfsCycle$ to get an additional integer parameter $\alpha$ such that $2\leq\alpha\leq k$.
After each call to $\BallOrCycle(G',v,k)$, where $v \in N_s$, if no cycle was found we add $V_v^{k-\alpha}$, instead of $v$,  to $\hat{U}$. 
The modified pseudo-code appears in Algorithm~\ref{A-DoubleBfsCycle}.
We rephrase Lemma~\ref{L-DoubleBfsCycle1} to suit this modification.

\begin{algorithm2e}[t]
\caption{$\DoubleBfsCycle(G, s, k,\alpha)$}
% \DontPrintSemicolon
\label{A-DoubleBfsCycle}

    $\hat{U} \gets \emptyset$\;

    $(V_s^k,C) \gets \BallOrCycle(s, k)$\;

    \lIf {$C\neq \codeNull$}{\Return $(\emptyset, C)$}
    \BlankLine

    $\hat{U}\gets \hat{U} \cup \{s\}$\;

    $N_s \gets N(s)$\;

    $G \gets G \setminus \{s\}$\;

     \ForEach{$(s,v) \in N_s$}{
         $(V_v^k,C) \gets \BallOrCycle(v, k)$\;

         \lIf {$C\neq \codeNull$}{\Return $(\emptyset, C)$}

        $ \hat{U}\gets \hat{U} \cup V_{v}^{k-\alpha}$ \;           

     }        


    add $s$ and the edge set $\{(s,v) \mid v\in N_s\}$ back to $G$;

    \Return $(\hat{U}, \codeNull);$

\end{algorithm2e}


\begin{lemma}  \label{L-DoubleBfsCycle}
    Let $2\leq \alpha \leq k$. If  $\DoubleBfsCycle(G,s,k,\alpha)$ finds a cycle $C$ then $\wt(C)\leq 2k$. Otherwise, no vertex in $V_s^{k-\alpha+1}$ is part of a $C_{\leq 2\alpha}$ in $G$, and the set $\hat{U}= V_s^{k-\alpha+1}$ is returned. 
\end{lemma}

\begin{proof}
    The proof that if a cycle $C$ is returned then $\wt(C)\leq 2k$ is as in Lemma~\ref{L-DoubleBfsCycle1}.
    It is left to show that if no cycle is found then no vertex in $V_s^{k-\alpha+1}$ is part of a $C_{\leq 2\alpha}$ in $G$, and the set $\hat{U}= V_s^{k-\alpha+1}$ is returned.

    From Lemma~\ref{L-not-part-of} it follows that if $\BallOrCycle(G',v,k)$ did not  return a cycle then no vertex in $V_v^{k-\alpha}$ is part of a $C_{\leq 2\alpha}$ in $G'$, and therefore also in $G$, since $G'=G \setminus \{s\}$ and  since $s$ itself is not on a $C_{\leq 2\alpha}$ as otherwise $\BallOrCycle(G',v,k)$ would not have been called. 
    Thus, if no cycle was found, we have $\hat{U}=V_s^{k-\alpha+1}(G)$, as in this case $\hat{U}$ contains $s$ and $V_v^{k-\alpha}(G')$ for each $v\in N(s)$, which equals to $V_s^{k-\alpha+1}(G)$.
\end{proof}



For the running time, we note that the sets $V_{v}^{k}$ are computed during the execution of $\BallOrCycle(G',v,k)$, for every $(s,v)\in N_s$ for which no cycle was found. Their total size is also $O(n+m)$, and we can obtain from them the sets $V_{v}^{k-\alpha}$ and add these sets to $\hat{U}$ in $O(n+m)$ time. Therefore, the modified $\DoubleBfsCycle$ also runs in $O(n+m)$ time.



\subsection{\texorpdfstring{A $(\max\{2k,g\},\gt)$-hybrid algorithm}{A (max{2k,g},tilde(g))-hybrid algorithm}}


In this section we present a $(\max\{2k,g\},2\alpha)$-hybrid algorithm called $\OneAlg$, where $\alpha = \lceil \frac{\gt}{2}\rceil $. $\OneAlg$ (see Algorithm~\ref{A:OneAlg}) gets 
% as an input 
a graph $G$ and two integers $\alpha, k\geq 2$.
% and $\alpha\geq 2$.
If $m \geq 1+\lceil n\cdot (1+n^{1/k})\rceil$ then we run algorithm $\SrtCycDns(G,k)$ (see Algorithm~\ref{A:srtCycDns}), which is based on algorithm $\DegenerateOrCycle$ of \cite{kadria2022algorithmic}.
If $m < 1+\lceil n\cdot (1+n^{1/k})\rceil$ then the main challenge is when
 $\alpha \leq k< \frac{n}{2}$. In this case we run algorithm $\SrtCycSpr(G,k,\alpha)$ (described later). 
The 
% special 
cases that $k\geq \frac{n}{2}$ or  $k<\alpha$ are relatively simple and 
% are 
treated in algorithm $\SpCase(G,k,\alpha)$ (see Section~\ref{subsec:special}). 
We summarize 
the properties of 
$\OneAlg(G,k,\alpha)$
in the next theorem.



  \begin{algorithm2e}[t]
            \caption{$\OneAlg(G,k,\alpha)$}
            % \DontPrintSemicolon
            \label{A:OneAlg}

            \If{$m \geq 1+\lceil n\cdot (1+n^{1/k})\rceil$}
            {
                       \Return $\SrtCycDns(G,k)$\;
            }
            \BlankLine
            % \tcp{\red{Here $m < 1+\lceil n\cdot (1+n^{1/k})\rceil$}}

            \If{$\alpha \leq k< \frac{n}{2} $}
            {
            \Return $\SrtCycSpr(G,k,\alpha)$\;
            }

            \Return $\SpCase(G,k,\alpha)$

    \end{algorithm2e}


\begin{algorithm2e}[t]
    \caption{$\SrtCycDns(G,k)$}
    % \DontPrintSemicolon
    \label{A:srtCycDns}

        $G'\gets (V',E')$ is the edge induced subgraph formed by an arbitrary subset of $1+\lceil n\cdot (1+n^{1/k})\rceil$ edges; 

        \BlankLine

        $S \gets \{a \in V' \mid deg_{G'}(a)\leq 1+n^{1/k}\}$\;


        \While{$S \neq \emptyset$}
        {
            pick $a$ from $S$\;     
            \ForEach{$(a,b)\in E'$}{\lIf {$deg_{G'}(b)=2+n^{1/k}$}{$S \gets S \cup \{b\}$}}
            remove $a$ from $G'$ and from $S$\;
        }
        % \BlankLine

        $(*, C) \gets \BallOrCycle(G',w,k)$ with some $w \in V'$\;
        \Return $C$\tcp*{$C$ is a cycle of length $\leq 2k$}   
    \end{algorithm2e}

\begin{theorem}
\label{Thm-One-Alg}
Let $\alpha,k\geq2$  be   integers.  $\OneAlg(G,k,\alpha)$ runs whp in $\Ot((\frac{k+1}{\alpha-1}+\alpha) \cdot \min\{m^{1+\frac{\alpha-1}{k+1}},n^{1+\frac{\alpha}{k}}\})$ time 
and either returns a $C_{\leq \max\{2k,g\}}$, or determines that $g > 2\alpha$.  
\end{theorem}

The next corollary follows from  Theorem~\ref{Thm-One-Alg}, when $\alpha \leq k$. 


\begin{corollary}
\label{C-shortCycleBigK}
    Let $2\leq \alpha \leq k$.
    Algorithm $\OneAlg(G,k,\alpha)$ runs whp in $\tilde{O}((\frac{k+1}{\alpha-1}+\alpha) \cdot \min \{m^{1+\frac{\alpha-1}{k+1}},n^{1+\frac{\alpha}{k}}\})$
    time and either returns a $C_{\leq 2k}$, or determines that $g > 2\alpha$.
\end{corollary}


In the rest of this section, we present  the proof of Theorem~\ref{Thm-One-Alg}.
As follows from~\cite{kadria2022algorithmic},  if $m \geq 1+\lceil n\cdot (1+n^{1/k})\rceil$ then  $\SrtCycDns(G,k)$ returns in  $O(\min\{m,n^{1+1/k}\})$ time  a $C_{\leq 2k}$. We now consider the case in which $m < 1+\lceil n\cdot (1+n^{1/k})\rceil$.
%For the case  that $k\geq\frac{n}{2}$ and the case  that $k<\alpha$
We prove in Section~\ref{subsec:special} that  $\SpCase(G,k,\alpha)$ satisfies the claim of Theorem~\ref{Thm-One-Alg}, when $k\geq\frac{n}{2}$ or $k<\alpha$.

Our main technical contribution is algorithm $\SrtCycSpr$ that handles the case of
$\alpha \leq k < \frac{n}{2}$.
Notice  that if  $|E_u^{\alpha-1}|< m^{\frac{\alpha-1}{k+1}}$ for every $u\in V$, then 
$\dHybrid(G,\alpha)$ is a $(2k,2\alpha)$-hybrid algorithm that either finds a $C_{\leq 2\alpha}$ (which is also a $C_{\leq 2k}$ as $\alpha \leq k$) or determines that $g>2\alpha$, in $O(m^{1+\frac{\alpha-1}{k+1}})$ time. 
Thus, in  $\SrtCycSpr$ we  ensure that if we call  $\dHybrid$,
the property that $|E_u^{\alpha-1}|< m^{\frac{\alpha-1}{k+1}}$, for  every $u\in V$ (whp), holds.
To do so, we  run $\BFSSampleM$ and possibly $\HandleReminderM$. 
If no cycle was returned, the property holds, 
and we can safely run  $\dHybrid$. 


$\SrtCycSpr$ (see Algorithm~\ref{A-BigKM}) gets a graph $G$ and 
% \red{the}
two integers $\alpha, k\geq 2$ such that $\alpha \leq k < \frac{n}{2}$,
and is composed of three stages.
In the first stage we call
$\BFSSampleM(G,k,\alpha)$ (described later). 
If $\BFSSampleM$ returns a cycle $C$ then $\SrtCycSpr$ stops and returns $C$,
otherwise we proceed to the second stage. 
In the second stage, if $(k+1) \bmod (\alpha-1) \neq 0$, we call 
$\HandleReminderM(G,k,\alpha)$ (also described later). 
If $\HandleReminderM$ returns a cycle $C$ then $\SrtCycSpr$ stops and returns $C$, otherwise we proceed to the last stage. 
In the last  stage, we call $\dHybrid(G,\alpha)$.
If $\dHybrid$ returns a cycle $C$ then $\kHybrid$ stops and returns $C$, otherwise $\SrtCycSpr$ returns $\codeNull$.
% The pseudo-code of $\SrtCycSpr$ appears in Algorithm~\ref{A-BigKM}.
\looseness=-1


 \begin{algorithm2e}[t]

    \caption{$\SrtCycSpr(G,k,\alpha)$}
    % \DontPrintSemicolon
    \label{A-BigKM}

        $C \gets \BFSSampleM(G,k,\alpha)$\;

        \lIf{$C\neq \codeNull$}{\Return $C$}

        \BlankLine

        \If{$(k+1) \bmod (\alpha-1)  \neq 0$}{
        $C \gets \HandleReminderM(G,k,\alpha)$\;

        \lIf{$C\neq \codeNull$}{\Return $C$}
        }

         \BlankLine


          $C \gets \dHybrid(G,\alpha)$\;

          \lIf {$C\neq \codeNull$}{\Return $C$}


        \BlankLine
        \Return $\codeNull$\;


    \end{algorithm2e}


Next, we give a high level description of  $\BFSSampleM$.
The goal of $\BFSSampleM$ is to either sparsify the graph 
without removing any $C_{\leq 2\alpha}$, 
or to report a $C_{\leq 2k}$. 
For simplicity  assume that $(k+1) \bmod (\alpha-1) =0$.
In such a case, if $\BFSSampleM$ does not report a $C_{\leq 2k}$, then the graph after $\BFSSampleM$ ends contains all the $C_{\leq 2\alpha}$s  that  
were in the original graph, and satisfies, whp, the following sparsity property: 
For every $u\in V$ it holds that $|E_u^{\alpha-1}| < m^{\frac{\alpha-1}{k+1}}$. 

This implies that in $\BFSSampleM$ we need to find every $u\in V$ 
which is in a dense region with
$|E_u^{\alpha-1}| \geq m^{\frac{\alpha-1}{k+1}}$, and to check if $u$ is in a $C_{\leq 2\alpha}$, so that if not we can remove $u$.
Finding every such $u$ is possible within the time limit by running $\IsDense(G,u,m^{\frac{\alpha-1}{k+1}}, \alpha - 1)$ for every $u \in V$.
The problem  is that checking whether $u$  is on a $C_{\leq 2\alpha}$ for every such $u$ is too costly since there might be $n$ such vertices, and this check costs $O(n)$ using $\BallOrCycle(G,u,\alpha)$. 

One  way to overcome this problem is to  sample  an edge set $S$ of size $\tilde{\Theta}(m^{1-\frac{\alpha-1}{k+1}})$  that hits the $m^{\frac{\alpha-1}{k+1}}$ closest edges of each vertex,
and then use $S$ to detect the vertices in the dense regions that are not on a $C_{\leq 2\alpha}$.
In $\BFSSampleM$ we use a \textit{detection process} in which we call $\BallOrCycle$ or $\DoubleBfsCycle$ from the endpoints of $S$'s edges, and then, if no cycle was found, we use the information obtained from this call to identify vertices that are not on a  $C_{\leq 2\alpha}$. 
The detection process either detects vertices that are not on a $C_{\leq 2\alpha}$ and  can be removed, or reports a $C_{\leq 2k}$. 
However, it is not clear how to 
implement this detection process efficiently, since just running $\BallOrCycle$ from the endpoints of $S$'s edges takes $O(n m^{1-\frac{\alpha-1}{k+1}})$ time which might be too much.
Our solution is an \textit{iterative} sampling procedure that starts with a smaller hitting set of edges, of size $\tilde{\Theta}(m^{\frac{\alpha-1}{k+1}})$.
For such a hitting set we 
can run our detection process.
If a $C_{\leq 2k}$ was not reported, then we remove the appropriate vertices and sparsify the graph without removing any $C_{\leq 2\alpha}$.
When the graph is sparser, the running time of our detection process 
becomes faster. Thus, in the following iteration we can sample a larger hitting set for which we run this process, and either return a  $C_{\leq 2k}$ or sparsify the graph further for the next iteration.
We continue the iterative sampling procedure until we get to the required sparsity property in which $|E_u^{\alpha-1}| < m^{\frac{\alpha-1}{k+1}}$ for every $u\in V$ (whp). 


We remark that in the first iteration of $\BFSSampleM$, the detection process calls $\DoubleBfsCycle$, while in the rest of the iterations $\BallOrCycle$ is called. 
% In the first iteration the samples set is small enough to allow the running time of $O(m)$ for each sampled edge.
The use of $\DoubleBfsCycle$ allows us, in the case that no $C_{\leq 2k}$ is reported, 
to bound $|E_v^d|$ with $m^{\frac{d}{k+1}}$ for every $v\in V$, rather than $|E_v^{d-1}|$.
This is used to achieve the required sparsity property.
Since 
$\DoubleBfsCycle$ runs in $O(m)$ time we can only use it in the first iteration when the sampled set is small enough. In the rest of the iterations we use $\BallOrCycle$ instead.



We now formally describe 
$\BFSSampleM$.
$\BFSSampleM$ (see Algorithm~\ref{BFSSample-M}) gets 
a graph $G$ and two integers
$\alpha , k \geq 2$
such that $\alpha \leq k < \frac{n}{2}$. We 
first set $y$ to $\lceil \frac{k+1}{\alpha-1}\rceil-1$.
Then, we start the main for loop that has at most $y$ iterations.
% During 
In the $i$th iteration,
% of the for loop, 
we initialize $\hat{V}$ to $\emptyset$ and sample a set $S_i\subseteq E$ of size $\Tilde{\Theta}(m^\frac{i\cdot(\alpha-1)}{k+1})$.
Next, 
we scan the 
endpoints in $V(S_i)$ using an inner for-each loop.
% edges of $S_i$ in an inner for-each loop. 
\looseness=-1

If $i=1$, we call $\DoubleBfsCycle(G,s,k,\alpha)$ from every endpoint $s\in V(S_1)$.
% of a sampled edge from $S_1$. 
$\DoubleBfsCycle$ returns either a cycle or a set of vertices $\hat{U}$. If $\DoubleBfsCycle$ returns a cycle then the cycle is returned by $\BFSSampleM$. 
% If 
% $\DoubleBfsCycle$ does not return a cycle 
% then
Otherwise, we add $\hat{U}$ to $\hat{V}$.

If $i>1$ then we call $\BallOrCycle(s, k_i)$, where $k_i=(k+1)-(i-1)\cdot(\alpha-1)$,  from every endpoint $s\in V(S_i)$.
% of a sampled edge from $S_i$.
If a cycle is found by $\BallOrCycle$ then the cycle is returned by $\BFSSampleM$. If $\BallOrCycle$ does not return a cycle then we add $V_{u_j}^{k_i -\alpha}$ to $\hat{V}$.

Right after the inner for-each loop ends, we remove $\hat{V}$ from  $G$, and continue to the next iteration of the main for loop.
If no cycle was found after $y$ iterations, we return $\codeNull$.
Let $\ell \leq y$ be the last iteration in which vertices were removed. Let $\hat{V_i}$ be the set of vertices that were removed during the $i$th iteration, where $\hat{V_i} = \emptyset$ for $i>\ell$.
Let $G_0$ ($G_1$) be  $G$  before (after) running $\BFSSampleM$.
Figure~\ref{fig:BFSSampleMFirstIteration} and Figure~\ref{fig:BFSSampleMIteration} illustrate the key steps of the first and the following iterations of $\BFSSampleM$, respectively. 
We summarize the properties $\BFSSampleM$ in the next lemma. \looseness=-1

\begin{algorithm2e}[t]
\caption{$\BFSSampleM(G,k,\alpha)$}
% \DontPrintSemicolon
\label{BFSSample-M}
    $y \gets \lceil \frac{k+1}{\alpha-1}\rceil-1$\; 

    \For{$i \gets 1$ to $y$}{
        sample a set $S_i$ of $\Tilde{\Theta}(m^\frac{i\cdot(\alpha-1)}{k+1})$ edges\;

        $\hat{V} \gets \emptyset$\;

        \ForEach{$s \in V(S_i)$}{

                \If{$i=1$}{ 
                    $(\hat{U},C) \gets \DoubleBfsCycle(G,s, k, \alpha)$\;

                    \lIf {$C\neq \codeNull$}{\Return $C$}
        	      $\hat{V}\gets \hat{V} \cup    \hat{U} $\;
                }%
                \Else{ %
                    $k_i \gets (k+1)-(i-1)\cdot(\alpha-1)$\;
                    $(V_{s}^{k_i},C) \gets \BallOrCycle(s, k_i)$\;

                    \lIf {$C\neq \codeNull$}{\Return $C$}
        	      $\hat{V}\gets \hat{V} \cup    V_{s}^{k_i-\alpha} $;
                }%
        }
       $G\gets G \setminus \hat{V}$\;
    }
    \Return $\codeNull$;

\end{algorithm2e}


