\begin{lemma}\label{L-BFSSample-M} 
$\BFSSampleM(G,k,\alpha)$ satisfies the following: 
\begin{enumerate} [label=(\roman*)]
\item
If a cycle $C$ is returned then $\wt(C)\leq 2k$
\item
If a cycle is not returned then $|E_u^{(k+1)-y \cdot (\alpha-1)}| 
<
m^{1-\frac{y \cdot (\alpha-1)}{k+1}}$, for every $u\in G_1$, whp
\item
If $u \in G_0 \setminus G_1$ then $u$ is not part of a $C_{\leq 2\alpha}$ in $G_0$
\item $\BFSSampleM(G,k,\alpha)$ runs in $\Ot(\lfloor \frac{k+1}{\alpha-1}\rfloor \cdot
m^{1+\frac{\alpha-1}{k+1}})
$ time, whp.  
\end{enumerate}
\end{lemma}


\begin{proof} 
\begin{enumerate} [label=(\roman*)]
    \item 
    We first show that if a cycle $C$ is returned then $\wt(C)\leq 2k$. 
    $\BFSSampleM$ returns a cycle only if 
    a call to $\DoubleBfsCycle(G, s, k, \alpha)$ returns a cycle or a call to $\BallOrCycle(s, k_i)$, where $2\leq i \leq y$ and $k_i=(k+1)-(i-1)\cdot(\alpha-1)$, returns a cycle. 
    By Lemma~\ref{L-DoubleBfsCycle}, if $\DoubleBfsCycle(G, s, k, \alpha)$ returns a cycle $C$ then $\wt(C)\leq 2k$.
    By Lemma~\ref{L-BallOrCycle}, if $\BallOrCycle(s,k_i)$ returns a cycle $C$ then $\wt(C) \leq 2 k_i$.
    % 2 ((k+1)-(i-1)\cdot(\alpha-1))$.
    Since $i>1$ is an integer, and since $\alpha\geq 2$, we have
    $k_i = (k+1)-(i-1)\cdot(\alpha-1) \leq (k+1)-(\alpha-1)\leq k$. Therefore,  $\wt(C) \leq 2k$.


    \item 
      Next, we show that if a cycle is not returned then $|E_u^{(k+1)-y \cdot (\alpha-1)}| < m^{1-\frac{y \cdot (\alpha-1)}{k+1}}$, for every $u\in G_1$, whp.
      Since $k\geq \alpha$, we have $y\geq 1$ and there is at least one iteration.

     Consider the $i$th iteration of the main loop. 
     We show that if no cycle was found during the $i$th iteration
     then after the $i$th iteration every 
     $u\in G_0\setminus (\cup_{j=1}^{i}\hat{V}_{j})$
     satisfies the following property: $|E_{u}^{(k+1)-i\cdot(\alpha-1)}| < m^{1-\frac{i\cdot(\alpha -1)}{k+1}}$,  whp. 


    Let $u\in G_0\setminus (\cup_{j=1}^{i}\hat{V}_{j})$. 
    By Lemma~\ref{L-whpM}, the set $S_i$ hits the $m^{1-\frac{i\cdot(\alpha-1)}{k+1}}$ closest edges of every vertex of $G_0\setminus (\cup_{j=1}^{i-1}\hat{V}_{j})$, whp. 
    Assume that $S_i$ is indeed such a hitting set, and assume, towards a contradiction, that after the $i$th iteration $|E_{u}^{(k+1)-i\cdot(\alpha-1)}| \geq m^{1-\frac{i\cdot(\alpha -1)}{k+1}}$.
    Since $G_0\setminus (\cup_{j=1}^{i}\hat{V}_{j}) \subseteq G_0\setminus (\cup_{j=1}^{i-1}\hat{V}_{j})$ we have $u\in G_0 \setminus (\cup_{j=1}^{i-1}\hat{V}_{j})$. 
    Now, since  $u\in G_0 \setminus (\cup_{j=1}^{i-1}\hat{V}_{j})$ and since the graph is not updated in the inner for-all loop, it follows that there is an edge $(u_1,u_2) \in S_i$ such that
    $(u_1,u_2) \in E_{u}^{(k+1)-i\cdot(\alpha-1)}$.
     By the definition of $E_{u}^{(k+1)-i\cdot(\alpha-1)}$, either $u_1$ or $u_2$, denoted with $s$, satisfies that $d(u,s)\leq (k+1)-i\cdot(\alpha-1) -1$. By the definition of $V(S_i)$, we know that $s\in V(S_i)$.

     When $i=1$, we have $d(u,s)\leq  (k+1) - i
     \cdot(\alpha-1) -1 = k-\alpha+1$. Therefore, $u\in V_{s}^{k-\alpha+1}$. At the first iteration, when $i=1$, the input graph has not changed yet so $G=G_0$. Since no cycle was found by $\DoubleBfsCycle(G_0,s,k,\alpha)$, it follows from Lemma~\ref{L-DoubleBfsCycle} that $\hat{U} = V_{s}^{k-\alpha+1}$. Therefore,  $u\in \hat{U}$, and $u$ is added to $\hat{V_i}$ after the call to $\DoubleBfsCycle(G_0,s,k,\alpha)$. Hence, $u\notin G_0\setminus (\cup_{j=1}^{i}\hat{V}_i)$, a contradiction.  

     We now handle the case that $i>1$. It holds that $d(u,s)\leq  (k+1)-i\cdot(\alpha-1)-1 = (k+1)-(i-1)\cdot(\alpha-1)- \alpha =k_i-\alpha$.
    % Hence, $u\in V_{s}^{(k+1)-(i-1)\cdot(\alpha-1)-\alpha}$.
    Hence, $u\in V_{s}^{k_i-\alpha}$.
    Since no cycle was found during the $i$th iteration, $u$ is added to $\hat{V_i}$ after the call to 
    % $\BallOrCycle(s, (k+1)-(i-1)\cdot(\alpha-1))$,
    $\BallOrCycle(s, k_i)$,
    and therefore, $u\notin G_0\setminus (\cup_{j=1}^{i}\hat{V}_i)$, a contradiction.  

    Now, if $\BFSSampleM$ does not return a cycle we get for $i=y$ that if $u\in G_0\setminus (\cup_{j=1}^{y}\hat{V}_{j})=G_1$
    then 
    $|E_u^{(k+1)-y \cdot (\alpha-1)}| < m^{1-\frac{y \cdot (\alpha-1)}{k+1}}$, whp. 

   \item 
    Next, we prove that if $u \in G_0 \setminus G_1$ then $u$ is not part of a $C_{\leq 2\alpha}$ in $G_0$.
    Since $u \in G_0 \setminus G_1$ and since $G_1 = G_0 \setminus (\cup_{j=1}^y\hat{V}_j$) it holds that $u\in \hat{V}_i$, where $1\leq i \leq y$.

    If $i=1$ then since $u\in \hat{V}_i$ it follows that there was in the first iteration a vertex $s$ such that $u\in \hat{U}$ after a call to $\DoubleBfsCycle(G_0,s,k,\alpha)$ did not return a cycle. By Lemma~\ref{L-DoubleBfsCycle}, $\hat{U} = V_{s}^{k-\alpha+1}$ and no vertex in $V_s^{k-\alpha+1}$ is part of a $C_{\leq 2\alpha}$ in $G_0$. Therefore, $u$ is not part of  a $C_{\leq 2\alpha}$ in $G_0$.

    If $i>1$ then since $u\in \hat{V}_i$ it follows that there was in the $i$th iteration a vertex $s$ such that 
    % $u\in V_{s}^{(k+1)-(i-1)\cdot(\alpha-1)-\alpha}$
    $u\in V_{s}^{k_i-\alpha}$
    after a call to $\BallOrCycle(s, k_i)$ did not return a cycle.
    As $\BallOrCycle(s, k_i)$ did not return a cycle, by Lemma~\ref{L-BallOrCycle} we know that $B(s,k_i)$ is a tree.
    It follows from Lemma~\ref{L-not-part-of} that no vertex in $V_{s}^{k_i-\alpha}$, and in particular $u$, is part of a $ C_{\leq2\alpha}$ in $G_0 \setminus (\cup_{j=1}^{i-1}\hat{V}_{j})$.
    Since during the run of $\BFSSampleM$ we remove only vertices that are not part of a $ C_{\leq2\alpha}$, $u$ is not part of a $C_{\leq 2\alpha}$ also in $G_0$.

    \item
    Finally, we show that $\BFSSampleM$ runs in  $\Ot(\lfloor \frac{k+1}{\alpha-1}\rfloor \cdot
    m^{1+\frac{\alpha-1}{k+1}})
    $ time, whp.
    To do so, we show that the running time of the $i$th iteration of the main for loop is whp $\Ot(m^{1+\frac{\alpha-1}{k+1}})$.
    % \blue{Since $k\geq \alpha$, we have $y\geq 1$, and there is at least one iteration.}

    We start with the first iteration, in which $i=1$. The size of $S_1$ is $\Tilde{\Theta}(m^{\frac{\alpha-1}{k+1}})$. 
    The size of $V(S_1)$ is at most $2\cdot |S_1|$. 
    For every $s\in V(S_1)$ we run $\DoubleBfsCycle(G_0,s, k, \alpha)$.
    By Lemma \ref{L-DoubleBfsCycle-time}, running $\DoubleBfsCycle$ from $s$ costs $O(n+m)=O(m)$.
    Adding $\hat{U}$ to $\hat{V}$ costs $O(n) = O(m)$. 
    Therefore, the total running time for all $s\in V(S_1)$ is at most $ 2\cdot |S_1|\cdot O(m) = 
       \Tilde{O}(m^{\frac{\alpha-1}{k+1}}\cdot m) = 
       \Tilde{O}(m^{1+\frac{\alpha-1}{k+1}})$.


    Now we assume that $i>1$.
    We proved in (ii) that if $i > 1$ and $u\in G_0\setminus (\cup_{j=1}^{i-1}\hat{V}_{j})$ then after the $(i-1)$th iteration, if no cycle was found, we have $|E_{u}^{(k+1)-(i-1)\cdot(\alpha-1)}| < m^{1-\frac{(i-1)\cdot(\alpha -1)}{k+1}}$,  whp.
    By Lemma~\ref{L-BallOrCycle}, for every $s\in V(S_i)$, the cost of running 
     $\BallOrCycle(s, k_i)$ is $O(|V_{s}^{k_i}|) = 
     O(|E_{s}^{k_i}|)=
     O(|E_{s}^{(k+1)-(i-1)\cdot(\alpha-1)}|)$. In our case this is at most $O(m^{1-\frac{(i-1)\cdot(\alpha -1)}{k+1}})$.
     As the size of $S_i$ is $\Tilde{\Theta}(m^\frac{i\cdot(\alpha-1)}{k+1})$ and the size of $V(S_i)$ is at most $2\cdot |S_i|$, the total running time of the calls to $\BallOrCycle$ for every $s\in V(S_i)$ is, whp,
         $
         2\cdot |S_i| \cdot O(m^{1-\frac{(i-1)\cdot(\alpha -1)}{k+1}}) =
        \Tilde{\Theta}(m^\frac{i\cdot(\alpha-1)}{k+1}) \cdot O(m^{1-\frac{(i-1)\cdot(\alpha -1)}{k+1}}) =\tilde{O}(m^{1+\frac{\alpha-1}{k+1}}).
        $


       The cost of adding $V_{s}^{k_i-\alpha}$ to $\hat{V}$ is $O(|V_{s}^{k_i-\alpha}|) $. This is at most $O(|V_{s}^{k_i}|) = O(m^{1-\frac{(i-1)\cdot(\alpha -1)}{k+1}})$ (whp), which is $\tilde{O}(m^{1+\frac{\alpha-1}{k+1}})$ for all $s\in V(S_i)$ (similarly to the previous calculation).

       The cost of removing a vertex $v$ is $O(deg(v))$. Thus, for every $i\geq 1$, the total cost of removing all the vertices in $\hat{V_i}$ is at most $O(m)$,    
        so the total running time of the $i$th iteration is $\tilde{O}(m^{1+\frac{\alpha-1}{k+1}})$, whp.

        If we are in the scenario that a cycle is returned, then the $i$th iteration  stops at an earlier stage, and therefore the running time is also $\tilde{O}(m^{1+\frac{\alpha-1}{k+1}})$.

        Now, since there are at most $y$ iterations of the main for loop, the running time of $\BFSSampleM$ is, whp\footnote{This is the running time in the case that $S_i$ was a hitting sets as described for every $1\leq i \leq y$. This happens whp since 
        we assume that
        $k < \frac{n}{2} < n$ and 
        % thus
        therefore 
        % also 
        $y < n$. For every $1\leq i \leq y$ the probability that $S_i$ is not such a hitting set is at most $\frac{1}{n^c}$. Therefore, using the standard union bound argument, the probability that there exists $1\leq i \leq y$ such that $S_i$ is not a hitting set is at most $y \cdot \frac{1}{n^c} \leq 
        % n \cdot \frac{1}{n^c} =
        \frac{1}{n^{c-1}}$. For large enough $c$, we get that $S_i$ is a hitting set for every $1\leq i \leq y$, whp.}, $\tilde{O}(y\cdot m^{1+\frac{\alpha-1}{k+1}}) = \Ot(\lfloor \frac{k+1}{\alpha-1}\rfloor \cdot
    m^{1+\frac{\alpha-1}{k+1}})$. \qedhere
\end{enumerate}
\end{proof}



Recall that our goal is to obtain the sparsity property that
$|E_u^{\alpha-1}| < m^{\frac{\alpha-1}{k+1}}$, for every $u\in V$, so that we can run $\dHybrid(G,\alpha)$.   
However, after running $\BFSSampleM$ the required sparsity property is guaranteed to hold (whp) only if $(k+1) \bmod (\alpha-1)  = 0$. 
% If this is not the case,
In the case that $(k+1) \bmod (\alpha-1)  \neq 0$  we need an additional  step which is implemented in $\HandleReminderM$,  to guarantee  that the required sparsity property holds. \looseness=-1




Next, we formally describe $\HandleReminderM$. 
$\HandleReminderM$ (see Algorithm~\ref{A-handleRM}) gets a graph $G$ and two integers $\alpha,k \geq 2$ such that $k+1=q(\alpha-1)+r$ where $q\geq 1$ and $r>0$.
% In $\HandleReminderM$, we set   
We  set
$D$ to $m^{\frac{1}{k+1}}$ and $r$ to $(k+1) \bmod (\alpha-1)$. 
Then,  a while loop runs as long as $(\alpha-1) \bmod r \neq 0$. 
Let $r_i$ be
the value of $r$ when the $i$th iteration
% of the loop 
begins, so that $r_1$ is $ (k+1) \bmod (\alpha-1)$. 
% We denote with $\ell$ 
Let $\ell$ be
the total number of iterations
% of the loop 
and
% with $r_{\ell +1}$ 
$r_{\ell +1}$
the value of $r$ after the $\ell$th iteration.
During the $i$th iteration, we set $r_{i+1}$ to 
$(\lceil \frac{\alpha-1}{r_i} \rceil \cdot r_i) - (\alpha-1)$, where $\lceil \frac{\alpha-1}{r_i} \rceil \cdot r_i$ is the smallest multiple of $r_i$ that is at least $\alpha-1$ (see Figure~\ref{fig:r-jumps-M}).
Then, we call $\SparseOrCycleM(G, D, r_{i+1}, \alpha)$.
If $\SparseOrCycleM$ returns a cycle $C$ then $\HandleReminderM$ returns $C$.
 If $\SparseOrCycleM$ does not return a cycle then it might be that some vertices were removed from $G$, and we continue to the next iteration.
 % of the while loop. 
If the while loop ends without returning a cycle then we return $\codeNull$.
Let $G_0$ ($G_1$) be  $G$  before (after) running $\HandleReminderM$.
Next, we prove two properties on the value of  $r$ during the run of  $\HandleReminderM$.



\begin{algorithm2e}[t]
\caption{$\HandleReminderM(G,k,\alpha)$}
% \DontPrintSemicolon
\label{A-handleRM}

    $D\gets m^{\frac{1}{k+1}}$\;

    $r \gets (k+1) \bmod (\alpha-1)$\;


    \While{ $(\alpha-1) \bmod r \neq 0$ } 
    {

        $r\gets (\lceil \frac{\alpha-1}{r} \rceil \cdot r) - (\alpha-1)$\; 

        $C\gets \SparseOrCycleM(G, D, r, \alpha)$\;

        \lIf {$C\neq \codeNull$}{\Return $C$}

    } 

    \Return $\codeNull$\;

\end{algorithm2e}

\begin{claim} \label{C-remindersM} 
Let $k+1 = q(\alpha-1)+r_1$ and assume  $r_1>0$. \textbf{(i)} $0 < r_{\ell+1} < r_{\ell} < \cdots < r_1 <\alpha-1$. \textbf{(ii)} ($r_{i+1} + \alpha-1) \bmod  r_i = 0$, for every $1\leq i\leq \ell$.

\end{claim}




\begin{proof}
\begin{enumerate} [label=(\roman*)]
\item 
 First, since $r_1 = (k+1) \bmod (\alpha-1)$ and we assume that $r_1>0$, we have $0 < r_1 < \alpha-1$.
Now we show that $0 < r_{i+1}<r_i$, for every $1 \leq i \leq \ell$.  
This implies that  $0 < r_{\ell+1} < r_{\ell} < \cdots < r_1 <\alpha$, as required.

We first show by induction that $r_i>0$, for every $1 \leq i \leq \ell$. The base of the induction follows from the assumption that $r_1 > 0$. We assume that $r_{i}>0$ and prove that $r_{i+1}>0$. 
During the $i$th iteration of the while loop, we set $r_{i+1}$ to 
$(\lceil \frac{\alpha-1}{r_i} \rceil \cdot r_i) - (\alpha-1)$. 
Since this occurs during  the $i$th iteration it must be that $(\alpha-1) \bmod r_i \neq 0$, as otherwise the $i$th iteration would not have started.
Since $(\alpha-1) \bmod r_i \neq 0$ we have $\lceil\frac{\alpha-1}{r_i}\rceil>\frac{\alpha-1}{r_i}$ and therefore, 
$\lceil \frac{\alpha-1}{r_i} \rceil \cdot r_i > \alpha - 1$.
We get that 
$r_{i+1} = (\lceil \frac{\alpha-1}{r_i} \rceil \cdot r_i) - (\alpha-1) >0$, as required.

We now turn to prove that $r_{i+1}<r_i$.
As $\lceil \frac{\alpha-1}{r_i} \rceil \cdot r_i$ is the smallest multiple of $r_i$ that is at least $\alpha-1$, we know that 
 $(\lceil\frac{\alpha-1}{r_i}\rceil -1)\cdot r_i = \lceil\frac{\alpha-1}{r_i}\rceil\cdot r_i -r_i < \alpha-1$.
 Therefore, $\lceil\frac{\alpha-1}{r_i}\rceil\cdot r_i - (\alpha-1) < r_i$. Since $r_{i+1} = \lceil\frac{\alpha-1}{r_i}\rceil\cdot r_i -(\alpha-1)$, we get that $r_{i+1}<r_i$.


\item
Let $1\leq i\leq \ell$. Since $ r_{i+1} = \lceil\frac{\alpha-1}{r_i}\rceil\cdot r_i -(\alpha-1)$, it follows that $ r_{i+1} +(\alpha-1)$ is a multiple of $r_i$, so   ($r_{i+1} + \alpha-1) \bmod  r_i = 0$.  \qedhere
 \end{enumerate}
\end{proof}



