We now prove the main lemma regarding $\HandleReminderM$.


\begin{lemma}\label{L-HandleReminderM}
Let $k+1 = q(\alpha-1)+r_1$ and assume that $r_1>0$, $q\geq 1$,  and  that $|E_u^{r_{1}}| < D^{r_{1}}$, for every $u\in V$.
$\HandleReminderM(G,k,\alpha)$ 
satisfies the following: 
\begin{enumerate} [label=(\roman*)]
\item If a cycle $C$ is returned then $\wt(C)\leq 2k$
\item If a cycle is not returned then
$|E_u^{\alpha-1}| < D^{\alpha-1}$, for every vertex $u\in G_2$
\item 
If $u \in G_1 \setminus G_2$ 
then $u$ is not on a $C_{\leq 2\alpha}$ in  $G_1$
\item 
$\HandleReminderM(G,k,\alpha)$ runs in $O(r_1\cdot m^{1+\frac{\alpha-1}{k+1}})$ time.
\end{enumerate}
\end{lemma}



\begin{proof}
\begin{enumerate} [label=(\roman*)]
    \item
    First, we show that if a cycle $C$ is returned then $\wt(C) \leq 2k$.     
   $\HandleReminderM$  returns  a cycle only if a call  to $\SparseOrCycleM(G, D, r_{i+1}, \alpha)$, where $1\leq i \leq \ell$, returns  a cycle. 
   By Lemma~\ref{L-SparseOrCycleM}, if $\SparseOrCycleM(G, D, r_{i+1}, \alpha)$ returns a cycle $C$ then $\wt(C)\leq 2(r_{i+1} -1 +\alpha)$. 
    By Claim~\ref{C-remindersM}(i), $r_{i+1} < r_1$.
    In addition, since $k+1 =q(\alpha-1) +r_1$ with $q\geq 1$, 
     we have $r_{i+1} -1 +\alpha < r_{1} -1 +\alpha = (\alpha-1) + r_{1} \leq k+1$.
    As $r_{i+1} -1 +\alpha$ and $k$ are integers, we have $r_{i+1} -1 +\alpha \leq k$.
    Therefore, $\wt(C)\leq 2(r_{i+1} -1 +\alpha) \leq 2k$.


    \item
    Next, we show that if a cycle is not returned then
    $|E_u^{\alpha-1}| < D^{\alpha-1}$, for every vertex $u\in G_2$.
    To do so, we show that if $\HandleReminderM$ does not return a cycle then when the algorithm ends, for every vertex $u \in G_2$ we have $|E_u^{r_{\ell+1}}| < D^{r_{\ell+1}}$.

     If we do not enter the while loop and $\ell=0$ then by our assumption $|E_u^{r_{1}}| < D^{r_{1}}$, for every $u\in V$, as required.
    Now we assume that we enter the loop so $\ell>0$.
    Consider the $i$th iteration of the while loop. During the $i$th iteration $\SparseOrCycleM(G,D,r_{i+1},\alpha)$ is called. 
    If $\SparseOrCycleM$ does not return a cycle, then it follows from  Lemma~\ref{L-SparseOrCycleM} that if $u\in \hat{V}$ ($u$ was not removed) then  $|E_u^{r_{i+1}}| < D^{r_{i+1}}$. 
    Therefore, if no cycle was returned by $\HandleReminderM$ we get for $i=\ell$ that after the $\ell$th iteration, we have $|E_u^{r_{\ell+1}}| < D^{r_{\ell+1}}$, for every $u \in G_2$. 

    The while loop ends when $(\alpha-1) \bmod r = 0$. Therefore, we know that after the while loop, $(\alpha-1) \bmod r_{\ell +1} = 0$. 
    Additionally,  By Claim~\ref{C-remindersM}(i) $ r_{\ell +1} < \alpha - 1$, so there is $z>0$ such that $\alpha - 1  = zr_{\ell +1}$. By Corollary~\ref{C-SumOfDenseM}, since $|E_u^{r_{\ell+1}}| < D^{r_{\ell+1}}$, we know that $|E_u^{\alpha-1}| = |E_u^{zr_{\ell +1}}| < D^{{zr_{\ell +1}}} = 
    D^{\alpha-1}$, as required.

    \item
    Next, we prove that if $u \in G_1 \setminus G_2$ then $u$ is not on a $C_{\leq 2\alpha}$ in  $G_1$.
    If $u \in G_1 \setminus G_2$ then by the definition of $G_1$ and $G_2$, $u$ was removed while executing  $\HandleReminderM$.
    During the run of $\HandleReminderM$, a vertex can be removed only by $\SparseOrCycleM(G, D, r_{i+1}, \alpha)$ for some $1\leq i \leq \ell$.
    Therefore, by Lemma~\ref{L-SparseOrCycleM}, $u$ is not part of a $ C_{\leq2\alpha}$ in $G$.
    Since during the run of $\HandleReminderM$  only vertices that are not part of a $C_{\leq2\alpha}$ are removed, $u$ is not part of a $C_{\leq 2\alpha}$ also in $G_1$.

    \item
    Finally, we show that $\HandleReminderM$ runs in $O(r_1\cdot m^{1+\frac{\alpha-1}{k+1}})$ time.
    To do so, we show that the running time of the $i$th iteration of the while loop is $O(m^{1+\frac{\alpha-1}{k+1}})$. When $\ell=0$ there are no iterations and the running time is $O(1)$. Now we assume that $\ell>0$.
   During the $i$th iteration, we call $\SparseOrCycleM(G, D, r_{i+1}, \alpha)$. 
   We proved in (ii) that for $i > 1$ if $\SparseOrCycleM$ did not return a cycle during the $(i-1)$th iteration and $u\in \hat{V}$ ($u$ was not removed) then after the $(i-1)$th iteration $|E_u^{r_{i}}| < D^{r_{i}}$. For $i=1$ by our assumption $|E_u^{r_{1}}|  < D^{r_{1}}$.
    Therefore, before the $i$th iteration starts, by Corollary~\ref{C-SumOfDenseM}, $|E_u^{zr_{i}}| < D^{zr_{i}}$ for every integer $z>0$.  By Claim~\ref{C-remindersM}(ii), $r_{i+1}-1+\alpha$ is divisible by $r_i$, so $|E_u^{r_{i+1}-1+\alpha}|  < 
    D^{r_{i+1}-1+\alpha}$ for every vertex $u$.
    It then follows from Corollary~\ref{C-SparseOrCycle-sparse-time} that $\SparseOrCycleM(G, D, r_{i+1}, \alpha)$ runs in $O(nD^{r_{i+1}}+mD^{\alpha-1})$ time.
    By Claim~\ref{C-remindersM}(i), $r_{i+1} < \alpha-1$ so $O(nD^{r_{i+1}}+mD^{\alpha-1})\leq 
    O(mD^{\alpha-1})=
    O(m^{1+\frac{\alpha-1}{k+1}})$, and the running time of the $i$th iteration is $O(m^{1+\frac{\alpha-1}{k+1}})$.   
    Now, it follows from Claim~\ref{C-remindersM}(i) that after at most $r_1 < \alpha-1$ iterations, the value of $r$ cannot decrease anymore (since it cannot become less than $1$, and $(\alpha-1) \bmod 1 = 0$) so the while loop ends. As we saw, the running time of each iteration is $O(m^{1+\frac{\alpha-1}{k+1}})$, hence the total running time of the while loop is $O(r_1 \cdot m^{1+\frac{\alpha-1}{k+1}})$. \qedhere
    \end{enumerate}
\end{proof}





Now we are ready to prove the correctness and running time of $\SrtCycSpr$. 


\begin{lemma} \label{L-shortCycleSparse}
    % \red{Let $\alpha\geq2$ and let  $k\geq 2$} 
   Let $2\leq \alpha \leq k < \frac{n}{2}$
    such that 
    $k +1 = q (\alpha-1)+r$, 
    where $q\geq 1$ and $0\leq r < \alpha-1$ are integers.
    Algorithm $\SrtCycSpr(G,k,\alpha)$ runs whp in $\tilde{O}((q+r) \cdot m^{1+\frac{\alpha-1}{k+1}})$
    time and either returns a $C_{\leq 2k}$, or determines that $g > 2\alpha$.
\end{lemma}


\begin{proof} 


First, $\SrtCycSpr(G,k,\alpha)$ returns a cycle $C$ only if $\BFSSampleM(G,k,\alpha)$, $\HandleReminderM(G,k,\alpha)$, or $\dHybrid(G,\alpha)$ returns a cycle $C$. 
If $\BFSSampleM$ or $\dHybrid$ returns a cycle $C$ then by Lemma~\ref{L-BFSSample-M} or by Lemma~\ref{L-dHybrid-properties}, $\wt(C)\leq 2k$.
If $\HandleReminderM$ returns a cycle $C$ then by Lemma \ref{L-HandleReminderM}, since $k\geq \alpha$ and hence $q\geq 1$,  $\wt(C)\leq 2k$.

Second, we show that if no cycle was found then $g>2\alpha$.
If no cycle was found then it might be that some vertices were removed from the graph.
A vertex $u$ can be removed either by  $\BFSSampleM$ or by $\HandleReminderM$.  It follows from Lemma~\ref{L-BFSSample-M} and Lemma~\ref{L-HandleReminderM}, that $u$ is not part of a $C_{\leq 2\alpha}$ when $u$ is removed. Since only vertices that are not on a $C_{\leq 2\alpha}$ are removed, every $C_{\leq 2\alpha}$ that was in the input graph also belongs to the updated graph. 
After the (possible) removal of vertices, we call $\dHybrid(G,\alpha)$ with the updated graph. Since we are in the case that no cycle was found, $\dHybrid$ did not return a cycle. It follows from Lemma~\ref{L-dHybrid-properties} that $g>2\alpha$ in the updated graph, and therefore $g>2\alpha$ also in the input graph.

Now we turn to analyze the running time of $\SrtCycSpr$.
At the beginning, $\SrtCycSpr$ calls $\BFSSampleM$.
By Lemma~\ref{L-BFSSample-M}, $\BFSSampleM$ runs in $\Ot(\lfloor \frac{k+1}{\alpha-1}\rfloor \cdot
    m^{1+\frac{\alpha-1}{k+1}}) = \Ot(q \cdot m^{1+\frac{\alpha-1}{k+1}})$ time.
Let $G_1$ be the graph after the call to $\BFSSampleM$.
Recall that $y=\lceil \frac{k+1}{\alpha-1}\rceil-1$. By Lemma~\ref{L-BFSSample-M},
  for every $u\in G_1$ we have $|E_u^{(k+1)-y \cdot (\alpha-1)}| < m^{1-\frac{y \cdot (\alpha-1)}{k+1}}$, whp.
 If $r>0$ then $y=q$ and $|E_u^{r}| < m^{\frac{r}{k+1}}$.  
 If $r=0$ then $y=q-1$ and $|E_u^{\alpha-1}| < m^{\frac{\alpha-1}{k+1}}$.


Next, $\SrtCycSpr$ checks if $r = (k-1) \bmod (\alpha-1) > 0$. 
We divide the rest of the proof  to the case that $r = 0$ and to the case that $r > 0$. 
If $r = 0$ then $\SrtCycSpr$ calls $\dHybrid$. 
Since $r = 0$, we have $|E_u^{\alpha-1}| < m^{\frac{\alpha-1}{k+1}}$ after $\BFSSampleM$.
By Corollary~\ref{C-dHybrid-sparse-time}, the running time of $\dHybrid$ is $O(m\cdot m^{\frac{\alpha-1}{k+1}}) = O(m^{1+\frac{\alpha-1}{k+1}})$.

We now turn to the case that $r > 0$. 
In this case it might be that $|E_u^{\alpha-1}| \geq m^{\frac{\alpha-1}{k+1}}$ for some vertices $u\in G_1$. 
Therefore, we first call $\HandleReminderM(G,k,\alpha)$, knowing that $r>0$, $q\geq 1$ and that whp, $|E_u^{r}| < m^{\frac{r}{k+1}}$ after $\BFSSampleM$.
By Lemma~\ref{L-HandleReminderM}, the running time is $O(r\cdot m^{1+\frac{\alpha-1}{k+1}})$.
Let $G_2$ be the graph after $\HandleReminderM$ ends.  By Lemma~\ref{L-HandleReminderM}, for every $u\in G_2$ we have $|E_u^{\alpha-1}| < D^{\alpha-1}$, where $D = m^{\frac{1}{k+1}}$.
Now $\SrtCycSpr$ calls $\dHybrid$, and using  Corollary~\ref{C-dHybrid-sparse-time} again, we get that the running time of $\dHybrid$ is $O(m\cdot m^{\frac{k-1}{k+1}}) = O(m^{1+\frac{k-1}{k+1}})$.


It follows from the above discussion that $\SrtCycSpr$ either returns a $C_{\leq 2k}$ or determines that $g>2\alpha$, and
the running time is whp\footnote{
    Throughout the run of $\SrtCycSpr$, some of the bounds that we get on $|E_v^d|$ for vertices $v\in V$ and distances $d$, are whp, because the sets that we sample are hitting sets whp (see the proof of Lemma~\ref{L-BFSSample-M}). Therefore, also the running times of $\BFSSampleM$, $\HandleReminderM$ and $\dHybrid$ are whp, since they rely on these bounds.
    }
    $\Ot(( q+r) \cdot
    m^{1+\frac{\alpha-1}{k+1}})$.
\end{proof}

Since $\SrtCycSpr$ is run by $\OneAlg$ when $m\leq O(n^{1+\frac{1}{k}})$ and when 
% $\alpha-1\leq k+1$
$\alpha\leq k$
and so $1+\frac{\alpha-1}{k+1}\leq 2$, we have $m^{1+\frac{\alpha-1}{k+1}}\leq O(n^{1+\frac{\alpha}{k}})$. Thus, the running time of $\SrtCycSpr$ is whp $\Ot(( q+r) \cdot
   \min\{ m^{1+\frac{\alpha-1}{k+1}},
    n^{1+\frac{\alpha}{k}}
   \})$,
    which is at most 
   $\Ot(( \frac{k+1}{\alpha-1}+\alpha) \cdot
   \min\{ m^{1+\frac{\alpha-1}{k+1}},
    n^{1+\frac{\alpha}{k}}
   \})$.




\subsubsection{Algorithm SpecialCases} \label{subsec:special}


 We now present algorithm $\SpCase$ that handles special cases of $k$ and $\alpha$.
$\SpCase(G,k,\alpha)$ gets as an input a graph $G$ and two integers $k\geq 2$ and $\alpha \geq 2$.

If $k\geq \frac{n}{2}$, the algorithm simply runs $\BallOrCycle(G,w,n)$ from an arbitrary vertex $w\in V$ in $O(n)\leq O(\min\{m^{1+\frac{\alpha-1}{k+1}},n^{1+\frac{\alpha}{k}}\})$ time, to check whether $G$ contains a cycle.  If a cycle is found then its length is at most $n\leq 2k$, and we return a $C_{\leq 2k}$. Otherwise, $g=\infty$ so for every integer $\alpha$ we return that $g>2\alpha$.

If $k \leq \alpha -1$, we check if the graph contains a $C_d$ for $d\gets 3,..., 2\alpha$, using an algorithm of Alon, Yuster and Zwick \cite{alon1997finding}. Their algorithm decides whether $G$ contains $C_{2 \ell-1}$s and $C_{2 \ell}$s, and finds such cycles if it does, in $O(m^{2-\frac{1}{\ell}})$ time.
Applying this algorithm with increasing cycle lengths until a length of $2\alpha$ (the values of $\ell$ are in the worst case $2,3,...,\alpha$), we can either find the shortest cycle or determine that $g> 2\alpha$.
The running time is $O(m^{2-\frac{1}{2}}+m^{2-\frac{1}{3}}+\dots m^{2-\frac{1}{\alpha}})= O(\alpha \cdot m^{2-\frac{1}{\alpha}}) = O(\alpha \cdot  m^{1+\frac{\alpha-1}{\alpha}})$ time\footnote{It is possible to modify the algorithm of Alon \etal{} \cite{alon1997finding} to search in $O(m^{2-\frac{1}{\ell}})$ time a shortest cycle of length \textit{at most} $2\ell$ instead of \textit{exactly} $2\ell-1$ or $2\ell$, and then run it only with $\ell = \alpha$, to avoid the $\alpha$ factor in the running time. 
% \red{Such a search can be done by running a version of BFS up to depth $\alpha$ from every vertex $v$ in $O(|E_v^{\alpha}|)$ time, starting with the high degree vertices (according to the definition of ~\cite{alon1997finding}), then removing them, and then continuing with the other vertices, and returning the shortest cycle that was found or nothing if no cycle was found.}
}.
Since $k\leq \alpha-1$, we have $k+1 \leq \alpha$ and therefore $O(\alpha\cdot m^{1+\frac{\alpha-1}{\alpha}}) \leq O(\alpha\cdot m^{1+\frac{\alpha-1}{k+1}})$.
In addition, since $m\leq O(n^{1+\frac{1}{k}})$ and since $1+\frac{\alpha-1}{\alpha}\leq 2$, we have $m^{1+\frac{\alpha-1}{\alpha}} \leq O(n^{(1+\frac{1}{k})\cdot (1+\frac{\alpha-1}{\alpha})})
\leq
O(n^{(1+\frac{1}{k})\cdot (1+\frac{\alpha-1}{k+1})}) 
=
O(n^{1+\frac{\alpha}{k}})
$.
Therefore, the running time is $O(\alpha\cdot m^{1+\frac{\alpha-1}{\alpha}})\leq O(\alpha\cdot \min\{m^{1+\frac{\alpha-1}{k+1}},n^{1+\frac{\alpha}{k}}\})$.

By choosing which algorithm to run according to the  relation between $k$, $\alpha$ and $\frac{n}{2}$, we get that for every two integers $\alpha\geq2$ and  $k\geq 2$, algorithm $\OneAlg(G,k,\alpha)$ runs whp in $\Ot((\frac{k+1}{\alpha-1}+\alpha) \cdot \min\{m^{1+\frac{\alpha-1}{k+1}},n^{1+\frac{\alpha}{k}}\})$ time 
and either returns a $C_{\leq \max\{2k,g\}}$, or determines that $g > 2\alpha$.
This completes the proof of Theorem~\ref{Thm-One-Alg}.



\section{Approximation of the girth}\label{sec:girth-approx}

In this section we present two new  tradeoffs for girth approximation that follow from  Corollary~\ref{C-shortCycleBigK}. 
In these tradeoffs we use $\OneAlg$ with  $2\leq \alpha \leq k$, so by Corollary~\ref{C-shortCycleBigK}, $\OneAlg$ is a $\tilde{O}((\frac{k+1}{\alpha-1}+\alpha) \cdot \min \{m^{1+\frac{\alpha-1}{k+1}},n^{1+\frac{\alpha}{k}}\})$-time, $(2k,2\alpha)$-hybrid algorithm.


\subsection{Dense graphs}
% \textbf{Dense graphs.}
Kadria \etal{} \cite{kadria2022algorithmic} presented an  $O((\alpha-c)\cdot n^{1+\frac{\alpha}{2\alpha - c}})$-time algorithm that either returns a $C_{\leq 4\alpha-2c}$, or determines that $g>2\alpha$, where $0 < c \leq \alpha$ are two integers. This is a $(4\alpha-2c, 2\alpha)$-hybrid algorithm which, combined with a binary search, was used by \cite{kadria2022algorithmic} 
% They \cite{kadria2022algorithmic} combined this $(4\alpha-2c, 2\alpha)$-hybrid algorithm with a binary search 
to compute for every $\varepsilon\in (0,1]$ a cycle $C$  such that $\wt(C) \leq 4\lceil \frac{g}{2}\rceil  - 2\lfloor \varepsilon \lceil \frac{g}{2}\rceil \rfloor \leq (2-\varepsilon)g+4$, in $\tO(n^{1+1/(2-\varepsilon)})$ time, if $g\leq \log^2 n$.
We use $\OneAlg$ in a similar way  and prove:
% \blue{The proof is similar to the corresponding proof of \cite{kadria2022algorithmic}.}

\begin{theorem}\label{L-approx-n}
    Let $\Ynew\geq 2$ be an integer, $\varepsilon\in [0,1]$ and  $g\leq \log^2 n$.
   It is possible to compute, whp, in    $\tO(\Ynew\cdot n^{1+1/(\Ynew-\varepsilon)})$ time, a cycle $C$ such that $\wt(C) \leq 2\Ynew\lceil \frac{g}{2}\rceil  - 2\lfloor \varepsilon \lceil \frac{g}{2}\rceil \rfloor \leq
(\Ynew-\varepsilon)g+\Ynew+2$.
\end{theorem}


\begin{proof}
For each $\tilde{g}$ in the range $[3,\log^2 n]$ in increasing order, we call $\OneAlg(G,k(\alpha_{\tilde{g}}), \alpha_{\tilde{g}})$, where $\alpha_{\tilde{g}} = \lceil \frac{\tilde{g}}{2}\rceil$, and $k(\alpha) = \Ynew\alpha - \lfloor \varepsilon\alpha \rfloor$.
When we find the smallest value $\tilde{g}$ for which $\OneAlg$ returns a cycle, we stop and return that cycle. 
Since $\Ynew\geq 2$ and $\varepsilon\leq 1$ we have $k(\alpha_{\tilde{g}})\geq \alpha_{\tilde{g}}$, and it follows from Corollary~\ref{C-shortCycleBigK} that $\OneAlg$ either returns a $C_{\leq 2k(\alpha_{\tilde{g}})}$ or determines that $g> 2\alpha_{\tilde{g}}\geq \tilde{g}$ in  $\tilde{O}((\frac{k(\alpha)+1}{\alpha-1}+\alpha) \cdot n^{1+\frac{\alpha}{k(\alpha)}})$ time, whp.


We first prove that the algorithm returns a cycle $C$ such that $\wt(C) \leq 2\Ynew\lceil \frac{g}{2}\rceil  - 2\lfloor \varepsilon \lceil \frac{g}{2}\rceil \rfloor \leq
(\Ynew-\varepsilon)g+\Ynew+2$.
Let $g'$ be the smallest value $\tilde{g}$ for which $\OneAlg$ returned a cycle. This implies that for $g'-1$ the algorithm did not return a cycle, and hence $g>g'-1$. Since $g$ and $g'$ are integers, we have $g\geq g'$. Also for $g'=3$ we have $g\geq g'$ since the girth is at least $3$.

The call to $\OneAlg(G,k(\alpha_{g'}),\alpha_{g'})$ returns a cycle $C$
such that  $\wt(C)\leq 2 k(\alpha_{g'}) =
2\cdot (\Ynew\alpha_{g'} - \lfloor \varepsilon \alpha_{g'} \rfloor) = 
2\cdot \Ynew \lceil \frac{g'}{2} \rceil - 2\cdot \lfloor \varepsilon \lceil \frac{g'}{2} \rceil \rfloor
\leq 
2 \Ynew \lceil \frac{g}{2} \rceil - 2 \lfloor \varepsilon \lceil \frac{g}{2} \rceil \rfloor
$. 
Thus, $\wt(C)\leq 2\Ynew\lceil \frac{g}{2}\rceil  -  2 \lfloor \varepsilon \lceil \frac{g}{2} \rceil \rfloor \leq
2\Ynew\lceil \frac{g}{2}\rceil - 2\lfloor \varepsilon \frac{g}{2} \rfloor
\leq 
2\Ynew\lceil \frac{g}{2}\rceil - 2( \varepsilon \frac{g}{2} -1) 
\leq
2\Ynew \frac{g+1}{2} - \varepsilon g +2
=
\Ynew g+\Ynew - \varepsilon g +2 = (\Ynew-\varepsilon)g +\Ynew+2
$.


For the running time, there are at most $O(\log^2 n
% \red{\log(\log^2 n)}
)$ calls to $\OneAlg$, and each call costs $\tilde{O}((\frac{k(\alpha)+1}{\alpha-1}+\alpha) \cdot n^{1+\frac{\alpha}{k(\alpha)}})$ whp (with the values of $k$ and $\alpha$ that correspond to that call).
 In each call,
 $ \frac{k(\alpha)+1}{\alpha-1} 
 = 
 \frac{\Ynew\alpha-\lfloor \varepsilon \alpha \rfloor+1}{\alpha-1}
 \leq 
  \frac{\Ynew\alpha+1}{\alpha-1}
 $ which is at most $2\Ynew+1$ since $\alpha \geq 2$.
In addition, $n^{1+\frac{\alpha}{k(\alpha)}} = n^{1+\frac{\alpha}{\Ynew\alpha-\lfloor \varepsilon \alpha \rfloor}} \leq 
n^{1+\frac{\alpha}{\Ynew\alpha- \varepsilon \alpha }} = 
n^{1+\frac{1}{\Ynew- \varepsilon}}
$. Thus, the running time of each call is 
$\tilde{O}((\Ynew+\alpha) \cdot n^{1+\frac{1}{\Ynew- \varepsilon}})$ whp, which is $\tilde{O}(\Ynew\cdot n^{1+\frac{1}{\Ynew- \varepsilon}})$ since $\alpha \leq \log^2 n$ in each call. Therefore, the total running time is, whp\footnote{The running time of each call to $\OneAlg$ is whp. 
Since the number of calls to $\OneAlg$ is at most $\log^2 n < n$, using a union bound argument as in the proof of Lemma \ref{L-BFSSample-M} we get that
also the total running of all the calls is whp.}, $\tilde{O}(
\log^2 n
\cdot \Ynew\cdot n^{1+\frac{1}{\Ynew- \varepsilon}}) = \tilde{O}(\Ynew\cdot n^{1+\frac{1}{\Ynew- \varepsilon}})$.
\end{proof}

 Our algorithm can be viewed as a natural generalization of a couple of algorithms from \cite{kadria2022algorithmic}. 
By setting $\Ynew=2$ in Theorem~\ref{L-approx-n} we get the $(2-\varepsilon)g+4$ approximation of \cite{kadria2022algorithmic}.
By setting $\varepsilon=0$ we get an  $\tO(\Ynew\cdot n^{1+1/\Ynew})$ time algorithm that computes a  $C_{\leq 2\Ynew\lceil \frac{g}{2}\rceil}$, which is similar to the $\tO(n^{1+1/\ell})$ time algorithm of \cite{kadria2022algorithmic} which computes a $C_{\leq 2\ell \lceil \frac{g}{2}\rceil}$. 

\subsection{Sparse graphs} 
We use a similar approach to obtain a tradeoff for girth approximation in sparse graphs. We prove the following theorem.



\begin{theorem}\label{L-approx-m}
    Let $\Ynew\geq 3$ 
    be an integer, $\varepsilon\in [0,1)$ and  $g\leq \log^2 n$.
    It is possible to compute, whp, in  $\tO(\Ynew\cdot m^{1+1/(\Ynew-\varepsilon)})$ time, a cycle $C$ such that $\wt(C) \leq 2\Ynew(\lceil \frac{g}{2}\rceil-1)  - 2\lfloor \varepsilon (\lceil \frac{g}{2}\rceil-1) \rfloor-2 \leq
(\Ynew-\varepsilon)g-\Ynew+2\varepsilon$.
\end{theorem}

\begin{proof}
For each $\tilde{g}$ in the range $[3,\log^2 n]$ in increasing order, we call $\OneAlg(G,k(\alpha_{\tilde{g}}), \alpha_{\tilde{g}})$, where $\alpha_{\tilde{g}} = \lceil \frac{\tilde{g}}{2}\rceil$, and $k(\alpha) = \Ynew(\alpha-1) - \lfloor \varepsilon(\alpha-1) \rfloor-1$.
When we find the smallest value $\tilde{g}$ for which $\OneAlg$ returns a cycle, we stop and return that cycle. 
Since $\Ynew\geq 3$ and $\varepsilon < 1$ we have $k(\alpha_{\tilde{g}})\geq \alpha_{\tilde{g}}$, and it follows from Corollary~\ref{C-shortCycleBigK} that $\OneAlg$ either returns a $C_{\leq 2k(\alpha_{\tilde{g}})}$ or determines that $g> 2\alpha_{\tilde{g}}\geq \tilde{g}$ in  $\tilde{O}((\frac{k(\alpha)+1}{\alpha-1}+\alpha) \cdot m^{1+\frac{\alpha-1}{k(\alpha)+1}})$ time, whp.

We first prove that the algorithm returns a cycle $C$ such that $\wt(C) \leq 2\Ynew(\lceil \frac{g}{2}\rceil-1)  - 2\lfloor \varepsilon (\lceil \frac{g}{2}\rceil-1) \rfloor-2 \leq
(\Ynew-\varepsilon)g-\Ynew+2\varepsilon$.
Let $g'$ be the smallest value $\tilde{g}$ for which $\OneAlg$ returned a cycle. As before, this implies that $g\geq g'$. 
The call to $\SrtCycSpr(G,k(\alpha_{g'}),\alpha_{g'})$ returns a cycle $C$
such that  
\begin{align*}
\wt(C)\leq 2 k(\alpha_{g'}) &=
2\cdot ( \Ynew(\alpha_{g'}-1) - \lfloor \varepsilon(\alpha_{g'}-1) \rfloor-1 )\\
& = 
2\cdot ( \Ynew(\lceil \frac{g'}{2} \rceil-1) - \lfloor \varepsilon(\lceil \frac{g'}{2} \rceil-1) \rfloor-1 )\\
& \leq 
2\cdot ( \Ynew(\lceil \frac{g}{2} \rceil-1) - \lfloor \varepsilon(\lceil \frac{g}{2} \rceil-1) \rfloor-1 ) \\
&=
2 \Ynew(\lceil \frac{g}{2} \rceil-1) - 2\lfloor \varepsilon(\lceil \frac{g}{2} \rceil-1) \rfloor-2. 
\end{align*}


Now, since $\lfloor \varepsilon(\lceil \frac{g}{2} \rceil-1) \rfloor
\geq 
\lfloor \varepsilon( \frac{g}{2} -1) \rfloor
\geq 
 \varepsilon( \frac{g}{2} -1) -1 
 =
  \varepsilon\frac{g}{2} -\varepsilon -1
$,
we get that $\wt(C) \leq 
% 2 \Ynew(\lceil \frac{g}{2} \rceil-1) - 2\lfloor \varepsilon(\lceil \frac{g}{2} \rceil-1) \rfloor-2
% \leq
2 \Ynew(\lceil \frac{g}{2} \rceil-1) - 2(\varepsilon\frac{g}{2} -\varepsilon -1)-2
=
2 \Ynew\lceil \frac{g}{2} \rceil-2\Ynew - \varepsilon g+2\varepsilon
\leq
2 \Ynew\frac{g+1}{2}-2\Ynew - \varepsilon g+2\varepsilon
=
\Ynew g+\Ynew-2\Ynew - \varepsilon g+2\varepsilon
=
(\Ynew-\varepsilon)g -\Ynew +2\varepsilon
$.



For the running time, there are at most $O(\log^2 n)$ calls to $\OneAlg$, and each call costs $\tilde{O}((\frac{k(\alpha)+1}{\alpha-1}+\alpha) \cdot m^{1+\frac{\alpha-1}{k(\alpha)+1}})$ whp (with the values of $k$ and $\alpha$ that correspond to that call).
We have $ \frac{k(\alpha)+1}{\alpha-1}
=
\frac{\Ynew(\alpha-1) - \lfloor \varepsilon(\alpha-1) \rfloor}{\alpha-1}
\leq
\frac{\Ynew(\alpha-1)}{\alpha-1}
=
\Ynew
$.
In addition, $m^{1+\frac{\alpha-1}{k+1}} = m^{1+\frac{\alpha-1}{\Ynew(\alpha-1) - \lfloor \varepsilon(\alpha-1) \rfloor}} \leq 
m^{1+\frac{\alpha-1}{\Ynew(\alpha-1) -  \varepsilon(\alpha-1) }}
=
m^{1+\frac{1}{\Ynew - \varepsilon}}
$. Thus, the running time of each call is 
$\tilde{O}((\Ynew+\alpha) \cdot m^{1+\frac{1}{\Ynew - \varepsilon}})$ whp, which is $\tilde{O}(\Ynew\cdot m^{1+\frac{1}{\Ynew - \varepsilon}})$ since $\alpha \leq \log^2 n$ in each call. Therefore, the total running time is, whp\footnote{See the previous footnote.}, $\tilde{O}(\log^2 n\cdot \Ynew\cdot m^{1+\frac{1}{\Ynew - \varepsilon}}) = \tilde{O}(\Ynew\cdot m^{1+\frac{1}{\Ynew - \varepsilon}})$.
\end{proof}


By setting $\varepsilon=0$ we get an  $\tO(\Ynew\cdot m^{1+1/\Ynew})$-time algorithm that computes a $C_{\leq 2\Ynew(\lceil \frac{g}{2}\rceil-1)}$, as opposed to the $\tO(\Ynew\cdot n^{1+1/\Ynew})$ time algorithm that computes a $C_{\leq2\Ynew\lceil \frac{g}{2}\rceil}$.



