\documentclass[main.tex]{subfiles}

\begin{document}

\section{Applications}
\label{sec:applications}

\subsection{Uniform box-filling fibrations}
\label{sec:uniform-fibrations}

To apply the theorems of \cref{sec:soa:algebraic-saturation} effectively, it is essential that we can compute the density comonads of generating diagrams.
We illustrate how this can proceed with the example of \textsc{awfs}'s for \emph{uniform fibrations}, which appear in semantics of homotopy type theory \cite{gambino-sattler:17}.
We consider only ``biased'' uniform fibrations, in \citeauthor{awodey:23}'s terminology \cite[\S3]{awodey:23}, and not unbiased or equivariant variations which are better-behaved in some settings \cite{cavallo-mortberg-swan:20,awodey:23,accrs:24}.
In various ways we sacrifice generality in favor of simplicity, \eg, by restricting ourselves to presheaf categories.

\begin{definition}
  \label{decode-characteristic}
  Given a map $t \co \CofT \mono \Cof$ in a presheaf category $\cat{E} = \PSh{\cat{C}}$, write $\phi^t \co \Slice{\cat{E}}{\Cof} \to \Arr{\cat{E}}$ for the functor that sends an object $a \co B \to \Cof$ to the base change
  \[
    \begin{tikzcd}
      A \pullback \ar[dashed,mono]{d}[left]{\phi^t(a)} \ar[dashed]{r} & \CofT \ar[mono]{d}{t} \\
      B \ar[below]{r}[below]{a} & \Cof \rlap{.}
    \end{tikzcd}
  \]
  Write $u^t \co \catEl{\Cof} \to \Arr{\cat{E}}$ for the composite
  \begin{tikzcd}[cramped]
    \catEl_{\cat{C}} \Cof \ar{r}{\yo}  & \Slice{\cat{E}}{\Cof} \ar{r}{\phi^t} & \Arr{\cat{E}}
  \end{tikzcd}.
\end{definition}

\begin{definition}
  \label{uniform-fibration-configuration}
  A \emph{uniform fibration configuration} in a presheaf category $\cat{E} = \PSh{\cat{C}}$ consists of
  \begin{enumerate}
  \item a \emph{cofibration classifier}: a map $t \co \CofT \mono \Cof$ which is locally ($\kappa$, mono)-small for some $\kappa > 0$, in the sense that for every $a \co \yo c \to \Cof$ the domain of $\phi^t(a)$ is ($\kappa$, mono)-small;
  \item a \emph{functorial cylinder}: a functor $I \co \cat{C} \to \cat{C}$ along with natural transformations
    \[
      \begin{tikzcd}
        \Id_{\cat{C}} \ar[equals]{dr} \ar{r}{\delta^0} & I \ar{d}[description,pos=0.4]{\sigma} & \ar{l}[above]{\delta^1} \ar[equals]{dl} \Id_{\cat{C}} \rlap{.} \\
        & \Id_{\cat{C}}
      \end{tikzcd}
    \]
    such that the functor $\lan{I} \co \cat{E} \to \cat{E}$ obtained by Yoneda extension preserves pullbacks and the induced $\delta^0,\delta^1 \co \Id_{\cat{E}} \to \lan{I}$ are cartesian natural transformations.
  \end{enumerate}
  We write $\lan{I} \dashv \subst{I} \dashv \ran{I}$ for the adjoint triple on $\cat{E}$ induced by $I$.
  As above, we write ${\delta^i}$ also for the induced transformation $\Id_{\cat{E}} \to \lan{I}$, while we write ${\partial_i} \co \subst{I} \to \Id_{\cat{E}}$ for its conjugate.
\end{definition}

\begin{proposition}
  \label{uniform-fibrations}
  Fix a presheaf category $\cat{E} = \PSh{\cat{C}}$ with a uniform fibration configuration $(t,I)$ as in \cref{uniform-fibration-configuration}.
  There is a \emph{uniform fibration \textsc{awfs}} cofibrantly generated by the diagram $\boxDiagram{t}{I} \defeq \copair{\leibpushapp{{\delta^0}}u^t}{\leibpushapp{{\delta^1}}u^t}$ below:
  \[
    \begin{tikzcd}[row sep=large]
      \textstyle\catEl_{\cat{C}} \Cof \ar{dr}[below left]{\leibpushapp{{\delta^0}}u^t} \ar{r}{\inl} & \textstyle(\catEl_{\cat{C}} \Cof) \sqcup (\catEl_{\cat{C}} \Cof) \ar[dashed]{d}[pos=0.4]{\boxDiagram{t}{I}} & \textstyle\catEl_{\cat{C}} \Cof \ar{l}[above]{\inr} \ar{dl}{\leibpushapp{{\delta^1}}u^t} \rlap{.} \\
      & \Arr{\cat{E}}
    \end{tikzcd}
  \]
  We call the left maps of the \textsc{awfs} \emph{trivial cofibrations}; we write $\TCof{t}{I}$ and $\DTCof{t}{I}$ for the category and double category of copointed endofunctor coalgebras.
\end{proposition}
\begin{proof}
  By \cref{soa-backdrop} applied with the backdrop of monomorphisms.
  Note that for $i \in \braces{0,1}$ and $a \co \yo c \to \Cof$, the domain of $\leibpushapp{{\delta^i}}u^t(a)$ is the pushout
  \[
    \begin{tikzcd}[column sep=large]
      \dom u^t(a) \ar[mono]{d} \ar{r}{\delta^i_A} & \lan{I}(\dom u^t(a)) \ar[mono]{d} \\
      \yo c \ar{r} & \pushout \object
    \end{tikzcd}
  \]
  and thus ($\kappa$, mono)-small, as ($\kappa$, mono)-small objects are closed under finite colimits and preserved by $I_!$.
\end{proof}

\begin{remark}
  One usually intends for the uniform fibration \textsc{awfs} to serve as the (trivial cofibration, fibration) \textsc{wfs} of a model structure on $\cat{E}$ whose (cofibration, trivial fibration) \textsc{wfs} is generated by $u^t \co \catEl_{\cat{C}} \Cof \to \Arr{\cat{E}}$.
  Typically $\Cof$ forms a \emph{dominance} and the (cofibration, trivial fibration) factorizations can be constructed more directly using \emph{partial map classifiers} \cites[\S4.4]{bourke-garner:16}[\S9]{gambino-sattler:17}[\S3]{van-den-berg-faber:22}[\S2]{awodey:23}.
\end{remark}

\begin{example}
  \label{cubical-sets-example}
  Consider the category of \emph{Boolean cubical sets}, the category of presheaves on the full subcategory $\square \subseteq \Set$ consisting of the finite powers of $\braces{0,1}$.
  The presheaf category contains a canonical interval object $\ival = \yo{\braces{0,1}} \in \PSh{\square}$.
  Given a locally ($\kappa$, mono)-small monomorphism $t \co \CofT \mono \Cof$, we get a uniform fibration configuration $(t,(-) \times \braces{0,1})$.
  Under some conditions on $t$, the uniform fibration \textsc{wfs} is the (trivial cofibration, fibration) \textsc{wfs} of a Quillen model structure whose cofibrations are those maps classified by $t$ \cite{gambino-sattler:17,sattler:17} and $\PSh{\square}$ admits an interpretation of homotopy type theory in which types are the uniform fibrations \cite{cohen-coquand-huber-mortberg:15}.

  In a classical metatheory, any monomorphism $t$ will satisfy the local smallness condition, and a canonical choice is the subobject classifier $\top \co 1 \mono \Omega$.
  In a constructive metatheory, the subobject classifier may not be locally ($\kappa$, mono)-small or may not exist at all.
  However, the \emph{levelwise complemented subobject} classifier $\top \co 1 \to \Omega_{\mathrm{lc}}$ is ($\omega$, mono)-small: the idempotent completion $\overline{\square}$ of $\square$ is an Eilenberg--Zilber category \cite[Theorem 8.12]{campion:23}, so levelwise decidable subobjects of the representable $n$-cube $\ival^n$ can be described as (in this case finite) unions of lower-degree objects in the image of the nerve $\overline{\square} \to \PSh{\square}$.
\end{example}

This example is one of many where $\cat{C}$ is taken to be a so-called \emph{cube category}, a monoidal category whose objects are powers of an interval object (see, \eg, \textcite{grandis-mauri:03} or \textcite{buchholtz-morehouse:17}).
For some choices of cube category, there are other interesting choices of cofibration classifier.

\begin{example}
  \label{de-morgan-example}
  \Textcite{cohen-coquand-huber-mortberg:15} give a model of type theory in \emph{De Morgan cubical sets}, presheaves over the Lawvere theory of De Morgan algebras.
  They interpret types as the uniform fibrations for a cofibration classifier they call the \emph{face lattice} \cite[\S4.1]{cohen-coquand-huber-mortberg:15}, the minimal subclassifier $\Cof \subseteq \Omega$ classifying the face inclusions $\ival^k \times \delta^i \times \ival^{n-k} \co \ival^n \mono \ival^{n+1}$ and closed under finite intersection and union.
  The face lattice excludes for example the diagonal subobject $\Delta_{\ival} \co \ival \mono \ival \times \ival$.

  This example is notable in our context because it is not generated by a set, even in a classical metatheory.
  Suppose for sake of contradiction that we have a generating set $S \subseteq \Arr{\PSh{\square}}$ of trivial cofibrations, so that every trivial cofibration is a cell complex of maps in $S$.
  For any cardinal $\lambda$, we can attach $\lambda$ copies of the 2-cube along their diagonals to obtain an object
  \[
    \begin{tikzcd}
      \coprod_\lambda \ival \ar[mono]{d}[left]{\coprod_\lambda \Delta_{\ival}} \ar{r}{\nabla} & \ival \ar[mono,dashed]{d}{m} \\
      \coprod_\lambda (\ival \times \ival) \ar[dashed]{r}[below]{q} & \pushout W_\lambda \rlap{.}
    \end{tikzcd}
  \]
  The composite
  \begin{tikzcd}[cramped]
    1 \ar[mono]{r}{\delta_0} & \ival \ar[mono]{r}{m} & W_\lambda
  \end{tikzcd}
  is classified by the face lattice and indeed a trivial cofibration, although $m$ is not.
  By our working assumption, $m\delta_0$ can be written as a cell complex of maps in $S$, in particular as a transfinite composite of maps $i_\alpha \co A_\alpha \mono A_{\alpha+1}$.
  Any stage of the transfinite composite that contains the interval $m \co \ival \mono W_\lambda$ must contain \emph{all} of $W_\lambda$, since we cannot glue on a square along its diagonal.
  Since $\ival$ is tiny (that is, $\Hom{\PSh{\square}}{\ival}{-}$ preserves all colimits), the least $\alpha$ such that $A_\alpha$ contains $\ival$ must be a successor ordinal $\alpha = \beta + 1$, and so we have a pushout square
  \[
    \begin{tikzcd}[column sep=large]
      \coprod_{i \in I} C_i \ar[mono]{d}[left]{\coprod_{i \in I} f_i} \ar{r}{[c_i]_{i \in I}} & A_\beta \ar[mono]{d} \\
      \coprod_{i \in I} D_i \ar[below]{r}[below]{[d_i]_{i \in I}} & W_\lambda
    \end{tikzcd}
  \]
  where the maps $f_i$ belong to $S$.
  There must be exactly one $i \in I$ such that the image of $d_i$ contains the image of $q \co \coprod_\lambda (\ival \times \ival) \to W_\lambda$, in which case we have a lower bound $\card{\Hom{\PSh{\square}}{\ival^2}{D_i}} \ge \lambda$ on the number of 2-cubes in $D_i$.
  But while $\lambda$ was arbitrary, the set $\set{\card{\Hom{\PSh{\square}}{\ival^2}{D}}}{(f \co C \to D) \in S}$ is bounded by some fixed cardinal; thus we have a contradiction.
\end{example}

Now we analyze the codensity monad for the generating diagram of a uniform fibration \textsc{awfs}.

\begin{proposition}
  \label{lan-adjoint}
  Let $\adjunction{F}{\cat{C}}{\cat{D}}{G}$ be an adjunction between cocomplete categories and let $u \co \cat{J} \to \cat{C}$ be a diagram.
  Then $\Den{Fu} \cong F \circ \Den{u} \circ G$.
\end{proposition}
\begin{proof}
  We have $\Lan_{Fu} (Fu) \cong F (\Lan_{Fu} u)$ because left adjoints preserve left Kan extensions \cite[Theorem X.5.1]{mac-lane:98}, and $\Lan_{Fu} u \cong (\Lan_u u)G$ by the isomorphism of comma categories $\Comma{Fu}{D} \cong \Comma{u}{GD}$ natural in $D \in \cat{D}$.
\end{proof}

\begin{notation}
  The morphism $\phi^t$ of \cref{decode-characteristic} decomposes as a sequence of left adjoints:
  \[
    \begin{tikzcd}
      \Slice{\cat{E}}{\Cof} \ar{r}{\Slice{\id_{(-)}}{\Cof}} &[2em] \Slice{\Arr{\cat{E}}}{\id_\Cof} \ar{r}{\subst{(t,\id_\Cof)}} &[2em] \Slice{\Arr{\cat{E}}}{t} \ar{r}{\sum_t} & \Arr{\cat{E}} \rlap{.}
    \end{tikzcd}
  \]
  We write $\nu^t \co \Arr{\cat{E}} \to \Slice{\cat{E}}{\Cof}$ for its right adjoint, which is thus given by the composite
  \[
    \begin{tikzcd}
      \Arr{\cat{E}} \ar{r}{(-) \times t} &[2em] \Slice{\Arr{\cat{E}}}{t} \ar{r}{\prod_{(t,\id_\Cof)}} &[2em] \Slice{\Arr{\cat{E}}}{\id_\Cof} \ar{r}{\Slice{\dom}{\id_\Cof}} &[2em] \Slice{\cat{E}}{\Cof} \rlap{.}
    \end{tikzcd}
  \]
\end{notation}

\begin{lemma}
  \label{cofibration-density-calculation}
  Let $t \co \CofT \mono \Cof$ be a map in a presheaf category $\cat{E} = \PSh{\cat{C}}$.
  The density comonad associated to $u^t$ is isomorphic to $\phi^t\nu^t \co \Arr{\cat{E}} \to \Arr{\cat{E}}$.
\end{lemma}
\begin{proof}
  By \cref{lan-adjoint}, the density comonad is isomorphic to a composite
  \[
    \begin{tikzcd}
      \Arr{\cat{E}} \ar{r}{\nu^t} & \Slice{\cat{E}}{\Cof} \ar{r} & \Slice{\cat{E}}{\Cof} \ar{r}{\phi^t} & \Arr{\cat{E}}
    \end{tikzcd}
  \]
  where the middle factor is the density comonad of $\yo \co \catEl_{\cat{C}} \Cof \to \Slice{\cat{E}} \Cof$.
  The Yoneda embedding is a dense functor, so its density comonad is the identity \cite[Proposition 1 and Corollary 3]{mac-lane:98}.
\end{proof}

\begin{notation}
  Given a category $\cat{E}$, write $\CartArr{\cat{E}} \hookrightarrow \Arr{\cat{E}}$ for the wide subcategory of pullback squares and $\CartMono{\cat{E}} \hookrightarrow \CartArr{\cat{E}}$ for the further full subcategory of monomorphisms of $\cat{E}$ and pullback squares between them.
\end{notation}

\begin{corollary}
  \label{cofibrations-mono}
  Let $t \co \CofT \mono \Cof$ be a monomorphism in a presheaf category $\cat{E}$.
  The density comonad $\Den{u^t} \co \Arr{\cat{E}} \to \Arr{\cat{E}}$  lifts through $\CartMono{\cat{E}} \hookrightarrow \Arr{\cat{E}}$ and preserves levelwise monomorphisms.
\end{corollary}
\begin{proof}
  By \cref{cofibration-density-calculation} we have $\Den{u^t} \cong \phi^t\nu^t$.
  The functor $\phi^t$ is valued in  monomorphisms by closure of monomorphisms under base change; thus $\Den{u^t}$ is also valued in monomorphisms.
  We know $\nu^t$ preserves monomorphisms as a right adjoint, and $\phi^t$ preserves monomorphisms by cancellation.
\end{proof}

\begin{proposition}
  \label{lan-coproduct}
  Let $S$ be a set and $u_i \co \cat{J}_i \to \cat{C}$ for $i \in S$ be a family of diagrams in a cocomplete category $\cat{E}$.
  If $u \co \coprod_{i \in S} \cat{J} \to \cat{C}$ is the induced map from the coproduct, then
  \begin{align*}
    \Den{u}C &\cong \textstyle\coprod_{i \in S} \Den{u_i}C
  \end{align*}
  naturally in $C \in \cat{C}$.
\end{proposition}
\begin{proof}
  The density comonad $\Den{u}$ is computed at $C \in \cat{C}$ by the colimit
  \begin{align*}
    \Den{u}(C)
    &\cong \colim \left(
      \begin{tikzcd}[cramped,ampersand replacement=\&,sep=small]
      \Comma{u}{C} \ar{r}{\proj{}} \& \coprod_{i \in S} \cat{J}_i \ar{r}{u} \&[1em] \cat{E}
      \end{tikzcd}\right) \\
    &\cong \textstyle\coprod_{i \in S} \colim \left(
      \begin{tikzcd}[cramped,ampersand replacement=\&,sep=small]
        \Comma{u_i}{C} \ar{r}{\proj{}} \& \cat{J_i} \ar{r}{u_i} \&[1em] \cat{E}
      \end{tikzcd}\right) \\
    &\cong \textstyle\coprod_{i \in S} \Den{u_i}(C) \rlap{.} \qedhere
  \end{align*}
\end{proof}

\begin{corollary}
  \label{trivial-cofibration-density-calculation}
  For a uniform fibration configuration $(t,I)$ on a presheaf category $\cat{E}$, the density comonad associated to $\boxDiagram{t}{I} \co \Arr{\cat{E}} \to \Arr{\cat{E}}$ is given by the formula
  \[
    \Den{\boxDiagram{t}{I}}f \cong \leibpushapp{{\delta^0}}\Den{u^t}(\leibpullapp{{\partial_0}}(f)) \sqcup \leibpushapp{{\delta^1}}\Den{u^t}(\leibpullapp{{\partial_1}}(f)) \rlap{.}
  \]
  In particular, $\boxDiagram{t}{I}$ factors through the functor $\Slice{\cat{E}}{\Cof} \to \Arr{\cat{E}}$ sending $a \co B \to \Cof$ to $\leibpushapp{{\delta^0}}\phi^t(a) \sqcup \leibpushapp{{\delta^1}}\phi^t(a)$.
\end{corollary}
\begin{proof}
  By \cref{lan-adjoint,lan-coproduct,cofibration-density-calculation}.
\end{proof}

\begin{corollary}
  \label{trivial-cofibrations-mono}
  Let $(t,I)$ be a uniform fibration configuration on a presheaf category $\cat{E}$.
  Then the density comonad associated to $\boxDiagram{t}{I} \co \Arr{\cat{E}} \to \Arr{\cat{E}}$ lifts through $\CartMono{\cat{E}} \hookrightarrow \Arr{\cat{E}}$ and preserves levelwise monomorphisms.
  In particular, per \cref{monomorphism-backdrop-compatible}, $\boxDiagram{t}{I}$ is compatible with the backdrop of monomorphisms.
\end{corollary}
\begin{proof}
  In light of \cref{cofibrations-mono,trivial-cofibration-density-calculation}, it suffices to show that each $\leibpushapp{{\delta^i}} \co \Arr{\cat{E}} \to \Arr{\cat{E}}$ lifts to a functor $\CartMono{\cat{E}} \to \CartMono{\cat{E}}$ and that this lift preserves levelwise monomorphisms; note that the functors $\leibpullapp{{\partial_i}}$ are right adjoints and thus automatically preserve levelwise monomorphisms.

  For $i \in \braces{0,1}$ and a monomorphism $m \co A \to B$ in $\cat{E}$, $\leibpushapp{{\delta^i}}(f)$ is defined as the pushout gap map
  \[
    \begin{tikzcd}[column sep=large]
      A \ar{d}[left]{m} \ar{r}{\delta^i_A} & \lan{I}A \ar{d} \ar[bend left=20]{ddr}{\lan{I}m} \\
      B \ar[bend right=20]{drr}[below]{\delta^i_B} \ar{r} & \pushout \object \ar{dr}[pos=0.2]{\leibpushapp{{\delta^i}}(m)} \\[-2em]
      & & \lan{I}B \rlap{.}
    \end{tikzcd}
  \]
  Since $\delta_i$ admits a retraction $\sigma$, it is valued in monomorphisms.
  Combined with the assumption that $\lan{I}$ preserves pullbacks and thus monomorphisms, this makes $\leibpushapp{{\delta^i}}(m)$ is the union of the monomorphisms $\delta^i_B$ and $\lan{I}m$ \cite[Theorem 5.1]{lack-sobocinski:05}.

  For any $f \co B' \to B$, $\leibpushapp{{\delta^i}}$ applied to the pullback of $m$ along $f$ is the pullback of $\leibpushapp{\delta^i}(m)$ along $\lan{I}f$, by pullback stability of colimits in $\cat{E}$ together with the assumptions that $\lan{I}$ preserves pullbacks and $\delta_i$ is cartesian.
  Thus $\leibpushapp{\delta^i}$ lifts to a functor $\CartMono{\cat{E}} \to \CartMono{\cat{E}}$.

  Given a levelwise monomorphism $(k,\ell) \co m \to n$ in $\CartMono{\cat{E}}$, the codomain component of $\leibpushapp{\delta^i}(k,\ell)$ is a monomorphism because $\lan{I}$ preserves monomorphisms, whence the domain component is a monomorphism by cancellation.
\end{proof}

In the following sections, we use uniform fibration \textsc{awfs}'s to illustrate our applications of the theorems of \cref{sec:soa:algebraic-saturation}.

\subsection{Action of a functor on left maps}

Suppose we have a functor $F \co \cat{D} \to \cat{E}$ and a \textsc{wfs} $(\class{L},\class{R})$ on $\cat{D}$ generated by a set $S$ using Quillen's small object argument, and we want to show that $F$ sends $\class{L}$ into some saturated class of maps $\class{A}$---perhaps the left class of another \textsc{wfs} on $\cat{E}$.
The saturation characterization of $\class{L}$ tells us that if $F$ preserves cell complex structure, then it is enough to check that $F$ sends $S$ into $\class{A}$.
For our first application, we prove an analogue of this result for \textsc{awfs}'s cofibrantly generated by a diagram.

\begin{definition}
  Let $F \co \cat{D} \to \cat{E}$ be a functor and $U \co \dcat{A} \to \Sq{\cat{E}}$ be a notion of composable structure.
  We define the notion of composable structure $\subst{F}U \co \subst{F}\dcat{A} \to \Sq{\cat{D}}$ by pulling back along $F$:
  \begin{equation}
    \label{preimage-vertical-structure-pullback}
    \begin{tikzcd}[column sep=large]
      \VertArr{(\subst{F}\dcat{A})} \ar[dashed]{d}[left]{\VertArr{(\subst{F}U)}} \pullback \ar[dashed]{r} & \VertArr{\dcat{A}} \ar{d}{\VertArr{U}} \\
      \Arr{\cat{D}} \ar{r}[below]{\Arr{F}} & \Arr{\cat{E}} \rlap{.}
    \end{tikzcd}
  \end{equation}
  That is, a vertical morphism $A \verto B$ in $\subst{F}\dcat{A}$ consists of a morphism $f \co A \to B$ in $\dcat{D}$ together with a vertical morphism $\bm{g} \co FA \verto FB$ in $\dcat{A}$ such that $U\bm{g} = Ff$.
  Likewise, a square in $\subst{F}\dcat{A}$ consists of a commutative square in $\cat{D}$ together with a square of $\dcat{A}$ over its image by $F$.
  Identities and composition are given in the evident way.
  The diagram \eqref{preimage-vertical-structure-pullback} extends to a double functor
  \[
    \begin{tikzcd}[column sep=large]
      \subst{F}\dcat{A} \ar[dashed]{d}[left]{\subst{F}U} \pullback \ar[dashed]{r} & \dcat{A} \ar{d}{U} \\
      \Sq{\cat{D}} \ar{r}[below]{\Sq{F}} & \Sq{\cat{E}} \rlap{.}
    \end{tikzcd}
  \]
\end{definition}

\begin{proposition}
  \label{preimage-left-connected}
  Let $U \co \dcat{A} \to \Sq{\cat{E}}$ be a notion of composable structure and $F \co \cat{D} \to \cat{E}$ be a functor.
  If $U$ is left-connected, then so is $\subst{F}U$.
\qed
\end{proposition}

\begin{proposition}
  \label{preimage-cellular}
  Let $U \co \dcat{A} \to \Sq{\cat{E}}$ be a notion of composable structure and $F \co (\cat{D},\class{M}) \to (\cat{E},\class{N})$ be a $\kappa$-backdrop-preserving functor.
  If $U$ is $(\kappa,\class{N})$-cellular, then $\subst{F}U \co \subst{F}\dcat{A} \to \Sq{\cat{D}}$ is $(\kappa,\class{M})$-cellular.
\end{proposition}
\begin{proof}
  The projections from $\VertArr{(\subst{F}\dcat{A})}$ to $\Arr{\cat{D}}$ and $\VertArr{\dcat{A}}$ send $\DCodClass{(\subst{F}\dcat{A})}{\class{M}}$ into $\CodClass{\cat{D}}{\class{M}}$ and $\DCodClass{\dcat{A}}{\class{N}}$ respectively, and the cospan of the defining pullback \eqref{preimage-vertical-structure-pullback} extends to a diagram of $\kappa$-backdrop-preserving functors
  \[
    \begin{tikzcd}[sep=large]
       & (\VertArr{\dcat{A}},\DCodClass{\dcat{A}}{\class{N}}) \ar{d}{\VertArr{U}} \\
      (\Arr{\cat{D}},\CodClass{\cat{D}}{\class{M}}) \ar{r}[below]{\Arr{F}} & (\Arr{\cat{E}},\CodClass{\cat{E}}{\class{N}}) \rlap{.}
    \end{tikzcd}
  \]
  It follows that that the relevant colimits in $\VertArr{(\subst{F}\dcat{A})}$ can be computed levelwise and that the pullback projection $\VertArr{(\subst{F}U)}$ preserves them, as required.
\end{proof}

\begin{proposition}
  \label{preimage-retracts}
  Let $F \co \cat{D} \to \cat{E}$ be a functor and $U \co \dcat{A} \to \Sq{\cat{E}}$ be a notion of composable structure.
  Any (compositional) codomain retract lifting operator on $U$ induces a (compositional) codomain retract lifting operator on $\subst{F}U$.
\qed
\end{proposition}

We now deduce the following generalization of \cref{soa-copointed-coalgebras-functor,soa-copointed-coalgebras-double-functor}.

\begin{theorem}
  \label{preimage-coalgebras-functor}
  Let $F \co (\cat{D},\class{M}) \to (\cat{E},\class{N})$ be a $\kappa$-backdrop-preserving functor.
  Fix a diagram $u \co \cat{J} \to \Arr{\cat{E}}$ compatible with $\class{M}$ such that $\dom u$ is levelwise $(\kappa,\class{M})$-small.
  Per \cref{soa-backdrop}, $u$ generates an \textsc{awfs} $(\comonad{L},\monad{R})$ on $\cat{D}$.
  For  a left-connected, $(\kappa,\class{N})$-cellular notion of composable structure $U \co \dcat{A} \to \Sq{\cat{E'}}$ with a codomain retract lifting operator, any lift
  \[
    \begin{tikzcd}[row sep=large]
      \Arr{\cat{D}} \ar[dashed]{r} \ar{d}[left]{\Den{u}} & \VertArr{\dcat{A}} \ar{d}{\VertArr{U}} \\
      \Arr{\cat{D}} \ar{r}[below]{\Arr{F}} & \Arr{\cat{E}}
    \end{tikzcd}
  \]
  induces a functor
  \[
    \begin{tikzcd}[row sep=large]
      \Coalg{\UnderPtd{\comonad{L}}} \ar{d}[left]{U_{\UnderPtd{\comonad{L}}}} \ar[dashed]{r} & \VertArr{\dcat{A}} \ar{d}{\VertArr{U}} \\
      \Arr{\cat{D}} \ar{r}[below]{\Arr{F}} & \Arr{\cat{E}} \rlap{.}
    \end{tikzcd}
  \]
  If $\dcat{A}$ is thin and its codomain retract lifting operator is compositional, then said functor extends to a pseudo double functor $\DCoalg{\UnderPtd{\comonad{L}}} \to \dcat{A}$ over $\Sq{\cat{D}} \to \Sq{\cat{E}}$.
\end{theorem}
\begin{proof}
  We apply \cref{soa-copointed-coalgebras-functor} with the $\kappa$-backdrop $\class{M}$ and the notion of composable structure
  \[
    \subst{F}U \co \subst{F}\dcat{A} \to \Sq{\cat{E}} \rlap{,}
  \]
  which is $(\kappa,\class{M})$-cellular by \cref{coalgebra-double-category-cellular,preimage-cellular} and admits retract lifting by \cref{preimage-retracts}.
  We obtain a pseudo double functor
  \[
    \begin{tikzcd}[row sep=large]
      \Coalg{\UnderPtd{\comonad{L}}} \ar{dr}[below left]{U_{\UnderPtd{\comonad{L}}}} \ar[dashed]{rr} &[-1em]&[-1em] \VertArr{\subst{F}\dcat{A}} \ar{dl}{\VertArr{\subst{F}U}} \ar{r} & \VertArr{\dcat{A}} \ar{d}{\VertArr{U}} \\
      & \Arr{\cat{D}} \ar{rr}[below]{\Arr{F}} & & \Arr{\cat{E}} \rlap{.}
    \end{tikzcd}
  \]
  The top horizontal composite is the desired functor $j \co \Coalg{\UnderPtd{\comonad{L}}} \to \VertArr{\dcat{A}}$.
  When $\dcat{A}$ is thin and its codomain retract lifting operator is compositional, we can instead apply \cref{soa-copointed-coalgebras-double-functor} to get a pseudo double functor.
\end{proof}

\begin{remark}
  Note that the analogous theorem for Quillen's small object argument only requires $F$ to preserve cobase changes and transfinite composites of maps in the left class, whereas our theorem requires this for the larger class $\class{M}$.
  It is not clear to us whether the stronger result can be derived from ours when the generating diagram is discrete.
\end{remark}

A typical application is to show that that a backdrop-preserving functor sends the left maps of one \textsc{awfs} to left maps of another \textsc{awfs}:

\begin{corollary}
  \label{functor-preserves-left-maps}
  Let $\cat{D}$ be a cocomplete category equipped with a $\kappa$-backdrop $\class{M}$ and levelwise $\kappa$-compact diagram $u \co \cat{J} \to \Arr{\cat{D}}$ compatible with $\class{M}$.
  Per \cref{soa-backdrop}, $u$ generates an \textsc{awfs} $(\comonad{L},\monad{R})$ on $\cat{D}$.
  Let $\cat{E}$ be a second category equipped with an \textsc{awfs} $(\comonad{L}',\comonad{R}')$ and let $F \co \cat{D} \to \cat{E}$ be a functor preserving cobase changes of maps in $\class{M}$ and $\alpha$-indexed colimits in $\class{M}$ for $\alpha \le \kappa$.
  Then any lift
  \[
    \begin{tikzcd}[row sep=large]
      \Arr{\cat{D}} \ar{d}[left]{\Den{u}} \ar[dashed]{r} & \Coalg{\UnderPtd{\comonad{L'}}} \ar{d}{\UnderPtd{\comonad{L'}}} \\
      \Arr{\cat{D}} \ar{r}[below]{\Arr{F}} & \Arr{\cat{E}}
    \end{tikzcd}
  \]
  induces a double functor $\DCoalg{\UnderPtd{\comonad{L}}} \to \DCoalg{\UnderPtd{\comonad{L'}}}$ over $\Sq{F}$.
\end{corollary}
\begin{proof}
  The notion of composable structure $\DCoalg{\UnderPtd{\comonad{L'}}}$ (with the trivial backdrop $\Arr{\cat{E}}$) satisfies the requirements of \cref{preimage-coalgebras-functor} by \cref{coalgebra-double-category-cellular,coalgebra-retract-lifting-compositional}.
  Note that the pseudo double functor we obtain is necessarily a double functor because $\VertArr{U_{\UnderPtd{\comonad{L'}}}}$ is amnestic, \ie, any isomorphism it sends to an identity is itself an identity.
\end{proof}

In the specific case of a uniform fibration $\textsc{awfs}$, the density comonad condition reduces to a natural requirement on pushout applications of the endpoints $\delta_i$ to cofibrations:

\begin{example}
  \label{functor-preserves-left-maps-uniform}
  Let $(t,I)$ be a uniform fibration configuration in a presheaf category $\cat{D} = \PSh{\cat{C}}$.
  Let $(\comonad{L},\comonad{R})$ be an \textsc{awfs} on a category $\cat{E}$ and let $F \co \cat{D} \to \cat{E}$ be a functor preserving $\omega$-indexed colimits of monomorphisms and cobase changes of monomorphisms.
  If $F\leibpushapp{\delta_i}\phi^t \co \Slice{\cat{E}}{\Cof} \to \Arr{\cat{E}}$ lifts through $\Coalg{\UnderPtd{\comonad{L}}}$ for $i \in \braces{0,1}$, then $\Sq{F} \co \Sq{\cat{D}} \to \Sq{\cat{E}}$ lifts to a double functor $\DTCof{t}{I} \to \DCoalg{\UnderPtd{\comonad{L}}}$.
\end{example}
\begin{proof}
  By \cref{functor-preserves-left-maps,trivial-cofibrations-mono,trivial-cofibration-density-calculation}.
\end{proof}

\begin{example}
  In a forthcoming article \cite{cavallo-sattler:counterexamples}, we use \cref{functor-preserves-left-maps-uniform} to analyze exponentiation by quotients of representables in cubical set categories.
  We briefly sketch the situation here, using the Boolean cubical sets from \cref{cubical-sets-example}.

  For this form of cubical set, we have an isomorphism $\sigma \co \ival \cong \ival$ that swaps $0$ and $1$.
  Exponentiation by the quotient $\ival/\sigma$ in $\PSh{\square}$ defines a functor $(-)^{\ival/\sigma} \co \PSh{\square} \to \PSh{\square}$ that does not preserve all colimits, but turns out to preserve $\omega$-indexed colimits and pushouts along monomorphisms.
  It moreover preserves $\ival$: the inclusion of constant maps $\ival \to \ival^{\ival/\sigma}$ is an isomorphism.
  It follows from \cref{functor-preserves-left-maps-uniform} that $(-)^{\ival/\sigma}$ preserves the trivial cofibrations of any uniform fibration configuration for which $(-)^{\ival}$ (and thus $(-)^{\ival/\sigma}$) preserves cofibrations.
  Ken Brown's lemma \cite[Lemma 1.1.12]{hovey:99} then implies that $(-)^{\ival/\sigma}$ preserves weak equivalences between cofibrant objects.

  This last fact is a key lemma in an argument, to be presented in \cite{cavallo-sattler:counterexamples}, that model structures associated with these uniform fibration \textsc{awfs}'s do not present the $(\infty,1)$-category of $\infty$-groupoids.
  A more immediate implication is that the model structure for $t = \top \co 1 \to \Omega$ does not coincide with Cisinski's \emph{test model structure} on this presheaf category, which does present the $(\infty,1)$-category of $\infty$-groupoids \cite{cisinski:06,buchholtz-morehouse:17}.
  Indeed, the object $\ival/\sigma$ is contractible in the test model structure but cannot be contractible in the uniform fibration model structure: the argument above would then imply that $(\ival/\sigma)^{\ival/\sigma}$ is also contractible, but $(\ival/\sigma)^{\ival/\sigma}$ is isomorphic to $1 \sqcup \ival/\sigma$ and thus patently non-contractible.

  This kind of argument can be applied to a number of model structures on cubical set categories that have been constructed to interpret homotopy type theory.
  In the case of \emph{cartesian cubical sets}, an unpublished note of \textcite{coquand:18:counterexample} describes an argument by the second author that the quotient of the 2-cube by the reflection along its diagonal is not contractible in one such model structure, using an explicit inductive description of the (trivial cofibration, fibration) factorization for that module structure.
  Although these results can also be obtained for some choices of $t \co \CofT \mono \Cof$ using Quillen's small object argument, we saw in \cref{de-morgan-example} that Quillen's argument does not apply in all cases of interest even in a classical methatheory.
\end{example}

\subsection{Extension operations}
\label{sec:applications:extension}

As a second application, we consider the construction of \emph{extension operations}.
The general pattern is that we have some notion of structure on objects of our category and want to show that any structure on the domain of a left map induces a compatible structure on its codomain.
The motivating example is the extension of \emph{fibrations along trivial cofibrations}, where the structure on an object is a fibration over it:

\begin{example}
  A (pre)model category \cite{barton:19} has the \emph{fibration extension property} when for any trivial cofibration $m \co A \tcof B$ and fibration $p \co X \fib A$ over its domain, there is a square
  \[
    \begin{tikzcd}
      X \pullback \ar[fib]{d}[left]{p} \ar[dashed]{r} & Y \ar[dashed,fib]{d} \\
      A \ar[tcof]{r}[below]{m} & B
    \end{tikzcd}
  \]
  exhibiting $p$ as a pullback of a fibration over $B$.
\end{example}

The property has a prominent role in homotopical semantics of type theory: it is used for example by \textcite[Proposition 2.21]{cisinski:14} to build interpretations of type theory from Quillen model categories, and conversely by \textcite{sattler:17} and others \cite{awodey:23,cavallo-sattler:23,accrs:24} to build Quillen model categories from (or in conjunction with) interpretations of type theory.
It is, in particular, connected to fibrancy of universes classifying fibrations: under some conditions, a fibration $p \co \widetilde{U} \fib U$ which classifies small fibrations will have a fibrant base object $U$ if and only if $U$-small fibrations extend along trivial cofibrations \cites[Remark 7.6]{sattler:17}[Proposition 2.2.4]{stenzel:19}.
It and related properties also appear in homotopy theory more broadly (\eg, \cites[Lemma 1.7.1]{joyal-tierney:99}[Corollary 5.2.11]{cisinski:19}).

In these situations, one often first shows explicitly that fibrations extend along \emph{generating} trivial cofibrations.
When the extension property can be cast in terms of fibrancy of a hierarchy of universes, extension along generators immediately gives extension along all trivial cofibrations.
If one is primarily interested in building a model category, however, it would be conceptually cleaner not to depend on a stratification of the category by size.

Instead, one can use a decomposition of trivial cofibrations by some kind of small object argument, as is done in \textcite[Corollary 7.4]{sattler:17} and \textcite[Lemma 3.2.6]{gambino-sattler-szumilo:22}.
We show in this section how to carry out such an argument for a class of trivial cofibrations generated using the \emph{algebraic} small object argument, where previous work was limited to factorization systems generated by Quillen's argument.
In particular, it can be applied with the uniform fibration factorization systems of \cref{sec:uniform-fibrations}.

\begin{remark}
  An alternative approach to the following result is described in unpublished work of the second author \cite{sattler-free-monad}, using the fine-grained functoriality of \cref{sec:free-monad-sequence} directly in place of this article's saturation machinery.
  That approach has the advantage of avoiding any pushforward manipulations by working with individual extension problems in place of extension operations.
\end{remark}

We consider notions of structure on objects of a category given as a Grothendieck fibration over that category.
We first fix some notation.

\begin{notation}
  Let $P \co \cat{E} \to \cat{B}$ be a Grothendieck fibration.
  \begin{itemize}
  \item For $a \in \cat{B}$, we write $\cat{E}_a$ for the fiber of $P$ over $a$.
  \item Similarly, for $u \co a \to b$ in $\cat{B}$ we write $\Arr{\cat{E}}_u$ for the fiber of $\Arr{P} \co \Arr{\cat{E}} \to \Arr{\cat{B}}$ over $u$.
  \item We assume that our fibrations come with a choice of cartesian lifts (\ie, are \emph{cloven}) and write $\overline{u}e \co \subst{u}e \to e$ for the chosen cartesian lift of some $e \in \cat{E}_a$ along $u \co b \to a$.
  \item We write $\FibOb{\cat{B}}{P} \co \FibOb{\cat{B}}{\cat{E}} \to \cat{B}$ for the restriction of $P$ to the wide subcategory $\FibOb{\cat{B}}{\cat{E}}$ consisting of $P$-cartesian morphisms (sometimes called the \emph{fibration of objects}).
  \end{itemize}
\end{notation}

We will also need an analogue of the concept of \emph{Van Kampen colimit} \cite{lack-sobocinski:04,cockett-xuo:07,heindel-sobocinski:11} in the setting of a Grothendieck fibration.

\begin{definition}
  \label{van-kampen}
  Let $P \co \cat{E} \to \cat{B}$ be a Grothendieck fibration.
  We say that a colimit cocone $\beta \co b \to \Delta b_0$ under a diagram $b \co \cat{K} \to \cat{B}$ is \emph{Van Kampen for $P$} when
  \begin{enumerate}[label=(\alph*),ref=\thedefinition(\alph*)]
  \item \label{vk-existence} every $e \co \cat{K} \to \FibOb{\cat{B}}{\cat{E}}$ over $b$ admits a colimit cocone in $\FibOb{\cat{B}}{\cat{E}}$ over $\beta$;
  \item \label{vk-restrict}
    given $e \co \cat{K} \to \FibOb{\cat{B}}{\cat{E}}$, every cocone $\eta \co e \to \Delta e_0$ in $\FibOb{\cat{B}}{\cat{E}}$ over $\beta$ is a colimit cocone in $\cat{E}$.
  \end{enumerate}
\end{definition}

\begin{remark}
  The cocone $\beta$ is Van Kampen for $P$ exactly if the corresponding pseudofunctor $\cat{E}_{(-)} \co \op{\cat{B}} \to \Cat$ sends it to a bilimit of categories.
\end{remark}

A Van Kampen colimit in the usual sense in a category $\cat{E}$ with pullbacks is then a colimit which is Van Kampen for the codomain fibration $\cod \co \Arr{\cat{E}} \to \cat{E}$.

\subsubsection{Cartesian pushforwards}

For this application, we want to associate each left map with an \emph{operation} which can take any structure on the domain as input and output an extension.
To define a category of such operations, we make use of pushforwards in $\Cat$.
Recall that a functor $P \co \cat{E} \to \cat{B}$ is \emph{exponentiable} when the pullback functor $\subst{P} \co \Slice{\Cat}{\cat{B}} \to \Slice{\Cat}{\cat{E}}$ has a right adjoint $\ran{P}$, and that any Grothendieck fibration is exponentiable \cite[Lemme 4.3, Th\'eor\`eme 4.4]{giraud:64}.
Given $F \co \cat{F} \to \cat{E}$, we write $\ran{P}F \co \ranob{P}{F} \to \cat{B}$ for the application of the right adjoint and call this the \emph{pushforward of $F$ along $P$}.

In fact we want a variation on the pushforward with a stronger condition on morphisms.

\begin{definition}
  Let $P \co \cat{E} \to \cat{B}$ and $Q \co \cat{F} \to \cat{B}$ be Grothendieck fibrations and $V \co (\cat{F},Q) \to (\cat{E},P)$ be a fibered functor over $\cat{E}$.
  The \emph{cartesian pushforward} $\ranc{P}{V} \co \rancob{P}{V}$ is the pullback
  \[
    \begin{tikzcd}
      \rancob{P}{V} \pullback \ar[dashed,bend left=20]{rr}{\ranc{P}{V}} \ar[dashed]{d} \ar[dashed]{r} & \prod_P V \ar{d} \ar{r}[below]{\ran{P}V} & \cat{B} \rlap{,} \\
      \prod_{\FibOb{\cat{B}}{P}} \FibOb{\cat{B}}{V} \ar{r} & \prod_{\FibOb{\cat{B}}{P}} V
    \end{tikzcd}
  \]
  where $\FibOb{\cat{B}}{V} \co \FibOb{\cat{B}}{P} \to \FibOb{\cat{B}}{Q}$ is the restriction of $V$ to cartesian arrows over $\cat{B}$.
\end{definition}

\begin{remark}
  The objects of $\xi \in \ranob{P}{V}$ over $b \in \cat{B}$ correspond, by transposition, to sections $\xi^\dagger \co \cat{E}_b \to \cat{F}_b$ of the restriction $V_b \co \cat{F}_b \to \cat{E}_b$ of $V$ to the fibers over $b$.
  The category $\rancob{P}{V}$ has the same objects: they are sections $\cat{E}_b \to \cat{F}_b$ which preserve cartesian morphisms over $\cat{B}$, but this is no requirement since any vertical cartesian morphism is an isomorphism.
  Its morphisms are however more restrictive than those of $\ranob{P}{V}$, as we unpack below.
\end{remark}

\begin{proposition}
  \label{pushforward-morphisms}
  Let $P \co \cat{E} \to \cat{B}$ and $V \co \cat{F} \to \cat{E}$ be a functor.
  Given a morphism $\alpha \co b \to b'$ in $\cat{B}$ and objects $\xi \in \left(\ranob{P}{V}\right)_b$ and $\xi' \in \left(\ranob{P}{V}\right)_{b'}$, the morphisms $\beta \co \xi \to \xi'$ in $\ranob{P}{V}$ over $\alpha$ correspond to natural transformations
  \[
    \begin{tikzcd}[row sep=tiny,column sep=large]
      \cat{E}_b \ar{dr}{\xi^\dagger} \\
      { } \ar[phantom,pos=.3]{r}{\Downarrow \beta^{\ddagger}} & \cat{F} \\
      \cat{E}_{b'} \ar{uu}{\subst{\alpha}} \ar{ur}[below right]{\xi'^\dagger}
    \end{tikzcd}
  \]
  such that $V \beta^{\dagger}$ sends each $e \in \cat{E}_{b'}$ to the cartesian lift $\overline{\alpha} e \co \subst{\alpha}e \to e$.
\end{proposition}
\begin{proof}
  Use the universal property of $\ran{P}{V}$ to characterize the functors $\2 \to \ranob{P}{V}$.
\end{proof}

\begin{corollary}
  \label{cartesian-pushforward-morphisms}
  Let $P \co \cat{E} \to \cat{B}$ and $Q \co \cat{F} \to \cat{B}$ be Grothendieck fibrations and $V \co (\cat{F},Q) \to (\cat{E},P)$ be a fibered functor over $\cat{E}$.
  Given a morphism $\alpha \co b \to b'$ in $\cat{B}$ and objects $\xi \in \left(\rancob{P}{V}\right)_b$ and $\xi' \in \left(\rancob{P}{V}\right)_{b'}$, the morphisms $\beta \co \xi \to \xi'$ in $\rancob{P}{V}$ over $\alpha$ are those natural transformations as in \cref{pushforward-morphisms} which are valued in $Q$-cartesian morphisms. These correspond in particular to natural isomorphisms $\theta \co \xi^\dagger\subst{\alpha} \to \subst{\alpha}\xi'^\dagger$ such that
  \[
    \begin{tikzcd}
      \cat{E}_{b} \ar[phantom]{dr}{\theta} \ar{r}{\xi^\dagger} & \cat{F}_b \ar[phantomcenter]{dr}{\cong} \ar{r}{V_b} & \cat{E}_b \\
      \cat{E}_{b'} \ar{u}{\subst{\alpha}} \ar{r}[below]{\xi'^\dagger} & \cat{F}_{b'} \ar{u}{\subst{\alpha}} \ar{r}[below]{V_{b'}} & \cat{E}_{b'} \ar{u}[right]{\subst{\alpha}}
    \end{tikzcd}
    \quad
    =
    \quad
    \begin{tikzcd}
      \cat{E}_b \ar[equals]{r} & \cat{E}_b \\
      \cat{E}_{b'} \ar{u}{\subst{\alpha}} \ar[equals]{r} & \cat{E}_{b'} \ar{u}[right]{\subst{\alpha}} \rlap{.}
    \end{tikzcd}
  \]
\end{corollary}

\begin{notation}
  Fix a Grothendieck fibration $P \co \cat{E} \to \cat{B}$, a diagram $b \co \cat{K} \to \cat{B}$, and a cocone $\beta \co b \to \Delta b_0$ in $\cat{B}$.
  Then we have a functor and natural transformation
  \[
    \begin{tikzcd}[column sep=small,row sep=large]
      \cat{K} \times_{\cat{B}} \cat{E} \ar{dr}[below left]{\subst{P}b} & {} & \ar[dashed]{ll}[above]{\corr{P}{\beta}} \cat{K} \times \cat{E}_{b_0} \ar{dl}{\subst{P}\Delta b_0} \\
      & \cat{E} \ar[phantom]{u}[yshift=0.7em]{\lift{P}\beta}[yshift=-0.3em]{\Rightarrow}
    \end{tikzcd}
  \]
  as follows: $\corr{P}{\beta}$ sends  $(k,e)$ to $(k,\subst{\beta_k}e)$ and $\lift{P}{\beta}$ sends $(k,e)$ to $\overline{\beta_k}e \co \subst{\beta}_ke \to e$.
\end{notation}

Since the goal is to build a cellular notion of composable structure for extension operations, we are interested in colimits in pushforward categories.
Here we need Van Kampen colimits in the base.

\begin{lemma}
  \label{pushforward-colimit}
  Let $P \co \cat{E} \to \cat{B}$ and $Q \co \cat{F} \to \cat{B}$ be Grothendieck fibrations and $V \co (\cat{F},Q) \to (\cat{E},P)$ be a fibered functor over $\cat{E}$  which is itself an isofibration.
  Let a small category $\cat{K}$ and diagram
  \[
    \begin{tikzcd}[row sep=small]
      \cat{K} \ar{dr}[below left]{b} \ar{rr}{d} && \rancob{P}V \ar{dl}{\ranc{P}V} \\
      & \cat{B}
    \end{tikzcd}
  \]
  be given, and suppose that $b \co \cat{K} \to \cat{B}$ admits a colimit that is Van Kampen for $P$ and $Q$.
  Then the colimit of $d \co \cat{K} \to \rancob{P}V$ exists and is preserved by $\ranc{P}V$.
\end{lemma}
\begin{proof}
  By assumption, we have a colimit cocone $\beta \co b \to \Delta b_0$.
  Consider the transpose $d^\dagger \co \cat{K} \times_{\cat{B}} \cat{E} \to \cat{F}$.
  For each $e \in \cat{E}_{b_0}$, the composite
  \[
    \begin{tikzcd}
      \cat{K} \ar{r}{\cat{K} \times e} &[1em] \cat{K} \times \cat{E}_{b_0} \ar{r}{\corr{P}{\beta}} &[1em] \cat{K} \times_{\cat{B}} \cat{E}
    \end{tikzcd}
  \]
  factors through $\cat{K} \times_{\cat{B}} \FibOb{\cat{B}}{\cat{E}}$.
  Because $d$ is a diagram in the cartesian pushforward, its transpose $d^\dagger$ restricts to a functor $\cat{K} \times_{\cat{B}} \FibOb{\cat{B}}{\cat{E}} \to \FibOb{\cat{B}}{\cat{F}}$.
  From the diagram
  \[
    \begin{tikzcd}[row sep=large]
      \cat{K} \ar{dr}[below left]{b} \ar{r}{\corr{P}{\beta}(\cat{K} \times e)} &[5em] \cat{K} \times_{\cat{B}} \FibOb{\cat{B}}{\cat{E}} \ar{r}{d^\dagger} & \FibOb{\cat{B}}{\cat{F}} \ar{dl}{\FibOb{\cat{B}}{Q}} \\
      & \cat{B}
    \end{tikzcd}
  \]
  it follows by \ref{vk-existence} that the family $d^\dagger \circ \corr{P}{\beta} \co \cat{K} \times \cat{E}_{b_0} \to \cat{F}$ admits colimits pointwise in $e \in \cat{E}_{b_0}$, defining a family of colimits $f_0 \co \cat{E}_{b_0} \to \FibOb{\cat{B}}{\cat{F}}$ and colimit cocones $\phi \co d^\dagger \circ \corr{P}{\beta} \to f_0\projr$.
  Since $V$ is a fibred functor, the images of these cocones by $V$ land in $\FibOb{\cat{B}}{\cat{E}}$.
  By \ref{vk-restrict}, then, they are also colimit cocones; since $Vd^\dagger \circ \corr{P}{\beta} = \projr \circ \corr{P}{\beta} \co \cat{K} \times \cat{E}_{b_0} \to \cat{E}$, this means that $Vf_0 \cong \subst{P}b_0 \co \cat{E}_{b_0} \to \cat{E}$.
  Since $V$ is an isofibration, we can assume without loss of generality that $Vf_0 = \subst{P}b_0$ and that $V\phi = \lift{P}{\beta}$.
  In this case, $f_0$ and $\phi$ correspond (using the description of \cref{pushforward-morphisms}) to an object $f_0^\dagger \in \rancob{P}{V}$ and cocone $\phi^{\ddagger} \co d \to \Delta f_0^\dagger$.

  It remains to check that $\phi^{\ddagger}$ is a colimit cocone.
  Let $\xi \co d \to \Delta x$ be a cocone under $d$.
  Write $b_x = \ranc{P}V(x) \in \cat{B}$ and $\beta' = \ranc{P}V \circ \xi \co b \to \Delta b_x$; we have a unique morphism $[\beta'] \co b_0 \to b_x$ with $\Delta [\beta'] \circ \beta' = \beta$.
  By \cref{pushforward-morphisms}, $\xi$ corresponds to a transformation $\xi^\ddagger \co d^\dagger \circ \corr{P}{\beta'} \to x^\dagger\projr$ with $V\xi^\ddagger = \lift{P}{\beta'}$.
  By the universal properties of $\phi(-,\subst{[\beta']}e)$ for $e \in \cat{E}_{b_x}$, $\xi^\ddagger$ induces a natural transformation $f_0\subst{[\beta']} \to x^\dagger$, valued in $Q$-cartesian morphisms, which transposes to the desired morphism $f_0^\dagger \to x$ in $\rancob{P}{V}$ over $[\beta']$.
\end{proof}

\subsubsection{Saturation for extension operations}

\begin{definition}
  Given a Grothendieck fibration $P \co \cat{F} \to \cat{E}$, write $\FullCartArr{\cat{F}} \hookrightarrow \Arr{\cat{F}}$ for the full subcategory of $\Arr{\cat{F}}$ consisting of the $P$-cartesian morphisms and $\FullCartArr{P} \co \FullCartArr{\cat{F}} \to \Arr{\cat{E}}$ for the restriction of $P$ to this category.
\end{definition}

\begin{proposition}
  If $P \co \cat{F} \to \cat{E}$ is a Grothendieck fibration, then $\FullCartArr{P} \co \FullCartArr{\cat{F}} \to \Arr{\cat{E}}$ is also a Grothendieck fibration.
\end{proposition}
\begin{proof}
  By the cancellation properties of cartesian morphisms (if $g$ is cartesian and $gf$ is cartesian, then $f$ is cartesian).
\end{proof}

\begin{definition}[Category of extension operations]
  \label{extension-vertical-morphisms}
  Given a Grothendieck fibration $P \co \cat{F} \to \cat{E}$, define $\VertArr{U_P} \co \Ext{P} \to \Arr{\cat{E}}$ to be the cartesian pushforward
  \[
    \begin{tikzcd}
      \FullCartArr{\cat{F}} \ar{d}[left]{\leibpullapp{\dom}(P)} & \rancob{\projl}{\leibpullapp{\dom}(P)} \ar[dashed]{d} & \\
      \Arr{\cat{E}} \times_{\cat{E}} \cat{F} \ar{r}[below]{\projl} & \Arr{\cat{E}} 
    \end{tikzcd}
  \]
  of $\leibpullapp{\dom}(P) \defeq \pair{\FullCartArr{P}}{\dom} \co \FullCartArr{\cat{F}} \to \Arr{\cat{E}} \times_{\cat{E}} \cat{F}$, seen as a fibred functor between the Grothendieck fibrations $\FullCartArr{P} \co \FullCartArr{\cat{F}} \to \Arr{\cat{E}}$ and $\projl \co \Arr{\cat{E}} \times_{\cat{E}} \cat{F} \to \Arr{\cat{E}}$.
\end{definition}

An object of $\Ext{P}$ over a morphism $f \co A \to B$ in $\Arr{\cat{E}}$ thus corresponds to a section $\bm{f} \co \cat{F}_A \to \FullCartArr{\cat{F}}_f$ of the domain projection $\dom \co \FullCartArr{\cat{F}}_f \to \cat{F}_A$, \ie, a functor which extends any $\cat{F}$-structure over $A$ to an $\cat{F}$-structure over $B$ together with a $P$-cartesian morphism over $f$ from the input to the output structure.

\begin{definition}[Double category of extension operations]
  Let $P \co \cat{F} \to \cat{E}$ be a Grothendieck fibration.
  We extend $\VertArr{U_P} \co \Ext{P} \to \Arr{\cat{E}}$ of \cref{extension-vertical-morphisms} to a notion of composable structure $U_P \co \DExt{P} \to \Sq{\cat{E}}$ by taking the vertical identity functor $\idv_{(-)} \co \cat{E} \to \Ext{P}$ to be the transpose of the diagram
    \[
      \begin{tikzcd}
        \cat{F} \ar{dr}[below left]{\pair{\id_{P(-)}}{\Id_{\cat{F}}}} \ar{rr}{\id_{(-)}} & & \FullCartArr{\cat{F}} \ar{dl}{\leibpullapp{\dom}(P)} \\
        & \Arr{\cat{E}} \times_{\cat{E}} \cat{F}
      \end{tikzcd}
    \]
  and vertical composition $\star \co \Ext{P} \times_{\cat{E}} \Ext{P} \to \Ext{P}$ to be the transpose of the diagram
    \[
      \begin{tikzcd}[row sep=large]
        \Ext{P} \times_{\cat{E}} \Ext{P} \times_{\cat{E}} \cat{F} \ar{r}{\Ext{P} \times_{\cat{E}} \epsilon} \ar{dr}[below left]{\VertArr{U_P} \times_{\cat{E}} \VertArr{U_P} \times_{\cat{E}} \cat{F}} &[2em] \Ext{P} \times_{\cat{E}} \FullCartArr{\cat{F}} \ar{rr}{\pair{\epsilon(\Ext{P} \times_{\cat{E}} \dom)}{\projr}} && \FullCartArr{\cat{F}} \times_{\cat{F}} \FullCartArr{\cat{F}} \ar{r}{\circ} &[-1em] \FullCartArr{\cat{F}} \ar{ddll}{\leibpullapp{\dom}(P)} \rlap{.} \\
        & \Arr{\cat{E}} \times_{\cat{E}} \Arr{\cat{E}} \times_{\cat{E}} \cat{F} \ar{dr}[below left]{(\circ) \times_{\cat{E}} \cat{F}}  \\[-1em]
        & & \Arr{\cat{E}} \times_{\cat{E}} \cat{F}
      \end{tikzcd}
    \]
    Conservativity of $\VertArr{U_P}$ follows from the description of morphisms in $\Ext{P}$ in \cref{cartesian-pushforward-morphisms}.
\end{definition}

\begin{proposition}
  \label{extension-dcat-left-connected}
  $U_v \co \DExt{P} \to \Sq{\cat{E}}$ is left-connected.
\end{proposition}
\begin{proof}
  A square with boundary of the form
  \[
    \begin{tikzcd}
      A \ar[verto]{d}[left]{\idv_A} \ar{r}{h} & B \ar[verto]{d}{\bm{g}} \\
      A \ar{r}[below]{k} & C
    \end{tikzcd}
  \]
  in $\DExt{P}$ consists by \cref{cartesian-pushforward-morphisms} of a natural isomorphism $\theta$ such that
  \[
    \begin{tikzcd}[sep=large]
      \cat{F}_{A} \ar[phantom]{dr}{\theta} \ar{r}{\id_{(-)}} & \FullCartArr{\cat{F}}_{\id_A} \ar[phantomcenter]{dr}{\cong} \ar{r}{\dom} & \cat{F}_A \\
      \cat{F}_{B} \ar{u}{\subst{h}} \ar{r}[below]{\bm{g}^\dagger} & \FullCartArr{\cat{F}}_g \ar{u}[description]{\subst{(h,k)}} \ar{r}[below]{\dom} & \cat{F}_B \ar{u}[right]{\subst{h}}
    \end{tikzcd}
    \quad
    =
    \quad
    \begin{tikzcd}[sep=large]
      \cat{F}_A \ar[equals]{r} & \cat{F}_A \\
      \cat{F}_B \ar{u}{\subst{h}} \ar[equals]{r} & \cat{F}_B \ar{u}[right]{\subst{h}} \rlap{.}
    \end{tikzcd}
  \]
  Because any vertical cartesian morphism is an isomorphism, any pair of objects of $\FullCartArr{\cat{F}}_{\id_A}$ are related by a unique domain-fixing isomorphism.
  Thus there is a unique such square provided $gh = k$.
\end{proof}

\begin{proposition}
  \label{extension-dcat-retracts}
  $U_v \co \DExt{P} \to \Sq{\cat{E}}$ admits a codomain retract lifting operator.
\end{proposition}
\begin{proof}
  Suppose we have a codomain retract diagram
  \[
    \begin{tikzcd}
      & A \ar{dl}[above left]{f'} \ar{d}{f} \ar{dr}{f'} \\
      B' \ar{r}[below]{s} & B \ar{r}[below]{r} & B'
    \end{tikzcd}
  \]
  and a vertical morphism over $f$, which is to say a section $\xi \co \cat{F}_A \to \FullCartArr{\cat{F}}_f$ of the domain projection.
  Post-composing with $\subst{(\id_A,s)} \co \FullCartArr{\cat{F}}_f \to \FullCartArr{\cat{F}}_{f'}$ yields a vertical morphism over $f'$.\footnote{Here we abusively write $\subst{(\id_A,s)}$ for the functor which performs the canonical lift along $s$ in the codomain and is the identity in the domain, though we have not assumed that $\subst{\id_A}$ is the identity.}
  This operation can clearly be made functorial in the retract diagram.
\end{proof}

\begin{lemma}
  \label{pullback-van-kampen}
  Let $P \co \cat{E} \to \cat{B}$ be a Grothendieck fibration, $F \co \cat{C} \to \cat{B}$ be a functor, and $c \co \cat{K} \to \cat{C}$ be a diagram.
  If $\psi \co c \to \Delta c_0$ is a colimit cocone such that $F\psi$ is a Van Kampen colimit cocone for $P$, then $\psi$ is Van Kampen for $\subst{F}P$.
\end{lemma}
\begin{proof}
  This is a straightforward consequence of the fact that $\FibOb{\cat{C}}{(\cat{C} \times_{\cat{B}} \cat{E})} \cong \cat{C} \times_{\cat{B}} \FibOb{\cat{B}}{\cat{E}}$.
\end{proof}

\begin{lemma}
  \label{fullcartarr-van-kampen}
  Let $P \co \cat{E} \to \cat{B}$ be a Grothendieck fibration and $d \co \cat{K} \to \Arr{\cat{B}}$ be a diagram.
  If $\delta \co d \to \Delta d_0$ is a colimit cocone such that ${\dom} \circ \delta$ and ${\cod} \circ \delta$ are Van Kampen for $P$, then $\delta$ is Van Kampen for $\FullCartArr{P} \co \FullCartArr{\cat{E}} \to \Arr{\cat{B}}$.
\end{lemma}
\begin{proof}
  Since colimits in arrow categories are computed pointwise, it suffices to check that for any diagram $e \co \cat{K} \to \FullCartArr{\cat{E}}$ over $d$, the induced morphism $\colim ({\dom} \circ e) \to \colim ({\cod} \circ e)$ in $\cat{E}$ is $P$-cartesian.
  This is the case because $\colim ({\dom} \circ e)$ is a colimit in $\FibOb{\cat{B}}{\cat{E}}$, because ${\dom} \circ \delta$ is Van Kampen for $P$.
\end{proof}

By the saturation theorem, we conclude:

\begin{theorem}
  \label{lift-extension-operation}
  Let $\cat{E}$ be a cocomplete category equipped with a $\kappa$-backdrop $\class{M}$ and a diagram $u \co \cat{J} \to \Arr{\cat{E}}$ compatible with $\class{M}$ such that $\dom u$ is levelwise $(\kappa,\class{M})$-small.
  Per \cref{soa-backdrop}, $u$ generates an \textsc{awfs} $(\comonad{L},\monad{R})$ on $\cat{E}$.
  Let $P \co \cat{F} \to \cat{E}$ be a Grothendieck fibration such that
  \begin{itemize}
  \item $\alpha$-indexed colimits in $\class{M}$ are Van Kampen for $P$ for $\alpha \le \kappa$;
  \item cobase changes of maps in $\class{M}$ are Van Kampen for $P$.
  \end{itemize}
  Then any lift of $\Den{u} \co \Arr{\cat{E}} \to \Arr{\cat{E}}$ through $U_P \co \Ext{P} \to \Arr{\cat{E}}$ induces a functor $\Coalg{\UnderPtd{\comonad{L}}} \to \Ext{P}$ over $\Arr{\cat{E}}$ assigning an extension operation to every left map of the \textsc{awfs}.
\end{theorem}
\begin{proof}
  By \cref{soa-copointed-coalgebras-functor}.
  \Cref{extension-dcat-left-connected} gives left-connectedness and \cref{extension-dcat-retracts} provides a codomain retract lifting operator.
  For colimits, \cref{pullback-van-kampen,fullcartarr-van-kampen} imply that $\alpha$-indexed colimits in $\CodClass{\cat{E}}{\class{M}}$ for $\alpha \le \kappa$ and cobase changes of maps in $\CodClass{\cat{E}}{\class{M}}$ are Van Kampen for  $\FullCartArr{P} \co \FullCartArr{F} \to \Arr{\cat{E}}$ and $\projl \co \Arr{\cat{E}} \times_{\cat{E}} \cat{F} \to \Arr{\cat{E}}$.
  Thus \cref{pushforward-colimit} implies that $\DCodClass{\DExt{P}}{\class{M}}$ is $(\kappa,\class{M})$-cellular.
\end{proof}

Finally, we return to the motivating example of extension of fibrations along trivial cofibrations.
When $(\comonad{L},\monad{R})$ is an \textsc{awfs} on a category $\cat{E}$ with pullbacks, the composite $\cod U_{\monad{R}} \co \Alg{\monad{R}} \to \cat{E}$ is a Grothendieck fibration \cite[Proposition 8]{bourke-garner:16}.
When the \textsc{awfs} is generated by a diagram of maps with tiny codomain, this fibration inherits the Van Kampen colimits of the underlying category:

\begin{lemma}
  \label{awfs-algebras-van-kampen}
  Let $u \co \cat{J} \to \Arr{\cat{E}}$ be a diagram of arrows in a category with pullbacks and let $(\comonad{L},\monad{R})$ be an \textsc{awfs} on $\cat{E}$ cofibrantly generated by $u$.
  Suppose that $\cod u$ is levelwise tiny, in the sense that $\Hom{\cat{E}}{\cod u_i}{-}$ preserves all colimits for all $i \in \cat{J}$.
  Given a diagram $Y \co \cat{K} \to \cat{E}$ and colimit cocone $\upsilon \co Y \to \Delta Y_0$, if $\upsilon$ is Van Kampen for $\cod \co \Arr{\cat{E}} \to \cat{E}$, then $\upsilon$ is also Van Kampen for $\cod U_{\monad{R}} \co \Alg{\monad{R}} \to \cat{E}$.
\end{lemma}
\begin{proof}
  By definition of cofibrantly generated \textsc{awfs} (and \cref{lifting-is-algebras}), $\monad{R}$-algebras are equivalently $\SplPtdEndo[u]_{\cat{E}}$-algebras: an $\monad{R}$-algebra structure on $f \in \Arr{\cat{E}}$ is a section of
  \[
    \begin{tikzcd}[sep=large]
      \Hom{\cat{E}}{\cod u_{(-)}}{\dom f} \ar{r}{\leibpullapp{\conjugate{u}}(f)} & \Hom{\Arr{\cat{E}}}{u_{(-)}}{f} \rlap{.}
    \end{tikzcd}
  \]
  Let $\bm{f} \co \cat{K} \to \FibOb{\cat{E}}{(\Alg{\monad{R}})}$ be a diagram over $Y$.
  Then the composite $f \defeq U_{\monad{R}} \bm{f} \co \cat{K} \to \Arr{\cat{E}}$ factors through $\CartArr{\cat{E}}$, so by assumption admits a colimiting cone $\phi \co f \to f_0$ in $\CartArr{\cat{E}}$ over $\upsilon$.

  Since $\cod u$ is levelwise tiny, $\Hom{\cat{E}}{\cod u_i}{\upsilon}$ and $\Hom{\cat{E}}{\cod u_i}{\dom \phi}$ are colimit cocones in $\Set$.
  Because $f$ is a cartesian natural transformation, we have $\Hom{\Arr{\cat{E}}}{u_i}{f_k} \cong \Hom{\cat{E}}{\cod u_i}{Y_k} \times_{\Hom{\cat{E}}{\cod u_k}{Y_0}} \Hom{\Arr{\cat{E}}}{u_i}{f_0}$, and so $\Hom{\Arr{\cat{E}}}{u_i}{\phi}$ is also a colimit cocone by pullback stability of colimits in $\Set$.
  Thus the compatible family of sections for the maps $\leibpullapp{\conjugate{u}}(f_k)$ provided by $\bm{f}$ induces a unique compatible section of $\leibpullapp{\conjugate{u}}(f_0)$, providing a colimiting cocone $\bm{f} \to \Delta \bm{f}_0$ in $\FibOb{\cat{E}}{(\Alg{\monad{R}})}$ over $\upsilon$.
\end{proof}

The uniform fibrations \textsc{awfs} fits this lemma, and so we have:

\begin{example}
  \label{uniform-fibration-extension}
  Let $(t,I)$ be a uniform fibration configuration in a presheaf category $\cat{E}$.
  Write $P \co \Fib{t}{I} \to \cat{E}$ for the category of monad algebras of the associated \textsc{awfs} with its codomain projection.
  Given lifts of $\leibpushapp{\delta_i}\phi^t \co \Slice{\cat{E}}{\Cof} \to \Arr{\cat{E}}$ through $\Ext{P}$ for $i \in \braces{0,1}$, we can construct a functor $\TCof{t}{I} \to \Ext{P}$ over $\Arr{\cat{E}}$ assigning a uniform fibration extension operation to every trivial cofibration.
\end{example}
\begin{proof}
  By \cref{lift-extension-operation} applied with the backdrop of monomorphisms and \cref{awfs-algebras-van-kampen}, it suffices to check that $\alpha$-indexed colimits of monomorphisms and cobase changes of monomorphisms are Van Kampen in $\cat{E}$.
  This is the case in any presheaf category \cites{lack-sobocinski:06}[\S3]{shulman:15}.
\end{proof}

The generating case of \cref{uniform-fibration-extension}, namely extension along maps of the form $\leibpushapp{\delta_i}(m)$ where $m$ is a cofibration, can be treated directly in various cubical settings, as in \textcite[Lemma 7.3 and Corollary 7.4]{sattler:17} and \textcite[Proof of Proposition 120]{awodey:23}.

\begin{example}
  \Textcite[\S3]{shulman:19-all} introduces the framework of \emph{notions of fibred structure} to axiomatize algebraic incarnations of classes of maps such as fibrations and trivial fibrations that are closed under base change.
  In particular, the categories $\Alg{\monad{R}}$ and $\Alg{\UnderPtd{\monad{R}}}$ associated to an \textsc{awfs} $(\comonad{L},\monad{R})$ on a category $\cat{E}$ with pullbacks give rise to notions of fibred structure in $\cat{E}$ \cites[Example 3.7]{shulman:19-all}[Proposition 8]{bourke-garner:16}.

  Given a notion of fibred structure on a category $\cat{E}$, we have in particular a Grothendieck fibration $P \co \cat{F} \to \cat{E}$ from a category of structured maps $\cat{F}$ that projects the codomain of a structured map.
  Shulman's Proposition 3.18(i)$\Rightarrow$(iii) implies that for a \emph{locally representable} notion of fibred structure on $\cat{E}$, any colimit in $\cat{E}$ that is Van Kampen for the codomain fibration $\cod \co \Arr{\cat{E}} \to \cat{E}$ is also Van Kampen for the induced fibration $P$.
  Provided that $\cat{E}$ has enough Van Kampen colimits, extension operations for such structures are thus susceptible to \cref{lift-extension-operation}.
  Indeed, \cref{uniform-fibration-extension} could be factored through a proof that the notion of fibred structure corresponding to uniform fibration monad algebras is locally representable.
\end{example}

