\begin{abstract}
Given any two sequences of complex numbers, we establish simple relations between their binomial convolution and the binomial convolution of their individual binomial transforms. We employ these relations to derive new identities involving Fibonacci numbers, Bernoulli numbers, harmonic numbers, odd harmonic numbers and binomial coefficients.
\end{abstract}

\noindent 2020 {\it Mathematics Subject Classification}: Primary 05A19; Secondary 05A10, 11B68, 11B39. 

\noindent \emph{Keywords:} Binomial transform, binomial coefficient, combinatorial identity, sequence, Bernoulli numbers, harmonic numbers.

\section{Introduction}

Let $n$ be a non-negative integer. Let $(s_k)$ and $(\sigma_k)$, $k=0,1,2,\ldots$, be sequences of complex numbers. It is known that
\begin{equation}\label{first}
s_n  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\sigma _k }\iff \sigma_n  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}s_k } .
\end{equation}
Such sequences $(s_k)$ and $(\sigma_k)$, as given in~\eqref{first}, will be called a binomial-transform pair of the first kind.

Consider two binomial-transform pairs of the first kind, namely, $\{(s_k), (\sigma_k)\}$ and $\{(t_k), (\tau_k)\}$, $k=0,1,2,\ldots$. We will establish the following binomial convolution identity:
\begin{equation*}
\sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k}s_k t_{n-k} }  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\sigma _k \tau _{n-k} } .
\end{equation*}

Let $(\bar s_k)$ and $(\bar\sigma_k)$, $k=0,1,2,\ldots$, be sequences of complex numbers. It is also known that
\begin{equation}\label{second}
\bar s_n  = \sum_{k = 0}^n {( - 1)^{n-k} \binom{{n}}{k}\bar\sigma _k }\iff \bar\sigma_n  = \sum_{k = 0}^n { \binom{{n}}{k}\bar s_k } .
\end{equation}
Such sequences $(\bar s_k)$ and $(\bar\sigma_k)$, as given in~\eqref{second}, will be called a binomial-transform pair of the second kind. In this case we also call $(\bar\sigma_k)$ the binomial transform of $(\bar s_k)$.

Given two binomial-transform pairs of the second kind, say $\{(\bar s_k), (\bar\sigma_k)\}$ and $\{(\bar t_k), (\bar\tau_k)\}$, $k=0,1,2,\ldots$, we will derive the following binomial convolution identity:
\begin{equation*}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\bar s_k \bar t_{n-k} }  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\bar\sigma _k \bar\tau _{n-k} } .
\end{equation*}
Throughout, we will distinguish binomial-transform pairs of the second kind with an overbar on the letter representing each sequence. We will use a Greek alphabet to denote each binomial transform and the corresponding Latin alphabet to represent the original sequence.

We will also derive the following binomial convolution of one sequence and the binomial transform of the other:
\begin{equation*}
\sum_{k = 0}^n {\binom{{n}}{k}\bar s_k \bar\tau_{n-k} }  = \sum_{k = 0}^n {\binom{{n}}{k}\bar\sigma _k \bar t _{n-k} }.
\end{equation*}
Given a binomial-transform pair of the first kind, $\{(s_k),(\sigma_k)\}$ and a binomial-transform pair of the second kind, $\{(\bar t_k),(\bar\tau_k)\}$, $k=0,1,2,\ldots$, we will derive the following binomial convolution:
\begin{equation*}
\sum_{k = 0}^n {\binom{{n}}{k}s_k \bar t_{n-k} }  = \sum_{k = 0}^n {(-1)^k\binom{{n}}{k} \sigma_k \bar \tau _{n-k} } .
\end{equation*}

\begin{remark}
Although conversion from one kind of binomial transforms to the other is, in general, very straightforward (see Remark~\ref{rem.r7dv221}), it is convenient to retain the distinction between the two kinds because binomial transform identities occur naturally in either of the two kinds. Thus, binomial convolution identities can be written directly without the need to convert from one kind to the other.
\end{remark}

The binomial convolution identities developed in this paper will facilitate the discovery of an avalanche of new combinatorial identities. To close this section, we present a couple of identities, selected from our results, to whet the reader's appetite for reading on.

We derived various general identities involving binomial transform pairs, such as

\begin{equation*}
\sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k}\binom{{y - k}}{x}t_{n - k} }  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\binom{{y - k}}{{y - x}}\tau _{n - k} }, 
\end{equation*}

\begin{equation*}
\sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k}\frac{{m\,H_{k + m} }}{{k + m}}\,t_{n - k} } = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\binom{{k + m}}{m}^{ - 1} \left( {H_{k + m}  - H_k } \right)\tau _{n - k} },
\end{equation*}
and
\begin{equation*}
\sum_{k = 0}^n {\binom{{n}}{k}H_{k + m} \bar t_{n - k} }  = H_m \bar \tau _n  - \sum_{k = 1}^n {( - 1)^k \binom{{n}}{k}\binom{{k + m}}{m}^{ - 1}\frac1k\, \bar \tau _{n - k} } ,
\end{equation*}
where $H_k$ is a harmonic number and $m$ is a complex number that is not a negative integer.

We discovered the following binomial convolution of harmonic and odd harmonic numbers:
\begin{equation*}
\sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k}H_k O_{n - k} }= \sum_{k = 1}^{n - 1} {( - 1)^k \binom{{n}}{k}\frac{{2^{2\left( {n - k} \right) - 1} }}{{k\left( {n - k} \right)}}\binom{{2\left( {n - k} \right)}}{{n - k}}^{ - 1} } .
\end{equation*}
We also obtained some identities involving Bernoulli numbers and Bernoulli polynomials, including the following:
\begin{equation*}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\left( {\frac{y}{w}} \right)^k B_{n - k} (y)B_k (w)}  = \frac{{ny}}{{2w}}B_{n - 1} \left( {1 - \left( {\frac{y}{w}} \right)^{n - 2} } \right)
\end{equation*}
and
\begin{equation*}
\sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k}\binom{{x}}{k}B_{n - k} }  = \sum_{k = 0}^n {\binom{{n}}{k}\binom{{x + k}}{k}B_{n - k} } ,
\end{equation*}
where $x$, $y$ and $w$ are complex numbers.

We found the following binomial convolution of Fibonacci and Bernoulli numbers, valid for $n$ an even integer:
\begin{equation*}
\sum_{k = 0}^n {\binom{{n}}{k}F_k B_{n - k} }  = 0.
\end{equation*}
We obtained the following polynomial identities involving, respectively, harmonic numbers and odd harmonic numbers:
\begin{equation*}
\sum_{k = 0}^n {\binom{{n}}{k}H_k t^k }  =\sum_{k = 1}^n {( - 1)^{k - 1} \binom{{n}}{k}\frac{1}{k}\,t^k \left( {1 + t} \right)^{n - k} } 
\end{equation*}
and
\begin{equation*}
\sum_{k = 0}^n {\binom{{n}}{k}O_k t^k }  =\sum_{k = 1}^n {( - 1)^{k - 1} \binom{{n}}{k}2^{2k-1}\binom{2k}k^{-1}\frac{1}{k}\,t^k \left( {1 + t} \right)^{n - k} } ,
\end{equation*}
with the special values
\begin{equation*}
\sum_{k = 0}^n {\binom{{n}}{k}H_k }  = \sum_{k = 1}^n {( - 1)^{k - 1} 2^{n - k} \binom{{n}}{k}\frac{1}{k}} 
\end{equation*}
and
\begin{equation*}
\sum_{k = 0}^n {\binom{{n}}{k}O_k }  = \sum_{k = 1}^n {( - 1)^{k - 1} 2^{n + k - 1} \binom{{n}}{k}\binom{2k}k^{-1}\frac{1}{k}}. 
\end{equation*}
We close tis section by giving a short description of each of the special numbers from which illustrations will be drawn.

Binomial coefficients are defined, for non-negative integers $i$ and $j$, by
\begin{equation*}
\binom ij=
\begin{cases}
\dfrac{{i!}}{{j!(i - j)!}}, & \text{$i \ge j$};\\
0, & \text{$i<j$};
\end{cases}
\end{equation*}
the number of distinct sets of $j$ objects that can be chosen from $i$ distinct objects.

Generalized binomial coefficients are defined for complex numbers $r$ and $s$ by
\begin{equation*}
\binom rs= \frac{{\Gamma (r + 1)}}{{\Gamma (s + 1)\Gamma (r - s + 1)}},
\end{equation*}
where the Gamma function, $\Gamma(z)$, is defined for $\Re(z)>0$ by
\begin{equation*}
\Gamma (z) = \int_0^\infty  {e^{ - t} t^{z - 1}dt}  = \int_0^\infty  {\left( {\log (1/t)} \right)^{z - 1}dt},
\end{equation*}
and is extended to the rest of the complex plane, excluding the non-positive integers, by analytic continuation.

Harmonic numbers, $H_n$, and odd harmonic numbers, $O_n$, are defined for non-negative integers $n$ by
\begin{equation*}
H_n=\sum_{k=1}^n\frac1k,\quad O_n=\sum_{k=1}^n\frac1{2k-1},\quad H_0=0=O_0.
\end{equation*}

The Bernoulli numbers, $B_k$, are defined by the generating function
\begin{equation*}
\frac{z}{{e^z  - 1}} = \sum_{k = 0}^\infty  {B_k \frac{{z^k }}{{k!}}},\quad z<2\pi\,,
\end{equation*}
and the Bernoulli polynomials by the generating function
\begin{equation*}
\frac{{ze^{xz} }}{{e^z  - 1}} = \sum_{k = 0}^\infty  {B_k (x)\frac{{z^k }}{{k!}}},\quad|z|<2\pi\,.
\end{equation*}
Clearly, $B_k=B_k(0)$.

The first few Bernoulli numbers are
\begin{equation*}
B_0  = 1,\,B_1  =  - \frac{1}{2},\,B_2  = \frac{1}{6},\,B_3  = 0,\,B_4  =  - \frac{1}{{30}},\,B_5  = 0,\,B_6  = \frac{1}{{42}},\,B_7  = 0,\,\ldots\,,
\end{equation*}
while the first few Bernoulli polynomials are
\begin{equation*}
\begin{split}
&B_0 (x)= 1,\quad B_1 (x) = x - \frac{1}{2},\quad B_2 (x) = x^2  - x + \frac{1}{6},\quad B_3 (x) = x^3  - \frac{3}{2}x^2  + \frac{1}{2}x.
\end{split}
\end{equation*}
An explicit formula for the Bernoulli polynomials is
\begin{equation*}
\frac{B_n (x)}{x^n} = \sum_{k = 0}^n {\binom nk\frac{B_k}{x^k} }\,,
\end{equation*}
while a recurrence formula for them is
\begin{equation}\label{eq.v8egj4b}
B_n (x + 1) = \sum_{k = 0}^n {\binom nkB_k (x)}.
\end{equation}
The Fibonacci numbers, $F_n$, and the Lucas numbers, $L_n$, are defined, for \mbox{$n\in\mathbb Z$}, through the recurrence relations 
\begin{equation*}
F_n=F_{n-1}+F_{n-2}, \mbox{($n\ge 2$)},\quad\mbox{$F_0=0$, $F_1=1$};
\end{equation*}
and
\begin{equation*}
L_n=L_{n-1}+L_{n-2}, \mbox{($n\ge 2$)},\quad\mbox{$L_0=2$, $L_1=1$};
\end{equation*}
with
\begin{equation}
F_{-n}=(-1)^{n-1}F_n\,,\quad L_{-n}=(-1)^nL_n\,.
\end{equation}

Explicit formulas (Binet formulas) for the Fibonacci and Lucas numbers are
\begin{equation*}
F_n  = \frac{{\alpha ^n  - \beta ^n }}{{\alpha  - \beta }},\quad L_n  = \alpha ^n  + \beta ^n,\quad n\in\mathbb Z,
\end{equation*}
where $\alpha=(1+\sqrt 5)/2$ is the golden ratio and $\beta=(1-\sqrt 5)/2=-1/\alpha$.

The generalized Fibonacci sequence, $(G_n)$, $n=0,1,2,\ldots$, the so-called gibonacci sequence, is a generalization of $F_n$ and $L_n$; having the same recurrence relation as the Fibonacci sequence but with arbitrary initial values. Thus
\begin{equation*}
G_n  = G_{n - 1}  + G_{n - 2},\quad (n \ge 2);
\end{equation*}
with
\begin{equation*}
\quad G_{-n}=G_{-n+2}-G_{-n+1}.
\end{equation*}
where $G_0$ and $G_1$ arbitrary numbers (usually integers) not both zero. 

\section{Identities involving binomial-transform pairs of the first kind}
Our first main result is stated in Theorem~\ref{thm.main1}; we require the result stated in the next lemma for its proof.
\begin{lemma}
Let $\left\{(a_k),(\alpha_k)\right\}$, $k=0,1,2,\ldots$, be a binomial-transform pair of the first kind. Let $\mathcal L_x$ be a linear operator defined by $\mathcal L_x(x^j)=a_j$ for every complex number $x$ and every non-negative integer~$j$. Then $\mathcal L_x((1-x)^j)=\alpha_j$.
\end{lemma}
\begin{proof}
We have
\begin{align*}
\mathcal L_x\left( {\left( {1 - x} \right)^j } \right) = \mathcal L_x\left( {\sum_{k = 0}^j {( - 1)^k \binom{{j}}{k}x^k } } \right) &= \sum_{k = 0}^j {( - 1)^k \binom{{j}}{k}\mathcal L_x\left( {x^k } \right)} \\
& = \sum_{k = 0}^j {( - 1)^k \binom{{j}}{k}a_k }\\ 
&=\alpha_j.
\end{align*}
\end{proof}
\begin{theorem}\label{thm.main1}
Let $n$ be a non-negative integer. If $\{(s_k), (\sigma_k)\}$ and $\{(t_k), (\tau_k)\}$, $k=0,1,2,\ldots$, are binomial-transform pairs of the first kind, then
\begin{equation}\label{main1}
\sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k}s_k t_{n-k} }  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\sigma _k \tau _{n-k} } .
\end{equation}
\end{theorem}

\begin{proof}
Let $n$ be a non-negative integer. Let $x$ and $y$ be complex numbers. Consider the following identity whose veracity is readily established by the binomial theorem:
\begin{equation}\label{eq.fltsd62}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k} y^{n - k}x^k }  = \sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k} \left( {1 - y} \right)^{n - k} \left( {1 - x} \right)^k} .
\end{equation}
Let $(t_j)$, $j=0,1,2,\ldots$, be a sequence of complex numbers. Let $\mathcal L_x(x^j)=t_j$ .

Operate on both sides of~\eqref{eq.fltsd62} with $\mathcal L_x$ to obtain
\begin{equation*}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k} y^{n - k}t_k }  = \sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k} \left( {1 - y} \right)^{n - k} \tau _k} ,
\end{equation*}
where
\begin{equation*}
\tau _k  = \mathcal L_x((1-x)^k)=\sum_{i = 0}^k {( - 1)^i \binom{{k}}{i}t_i }.
\end{equation*}
Thus,
\begin{equation}\label{eq.renl1hy}
\sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k}y^kt_{n - k}  }  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\left( {1 - y} \right)^k\tau _{n - k} } .
\end{equation}
Let $(s_j)$, $j=0,1,2,\ldots$, be a sequence of complex numbers. Let $\mathcal L_y(y^j)=s_j$. The action of $\mathcal L_y$ on~\eqref{eq.renl1hy} produces
\begin{equation*}
\sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k}s_kt_{n - k}  }  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\sigma_k\tau _{n - k} } ,
\end{equation*}
where
\begin{equation*}
\sigma _k  = \mathcal L_y((1-y)^k)=\sum_{i = 0}^k {( - 1)^i \binom{{k}}{i}s_i },
\end{equation*}
and the proof is complete.

\end{proof}
In the next example we illustrate Theorem~\ref{thm.main1}.
\begin{example}
Consider the following identity~\cite[Equation (10.7)]{boyadzhiev16} where $x$ and $y$ are complex numbers and $n$ is a non-negative integer:
\begin{equation}\label{eq.zw4rawn}
\sum_{k = 0}^n {\binom{{n}}{k}( - 1)^k \binom{{y - k}}{x} }  = \binom{{y - n}}{{y - x}}.
\end{equation}
From~\eqref{eq.zw4rawn}, we can choose
\begin{equation*}
s_k  = \binom{{y - k}}{x},\quad\sigma _k  = \binom{{y - k}}{{y - x}},
\end{equation*}
and use these in~\eqref{main1} to obtain the following identity
\begin{equation}\label{eq.o20tqr7}
\sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k}\binom{{y - k}}{x}t_{n - k} }  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\binom{{y - k}}{{y - x}}\tau _{n - k} }, 
\end{equation}
which holds for every binomial-transform pair of the first kind $\{(t_k),(\tau_k)\}$.

As an immediate consequence of~\eqref{eq.o20tqr7}, we have the following polynomial identity in the complex variable $t$:
\begin{equation*}
\sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k}\binom{{y - k}}{x}t^{n - k} }  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\binom{{y - k}}{{y - x}}\left( {1 - t} \right)^{n - k} } ,
\end{equation*}
which can also be written as
\begin{equation}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\binom{{y + k}}{x}t^k }  = \sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k}\binom{{y + k}}{{y + n - x}}\left( {1 - t} \right)^k },
\end{equation}
which is valid for all complex numbers $x$,  $y$ and $t$.
\end{example}

\begin{example}\label{ex.ur405iz}
If we identify
\begin{equation*}
s_k  = \frac{{H_{k + m} }}{{k + m}},\quad\sigma _k  = \frac{{H_{k + m}  - H_k }}{m}\binom{{k + m}}{k}^{ - 1}, 
\end{equation*}
from the following identity~\cite[Equation (9.46)]{boyadzhiev16}:
\begin{equation*}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\frac{{H_{k + m} }}{{k + m}}}  = \frac{{H_{n + m}  - H_n }}{m}\binom{{n + m}}{n}^{ - 1},\quad m\ne 0,
\end{equation*}
then, from~\eqref{main1}, we obtain the following identity
\begin{align}\label{eq.awm96g7}
\sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k}\frac{{m\,H_{k + m} }}{{k + m}}\,t_{n - k} } = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\binom{{k + m}}{m}^{ - 1} \left( {H_{k + m}  - H_k } \right)\tau _{n - k} },
\end{align}
which holds for any binomial-transform pair of the first kind, $\{(t_k),(\tau_k)\}$, for every complex number $m$ that is not a non-positive number and every non-negative integer $n$.

In particular, since
\begin{equation*}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\frac{{G_{tk + r} }}{{L_t^k }}}  = \frac{{( - 1)^r }}{{L_t^n }}\left( {G_0 L_{tn - r}  - G_{tn - r} } \right),
\end{equation*}
using
\begin{equation*}
t_k  = \frac{{G_{tk + r} }}{{L_t^k }},\quad\tau _k  = \frac{{( - 1)^r }}{{L_t^k }}\left(G_0L_{tk-r}-G_{tk-r}\right),
\end{equation*}
in~\eqref{eq.awm96g7} yields the following general Fibonacci-harmonic number identity:
\begin{align}
&\sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k}\frac{{m\,H_{k + m} }}{{k + m}}L_t^k G_{t(n - k) + r} },\nonumber\\
&\qquad  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\binom{{k + m}}{m}^{ - 1} \left( {H_{k + m}  - H_k } \right)L_t^k \left( {G_0 L_{t(n - k) - r}  - G_{t(n - k) - r} } \right)}; 
\end{align}
and, in particular,
\begin{equation}
\sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k}\frac{{m }}{{k + m}}H_{k + m}F_{n - k} }  = \sum_{k = 0}^n {( - 1)^{k-1} \binom{{n}}{k}\binom{{k + m}}{m}^{ - 1} \left( {H_{k + m}  - H_k } \right)F_{n - k} } ,
\end{equation}
with the special value
\begin{equation}
\sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k}\frac{{H_{k + 1} F_{n - k} }}{{k + 1}}}  = \sum_{k = 0}^n {( - 1)^{k-1} \binom{{n}}{k}\frac{{F_{n - k} }}{{\left( {k + 1} \right)^2 }}} .
\end{equation}
\end{example}

\begin{example}
From~\eqref{eq.zw4rawn} and~\cite[Equation (10.1)]{boyadzhiev16}:
\begin{equation}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\binom{{x}}{k}\binom{{y}}{k}^{ - 1} }  = \binom{{y - x}}{n}\binom{{y}}{n}^{ - 1},\quad y-n\not\in\mathbb Z^-,y\in\mathbb C,\label{eq.a45516v}
\end{equation}
we can choose
\begin{equation*}
s_k  = \binom{{y - k}}{x},\quad\sigma _k  = \binom{{y - k}}{{y - x}},
\end{equation*}
and
\begin{equation*}
t_k  = \binom{{u}}{k}\binom{{v}}{k}^{ - 1} ,\quad\tau _k  = \binom{{v - u}}{k}\binom{{v}}{k}^{ - 1}. 
\end{equation*}
Using these in~\eqref{main1}, we obtain the following identity
\begin{align}
&\sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k}\binom{{y - k}}{x}\binom{u}{{n - k}}\binom{{v}}{{n - k}}^{ - 1} }\nonumber \\
&\qquad = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\binom{{y - k}}{{y - x}}\binom{{v - u}}{{n - k}}\binom{{v}}{{n - k}}^{ - 1} } ,
\end{align}
which is valid for complex numbers $x$, $y$, $u$ and $v$ such that $v$ is not a non-negative number that is less than $n$.

In particular, at $v=n$, we get
\begin{equation}
\sum_{k = 0}^n {( - 1)^{n - k} \binom{{y - k}}{x}\binom{u}{{n - k}}}  = \sum_{k = 0}^n {( - 1)^k \binom{{y - k}}{{y - x}}\binom{{n - u}}{{n - k}}} ,
\end{equation}
with the special value
\begin{equation}
\sum_{k = 0}^n {( - 1)^k \binom nk\binom{{y - k}}{{y - x}}}=\binom{y-n}x ,
\end{equation}
which is the binomial transform of the first kind of~\eqref{eq.zw4rawn}.
\end{example}

\begin{example}\label{ex.omtqrl4}
From~\cite[Equation (9.37)]{boyadzhiev16}:
\begin{equation}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}H_{k + m} }  =  - \frac{1}{n}\binom{{n + m}}{m}^{ - 1},\quad n\ne0,\label{eq.wt34kp1}
\end{equation}
and~\cite[Equation (9.51)]{boyadzhiev16}:
\begin{equation}\label{eq.jupxl7y}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}O_k }  =  - \binom{{2n}}{n}^{ - 1} \frac{{2^{2n - 1} }}{n},
\end{equation}
we can identify
\begin{equation*}
s_k  = H_{k + m} ,\quad\sigma _k  =  \frac{{\delta _{k0}(1+H_m)-1 }}{{k + \delta _{k0} }}\binom{{k + m}}{m}^{ - 1},  
\end{equation*}
and
\begin{equation*}
t_k  = O_k ,\quad\tau _k  =  - \frac{{1 - \delta _{k0} }}{{k + \delta _{k0} }}\binom{{2k}}{k}^{ - 1} 2^{2k - 1}. 
\end{equation*}
Here and throughout this paper, $\delta_{ij}$ is Kronecker's delta having the value $1$ when $i=j$ and is zero otherwise.

Using these in~\eqref{main1} leads to the following harmonic number identity:
\begin{align}
&\sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k}H_{k + m} O_{n - k} }\nonumber\\
&\qquad  = -\frac{H_m}n\binom{2n}n^{-1}2^{2n-1}+\sum_{k = 1}^{n - 1} {( - 1)^k \binom{{n}}{k}\frac{{2^{2\left( {n - k} \right) - 1} }}{{k\left( {n - k} \right)}}\binom{{k + m}}{m}^{ - 1} \binom{{2\left( {n - k} \right)}}{{n - k}}^{ - 1} } ,
\end{align}
which is valid for every positive integer $n$ and every complex number $m$ that is not a negative integer.

In particular, we have the following alternating binomial convolution of harmonic number and odd harmonic number:
\begin{align}
\sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k}H_k O_{n - k} }= \sum_{k = 1}^{n - 1} {( - 1)^k \binom{{n}}{k}\frac{{2^{2\left( {n - k} \right) - 1} }}{{k\left( {n - k} \right)}}\binom{{2\left( {n - k} \right)}}{{n - k}}^{ - 1} } .
\end{align}

\end{example}

\begin{corollary}
Let $n$ be a non-negative integer. If $\{(s_k), (\sigma_k)\}$ and $\{(t_k), (\tau_k)\}$, $k=0,1,2,\ldots$, are binomial-transform pairs, then
\begin{equation}
\sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k}\sigma_k t_{n-k} }  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}s _k \tau _{n-k} }.
\end{equation}

\end{corollary}

\begin{corollary}
Let $n$ be a non-negative integer. If $\{(s_k), (\sigma_k)\}$, $k=0,1,2,\ldots$, is a binomial-transform pair, then
\begin{equation}\label{eq.ci4kck8}
\sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k}s_k s_{n-k} }  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\sigma _k \sigma _{n-k} } .
\end{equation}
\end{corollary}

\begin{remark}
We deduce from~\eqref{eq.ci4kck8} that if $n$ is a non-negative integer, then
\begin{equation}\label{eq.pt7l41w}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}s_k s_{n-k} }  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\sigma _k \sigma _{n-k} } ,
\end{equation}
with each sum being $0$ for odd $n$.
\end{remark}

\begin{example}
Plugging $s_k$ and $\sigma_k$ from Example~\ref{ex.ur405iz} into~\eqref{eq.pt7l41w} yields, for $n$ a non-negative integer and $m$ a complex number that is not a negative integer,
\begin{align}
&\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\frac{{m^2 H_{k + m} H_{n - k + m} }}{{\left( {k + m} \right)\left( {n - k + m} \right)}}}\nonumber\\
&\qquad  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\binom{{k + m}}{k}^{ - 1} \binom{{n - k + m}}{{n - k}}^{ - 1} \left( {H_{k + m}  - H_k } \right)\left( {H_{n - k + m}  - H_{n - k} } \right)} ,
\end{align}
and, in particular,
\begin{equation}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\frac{{H_{k + 1} H_{n - k + 1} }}{{\left( {k + 1} \right)\left( {n - k + 1} \right)}}}  = \sum_{k = 0}^n {\frac{{( - 1)^k }}{{\left( {k + 1} \right)^2 \left( {n - k + 1} \right)^2 }}\binom{{n}}{k}} .
\end{equation}
\end{example}
\begin{example}
From~\eqref{eq.a45516v}, with
\begin{equation*}
s_k  = \binom{{x}}{k}\binom{{y}}{k}^{ - 1} ,\quad\sigma _k  = \binom{{y - x}}{k}\binom{{y}}{k}^{ - 1}, 
\end{equation*}
identity~\eqref{eq.pt7l41w} gives
\begin{align}
&\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\binom{{x}}{k}\binom{{x}}{{n - k}}\binom{y}{k}^{ - 1} \binom{{y}}{{n - k}}^{ - 1} } \nonumber\\
&\qquad = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\binom{{y - x}}{k}\binom{{y - x}}{{n - k}}\binom{{y}}{k}^{ - 1} \binom{{y}}{{n - k}}^{ - 1} } ,
\end{align}
which, upon setting $x=n$ and $y=n$, in turn, yields
\begin{align}\label{eq.hiez2vp}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}^3 \binom{y}{k}^{ - 1} \binom{{y}}{{n - k}}^{ - 1} }  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\binom{{y - n}}{k}\binom{{y - n}}{{n - k}}\binom{{y}}{k}^{ - 1} \binom{{y}}{{n - k}}^{ - 1} } 
\end{align}
and
\begin{equation}\label{eq.u00e6qz}
\sum_{k = 0}^n {( - 1)^k \binom{{x}}{k}\binom{{x}}{{n - k}}\binom{{n}}{k}^{ - 1} }  = \sum_{k = 0}^n {( - 1)^k \binom{{n - x}}{k}\binom{{n - x}}{{n - k}}\binom{{n}}{k}^{ - 1} } .
\end{equation}
Setting $y=-1$ in~\eqref{eq.hiez2vp} gives, after some simplification,
\begin{equation*}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}^3 }  = \sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k}\binom{{n + k}}{k}\binom{{2n - k}}{{n - k}}} ,
\end{equation*}
the left hand side of which is known to be
\begin{equation*}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}^3 } 
=\begin{cases}
 0, &\text{if $n$ is odd;}\\ 
 ( - 1)^{n/2} \left( {3n/2} \right)!\left( {(n/2)!} \right)^{ - 3},&\text{if $n$ is even.}  \\ 
 \end{cases} 
\end{equation*}
We therefore obtain
\begin{equation}
\sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k}\binom{{n + k}}{k}\binom{{2n - k}}{{n - k}}}
=\begin{cases}
 0, &\text{if $n$ is odd;}\\ 
 ( - 1)^{n/2} \left( {3n/2} \right)!\left( {(n/2)!} \right)^{ - 3},&\text{if $n$ is even.}  \\ 
 \end{cases} 
\end{equation}
Similarly, setting $x=-1$ in~\eqref{eq.u00e6qz} gives
\begin{equation*}
\sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k}^{ - 1} }  = \sum_{k = 0}^n {(-1)^k\binom{{n}}{k}\frac{{\left( {n + 1} \right)^2 }}{{\left( {n - k + 1} \right)\left( {k + 1} \right)}}} ,
\end{equation*}
from which we get
\begin{equation}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\frac{1}{{\left( {n - k + 1} \right)\left( {k + 1} \right)}}}  = \frac{{1 + ( - 1)^n }}{{\left( {n + 1} \right)\left( {n + 2} \right)}},
\end{equation}
upon using~\cite{sury04}:
\begin{equation*}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}^{ - 1} }  = \left( {1 + ( - 1)^n } \right)\frac{{n + 1}}{{n + 2}}.
\end{equation*}
\end{example}

A sequence $(s_k)$, $k=0,1,2,\ldots$, for which
\begin{equation*}
s_n  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}s_k },
\end{equation*}
for every non-negative integer $n$ will be called an invariant sequence, following Sun~\cite{sun01}.

A sequence $(s_k)$, $k=0,1,2,\ldots$, for which
\begin{equation*}
-s_n  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}s_k },
\end{equation*}
for every non-negative integer $n$ will be called an inverse invariant sequence.
Many invariant sequences are known (see e.g.~Sun~\cite{sun01}, Boyadzhiev~\cite{boyadzhiev18}). Examples include $(L_k)$, $(kF_{k-1})$, $(\binom{x/2}k/\binom xk)$, $0\ne x\not\in\mathbb Z^+$, $(\binom{2k}k/2^{2k})$. Inverse invariant sequences include $(F_k)$ and $(H_k/(k+1))$. 

\begin{corollary}\label{cor.rgyk46r}
Let $(s_k)$ and $(t_k)$, $k=0,1,2,\ldots$, be two sequences of complex numbers. Let $n$ be a non-negative integer. If both sequences are invariant or both are inverse invariant, then
\begin{equation}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}s_k t_{n - k} }  = 0,\text{ if $n$ is odd;}
\end{equation}
while if one of the sequences is invariant and the other is inverse invariant, then
\begin{equation}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}s_k t_{n - k} }  = 0,\text{ if $n$ is even.}
\end{equation}

\end{corollary}

\begin{remark}
The results stated in Corollary~\ref{cor.rgyk46r} were also obtained by Wang~\cite{wang05}.
\end{remark}

\begin{example}
If $n$ is a non-negative odd integer and $x$ is a non-zero complex number that is not a positive integer that is less than $n$, then
\begin{equation}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\binom{{x/2}}{k}\binom{{x}}{k}^{ - 1} L_{n - k} }  = 0.
\end{equation}
\end{example}

\section{Identities involving binomial-transform pairs of the second kind}

\begin{lemma}
Let $\left\{(\bar a_k),(\bar\alpha_k)\right\}$, $k=0,1,2,\ldots$, be a binomial-transform pair of the second kind. Let $\mathcal M_x$ be a linear operator defined by $\mathcal M_x(x^j)=\bar a_j$ for every complex number $x$ and every non-negative integer~$j$. Then $\mathcal M_x((1+x)^j)=\bar\alpha_j$.
\end{lemma}
\begin{proof}
We have
\begin{align*}
\mathcal M_x\left( {\left( {1 + x} \right)^j } \right) = \mathcal M_x\left( {\sum_{k = 0}^j { \binom{{j}}{k}x^k } } \right) &= \sum_{k = 0}^j {\binom{{j}}{k}\mathcal M_x\left( {x^k } \right)} \\
& = \sum_{k = 0}^j {\binom{{j}}{k}\bar a_k }\\ 
&=\bar\alpha_j.
\end{align*}
\end{proof}

\begin{theorem}\label{thm.slg7tm1}
Let $n$ be a non-negative integer. If $\{(\bar s_k), (\bar\sigma_k)\}$ and $\{(\bar t_k), (\bar\tau_k)\}$, $k=0,1,2,\ldots$, are binomial-transform pairs of the second kind, then
\begin{equation}\label{main2}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\bar s_k \bar t_{n-k} }  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\bar\sigma _k \bar\tau _{n-k} } .
\end{equation}
\end{theorem}

\begin{proof}
Write~\eqref{eq.fltsd62} as
\begin{equation}\label{eq.ch50dhg}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k} y^{n - k}x^k }  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k} \left( {1 + y} \right)^{n - k} \left( {1 + x} \right)^k} .
\end{equation}
Let $(\bar t_j)$, $j=0,1,2,\ldots$, be a sequence of complex numbers. Let $\mathcal M_x(x^j)=\bar t_j$ .

Operate on both sides of~\eqref{eq.ch50dhg} with $\mathcal M_x$ to obtain
\begin{equation*}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k} y^{n - k}\bar t_k }  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k} \left( {1 + y} \right)^{n - k} \bar\tau _k} ,
\end{equation*}
where
\begin{equation*}
\bar\tau _k  = \mathcal M_x((1+x)^k)=\sum_{i = 0}^k {\binom{{k}}{i}\bar t_i }.
\end{equation*}
Thus,
\begin{equation}\label{eq.cr8jcr4}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}y^k\bar t_{n - k}  }  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\left( {1 + y} \right)^k\bar\tau _{n - k} } .
\end{equation}
Let $(\bar s_j)$, $j=0,1,2,\ldots$, be a sequence of complex numbers. Let $\mathcal M_y(y^j)=\bar s_j$. The action of $\mathcal M_y$ on~\eqref{eq.cr8jcr4} produces
\begin{equation*}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\bar s_k\bar t_{n - k}  }  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\bar\sigma_k\bar\tau _{n - k} } ,
\end{equation*}
where
\begin{equation*}
\bar\sigma _k  = \mathcal M_y((1+y)^k)=\sum_{i = 0}^k { \binom{{k}}{i}\bar s_i },
\end{equation*}
and the proof is complete.

\end{proof}

\begin{example}
Consider the general recurrence relation for Bernoulli polynomials:
\begin{equation}\label{eq.dyudhfw}
\frac{{B_n \left( {x + y} \right)}}{{y^n }} = \sum_{k = 0}^n {\binom{{n}}{k}\frac{{B_k (x)}}{{y^k }}}.
\end{equation}
If we choose
\begin{equation*}
\bar s_k  = \frac{{B_k (x)}}{{y^k }},\quad\bar \sigma _k  = \frac{{B_k \left( {x + y} \right)}}{{y^k }},
\end{equation*}
in~\eqref{main2}, we obtain
\begin{equation}\label{eq.bf4tiok}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}y^k B_{n - k} (x)\bar t_k }  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}y^k B_{n - k} \left( {x + y} \right)\bar \tau _k } ,
\end{equation}
which is valid for complex variables $x$ and $y$ and any binomial transform pair $\{(\bar s_k),(\bar\sigma_k)\}$ of the second kind.

Many results can be derived from~\eqref{eq.bf4tiok}. To begin with, we have the following polynomial identity:
\begin{equation}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}y^k B_{n - k} (x)t^k }  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}y^k B_{n - k} \left( {x + y} \right)\left( {1 + t} \right)^k } ,
\end{equation}
which holds for complex numbers $x$, $y$ and $t$.

Choosing
\begin{equation*}
\bar t_k  = \frac{{B_k (z)}}{{w^k }},\quad\bar \tau _k  = \frac{{B_k \left( {z + w} \right)}}{{w^k }},
\end{equation*}
in~\eqref{eq.bf4tiok} leads to
\begin{align}
&\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\left( {y/w} \right)^k B_{n - k} (x)B_k (z)}\nonumber\\
&\qquad  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\left( {y/w} \right)^k B_{n - k} \left( {x + y} \right)B_k \left( {z + w} \right)} ,
\end{align}
giving, in particular,
\begin{align}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}B_{n - k} (x)B_k (z)}  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}B_{n - k} \left( {x + w} \right)B_k \left( {z + w} \right)} ,
\end{align}
and
\begin{equation}\label{eq.zc4ufo6}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\left( {y/w} \right)^k B_{n - k} \left( {y} \right)B_k \left( {w} \right)}=\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\left( {y/w} \right)^k B_{n - k}B_k}.
\end{equation}

\end{example}

\begin{proposition}
If $n$ is a positive odd integer and $y$ and $w$ are complex numbers, then
\begin{equation}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\left( {\frac{y}{w}} \right)^k B_{n - k} (y)B_k (w)}  = \frac{{ny}}{{2w}}B_{n - 1} \left( {1 - \left( {\frac{y}{w}} \right)^{n - 2} } \right).
\end{equation}

\end{proposition}

\begin{proof}
This is a consequence of the fact that the right-hand side of~\eqref{eq.zc4ufo6} can be written as
\begin{equation*}
\sum_{k = 0}^{\left\lfloor {n/2} \right\rfloor } {\binom{{n}}{{2k}}(y/w)^{2k} B_{n - 2k} B_{2k} }  - \sum_{k = 1}^{\left\lceil {n/2} \right\rceil } {\binom{{n}}{{2k - 1}}(y/w)^{2k - 1} B_{n - 2k + 1} B_{2k - 1} }, 
\end{equation*}
and the fact that $B_j$ is zero for odd $j$ greater than unity.
\end{proof}

\begin{example}
Using the binomial-transform pairs
\begin{equation}\label{munb79m}
\bar s_k  = \binom{{x}}{k},\quad\bar \sigma_k  = \binom{{x + k}}{k},
\end{equation}
obtained from~\cite[Equation (10.10d)]{boyadzhiev16}:
\begin{equation}
\sum_{k = 0}^n {\binom{{n}}{k}\binom{{x}}{k}}  = \binom{{n + x}}{n}\label{eq.s21u1g9}
\end{equation}
and
\begin{equation}
\bar t_k  = B_k ,\quad\bar \tau _k  = ( - 1)^k B_k,
\end{equation}
found from the recurrence relation
\begin{equation}\label{eq.sh7iwik}
\sum_{k = 0}^n {\binom nkB_k }  = ( - 1)^n B_n,
\end{equation}
in~\eqref{main2} gives
\begin{equation}
\sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k}\binom{{x}}{k}B_{n - k} }  = \sum_{k = 0}^n {\binom{{n}}{k}\binom{{x + k}}{k}B_{n - k} } .
\end{equation}
\end{example}

\begin{corollary}
Let $n$ be a non-negative integer. If $\{(\bar s_k), (\bar\sigma_k)\}$ is a binomial-transform pair of the second kind, then
\begin{equation}\label{s12ccud}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\bar s_k \bar s_{n-k} }  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\bar\sigma _k \bar\sigma _{n-k} } .
\end{equation}
\end{corollary}

\begin{example}
Using, in~\eqref{s12ccud}, the $\bar s_k$ and $\bar\sigma_k$ given in~\eqref{munb79m}, we have
\begin{equation}
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\binom{{x}}{k}\binom{{x}}{{n - k}}}  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\binom{{x + k}}{k}\binom{{x + n - k}}{{n - k}}} ;
\end{equation}
which holds for every non-negative integer $n$ and every complex number $x$.
\end{example}

\begin{example}
From~\cite[Equation (9.62)]{boyadzhiev16}:
\begin{equation}
\sum_{k = 0}^n {\binom{{n}}{k}\binom{{m}}{k}H_k }  = \binom{{n + m}}{m}\left( {H_m  + H_n  - H_{m + n} } \right)\label{eq.mwv0ueq},
\end{equation}

we identify the following binomial-transform pair of the second kind:
\begin{equation}\label{fkgvrgi}
\bar s_k  = \binom{{m}}{k}H_k ,\quad\bar \sigma _k  = \binom{{k + m}}{m}\left( {H_m  + H_k  - H_{k + m} } \right),
\end{equation}
which when used in~\eqref{s12ccud} gives
\begin{align}
&\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\binom{{m}}{k}\binom{{m}}{{n - k}}H_k H_{n - k} }\nonumber\\
&\qquad  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\binom{{k + m}}{m}\binom{{n - k + m}}{m}\left( {H_m  + H_k  - H_{k + m} } \right)\left( {H_m  + H_{n - k}  - H_{n - k + m} } \right)} ,
\end{align}
which is valid for every non-negative integer $n$ and every complex number $m$ that is not a negative integer.
\end{example}
\begin{theorem}\label{thm.njtayqa}
Let $n$ be a non-negative integer. If $\{(\bar s_k), (\bar\sigma_k)\}$ and $\{(\bar t_k), (\bar\tau_k)\}$, $k=0,1,2,\ldots$, are binomial-transform pairs of the second kind, then
\begin{equation}\label{o5suprg}
\sum_{k = 0}^n {\binom{{n}}{k}\bar s_k \bar\tau_{n-k} }  = \sum_{k = 0}^n {\binom{{n}}{k}\bar\sigma _k \bar t _{n-k} } .
\end{equation}
\end{theorem}

\begin{proof}
Consider the following variation on~\eqref{eq.ch50dhg}:
\begin{equation}\label{eq.te268n7}
\sum_{k = 0}^n {\binom{{n}}{k}y^{n - k} \left( {1 + x} \right)^k }  = \sum_{k = 0}^n {\binom{{n}}{k}\left( {1 + y} \right)^{n - k} x^k } ,
\end{equation}
and proceed as in the proof of Theorem~\ref{thm.slg7tm1}.
\end{proof}

\begin{example}
Using the binomial-transform pairs of the second kind
\begin{equation*}
\bar s_k  = \binom{{m}}{k}H_k ,\quad\bar \sigma _k  = \binom{{k + m}}{m}\left( {H_m  + H_k  - H_{k + m} } \right), \text{ Equation~\eqref{fkgvrgi}},
\end{equation*}
and
\begin{equation*}
\bar t_k  = \binom{{x}}{k},\quad\bar \tau_k  = \binom{{x + k}}{k},\text{ Equation~\eqref{munb79m} relabelled},
\end{equation*}
in~\eqref{o5suprg} yields
\begin{equation}\label{zrnqrxn}
\sum_{k = 0}^n {\binom{{n}}{k}\binom{{m}}{k}\binom{{x + n - k}}{{n - k}}H_k }  = \sum_{k = 0}^n {\binom{{n}}{k}\binom{{x}}{{n - k}}\binom{{k + m}}{m}\left( {H_m  + H_k  - H_{k + m} } \right)} .
\end{equation}
\end{example}
By considering the binomial-transform pair of the second kind $\{(1),(2^k)\}$, $k=0,1,2,\ldots$, we obtain a corollary to Theorem~\ref{thm.njtayqa}.
\begin{corollary}
Let $n$ be a non-negative integer. If $\{(\bar s_k), (\bar\sigma_k)\}$ is a binomial-transform pair of the second kind, then
\begin{equation}\label{pop9ybt}
\sum_{k = 0}^n {\binom{{n}}{k}\bar \sigma _k }  = \sum_{k = 0}^n {\binom{{n}}{k}2^{n - k} \bar s_k } .
\end{equation}
\end{corollary}

\begin{remark}
Identity~\eqref{pop9ybt} corresponds to Example 4 of Boyadzhiev~\cite{boyadzhiev16}.
\end{remark}

\begin{example}
With~\cite[Equation (10.10a)]{boyadzhiev16} 
\begin{equation*}
\sum_{k = 0}^n {\binom{{n}}{k}\binom{{x}}{{k + z}}}  = \binom{{n + x}}{{n + z}},
\end{equation*}
in mind, choosing
\begin{equation}
\bar s_k  = \binom{{x}}{{k + z}},\quad\bar \sigma _k  = \binom{{k + x}}{{k + z}},
\end{equation}
in~\eqref{pop9ybt} yields
\begin{equation}
\sum_{k = 0}^n {\binom{{n}}{k}\binom{{k + x}}{{k + z}}}  = \sum_{k = 0}^n {\binom{{n}}{k}\binom{{x}}{{k + z}}2^{n - k} } .
\end{equation}
for $n$ a non-negative integer and $x$ and $z$ complex numbers.
\end{example}

\section{Identities involving mixed binomial transform pairs}

\begin{theorem}
Let $n$ be a non-negative integer. If $\{(s_k), (\sigma_k)\}$ is a binomial transform pair of the first kind and $\{(\bar t_k), (\bar\tau_k)\}$, $k=0,1,2,\ldots$, is a binomial-transform pair of the second kind, then
\begin{equation}\label{x1h685v}
\sum_{k = 0}^n {\binom{{n}}{k}s_k \bar t_{n-k} }  = \sum_{k = 0}^n {(-1)^k\binom{{n}}{k} \sigma_k \bar \tau _{n-k} } .
\end{equation}
\end{theorem}

\begin{proof}
Let $M_x(x^k)=\bar t_k$ and $\mathcal L_y(y^k)=s_k$.

Act on the identity
\begin{equation*}
\sum_{k = 0}^n {\binom{{n}}{k}y^{n - k} x^k }  = \sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k}\left( {1 - y} \right)^{n - k} \left( {1 + x} \right)^k } ,
\end{equation*}
with $\mathcal M_x$ and $\mathcal L_y$, in succession.
\end{proof}

\begin{example}
Use of the binomial-transform pair of the first kind $\{(F_k),(-F_k)\}$, and the binomial-transform pair of the second kind $\{(B_k),((-1)^kB_k)\}$, $k=0,1,2,\ldots$, in~\eqref{x1h685v} gives 
\begin{equation}
\sum_{k = 0}^n {\binom{{n}}{k}F_k B_{n - k} }  = 0,
\end{equation}
for $n$ an even integer.

Similarly $\{(L_k),(-L_k)\}$ and $\{(B_k),((-1)^kB_k)\}$, $k=0,1,2,\ldots$, in~\eqref{x1h685v} yields
\begin{equation}
\sum_{k = 0}^n {\binom{{n}}{k}L_k B_{n - k} }  = 0,
\end{equation}
for $n$ an odd integer.

\end{example}

\begin{example}
Use of the following binomial-transform pair (see Example~\ref{ex.omtqrl4}):
\begin{equation*}
s_k  = H_{k + m} ,\quad\sigma _k  =  \frac{{\delta _{k0}(1+H_m)-1 }}{{k + \delta _{k0} }}\binom{{k + m}}{m}^{ - 1},  
\end{equation*}
in~\eqref{x1h685v} leads to the following identity
\begin{equation}\label{jy2d3um}
\sum_{k = 0}^n {\binom{{n}}{k}H_{k + m} \bar t_{n - k} }  = H_m \bar \tau _n  - \sum_{k = 1}^n {( - 1)^k \binom{{n}}{k}\binom{{k + m}}{m}^{ - 1}\frac1k\, \bar \tau _{n - k} } ,
\end{equation}
which is valid for every binomial-transform pair of the second kind $\{(\bar t_k),(\bar\tau_k)\}$, $k=0,1,2,\ldots$ and every complex number $m$ that is not a negative integer.

In particular, the following polynomial identity holds:
\begin{equation*}
\sum_{k = 0}^n {\binom{{n}}{k}H_{k + m} t^{n - k} }  = (1+t)^n H_m  - \sum_{k = 1}^n {( - 1)^k \binom{{n}}{k}\binom{{k + m}}{m}^{ - 1}\frac{(1+t)^{n - k}}k },
\end{equation*}
and can be recast as stated in proposition~\ref{prop.ai6n4y9} by writing $1/t$ for $t$.
\end{example}

\begin{proposition}\label{prop.ai6n4y9}
If $n$ is a non-negative integer, $m$ is a complex number that is not a negative integer and $t$ is a complex variable, then
\begin{equation}\label{t7tu7xu}
\sum_{k = 0}^n {\binom{{n}}{k}H_{k + m} t^k }  = \left( {1 + t} \right)^n H_m  + \sum_{k = 1}^n {( - 1)^{k - 1} \binom{{n}}{k}\binom{{k + m}}{m}^{ - 1} \frac{1}{k}\,t^k \left( {1 + t} \right)^{n - k} } .
\end{equation}
\end{proposition}
In particular, evaluation at $m=0$ and $m=-1/2$, respectively, gives
\begin{equation}
\sum_{k = 0}^n {\binom{{n}}{k}H_k t^k }  =\sum_{k = 1}^n {( - 1)^{k - 1} \binom{{n}}{k}\frac{1}{k}\,t^k \left( {1 + t} \right)^{n - k} } 
\end{equation}
and
\begin{equation}\label{mdlphw5}
\sum_{k = 0}^n {\binom{{n}}{k}O_k t^k }  =\sum_{k = 1}^n {( - 1)^{k - 1} \binom{{n}}{k}2^{2k-1}\binom{2k}k^{-1}\frac{1}{k}\,t^k \left( {1 + t} \right)^{n - k} } ,
\end{equation}
with the special values
\begin{equation}
\sum_{k = 0}^n {\binom{{n}}{k}H_k }  = \sum_{k = 1}^n {( - 1)^{k - 1} 2^{n - k} \binom{{n}}{k}\frac{1}{k}} 
\end{equation}
and
\begin{equation}
\sum_{k = 0}^n {\binom{{n}}{k}O_k }  = \sum_{k = 1}^n {( - 1)^{k - 1} 2^{n + k - 1} \binom{{n}}{k}\binom{2k}k^{-1}\frac{1}{k}}. 
\end{equation}
In deriving~\eqref{mdlphw5}, we used
\begin{equation*}
H_{k-1/2}=2O_k-2\log 2
\end{equation*}
and
\begin{equation*}
\binom{{k - 1/2}}{k} = 2^{ - 2k} \binom{{2k}}{k}.
\end{equation*}
\begin{corollary}
Let $n$ be a non-negative integer. If $\{(s_k), (\sigma_k)\}$ is a binomial transform pair of the first kind and $\{(\bar t_k), (\bar\tau_k)\}$, $k=0,1,2,\ldots$, is a binomial-transform pair of the second kind, then
\begin{equation}
\sum_{k = 0}^n {\binom{{n}}{k}\sigma_k \bar t_{n-k} }  = \sum_{k = 0}^n {(-1)^k\binom{{n}}{k} s_k \bar \tau _{n-k} } .
\end{equation}
\end{corollary}

\section{Polynomial identities involving a binomial transform pair}

We have already encountered the identities stated in the next theorem; they are variations on~\eqref{eq.renl1hy} and~\eqref{eq.cr8jcr4}.

\begin{theorem}\label{thm.xzlyuwd}
If $n$ is a non-negative integer and $y$ is a complex variable, then
\begin{align}
\sum_{k = 0}^n { \binom{{n}}{k}s_{n - k}y^k  }  = \sum_{k = 0}^n {( - 1)^{n-k} \binom{{n}}{k}\sigma _{n - k}\left( {1 + y} \right)^k }\label{eq.t182qp7},\\
\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\bar s_{n - k}y^k  }  = \sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\bar\sigma _{n - k}\left( {1 + y} \right)^k } \label{eq.l6e3qzc}.
\end{align}
\end{theorem}




The implication of Theorem~\ref{thm.xzlyuwd} is that every binomial-transform pair has associated with it a polynomial identity.

\begin{remark}
Identity~\eqref{eq.l6e3qzc} is equivalent to Boyadzhiev~\cite[Corollary 1]{boyadzhiev16}.
\end{remark}

\section{Binomial transform identities associated with polynomial identities of a certain type}
Polynomial identities of the following form abound in the literature:
\begin{equation}\label{poly}
\sum_{k = 0}^n {f(k)t^{p(k)} }  = \sum_{k = 0}^m {g(k)\left( {1 - t} \right)^{q(k)} } ;
\end{equation}
where $m$ and $n$ are non-negative integers, $t$ is a complex variable, $p(k)$ and $q(k)$ are sequences of integers, and $f(k)$ and $g(k)$ are sequences of complex numbers.

The binomial identities stated in Theorems~\ref{thm.qs3j4nk} and~\ref{thm.ru7y30f} are readily derived using the operators $\mathcal L_y$ and $\mathcal M_y$.
\begin{theorem}\label{thm.qs3j4nk}
Let a polynomial identity have the form stated in~\eqref{poly}. If $\{(s_k), (\sigma_k)\}$ is a binomial-transform pair of the first kind, then
\begin{equation}
\sum_{k = 0}^n {f(k)s_{p(k)} }  = \sum_{k = 0}^m {g(k)\sigma _{q(k)} } .
\end{equation}


\end{theorem}

\begin{theorem}\label{thm.ru7y30f}
Let a polynomial identity have the form stated in~\eqref{poly}. If $\{(\bar s_k), (\bar\sigma_k)\}$ is a binomial-transform pair of the second kind, then
\begin{equation}
\sum_{k = 0}^n {( - 1)^{p(k)} f(k)\bar s_{p(k)} }  = \sum_{k = 0}^m {g(k)\bar \sigma _{q(k)} } .
\end{equation}


\end{theorem}

\begin{lemma}{Sun~\cite[Lemma 3.1]{sun03}}
If $m$, $n$ and $r$ are non-negative integers and $t$ is a complex variable, then
\begin{equation}\label{lpj4ylb}
\sum_{k = 0}^n {( - 1)^{k - r} \binom{{n}}{k}\binom{{k + m}}{r}t^{k + m - r} }  = \sum_{k = 0}^m {(-1)^k\binom{{m}}{k}\binom{{k + n}}{r}\left( {1 - t} \right)^{n + k - r} } .
\end{equation}
\end{lemma}

\begin{example}
In~\eqref{lpj4ylb} we can identify
\begin{equation}
f(k) = ( - 1)^{k - r} \binom{{n}}{k}\binom{{k + m}}{r},\quad g(k) = \binom{{m}}{k}\binom{{k + n}}{r},
\end{equation}
and 
\begin{equation}
p(k) = k + m - r \mbox{ and } q(k) = n + k - r.
\end{equation}
Using these in Theorem~\ref{thm.qs3j4nk} gives
\begin{equation}
\sum_{k = 0}^n {( - 1)^{k - r} \binom{{n}}{k}\binom{{k + m}}{r}s_{k + m - r} }  = \sum_{k = 0}^m {(-1)^k\binom{{m}}{k}\binom{{k + n}}{r}\sigma_{n + k - r} }.
\end{equation}
for every binomial-transform pair $\{(s_k),(\sigma_k)\}$ of the first kind.
\end{example}


\section{Conversion between binomial transform identities}
If a binomial transform identity involves a binomial-transform pair of the first kind, it is straightforward to convert it to an identity involving a binomial-transform pair of the second kind; and vice versa. An identity involving $\{ s(k),\sigma(k)\}$, $k=0,1,2,\dots$, can be converted to that involving $\{ \bar s(k),\bar\sigma(k)\}$ by choosing $s(k)=x^k$ and $\sigma(k)=(1-x)^k$, replacing $x$ with $-x$ and then operating on the resulting identity with $\mathcal M_x$. Similarly, an identity involving $\{ \bar s(k),\bar\sigma(k)\}$ can be converted to that involving $\{ s(k),\sigma(k)\}$ by choosing $\bar s(k)=x^k$ and $\bar\sigma(k)=(1+x)^k$, replacing $x$ with $-x$ and then operating on the resulting identity with $\mathcal L_x$.

\begin{example}
Let $\{(\bar t_k),(\bar\tau_k)\}$, $k=0,1,2,\ldots$,  be a binomial-transform pair of the second kind. Chen's main result~\cite[Theorem 3.1]{chen07} (after  Gould and Quaintance's simplification~\cite[Equation (10)]{gould14}) for non-negative integers $m$, $n$ and $s$ is
\begin{align}\label{eq.ollq3g3}
&\sum_{k = 0}^m {\binom{{m}}{k}\binom{{n + k + s}}{s}^{ - 1} \bar t_{n + k + s} }\nonumber\\
&\qquad= \sum_{k = 0}^n {( - 1)^{n - k} \binom{{n}}{k}\binom{{m + k + s}}{s}^{ - 1} \bar \tau _{m + k + s} }\nonumber\\
&\qquad\qquad  + \sum_{k = 0}^{s - 1} {\frac{{( - 1)^{n + s - k} s}}{{m + n + s - k}}\binom{{s - 1}}{k}\binom{{m + n + s - k - 1}}{n}^{ - 1} \bar \tau _k } .
\end{align}
In order to convert~\eqref{eq.ollq3g3} to an identity for the binomial-transform pair of the first kind, $\{(t_k),(\tau_k)\}$, $k=0,1,2,\ldots$, we choose $\bar t_k=x^k$ and $\bar\tau_k=(1+x)^k$ and replace $x$ with $-x$ to obtain
\begin{align*}
&\sum_{k = 0}^m {(-1)^k\binom{{m}}{k}\binom{{n + k + s}}{s}^{ - 1} x^{n + k + s} }\nonumber\\
&\qquad= (-1)^s\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\binom{{m + k + s}}{s}^{ - 1} (1 - x)^{m + k + s} }\nonumber\\
&\qquad\qquad  + \sum_{k = 0}^{s - 1} {\frac{{( - 1)^k s}}{{m + n + s - k}}\binom{{s - 1}}{k}\binom{{m + n + s - k - 1}}{n}^{ - 1} (1 - x)^k } .
\end{align*}
Operating on the above equation with the linear operator $\mathcal L_x$ now gives
\begin{align}\label{eq.coax3mm}
&\sum_{k = 0}^m {(-1)^k\binom{{m}}{k}\binom{{n + k + s}}{s}^{ - 1} t_{n + k + s} }\nonumber\\
&\qquad= (-1)^s\sum_{k = 0}^n {( - 1)^k \binom{{n}}{k}\binom{{m + k + s}}{s}^{ - 1} \tau_{m + k + s} }\nonumber\\
&\qquad\qquad  + \sum_{k = 0}^{s - 1} {\frac{{( - 1)^k s}}{{m + n + s - k}}\binom{{s - 1}}{k}\binom{{m + n + s - k - 1}}{n}^{ - 1} \tau_k } .
\end{align}

\end{example}

\begin{example}
Another example, Chen~\cite[Theorem 3.2]{chen07} is
\begin{equation}
\sum_{k = 0}^m {\binom{{m}}{k}\binom{{n + k}}{s}\bar t_{n + k - s} }  = \sum_{k = 0}^n {( - 1)^{n - k}\binom{{n}}{k}\binom{{m + k}}{s} \bar \tau _{m + k - s} } ;
\end{equation}
whose corresponding version for a binomial-transform pair of the first kind is
\begin{equation}
\sum_{k = 0}^m {(-1)^{s-k}\binom{{m}}{k}\binom{{n + k}}{s} t_{n + k - s} }  = \sum_{k = 0}^n {( - 1)^k\binom{{n}}{k}\binom{{m + k}}{s} \tau _{m + k - s} } .
\end{equation}

\end{example}

\begin{example}
Gould and Quaintance~\cite[Theorem 3]{gould14} gave the following identity involving a binomial transform pair of the second kind:
\begin{align}
&\sum_{k = 0}^s {\binom{{s}}{k}\binom{{m + n + s - k}}{m}^{ - 1} \frac{{\bar t_k }}{{m + n + s + 1 - k}}}\nonumber \\
&\qquad = \sum_{k = 0}^s {\binom{{s}}{k}\binom{{m + n + s - k}}{n}^{ - 1} \frac{{( - 1)^{s - k}\bar \tau_k }}{{m + n + s + 1 - k}}} ,
\end{align}
which is valid for every non-negative integer $s$ and all complex numbers $m$ and $n$ excluding the set of negative integers. 

The corresponding result for a binomial-transform pair of the first kind is
\begin{align}
&\sum_{k = 0}^s {(-1)^k\binom{{s}}{k}\binom{{m + n + s - k}}{m}^{ - 1} \frac{{t_k }}{{m + n + s + 1 - k}}}\nonumber \\
&\qquad = \sum_{k = 0}^s {\binom{{s}}{k}\binom{{m + n + s - k}}{n}^{ - 1} \frac{{( - 1)^{s - k}\tau_k }}{{m + n + s + 1 - k}}} .
\end{align}
\end{example}

\begin{remark}\label{rem.r7dv221}
An identity involving a binomial-transform pair of the first kind $\{s_k,\sigma_k\}$, \mbox{$k=0,1,2,\ldots$}, can always be converted to a binomial-transform pair identity of the second kind $\{\bar s_k,\bar\sigma_k\}$ by doing 
\begin{equation*}
s_k\to(-1)^k\bar s_k,\quad\sigma_k\to\bar\sigma_k.
\end{equation*}
Similarly, conversion of a second kind transform pair identity to a first kind transform pair is achieved through
\begin{equation*}
\bar s_k\to(-1)^ks_k,\quad\bar\sigma_k\to\sigma_k.
\end{equation*}
\end{remark}

