\subsection*{B.3 Diffeomorphisms}

The normally distributed innovations $(\varepsilon_{1,t},\varepsilon_{2,t})$ can be written on polar coordinates such that: 
\begin{equation*}
	\begin{cases}
		\varepsilon_{1,t} = \rho \cos \theta,\\
		\varepsilon_{2,t} = \rho \sin \theta. \\ 
	\end{cases} \iff 	\begin{cases}
		\rho = \sqrt{\varepsilon_{1,t}^2+\varepsilon_{2,t}^2},\\
		\theta= \tan^{-1}(\varepsilon_{2,t}/\varepsilon_{1,t}). \\ 
	\end{cases}
	%	\begin{split}
		%		\varepsilon_{1,t} = \rho \cos \theta,\\
		%		\varepsilon_{2,t} = \rho \sin \theta. \\ 
		%	\end{split}
\end{equation*}
Then, the density of the standard normal distribution becomes $f(\rho,\theta)=\frac{1}{2\pi}\rho\exp(-\rho^2/2)$, on the domain $(0,\infty)\times(0,2\pi)$ (up to modulo $2\pi$ for $\theta$). Now, consider the transformation $(\rho,\theta) \rightarrow (\rho^*,\theta^*) = (\rho,\theta+a(\rho))$, where $a(\cdot)$ is a continuous differentiable function of $\rho$\footnote{Note that the Jacobian formula is  valid for functions that are diffeomorphisms almost everywhere. In our framework, the transformation is a piecewise diffeomorphism and has to be understood with $\theta + a(\rho)$, up to modulo $2\pi$.}. Then we have: 
\begin{equation*}
	\begin{cases}
		\varepsilon^*_{1,t} = \rho^* \cos \theta^*,\\
		\varepsilon^*_{2,t} = \rho^* \sin \theta^*. \\ 
	\end{cases} \iff 	\begin{cases}
		\rho^* = \sqrt{\varepsilon_{1,t}^2+\varepsilon_{2,t}^2},\\
		\theta^*= \tan^{-1}(\varepsilon_{2,t}/\varepsilon_{1,t})+a\left(\sqrt{\varepsilon_{1,t}^2+\varepsilon_{2,t}^2}\right). \\ 
	\end{cases}
	%	\begin{split}
		%		\varepsilon_{1,t} = \rho \cos \theta,\\
		%		\varepsilon_{2,t} = \rho \sin \theta. \\ 
		%	\end{split}
\end{equation*}
Thus, we get for $(u^*_{1,t},u^*_{2,t})=(\Phi(u_{1,t}),\Phi(u_{2,t}))$:
\begin{equation}
	\begin{cases}
u^*_{1,t} = \Phi \left[\sqrt{\Phi^{-1}(u_{1,t})^2+\Phi^{-1}(u_{2,t})^2} \cos\left(\tan^{-1}(\Phi^{-1}(u_{2,t})/\Phi^{-1}(u_{1,t}))+a\left(\sqrt{\Phi^{-1}(u_{1,t})^2+\Phi^{-1}(u_{2,t})^2}\right)\right)\right] ,\\
u^*_{2,t} = \Phi \left[\sqrt{\Phi^{-1}(u_{1,t})^2+\Phi^{-1}(u_{2,t})^2} \sin\left(\tan^{-1}(\Phi^{-1}(u_{2,t})/\Phi^{-1}(u_{1,t}))+a\left(\sqrt{\Phi^{-1}(u_{1,t})^2+\Phi^{-1}(u_{2,t})^2}\right)\right)\right] . \\ 
\end{cases}
\end{equation}




