\paragraph{Outline.} 
In Section \ref{sec:results} we describe our model, state the main result of the paper and discuss it. Section \ref{sec:proofs} contains proofs and technical material, while in the appendix we collect known results on which our proofs hinge and some auxiliary computations.


\section{Model description and main results}\label{sec:results}

We consider a market where $N$ agents are placing  orders for a given asset. The counting processes $N^+_i$ and $N^-_i$, for $i=1,\dots, N$, are Hawkes processes and represent variations (upward and downward, respectively) in the price due to orders (buy and sell, respectively) placed by agent $i$. 
We refer the reader to \cite{Gatheral01082010,Huberman,durin.et.al} and the references therein for more information on impact of buy and sell orders on price.
The contribution of agent $i$ to the asset log-price is therefore the sum of its positive and negative price variations
\be{def:singlep}
P_i = N^+_i - N^-_i.
\ee
We also interpret this model as a decomposition over individual agents of the model in \cite{el2018microstructural,Bacry01012013}. See next Remark \ref{rm:agg.model}) for an alternative interpretation in the case of market indices or portfolios.

We consider in this paper the function $\varphi(t) = e^{-\a t}$, ruling the memory of the  process. Note that more general choices of $\varphi:[0,+\infty) \ra [0,+\infty)$ have been considered, see for example \cite{el2018microstructural}; however, our analysis relies on this choice. Let us introduce two sequences $\nu_N^{\pm}$ of $\s$-finite measures on $[0,+\infty)$,  and define
\begin{equation}\label{def:X}
X^{\pm}_i(t) := \int_{[0,t]} \varphi(t-s) \left[dN^{\pm}_i(s) + \nu_N^{\pm}(ds)\right].
\end{equation}
We then consider the empirical means
\[
m_N^{\pm}(t) := \frac{1}{N} \sum_{i=1}^N X^{\pm}_i(t).
\]
We will assume that the point processes $(N^{\pm}_i)_{i=1}^N$ are conditionally independent given $(X^{\pm}_i)_{i=1}^N$. Each ``upward'' jump process $N^+_i$ has a stochastic intensity given by
\begin{equation}\label{def:lambda}
\l_N^+(t) := f(m_N^+(t) + \b \g m_N^-(t)),
\end{equation}
while the``downward" jumps have stochastic intensity
\begin{equation}\label{def:lambdameno}
\l_N^-(t) := f( \g m_N^+(t) + (1+(\b-1) \g) m_N^-(t)),
\end{equation}
where 
$f$ is a given increasing, concave function of class $\mathcal{C}^3$, with $f(0) = 0$, $f'(0)>0$, $f''(0)<0$ with $f'$, $f''$ and $f'''$ bounded,  and $\b \geq 1,  \, \g\in [0,1]$ are parameters ruling the self and cross excitation of upward and downward jumps (see Remarks \ref{rm.jump.parameters} and \ref{rm.f}).

The processes $(N^\pm_i)_{i=1}^n$  are called Hawkes processes. Note that the intensity is an increasing function of the mean $m_{N}^{\pm}$ and is the same for each agent, which should reflect contagion and homogeneity of the model. The \emph{mean-field} interaction models the fact that buy orders, with consequent increase in the log-price (and viceversa, sell orders with  consequent decrease in the log-price) are exciting orders of the same type in other labeled agents.
Moreover, the processes $X_i^{\pm}$ that are responsible for the self-excitation of the $N_i^{\pm}$, are also driven by a common, external signal modeled by the measure $\nu_N^{\pm}$, representing a ``baseline'' volatility. In what follows we will assume that
\[
\nu_N^{\pm}(dt) = a^{\pm}_N \delta_0(dt) + b_N^{\pm} dt,
\]
where $a_N, b_N$ are positive constants satisfying
\be{assab}
\lim_{N \ra +\infty} \sqrt{N} a_N^{\pm} = a^{\pm} \in (0,+\infty), \ \ \ \lim_{N \ra +\infty} \sqrt{N} b_N^{\pm} = b^{\pm} \in (0,+\infty).
\ee
Note that $a_N$ is responsible for the value at time $t=0$ of the stochastic intensities $\l_N^{\pm}$, while $b_N$ represents a stationary external signal. More irregular choices for $\nu_N$ are also possible.

We now introduce the rescaled log-price process
\be{def:pn}
\Pi_N(t)  = \frac{1}{\sqrt{N}} \sum_{i=1}^N P_i(\sqrt{N}t). 
\ee
Our main result is the following (see next Theorem \ref{th:price} for a more detailed version of the theorem).

\begin{theorem} \label{th:main}
Suppose the criticality condition 
\be{intro:critical}
\a = f'(0)(1+\b\g)
\ee
holds.
The process $\Pi_N$ converges in  distribution in $(0,T]$ to the process $\pi$, where $(\pi,y)$ solves the SDE
\begin{equation} \label{volmod}
\begin{split}
d\pi(t) & =\beta_{\pi} dt + \sigma_{\pi} \sqrt{f'(0) y(t)} dW(t) \\
dy(t)  & = (\beta_{y}  + \alpha_{y} f''(0) y^2(t) )dt + \sigma_{y} \sqrt{f'(0)y(t)} dB(t)
\end{split}
\end{equation}
with initial condition
\[
\pi(0)  = \frac{1-\g}{\g(1+\b)}(a^+ - a^-),\quad 
y(0)  = \left(\frac{2}{1+\b}+\frac{2\b}{1+\b}\g\right) a^+ + \left(\frac{2\b}{1+\b}(1-\g) + 2\b\g\right) a^-,
\]
where the constants in the dynamics depend on $\beta,\gamma,b^{\pm}$ as below
\[
\begin{split}
\beta_{\pi}&= \frac{1-\g}{\g(1+\b)}(b^+ - b^-);\quad
\sigma_{\pi}=\sqrt{2} \frac{1+\b\g}{\g(1+\b)} ;\\
\beta_{y}&=\left(\frac{2}{1+\b}+\frac{2\b}{1+\b}\g\right) b^+
+ \left(\frac{2\b}{1+\b}(1-\g) + 2\b\g\right) b^- ;\quad
\alpha_{y}= \frac12 (1+\b\g);\quad
\sigma_{y}= \frac{\sqrt{(1+\b^2)}(1+\b\g)}{1+\b}
\end{split}\]
and $W,B$ are standard Brownian motions, with correlation
\be{intro:limcorr}
d\langle B,W \rangle_t =  \frac{(1+\b)\g}{1+\b\g}\frac{(1-\b)}{\sqrt{2(1+\b^2)}} dt. 
\ee
\label{th:initial}
\end{theorem}

\begin{remark}\label{rm.jump.parameters}
Note that \eqref{def:lambda} and \eqref{def:lambdameno} express the jump intensity as a concave function of a functional of past jumps. For instance, referring to \eqref{def:lambda}, the term $m^+_N(t)$ can be interpreted as the impact of past jump upwards on $\lambda^+_N$, and $\beta \gamma m_N^-(t)$ as the impact of past jump downwards on $\lambda^+_N$. The condition $\gamma \leq 1$ corresponds to the requirement ``past jump upwards (resp. downwards) impact more on $\lambda^+_N$ than on $\lambda^-_N$ (resp. more on $\lambda^-_N$ than on $\lambda^+_N$)'', which we need to encode herd behavior in our model. Indeed,
\[
m_N^+ \geq \g m_N^+  \mbox{ and } (1+(\b-1)\g)m_N^- \geq \b \g m_N^-,
\]
with equality for $\g = 1$. The condition $\b \geq 1$ is related to the higher impact of the jump downwards, in the following sense:
``the impact of jump downwards on $\l_N^+$ (resp. $\l_N^-$)
is greater than the impact of jump upwards on 
$\l_N^-$ (resp. $\l_N^+$). 
Indeed the coefficient $\b\g$ of $m_N^-(t)$ in \eqref{def:lambda} is greater than the coefficient $\g$ of $m_N^+(t)$ in \eqref{def:lambdameno}, and the coefficient $(1+(\b-1)\g)$ of $m_N^-$ in \eqref{def:lambdameno} is greater than the coefficient $1$ of $m_N^+$ in \eqref{def:lambda}, with equality for $\b=1$. 
This condition seems natural in a financial context due to the higher ``excitatory power'' of downard price movements, i.e., the fact that investors react more to a decrease than to an increase in the price; cf. also the explanation in \cite{el2018microstructural}. This  corresponds to $\beta\geq 1$, and gives rise to leverage effect in the limit system in the sense of Remark \ref{rm.leverage}.
Note also that the requirements on the impact of jump upwards and downwards lead naturally to introduce at least two parameters in the model, possibly with a different combination from the one we have chosen.
\end{remark}

\begin{remark}\label{rm.f}
In our setting, equations \eqref{def:lambda} and \eqref{def:lambdameno} encompass the fact that the effect on present jumps intensity of compounded past jumps averaged over all the agents is not linear, but mediated by the increasing concave function $f$,  meaning that a saturation effect is at play, with larger past jumps producing a stronger intensity of present jumps, with a decreasing marginal dependence. Note that the $y$ process in \eqref{volmod} is mean reverting, since $f''(0)<0$.
\end{remark}



\begin{remark}[Leverage effect]\label{rm.leverage}
Since $\gamma\in[0,1]$ and $\beta\geq 1$, it always holds that ${(1+\b)\g}/{(1+\b\g)}\in [0,1]$ and $\langle B,W \rangle\in(-1/\sqrt{2},0]$. When $\b\to\infty$, we have $\langle B,W \rangle\to -1/\sqrt{2}$. Recall that in \cite{el2018microstructural}, the correlation in the limit model is ${(1-\b)}/{\sqrt{2(1+\b^2)}}$, which we obtain here with $\gamma=1$. The fact that  $\langle B,W \rangle\leq 0$ means that this model displays a negative relationship between changes in stock returns and in volatility, the so called leverage effect.
This is a reflection of the fact that $\beta\geq 1$, representing, as seen in Remark \ref{rm.jump.parameters}, the fact that  jumps downwards are overall more excitatory than jumps upwards.
\end{remark}

\begin{remark}\label{rm:agg.model}
[Index and portfolio dynamics]
A different possible interpretation of the aggregated price in \eqref{def:pn} and its limit  $(\pi_{t})_{t}$, is that of an index or portfolio composed of $i=1,\dots, N$ assets. The variations of the index are given by an average of the variations of the single components of the index, each represented by the sum of its positive and negative ``micro'' variations. The single assets have dynamics as in \cite{el2018microstructural,Bacry01012013}, they are self exciting and are exciting each other, with jumps in one price exciting jumps in all the others through a mean-field interaction. The diffusive dynamics is seen at a slower time scale than the order book time scale where we see the jumps in the prices.
\end{remark}


\begin{remark}[Multifractality - Multiscaling of moments]
Let $(X_t)_{t \geq 0}$ be a continuous-time martingale, having stationary increments; in financial applications this could be identified with the de-trended {\em log-price} of an asset, or the log-price with respect to the martingale measure used for pricing derivatives. We say that multiscaling of moments occurs if $\E\left(|X_{t+h} - X_t|^q \right)$ scales, in the limit as  $h \downarrow 0$, as $h^{A(q)}$, with $A(q) = \frac{q}{2}$ for small $q$ but $A(q) < \frac{q}{2}$ beyond a certain threshold.  The presence of multiscaling in financial time series is well established and various models have been proposed to capture it, most notably multi-fractal processes \cite{calvet.fisher}, see also \cite{wu.muzy.bacry,NR18,acdp}. In \cite{daipra.pigato} we have shown that in a stochastic volatility model whose volatility $V_t$ solves the stochastic differential equation
\be{sde}
dV_t \, = \, - f(V_t) dt + dL_t,
\ee
with $L$ a {\em Levy process},  multiscaling occurs if and only if the characteristic measure of $L$ has power law tails at infinity, and $f$ is a {\em superlinear} mean reversion function, a fact that is supported e.g. by the empirical findings in \cite{BAKSHI}.  Therefore, the result in Theorem \ref{th:initial} is a possible explanation of the origin of the superlinear mean reversion, while jumps may be produced by exogenous shocks.
\label{rm:multiscaling}
\end{remark}




\section{Proofs}\label{sec:proofs}
The proof of Theorem \ref{th:main} is divided in  two steps. We first identify a {\em microscopic } volatility process $Y_N(t)$, and we show it converges in distribution to a solution of the second equation in \eqref{volmod}. We use martingale methods for this convergence; the main difficulty is to show that certain terms in the dynamics of $Y_N$ vanish as $N \rightarrow +\infty$, which is essential to obtain a closed equation for the limit of $Y_N$. As it is customary in critical dynamics, there is one divergent term (as $N \rightarrow +\infty$) in the dynamics of $Y_N$, which however vanishes if the criticality condition \eqref{intro:critical} holds. In the second step we prove the convergence of the price process. This turns out to be more difficult, as the divergent term in the price dynamics does not disappear at criticality. This type of problem appears in perturbation theory of operators (see \cite{da83} for an application to a mean field model). Here we circumvent the problem by applying a theorem on {\em collapsing processes} due to Comets \& Eisele \cite{CE88}, which may be seen as the probabilistic counterpart of a perturbation theory argument.
Theorem \ref{thm:diffusion:approx}, Theorem \ref{collapsing}, Lemma \ref{lemma:collapsing} and Theorem \ref{thm:eq.quad}, which we use along the proof, are given in the appendix.

\subsection{Preliminaries}

Using our specific choice $\varphi(t)=e^{-\alpha t}$ , by Fubini's Theorem and the fact that $\phi(t) = -\frac{1}{\a} \frac{d}{dt} \phi(t)$:
\[
\begin{split}
\int_0^t X^{\pm}_i(s) ds & =  \int_0^t \int_{[0,s]} \varphi(s-r)\left[ dN^{\pm}_i(r) +\nu_N^{\pm}(dr)\right]ds = \int_{[0,t]} \left(\int_r^t \varphi(s-r) ds \right) \left[ dN^{\pm}_i(r) + \nu_N^{\pm}(dr)\right] \\
& =  \int_{[0,t]}\frac{1}{\a} \left(1-\varphi(t-r)\right) \left[ dN^{\pm}_i(r) + \nu_N^{\pm}(dr)\right]  = \frac{1}{\a}N^{\pm}_i(t) + \frac{1}{\a} \nu_N^{\pm}([0,t]) - \frac{1}{\a} X^{\pm}_i(t),
\end{split}
\]
and therefore
\begin{equation} \label{Markov}
X^{\pm}_i(t) =  - \a \int_0^t X^{\pm}_i(s) ds  + N^{\pm}_i(t) + \nu_N^{\pm}([0,t]).
\end{equation}
Note that this computation relies on our specific functional choice for $\phi$, and not only on the memory.

We now give a representation of the processes $X^{\pm}_i(t)$ in terms of a family $n_i^+(ds,du)$, $n_i^-(ds,du)$ of independent Poisson Random Measures on $[0,+\infty)^2$ with intensity measure $ds \, du$. We can write
\begin{equation} \label{micsde}
X^{\pm}_i(t) = - \a \int_0^t X^{\pm}_i(s) ds + \int_{[0,t]\times [0,+\infty)} {\bf 1}_{[0,\l_N^{\pm}(s^-))}(u) n_i^{\pm}(ds,du)+ a^{\pm}_N + b^{\pm}_N t,
\end{equation}
which can be aggregated to
\begin{equation} \label{macsde}
m_N^{\pm}(t) = - \a \int_0^t m_N^{\pm}(s) ds + \int_{[0,t]\times [0,+\infty)} {\bf 1}_{[0,\l_N^{\pm}(s^-))}(u) \frac{1}{N} \sum_{i=1}^N n_i^{\pm}(ds,du)+ a^{\pm}_N + b^{\pm}_N t.
\end{equation}
Using then the compensated Poisson Random Measures $\tilde{n}_i^{\pm}(ds,du) = n_i^{\pm}(ds,du) - ds \, du$ we obtain the semimartingale representation
\begin{equation} \label{macsdesemim}
m_N^{\pm}(t) = - \a \int_0^t m_N^{\pm}(s) ds  + \int_0^t \l_N^{\pm}(s)ds + a^{\pm}_N + b^{\pm}_N t+ \int_{[0,t]\times [0,+\infty)} {\bf 1}_{[0,\l_N^{\pm}(s^-))}(u) \frac{1}{N} \sum_{i=1}^N \tilde{n}_i^{\pm}(ds,du).
\end{equation}
Note that
\[
M_N^{\pm}(t) := \int_{[0,t]\times [0,+\infty)} {\bf 1}_{[0,\l^{\pm}(s^-))}(u) \frac{1}{N} \sum_{i=1}^N \tilde{n}_i^{\pm}(ds,du)
\]
are orthogonal martingales with quadratic variations $\frac{1}{N} \int_0^t \l_N^{\pm}(s)ds$. 

\subsection{Definition and convergence of the volatility process}
We now define
\[
Y_N(t) 
 = \frac{\sqrt{N}}{2} \left[\left(\frac{2}{1+\b}+\frac{2\b}{1+\b}\g\right) m_N^+(\sqrt{N}t) + \left(\frac{2\b}{1+\b}(1-\g) + 2\b\g\right) m_N^-(\sqrt{N}t)\right]
\]
and
\[
Z_N(t) 
 = \frac{(1-\g)\sqrt{N}}{2} \left[  m_N^+(\sqrt{N}t) -  m_N^-(\sqrt{N}t)\right].
\]
Note that
\[
\l_N^{+}(t) = f \left( \frac{1}{\sqrt{N}}Y_N(t/\sqrt{N}) +  \frac{1}{\sqrt{N}} \frac{2\b}{1+\b}Z_N(t/\sqrt{N}) \right)
\]
and
\[
\l_N^{-}(t) = f \left( \frac{1}{\sqrt{N}}Y_N(t/\sqrt{N}) -  \frac{1}{\sqrt{N}} \frac{2}{1+\b}Z_N(t/\sqrt{N}) \right)
\]
Moreover, observing that $Y_N \geq 0$ and that the arguments of $f$ in the definition of $\l^{\pm}_N$ are nonnegative, we obtain the bound
\be{boundZ}
|Z_N(t)| \leq \frac{1+\b}{2} Y_N(t).
\ee
We are going to see that the process $Y_N$ has a nontrivial limit as $N \ra +\infty$, while $Z_N$ converges to zero in a suitable sense. We begin by studying $Z_N$. Using \eqref{macsde} we obtain
\be{eqZ_N}
\begin{split}
