where 
\[
\tilde{\l}_N^{+}(t) = f \left( \frac{1}{\sqrt{N}}\tY_N(t/\sqrt{N}) +  \frac{1}{\sqrt{N}} \frac{2\b}{1+\b}\tZ_N(t/\sqrt{N}) \right)
\]
and
\[
\tilde{\l}_N^{-}(t) = f \left( \frac{1}{\sqrt{N}}\tY_N(t/\sqrt{N}) -  \frac{1}{\sqrt{N}} \frac{2}{1+\b}\tZ_N(t/\sqrt{N}) \right)
\]
It follows that
\be{tZ2}
\begin{split}
\tZ_N^2(t) & = E_N^2 + 2 F_N \int_0^t \tZ_N(s)ds - 2 \a \sqrt{N} \int_0^t \tZ_N^2(s)ds \\ & + \int_{[0,\sqrt{N} t]} {\bf 1}_{[0,\tilde{\l}_N^+(s))}(u) \left[\left(\tZ_N\left(\frac{s^-}{\sqrt{N}}\right) + \frac{1-\g}{2 \sqrt{N}} \right)^2 - \tZ^2_N\left(\frac{s^-}{\sqrt{N}}\right) \right]\sum_{i=1}^N n_i^+(ds,du) \\ & + \int_{[0,\sqrt{N} t]} {\bf 1}_{[0,\tilde{\l}_N^-(s))}(u) \left[\left(\tZ_N\left(\frac{s^-}{\sqrt{N}}\right) - \frac{1-\g}{2 \sqrt{N}} \right)^2 - \tZ^2_N\left(\frac{s^-}{\sqrt{N}}\right) \right] \sum_{i=1}^N n_i^-(ds,du)
