Using then the compensated Poisson Random Measures $\tilde{n}_i^{\pm}(ds,du) = n_i^{\pm}(ds,du) - ds \, du$ as above we obtain
\be{tZ2mart}
\begin{split}
\tZ_N^2(t) & = E_N^2 + 2 F_N \int_0^t \tZ_N(s)ds - 2 \a \sqrt{N} \int_0^t \tZ_N^2(s)ds \\ & + N \int_0^{\sqrt{N}t}\left[\frac{(1-\g)^2}{4N} + \frac{1-\g}{ \sqrt{N}}\tZ_N\left(\frac{s}{\sqrt{N}}\right)\right]  f \left( \frac{1}{\sqrt{N}}\tY_N\left(\frac{s}{\sqrt{N}}\right) +  \frac{1}{\sqrt{N}}\frac{2\b}{1+\b}\tZ_N\left(\frac{s}{\sqrt{N}}\right) \right) ds \\ & + N \int_0^{\sqrt{N}t}\left[\frac{(1-\g)^2}{4N} - \frac{1-\g}{ \sqrt{N}}\tZ_N\left(\frac{s}{\sqrt{N}}\right)\right]  f \left( \frac{1}{\sqrt{N}}\tY_N\left(\frac{s}{\sqrt{N}}\right) -  \frac{1}{\sqrt{N}}\frac{2}{1+\b}\tZ_N\left(\frac{s}{\sqrt{N}}\right) \right) ds  \\ & + M_N^{\tZ^2}(t) \\ & = E_N^2 + 2 F_N \int_0^t \tZ_N(s)ds - 2 \a \sqrt{N} \int_0^t \tZ_N^2(s)ds \\ & + N^{3/2} \int_0^{t}\left[\frac{(1-\g)^2}{4N} + \frac{1-\g}{ \sqrt{N}}\tZ_N\left(s\right)\right]  f \left( \frac{1}{\sqrt{N}}\tY_N\left(s\right) +  \frac{1}{\sqrt{N}}\frac{2\b}{1+\b}\tZ_N\left(s\right) \right) ds \\ & + N^{3/2} \int_0^{t}\left[\frac{(1-\g)^2}{4N} - \frac{1-\g}{ \sqrt{N}}\tZ_N\left(s\right)\right]  f \left( \frac{1}{\sqrt{N}}\tY_N\left(s\right) -  \frac{1}{\sqrt{N}}\frac{2}{1+\b}\tZ_N\left(s\right) \right) ds  \\ & + M_N^{\tZ^2}(t),
\end{split}
\ee
where $M_N^{\tZ^2}$ is a mean zero martingale. Taking the expectation in \eqref{tZ2mart} we obtain
\be{tZ2der}
\begin{split}
\frac{d}{dt} \E\left[\tZ_N^2(t)\right] &  =  2 F_N \E\left[\tZ_N(t)\right] -2\a \sqrt{N} \E\left[\tZ_N^2(t)\right] \\ & + N^{3/2}\E\left[\left[\frac{(1-\g)^2}{4N} + \frac{1-\g}{ \sqrt{N}}\tZ_N\left(t\right)\right]  f \left( \frac{1}{\sqrt{N}}\tY_N\left(t\right) +  \frac{1}{\sqrt{N}}\frac{2\b}{1+\b}\tZ_N\left(s\right) \right)\right] \\ & + N^{3/2} \E\left[\left[\frac{(1-\g)^2}{4N} - \frac{1-\g}{ \sqrt{N}}\tZ_N\left(t\right)\right]  f \left( \frac{1}{\sqrt{N}}\tY_N\left(t\right) -  \frac{1}{\sqrt{N}}\frac{2}{1+\b}\tZ_N\left(t\right) \right) \right]
\end{split}
\ee
Using the fact that $f$ is concave for $x>0$ we have that $f(x) \leq f'(0)|x|$ for all $x \in \R$. So
\begin{multline*}
\frac{(1-\g)^2}{4N} \left[  f \left( \frac{1}{\sqrt{N}}\tY_N\left(t\right) +  \frac{1}{\sqrt{N}}\frac{2\b}{1+\b}\tZ_N\left(t\right) \right) +  f \left( \frac{1}{\sqrt{N}}\tY_N\left(t\right) -  \frac{1}{\sqrt{N}}\frac{2}{1+\b}\tZ_N\left(t\right) \right) \right]
 \\ \leq \frac{(1-\g)^2}{2N^{3/2}}f'(0)\left[ \tY_N(t) + 2 |\tZ_N(t)| \right].
 \end{multline*}
Moreover $f$ is Lipschitz with constant $f'(0)$, so
\begin{multline*}
\frac{1-\g}{\sqrt{N}} \tZ_N(t) \left[ f \left( \frac{1}{\sqrt{N}}\tY_N\left(t\right) +  \frac{1}{\sqrt{N}}\frac{2\b}{1+\b}\tZ_N\left(t\right) \right) -  f \left( \frac{1}{\sqrt{N}}\tY_N\left(t\right) -  \frac{1}{\sqrt{N}}\frac{2}{1+\b}\tZ_N\left(t\right) \right) \right]  \\
 \leq \frac{1-\g}{\sqrt{N}} |\tZ_N(t)| \left| f \left( \frac{1}{\sqrt{N}}\tY_N\left(t\right) +  \frac{1}{\sqrt{N}}\frac{2\b}{1+\b}\tZ_N\left(t\right) \right) -  f \left( \frac{1}{\sqrt{N}}\tY_N\left(t\right) -  \frac{1}{\sqrt{N}}\frac{2}{1+\b}\tZ_N\left(t\right) \right) \right| \\
 \leq \frac{2 f'(0)(1-\g)}{N} \tZ^2_N(t).
\end{multline*}
Summing all up we obtain
\be{tZ2derest}
\begin{split}
\frac{d}{dt} \E\left[\tZ_N^2(t)\right] & \leq  [2F_N + (1-\g)^2 f'(0)]\E\left[|\tZ_N(t)|\right] \\ & ~~~ - 2[\a-(1-\g) f'(0)] \sqrt{N} \E\left[\tZ_N^2(t)\right] + \frac{(1-\g)^2}{2} f'(0) \tY_N(t).
\end{split}
\ee
Using the fact that the sequence $F_N$ is bounded (see \eqref{assab}), that $\tY_N(t) \leq h$  and using the Cauchy-Schwartz inequality, we have that $x_N(t) := \E\left[\tZ_N^2(t)\right] $ 
satisfies the differential inequality for suitable constants $A,B>0$:
\be{tZ2derest2}
\frac{d}{dt}x_N(t)  \leq A + B \sqrt{x_N(t)} - 2[\a-(1-\g) f'(0)] \sqrt{N} x_N(t)
\ee
Considering also that $x_N(0) = E_N^2$ which is bounded by a constant $C$ (see \eqref{assab}), we have, by the comparison theorem for differential equations, that $x_N(t) \leq y_N(t)$, where 
\[
\begin{split}
\frac{d}{dt}y_N(t) & = A + B \sqrt{y_N(t)} - 2[\a-(1-\g) f'(0)] \sqrt{N} y_N(t) \\
y_N(0) & = C.
\end{split}
\]
It follows from Lemma \ref{lemma:collapsing} that for every $t>0$
\be{collZ}
\sup_N N^{\frac12} \E\left[\tZ_N^2(t)\right] < +\infty.
\ee
From the pointwise estimate \eqref{collZ} we can derive a uniform estimate by using Theorem \ref{collapsing}. First we identify the index $n$ appearing in Theorem \ref{collapsing} with $N^{\frac{3}{16}}$, so all processes are indexed by $N$ rather than $n$. Set $X_N(t) = \tZ_N^2(t)$. Then \eqref{tZ2} can be rewritten in the form
\[dX_N(t) = S_N(t)dt + \int_{[0,t]\times \mathcal{Y}} f_N(s^-, y) [\Lambda_N(ds,dy) - A_N(s,dy)ds]\]
with 
\[
\mathcal{Y} = [0,+\infty) \times \{+,-\}, \ \ \Lambda_N(ds,du, \pm) = 
\sum_{i=1}^N n^{\pm}_i(\sqrt{N}ds,du), \ \ A_N(s,du,\pm) = N^{\frac32} du
\]
\begin{equation} \label{effeN}
f_N(s,u,\pm) =  {\bf 1}_{[0, \tilde{\lambda}^{\pm}(\sqrt{N} s))}(u) \left[ \left(\tZ_N(s) \pm \frac{1-\g}{2\sqrt{N}} \right)^2 - \tZ_N^2(s) \right],
\end{equation}
\begin{equation} \label{esseN}
S_N(t) = 2 F_N \tZ_N(t) - 2 \a \sqrt{N} \tZ_N^2(t).
\end{equation}
We now verify that conditions in Theorem \ref{collapsing} hold, with the only difference that the initial time is $\e>0$ rather than zero. We set $d=2$, $\a_N = N^{\frac18}$, $\beta_N = 1$. With these choices requirements \eqref{condc1} are satisfied. Now, using \eqref{collZ} and the fact that $\tZ_N$ is bounded (by \eqref{boundZ} and the boundedness of $\tY_N$), we have
\[
\mathbb{E}\left[X_N^d(\e)\right] = \mathbb{E}\left[\tZ_N^4(\e)\right] \leq A \mathbb{E}\left[\tZ_N^2(\e)\right]  \leq B N^{-\frac12} \leq C_1 N^{-\frac14} = C_1 \a_N^{-d}
\]
for some constants $A,B$ and $C_1$, so condition \eqref{condc2} is checked. Condition \eqref{condc3} follows from \eqref{esseN}, the fact that $\tZ_N$ is bounded and that $\sqrt{N} \geq n = N^{\frac{3}{16}}$. Note that no stopping time is needed here. We now consider conditions \eqref{condc4} and \eqref{condc5}. Note that, by \eqref{effeN}, 
\[
|f_N(s,u,\pm)| \leq \frac{C}{\sqrt{N}} \leq C_4 \a_N^{-1}
\]
for some constants $C$ and $C_4$; moreover
\[
\begin{split}
\int_{\mathcal{Y}} (f_N(t,y))^2 A_N(t,dy)  = &  N^{\frac32}\tilde{\lambda}^+ (\sqrt{N} t) \left[ \left(\tZ_N(s) + \frac{1-\g}{2\sqrt{N}} \right)^2 - \tZ_N^2(s) \right]^2 \\
& + N^{\frac32}\tilde{\lambda}^- (\sqrt{N} t) \left[ \left(\tZ_N(s) - \frac{1-\g}{2\sqrt{N}} \right)^2 - \tZ_N^2(s) \right]^2  \leq C_5
\end{split}
\]
for some constant $C_5$, as, for some $C>0$, 
\[
\tilde{\lambda}^{\pm} (\sqrt{N} t) \leq \frac{C}{\sqrt{N}}
\]
by definition of $\tilde{\lambda}^{\pm}$ and boundedness of $\tZ_N$ and $\tY_N$, and
\[
\left[ \left(\tZ_N(s) \pm \frac{1-\g}{2\sqrt{N}} \right)^2 - \tZ_N^2(s) \right]^2 \leq \frac{C}{N}.
\]
Thus all conditions in Theorem \ref{collapsing} are verified, and we obtain that, for all $\e>0$,
\be{collZpr}
\sup_{t \in [\e,T]}  \tZ_N^2(t) \ \longrightarrow \ 0 \ \ \mbox{in probability and in $L^1$.}
\ee

