Y_N(t) & = C_N + D_N t + \sqrt{N} \int_0^t [-\a + f'(0)(1+\b \g)] Y_N(s) ds  \\
& ~~~ + \frac12(1+\b\g) f''(0) \int_0^t Y_N^2(s) ds + A(\b,\g) f''(0) \int_0^t Y_N(s)Z_N(s) ds + B(\b,\g) f''(0) \int_0^t Z_N^2(s) ds  \\
& ~~~ + \frac{1}{\sqrt{N}} C(\b,\g) \int_0^t R\left(\frac{1}{\sqrt{N}}Y_N\left(s\right) +  \frac{1}{\sqrt{N}}\frac{2\b}{1+\b}Z_N\left(s\right)  \right) \left(\frac{1}{\sqrt{N}}Y_N\left(s\right) +  \frac{1}{\sqrt{N}}\frac{2\b}{1+\b}Z_N\left(s\right)  \right)^3 ds \\ & ~~~ + \frac{1}{\sqrt{N}}D(\b,\g)  \int_0^t R\left( \frac{1}{\sqrt{N}}Y_N(s) -  \frac{1}{\sqrt{N}} \frac{2}{1+\b}Z_N(s) \right) \left( \frac{1}{\sqrt{N}}Y_N(s) -  \frac{1}{\sqrt{N}} \frac{2}{1+\b}Z_N(s) \right)^3 ds \\ & ~~~ +  M_N^Y(t)
\end{split}
\ee
where $A(\b,\g)$, $B(\b,\g)$, $C(\b,\g$ and $D(\b,\g)$ are constants depending on $\b,\g$, whose precise value will not be relevant.
It should be remarked that in this expansion the term of order $\sqrt{N} \int_0^T Z_N(s) ds$ has zero coefficient: this is the main motivation for the specific choice of the combinators in the definition of $Y_N$ and $Z_N$.

We are now ready to prove the first part of our asymptotic result.

\begin{theorem} \label{th:volatility}
Suppose the criticality condition 
\be{critical}
\a = f'(0)(1+\b\g)
\ee
holds. Then the sequence $(Y_N(t))_{t \in [0,T]}$ converges in distribution to the unique solution of the SDE
\be{limvol}
\begin{split}
dy(t)  & = \left[\left(\frac{2}{1+\b}+\frac{2\b}{1+\b}\g\right) b^+ + \left(\frac{2\b}{1+\b}(1-\g) + 2\b\g\right) b^- + \frac12 (1+\b\g) f''(0) y^2(t) \right] dt  \\ & ~~~~~ + \frac{\sqrt{f'(0) (1+\b^2)}(1+\b\g)}{1+\b} \sqrt{y(t)} dB(t) \\
y(0) & = \left(\frac{2}{1+\b}+\frac{2\b}{1+\b}\g\right) a^+ + \left(\frac{2\b}{1+\b}(1-\g) + 2\b\g\right) a^-,
\end{split}
\ee
where $B$ is a simple Brownian motion.
\end{theorem}
\begin{proof}
We use next Theorem \ref{thm:diffusion:approx}, for the one-dimensional process $Y_N(t)$. We choose 
\be{B}
\begin{split}
B^N(t) &  := D_N t \\ & ~~~ + \frac12(1+\b\g) f''(0) \int_0^t Y_N^2(s) ds + A(\b,\g) f''(0) \int_0^t Y_N(s)Z_N(s) ds + B(\b,\g) f''(0) \int_0^t Z_N^2(s) ds  \\
& ~~~ + \frac{1}{\sqrt{N}} C(\b,\g) \int_0^t R\left(\frac{1}{\sqrt{N}}Y_N\left(s\right) +  \frac{1}{\sqrt{N}}\frac{2\b}{1+\b}Z_N\left(s\right)  \right) \left(\frac{1}{\sqrt{N}}Y_N\left(s\right) +  \frac{1}{\sqrt{N}}\frac{2\b}{1+\b}Z_N\left(s\right)  \right)^3 ds \\ & ~~~ + \frac{1}{\sqrt{N}}D(\b,\g)  \int_0^t R\left( \frac{1}{\sqrt{N}}Y_N(s) -  \frac{1}{\sqrt{N}} \frac{2}{1+\b}Z_N(s) \right) \left( \frac{1}{\sqrt{N}}Y_N(s) -  \frac{1}{\sqrt{N}} \frac{2}{1+\b}Z_N(s) \right)^3 ds,
\end{split}
\ee
\be{b}
b(x) := \left[\left(\frac{2}{1+\b}+\frac{2\b}{1+\b}\g\right) b^+ + \left(\frac{2\b}{1+\b}(1-\g) + 2\b\g\right) b^- + \frac12 (1+\b\g) f''(0) x^2 \right],
\ee
\be{A}
\begin{split}
A^N(t) & := \frac{ \sqrt{N} }{4}\left[ \left(\frac{2}{1+\b}+\frac{2\b}{1+\b}\g\right)^2\int_0^t  f\left(\frac{1}{\sqrt{N}}Y_N\left(s\right) +  \frac{1}{\sqrt{N}}\frac{2\b}{1+\b}Z_N\left(s\right) \right) ds \right. \\ & ~~~~~~~ 
\left.+ \left(\frac{2\b}{1+\b}(1-\g) + 2\b\g\right) ^2\int_0^t  f\left( \frac{1}{\sqrt{N}}Y_N(s) -  \frac{1}{\sqrt{N}} \frac{2}{1+\b}Z_N(s)  \right) ds \right],
\end{split}
\ee
\be{a}
a(x) =  \frac{\a (1+\b^2)(1+\b\g)}{(1+\b)^2}|x|.
\ee
By \eqref{quadvarMY} and \eqref{Y2} it follows that $Y_N - A^N$ is a martingale with quadratic variation $A^N$. Conditions \eqref{eq:hyp4.4}, \eqref{eq:hyp4.5} and \eqref{eq:hyp4.3} are trivial, since $A^N$ and $B^N$ are continuous in $t$ and the jumps of $Y_N$ have order $\frac{1}{\sqrt{N}}$. By Theorem \ref{thm:eq.quad} the SDE \eqref{limvol} has a unique solution, and 
\[
\lim_{N \ra +\infty} Y_N(0) = \lim_{N \ra +\infty}  C_N  = y(0).
\]
Thus, to complete the proof, we need to establish \eqref{eq:hyp4.7} and \eqref{eq:hyp4.6}. We begin by \eqref{eq:hyp4.6}. Note that 
\begin{multline} \label{estB}
B^N(t) - \int_0^t b(Y_N(s)) ds   = \left[ D_N - \left(\frac{2}{1+\b}+\frac{2\b}{1+\b}\g\right) b^+ - \left(\frac{2\b}{1+\b}(1-\g) + 2\b\g\right) b^- \right]t \\ +
A(\b,\g) f''(0) \int_0^t Y_N(s)Z_N(s) ds + B(\b,\g) f''(0) \int_0^t Z_N^2(s) ds \\
 + \frac{1}{\sqrt{N}} C(\b,\g) \int_0^t R\left(\frac{1}{\sqrt{N}}Y_N\left(s\right) +  \frac{1}{\sqrt{N}}\frac{2\b}{1+\b}Z_N\left(s\right)  \right) \left(\frac{1}{\sqrt{N}}Y_N\left(s\right) +  \frac{1}{\sqrt{N}}\frac{2\b}{1+\b}Z_N\left(s\right)  \right)^3 ds \\ + \frac{1}{\sqrt{N}}D(\b,\g)  \int_0^t R\left( \frac{1}{\sqrt{N}}Y_N(s) -  \frac{1}{\sqrt{N}} \frac{2}{1+\b}Z_N(s) \right) \left( \frac{1}{\sqrt{N}}Y_N(s) -  \frac{1}{\sqrt{N}} \frac{2}{1+\b}Z_N(s) \right)^3 ds
\end{multline}
To prove \eqref{eq:hyp4.6} we show that all terms in the r.h.s of \eqref{estB} converge to zero in probability after replacing $t$ by $t \wedge  \tau^N_h$, with  $\tau^N_h := \inf\{t>0 : Y_N(t) > h\}$. The first term in easy, since 
\[
\lim_{N \ra +\infty} D_N  = \left(\frac{2}{1+\b}+\frac{2\b}{1+\b}\g\right) b^+ + \left(\frac{2\b}{1+\b}(1-\g) + 2\b\g\right) b^-
\]
by \eqref{assab}.
The estimate of the next two terms in \eqref{estB} is based on the facts that, for $t \leq \tau^N_h$, we have that $\tZ_N(t) = Z_N(t)$, $Y_N(t) \leq h$ and, by \eqref{boundZ}
  \[
|Z_N(t)| \leq \frac{1+\b}{2} Y_N(t) \leq  \frac{1+\b}{2}h.
\]
Thus 
\[
\left|A(\b,\g) f''(0) \int_0^{t\wedge \tau^N_h} Y_N(s)Z_N(s) ds + B(\b,\g) f''(0) \int_0^{t\wedge \tau^N_h} Z_N^2(s) ds \right| \leq \mbox{constant} \cdot \int_0^t \tZ_N^2(s)\wedge \frac{(1+\b)^2}{4}h^2 ds
\]
which, by \eqref{collZ} and dominated convergence, converges to zero in $L^1$ and so in probability. For the remaining two terms in \eqref{estB} we use again
  \[
|Z_N(t)| \leq \frac{1+\b}{2} Y_N(t),
\]
which implies that
\[
\int_0^{t \wedge \tau^N_h} R\left(\frac{1}{\sqrt{N}}Y_N\left(s\right) +  \frac{1}{\sqrt{N}}\frac{2\b}{1+\b}Z_N\left(s\right)  \right) \left(\frac{1}{\sqrt{N}}Y_N\left(s\right) +  \frac{1}{\sqrt{N}}\frac{2\b}{1+\b}Z_N\left(s\right)  \right)^3 ds
\]
is bounded by a constant. This completes the proof on \eqref{eq:hyp4.6}. The proof of \eqref{eq:hyp4.7} is similar but easier, as it requires only a first order expansion for $f$
\end{proof}

\subsection{Convergence of the joint price-volatility process}
Let us recall the rescaled log-price in \eqref{def:pn}
\[
\begin{split}
\Pi_N(t)  = \frac{1}{\sqrt{N}} \sum_{i=1}^N P_i(\sqrt{N}t) & = \frac{1}{\sqrt{N}} \sum_{i=1}^N \left[ \int_{[0,\sqrt{N}t]\times [0,+\infty)} {\bf 1}_{[0,\l_N^{+}(s^-))}(u) n_i^{+}(ds,du) \right. \\ & ~~~ \left. -  \int_{[0,\sqrt{N}t]\times [0,+\infty)} {\bf 1}_{[0,\l_N^{-}(s^-))}(u) n_i^{-}(ds,du) \right].
\end{split}
\]
Compensating as above the Poisson Processes we obtain
\be{price}
\begin{split}
\Pi_N(t)  & = N \left[ \int_0^{ t} f\left(\frac{1}{\sqrt{N}}Y_N\left(s\right) +  \frac{1}{\sqrt{N}}\frac{2\b}{1+\b}Z_N\left(s\right)  \right) ds \right. \\
& ~~~ - \left.   \int_0^{ t} f\left( \frac{1}{\sqrt{N}}Y_N(s) -  \frac{1}{\sqrt{N}} \frac{2}{1+\b}Z_N(s)  \right) ds \right] + M_N^{\Pi}(t),
\end{split}
\ee
where $M_N^{\Pi}$ is a martingale with zero mean and quadratic variation 
\be{pricequadvar}
\sqrt{N} \left[ \int_0^{ t} f\left(\frac{1}{\sqrt{N}}Y_N\left(s\right) +  \frac{1}{\sqrt{N}}\frac{2\b}{1+\b}Z_N\left(s\right)  \right) ds + \int_0^{ t} f\left( \frac{1}{\sqrt{N}}Y_N(s) -  \frac{1}{\sqrt{N}} \frac{2}{1+\b}Z_N(s)  \right) ds \right] .
\ee
We can also easily identify the covariation between the martingales $M_N^{\Pi}$ and $M_N^{Y}$, which is given by
\begin{multline} \label{quadcovar}
\sqrt{N} \left[ \left(\frac{1}{1+\b}+\frac{\b}{1+\b}\g\right)\int_0^t  f\left(\frac{1}{\sqrt{N}}Y_N\left(s\right) +  \frac{1}{\sqrt{N}}\frac{2\b}{1+\b}Z_N\left(s\right) \right) ds \right. \\  
\left.- \left(\frac{\b}{1+\b}(1-\g) + \b\g\right) \int_0^t  f\left( \frac{1}{\sqrt{N}}Y_N(s) -  \frac{1}{\sqrt{N}} \frac{2}{1+\b}Z_N(s)  \right) ds \right].
\end{multline}
We can now rewrite \eqref{price} by using the Taylor expansion \eqref{taylor}, and we obtain
\be{priceexp}
\begin{split}
\Pi_N(t)  & = 2f'(0)\sqrt{N}\int_0^t Z_N(s) ds  \\ & ~~~ + \frac{1}{2} f''(0) \int_0^t \left[ \left( Y_N(s) + \frac{2\b}{1+\b} Z_N(s)\right)^2 - \left( Y_N(s) - \frac{2}{1+\b} Z_N(s)\right)^2 \right]ds
\\ & ~~~ + \frac{1}{\sqrt{N}} \int_0^t R\left( Y_N(s) + \frac{2\b}{1+\b} Z_N(s)\right)\left( Y_N(s) + \frac{2\b}{1+\b} Z_N(s)\right)^3 ds \\ &  ~~~ + \frac{1}{\sqrt{N}} \int_0^t R\left( Y_N(s) - \frac{2}{1+\b} Z_N(s)\right)\left( Y_N(s) - \frac{2}{1+\b} Z_N(s)\right)^3 ds
 + M_N^{\Pi}(t) \\ &  = 2f'(0)\sqrt{N}\int_0^t Z_N(s) ds  \\ & ~~~ +  f''(0) \int_0^t \left[  2Y_N(s) Z_N(s) + 2\frac{\b-1}{\b+1} Z_N^2(s) \right]ds
\\ & ~~~ + \frac{1}{\sqrt{N}} \int_0^t R\left( Y_N(s) + \frac{2\b}{1+\b} Z_N(s)\right)\left( Y_N(s) + \frac{2\b}{1+\b} Z_N(s)\right)^3 ds \\ &  ~~~ + \frac{1}{\sqrt{N}} \int_0^t R\left( Y_N(s) - \frac{2}{1+\b} Z_N(s)\right)\left( Y_N(s) - \frac{2}{1+\b} Z_N(s)\right)^3 ds
 + M_N^{\Pi}(t).
\end{split}
\ee
The problem here is in the term $2f'(0)\sqrt{N}\int_0^t Z_N(s) ds$. We have shown that
\[
\lim_{N \ra +\infty} \E \left[ \int_0^{T \wedge \tau^N_h} Z_N^2(s) ds \right] = 0,
\]
but this does not allow to control $\sqrt{N}\int_0^t Z_N(s) ds$.  To overcome this difficulty, we go back to \eqref{eqZ_N}, which gives
\[
\begin{split}
Z_N(t) & = E_N + F_N t - \a \sqrt{N} \int_0^{t} Z_N(s) ds \\ & ~~~~~~+ \frac{1-\g}{2 \sqrt{N}} \int_0^t \left[ f\left(\frac{1}{\sqrt{N}}Y_N\left(s/\sqrt{N}\right) +  \frac{1}{\sqrt{N}}\frac{2\b}{1+\b}Z_N\left(s/\sqrt{N}\right) \right) \right. \\ & ~~~~~~~~~~~~~~~~~~~~~~ \left.- f\left( \frac{1}{\sqrt{N}}Y_N(s/\sqrt{N}) -  \frac{1}{\sqrt{N}} \frac{2}{1+\b}Z_N(s/\sqrt{N}) \right) \right]ds + M_N^Z(t),
\end{split}
\]
where $M_N^Z(t) = \frac{1-\g}{2} M_N^{\Pi}(t)$. Expanding $f$ as above we obtain
\be{altZN}
\begin{split}
Z_N(t) & = E_N + F_N t - (\a- (1-\g) f'(0)) \sqrt{N} \int_0^{t} Z_N(s) ds \\ & ~~~~~~+ (1-\g) f''(0) \int_0^t \left[Y_N(s) Z_N(s) + \frac{\b-1}{1+\b} Z_N^2(s) \right] ds + Q_N(t) + \frac{1-\g}{2} M_N^{\Pi}(t),
\end{split}
\ee
where $Q_N(t)$ comes from the cubic part of the expansion, and $Q_N(t \wedge \tau_h^N)$ converges uniformly to zero as $N \ra +\infty$. We can now use \eqref{altZN} to eliminate the divergent term from \eqref{priceexp}.
\be{priceeq}
\begin{split}
\Pi_N(t) & = -\frac{2 f'(0)}{\a-(1-\g)f'(0)} Z_N(t) + \frac{2 f'(0)}{\a-(1-\g)f'(0)} E_N + \frac{2 f'(0)}{\a-(1-\g)f'(0)} F_N t \\ & + 2f''(0)\left( 2+ \frac{2 f'(0)(1-\g)}{\a-(1-\g)f'(0)} \right) \int_0^t \left[ Y_N(s)Z_N(s) + \frac{\b-1}{1+\b} Z_N^2(s)\right]ds \\ & + \left(1+\frac{f'(0)(1-\g)}{\a-(1-\g)f'(0)}\right) M_N^{\Pi}(t) + Q_N(t),
\end{split}
\ee
where $Q_N(t)$ is the same as the one in \eqref{altZN} up to a multiplicative constant.

We can now describe the asymptotic behavior of the log-price process. In what follows by convergence in distribution in $(0,T]$ we mean that the convergence occurs in $[\e,T]$ for all $\e>0$.

\begin{theorem} \label{th:price}
Suppose the criticality condition 
\be{critical}
\a = f'(0)(1+\b\g)
\ee
holds.
The pair $(\Pi_N, Y_N)$ converges in  distribution in $(0,T]$ to the process $(\pi,y)$ where $y(t)$ solves equation \eqref{limvol}, and
\be{limprice}
\begin{split}
d\pi(t) & = \frac{1-\g}{\g(1+\b)}(b^+ - b^-) dt + \frac{1+\b\g}{\g(1+\b)}\sqrt{2 f'(0) y(t)} dW(t) \\
\pi(0) & = \frac{1-\g}{\g(1+\b)}(a^+ - a^-),
\end{split}
\ee
where $W$ is a Brownian motion, and 
\be{limcorr}
d \langle B,W \rangle_t = - \frac{\g(\b^2-1)}{(1+\b\g)\sqrt{2(1+\b^2)}} dt.
\ee
\end{theorem}

\begin{proof}
We use Theorem \ref{thm:diffusion:approx} for the two dimensional process $(\Pi_N, Y_N)$. The convergence of $Y_N$ has been already established. So, we need to show the convergence of: the drift part of $\Pi_N$,  the quadratic variation of the martingale part of $\Pi_N$, and the quadratic covariation of the two martingale components. 

The drift part of $\Pi_N$ contains the term
\[
\frac{2 f'(0)}{\a-(1-\g)f'(0)} F_N t
\]
which asymptotically produces the constant drift 
\[
\frac{f'(0)(1-\g)}{\a-(1-\g)f'(0)}(b^+ - b^-).
\]
To complete the treatment of the drift we need to show that, for every $\e,\d>0$,
\[
\lim_{N \ra +\infty} \P \left(\sup_{\e \leq t \leq T \wedge \tau_h^N} \left|\int_0^t \left[ Y_N(s)Z_N(s) + \frac{\b-1}{1+\b} Z_N^2(s)\right]ds \right| \geq \delta \right) = 0,
\]
which readily follows from \eqref{collZpr} and the fact that $Y_N$ is bounded up to time $\tau_h^N$.

The martingale component of $\Pi_N$ is given by, using $\a = f'(0)(1+\b\g)$,
\[
\left(1+\frac{f'(0)(1-\g)}{\a-(1-\g)f'(0)}\right) M_N^{\Pi}(t) = \frac{1+\b\g}{\g(1+\b)}M_N^{\Pi}(t).
\]
Thus, using \eqref{pricequadvar}, we need to show that
\be{estmartprice}
\lim_{N \ra +\infty} \P \left(\sup_{\e \leq t \leq T \wedge \tau_h^N} \left|\int_0^t A_N(s) ds - \int_0^t 2 f'(0) Y_N(s) ds \right| \geq \delta \right) = 0,
\ee
where
\[
A_N(s) := \sqrt{N} \left[f\left( \frac{1}{\sqrt{N}}Y_N(s) -  \frac{1}{\sqrt{N}} \frac{2}{1+\b}Z_N(s)  \right) + f\left( \frac{1}{\sqrt{N}}Y_N(s) -  \frac{1}{\sqrt{N}} \frac{2}{1+\b}Z_N(s)\right)\right],
\]
which is established by a simple first order Taylor expansion of $f$.

Finally we need to verify the convergence of the covariation. Using \eqref{quadcovar}, it follows that the covariation $\langle  M^{\Pi}_N, M_{Y}^N \rangle(t)$ converges, in the sense of \eqref{eq:hyp4.7}, to
\[
f'(0) \frac{(1-\b)(1+\b \g)}{1+\b} \int_0^t y(s) ds.
\]
Thus, comparing \eqref{limvol}, and \eqref{limprice}, we need
\[
\frac{\sqrt{f'(0) y(t) (1+\b^2)}(1+\b\g)}{1+\b} \frac{1+\b\g}{\g(1+\b)}\sqrt{2 f'(0) y(t)} d\langle B,W\rangle (t) = f'(0) \frac{(1-\b)(1+\b \g)}{1+\b} y(t) dt,
\]

which implies \eqref{limcorr}.
\end{proof}




