\section{Useful results}

These theorems correspond to Theorem VII, 4.1 \cite{EtKu2005} and the Proposition in Appendix A in \cite{CE88}.


\begin{theorem}[\textbf{Diffusion approximation }]\label{thm:diffusion:approx}
Let $\left(X^N\right)_{N\in \mathbb{N}}$ and  $\left(B^N\right)_{N\in \mathbb{N}}$ $\R^d$-valued processes with càdlàg sample paths and let $A^N = \left(A^N_{i j}\right)$ be a symmetric $d\times d$ matrix-valued process such that $A^N_{i j}$ has càdlàg sample paths in $\R$ and $A^N(t)-A^N(s)$ is non-negative definite for all $t> s \geq 0$. 
Let $\mathcal{F}^N_t \coloneqq \sigma\left(X^N(s), B^N(s), A^N(s)\, : \, s\leq t \right)$. 
Let $\tau^N_h \coloneqq \inf\left\{t > 0\, : \, \vert X^N(t)\vert\geq h \, \text{or}\, \vert X^N(t^-)\vert \geq h \right\}$, where $X^N(t^-) \coloneqq \lim_{s\to t^-} X^N(s)$ denotes the left-hand limit. 
% serve includere X in t^- perché il processo è continuo a dx, non continuo, quindi potrebbe essere che X(t)>r, ma che il processo fosse già esploso prima $X^N(t^-) \coloneqq \lim_{s\to t^-} X^N(s)$, Potrebbe essere che questo limite esca oltre r ma che invece poi X^N(t) riprenda da dentro [-r,r]
Assume that
\begin{itemize}
    \item $M^N \coloneqq X^N - B^N$ and $M^N_i M^N_j - A^N_{i j }$ $i,j=1,\dots,d$ are $\left(\mathcal{F}^N_t\right)$-local martingales
    \item for each $T>0$, $h>0$
    \begin{equation}\label{eq:hyp4.4}
        \lim_{N \to +\infty}\E\left[ \sup_{t \leq T \wedge \tau^N_h} \vert B^N(t) - B^N(t^-)\vert^2\right] = 0
    \end{equation}
    \item for each $T>0$, $h>0$, $i,j=1,\dots,d$
    \begin{equation}\label{eq:hyp4.5}
        \lim_{N \to +\infty}\E\left[ \sup_{t \leq T \wedge \tau^N_h} \vert A^N_{i j}(t) - A^N_{i j}(t^-)\vert\right] = 0 
    \end{equation}
    \item for each $T>0$, $h>0$ 
    \begin{equation}\label{eq:hyp4.3}
        \lim_{N \to +\infty}\E\left[ \sup_{t \leq T \wedge \tau^N_h} \vert X^N(t) - X^N(t^-)\vert^2\right] = 0 
    \end{equation}
    \item there exist a continuous, symmetric, non-negative definite $d\times d$ matrix-valued function on $\R^d$, $a=\left(a_{i j}\right)$, and a continuous function $b: \R^d \to \R^d$ such that, for each $h>0$, $T>0$ and $i,j=1,\dots,d$, and for all $\epsilon>0$, 
    \begin{equation}\label{eq:hyp4.7}
        \lim_{N\to +\infty}\mathbb{P}\left(\sup_{t\leq T\wedge \tau^N_h} \Bigg\vert A^N_{ i j}(t) - \int_0^t a_{i j }(X^N(s))ds \Bigg\vert > \epsilon \right) = 0 
    \end{equation}
    and 
    \begin{equation}\label{eq:hyp4.6}
        \lim_{N\to +\infty}\mathbb{P}\left(\sup_{t\leq T \wedge \tau^N_h} \Bigg\vert B^N_i(t) - \int_0^t b_i(X^N(s))ds \Bigg\vert > \epsilon \right) = 0 
    \end{equation}
    \item the $\mathcal{C}_{\R^d}\left([0,+\infty)\right)$ martingale problem for
	\begin{equation}\label{A:EtKu}
	\tilde{A} \coloneqq \left\{\left(f,Gf\coloneqq \frac{1}{2}\sum_{i,j} a_{i j}\partial_i \partial_j f + \sum_i b_i \partial_i f\right)\, : \, f \in \mathcal{C}^{\infty}_c\left(\R^d\right) \right\} 
	\end{equation}
is well-posed. 

    \item the sequence of the initial laws of the $X^N$s converges in distribution to some probability distribution on $\R^d$, $\nu$. 
\end{itemize}
Then $\left(X^N\right)_N$ converges in distribution to the solution of the martingale problem for $(\tilde{A},\nu)$. 
That is, the laws of the processes $\left(X^N\right)_N$ converge weakly to the law of a process $X$ which is a weak solution of the SDE 
\begin{equation}
    \begin{split}
        dX(t) = b(X(t))dt +\Sigma(X(t)) dW(t)
    \end{split}
\end{equation}
where $b = (b_i)_i$ and $\left(\Sigma \Sigma^T\right)_{i j }= a_{i j} $ are the drift vector and the diffusion coefficient in \eqref{A:EtKu}.
\end{theorem}




