\begin{theorem} \label{collapsing}
Let $\{X_n(t)\}_{n \geq 1}$ be a sequence of positive semimartingales on a probability space $(\Omega, \mathcal{A}, \mathcal{P})$, with
\[dX_n(t) = S_n(t)dt + \int_{[0,t]\times \mathcal{Y}} f_n(s^-, y) [\Lambda_n(ds,dy) - A_n(s,dy)ds]\]
Here, $\Lambda_n$ is a Point Process of intensity $A_n(t,dy)dt$ on $\mathbb{R}^+\times \mathcal{Y}$, where $\mathcal{Y}$ is a measurable space, and $S_n(t)$ and $f_n(t)$ are $\mathcal{A}_t$-adapted processes, if we consider $(\mathcal{A}_t)_{t\geq 0}$ a filtration on $(\Omega, \mathcal{A}, \mathcal{P})$ generated by $\Lambda_n$.\\ 
Let $d>1$ and $C_i$ constants independent of $n$ and $t$. Suppose there exist $\{\alpha_n\}_{n \geq1}$ and $\{\beta_n\}_{n \geq 1}$, increasing sequences with
\begin{equation} \label{condc1} n^{1/d}\alpha_n^{-1} \xrightarrow{n\rightarrow +\infty} 0, n^{-1} \alpha_n  \xrightarrow{n\rightarrow +\infty} 0, n^{-1}\beta_n  \xrightarrow{n\rightarrow +\infty} 0  \end{equation}
and
\begin{equation} \label{condc2} E \Big[ \Big( X_n(0) \Big)^d \Big] \leq C_1 \alpha_n^{-d} \qquad \mbox{for all $n$} \end{equation}
Furthermore, let $\{\tau_n\}_{n \geq 1}$ be stopping times such that for $t \in [0, \tau_n]$ and $n \geq 1$,
\begin{equation} \label{condc3} S_n(t) \leq -n \delta X_n(t) + \beta_n C_2 + C_3 \qquad \mbox{with $\delta>0$} \end{equation}
\begin{equation} \label{condc4} \sup_{\omega\in\Omega, y\in\mathcal{Y}, t\leq\tau_n}\vert f_n(t,y) \vert \leq C_4 \alpha_{n}^{-1},\end{equation}
and also assume
\begin{equation}\label{condc5}
\int_{\mathcal{Y}} (f_n(t,y))^2 A_n(t,dy) \leq C_5\,.
\end{equation}
Then, for any $\varepsilon >0$, there exist $C_6>0$ and $n_0$ such that
\begin{equation}\label{tesithmCOEI}
\sup_{n \geq n_0} \mathcal{P} \left\{ \sup_{0 \leq t \leq T \wedge \tau_n} X_n (t) > C_6 (n^{1/d} \alpha_n^{-1} \vee \alpha_n n^{-1})\right\} \leq \varepsilon 
\end{equation}

\end{theorem}

