\section{Relative Deformation Gradient Identities} \label{section:RelIdentities}
The relative deformation gradient can be expressed in terms of the standard deformation gradients at time $s$ and $t$ through $\boldsymbol{F}(t,s)=\boldsymbol{F}(t)\boldsymbol{F}^{-1}(s)$. For indicial notation, components associated with the configuration at times $0$, $t$ and $s$ are denoted by uppercase, lowercase, and calligraphic letters, respectively. For decomposing the transient network stresses and tangents, the following identities may be useful:\\
\newline
Right Green Cauchy Tensor:
\begin{equation}
	C_{\mathcal{I}\mathcal{J}}(t,s)=F_{kM}(t)F_{M\mathcal{I}}^{-1}(s)F_{kN}(t)F_{N\mathcal{J}}^{-1}(s)=C_{MN}(t)F^{-1}_{M\mathcal{I}}(s)F^{-1}_{N\mathcal{J}}(s)
\end{equation}
Left Cauchy-Green Tensor:
\begin{equation}
	b_{ij}(t,s)=F_{iM}(t)F_{M\mathcal{K}}^{-1}(s)F_{jN}(t)F_{N\mathcal{K}}^{-1}(s)=F_{iM}(t)F_{jN}(t)C_{MN}^{-1}(s)
\end{equation}
First Invariant
\begin{equation}
	I_1(t,s)=C_{\mathcal{I}\mathcal{I}}(t,s)=C_{MN}(t)C^{-1}_{MN}(s)
\end{equation}
Second Invariant
\begin{equation}
	\begin{split}
		I_2(t,s)=&\frac{1}{2}\Big(C_{\mathcal{I}\mathcal{J}}(t,s)C_{\mathcal{I}\mathcal{J}}(t,s)-C_{\mathcal{I}\mathcal{J}}(t,s)C_{\mathcal{J}\mathcal{I}}(t,s) \Big) \\ =&\frac{1}{2}C_{LM}(t)C_{NO}(t)\Big(C^{-1}_{LM}(s)C^{-1}_{NO}(s)- C^{-1}_{LO}(s)C^{-1}_{MN}(s)\Big) 	
	\end{split}
\end{equation}
Third Invariant
\begin{equation}
	\begin{split}
		I_3(t,s)=\det(C(t,s))=\frac{J^2(t)}{J^2(s)}
	\end{split}
\end{equation}
Left Cauchy-Green Inverse
\begin{equation}
	\begin{split}
		b^{-1}_{ij}(t,s)=C_{MN}(s)F^{-1}_{Mi}(t)F^{-1}_{Nj}(t)
	\end{split}
\end{equation}



\section{Transient Network Tangents} \label{section:Tangents}
%\subsection{Invariant-Based Models}
The tangents can be treated in an analogous way to the stress. The spatial tangent from all induced networks is given by
\begin{equation}
	\begin{split}
		\boldsymbol{h}^{**}(t) &= \intu_{0}^{t}  \gamma(t,s)\boldsymbol{h}^*(t,s) ds \, ,
	\end{split}
\end{equation}
where the spatial tangent of a particular network permits the decomposition
\begin{equation}
	\begin{split}
		\boldsymbol{h}^{*}(t,s) &= \sum_{i}\boldsymbol{\mathbb{A}}^{i}(s) : \boldsymbol{\mathbb{B}}^{i}(t) \, .
	\end{split}
\end{equation}
Then the spatial tangent may be treated (similar to the stress) as
\begin{equation} \label{TangDef}
	\boldsymbol{h}^{**}(t) = \sum_{i}\boldsymbol{\mathcal{G}}^{i}(t) : \boldsymbol{\mathbb{B}}^{i}(t)
\end{equation}
\begin{equation}
	\boldsymbol{\mathcal{G}}^{i}(t) =\intu_{0}^{t}  \gamma(t,s)\boldsymbol{\mathbb{A}}^{i}(s)ds \, ,
\end{equation}
for which the tangent history variables $\boldsymbol{\mathcal{G}}^{i}(t)$ are integrated in a consistent way with the stress tensor. For the invariant-based material models, the spatial tangent and their corresponding decompositions are given in Tables \ref{CNHTangenttable}\ref{BKTangenttable}, and \ref{YeohTangenttable}.

%\subsection{Stretch-Based Ogden Model}
For the stretch-based model, the spatial tangent of the induced networks can be expressed through the Piola pushforward given by Equation \ref{Piola_push2}, 
where the material tangent of the induced networks is given by
\begin{equation}
	\boldsymbol{H}^{**}(t) = \intu_{0}^{t}  \gamma(t,s)\boldsymbol{H}^*(t,s)  ds ; \quad 	\boldsymbol{H}^*(t,s) = 4J(s)\frac{\partial^2 W(\boldsymbol{U}^2(t),\boldsymbol{U}^2(s))}{\partial \boldsymbol{C}(t)\partial \boldsymbol{C}(t)} \, .
\end{equation}
A decomposition is then sought of the form 
$\boldsymbol{H}^*(t,s)  =\sum_{i}\boldsymbol{\mathbb{A}}^{i}(s) : \boldsymbol{\mathbb{B}^*}^{i}(t)$, so that the spatial tangent is given by Equation \ref{TangDef}, with $\boldsymbol{\mathbb{B}}^{i}(t) =\frac{1}{J(t)}\boldsymbol{F}(t)\boldsymbol{F}(t) \boldsymbol{\mathbb{B}^*}^{i}(t) \boldsymbol{F}^{T}(t)\boldsymbol{F}^{T}(t)$.
For the term associated with the trace of a particular stretch measure, we have 
\begin{equation}
	H^{*}_{IJKL}(t,s)=  \mu  J(s)  U_{MN}^{-2\alpha}(s) L^{\alpha}_{MNIJKL}(t) \, ,
\end{equation}
where
\begin{equation}
  L^{\alpha}_{MNIJKL}:= 4 \frac{\partial^2 E^{\alpha}_{MN}}{\partial C_{IJ}\partial C_{KL}} \, .
\end{equation}
For the case of distinct eigenvalues, $\boldsymbol{L}^{\alpha}$ can be written as \cite{beex2019fusing,liu2024continuum}
\begin{equation} 
	\begin{split}
			\boldsymbol{L}^{\alpha}=&  \sum_{a=1}^{3} f_a \boldsymbol{M}_a \smallotimes \boldsymbol{M}_a \smallotimes \boldsymbol{M}_a +\sum_{a=1}^{3}\sum_{b\ne a}^{3} \xi_{ab}\big(\boldsymbol{G}^{**}_{abb}+\boldsymbol{G}^{**}_{bab}+\boldsymbol{G}^{**}_{bba}  \big) \\
			&+  \sum_{a=1}^{3}\sum_{b\ne a}^{3} \sum_{
			\substack{c\ne a \\ c\ne b }}^{3} \eta \boldsymbol{G}^{**}_{abc}
	\end{split}
\end{equation}
where
\begin{equation}
	\begin{split}
			\boldsymbol{G}^{**}_{abc}&=   \boldsymbol{N}_a  \smallotimes  \boldsymbol{N}_b \smallotimes  \boldsymbol{N}_c \smallotimes  \boldsymbol{N}_a  \smallotimes  \boldsymbol{N}_b \smallotimes  \boldsymbol{N}_c + \boldsymbol{N}_a \smallotimes  \boldsymbol{N}_b \smallotimes  \boldsymbol{N}_c \smallotimes  \boldsymbol{N}_a  \smallotimes  \boldsymbol{N}_c \smallotimes  \boldsymbol{N}_b  \\
			&+    \boldsymbol{N}_a  \smallotimes  \boldsymbol{N}_b \smallotimes  \boldsymbol{N}_a \smallotimes  \boldsymbol{N}_c  \smallotimes  \boldsymbol{N}_b \smallotimes  \boldsymbol{N}_c + \boldsymbol{N}_a \smallotimes  \boldsymbol{N}_b \smallotimes  \boldsymbol{N}_a \smallotimes  \boldsymbol{N}_c  \smallotimes  \boldsymbol{N}_c \smallotimes  \boldsymbol{N}_b  \\
			&+    \boldsymbol{N}_b  \smallotimes  \boldsymbol{N}_a \smallotimes  \boldsymbol{N}_c \smallotimes  \boldsymbol{N}_a  \smallotimes  \boldsymbol{N}_b \smallotimes  \boldsymbol{N}_c + \boldsymbol{N}_b \smallotimes  \boldsymbol{N}_a \smallotimes  \boldsymbol{N}_c \smallotimes  \boldsymbol{N}_a  \smallotimes  \boldsymbol{N}_c \smallotimes  \boldsymbol{N}_b  \\
			&+    \boldsymbol{N}_b  \smallotimes  \boldsymbol{N}_a \smallotimes  \boldsymbol{N}_a \smallotimes  \boldsymbol{N}_c  \smallotimes  \boldsymbol{N}_b \smallotimes  \boldsymbol{N}_c + \boldsymbol{N}_b \smallotimes  \boldsymbol{N}_a \smallotimes  \boldsymbol{N}_a \smallotimes  \boldsymbol{N}_c  \smallotimes  \boldsymbol{N}_c \smallotimes  \boldsymbol{N}_b  \\
	\end{split}
\end{equation}
\begin{equation}
	f_a := 4 \frac{\partial^2 E_a^{\alpha}}{\partial \lambda_a^2 \partial \lambda_a^2}= 2(\alpha-1) \lambda_a^{2(\alpha-2)}
\end{equation}
\begin{equation}
	\xi_{ab}:= \frac{ v_{ab}-\frac{1}{2}d_b}{(\lambda_a^2-\lambda_b^2)} 
\end{equation}
\begin{equation}
	\eta=\sum_{a=1}^{3}\sum_{b\ne a}^{3}\sum_{
		\substack{c\ne a \\ c\ne b }}^{3}  \frac{E_a^{\alpha}(\lambda_a)}{2(\lambda_a^2-\lambda_b^2)(\lambda_a^2-\lambda_c^2)} =\sum_{a=1}^{3}\sum_{b\ne a}^{3}\sum_{
		\substack{c\ne a \\ c\ne b }}^{3}  \frac{\lambda_a^{2\alpha}-1}{4\alpha(\lambda_a^2-\lambda_b^2)(\lambda_a^2-\lambda_c^2)} \, .
\end{equation}
In the case of repeated eigenvalues
%\begin{equation}
%	\lim\limits_{\lambda_b \rightarrow \lambda_a} \xi_{ab}=\frac{1}{8}f_a
%\end{equation}
%\begin{equation}
%	\lim\limits_{
%		\substack{\lambda_b \rightarrow \lambda_a \\ \lambda_c \ne \lambda_a }} \eta=\xi_{ca} \quad \quad \lim\limits_{
%		\substack{\lambda_b \rightarrow \lambda_a \\ \lambda_c \rightarrow \lambda_a }} \eta=\frac{1}{8}f_{a} 
%\end{equation}

\begin{equation}
	\lim\limits_{\lambda_b \rightarrow \lambda_a} \xi_{ab}=\frac{1}{8}f_a \, ; \quad \quad
	\lim\limits_{
		\substack{\lambda_b \rightarrow \lambda_a \\ \lambda_c \ne \lambda_a }} \eta=\xi_{ca} \, ; \quad \quad \lim\limits_{
		\substack{\lambda_b \rightarrow \lambda_a \\ \lambda_c \rightarrow \lambda_a }} \eta=\frac{1}{8}f_{a} \, .
\end{equation}
The decomposition for the tangent associated with the Ogden-Hill model is given in Table \ref{OgdenTangDecomp}. We note that for each material, there are no tangent history variables that have not already been computed as part of the Cauchy stress.

